// ------------------------------------------- written before the run (ADR-0085, ADR-0086)

/// H-16's modulation baseline: H-14's zero, the reward's gate, under which an excitatory
/// synapse consolidates nothing but what a reward reaches.
const GATE_BASELINE_Q16: i32 = 0;
/// H-16's inhibitory baseline (ADR-0085): 0.5, brief 027's `BASELINE_Q16`, the value under
/// which ADR-0077's lead-in settled the network and H-15 read the inhibitory rule's course —
/// the one constant moved from H-14's configuration, and a parameter the image carries
/// (ADR-0086).
const INHIBITORY_BASELINE_Q16: i32 = BASELINE_Q16;
const _: () = assert!(GATE_BASELINE_Q16 == 0 && INHIBITORY_BASELINE_Q16 == ONE / 2);
/// The trials of an arm, H-14's: three of the instrument's runs, twenty-four blocks.
const INHIBITION_TRIALS: usize = REINFORCED_TRIALS;
const _: () = assert!(INHIBITION_TRIALS == 1_536 && INHIBITION_TRIALS / BLOCK == 24);

/// The arms of H-16 (ADR-0085), in the order run and no other, every one `Delivery::Addressed`
/// from the one image with the inhibitory baseline set: the assignment (`Feedback::Answer`,
/// A's answer readout 0 and B's readout 1), the mirrored assignment (`Feedback::Answer`,
/// `mirrored`), and the reward withheld (`Feedback::Withheld`: no reward, the signal at rest,
/// no excitatory synapse consolidating and every inhibitory one under its baseline), a
/// reading bounded by no clause. The shuffled reward is not run.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum Inhibition {
    Assignment,
    Mirrored,
    Withheld,
}
const INHIBITION_ARMS: [Inhibition; 3] = [
    Inhibition::Assignment,
    Inhibition::Mirrored,
    Inhibition::Withheld,
];
/// The rewarded arms in `INHIBITION_ARMS`'s order, the criterion's `[assignment, mirrored]`.
const INHIBITION_REWARDED: [Inhibition; 2] = [Inhibition::Assignment, Inhibition::Mirrored];
/// The withheld arm's index in `INHIBITION_ARMS`.
const WITHHELD: usize = 2;

/// Where an arm's reward takes its sign from: the answer, or nothing.
fn inhibition_feedback(arm: Inhibition) -> Feedback {
    if arm == Inhibition::Withheld {
        Feedback::Withheld
    } else {
        Feedback::Answer
    }
}

/// Whether an arm mirrors the assignment.
fn inhibition_mirrors(arm: Inhibition) -> bool {
    arm == Inhibition::Mirrored
}

/// True for an arm whose reward carries the answer, the criterion's two.
fn inhibition_rewards(arm: Inhibition) -> bool {
    arm != Inhibition::Withheld
}

/// The pairs an arm's delivery can reach with the gate at zero: the two answer pairs where
/// the reward carries the answer (ADR-0080's derivation, which the inhibitory baseline does
/// not touch: a wrong selection's pair spends the next trial under a signal below zero and
/// consolidates nothing), and none with the reward withheld, where no excitatory synapse
/// consolidates at all; the four pairs name where the withheld arm's reach is counted.
fn inhibition_pairs(arm: Inhibition) -> Vec<(usize, usize)> {
    if inhibition_rewards(arm) {
        assigned_pairs(inhibition_mirrors(arm)).to_vec()
    } else {
        ALL_PAIRS.to_vec()
    }
}

/// ADR-0085's prediction, a Hypothesis written before the run: H-16 is yes.
const INHIBITION_PREDICTED: bool = true;

// ---------------------------------------------------- the assertion's shape (ADR-0085)

/// The reach of a run over the arena by polarity: the synapses whose weight differs from the
/// image's, counted inside the pairs named and outside them, for the excitatory synapses and
/// for the inhibitory ones. Every occupied slot is walked once, through its unit's chain; a
/// block's polarity is its presynaptic unit's flag (ADR-0049).
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
struct Reach {
    excitatory: (u64, u64),
    inhibitory: (u64, u64),
}

fn reach_by_polarity(
    exec: &Engine,
    before: &[Vec<i16>],
    units: u32,
    pairs: &[(usize, usize)],
) -> Reach {
    reach_over(&geometry(units, rotation(units)), exec, before, pairs)
}

/// `reach_by_polarity` over the four sets given (brief 067), which `reach_by_polarity` calls with
/// the sets of the rotation written for its units.
fn reach_over(
    sets: &[Set; 4],
    exec: &Engine,
    before: &[Vec<i16>],
    pairs: &[(usize, usize)],
) -> Reach {
    let mut out = Reach::default();
    for unit in exec.units() {
        let id = unit.id as u32;
        let inhibitory = unit.flags & FLAG_INHIBITORY != 0;
        for s in unit.fan_out(exec.blocks()) {
            let was = before
                .get(s.block_idx as usize)
                .and_then(|b| b.get(usize::from(s.slot)))
                .copied();
            if was == Some(s.weight_q1_15) {
                continue;
            }
            let in_pair = pairs.iter().any(|&(stimulus, readout)| {
                sets[stimulus].contains(id) && readout_set(sets, readout).contains(s.target)
            });
            let into = if inhibitory {
                &mut out.inhibitory
            } else {
                &mut out.excitatory
            };
            if in_pair {
                into.0 = into.0.saturating_add(1);
            } else {
                into.1 = into.1.saturating_add(1);
            }
        }
    }
    out
}

/// ADR-0085's assertion as a rule over an arm's reach, its pairs the ones `inhibition_pairs`
/// names: in a rewarded arm no excitatory synapse outside the two answer pairs moved; in the
/// withheld arm no excitatory synapse moved at all, inside the four pairs or outside them.
/// The inhibitory synapses are outside the clause: that they move is ADR-0085's rule, read
/// beside it. True on every arm is the assertion; false on one is a finding against
/// ADR-0080's derivation as ADR-0085 extends it, reported beside the verdict and not in
/// place of it.
fn excitatory_held(reach: &Reach, rewarded: bool) -> bool {
    reach.excitatory.1 == 0 && (rewarded || reach.excitatory.0 == 0)
}

// ------------------------------------------ the predicted readings' shape (ADR-0085)

/// ADR-0085's predicted reading (a): the arena's inhibitory sum falls in every block, as it
/// did under H-15 — each block's sum below the block's before, the first below the image's;
/// false for a run of no block.
fn falls_every_block(image: i64, blocks: &[Block]) -> bool {
    let mut previous = image;
    for block in blocks {
        if block.7 >= previous {
            return false;
        }
        previous = block.7;
    }
    !blocks.is_empty()
}

/// A Hypothesis written before the run and never asserted: the inhibitory sum falls in every
/// block of every arm, `[assignment, mirrored, withheld]`.
const FALLS_PREDICTED: [bool; 3] = [true; 3];

/// A sum as a fraction of the image's, in parts per ten thousand; zero against an image sum
/// of zero, which no image of this network has.
fn per_myriad(sum: i64, image: i64) -> i64 {
    sum.saturating_mul(10_000).checked_div(image).unwrap_or(0)
}

/// The readout each stimulus selected more often, `[A, B]`, from the selections per stimulus
/// (`[stimulus][readout 0, readout 1, tie]`): the sign of the two readouts' counts as
/// `selected` reads it, none at equal counts.
fn lean(splits: [[u32; 3]; 2]) -> [Option<u8>; 2] {
    [
        selected([splits[0][0], splits[0][1]]),
        selected([splits[1][0], splits[1][1]]),
    ]
}

/// The frozen network's lean: the readout each stimulus selected more often over ADR-0077's
/// frozen block of the settled candidate (`BACKGROUND_COUNTED_1024[SETTLED]`, the sixty-four
/// trials the calibration reproduces), each trial's selection the sign of its counts as the
/// task makes it.
fn frozen_lean() -> [Option<u8>; 2] {
    let mut splits = [[0u32; 3]; 2];
    for &(stimulus, counts) in &BACKGROUND_COUNTED_1024[SETTLED] {
        let into = &mut splits[usize::from(stimulus)][selected(counts).map_or(2, usize::from)];
        *into = into.saturating_add(1);
    }
    lean(splits)
}

/// The frozen network's lean as the pinned table gives it, computed by `frozen_lean` before
/// the run and held to it in the gate: readout 1 for both stimuli, by one selection for A
/// (14 to 15 with 5 ties) and three for B (12 to 15 with 3 ties).
const FROZEN_LEAN_1024: [Option<u8>; 2] = [Some(1), Some(1)];

/// ADR-0085's predicted reading (b), a Hypothesis written before the run and never asserted:
/// the withheld arm's excitatory weights stay the image's, so its selection stays where the
/// frozen network's is — the lean of its last 128 trials the frozen network's lean.
const LEAN_AS_FROZEN_PREDICTED: bool = true;

// ---------------------------------------------------------------- the run (brief 039)

/// The settled image with the inhibitory baseline set (ADR-0086): ADR-0077's frozen image
/// — the baseline patched to zero, the inhibitory baseline unset — with the modulator
/// section's flag at `[24]` set and its value at `[28..32)` written 0.5, the section
/// re-sealed; every other byte the frozen image's.
fn inhibited_image(zero: &[u8]) -> Vec<u8> {
    let mut img = zero.to_vec();
    let header = MenteionFileHeader::decode(img[0..64].try_into().unwrap());
    for at in (64..).step_by(64).take(header.section_count as usize) {
        let mut entry = SectionEntry::decode(img[at..][..64].try_into().unwrap());
        if entry.kind == SECTION_MODULATOR {
            let (offset, length) = (entry.offset as usize, entry.length as usize);
            img[offset..][24] = 1;
            img[offset..][28..32].copy_from_slice(&INHIBITORY_BASELINE_Q16.to_le_bytes());
            entry.crc64 = crc64(&img[offset..][..length]);
            img[at..][..64].copy_from_slice(&entry.encode());
            return img;
        }
    }
    panic!("the image holds a modulator section");
}

/// The engine from the inhibited image, decoded under the calibration's configuration (two
/// workers, a train that holds a trial, the baseline zero, the inhibitory baseline unset):
/// the image's baseline, inhibitory baseline, gain and step outrank the configuration's
/// (§8.3); the baseline asserted zero and the inhibitory baseline 0.5.
fn inhibited_from(image: &[u8], units: u32) -> Engine {
    let exec =
        served(Image::decode::<2048>(image, config(units, 2, 0)).expect("a well-formed record"));
    assert_eq!(exec.modulation_baseline_q16(), 0, "the gate");
    assert_eq!(
        exec.inhibitory_baseline_q16(),
        Some(INHIBITORY_BASELINE_Q16),
        "the image carries the inhibitory baseline"
    );
    exec
}

/// The two images of the one settled engine: ADR-0077's frozen image, held as
/// `settled_image` holds it, for the calibration; and the inhibited image for the arms —
/// decoded and asserted to carry the baseline zero, the inhibitory baseline 0.5, the sums,
/// the gain and the step, and to resume the clock where the image was written. The two
/// differ in the modulator section's flag byte, the one byte of the value that is not zero
/// and the section's CRC, and nowhere else.
fn inhibited_images(name: &str) -> (Vec<u8>, Vec<u8>) {
    let (exec, quieted) = settled_engine(name);
    let zero = frozen_image_checked(name, &exec, quieted);
    let inhibited = inhibited_image(&zero);
    let decoded = inhibited_from(&inhibited, 1024);
    assert_eq!(
        weights_by_polarity(&decoded),
        quieted,
        "{name}: the inhibited image carries the weights"
    );
    assert_eq!(
        decoded.homeostasis().synaptic_gain_q16,
        GAIN_1024,
        "{name}: and the gain"
    );
    assert_eq!(
        decoded.homeostasis().control_step_q0_16,
        BACKGROUNDS[SETTLED],
        "{name}: and the step"
    );
    assert_eq!(
        decoded.ticks(),
        exec.ticks(),
        "{name}: the clock resumes where the image was written"
    );
    assert_eq!(zero.len(), inhibited.len(), "{name}: one image, twice");
    let differing = zero
        .iter()
        .zip(inhibited.iter())
        .filter(|(a, b)| a != b)
        .count();
    assert!(
        differing > 0 && differing <= 10,
        "{name}: the images differ in the flag, the value's one byte and the section's CRC: {differing} bytes"
    );
    eprintln!(
        "DUMP {name} images {} bytes, {differing} differ, written at tick {}",
        inhibited.len(),
        exec.ticks()
    );
    (zero, inhibited)
}

/// An arm's run from the inhibited engine: `earned_run_under` with the arm's feedback and
/// assignment at the gate's zero, H-14's rule for every excitatory synapse — the oracle
/// consolidating every stimulus–readout synapse under the signal where the synapse is
/// addressed and under zero elsewhere, held to the record at every trial — while the
/// inhibitory synapses consolidate under their own baseline, which the oracle does not
/// model and the readings read from the record; under the withheld arm the reward is zero
/// and the signal stays at rest, asserted trial by trial.
fn inhibition_run(exec: &mut Engine, arm: Inhibition, trials: usize) -> EarnedRun {
    earned_run_under(
        exec,
        inhibition_feedback(arm),
        inhibition_mirrors(arm),
        1024,
        trials,
        GATE_BASELINE_Q16,
    )
}

/// The inhibitory sum after each block as a fraction of the image's, in parts per ten
/// thousand: the course a run's blocks hold, read beside H-15's.
fn course(image: i64, blocks: &[Block]) -> Vec<i64> {
    blocks.iter().map(|b| per_myriad(b.7, image)).collect()
}

/// Holds an arm's run to its pinned tables: the blocks and the trace, the composition per
/// block, the earned blocks, the readings' hash and the census.
fn pinned_inhibition(name: &str, k: usize, run: &EarnedRun, earned: &[EarnedBlock]) {
    let (blocks, trace, trials, read, volley_ticks) = run;
    pinned(
        &format!("{name} sight"),
        blocks,
        *trace,
        INHIBITION_BLOCKS_1024[k],
        INHIBITION_TRACES_1024[k],
    );
    let compositions: Vec<Composition> = trials.chunks(BLOCK).map(composition).collect();
    assert_eq!(
        compositions.as_slice(),
        INHIBITION_COMPOSITIONS_1024[k],
        "{name}: the composition per block"
    );
    assert_eq!(
        earned, INHIBITION_EARNED_1024[k],
        "{name}: the earned blocks"
    );
    assert_eq!(
        earned_hash(read),
        INHIBITION_READ_1024[k],
        "{name}: the readings"
    );
    assert_eq!(
        census_of(volley_ticks),
        INHIBITION_CENSUS_1024[k].to_vec(),
        "{name}: the volley's ticks"
    );
}

/// H-16 at 1 024 units (brief 039): the settled engine, held to ADR-0077 step by step, and
/// its two images; the calibration — a frozen block from the zero image, the inhibitory
/// baseline unset, the reward withheld, held to ADR-0077's frozen run — before any rewarded
/// run (H-16's stopping rule, step 2); then the assignment, the mirrored assignment and the
/// reward withheld, each `INHIBITION_TRIALS` trials from the inhibited image under the
/// task's own delivery, each dumped and the verdict and every reading computed by the rules
/// before anything is held; then the assertion — every excitatory synapse outside the pairs
/// the reward can reach the image's, bit for bit, on every arm — and the pinned tables.
#[test]
#[ignore]
fn inhibition_off_the_gate_at_1024_units_exhaustive() {
    let name = "inhibition1024";
    let (zero, inhibited) = inhibited_images(name);
    {
        let mut frozen = frozen_from(&zero, 1024);
        assert_eq!(
            frozen.inhibitory_baseline_q16(),
            None,
            "{name}: the calibration's image leaves the inhibitory baseline unset"
        );
        let calibration = taught_run(&mut frozen, Arm::Withheld, 1024, BLOCK);
        calibration_holds(&format!("{name} calibration"), &calibration);
        eprintln!("DUMP {name} calibration holds: ADR-0077's settled candidate reproduced");
    }
    let sets = geometry(1024, ROTATION_1024);
    let image_sums = QUIET_1024[SETTLED].1;
    let mut runs: Vec<EarnedRun> = Vec::with_capacity(INHIBITION_ARMS.len());
    let mut reaches = [Reach::default(); 3];
    let mut sums_after = [(0i64, 0i64); 3];
    for (k, &arm) in INHIBITION_ARMS.iter().enumerate() {
        let arm_name = format!("{name} {arm:?}");
        let mut exec = inhibited_from(&inhibited, 1024);
        assert_eq!(
            weights_by_polarity(&exec),
            image_sums,
            "{arm_name}: the image's sums"
        );
        let before = weights_of(&exec);
        let couplings_before = [
            [
                coupling(&exec, sets[0], sets[2]),
                coupling(&exec, sets[0], sets[3]),
            ],
            [
                coupling(&exec, sets[1], sets[2]),
                coupling(&exec, sets[1], sets[3]),
            ],
        ];
        assert_eq!(
            couplings_before, IMAGE_COUPLINGS_1024,
            "{arm_name}: the same image"
        );
        let run = inhibition_run(&mut exec, arm, INHIBITION_TRIALS);
        let reach = reach_by_polarity(&exec, &before, 1024, &inhibition_pairs(arm));
        sums_after[k] = weights_by_polarity(&exec);
        eprintln!(
            "DUMP {arm_name} reach {reach:?} sums after the run {:?} signal {:#x}",
            sums_after[k],
            exec.modulator().dopamine_rpe
        );
        reaches[k] = reach;
        runs.push(run);
    }
    // Every arm dumped and the verdict and the readings computed before anything is held.
    let mut tables: Vec<Vec<EarnedBlock>> = Vec::with_capacity(INHIBITION_ARMS.len());
    for (k, &arm) in INHIBITION_ARMS.iter().enumerate() {
        let earned = earned_blocks(&runs[k].3);
        dump_earned(&format!("{name} {arm:?}"), &runs[k], &earned);
        tables.push(earned);
    }
    let verdict = reinforced([&runs[0].0, &runs[1].0]);
    let correct_last = [last_correct(&runs[0].0), last_correct(&runs[1].0)];
    let last = [
        last_splits(&runs[0].3),
        last_splits(&runs[1].3),
        last_splits(&runs[2].3),
    ];
    let crossed = [
        crossing(&runs[0].0),
        crossing(&runs[1].0),
        crossing(&runs[2].0),
    ];
    let derivation_read = [
        derivation(&runs[0].3),
        derivation(&runs[1].3),
        derivation(&runs[2].3),
    ];
    let falls_read = [
        falls_every_block(image_sums.0, &runs[0].0),
        falls_every_block(image_sums.0, &runs[1].0),
        falls_every_block(image_sums.0, &runs[2].0),
    ];
    let courses = [
        course(image_sums.0, &runs[0].0),
        course(image_sums.0, &runs[1].0),
        course(image_sums.0, &runs[2].0),
    ];
    let lean_read = lean(last[WITHHELD]);
    let frozen = frozen_lean();
    let held = [
        excitatory_held(&reaches[0], true),
        excitatory_held(&reaches[1], true),
        excitatory_held(&reaches[2], false),
    ];
    eprintln!(
        "DUMP {name} verdict {verdict:?} predicted {INHIBITION_PREDICTED} correct last {correct_last:?} crossed {crossed:?} (H-14's {:?}) splits last {last:?} derivation {derivation_read:?} falls {falls_read:?} predicted {FALLS_PREDICTED:?} courses {courses:?} lean {lean_read:?} frozen {frozen:?} predicted as frozen {LEAN_AS_FROZEN_PREDICTED} held {held:?} reach {reaches:?} sums after {sums_after:?} image {image_sums:?}",
        &CROSSED_1024[..2]
    );
    // The assertion (ADR-0085's), after the verdict and beside it: every excitatory synapse
    // outside the pairs the reward can reach is the image's, on every arm.
    for (k, &arm) in INHIBITION_ARMS.iter().enumerate() {
        assert!(
            held[k],
            "{arm:?}: ADR-0085's assertion — every excitatory synapse outside the pairs the reward reaches ends the run as the image holds it: {:?}",
            reaches[k]
        );
    }
    for (k, &arm) in INHIBITION_ARMS.iter().enumerate() {
        pinned_inhibition(&format!("{name} {arm:?}"), k, &runs[k], &tables[k]);
    }
    assert_eq!(verdict, INHIBITION_1024, "the verdict as written");
    assert_eq!(correct_last, CORRECT_LAST_INHIBITION_1024);
    assert_eq!(crossed, CROSSED_INHIBITION_1024);
    assert_eq!(last, SPLITS_LAST_INHIBITION_1024);
    assert_eq!(derivation_read, DERIVATION_INHIBITION_1024);
    assert_eq!(falls_read, FALLS_1024);
    assert_eq!(lean_read, LEAN_1024);
    assert_eq!(frozen, FROZEN_LEAN_1024);
    assert_eq!(reaches, REACH_INHIBITION_1024);
    assert_eq!(sums_after, SUMS_AFTER_1024);
}

// --------------------- the measurement (brief 039), its tables in inhibition/pins/h16.rs

const INHIBITION_READ_1024: [u64; 3] = [0x9125c69cd9000bff, 0xbb2bfa57ebdfaff0, 0xfbb9d0ae596907cf];
/// The correct selections over the last 128 trials, per rewarded arm, against `REWARDED_MIN`.
const CORRECT_LAST_INHIBITION_1024: [u32; 2] = [128, 128];
/// Where each arm's selection first passed 40 of 64 per block, as read, beside H-14's 448
/// and 384 (`CROSSED_1024`) and H-15's 704 and 512.
const CROSSED_INHIBITION_1024: [Option<usize>; 3] = [Some(512), Some(256), None];
/// Whether the inhibitory sum fell in every block of each arm, as read, beside
/// `FALLS_PREDICTED`.
const FALLS_1024: [bool; 3] = [true, true, true];
/// The withheld arm's lean over its last 128 trials, as read, beside `FROZEN_LEAN_1024`.
const LEAN_1024: [Option<u8>; 2] = [Some(0), Some(1)];

/// The gate's test (ADR-0061's class; brief 039): the arms and their feedback; the constants
/// as ADR-0085 fixed them; the assertion's rule and the readings' rules at their edges over
/// reaches, blocks and splits written by hand; the frozen network's lean from the pinned
/// table; the reach by polarity on the instrument's network, nothing moved and then one
/// weight of each polarity moved by hand; and eight trials on the instrument's network at
/// 1 024 units with the inhibitory baseline set — the assignment, with the oracle held at
/// every trial inside `earned_run_under`, no excitatory synapse outside the answer pairs
/// moved and the inhibitory synapses moved; then the reward withheld, no excitatory synapse
/// moved and the inhibitory ones moved; then the reward withheld with the baseline unset,
/// nothing moved at all, today's rule. No whole run, and nothing else added to the gate. The
/// instrument's network and not the settled one, as ADR-0083's gate ran it: the settled
/// lead-in is the weekly test's cost, and the rules read the same on any network.
#[test]
fn the_first_eight_trials_of_inhibition_off_the_gate_at_1024_units_and_the_rules_over_their_tables()
{
    // The arms, their feedback, their assignment and their pairs; the constants.
    assert_eq!(
        INHIBITION_REWARDED,
        [INHIBITION_ARMS[0], INHIBITION_ARMS[1]]
    );
    assert_eq!(INHIBITION_ARMS[WITHHELD], Inhibition::Withheld);
    assert_eq!(
        inhibition_feedback(Inhibition::Assignment),
        Feedback::Answer
    );
    assert_eq!(inhibition_feedback(Inhibition::Mirrored), Feedback::Answer);
    assert_eq!(
        inhibition_feedback(Inhibition::Withheld),
        Feedback::Withheld
    );
    assert!(
        !inhibition_mirrors(Inhibition::Assignment)
            && inhibition_mirrors(Inhibition::Mirrored)
            && !inhibition_mirrors(Inhibition::Withheld)
    );
    assert!(
        inhibition_rewards(Inhibition::Assignment)
            && inhibition_rewards(Inhibition::Mirrored)
            && !inhibition_rewards(Inhibition::Withheld)
    );
    assert_eq!(
        inhibition_pairs(Inhibition::Assignment),
        vec![(0, 0), (1, 1)]
    );
    assert_eq!(inhibition_pairs(Inhibition::Mirrored), vec![(0, 1), (1, 0)]);
    assert_eq!(inhibition_pairs(Inhibition::Withheld), ALL_PAIRS.to_vec());
    assert_eq!(GATE_BASELINE_Q16, 0);
    assert_eq!(INHIBITORY_BASELINE_Q16, 0x8000);
    assert_eq!(INHIBITION_TRIALS, REINFORCED_TRIALS);
    assert_eq!([INHIBITION_PREDICTED, LEAN_AS_FROZEN_PREDICTED], [true; 2]);
    assert_eq!(FALLS_PREDICTED, [true; 3]);
    // The assertion's rule at its edges over reaches written by hand.
    let reach = |excitatory: (u64, u64), inhibitory: (u64, u64)| Reach {
        excitatory,
        inhibitory,
    };
    assert!(excitatory_held(&Reach::default(), true));
    assert!(excitatory_held(&Reach::default(), false));
    assert!(
        excitatory_held(&reach((5, 0), (0, 9)), true),
        "a rewarded arm's answer pairs may move"
    );
    assert!(
        !excitatory_held(&reach((5, 0), (0, 9)), false),
        "the withheld arm's may not"
    );
    assert!(
        !excitatory_held(&reach((0, 1), (0, 0)), true),
        "one excitatory synapse outside the pairs fails a rewarded arm"
    );
    assert!(!excitatory_held(&reach((0, 1), (0, 0)), false));
    assert!(
        excitatory_held(&reach((0, 0), (7, 3)), false),
        "the inhibitory synapses are outside the clause"
    );
    // The readings' rules at their edges: the fall over blocks written by hand, the fraction,
    // the lean over splits written by hand, and the frozen network's lean from the table.
    let block_with = |inhibitory: i64| -> Block {
        (
            0,
            0,
            [[0; 2]; 2],
            [0; 2],
            [0; 2],
            [0; 2],
            0,
            inhibitory,
            0,
            0,
            [[0; 2]; 2],
            0,
        )
    };
    assert!(!falls_every_block(100, &[]), "no block falls");
    assert!(falls_every_block(100, &[block_with(99)]));
    assert!(
        !falls_every_block(100, &[block_with(100)]),
        "level is not a fall"
    );
    assert!(!falls_every_block(100, &[block_with(101)]));
    assert!(falls_every_block(
        100,
        &[block_with(99), block_with(98), block_with(1)]
    ));
    assert!(!falls_every_block(100, &[block_with(99), block_with(99)]));
    assert!(!falls_every_block(
        100,
        &[block_with(99), block_with(98), block_with(98)]
    ));
    assert!(!falls_every_block(100, &[block_with(99), block_with(100)]));
    assert_eq!(per_myriad(100, 100), 10_000);
    assert_eq!(per_myriad(41, 100), 4_100);
    assert_eq!(per_myriad(165_876_268, 165_876_268), 10_000);
    assert_eq!(per_myriad(68_197_381, 165_876_268), 4_111, "H-15's 0.411");
    assert_eq!(per_myriad(1, 0), 0);
    assert_eq!(
        course(100, &[block_with(99), block_with(50)]),
        vec![9_900, 5_000]
    );
    assert_eq!(lean([[3, 4, 0], [5, 5, 1]]), [Some(1), None]);
    assert_eq!(lean([[4, 3, 9], [0, 1, 0]]), [Some(0), Some(1)]);
    assert_eq!(lean([[0; 3]; 2]), [None; 2]);
    assert_eq!(frozen_lean(), FROZEN_LEAN_1024, "the frozen network's lean");
    let mut frozen_splits = [[0u32; 3]; 2];
    for &(stimulus, counts) in &BACKGROUND_COUNTED_1024[SETTLED] {
        let into =
            &mut frozen_splits[usize::from(stimulus)][selected(counts).map_or(2, usize::from)];
        *into = into.saturating_add(1);
    }
    assert_eq!(
        frozen_splits,
        [[14, 15, 5], [12, 15, 3]],
        "the calibration's block by stimulus and readout"
    );
    assert_eq!(
        frozen_splits[0].iter().sum::<u32>() + frozen_splits[1].iter().sum::<u32>(),
        BLOCK as u32
    );
    // The reach by polarity on the instrument's network: nothing moved, then one excitatory
    // weight inside an answer pair and one inhibitory weight moved by hand.
    let p = prior(1024);
    let sets = geometry(1024, ROTATION_1024);
    let mut exec = at_gain(&p, config(1024, 2, GATE_BASELINE_Q16), GAIN_1024);
    let before = weights_of(&exec);
    assert_eq!(
        reach_by_polarity(&exec, &before, 1024, &ALL_PAIRS),
        Reach::default()
    );
    // The arena's synapses by polarity, the count the reach is read against: the settled
    // network is this network after its lead-in, with every synapse where the prior put it.
    let (inhibitory_synapses, excitatory_synapses) =
        exec.units()
            .iter()
            .fold((0u64, 0u64), |(inhibitory, excitatory), unit| {
                let count = unit.fan_out(exec.blocks()).count() as u64;
                if unit.flags & FLAG_INHIBITORY != 0 {
                    (inhibitory.saturating_add(count), excitatory)
                } else {
                    (inhibitory, excitatory.saturating_add(count))
                }
            });
    eprintln!(
        "DUMP inhibition1024 synapses inhibitory {inhibitory_synapses} excitatory {excitatory_synapses}"
    );
    assert!(inhibitory_synapses > 0 && excitatory_synapses > 0);
    let mut moved: Vec<(usize, usize)> = Vec::new();
    for unit in exec.units() {
        let id = unit.id as u32;
        let inhibitory = unit.flags & FLAG_INHIBITORY != 0;
        for s in unit.fan_out(exec.blocks()) {
            let wanted = if inhibitory {
                moved.len() == 1
            } else {
                moved.is_empty() && sets[0].contains(id) && sets[2].contains(s.target)
            };
            if wanted {
                moved.push((s.block_idx as usize, usize::from(s.slot)));
                break;
            }
        }
        if moved.len() == 2 {
            break;
        }
    }
    assert_eq!(moved.len(), 2, "one synapse of each polarity");
    for &(block, slot) in &moved {
        let w = &mut exec.blocks_mut()[block].weights_q1_15[slot];
        *w = w.saturating_sub(1);
    }
    assert_eq!(
        reach_by_polarity(&exec, &before, 1024, &[(0, 0)]),
        reach((1, 0), (0, 1)),
        "A→R0 inside, the inhibitory synapse outside"
    );
    assert_eq!(
        reach_by_polarity(&exec, &before, 1024, &[(0, 1)]),
        reach((0, 1), (0, 1)),
        "against the other pair, outside"
    );
    // Eight trials with the inhibitory baseline set on the instrument's network at 1 024
    // units: the assignment, the oracle held at every trial inside `earned_run_under`; then
    // the arena against the weights before — no excitatory synapse outside the answer pairs
    // moved, the inhibitory synapses moved — and ADR-0080's derivation true; then the reward
    // withheld, no excitatory synapse moved and the inhibitory ones moved; then the reward
    // withheld with the baseline unset, nothing moved: today's rule.
    let inhibited = || Config {
        inhibitory_baseline_q16: Some(INHIBITORY_BASELINE_Q16),
        ..config(1024, 2, GATE_BASELINE_Q16)
    };
    let mut exec = at_gain(&p, inhibited(), GAIN_1024);
    assert_eq!(
        exec.inhibitory_baseline_q16(),
        Some(INHIBITORY_BASELINE_Q16)
    );
    let before = weights_of(&exec);
    let run = inhibition_run(&mut exec, Inhibition::Assignment, GATE_TRIALS);
    let (blocks, trace, trials, read, _) = &run;
    assert!(blocks.is_empty(), "eight trials are no whole block");
    assert_eq!(trials.len(), GATE_TRIALS);
    eprintln!("DUMP inhibition1024 first eight trace {trace:#018x} read {read:?}");
    let reach_read = reach_by_polarity(
        &exec,
        &before,
        1024,
        &inhibition_pairs(Inhibition::Assignment),
    );
    eprintln!("DUMP inhibition1024 first eight reach {reach_read:?}");
    assert!(
        excitatory_held(&reach_read, true),
        "no excitatory synapse outside the answer pairs moved: {reach_read:?}"
    );
    assert!(
        reach_read.inhibitory.1 > 0,
        "the inhibitory synapses consolidated under their baseline: {reach_read:?}"
    );
    assert_eq!(
        reach_read.inhibitory.0, 0,
        "no inhibitory synapse is inside a pair: a stimulus unit is excitatory"
    );
    assert_eq!(derivation(read), [true; 3], "ADR-0080's derivation");
    assert!(
        read.iter().all(|t| t.4.abs() == REWARD_Q16),
        "every reward is 1.0 in magnitude"
    );
    assert!(
        read.iter()
            .all(|t| t.3 == (t.2 == Some(answer_of(t.0, false) as u8))),
        "correct is the answer, a tie not"
    );
    assert!(
        read.iter().all(|t| (t.4 > 0) == t.3),
        "the reward's sign is the outcome's"
    );
    assert!(
        read.iter().all(|t| t.5[0][1] == 0 && t.5[1][0] == 0),
        "no wrong pair consolidated under the gate"
    );
    let mut withheld = at_gain(&p, inhibited(), GAIN_1024);
    let before = weights_of(&withheld);
    let run = inhibition_run(&mut withheld, Inhibition::Withheld, GATE_TRIALS);
    let (_, trace, _, read, _) = &run;
    eprintln!("DUMP inhibition1024 first eight withheld trace {trace:#018x} read {read:?}");
    let reach_read = reach_by_polarity(&withheld, &before, 1024, &ALL_PAIRS);
    eprintln!("DUMP inhibition1024 first eight withheld reach {reach_read:?}");
    assert!(
        excitatory_held(&reach_read, false),
        "no excitatory synapse moved with the reward withheld: {reach_read:?}"
    );
    assert!(
        reach_read.inhibitory.1 > 0,
        "and the inhibitory synapses still consolidated: {reach_read:?}"
    );
    assert!(
        read.iter().all(|t| t.4 == 0 && t.6 == 0 && t.7 == 0),
        "no reward, the signal at rest"
    );
    assert!(
        read.iter()
            .all(|t| t.5.iter().flatten().all(|&amount| amount == 0)),
        "the pairs consolidated nothing under the gate"
    );
    let mut unset = at_gain(&p, config(1024, 2, GATE_BASELINE_Q16), GAIN_1024);
    assert_eq!(unset.inhibitory_baseline_q16(), None);
    let before = weights_of(&unset);
    let run = inhibition_run(&mut unset, Inhibition::Withheld, GATE_TRIALS);
    let (_, trace, _, _, _) = &run;
    eprintln!("DUMP inhibition1024 first eight unset trace {trace:#018x}");
    assert_eq!(
        reach_by_polarity(&unset, &before, 1024, &ALL_PAIRS),
        Reach::default(),
        "unset, nothing moves with the reward withheld under the gate: today's rule"
    );
    // Over the pinned tables: the verdict as written, by the rules; the correct selections,
    // the crossings, the splits, the derivation, the fall, the lean, the reach and the sums
    // as the constants state, the two predicted readings beside what was read — the fall as
    // predicted, the lean not the frozen network's for A; each arm's twenty-four blocks with
    // the same trials presenting A; the inhibitory sum below the block before in every block
    // of every arm; in a rewarded arm the two wrong pairs' couplings the image's to the LSB
    // in every block and the answer pairs' above the block before; in the withheld arm every
    // coupling and the excitatory sum the image's in every block, its rewards zero and its
    // signal at rest; the excitatory sum's rise in a rewarded arm exactly the answer pairs';
    // and each block's earned readings consistent with its sight's block.
    let verdict = reinforced([INHIBITION_BLOCKS_1024[0], INHIBITION_BLOCKS_1024[1]]);
    assert_eq!(verdict, INHIBITION_1024, "the verdict as written");
    assert!(verdict.yes, "H-16 is yes");
    assert_eq!(verdict.yes, INHIBITION_PREDICTED, "as ADR-0085 predicted");
    assert_eq!(
        [
            last_correct(INHIBITION_BLOCKS_1024[0]),
            last_correct(INHIBITION_BLOCKS_1024[1]),
        ],
        CORRECT_LAST_INHIBITION_1024
    );
    assert!(
        CORRECT_LAST_INHIBITION_1024
            .iter()
            .all(|&correct| correct >= REWARDED_MIN)
    );
    assert_eq!(
        [
            crossing(INHIBITION_BLOCKS_1024[0]),
            crossing(INHIBITION_BLOCKS_1024[1]),
            crossing(INHIBITION_BLOCKS_1024[2]),
        ],
        CROSSED_INHIBITION_1024
    );
    let image = QUIET_1024[SETTLED].1;
    assert_eq!(
        [
            falls_every_block(image.0, INHIBITION_BLOCKS_1024[0]),
            falls_every_block(image.0, INHIBITION_BLOCKS_1024[1]),
            falls_every_block(image.0, INHIBITION_BLOCKS_1024[2]),
        ],
        FALLS_1024
    );
    assert_eq!(
        FALLS_1024, FALLS_PREDICTED,
        "the inhibitory sum fell in every block of every arm, as predicted"
    );
    assert_eq!(lean(SPLITS_LAST_INHIBITION_1024[WITHHELD]), LEAN_1024);
    assert_ne!(
        LEAN_1024, FROZEN_LEAN_1024,
        "the withheld arm's lean is not the frozen network's for A: the predicted reading did not hold as written, and is recorded so"
    );
    assert_eq!(LEAN_1024[1], FROZEN_LEAN_1024[1], "and is for B");
    assert_eq!(DERIVATION_INHIBITION_1024, [[true; 3]; 3]);
    let assignment = INHIBITION_BLOCKS_1024[0];
    for (k, &arm) in INHIBITION_ARMS.iter().enumerate() {
        let blocks = INHIBITION_BLOCKS_1024[k];
        let earned = INHIBITION_EARNED_1024[k];
        let compositions = INHIBITION_COMPOSITIONS_1024[k];
        let rewarded = inhibition_rewards(arm);
        let mirrored = inhibition_mirrors(arm);
        assert_eq!(
            blocks.len(),
            INHIBITION_TRIALS / BLOCK,
            "{arm:?}: twenty-four blocks"
        );
        assert_eq!(earned.len(), INHIBITION_TRIALS / BLOCK);
        assert_eq!(compositions.len(), INHIBITION_TRIALS / BLOCK);
        assert_ne!(INHIBITION_TRACES_1024[k], 0);
        assert_ne!(INHIBITION_READ_1024[k], 0);
        assert!(!INHIBITION_CENSUS_1024[k].is_empty());
        let reach = REACH_INHIBITION_1024[k];
        assert!(
            excitatory_held(&reach, rewarded),
            "{arm:?}: the assertion over the pinned reach"
        );
        assert!(
            reach.inhibitory.1 > 0 && reach.inhibitory.0 == 0,
            "{arm:?}: the inhibitory synapses moved, none inside a pair"
        );
        if rewarded {
            let pairs = assigned_pairs(mirrored);
            let synapses = u64::from(SYNAPSES_1024[pairs[0].0][pairs[0].1])
                .saturating_add(u64::from(SYNAPSES_1024[pairs[1].0][pairs[1].1]));
            assert_eq!(
                reach.excitatory.0, synapses,
                "{arm:?}: every synapse of the two answer pairs moved"
            );
        } else {
            assert_eq!(reach.excitatory, (0, 0));
        }
        let last = blocks.last().expect("a block");
        assert_eq!(
            SUMS_AFTER_1024[k],
            (last.7, last.8),
            "{arm:?}: the sums after the run are the last block's"
        );
        assert!(
            SUMS_AFTER_1024[k].0 < image.0,
            "{arm:?}: the inhibitory sum fell"
        );
        let last_two = earned
            .iter()
            .rev()
            .take(LAST_BLOCKS)
            .fold([[0u32; 3]; 2], |mut sum, b| {
                for (s, split) in b.0.iter().enumerate() {
                    for (r, &n) in split.iter().enumerate() {
                        sum[s][r] = sum[s][r].saturating_add(n);
                    }
                }
                sum
            });
        assert_eq!(
            last_two, SPLITS_LAST_INHIBITION_1024[k],
            "{arm:?}: the last blocks' splits"
        );
        let mut previous_couplings = IMAGE_COUPLINGS_1024;
        for (j, block) in blocks.iter().enumerate() {
            assert_eq!(
                block.1, assignment[j].1,
                "{arm:?} block {j}: the trials presenting A"
            );
            let presented = [block.1, BLOCK as u32 - block.1];
            for (s, &n) in presented.iter().enumerate() {
                assert_eq!(
                    earned[j].0[s].iter().sum::<u32>(),
                    n,
                    "{arm:?} block {j}: every presentation of {s} selected or tied"
                );
            }
            assert_eq!(
                block.11,
                earned[j].0[0][2] + earned[j].0[1][2],
                "{arm:?} block {j}: the ties"
            );
            assert_eq!(
                block.9, earned[j].4,
                "{arm:?} block {j}: the signal after the last reward"
            );
            assert!(earned[j].3 <= SIGNAL_END_FIXED_Q16);
            assert!(compositions[j].3 <= BLOCK as u32);
            for &(s, r) in &ALL_PAIRS {
                let answer = rewarded && answer_of(s as u8, mirrored) == r;
                if answer {
                    assert!(
                        block.10[s][r] > previous_couplings[s][r],
                        "{arm:?} block {j}: the answer pair {s}→{r} rose"
                    );
                } else {
                    assert_eq!(
                        block.10[s][r], IMAGE_COUPLINGS_1024[s][r],
                        "{arm:?} block {j}: the coupling {s}→{r} is the image's to the LSB"
                    );
                }
            }
            previous_couplings = block.10;
            if rewarded {
                let correct =
                    earned[j].0[0][answer_of(0, mirrored)] + earned[j].0[1][answer_of(1, mirrored)];
                assert_eq!(block.0, correct, "{arm:?} block {j}: the correct trials");
                assert_eq!(
                    earned[j].1, correct,
                    "{arm:?} block {j}: one positive reward per correct trial"
                );
                let pairs = assigned_pairs(mirrored);
                let rise = block.10[pairs[0].0][pairs[0].1]
                    .saturating_sub(IMAGE_COUPLINGS_1024[pairs[0].0][pairs[0].1])
                    .saturating_add(
                        block.10[pairs[1].0][pairs[1].1]
                            .saturating_sub(IMAGE_COUPLINGS_1024[pairs[1].0][pairs[1].1]),
                    );
                assert_eq!(
                    block.8,
                    image.1.saturating_add(rise),
                    "{arm:?} block {j}: the excitatory sum rose by exactly the answer pairs' rise"
                );
            } else {
                assert_eq!(
                    block.0,
                    earned[j].0[0][0] + earned[j].0[1][1],
                    "{arm:?} block {j}: correct reads the assignment's answers"
                );
                assert_eq!(earned[j].1, 0, "{arm:?} block {j}: no reward");
                assert_eq!(
                    (earned[j].3, earned[j].4),
                    (0, 0),
                    "{arm:?} block {j}: the signal at rest"
                );
                assert_eq!(
                    block.8, image.1,
                    "{arm:?} block {j}: the excitatory sum is the image's"
                );
            }
        }
    }
}

// =================================================================================== H-17

// ------------------------------------------ written before the run (ADR-0089, ADR-0090)

/// H-17's run (ADR-0089): two of H-16's, forty-eight blocks.
const REVERSAL_TRIALS: usize = 2 * INHIBITION_TRIALS;
const _: () = assert!(REVERSAL_TRIALS == 3_072 && REVERSAL_TRIALS / BLOCK == 48);
/// The blocks of an H-17 run.
const REVERSAL_BLOCKS: usize = REVERSAL_TRIALS / BLOCK;

/// The flip (ADR-0089): the index of the first trial under the second mapping, the 1 537th,
/// the flip falling between the 1 536th and it. The trials before it are H-16's arm of the
/// first mapping, bit for bit (ADR-0090).
const FLIP: usize = INHIBITION_TRIALS;
/// The index of the last trial under the first mapping, the 1 536th, whose delivery the
/// 1 537th consolidates (ADR-0090).
const LAST_BEFORE_FLIP: usize = FLIP - 1;
/// The first block under the second mapping, the twenty-fifth; the twenty-four before it are
/// H-16's.
const FLIP_BLOCK: usize = FLIP / BLOCK;
const _: () = assert!(FLIP == 1_536 && FLIP % BLOCK == 0 && FLIP_BLOCK == 24);
const _: () = assert!(FLIP_BLOCK >= LAST_BLOCKS && REVERSAL_BLOCKS - FLIP_BLOCK >= LAST_BLOCKS);

/// The arms of H-17 (ADR-0089), each its own weekly test (ADR-0088's floor is the longest
/// test): the assignment first — A onto readout 0 and B onto readout 1 for the first 1 536
/// trials, the mirrored mapping for the last 1 536 — and the mirrored first, the other way
/// round; both `Feedback::Answer` under the task's own delivery from the one inhibited image,
/// the flip `Task::mirrored` negated and nothing else. No withheld arm.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum Reversal {
    AssignmentFirst,
    MirroredFirst,
}
const REVERSAL_ARMS: [Reversal; 2] = [Reversal::AssignmentFirst, Reversal::MirroredFirst];

/// The mapping an arm starts under, the task's `mirrored` before the flip; after it, the
/// other.
fn first_mapping(arm: Reversal) -> bool {
    arm == Reversal::MirroredFirst
}

/// The H-16 arm an H-17 arm's first half is, by its index in `INHIBITION_ARMS` (ADR-0090):
/// the assignment for the assignment first, the mirrored assignment for the mirrored first.
fn replicated_arm(arm: Reversal) -> usize {
    usize::from(first_mapping(arm))
}

/// ADR-0089's prediction, a Hypothesis written before the run: H-17 is no.
const REVERSAL_PREDICTED: bool = false;

// ------------------------------------------------------------ the criterion (ADR-0089)

/// Clause 1's count (ADR-0089): the correct selections over the last `LAST_BLOCKS` blocks
/// before the flip, trials 1 409 to 1 536, under the first mapping; zero for a run that does
/// not reach the flip.
fn correct_before(blocks: &[Block]) -> u32 {
    blocks.get(..FLIP_BLOCK).map_or(0, last_correct)
}

/// Clause 2's count: the correct selections over the last `LAST_BLOCKS` blocks of the run,
/// trials 2 945 to 3 072, under the second mapping; zero for a run of any other length.
fn correct_after(blocks: &[Block]) -> u32 {
    if blocks.len() == REVERSAL_BLOCKS {
        last_correct(blocks)
    } else {
        0
    }
}

/// H-17's criterion (ADR-0089), clause by clause per arm `[assignment first, mirrored
/// first]`: (1) it learned — `correct_before` at least `REWARDED_MIN`; (2) it revised —
/// `correct_after` at least `REWARDED_MIN`; a tie not correct, the task's count. `replicated`
/// is clause 1 in both arms, H-16's result reproduced; `yes` is all four. A run whose
/// `replicated` is false is a failure to replicate H-16 and answers nothing of H-17.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct Revision {
    learned: [bool; 2],
    revised: [bool; 2],
    replicated: bool,
    yes: bool,
}

fn revision(arms: [&[Block]; 2]) -> Revision {
    let learned = arms.map(|blocks| correct_before(blocks) >= REWARDED_MIN);
    let revised = arms.map(|blocks| correct_after(blocks) >= REWARDED_MIN);
    let replicated = learned[0] && learned[1];
    Revision {
        learned,
        revised,
        replicated,
        yes: replicated && revised[0] && revised[1],
    }
}

// ------------------------------------------------ the assertion's shape (ADR-0090)

/// The weights and the four couplings at a trial's end: what the assertion compares at the
/// 1 536th and the 1 537th trials.
type Snapshot = (Vec<Vec<i16>>, [[i64; 2]; 2]);

/// The four stimulus–readout couplings of `exec`, `[stimulus][readout]`, as a block reads
/// them.
fn pair_couplings(exec: &Engine, sets: &[Set; 4]) -> [[i64; 2]; 2] {
    [
        [
            coupling(exec, sets[0], sets[2]),
            coupling(exec, sets[0], sets[3]),
        ],
        [
            coupling(exec, sets[1], sets[2]),
            coupling(exec, sets[1], sets[3]),
        ],
    ]
}

/// The pair the 1 536th trial's delivery carries into the 1 537th (ADR-0090): the stimulus it
/// presented onto the readout it selected, when it was rewarded; none otherwise.
fn carried_pair(last: &EarnedTrial) -> Option<(usize, usize)> {
    if last.4 > 0 {
        last.2.map(|r| (usize::from(last.0), usize::from(r)))
    } else {
        None
    }
}

/// The old answer's pairs the carry-over does not reach: both, when the 1 536th trial
/// carried none.
fn uncarried(old: [(usize, usize); 2], carried: Option<(usize, usize)>) -> Vec<(usize, usize)> {
    old.into_iter()
        .filter(|&pair| Some(pair) != carried)
        .collect()
}

/// ADR-0090's assertion read over a run, clause by clause, as the synapses that moved: (a) of
/// the two old answer pairs, from the end of the 1 537th trial to the run's end; (b) of the
/// old answer pair the carry-over does not reach, from the end of the 1 536th; (c) the
/// excitatory synapses outside the four stimulus–readout pairs, from the image's. Beside
/// them, a reading and no clause: the synapses of the old answer's pairs the 1 537th trial
/// moved.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
struct Held {
    after_carry: u64,
    uncarried: u64,
    outside: u64,
    carried: u64,
}

/// The assertion as a rule: (a), (b) and (c) each moved nothing. True on both arms is the
/// assertion; false on one is a finding against ADR-0080's derivation as ADR-0089 and
/// ADR-0090 extend it, reported beside the verdict and not in place of it.
fn reversal_held(held: &Held) -> bool {
    held.after_carry == 0 && held.uncarried == 0 && held.outside == 0
}

/// The assertion's reach over an arm's run: the executor at the run's end against the
/// image's weights and the weights at the ends of the 1 536th and the 1 537th trials, the
/// pairs named by the arm's first mapping and the 1 536th trial's reading; `carried` is the
/// synapses of the old answer's pairs that moved in the 1 537th trial, read at its end.
fn held_of(
    exec: &Engine,
    image: &[Vec<i16>],
    at_flip: &[Vec<i16>],
    at_carry: &[Vec<i16>],
    last: &EarnedTrial,
    arm: Reversal,
    carried: u64,
) -> Held {
    let old = assigned_pairs(first_mapping(arm));
    Held {
        after_carry: reach(exec, at_carry, 1024, &old).0,
        uncarried: reach(exec, at_flip, 1024, &uncarried(old, carried_pair(last))).0,
        outside: reach_by_polarity(exec, image, 1024, &ALL_PAIRS)
            .excitatory
            .1,
        carried,
    }
}

// --------------------------------------------- the readings' shape (ADR-0089): the need

/// The measured need after the flip (ADR-0089), per arm: the trials in which the engine
/// selected the readout that is the answer under the second mapping (the task's correct
/// count), the trials in which it selected the old answer, the ties, the rewards it earned,
/// and the trial at whose block's end the selection first passed `CROSSING_MARK` after the
/// flip, none when no block did.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
struct Need {
    selected_new: u32,
    selected_old: u32,
    ties: u32,
    rewards: u32,
    crossed: Option<usize>,
}

fn need(blocks: &[Block], earned: &[EarnedBlock]) -> Need {
    let after = blocks.get(FLIP_BLOCK..).unwrap_or(&[]);
    let selected_new = after.iter().fold(0u32, |sum, b| sum.saturating_add(b.0));
    let ties = after.iter().fold(0u32, |sum, b| sum.saturating_add(b.11));
    let trials = (after.len() as u32).saturating_mul(BLOCK as u32);
    Need {
        selected_new,
        selected_old: trials.saturating_sub(selected_new).saturating_sub(ties),
        ties,
        rewards: earned
            .get(FLIP_BLOCK..)
            .unwrap_or(&[])
            .iter()
            .fold(0u32, |sum, b| sum.saturating_add(b.1)),
        crossed: crossing(after).map(|t| t.saturating_add(FLIP)),
    }
}

/// The first trial after the flip, by index, that earned a reward; none when none did.
fn first_reward(read: &[EarnedTrial]) -> Option<usize> {
    read.iter()
        .enumerate()
        .skip(FLIP)
        .find(|(_, t)| t.4 > 0)
        .map(|(k, _)| k)
}

/// The counts' gap per block (ADR-0089): for each stimulus, the spikes over the block of the
/// readout that is its answer under the first mapping less the other readout's, `[A, B]` —
/// the lead the first mapping's learning built before the flip, and the lead the old answer
/// keeps after it.
fn gaps(blocks: &[Block], first: bool) -> Vec<[i64; 2]> {
    blocks
        .iter()
        .map(|b| {
            [0u8, 1].map(|s| {
                let old = answer_of(s, first);
                let split = b.2[usize::from(s)];
                (split[old] as i64).saturating_sub(split[old ^ 1] as i64)
            })
        })
        .collect()
}

/// The new answer's pairs' couplings at the run's end less at the flip, `[A, B]`: whether, and
/// by how much, the rewards the second mapping earned raised them; zero for a run that does
/// not pass the flip.
fn new_rise(blocks: &[Block], first: bool) -> [i64; 2] {
    let (Some(flip), Some(last)) = (
        blocks.get(FLIP_BLOCK - 1),
        blocks.get(FLIP_BLOCK..).and_then(|after| after.last()),
    ) else {
        return [0; 2];
    };
    [0u8, 1].map(|s| {
        let new = answer_of(s, !first);
        last.10[usize::from(s)][new].saturating_sub(flip.10[usize::from(s)][new])
    })
}

/// The blocks in which the stimulus fired once by ADR-0074's measure (`fires_once`), of a
/// run's blocks and their compositions.
fn once_blocks(blocks: &[Block], compositions: &[Composition]) -> u32 {
    blocks
        .iter()
        .zip(compositions.iter())
        .filter(|(b, c)| fires_once(1024, b, c))
        .count() as u32
}

// ------------------------------------------------------------------ the run (brief 040)

/// An image with its header's version written as `version` and the header resealed, every
/// other byte as it was (ADR-0095): the image a writer of that version would have produced
/// from the same records, where no record's bytes differ between the two versions. Below 26 the
/// magic is written back too, `VCORTEX1`, the magic of every format before ADR-0221's (ADR-0222).
fn with_version(image: &[u8], version: u32) -> Vec<u8> {
    let mut img = image.to_vec();
    let mut header = MenteionFileHeader::decode(img[0..64].try_into().unwrap());
    header.version = version;
    if version < 26 {
        header.magic = *b"VCORTEX1";
    }
    header.crc64 = header.checksum();
    img[0..64].copy_from_slice(&header.encode());
    img
}

/// The format this file's whole-image pins hold their images at (ADR-0222): 25, the last whose
/// magic was `VCORTEX1`. ADR-0221 moved the format to 26 for the magic alone, so an image is held
/// to its pin through its header written back to 25 (`pinned_crc`), every byte but the magic, the
/// version and the seal the image the pin was taken from, as `BOTH_TARGETS_FORMAT` holds H-41's
/// derivations at 24.
const PINNED_FORMAT: u32 = 25;

/// An image's CRC-64 at `PINNED_FORMAT`: the CRC its pin holds.
fn pinned_crc(image: &[u8]) -> u64 {
    crc64(&with_version(image, PINNED_FORMAT))
}

/// An arm's run from the inhibited engine (brief 040): `earned_run_flipped` under the
/// answer's feedback at the gate's zero, the arm's first mapping, the flip before the trial
/// of index `flip`, and `after` reading the executor at every trial's end — the oracle held
/// to the record at every trial and every trial's contract asserted under the mapping in
/// force at it.
fn reversal_run(
    exec: &mut Engine,
    arm: Reversal,
    trials: usize,
    flip: usize,
    after: &mut dyn FnMut(&Engine, usize),
) -> EarnedRun {
    earned_run_flipped(
        exec,
        Feedback::Answer,
        first_mapping(arm),
        1024,
        trials,
        GATE_BASELINE_Q16,
        Some(flip),
        after,
    )
}

/// One arm of H-17 at 1 024 units (brief 040): the settled engine held to ADR-0077 step by
/// step and its two images; the calibration — a frozen block from the zero image, the
/// inhibitory baseline unset, the reward withheld, held to ADR-0077's frozen run — before
/// any rewarded run (H-17's stopping rule, step 2); then the arm's 3 072 trials from the
/// inhibited image, the flip between the 1 536th and the 1 537th, the weights and the four
/// couplings read at the ends of those two trials; everything dumped and the clauses, the
/// assertion and the readings computed before anything is held; then the first half held to
/// H-16's arm (ADR-0090), the assertion, and the pinned tables of the second half.
fn reversal_arm(arm: Reversal) {
    let k = REVERSAL_ARMS
        .iter()
        .position(|&a| a == arm)
        .expect("an arm of H-17");
    let name = format!("reversal1024 {arm:?}");
    let (zero, inhibited) = inhibited_images(&name);
    let image_crc = pinned_crc(&inhibited);
    {
        let mut frozen = frozen_from(&zero, 1024);
        assert_eq!(
            frozen.inhibitory_baseline_q16(),
            None,
            "{name}: the calibration's image leaves the inhibitory baseline unset"
        );
        let calibration = taught_run(&mut frozen, Arm::Withheld, 1024, BLOCK);
        calibration_holds(&format!("{name} calibration"), &calibration);
        eprintln!(
            "DUMP {name} calibration holds: ADR-0077's settled candidate reproduced; image crc {image_crc:#018x}"
        );
    }
    let sets = geometry(1024, ROTATION_1024);
    let image_sums = QUIET_1024[SETTLED].1;
    let mut exec = inhibited_from(&inhibited, 1024);
    assert_eq!(
        weights_by_polarity(&exec),
        image_sums,
        "{name}: the image's sums"
    );
    assert_eq!(
        pair_couplings(&exec, &sets),
        IMAGE_COUPLINGS_1024,
        "{name}: the same image"
    );
    let image = weights_of(&exec);
    let first = first_mapping(arm);
    let old = assigned_pairs(first);
    let mut at_flip: Option<Snapshot> = None;
    let mut at_carry: Option<Snapshot> = None;
    let mut carried = 0u64;
    let run = reversal_run(&mut exec, arm, REVERSAL_TRIALS, FLIP, &mut |exec, trial| {
        if trial == LAST_BEFORE_FLIP {
            at_flip = Some((weights_of(exec), pair_couplings(exec, &sets)));
        } else if trial == FLIP {
            let before = at_flip.as_ref().expect("the 1 536th trial's reading first");
            carried = reach(exec, &before.0, 1024, &old).0;
            at_carry = Some((weights_of(exec), pair_couplings(exec, &sets)));
        }
    });
    let (blocks, trace, trials, read, volley_ticks) = &run;
    let at_flip = at_flip.expect("the run reached the flip");
    let at_carry = at_carry.expect("and the trial after it");
    let earned = earned_blocks(read);
    let compositions: Vec<Composition> = trials.chunks(BLOCK).map(composition).collect();
    assert_eq!(blocks.len(), REVERSAL_BLOCKS, "{name}: forty-eight blocks");
    assert_eq!(read.len(), REVERSAL_TRIALS);
    // Everything dumped, and the clauses, the assertion and the readings computed, before
    // anything is held.
    dump_earned(&name, &run, &earned);
    eprintln!("DUMP {name} PIN blocks {:?}", &blocks[FLIP_BLOCK..]);
    eprintln!("DUMP {name} PIN trace {trace:#018x}");
    eprintln!(
        "DUMP {name} PIN compositions {:?}",
        &compositions[FLIP_BLOCK..]
    );
    eprintln!("DUMP {name} PIN earned {:?}", &earned[FLIP_BLOCK..]);
    eprintln!("DUMP {name} PIN read {:#018x}", earned_hash(&read[FLIP..]));
    eprintln!("DUMP {name} PIN census {:?}", census_of(volley_ticks));
    eprintln!("DUMP {name} PIN snapshots {:?}", (at_flip.1, at_carry.1));
    let last = &read[LAST_BEFORE_FLIP];
    let held = held_of(&exec, &image, &at_flip.0, &at_carry.0, last, arm, carried);
    let correct = [correct_before(blocks), correct_after(blocks)];
    let need_read = need(blocks, &earned);
    let first_rewarded = first_reward(read);
    let carried_read = carried_pair(last);
    let new_rise_read = new_rise(blocks, first);
    let once = once_blocks(blocks, &compositions);
    let falls = falls_every_block(image_sums.0, blocks);
    let derivation_read = derivation(read);
    let sums_after = weights_by_polarity(&exec);
    eprintln!(
        "DUMP {name} PIN readings correct {correct:?} held {held:?} need {need_read:?} first reward {first_rewarded:?} carried {carried_read:?} new rise {new_rise_read:?} once {once} falls {falls} derivation {derivation_read:?} image crc {image_crc:#018x}"
    );
    eprintln!(
        "DUMP {name} gaps {:?} course {:?} sums after {sums_after:?} image {image_sums:?} last splits {:?}",
        gaps(blocks, first),
        course(image_sums.0, blocks),
        last_splits(read)
    );
    // The first half is H-16's arm of the first mapping, bit for bit (ADR-0090): clause 1 is
    // H-16's 128, and a mismatch here is a failure to replicate H-16.
    let h16 = replicated_arm(arm);
    assert_eq!(
        &blocks[..FLIP_BLOCK],
        INHIBITION_BLOCKS_1024[h16],
        "{name}: the first half is H-16's arm, block by block"
    );
    assert_eq!(
        &compositions[..FLIP_BLOCK],
        INHIBITION_COMPOSITIONS_1024[h16],
        "{name}: and its composition"
    );
    assert_eq!(
        &earned[..FLIP_BLOCK],
        INHIBITION_EARNED_1024[h16],
        "{name}: and its earned blocks"
    );
    assert_eq!(
        earned_hash(&read[..FLIP]),
        INHIBITION_READ_1024[h16],
        "{name}: and its readings"
    );
    // The assertion (ADR-0090), after the dump and beside the verdict.
    assert!(
        reversal_held(&held),
        "{name}: ADR-0090's assertion — the old answer's pairs held from the 1 537th trial, the uncarried one from the 1 536th, no excitatory synapse outside the four pairs moved: {held:?}"
    );
    // The pinned tables of the second half, and the readings as the constants state.
    pinned(
        &format!("{name} sight"),
        &blocks[FLIP_BLOCK..],
        *trace,
        REVERSAL_BLOCKS_1024[k],
        REVERSAL_TRACES_1024[k],
    );
    assert_eq!(
        &compositions[FLIP_BLOCK..],
        REVERSAL_COMPOSITIONS_1024[k],
        "{name}: the composition per block"
    );
    assert_eq!(
        &earned[FLIP_BLOCK..],
        REVERSAL_EARNED_1024[k],
        "{name}: the earned blocks"
    );
    assert_eq!(
        earned_hash(&read[FLIP..]),
        REVERSAL_READ_1024[k],
        "{name}: the readings"
    );
    assert_eq!(
        census_of(volley_ticks),
        REVERSAL_CENSUS_1024[k].to_vec(),
        "{name}: the volley's ticks"
    );
    assert_eq!(image_crc, REVERSAL_IMAGE_CRC_1024, "{name}: the one image");
    assert_eq!(
        crc64(&with_version(&inhibited, 15)),
        REVERSAL_IMAGE_CRC_FORMAT_15_1024,
        "{name}: every byte but the header's version and seal is the image H-17 read (ADR-0095)"
    );
    assert_eq!((at_flip.1, at_carry.1), REVERSAL_SNAPSHOTS_1024[k]);
    assert_eq!(correct, CORRECT_REVERSAL_1024[k]);
    assert_eq!(held, HELD_1024[k]);
    assert_eq!(need_read, NEED_1024[k]);
    assert_eq!(first_rewarded, FIRST_REWARD_1024[k]);
    assert_eq!(carried_read, CARRIED_1024[k]);
    assert_eq!(new_rise_read, NEW_RISE_1024[k]);
    assert_eq!(once, ONCE_BLOCKS_REVERSAL_1024[k]);
    assert_eq!(falls, FALLS_REVERSAL_1024[k]);
    assert_eq!(derivation_read, DERIVATION_REVERSAL_1024[k]);
    assert_eq!(
        (sums_after, blocks.last().map(|b| (b.7, b.8))),
        (
            SUMS_AFTER_REVERSAL_1024[k],
            Some(SUMS_AFTER_REVERSAL_1024[k])
        ),
        "{name}: the sums after the run are the last block's"
    );
}

/// H-17's arm that starts from the assignment (brief 040): A onto readout 0 and B onto
/// readout 1 for 1 536 trials, then the mirrored mapping for 1 536.
#[test]
#[ignore]
fn the_assignment_reversed_from_the_assignment_at_1024_units_exhaustive() {
    reversal_arm(Reversal::AssignmentFirst);
}

/// H-17's arm that starts from the mirrored assignment (brief 040): A onto readout 1 and B
/// onto readout 0 for 1 536 trials, then the assignment for 1 536.
#[test]
#[ignore]
fn the_assignment_reversed_from_the_mirrored_assignment_at_1024_units_exhaustive() {
    reversal_arm(Reversal::MirroredFirst);
}

// --------------------- the measurement (brief 040), its tables in inhibition/pins/h17.rs

const REVERSAL_TRACES_1024: [u64; 2] = [0x64a1d9adad28586c, 0x742fba322cc8bd8a];
const REVERSAL_READ_1024: [u64; 2] = [0xfa696f8fb2545fd6, 0x5c13c015d378e9a5];
/// The one inhibited image both arms decode, its CRC-64: the same bytes in both tests. Since
/// ADR-0094 the image's format is not the one H-17 read, so its header's version and seal are
/// not the bytes H-17 read, and ADR-0095 pins the image as it is now beside the CRC H-17 read;
/// ADR-0114 moved the format from 16 to 17, ADR-0123 from 17 to 18, ADR-0131 from 18 to 19,
/// ADR-0134 from 19 to 20, ADR-0155 from 20 to 21, ADR-0180 from 21 to 22, ADR-0189 from 22
/// to 23, ADR-0194 from 23 to 24 and ADR-0202 from 24 to 25, and each re-pinned it the same way
/// (it was `0xd2965219775c394a` at format 16, `0x938ad516b6badd90` at 17, `0x50af5c06f491f0fe`
/// at 18, `0x11b3db0935771424` at 19, `0x443ce10ddfc9b4a7` at 20, `0x052066021e2f507d` at 21,
/// `0xc605ef125c047d13` at 22, `0x8719681d9de299c9` at 23 and `0x6d1b9b1b89793c15` at 24).
/// ADR-0221 moved the format to 26 for the magic alone, and the pin holds the image at 25 since
/// (`pinned_crc`, ADR-0222).
const REVERSAL_IMAGE_CRC_1024: u64 = 0x2c071c14489fd8cf;
/// The same image with its header's version written back to 15 and the header resealed: the
/// CRC-64 H-17 read (ADR-0091), so that every byte of the image but the version and the seal is
/// the image H-17 ran from (ADR-0095).
const REVERSAL_IMAGE_CRC_FORMAT_15_1024: u64 = 0xd5579c31308388ad;
/// The four couplings at the ends of the 1 536th and the 1 537th trials, `[stimulus][readout]`.
type Carry = ([[i64; 2]; 2], [[i64; 2]; 2]);
/// Clause 1's and clause 2's counts per arm, `[before the flip, the run's last 128]`,
/// against `REWARDED_MIN`.
const CORRECT_REVERSAL_1024: [[u32; 2]; 2] = [[128, 0], [128, 0]];
/// The first trial after the flip that earned a reward, per arm, as read.
const FIRST_REWARD_1024: [Option<usize>; 2] = [Some(1762), Some(2373)];
/// The pair the 1 536th trial carried into the 1 537th, per arm, as read.
const CARRIED_1024: [Option<(usize, usize)>; 2] = [Some((1, 1)), Some((1, 0))];
/// The new answer's pairs' rise from the flip to the run's end, `[A, B]`, per arm, as read.
const NEW_RISE_1024: [[i64; 2]; 2] = [[3415, 625], [0, 162]];
/// The blocks, of forty-eight, in which the stimulus fired once, per arm, as read.
const ONCE_BLOCKS_REVERSAL_1024: [u32; 2] = [48, 48];
/// Whether the inhibitory sum fell in every block of the run, per arm, as read.
const FALLS_REVERSAL_1024: [bool; 2] = [true, true];
/// ADR-0080's derivation as read over each arm's whole run, clause by clause.
const DERIVATION_REVERSAL_1024: [[bool; 3]; 2] = [[true, true, true], [true, true, true]];
/// The arena's sums by polarity after each arm's run, `(inhibitory, excitatory)`.
const SUMS_AFTER_REVERSAL_1024: [(i64, i64); 2] = [(28694627, 222960156), (28136783, 223537260)];

/// The gate's test (ADR-0061's class; brief 040): the arms and their mappings; the constants
/// as ADR-0089 fixed them; the criterion's two clauses at their edges over blocks written by
/// hand, a clause-1 failure among them; ADR-0090's assertion's rule and the pair the
/// carry-over names at their edges; the readings' rules over blocks written by hand; and a
/// few trials over a flip on the instrument's network at 1 024 units with the inhibitory
/// baseline set — the flipped run, the oracle held at every trial inside
/// `earned_run_flipped`, beside a run with no flip from the same network: every trial
/// before the flip the same, and at the flip the same stimulus, counts, selection, signal
/// and consolidation, the correctness the other mapping's and the reward's sign with it.
/// No whole run, and nothing else added to the gate.
#[test]
fn a_few_trials_over_the_flip_at_1024_units_and_the_rules_of_the_assignment_reversed() {
    // The arms, their mappings and the H-16 arms their first halves are; the constants.
    assert_eq!(
        REVERSAL_ARMS,
        [Reversal::AssignmentFirst, Reversal::MirroredFirst]
    );
    assert!(!first_mapping(Reversal::AssignmentFirst) && first_mapping(Reversal::MirroredFirst));
    assert_eq!(
        REVERSAL_ARMS.map(replicated_arm),
        [0, 1],
        "the first halves are H-16's assignment and mirrored assignment"
    );
    assert_eq!(INHIBITION_ARMS[0], Inhibition::Assignment);
    assert_eq!(INHIBITION_ARMS[1], Inhibition::Mirrored);
    assert!(!inhibition_mirrors(INHIBITION_ARMS[0]) && inhibition_mirrors(INHIBITION_ARMS[1]));
    assert_eq!(
        (
            REVERSAL_TRIALS,
            REVERSAL_BLOCKS,
            FLIP,
            LAST_BEFORE_FLIP,
            FLIP_BLOCK
        ),
        (3_072, 48, 1_536, 1_535, 24)
    );
    assert_eq!([REVERSAL_PREDICTED], [false], "ADR-0089 predicts no");
    // Every constant of H-17 restated unchanged: ADR-0065's window, trial, seed and gain,
    // ADR-0066's mark and window of the criterion, ADR-0076's stimulus and cancel, ADR-0077's
    // settled candidate, ADR-0080's length and reward, ADR-0085's two baselines.
    assert_eq!(
        (WINDOW.from, WINDOW.ticks, TRIAL_TICKS, SEED, GAIN_1024),
        (100, 500, 1 << 14, 27, 0x0001_C000)
    );
    assert_eq!((REWARDED_MIN, LAST_BLOCKS, BLOCK), (80, 2, 64));
    assert_eq!(SHAPE_F46, (2, 0x0001_4000));
    assert_eq!(CANCEL_PICKED_1024, Some(CANCEL_AT_THE_EXTREME));
    assert_eq!((SETTLED, BACKGROUNDS[SETTLED]), (0, 0));
    assert_eq!(INHIBITION_TRIALS, REINFORCED_TRIALS);
    assert_eq!((GATE_BASELINE_Q16, INHIBITORY_BASELINE_Q16), (0, 0x8000));
    assert_eq!(REWARD_Q16, ONE);
    // The criterion at its edges over blocks written by hand: clause 1 reads the last two
    // blocks before the flip and nothing after it; clause 2 the run's last two and nothing
    // before them; a tie is never counted, since the task's correct count is the rule's.
    let blocks_of = |correct: &[u32]| -> Vec<Block> {
        correct
            .iter()
            .map(|&c| {
                (
                    c,
                    0,
                    [[0; 2]; 2],
                    [0; 2],
                    [0; 2],
                    [0; 2],
                    0,
                    0,
                    0,
                    0,
                    [[0; 2]; 2],
                    (BLOCK as u32).saturating_sub(c),
                )
            })
            .collect()
    };
    let run_of = |before: [u32; 2], after: [u32; 2], rest: u32| -> Vec<Block> {
        let mut correct = vec![rest; REVERSAL_BLOCKS];
        correct[FLIP_BLOCK - 2] = before[0];
        correct[FLIP_BLOCK - 1] = before[1];
        correct[REVERSAL_BLOCKS - 2] = after[0];
        correct[REVERSAL_BLOCKS - 1] = after[1];
        blocks_of(&correct)
    };
    let edge = run_of([40, 40], [40, 40], 0);
    assert_eq!((correct_before(&edge), correct_after(&edge)), (80, 80));
    let v = revision([&edge, &edge]);
    assert_eq!(
        v,
        Revision {
            learned: [true; 2],
            revised: [true; 2],
            replicated: true,
            yes: true
        },
        "80 and 80 in both arms: yes"
    );
    let short_after = run_of([40, 40], [40, 39], 64);
    assert_eq!(correct_after(&short_after), 79);
    let v = revision([&edge, &short_after]);
    assert_eq!(
        v,
        Revision {
            learned: [true; 2],
            revised: [true, false],
            replicated: true,
            yes: false
        },
        "79 after the flip in one arm: no, whatever the blocks between"
    );
    let short_before = run_of([39, 40], [64, 64], 64);
    assert_eq!(correct_before(&short_before), 79);
    let v = revision([&short_before, &edge]);
    assert_eq!(
        v,
        Revision {
            learned: [false, true],
            revised: [true; 2],
            replicated: false,
            yes: false
        },
        "a clause-1 failure: not replicated, and no answer to H-17 whatever clause 2 reads"
    );
    let only_after = run_of([0, 0], [64, 64], 64);
    assert_eq!(
        correct_before(&only_after),
        0,
        "clause 1 reads no block after the flip"
    );
    let only_before = run_of([64, 64], [0, 0], 64);
    assert_eq!(
        correct_after(&only_before),
        0,
        "clause 2 reads no block before the run's last two"
    );
    assert_eq!(
        correct_before(&blocks_of(&[64; 23])),
        0,
        "a run short of the flip"
    );
    assert_eq!(
        correct_before(&blocks_of(&[64; 24])),
        128,
        "a run that reaches it"
    );
    assert_eq!(
        correct_after(&blocks_of(&[64; 47])),
        0,
        "a run short of 3 072"
    );
    assert_eq!(correct_after(&blocks_of(&[64; 49])), 0, "or past it");
    assert_eq!(correct_after(&blocks_of(&[64; 48])), 128);
    // ADR-0090's assertion's rule at its edges, and the pair the carry-over names.
    let held = |after_carry: u64, uncarried: u64, outside: u64, carried: u64| Held {
        after_carry,
        uncarried,
        outside,
        carried,
    };
    assert!(reversal_held(&Held::default()));
    assert!(
        reversal_held(&held(0, 0, 0, 170)),
        "the carry-over's moves are a reading, not a clause"
    );
    assert!(!reversal_held(&held(1, 0, 0, 0)), "(a)");
    assert!(!reversal_held(&held(0, 1, 0, 0)), "(b)");
    assert!(!reversal_held(&held(0, 0, 1, 0)), "(c)");
    let trial = |stimulus: u8, selection: Option<u8>, reward: i32| -> EarnedTrial {
        (
            stimulus,
            [0; 2],
            selection,
            reward > 0,
            reward,
            [[0; 2]; 2],
            0,
            0,
        )
    };
    assert_eq!(carried_pair(&trial(1, Some(1), ONE)), Some((1, 1)));
    assert_eq!(carried_pair(&trial(0, Some(1), ONE)), Some((0, 1)));
    assert_eq!(
        carried_pair(&trial(1, Some(0), ONE.saturating_neg())),
        None,
        "a punishment carries nothing"
    );
    assert_eq!(
        carried_pair(&trial(1, None, ONE.saturating_neg())),
        None,
        "nor a tie"
    );
    let old = assigned_pairs(false);
    assert_eq!(uncarried(old, Some((1, 1))), vec![(0, 0)]);
    assert_eq!(uncarried(old, Some((0, 0))), vec![(1, 1)]);
    assert_eq!(uncarried(old, None), vec![(0, 0), (1, 1)]);
    assert_eq!(uncarried(assigned_pairs(true), Some((1, 0))), vec![(0, 1)]);
    // The readings' rules over blocks written by hand: the need after the flip, the first
    // reward, the gaps and the new answer's rise.
    let mut hand = run_of([64, 64], [3, 1], 0);
    for (j, b) in hand.iter_mut().enumerate() {
        b.11 = if j >= FLIP_BLOCK { 2 } else { 0 };
    }
    hand[FLIP_BLOCK + 3].0 = 41;
    let earned_hand: Vec<EarnedBlock> = hand
        .iter()
        .map(|b| ([[0; 3]; 2], b.0, [[0; 2]; 2], 0, 0))
        .collect();
    assert_eq!(
        need(&hand, &earned_hand),
        Need {
            selected_new: 45,
            selected_old: 1_536 - 45 - 48,
            ties: 48,
            rewards: 45,
            crossed: Some(FLIP + 4 * BLOCK),
        },
        "the need reads the blocks after the flip and nothing before"
    );
    assert_eq!(
        need(&hand[..FLIP_BLOCK], &earned_hand[..FLIP_BLOCK]),
        Need::default(),
        "a run that stops at the flip needs nothing yet"
    );
    let mut read_hand = vec![trial(0, Some(0), ONE); REVERSAL_TRIALS];
    for t in read_hand.iter_mut().skip(FLIP) {
        *t = trial(0, Some(0), ONE.saturating_neg());
    }
    assert_eq!(
        first_reward(&read_hand),
        None,
        "the rewards before the flip are not read"
    );
    read_hand[FLIP + 700] = trial(0, Some(1), ONE);
    read_hand[FLIP + 900] = trial(1, Some(0), ONE);
    assert_eq!(first_reward(&read_hand), Some(FLIP + 700));
    read_hand[FLIP] = trial(1, Some(0), ONE);
    assert_eq!(first_reward(&read_hand), Some(FLIP), "the 1 537th counts");
    let mut gap_block = blocks_of(&[0])[0];
    gap_block.2 = [[30, 12], [11, 29]];
    assert_eq!(gaps(&[gap_block], false), vec![[18, 18]]);
    assert_eq!(gaps(&[gap_block], true), vec![[-18, -18]]);
    let mut rise = blocks_of(&[0; REVERSAL_BLOCKS]);
    rise[FLIP_BLOCK - 1].10 = [[100, 200], [300, 400]];
    rise[REVERSAL_BLOCKS - 1].10 = [[100, 207], [305, 400]];
    assert_eq!(
        new_rise(&rise, false),
        [7, 5],
        "A→R1 and B→R0 after the assignment"
    );
    assert_eq!(
        new_rise(&rise, true),
        [0, 0],
        "A→R0 and B→R1 after the mirrored"
    );
    assert_eq!(
        new_rise(&rise[..FLIP_BLOCK], false),
        [0; 2],
        "no block after the flip"
    );
    assert_eq!(once_blocks(&[], &[]), 0);
    // A few trials over a flip on the instrument's network at 1 024 units, the inhibitory
    // baseline set: the assignment first, flipped before the trial of index `GATE_FLIP`,
    // the oracle held at every trial inside `earned_run_flipped` and every trial's contract
    // asserted under the mapping in force; beside it the same network run to the flip's
    // trial with no flip. The trials before the flip are the same run; at the flip's trial
    // the stimulus, the counts, the selection, the signal at the trial's end and what the
    // trial consolidated are the same, and the correctness is the other mapping's, the
    // reward's sign with it; after it, every trial is judged under the other mapping.
    const GATE_FLIP: usize = GATE_TRIALS / 2;
    let p = prior(1024);
    let inhibited = || Config {
        inhibitory_baseline_q16: Some(INHIBITORY_BASELINE_Q16),
        ..config(1024, 2, GATE_BASELINE_Q16)
    };
    let mut flipped = at_gain(&p, inhibited(), GAIN_1024);
    let old = assigned_pairs(false);
    let mut snapshot: Option<Vec<Vec<i16>>> = None;
    let mut moved_at_flip = [0u64; 2];
    let run = reversal_run(
        &mut flipped,
        Reversal::AssignmentFirst,
        GATE_TRIALS,
        GATE_FLIP,
        &mut |exec, trial| {
            if trial.saturating_add(1) == GATE_FLIP {
                snapshot = Some(weights_of(exec));
            } else if trial == GATE_FLIP {
                let before = snapshot.as_ref().expect("the trial before the flip first");
                moved_at_flip = old.map(|pair| reach(exec, before, 1024, &[pair]).0);
            }
        },
    );
    let (blocks, trace, _, read, _) = &run;
    assert!(blocks.is_empty(), "a few trials are no whole block");
    assert_eq!(read.len(), GATE_TRIALS);
    let mut plain = at_gain(&p, inhibited(), GAIN_1024);
    let reference = earned_run_under(
        &mut plain,
        Feedback::Answer,
        false,
        1024,
        GATE_FLIP + 1,
        GATE_BASELINE_Q16,
    );
    let (_, _, _, unflipped, _) = &reference;
    eprintln!(
        "DUMP reversal1024 over the flip trace {trace:#018x} read {read:?} unflipped {unflipped:?} moved at the flip {moved_at_flip:?}"
    );
    assert_eq!(
        read[..GATE_FLIP],
        unflipped[..GATE_FLIP],
        "the trials before the flip are the run with no flip"
    );
    let (at, was) = (&read[GATE_FLIP], &unflipped[GATE_FLIP]);
    assert_eq!(
        (at.0, at.1, at.2, at.5, at.6),
        (was.0, was.1, was.2, was.5, was.6),
        "at the flip's trial the stimulus, the counts, the selection, what it consolidated and the signal at its end are the same"
    );
    assert!(
        at.2.is_some(),
        "the flip's trial selects a readout, so the mapping decides its correctness"
    );
    assert_eq!(at.3, !was.3, "and its correctness is the other mapping's");
    assert_eq!(
        (at.4, was.4),
        (
            if at.3 {
                REWARD_Q16
            } else {
                REWARD_Q16.saturating_neg()
            },
            if was.3 {
                REWARD_Q16
            } else {
                REWARD_Q16.saturating_neg()
            }
        ),
        "the reward's sign with it"
    );
    for (trial, t) in read.iter().enumerate() {
        let in_force = trial >= GATE_FLIP;
        assert_eq!(
            t.3,
            t.2 == Some(answer_of(t.0, in_force) as u8),
            "trial {trial}: correct under the mapping in force"
        );
        assert_eq!(
            t.4 > 0,
            t.3,
            "trial {trial}: the reward's sign is the outcome's"
        );
    }
    assert_eq!(
        derivation(read),
        [true; 3],
        "ADR-0080's derivation over the flip"
    );
    // ADR-0090 at the gate: the trial after the flip moves no old answer pair but the one the
    // trial before it carried, if it carried one.
    let carried = carried_pair(&read[GATE_FLIP - 1]);
    for (pair, &moved) in old.iter().zip(moved_at_flip.iter()) {
        if Some(*pair) != carried {
            assert_eq!(
                moved, 0,
                "the uncarried old answer pair {pair:?} held over the flip"
            );
        }
    }
    // And the carry-over itself, the defect ADR-0090 amends ADR-0089's assertion for: here the
    // trial before the flip was rewarded on A→R0, and the trial after it consolidated that
    // pair — 560 of its synapses moved — under the second mapping.
    assert_eq!(
        carried,
        Some((0, 0)),
        "the trial before the flip carried A→R0"
    );
    assert!(
        moved_at_flip[0] > 0 && read[GATE_FLIP].5[0][0] > 0,
        "and the first trial under the second mapping consolidated it: {moved_at_flip:?}"
    );
    // Over the pinned tables: each arm's whole run is H-16's arm of its first mapping followed
    // by the second half pinned here. The verdict as written, by the rule committed first; the
    // clauses' counts, the need and the readings as the constants state; and, block by block,
    // the tables consistent with one another, with ADR-0090's assertion and with the oracle's
    // consolidation — each coupling after a block is the one before it plus what the oracle
    // consolidated into that pair over the block.
    let image = QUIET_1024[SETTLED].1;
    let full: Vec<Vec<Block>> = REVERSAL_ARMS
        .iter()
        .enumerate()
        .map(|(k, &arm)| {
            [
                INHIBITION_BLOCKS_1024[replicated_arm(arm)],
                REVERSAL_BLOCKS_1024[k],
            ]
            .concat()
        })
        .collect();
    let earned_full: Vec<Vec<EarnedBlock>> = REVERSAL_ARMS
        .iter()
        .enumerate()
        .map(|(k, &arm)| {
            [
                INHIBITION_EARNED_1024[replicated_arm(arm)],
                REVERSAL_EARNED_1024[k],
            ]
            .concat()
        })
        .collect();
    let verdict = revision([&full[0], &full[1]]);
    assert_eq!(verdict, REVERSAL_1024, "the verdict as written");
    assert!(
        verdict.replicated,
        "clause 1 held in both arms: H-16 replicated"
    );
    assert_eq!(
        verdict.yes, REVERSAL_PREDICTED,
        "H-17 is no, as ADR-0089 predicted"
    );
    for (k, &arm) in REVERSAL_ARMS.iter().enumerate() {
        let blocks = &full[k];
        let earned = &earned_full[k];
        let first = first_mapping(arm);
        let h16 = replicated_arm(arm);
        assert_eq!(blocks.len(), REVERSAL_BLOCKS, "{arm:?}: forty-eight blocks");
        assert_eq!(earned.len(), REVERSAL_BLOCKS);
        assert_eq!(
            REVERSAL_COMPOSITIONS_1024[k].len(),
            REVERSAL_BLOCKS - FLIP_BLOCK
        );
        assert_ne!(REVERSAL_TRACES_1024[k], 0);
        assert_ne!(REVERSAL_READ_1024[k], 0);
        assert!(!REVERSAL_CENSUS_1024[k].is_empty());
        assert_eq!(
            [correct_before(blocks), correct_after(blocks)],
            CORRECT_REVERSAL_1024[k]
        );
        let need_read = need(blocks, earned);
        assert_eq!(need_read, NEED_1024[k], "{arm:?}: the need");
        assert_eq!(
            need_read
                .selected_new
                .saturating_add(need_read.selected_old)
                .saturating_add(need_read.ties),
            (REVERSAL_TRIALS - FLIP) as u32,
            "{arm:?}: every trial after the flip selected one readout or tied"
        );
        assert_eq!(
            need_read.rewards, need_read.selected_new,
            "{arm:?}: a reward for every selection of the new answer and none else"
        );
        assert_eq!(new_rise(blocks, first), NEW_RISE_1024[k]);
        assert_eq!(falls_every_block(image.0, blocks), FALLS_REVERSAL_1024[k]);
        assert_eq!(
            once_blocks(&blocks[..FLIP_BLOCK], INHIBITION_COMPOSITIONS_1024[h16]).saturating_add(
                once_blocks(&blocks[FLIP_BLOCK..], REVERSAL_COMPOSITIONS_1024[k])
            ),
            ONCE_BLOCKS_REVERSAL_1024[k]
        );
        assert!(
            reversal_held(&HELD_1024[k]) && HELD_1024[k].carried > 0,
            "{arm:?}: the assertion held, and the carry-over moved the carried pair"
        );
        assert_eq!(DERIVATION_REVERSAL_1024[k], [true; 3]);
        let last = blocks.last().expect("a block");
        assert_eq!(SUMS_AFTER_REVERSAL_1024[k], (last.7, last.8));
        // The first reward after the flip is in a block that earned one, and none before it.
        if let Some(t) = FIRST_REWARD_1024[k] {
            let at = t.checked_div(BLOCK).expect("a block");
            assert!(at >= FLIP_BLOCK && earned[at].1 > 0);
            assert!(earned[FLIP_BLOCK..at].iter().all(|b| b.1 == 0));
        }
        // The carry-over (ADR-0090): the 1 536th trial presented B and was rewarded on its
        // first mapping's answer, and only that pair moved in the 1 537th.
        let (at_flip, at_carry) = REVERSAL_SNAPSHOTS_1024[k];
        let carried = (1, answer_of(1, first));
        assert_eq!(CARRIED_1024[k], Some(carried));
        assert_eq!(
            at_flip,
            blocks[FLIP_BLOCK - 1].10,
            "the flip is at a block's end"
        );
        for &(s, r) in &ALL_PAIRS {
            if (s, r) == carried {
                assert_ne!(
                    at_carry[s][r], at_flip[s][r],
                    "{arm:?}: the carried pair moved"
                );
            } else {
                assert_eq!(at_carry[s][r], at_flip[s][r], "{arm:?}: {s}→{r} did not");
            }
        }
        let mut previous = IMAGE_COUPLINGS_1024;
        for (j, block) in blocks.iter().enumerate() {
            let after_flip = j >= FLIP_BLOCK;
            let in_force = first != after_flip;
            assert_eq!(
                block.1, full[0][j].1,
                "{arm:?} block {j}: the same trials present A in both arms"
            );
            let presented = [block.1, (BLOCK as u32).saturating_sub(block.1)];
            for (s, &n) in presented.iter().enumerate() {
                assert_eq!(
                    earned[j].0[s].iter().sum::<u32>(),
                    n,
                    "{arm:?} block {j}: every presentation of {s} selected or tied"
                );
            }
            assert_eq!(
                block.11,
                earned[j].0[0][2].saturating_add(earned[j].0[1][2]),
                "{arm:?} block {j}: the ties"
            );
            let correct = earned[j].0[0][answer_of(0, in_force)]
                .saturating_add(earned[j].0[1][answer_of(1, in_force)]);
            assert_eq!(
                block.0, correct,
                "{arm:?} block {j}: correct under the mapping in force"
            );
            assert_eq!(
                earned[j].1, correct,
                "{arm:?} block {j}: one reward per correct trial"
            );
            assert!(earned[j].3.abs() <= SIGNAL_END_FIXED_Q16);
            let mut rise = 0i64;
            for &(s, r) in &ALL_PAIRS {
                assert_eq!(
                    block.10[s][r],
                    previous[s][r].saturating_add(earned[j].2[s][r]),
                    "{arm:?} block {j}: {s}→{r} moved by what the oracle consolidated"
                );
                rise =
                    rise.saturating_add(block.10[s][r].saturating_sub(IMAGE_COUPLINGS_1024[s][r]));
                let old = r == answer_of(s as u8, first);
                if after_flip && old {
                    assert_eq!(
                        block.10[s][r], at_carry[s][r],
                        "{arm:?} block {j}: the old answer's pair {s}→{r} held from the 1 537th trial"
                    );
                }
                if !after_flip && !old {
                    assert_eq!(
                        block.10[s][r], IMAGE_COUPLINGS_1024[s][r],
                        "{arm:?} block {j}: the second mapping's pair {s}→{r} is the image's before the flip"
                    );
                }
            }
            assert_eq!(
                block.8,
                image.1.saturating_add(rise),
                "{arm:?} block {j}: the excitatory sum moved by the four pairs' moves and nothing else"
            );
            previous = block.10;
        }
    }
}

// =================================================================================== H-18

// ------------------------------------------ written before the run (ADR-0093, ADR-0095)

/// H-18's run (ADR-0093): three of H-16's, seventy-two blocks, the second mapping 3 072 trials
/// long, the length derived before any run from ADR-0091's readings.
const PUNISHED_TRIALS: usize = 3 * INHIBITION_TRIALS;
const _: () = assert!(PUNISHED_TRIALS == 4_608 && PUNISHED_TRIALS / BLOCK == 72);
/// The blocks of an H-18 run.
const PUNISHED_BLOCKS: usize = PUNISHED_TRIALS / BLOCK;
/// The flip is H-17's (`FLIP`, before the trial of index 1 536; ADR-0089): the second mapping
/// runs the rest, 3 072 trials in forty-eight blocks, and the criterion's two windows each lie
/// wholly under one mapping.
const _: () = assert!(PUNISHED_TRIALS - FLIP == 3_072 && PUNISHED_BLOCKS - FLIP_BLOCK == 48);
const _: () = assert!(FLIP_BLOCK >= LAST_BLOCKS && PUNISHED_BLOCKS - FLIP_BLOCK >= LAST_BLOCKS);

/// The arms of H-18 (ADR-0093): H-17's two, in their order, each its own weekly test — the
/// assignment first and the mirrored first — from the one signed image, the flip
/// `Task::mirrored` negated and nothing else.
const PUNISHED_ARMS: [Reversal; 2] = REVERSAL_ARMS;

/// ADR-0093 writes no prediction for the verdict.
const PUNISHED_PREDICTED: Option<bool> = None;

/// ADR-0093's three predicted readings, Hypotheses written before the run and never asserted:
/// (a) after the flip the old answer pair falls, block on block on average, until the
/// selection crosses (`old_falls`); (b) its fall is fastest in the first blocks after the flip
/// and slows as it falls (`fall_slows`); (c) in the first half the wrong pairs end below the
/// image's couplings, depressed while they were selected early (`wrong_below`). Each is
/// predicted true for both stimuli in both arms.
const OLD_FALLS_PREDICTED: bool = true;
const FALL_SLOWS_PREDICTED: bool = true;
const WRONG_BELOW_PREDICTED: bool = true;

/// The modulator section's byte that holds the signed gate's flag (ADR-0094), which the
/// signed image sets.
const SIGNED_GATE_BYTE: usize = 25;

// ------------------------------------------------------------ the criterion (ADR-0093)

/// Clause 2's count under H-18: the correct selections over the run's last `LAST_BLOCKS`
/// blocks, trials 4 481 to 4 608, under the second mapping; zero for a run of any other
/// length.
fn revised_count(blocks: &[Block]) -> u32 {
    if blocks.len() == PUNISHED_BLOCKS {
        last_correct(blocks)
    } else {
        0
    }
}

/// H-18's criterion (ADR-0093), clause by clause per arm `[assignment first, mirrored first]`:
/// (1) it learned — `correct_before`, H-17's count over the two blocks before the flip, trials
/// 1 409 to 1 536 under the first mapping, at least `REWARDED_MIN`; (2) it revised —
/// `revised_count` at least `REWARDED_MIN`; a tie not correct, the task's count. `yes` is all
/// four. The signed gate acts in the first half too, so the first half is not H-16's run and
/// nothing is replicated: a failure of clause 1 is a no about the signed gate.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct Punished {
    learned: [bool; 2],
    revised: [bool; 2],
    yes: bool,
}

fn punished(arms: [&[Block]; 2]) -> Punished {
    let learned = arms.map(|blocks| correct_before(blocks) >= REWARDED_MIN);
    let revised = arms.map(|blocks| revised_count(blocks) >= REWARDED_MIN);
    Punished {
        learned,
        revised,
        yes: learned[0] && learned[1] && revised[0] && revised[1],
    }
}

// ------------------------------------------------ the assertion's shape (ADR-0093)

/// ADR-0093's assertion as a rule over an arm's reach from the image to the run's end: no
/// excitatory synapse outside the four stimulus–readout pairs moved. Beside it, the oracle —
/// extended to the signed branch — is held to the record's weights, traces and signal at
/// every trial inside `earned_run_signed`. True on both arms is the assertion; false on one is
/// a finding, reported beside the verdict and not in place of it.
fn punished_held(reach: &Reach) -> bool {
    reach.excitatory.1 == 0
}

// --------------------------------------------------- the readings' shape (ADR-0093)

/// The old answer pairs' couplings, `[A, B]` — each stimulus onto its answer under the first
/// mapping — at the end of every block from the last before the flip to the run's end.
fn old_course(blocks: &[Block], first: bool) -> Vec<[i64; 2]> {
    blocks
        .iter()
        .skip(FLIP_BLOCK - 1)
        .map(|b| [0u8, 1].map(|s| b.10[usize::from(s)][answer_of(s, first)]))
        .collect()
}

/// Per stimulus `[A, B]`, the first block after the flip, by index, in which the stimulus
/// selected its answer under the second mapping more often than its answer under the first
/// (the earned splits): where its selection crossed; none when no block did.
fn crossed_block(earned: &[EarnedBlock], first: bool) -> [Option<usize>; 2] {
    [0u8, 1].map(|s| {
        let (old, new) = (answer_of(s, first), answer_of(s, !first));
        earned
            .iter()
            .enumerate()
            .skip(FLIP_BLOCK)
            .find(|(_, b)| b.0[usize::from(s)][new] > b.0[usize::from(s)][old])
            .map(|(j, _)| j)
    })
}

/// Per stimulus, the first trial after the flip, by index, that selected the stimulus's
/// answer under the second mapping; none when none did.
fn first_new(read: &[EarnedTrial], first: bool) -> [Option<usize>; 2] {
    [0u8, 1].map(|s| {
        let new = answer_of(s, !first) as u8;
        read.iter()
            .enumerate()
            .skip(FLIP)
            .find(|(_, t)| t.0 == s && t.2 == Some(new))
            .map(|(k, _)| k)
    })
}

/// Per stimulus, the last block the predicted readings (a) and (b) read: the stimulus's
/// crossing block, or the run's last block when it never crossed; none for a run that does
/// not pass the flip.
fn span_end(blocks: &[Block], earned: &[EarnedBlock], first: bool) -> [Option<usize>; 2] {
    let last = blocks.len().checked_sub(1).filter(|&j| j >= FLIP_BLOCK);
    let crossed = crossed_block(earned, first);
    crossed.map(|c| last.map(|l| c.unwrap_or(l).min(l)))
}

/// ADR-0093's predicted reading (a) as a rule: per stimulus, the old answer pair's coupling at
/// the end of its span below its coupling at the flip, the end of the 1 536th trial — a fall
/// on average over the blocks from the flip until the selection crossed.
fn old_falls(blocks: &[Block], earned: &[EarnedBlock], first: bool) -> [bool; 2] {
    let ends = span_end(blocks, earned, first);
    [0usize, 1].map(|s| {
        let old = answer_of(s as u8, first);
        match (
            blocks.get(FLIP_BLOCK - 1),
            ends[s].and_then(|j| blocks.get(j)),
        ) {
            (Some(flip), Some(end)) => end.10[s][old] < flip.10[s][old],
            _ => false,
        }
    })
}

/// ADR-0093's predicted reading (b) as a rule: per stimulus, over the span's blocks after the
/// flip, the old answer pair's fall over the first half of them (rounded down) greater than
/// its fall over the rest; false for a span of fewer than two blocks after the flip.
fn fall_slows(blocks: &[Block], earned: &[EarnedBlock], first: bool) -> [bool; 2] {
    let ends = span_end(blocks, earned, first);
    [0usize, 1].map(|s| {
        let old = answer_of(s as u8, first);
        let Some(end) = ends[s] else {
            return false;
        };
        let after = end.saturating_add(1).saturating_sub(FLIP_BLOCK);
        if after < 2 {
            return false;
        }
        let mid = (FLIP_BLOCK - 1).saturating_add(after >> 1);
        let at = |j: usize| blocks.get(j).map_or(0, |b| b.10[s][old]);
        let early = at(FLIP_BLOCK - 1).saturating_sub(at(mid));
        let late = at(mid).saturating_sub(at(end));
        early > late
    })
}

/// ADR-0093's predicted reading (c) as a rule: per stimulus, the wrong pair's coupling — the
/// stimulus onto the readout that is not its answer under the first mapping — at the end of
/// the first half below the image's; false for a run that does not reach the flip.
fn wrong_below(blocks: &[Block], first: bool) -> [bool; 2] {
    let Some(flip) = blocks.get(FLIP_BLOCK - 1) else {
        return [false; 2];
    };
    [0usize, 1].map(|s| {
        let wrong = answer_of(s as u8, !first);
        flip.10[s][wrong] < IMAGE_COUPLINGS_1024[s][wrong]
    })
}

/// A block of what the consolidation did to the addressed pairs (brief 041), split by the
/// sign of the delivery each trial consolidated: `[after a reward, after a punishment]`, each
/// `([rose, fell, stayed], [raised, lowered])` summed over the block's trials.
type MovesBlock = [Moves; 2];

/// An arm's moves per block from its trials: a trial consolidates the previous trial's
/// delivery (ADR-0090), so trial `t`'s moves count under the sign of trial `t − 1`'s reward,
/// in trial `t`'s block; the first trial's, which consolidates nothing addressed, under
/// neither.
fn moves_blocks(read: &[EarnedTrial], moves: &[Moves]) -> Vec<MovesBlock> {
    let mut out = vec![[([0u32; 3], [0i64; 2]); 2]; read.len().div_ceil(BLOCK)];
    for (t, m) in moves.iter().enumerate().skip(1) {
        let Some(previous) = t.checked_sub(1).and_then(|p| read.get(p)) else {
            continue;
        };
        let side = match previous.4 {
            1.. => 0,
            0 => continue,
            _ => 1,
        };
        let Some(block) = t.checked_div(BLOCK).and_then(|j| out.get_mut(j)) else {
            continue;
        };
        add_moves(&mut block[side], m);
    }
    out
}

/// `into` plus `m`, count by count and amount by amount.
fn add_moves(into: &mut Moves, m: &Moves) {
    for (a, b) in into.0.iter_mut().zip(m.0.iter()) {
        *a = a.saturating_add(*b);
    }
    for (a, b) in into.1.iter_mut().zip(m.1.iter()) {
        *a = a.saturating_add(*b);
    }
}

/// The moves after a punishment (`side` 1) or after a reward (`side` 0), summed over the
/// blocks before the flip and over the blocks from it, `[before, after]`: the readings of how
/// often a punishment potentiated an addressed synapse, one whose trace was negative.
fn moves_totals(blocks: &[MovesBlock], side: usize) -> [Moves; 2] {
    let mut out = [([0u32; 3], [0i64; 2]); 2];
    for (j, block) in blocks.iter().enumerate() {
        add_moves(&mut out[usize::from(j >= FLIP_BLOCK)], &block[side]);
    }
    out
}

// ---------------------------------------------------------------- the run (brief 041)

/// The signed image (ADR-0094): the inhibited image with the modulator section's flag at
/// `[25]` set, the section re-sealed; every other byte the inhibited image's.
fn signed_image(inhibited: &[u8]) -> Vec<u8> {
    let mut img = inhibited.to_vec();
    let header = MenteionFileHeader::decode(img[0..64].try_into().unwrap());
    for at in (64..).step_by(64).take(header.section_count as usize) {
        let mut entry = SectionEntry::decode(img[at..][..64].try_into().unwrap());
        if entry.kind == SECTION_MODULATOR {
            let (offset, length) = (entry.offset as usize, entry.length as usize);
            assert_eq!(img[offset..][SIGNED_GATE_BYTE], 0, "the gate unset before");
            img[offset..][SIGNED_GATE_BYTE] = 1;
            entry.crc64 = crc64(&img[offset..][..length]);
            img[at..][..64].copy_from_slice(&entry.encode());
            return img;
        }
    }
    panic!("the image holds a modulator section");
}

/// The engine from the signed image, decoded under the calibration's configuration: the
/// image's baseline, inhibitory baseline, signed gate, gain and step outrank the
/// configuration's (§8.3); the baseline asserted zero, the inhibitory baseline 0.5 and the
/// signed gate set.
fn signed_from(image: &[u8], units: u32) -> Engine {
    let exec = inhibited_from(image, units);
    assert!(exec.signed_gate(), "the image carries the signed gate");
    exec
}

/// The images of the one settled engine (brief 041): ADR-0077's frozen image for the
/// calibration, and the signed image for the arms — built from the inhibited image as H-16's
/// and H-17's tests build it, decoded and asserted to carry the gate, the sums, the gain and
/// the step, and to differ from the inhibited image in the flag byte and the section's CRC
/// and nowhere else.
fn signed_images(name: &str) -> (Vec<u8>, Vec<u8>) {
    let (zero, inhibited) = inhibited_images(name);
    let signed = signed_image(&inhibited);
    assert!(
        !inhibited_from(&inhibited, 1024).signed_gate(),
        "{name}: the inhibited image leaves the gate unset"
    );
    let decoded = signed_from(&signed, 1024);
    assert_eq!(
        weights_by_polarity(&decoded),
        QUIET_1024[SETTLED].1,
        "{name}: the signed image carries the weights"
    );
    assert_eq!(decoded.homeostasis().synaptic_gain_q16, GAIN_1024);
    assert_eq!(
        decoded.homeostasis().control_step_q0_16,
        BACKGROUNDS[SETTLED]
    );
    assert_eq!(signed.len(), inhibited.len(), "{name}: one image, twice");
    let differing = signed
        .iter()
        .zip(inhibited.iter())
        .filter(|(a, b)| a != b)
        .count();
    assert!(
        differing > 0 && differing <= 9,
        "{name}: the images differ in the flag and the section's CRC: {differing} bytes"
    );
    eprintln!(
        "DUMP {name} signed image {} bytes, {differing} differ from the inhibited",
        signed.len()
    );
    (zero, signed)
}

/// An arm's run from the signed engine (brief 041): `earned_run_signed` under the answer's
/// feedback at the gate's zero with the signed gate set, the arm's first mapping, the flip
/// before the trial of index `flip`, and `after` reading the executor at every trial's end —
/// the oracle, consolidating every addressed replayed synapse by `consolidated_signed`, held
/// to the record at every trial, and every trial's contract asserted under the mapping in
/// force at it.
fn punished_run(
    exec: &mut Engine,
    arm: Reversal,
    trials: usize,
    flip: usize,
    after: &mut dyn FnMut(&Engine, usize),
) -> (EarnedRun, Vec<Moves>) {
    earned_run_signed(
        exec,
        Feedback::Answer,
        first_mapping(arm),
        1024,
        trials,
        GATE_BASELINE_Q16,
        Some(flip),
        true,
        after,
    )
}

/// One arm of H-18 at 1 024 units (brief 041): the settled engine held to ADR-0077 step by
/// step and its images; the calibration — a frozen block from the zero image, the inhibitory
/// baseline and the signed gate unset, the reward withheld, held to ADR-0077's frozen run —
/// before any rewarded run (H-18's stopping rule, step 2); then the arm's 4 608 trials from
/// the signed image, the flip between the 1 536th and the 1 537th, the couplings read at the
/// end of the 1 537th; everything dumped and the clauses, the assertion and the readings
/// computed before anything is held; then the assertion, and the pinned tables.
fn punished_arm(arm: Reversal) {
    let k = PUNISHED_ARMS
        .iter()
        .position(|&a| a == arm)
        .expect("an arm of H-18");
    let name = format!("punished1024 {arm:?}");
    let (zero, signed) = signed_images(&name);
    let image_crc = pinned_crc(&signed);
    {
        let mut frozen = frozen_from(&zero, 1024);
        assert_eq!(
            (frozen.inhibitory_baseline_q16(), frozen.signed_gate()),
            (None, false),
            "{name}: the calibration's image leaves the inhibitory baseline and the signed gate unset"
        );
        let calibration = taught_run(&mut frozen, Arm::Withheld, 1024, BLOCK);
        calibration_holds(&format!("{name} calibration"), &calibration);
        eprintln!(
            "DUMP {name} calibration holds: ADR-0077's settled candidate reproduced; image crc {image_crc:#018x}"
        );
    }
    let sets = geometry(1024, ROTATION_1024);
    let image_sums = QUIET_1024[SETTLED].1;
    let mut exec = signed_from(&signed, 1024);
    assert_eq!(
        weights_by_polarity(&exec),
        image_sums,
        "{name}: the image's sums"
    );
    assert_eq!(
        pair_couplings(&exec, &sets),
        IMAGE_COUPLINGS_1024,
        "{name}: the same image"
    );
    let image = weights_of(&exec);
    let first = first_mapping(arm);
    let mut at_carry: Option<[[i64; 2]; 2]> = None;
    let (run, moves) = punished_run(&mut exec, arm, PUNISHED_TRIALS, FLIP, &mut |exec, trial| {
        if trial == FLIP {
            at_carry = Some(pair_couplings(exec, &sets));
        }
    });
    let (blocks, trace, trials, read, volley_ticks) = &run;
    let at_carry = at_carry.expect("the run reached the trial after the flip");
    let earned = earned_blocks(read);
    let compositions: Vec<Composition> = trials.chunks(BLOCK).map(composition).collect();
    let moved = moves_blocks(read, &moves);
    assert_eq!(blocks.len(), PUNISHED_BLOCKS, "{name}: seventy-two blocks");
    assert_eq!(read.len(), PUNISHED_TRIALS);
    assert_eq!(moved.len(), PUNISHED_BLOCKS);
    // Everything dumped, and the clauses, the assertion and the readings computed, before
    // anything is held.
    dump_earned(&name, &run, &earned);
    eprintln!("DUMP {name} PIN blocks {blocks:?}");
    eprintln!("DUMP {name} PIN trace {trace:#018x}");
    eprintln!("DUMP {name} PIN compositions {compositions:?}");
    eprintln!("DUMP {name} PIN earned {earned:?}");
    eprintln!("DUMP {name} PIN read {:#018x}", earned_hash(read));
    eprintln!("DUMP {name} PIN census {:?}", census_of(volley_ticks));
    eprintln!("DUMP {name} PIN moves {moved:?}");
    eprintln!("DUMP {name} PIN carry {at_carry:?}");
    let reach = reach_by_polarity(&exec, &image, 1024, &ALL_PAIRS);
    let correct = [correct_before(blocks), revised_count(blocks)];
    let need_read = need(blocks, &earned);
    let first_rewarded = first_reward(read);
    let first_new_read = first_new(read, first);
    let crossed = crossed_block(&earned, first);
    let old_falls_read = old_falls(blocks, &earned, first);
    let fall_slows_read = fall_slows(blocks, &earned, first);
    let wrong_below_read = wrong_below(blocks, first);
    let punished_moves = moves_totals(&moved, 1);
    let rewarded_moves = moves_totals(&moved, 0);
    let new_rise_read = new_rise(blocks, first);
    let once = once_blocks(blocks, &compositions);
    let falls = falls_every_block(image_sums.0, blocks);
    let derivation_read = derivation(read);
    let sums_after = weights_by_polarity(&exec);
    eprintln!(
        "DUMP {name} PIN readings correct {correct:?} reach {reach:?} need {need_read:?} first reward {first_rewarded:?} first new {first_new_read:?} crossed {crossed:?} old falls {old_falls_read:?} (predicted {OLD_FALLS_PREDICTED}) slows {fall_slows_read:?} (predicted {FALL_SLOWS_PREDICTED}) wrong below {wrong_below_read:?} (predicted {WRONG_BELOW_PREDICTED}) punished moves {punished_moves:?} rewarded moves {rewarded_moves:?} new rise {new_rise_read:?} once {once} falls {falls} derivation {derivation_read:?} sums after {sums_after:?} image crc {image_crc:#018x}"
    );
    eprintln!(
        "DUMP {name} old course {:?} gaps {:?} course {:?} image {image_sums:?} last splits {:?}",
        old_course(blocks, first),
        gaps(blocks, first),
        course(image_sums.0, blocks),
        last_splits(read)
    );
    // The assertion (ADR-0093), after the dump and beside the verdict.
    assert!(
        punished_held(&reach),
        "{name}: ADR-0093's assertion — no excitatory synapse outside the four stimulus–readout pairs moved: {reach:?}"
    );
    // The pinned tables, and the readings as the constants state.
    pinned(
        &format!("{name} sight"),
        blocks,
        *trace,
        PUNISHED_BLOCKS_1024[k],
        PUNISHED_TRACES_1024[k],
    );
    assert_eq!(
        compositions.as_slice(),
        PUNISHED_COMPOSITIONS_1024[k],
        "{name}: the composition per block"
    );
    assert_eq!(
        earned.as_slice(),
        PUNISHED_EARNED_1024[k],
        "{name}: the earned blocks"
    );
    assert_eq!(
        earned_hash(read),
        PUNISHED_READ_1024[k],
        "{name}: the readings"
    );
    assert_eq!(
        census_of(volley_ticks),
        PUNISHED_CENSUS_1024[k].to_vec(),
        "{name}: the volley's ticks"
    );
    assert_eq!(
        moved.as_slice(),
        PUNISHED_MOVES_1024[k],
        "{name}: the moves per block"
    );
    assert_eq!(image_crc, PUNISHED_IMAGE_CRC_1024, "{name}: the one image");
    assert_eq!(
        crc64(&with_version(&signed, 16)),
        PUNISHED_IMAGE_CRC_FORMAT_16_1024,
        "{name}: every byte but the header's version and seal is the image H-18 read (ADR-0114)"
    );
    assert_eq!(at_carry, PUNISHED_CARRY_1024[k]);
    assert_eq!(correct, CORRECT_PUNISHED_1024[k]);
    assert_eq!(reach, REACH_PUNISHED_1024[k]);
    assert_eq!(need_read, NEED_PUNISHED_1024[k]);
    assert_eq!(first_rewarded, FIRST_REWARD_PUNISHED_1024[k]);
    assert_eq!(first_new_read, FIRST_NEW_1024[k]);
    assert_eq!(crossed, CROSSED_BLOCK_1024[k]);
    assert_eq!(old_falls_read, OLD_FALLS_1024[k]);
    assert_eq!(fall_slows_read, FALL_SLOWS_1024[k]);
    assert_eq!(wrong_below_read, WRONG_BELOW_1024[k]);
    assert_eq!(punished_moves, PUNISHED_MOVES_TOTAL_1024[k]);
    assert_eq!(rewarded_moves, REWARDED_MOVES_TOTAL_1024[k]);
    assert_eq!(new_rise_read, NEW_RISE_PUNISHED_1024[k]);
    assert_eq!(once, ONCE_BLOCKS_PUNISHED_1024[k]);
    assert_eq!(falls, FALLS_PUNISHED_1024[k]);
    assert_eq!(derivation_read, DERIVATION_PUNISHED_1024[k]);
    assert_eq!(
        (sums_after, blocks.last().map(|b| (b.7, b.8))),
        (
            SUMS_AFTER_PUNISHED_1024[k],
            Some(SUMS_AFTER_PUNISHED_1024[k])
        ),
        "{name}: the sums after the run are the last block's"
    );
}

/// H-18's arm that starts from the assignment (brief 041): A onto readout 0 and B onto
/// readout 1 for 1 536 trials, then the mirrored mapping for 3 072, the signed gate set.
#[test]
#[ignore]
fn the_punished_pair_from_the_assignment_at_1024_units_exhaustive() {
    punished_arm(Reversal::AssignmentFirst);
}

/// H-18's arm that starts from the mirrored assignment (brief 041): A onto readout 1 and B
/// onto readout 0 for 1 536 trials, then the assignment for 3 072, the signed gate set.
#[test]
#[ignore]
fn the_punished_pair_from_the_mirrored_assignment_at_1024_units_exhaustive() {
    punished_arm(Reversal::MirroredFirst);
}

/// The gate's test (ADR-0061's class; brief 041): the arms and the constants as ADR-0093 fixed
/// them; the criterion's two clauses at their edges over blocks written by hand, a clause-1
/// failure among them; the assertion's rule; the readings' rules over blocks and trials
/// written by hand; `with_version` on a small image (ADR-0095); and a few trials over a flip
/// on the instrument's network at 1 024 units with the inhibitory baseline set, the signed
/// gate set beside the same run with it unset — the oracle held at every trial inside
/// `earned_run_signed` in both — every trial the same up to the first punishment and the one
/// after it, in which the punished pair moves against its trace under the gate and not
/// without it, and no excitatory synapse outside the pairs the deliveries addressed moves.
/// No whole run, and nothing else added to the gate.
#[test]
fn a_few_trials_over_a_punishment_at_1024_units_and_the_rules_of_the_punished_pair() {
    // The arms and the constants.
    assert_eq!(
        PUNISHED_ARMS,
        [Reversal::AssignmentFirst, Reversal::MirroredFirst]
    );
    assert!(!first_mapping(Reversal::AssignmentFirst) && first_mapping(Reversal::MirroredFirst));
    assert_eq!(
        (PUNISHED_TRIALS, PUNISHED_BLOCKS, FLIP, FLIP_BLOCK),
        (4_608, 72, 1_536, 24)
    );
    assert_eq!(PUNISHED_PREDICTED, None, "ADR-0093 predicts no verdict");
    assert_eq!(
        [
            OLD_FALLS_PREDICTED,
            FALL_SLOWS_PREDICTED,
            WRONG_BELOW_PREDICTED
        ],
        [true; 3],
        "ADR-0093's three predicted readings"
    );
    assert_eq!(SIGNED_GATE_BYTE, 25, "ADR-0094's flag");
    // Every constant of H-18 restated unchanged: ADR-0065's window, trial, seed and gain,
    // ADR-0066's mark and window of the criterion, ADR-0076's stimulus and cancel, ADR-0077's
    // settled candidate, ADR-0080's reward, ADR-0085's two baselines, ADR-0089's flip.
    assert_eq!(
        (WINDOW.from, WINDOW.ticks, TRIAL_TICKS, SEED, GAIN_1024),
        (100, 500, 1 << 14, 27, 0x0001_C000)
    );
    assert_eq!((REWARDED_MIN, LAST_BLOCKS, BLOCK), (80, 2, 64));
    assert_eq!(SHAPE_F46, (2, 0x0001_4000));
    assert_eq!(CANCEL_PICKED_1024, Some(CANCEL_AT_THE_EXTREME));
    assert_eq!((SETTLED, BACKGROUNDS[SETTLED]), (0, 0));
    assert_eq!(INHIBITION_TRIALS, REINFORCED_TRIALS);
    assert_eq!((GATE_BASELINE_Q16, INHIBITORY_BASELINE_Q16), (0, 0x8000));
    assert_eq!(REWARD_Q16, ONE);
    assert_eq!((FLIP, LAST_BEFORE_FLIP), (INHIBITION_TRIALS, 1_535));
    // The criterion at its edges over blocks written by hand: clause 1 reads the two blocks
    // before the flip and nothing else; clause 2 the run's last two and nothing before them,
    // and only in a run of seventy-two blocks; a tie is never counted.
    let blocks_of = |correct: &[u32]| -> Vec<Block> {
        correct
            .iter()
            .map(|&c| {
                (
                    c,
                    0,
                    [[0; 2]; 2],
                    [0; 2],
                    [0; 2],
                    [0; 2],
                    0,
                    0,
                    0,
                    0,
                    [[0; 2]; 2],
                    (BLOCK as u32).saturating_sub(c),
                )
            })
            .collect()
    };
    let run_of = |before: [u32; 2], after: [u32; 2], rest: u32| -> Vec<Block> {
        let mut correct = vec![rest; PUNISHED_BLOCKS];
        correct[FLIP_BLOCK - 2] = before[0];
        correct[FLIP_BLOCK - 1] = before[1];
        correct[PUNISHED_BLOCKS - 2] = after[0];
        correct[PUNISHED_BLOCKS - 1] = after[1];
        blocks_of(&correct)
    };
    let edge = run_of([40, 40], [40, 40], 0);
    assert_eq!((correct_before(&edge), revised_count(&edge)), (80, 80));
    assert_eq!(
        punished([&edge, &edge]),
        Punished {
            learned: [true; 2],
            revised: [true; 2],
            yes: true
        },
        "80 and 80 in both arms: yes"
    );
    let short_after = run_of([40, 40], [40, 39], 64);
    assert_eq!(revised_count(&short_after), 79);
    assert_eq!(
        punished([&edge, &short_after]),
        Punished {
            learned: [true; 2],
            revised: [true, false],
            yes: false
        },
        "79 at the end in one arm: no, whatever the blocks between"
    );
    let short_before = run_of([39, 40], [64, 64], 64);
    assert_eq!(correct_before(&short_before), 79);
    assert_eq!(
        punished([&edge, &short_before]),
        Punished {
            learned: [true, false],
            revised: [true; 2],
            yes: false
        },
        "a clause-1 failure: a no about the signed gate, whatever clause 2 reads"
    );
    assert_eq!(
        correct_before(&run_of([0, 0], [64, 64], 64)),
        0,
        "clause 1 reads no block after the flip"
    );
    assert_eq!(
        revised_count(&run_of([64, 64], [0, 0], 64)),
        0,
        "clause 2 reads no block before the run's last two"
    );
    assert_eq!(
        revised_count(&blocks_of(&[64; 48])),
        0,
        "H-17's length is not H-18's"
    );
    assert_eq!(
        revised_count(&blocks_of(&[64; 71])),
        0,
        "a run short of 4 608"
    );
    assert_eq!(revised_count(&blocks_of(&[64; 73])), 0, "or past it");
    assert_eq!(revised_count(&blocks_of(&[64; 72])), 128);
    // The assertion's rule.
    assert!(punished_held(&Reach::default()));
    assert!(
        punished_held(&Reach {
            excitatory: (1_600, 0),
            inhibitory: (0, 6_000),
        }),
        "the four pairs and the inhibitory synapses move by the rules"
    );
    assert!(!punished_held(&Reach {
        excitatory: (0, 1),
        inhibitory: (0, 0),
    }));
    // The readings' rules over blocks written by hand, the assignment first: A's old answer
    // is readout 0 and its new one readout 1, B's the other way round.
    let mut hand = blocks_of(&[0; PUNISHED_BLOCKS]);
    for (j, b) in hand.iter_mut().enumerate() {
        // A→R0 (old) falls by 100 a block from the flip for eight blocks, by 20 for the
        // next eight, then stays; B→R1 (old) never falls; the wrong pairs of the first half,
        // A→R1 and B→R0, end it below and above the image's.
        let after = j.saturating_add(1).saturating_sub(FLIP_BLOCK) as i64;
        let fall = after
            .min(8)
            .saturating_mul(100)
            .saturating_add(after.saturating_sub(8).clamp(0, 8).saturating_mul(20));
        b.10 = [
            [
                IMAGE_COUPLINGS_1024[0][0].saturating_sub(fall),
                IMAGE_COUPLINGS_1024[0][1].saturating_sub(5),
            ],
            [
                IMAGE_COUPLINGS_1024[1][0].saturating_add(5),
                IMAGE_COUPLINGS_1024[1][1],
            ],
        ];
    }
    let mut earned_hand: Vec<EarnedBlock> = hand
        .iter()
        .map(|_| ([[32, 0, 0], [0, 32, 0]], 0, [[0; 2]; 2], 0, 0))
        .collect();
    // A crosses in the sixteenth block after the flip (index 39); B never.
    earned_hand[FLIP_BLOCK + 15].0[0] = [10, 22, 0];
    assert_eq!(
        crossed_block(&earned_hand, false),
        [Some(FLIP_BLOCK + 15), None]
    );
    assert_eq!(
        crossed_block(&earned_hand[..FLIP_BLOCK], false),
        [None; 2],
        "nothing crosses before the flip"
    );
    let mut tied = earned_hand.clone();
    tied[FLIP_BLOCK + 15].0[0] = [16, 16, 0];
    assert_eq!(
        crossed_block(&tied, false),
        [None; 2],
        "as many selections of each is no crossing"
    );
    assert_eq!(
        crossed_block(&earned_hand, true),
        [Some(FLIP_BLOCK); 2],
        "under the other first mapping the answers swap, and both stimuli already select the new one at the flip"
    );
    assert_eq!(
        span_end(&hand, &earned_hand, false),
        [Some(FLIP_BLOCK + 15), Some(PUNISHED_BLOCKS - 1)]
    );
    assert_eq!(
        span_end(&hand[..FLIP_BLOCK], &earned_hand, false),
        [None; 2]
    );
    assert_eq!(
        old_falls(&hand, &earned_hand, false),
        [true, false],
        "A's old pair fell to its crossing; B's never moved"
    );
    assert_eq!(
        fall_slows(&hand, &earned_hand, false),
        [true, false],
        "A: 800 over the first eight blocks against 160 over the next eight"
    );
    let mut steady = hand.clone();
    for (j, b) in steady.iter_mut().enumerate() {
        let after = j.saturating_add(1).saturating_sub(FLIP_BLOCK) as i64;
        b.10[0][0] = IMAGE_COUPLINGS_1024[0][0].saturating_sub(after.saturating_mul(50));
    }
    assert_eq!(
        (
            old_falls(&steady, &earned_hand, false),
            fall_slows(&steady, &earned_hand, false)
        ),
        ([true, false], [false, false]),
        "a steady fall is a fall and does not slow"
    );
    let mut at_once = earned_hand.clone();
    at_once[FLIP_BLOCK].0[0] = [0, 32, 0];
    assert_eq!(
        fall_slows(&hand, &at_once, false),
        [false, false],
        "a span of one block after the flip cannot read a slowing"
    );
    assert_eq!(
        wrong_below(&hand, false),
        [true, false],
        "A→R1 ended the first half below the image's, B→R0 above it"
    );
    assert_eq!(wrong_below(&hand[..FLIP_BLOCK - 1], false), [false; 2]);
    assert_eq!(
        old_course(&hand, false).first(),
        Some(&[IMAGE_COUPLINGS_1024[0][0], IMAGE_COUPLINGS_1024[1][1]]),
        "the course starts at the flip"
    );
    assert_eq!(
        old_course(&hand, false).len(),
        PUNISHED_BLOCKS - FLIP_BLOCK + 1
    );
    let trial = |stimulus: u8, selection: Option<u8>, reward: i32| -> EarnedTrial {
        (
            stimulus,
            [0; 2],
            selection,
            reward > 0,
            reward,
            [[0; 2]; 2],
            0,
            0,
        )
    };
    let mut read_hand = vec![trial(0, Some(0), ONE); PUNISHED_TRIALS];
    assert_eq!(
        first_new(&read_hand, false),
        [None; 2],
        "no new answer selected"
    );
    read_hand[FLIP - 1] = trial(0, Some(1), ONE.saturating_neg());
    read_hand[FLIP + 5] = trial(1, Some(0), ONE);
    read_hand[FLIP + 9] = trial(0, Some(1), ONE);
    assert_eq!(
        first_new(&read_hand, false),
        [Some(FLIP + 9), Some(FLIP + 5)],
        "the selections before the flip are not read"
    );
    // The moves per block: trial t counts under trial t − 1's reward, in trial t's block.
    let mut moves_hand = vec![([0u32; 3], [0i64; 2]); PUNISHED_TRIALS];
    moves_hand[0] = ([9, 9, 9], [99, -99]);
    moves_hand[FLIP] = ([3, 5, 800], [40, -70]);
    moves_hand[FLIP + 6] = ([1, 0, 0], [7, 0]);
    let blocks_moved = moves_blocks(&read_hand, &moves_hand);
    assert_eq!(blocks_moved.len(), PUNISHED_BLOCKS);
    assert_eq!(
        blocks_moved[0],
        [([0; 3], [0; 2]); 2],
        "the first trial consolidates nothing addressed"
    );
    assert_eq!(
        blocks_moved[FLIP_BLOCK],
        [([1, 0, 0], [7, 0]), ([3, 5, 800], [40, -70])],
        "the 1 537th trial under the 1 536th's punishment, the 1 543rd under the 1 542nd's reward"
    );
    assert_eq!(
        moves_totals(&blocks_moved, 1),
        [([0; 3], [0; 2]), ([3, 5, 800], [40, -70])]
    );
    assert_eq!(
        moves_totals(&blocks_moved, 0),
        [([0; 3], [0; 2]), ([1, 0, 0], [7, 0])]
    );
    let mut withheld = read_hand.clone();
    withheld[FLIP - 1].4 = 0;
    assert_eq!(
        moves_blocks(&withheld, &moves_hand)[FLIP_BLOCK][1],
        ([0; 3], [0; 2]),
        "a trial after no reward counts under neither sign"
    );
    // `with_version` (ADR-0095) on a small image: the current version is the image itself,
    // and another differs from it in the header's magic, version and seal and nowhere else
    // (ADR-0222).
    let small = Image::encode(
        &Executor::<8>::new(Config {
            units: 2,
            blocks: 1,
            ..Config::default()
        })
        .unwrap(),
    )
    .unwrap();
    assert_eq!(
        with_version(&small, MenteionFileHeader::FORMAT_VERSION),
        small
    );
    let older = with_version(&small, 15);
    let apart: Vec<usize> = older
        .iter()
        .zip(small.iter())
        .enumerate()
        .filter(|(_, (a, b))| a != b)
        .map(|(k, _)| k)
        .collect();
    assert!(
        !apart.is_empty()
            && apart
                .iter()
                .all(|&k| (0..12).contains(&k) || (48..56).contains(&k)),
        "only the magic, the version and the seal: {apart:?}"
    );
    assert_eq!(&older[0..8], b"VCORTEX1", "format 15's magic");
    assert_eq!(
        MenteionFileHeader::decode(older[0..64].try_into().unwrap()).version,
        15
    );
    // A few trials over a flip on the instrument's network at 1 024 units, the inhibitory
    // baseline set, the assignment first, flipped before the trial of index `GATE_FLIP`: the
    // signed gate set, and beside it the same network with the gate unset. The oracle is held
    // at every trial inside `earned_run_signed` in both. Up to and including the first
    // punishment the two runs are one run; in the trial after it the punished pair moves
    // against its trace under the gate and stays without it.
    const GATE_FLIP: usize = GATE_TRIALS / 2;
    let p = prior(1024);
    let network = |signed_gate: bool| Config {
        inhibitory_baseline_q16: Some(INHIBITORY_BASELINE_Q16),
        signed_gate,
        ..config(1024, 2, GATE_BASELINE_Q16)
    };
    let mut signed_exec = at_gain(&p, network(true), GAIN_1024);
    assert!(signed_exec.signed_gate());
    let before = weights_of(&signed_exec);
    let (run, signed_moves) = punished_run(
        &mut signed_exec,
        Reversal::AssignmentFirst,
        GATE_TRIALS,
        GATE_FLIP,
        &mut |_, _| {},
    );
    let (blocks, trace, _, read, _) = &run;
    assert!(blocks.is_empty(), "a few trials are no whole block");
    assert_eq!((read.len(), signed_moves.len()), (GATE_TRIALS, GATE_TRIALS));
    let mut plain_exec = at_gain(&p, network(false), GAIN_1024);
    let (plain_run, plain_moves) = earned_run_signed(
        &mut plain_exec,
        Feedback::Answer,
        false,
        1024,
        GATE_TRIALS,
        GATE_BASELINE_Q16,
        Some(GATE_FLIP),
        false,
        &mut |_, _| {},
    );
    let plain = &plain_run.3;
    eprintln!(
        "DUMP punished1024 over a punishment trace {trace:#018x} read {read:?} moves {signed_moves:?} plain {plain:?} plain moves {plain_moves:?}"
    );
    let punished_at = read
        .iter()
        .take(GATE_TRIALS - 1)
        .position(|t| t.4 < 0 && t.2.is_some())
        .expect("a punished selection before the last trial");
    assert_eq!(
        read[..=punished_at],
        plain[..=punished_at],
        "up to the first punishment the two runs are one run"
    );
    let after = punished_at.saturating_add(1);
    let punished_pair = (
        usize::from(read[punished_at].0),
        usize::from(read[punished_at].2.expect("a selection")),
    );
    let (signed_after, plain_after) = (signed_moves[after], plain_moves[after]);
    assert!(
        signed_after.0[0].saturating_add(signed_after.0[1]) > 0,
        "under the gate the punished pair {punished_pair:?} moved in the trial after: {signed_after:?}"
    );
    assert_eq!(
        (plain_after.0[0], plain_after.0[1], plain_after.1),
        (0, 0, [0, 0]),
        "without it the punished pair stayed: {plain_after:?}"
    );
    let transferred = read[after].5[punished_pair.0][punished_pair.1];
    assert_eq!(
        transferred,
        signed_after.1[0].saturating_add(signed_after.1[1]),
        "what the oracle consolidated into the pair is what its synapses moved"
    );
    assert_eq!(plain[after].5[punished_pair.0][punished_pair.1], 0);
    // No excitatory synapse outside the pairs the deliveries addressed moved.
    let addressed: Vec<(usize, usize)> = read
        .iter()
        .take(GATE_TRIALS - 1)
        .filter(|t| t.4 != 0)
        .filter_map(|t| t.2.map(|r| (usize::from(t.0), usize::from(r))))
        .collect();
    let reach = reach_by_polarity(&signed_exec, &before, 1024, &addressed);
    assert_eq!(
        reach.excitatory.1, 0,
        "no excitatory synapse outside the addressed pairs moved: {reach:?}"
    );
    assert!(reach.excitatory.0 > 0, "the addressed pairs moved");
    for (t, r) in read.iter().enumerate() {
        let in_force = t >= GATE_FLIP;
        assert_eq!(
            r.3,
            r.2 == Some(answer_of(r.0, in_force) as u8),
            "trial {t}: correct under the mapping in force"
        );
    }
    let derivation_read = derivation(read);
    assert!(
        derivation_read[0] && derivation_read[1],
        "the signal's course is the rewards' whatever the gate: {derivation_read:?}"
    );
    assert!(
        !derivation_read[2],
        "under the gate a punished pair consolidates, which ADR-0080's third clause excludes"
    );
    // Over the pinned tables: the verdict as written, by the rule committed first; the readings
    // as the constants state; and, block by block, both arms' seventy-two blocks consistent with
    // one another, with the assertion and with the oracle — each coupling after a block the one
    // before it plus what the oracle consolidated into that pair over the block, the excitatory
    // sum the image's plus the four pairs' moves, and what the addressed pairs' synapses moved,
    // trial by trial, what the oracle consolidated.
    let image = QUIET_1024[SETTLED].1;
    let verdict = punished([PUNISHED_BLOCKS_1024[0], PUNISHED_BLOCKS_1024[1]]);
    assert_eq!(verdict, PUNISHED_1024, "the verdict as written");
    assert_eq!(PUNISHED_PREDICTED, None, "and no prediction to hold it to");
    assert_ne!(PUNISHED_IMAGE_CRC_1024, 0);
    assert_ne!(PUNISHED_IMAGE_CRC_1024, PUNISHED_IMAGE_CRC_FORMAT_16_1024);
    for (k, &arm) in PUNISHED_ARMS.iter().enumerate() {
        let blocks = PUNISHED_BLOCKS_1024[k];
        let earned = PUNISHED_EARNED_1024[k];
        let moved = PUNISHED_MOVES_1024[k];
        let first = first_mapping(arm);
        assert_eq!(
            (
                blocks.len(),
                earned.len(),
                moved.len(),
                PUNISHED_COMPOSITIONS_1024[k].len()
            ),
            (
                PUNISHED_BLOCKS,
                PUNISHED_BLOCKS,
                PUNISHED_BLOCKS,
                PUNISHED_BLOCKS
            ),
            "{arm:?}: seventy-two blocks of each"
        );
        assert_ne!(PUNISHED_TRACES_1024[k], 0);
        assert_ne!(PUNISHED_READ_1024[k], 0);
        assert!(!PUNISHED_CENSUS_1024[k].is_empty());
        assert_eq!(
            [correct_before(blocks), revised_count(blocks)],
            CORRECT_PUNISHED_1024[k]
        );
        assert_eq!(
            [
                correct_before(blocks) >= REWARDED_MIN,
                revised_count(blocks) >= REWARDED_MIN
            ],
            [verdict.learned[k], verdict.revised[k]]
        );
        assert_eq!(
            need(blocks, earned),
            NEED_PUNISHED_1024[k],
            "{arm:?}: the need"
        );
        assert_eq!(crossed_block(earned, first), CROSSED_BLOCK_1024[k]);
        assert_eq!(old_falls(blocks, earned, first), OLD_FALLS_1024[k]);
        assert_eq!(fall_slows(blocks, earned, first), FALL_SLOWS_1024[k]);
        assert_eq!(wrong_below(blocks, first), WRONG_BELOW_1024[k]);
        assert_eq!(moves_totals(moved, 1), PUNISHED_MOVES_TOTAL_1024[k]);
        assert_eq!(moves_totals(moved, 0), REWARDED_MOVES_TOTAL_1024[k]);
        assert_eq!(new_rise(blocks, first), NEW_RISE_PUNISHED_1024[k]);
        assert_eq!(falls_every_block(image.0, blocks), FALLS_PUNISHED_1024[k]);
        assert_eq!(
            once_blocks(blocks, PUNISHED_COMPOSITIONS_1024[k]),
            ONCE_BLOCKS_PUNISHED_1024[k]
        );
        assert!(
            punished_held(&REACH_PUNISHED_1024[k]),
            "{arm:?}: the assertion held"
        );
        let last = blocks.last().expect("a block");
        assert_eq!(SUMS_AFTER_PUNISHED_1024[k], (last.7, last.8));
        let mut previous = IMAGE_COUPLINGS_1024;
        for (j, block) in blocks.iter().enumerate() {
            let in_force = first != (j >= FLIP_BLOCK);
            assert_eq!(
                block.1, PUNISHED_BLOCKS_1024[0][j].1,
                "{arm:?} block {j}: the same trials present A in both arms"
            );
            let presented = [block.1, (BLOCK as u32).saturating_sub(block.1)];
            for (s, &n) in presented.iter().enumerate() {
                assert_eq!(
                    earned[j].0[s].iter().sum::<u32>(),
                    n,
                    "{arm:?} block {j}: every presentation of {s} selected or tied"
                );
            }
            assert_eq!(
                block.11,
                earned[j].0[0][2].saturating_add(earned[j].0[1][2]),
                "{arm:?} block {j}: the ties"
            );
            let correct = earned[j].0[0][answer_of(0, in_force)]
                .saturating_add(earned[j].0[1][answer_of(1, in_force)]);
            assert_eq!(
                block.0, correct,
                "{arm:?} block {j}: correct under the mapping in force"
            );
            assert_eq!(
                earned[j].1, correct,
                "{arm:?} block {j}: one reward per correct trial"
            );
            assert!(earned[j].3.abs() <= SIGNAL_END_FIXED_Q16);
            let mut rise = 0i64;
            let mut consolidated = 0i64;
            for &(s, r) in &ALL_PAIRS {
                assert_eq!(
                    block.10[s][r],
                    previous[s][r].saturating_add(earned[j].2[s][r]),
                    "{arm:?} block {j}: {s}→{r} moved by what the oracle consolidated"
                );
                rise =
                    rise.saturating_add(block.10[s][r].saturating_sub(IMAGE_COUPLINGS_1024[s][r]));
                consolidated = consolidated.saturating_add(earned[j].2[s][r]);
            }
            assert_eq!(
                block.8,
                image.1.saturating_add(rise),
                "{arm:?} block {j}: the excitatory sum moved by the four pairs' moves and nothing else"
            );
            let moved_sum = moved[j]
                .iter()
                .flat_map(|m| m.1.iter())
                .fold(0i64, |sum, &a| sum.saturating_add(a));
            assert_eq!(
                moved_sum, consolidated,
                "{arm:?} block {j}: what the addressed synapses moved is what the oracle consolidated"
            );
            previous = block.10;
        }
    }
}

// --------------------- the measurement (brief 041), its tables in inhibition/pins/h18.rs

const PUNISHED_TRACES_1024: [u64; 2] = [0x987e1bcfabe50662, 0x7767c0e1a4be0c88];
const PUNISHED_READ_1024: [u64; 2] = [0xb299ee60cde2ecbd, 0xfafd2eaa5834f3fb];
/// The one signed image every arm of H-18, H-19 and H-20 decodes, its CRC-64. ADR-0114 moved
/// the format from 16 to 17, ADR-0123 from 17 to 18, ADR-0131 from 18 to 19, ADR-0134 from 19 to
/// 20, ADR-0155 from 20 to 21, ADR-0180 from 21 to 22, ADR-0189 from 22 to 23, ADR-0194 from
/// 23 to 24 and ADR-0202 from 24 to 25, so its header's version and seal are not the bytes those
/// arms read; the image as it is now, re-pinned as ADR-0095 re-pinned H-17's (it was
/// `0x766de462f9b77576` at format 17, `0xb5486d72bb9c5818` at 18, the CRC H-21 read,
/// `0xf454ea7d7a7abcc2` at 19, the CRC H-22 read, `0xa1dbd07990c41c41` at 20, the CRC H-23 to
/// H-29 read, `0xe0c757765122f89b` at 21, `0x23e2de661309d5f5` at 22, `0x62fe5969d2ef312f` at 23
/// and `0x88fcaa6fc67494f3` at 24).
/// ADR-0221 moved the format to 26 for the magic alone, and the pin holds the image at 25 since
/// (`pinned_crc`, ADR-0222).
const PUNISHED_IMAGE_CRC_1024: u64 = 0xc9e02d6007927029;
/// The same image with its header's version written back to 16 and the header resealed: the
/// CRC-64 H-18, H-19 and H-20 read (ADR-0096, ADR-0108, ADR-0110), so that every byte of the
/// image but the version and the seal is the image they ran from (ADR-0114, as ADR-0095).
const PUNISHED_IMAGE_CRC_FORMAT_16_1024: u64 = 0x3771636d385191ac;
/// Clause 1's and clause 2's counts per arm, `[before the flip, the run's last 128]`, against
/// `REWARDED_MIN`.
const CORRECT_PUNISHED_1024: [[u32; 2]; 2] = [[128, 128], [128, 128]];
/// The first trial after the flip that earned a reward, per arm, as read.
const FIRST_REWARD_PUNISHED_1024: [Option<usize>; 2] = [Some(1762), Some(1747)];
/// Per arm, per stimulus, the block in which the selection crossed to the new answer.
const CROSSED_BLOCK_1024: [[Option<usize>; 2]; 2] = [[Some(37), Some(41)], [Some(43), Some(39)]];
/// ADR-0093's predicted readings as read, per arm, per stimulus: (a), (b) and (c).
const OLD_FALLS_1024: [[bool; 2]; 2] = [[true, true], [true, true]];
const FALL_SLOWS_1024: [[bool; 2]; 2] = [[true, true], [true, true]];
const WRONG_BELOW_1024: [[bool; 2]; 2] = [[true, true], [true, true]];
/// The new answer's pairs' rise from the flip to the run's end, `[A, B]`, per arm.
const NEW_RISE_PUNISHED_1024: [[i64; 2]; 2] = [[3953274, 3028488], [2674728, 3895398]];
/// The blocks, of seventy-two, in which the stimulus fired once, per arm.
const ONCE_BLOCKS_PUNISHED_1024: [u32; 2] = [72, 72];
/// Whether the inhibitory sum fell in every block of the run, per arm.
const FALLS_PUNISHED_1024: [bool; 2] = [false, false];
/// ADR-0080's derivation as read over each arm's whole run, clause by clause.
const DERIVATION_PUNISHED_1024: [[bool; 3]; 2] = [[true, true, false], [true, true, false]];
/// The arena's sums by polarity after each arm's run, `(inhibitory, excitatory)`.
const SUMS_AFTER_PUNISHED_1024: [(i64, i64); 2] = [(18207853, 224498537), (19024488, 225117757)];

// =================================================================================== H-19

// ------------------------------------------ written before the run (ADR-0106, ADR-0107)

/// H-19's run (ADR-0106): H-18's, 4 608 trials in seventy-two blocks, the flip where H-18's
/// was, before the trial of index 1 536. Neither moves after a rewarded run.
const CRITIC_TRIALS: usize = PUNISHED_TRIALS;
/// The blocks of an H-19 run.
const CRITIC_BLOCKS: usize = PUNISHED_BLOCKS;
const _: () = assert!(CRITIC_TRIALS == 4_608 && CRITIC_BLOCKS == 72 && FLIP == 1_536);

/// The arms of H-19 (ADR-0106): H-18's two, in their order, each its own weekly test — the
/// assignment first and the mirrored first — from H-18's one signed image with the critic set,
/// the flip `Task::mirrored` negated and nothing else, the critic's expectations carried across
/// it.
const CRITIC_ARMS: [Reversal; 2] = PUNISHED_ARMS;

/// The critic's shift (ADR-0106): an expectation moves by a thirty-second of the error, so it
/// forgets over about thirty-two presentations of its stimulus, one block of trials. It does
/// not move after a rewarded run.
const CRITIC_SHIFT: u32 = 5;

/// The critic at the run's start (ADR-0106): both expectations zero.
const CRITIC_AT_START: Critic = Critic::new(CRITIC_SHIFT);

/// ADR-0106 writes no prediction for the verdict.
const CRITIC_PREDICTED: Option<bool> = None;

/// Clause 3's span (ADR-0106): the last four blocks of each mapping, 256 trials — trials 1 281
/// to 1 536 under the first mapping, 4 353 to 4 608 under the second — over which H-18's
/// answer pairs rose by 3.7 to 9.5 per cent of their image couplings.
const SETTLE_BLOCKS: usize = 4;
/// Clause 3's bound (ADR-0106): a move of less than one per cent of the pair's image coupling,
/// read in integers as `|Δ| × SETTLE_PER_CENT < image`.
const SETTLE_PER_CENT: i64 = 100;
const _: () = assert!(SETTLE_BLOCKS * BLOCK == 256 && FLIP_BLOCK >= SETTLE_BLOCKS);
const _: () = assert!(CRITIC_BLOCKS - FLIP_BLOCK >= SETTLE_BLOCKS);

/// ADR-0106's predicted reading (1), a Hypothesis written before the run and never asserted:
/// for both stimuli in both arms, the first mapping's answer pair at the flip stands below
/// H-18's same pair in the same arm at the flip (`below_punished`).
const BELOW_PUNISHED_PREDICTED: bool = true;

/// ADR-0106's predicted reading (2), a Hypothesis written before the run and never asserted:
/// for both stimuli in both arms, the stimulus's expectation is below zero after a trial within
/// `FALLS_WITHIN` trials of the flip, trials 1 537 to 1 600 (`falls_within`). ADR-0106's rule,
/// from an expectation of 1.0 punished at every presentation, says after 22 presentations.
const EXPECTATION_FALLS_PREDICTED: bool = true;
/// The trials from the flip the predicted reading (2) reads.
const FALLS_WITHIN: usize = BLOCK;
const _: () = assert!(FALLS_WITHIN == 64);

/// The signal at or below which a trial's delivery is counted as a strong punishment of the old
/// answer's pair (ADR-0106's reading): −0.5, the modulation the pair starts consolidating under
/// in the next trial, the baseline being zero.
const STRONG_PUNISHMENT_Q16: i32 = -(ONE / 2);

// ------------------------------------------------------------ the criterion (ADR-0106)

/// Clause 3's moves (ADR-0106), per mapping `[first, second]` and per stimulus `[A, B]`: the
/// stimulus's answer pair under that mapping, its coupling at the end of the mapping's last
/// block less its coupling `SETTLE_BLOCKS` blocks before — over trials 1 281 to 1 536 under
/// the first mapping and 4 353 to 4 608 under the second; none for a run of any other length.
fn settle_moves(blocks: &[Block], first: bool) -> Option<[[i64; 2]; 2]> {
    if blocks.len() != CRITIC_BLOCKS {
        return None;
    }
    let ends = [FLIP_BLOCK - 1, CRITIC_BLOCKS - 1];
    let mappings = [first, !first];
    Some([0usize, 1].map(|m| {
        [0usize, 1].map(|s| {
            let answer = answer_of(s as u8, mappings[m]);
            let at = |j: usize| blocks.get(j).map_or(0, |b| b.10[s][answer]);
            at(ends[m]).saturating_sub(at(ends[m].saturating_sub(SETTLE_BLOCKS)))
        })
    }))
}

/// Clause 3 as a rule (ADR-0106): each of the four moves less than one per cent of its pair's
/// image coupling, `|Δ| × 100 < image`, whichever way it moved; false for a run of any other
/// length.
fn settles(blocks: &[Block], first: bool) -> bool {
    let Some(moves) = settle_moves(blocks, first) else {
        return false;
    };
    moves.iter().zip([first, !first]).all(|(pairs, mapping)| {
        pairs.iter().enumerate().all(|(s, &delta)| {
            let image = IMAGE_COUPLINGS_1024[s][answer_of(s as u8, mapping)];
            delta.saturating_abs().saturating_mul(SETTLE_PER_CENT) < image
        })
    })
}

/// H-19's criterion (ADR-0106), clause by clause per arm `[assignment first, mirrored first]`:
/// (1) it learned — `correct_before`, trials 1 409 to 1 536 under the first mapping, at least
/// `REWARDED_MIN`; (2) it revised — `revised_count`, trials 4 481 to 4 608 under the second, at
/// least `REWARDED_MIN`; (3) it settled — `settles`; a tie not correct, the task's count. `yes`
/// is all six; a no names the clause that failed.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct Predicted {
    learned: [bool; 2],
    revised: [bool; 2],
    settled: [bool; 2],
    yes: bool,
}

fn predicted(arms: [&[Block]; 2]) -> Predicted {
    let learned = arms.map(|blocks| correct_before(blocks) >= REWARDED_MIN);
    let revised = arms.map(|blocks| revised_count(blocks) >= REWARDED_MIN);
    let settled = [0usize, 1].map(|k| settles(arms[k], first_mapping(CRITIC_ARMS[k])));
    Predicted {
        learned,
        revised,
        settled,
        yes: learned.iter().chain(&revised).chain(&settled).all(|&c| c),
    }
}

// --------------------------------------------------- the readings' shape (ADR-0106)

/// ADR-0106's predicted reading (1) as a rule: per stimulus, its answer pair under the first
/// mapping at the end of the 1 536th trial below the same pair at the same trial of `punished`,
/// H-18's arm of the same first mapping; false for a run that does not reach the flip.
fn below_punished(blocks: &[Block], punished: &[Block], first: bool) -> [bool; 2] {
    let (Some(here), Some(there)) = (blocks.get(FLIP_BLOCK - 1), punished.get(FLIP_BLOCK - 1))
    else {
        return [false; 2];
    };
    [0usize, 1].map(|s| {
        let answer = answer_of(s as u8, first);
        here.10[s][answer] < there.10[s][answer]
    })
}

/// Per stimulus, the first trial from the flip on, by index, after which its expectation was
/// below zero; none when none was.
fn below_zero(expected: &[[i32; 2]]) -> [Option<usize>; 2] {
    [0usize, 1].map(|s| {
        expected
            .iter()
            .enumerate()
            .skip(FLIP)
            .find(|(_, e)| e[s] < 0)
            .map(|(t, _)| t)
    })
}

/// ADR-0106's predicted reading (2) as a rule: per stimulus, `below_zero` within
/// `FALLS_WITHIN` trials of the flip, before the trial of index `FLIP + FALLS_WITHIN`.
fn falls_within(expected: &[[i32; 2]]) -> [bool; 2] {
    below_zero(expected).map(|t| t.is_some_and(|t| t < FLIP + FALLS_WITHIN))
}

/// Per stimulus, its presentations from the flip up to and including the trial `below_zero`
/// names — ADR-0106's arithmetic says 22 from an expectation of 1.0 punished at every one; none
/// when its expectation never fell below zero. A reading.
fn presentations_to_below(read: &[EarnedTrial], expected: &[[i32; 2]]) -> [Option<u32>; 2] {
    let at = below_zero(expected);
    [0usize, 1].map(|s| {
        at[s].map(|t| {
            read.get(FLIP..=t)
                .unwrap_or(&[])
                .iter()
                .filter(|r| usize::from(r.0) == s)
                .count() as u32
        })
    })
}

/// The punishment's course after the flip (ADR-0106's reading), per block from the flip and
/// per stimulus `[A, B]`: the trials that selected the stimulus's old answer — its answer under
/// the first mapping, an error under the second — and left a signal at or below
/// `STRONG_PUNISHMENT_Q16`, the modulation under which the old answer's pair starts
/// consolidating in the next trial, the baseline being zero. The blocks before the flip are not
/// read.
fn strong_punishments(read: &[EarnedTrial], first: bool) -> Vec<[u32; 2]> {
    read.get(FLIP..)
        .unwrap_or(&[])
        .chunks(BLOCK)
        .map(|block| {
            let mut out = [0u32; 2];
            for t in block {
                let old = answer_of(t.0, first) as u8;
                if t.2 == Some(old) && t.7 <= STRONG_PUNISHMENT_Q16 {
                    let into = &mut out[usize::from(t.0)];
                    *into = into.saturating_add(1);
                }
            }
            out
        })
        .collect()
}

/// `strong_punishments` summed over the blocks, per stimulus.
fn strong_total(blocks: &[[u32; 2]]) -> [u32; 2] {
    blocks.iter().fold([0u32; 2], |sum, b| {
        [sum[0].saturating_add(b[0]), sum[1].saturating_add(b[1])]
    })
}

/// ADR-0107's arithmetic of the punishment's fading with the dopamine signal's carry-over
/// (F-53), from the rules and not a reading: both expectations at 1.0 and the signal at rest,
/// every trial a punished presentation of the stimuli in turn — the course ADR-0106's
/// $delta_n = -2(31/32)^n$ describes — the error each trial delivers (`critic_step`) and the
/// signal it leaves, the error plus what the deliveries before it left, decayed over a trial
/// by the executor's rule (`signal_course`).
fn carried_punishment(trials: usize) -> Vec<(i32, i32)> {
    let mut expected = [ONE; 2];
    let mut signal = 0i32;
    (0..trials)
        .map(|t| {
            let s = t & 1;
            let (error, after) = critic_step(expected[s], ONE.saturating_neg(), CRITIC_SHIFT);
            expected[s] = after;
            signal = signal_end(&signal_course(signal)).saturating_add(error);
            (error, signal)
        })
        .collect()
}

/// Each stimulus's expectation at every block's end, `[A, B]`, from the trials' expectations.
fn expected_blocks(expected: &[[i32; 2]]) -> Vec<[i32; 2]> {
    expected
        .chunks(BLOCK)
        .filter_map(|block| block.last().copied())
        .collect()
}

/// The four couplings after every block as fractions of the image's, in parts per ten
/// thousand, `[stimulus][readout]`: the course the dump reads beside H-18's.
fn couplings_course(blocks: &[Block]) -> Vec<[[i64; 2]; 2]> {
    blocks
        .iter()
        .map(|b| {
            [0usize, 1]
                .map(|s| [0usize, 1].map(|r| per_myriad(b.10[s][r], IMAGE_COUPLINGS_1024[s][r])))
        })
        .collect()
}

// -------------------------- the run (brief 046), its tables in inhibition/pins/h19.rs

/// An arm's run from the signed engine (brief 046): `earned_run_predicted` under the answer's
/// feedback at the gate's zero with the signed gate set, the arm's first mapping, the flip
/// before the trial of index `flip`, the critic given, and `after` reading the executor at
/// every trial's end — the oracle, fed the reward each trial delivered, held to the record at
/// every trial; the task's error and expectations held to the harness's critic; every trial's
/// contract asserted under the mapping in force at it. With no critic it is `punished_run`'s
/// run.
fn critic_run(
    exec: &mut Engine,
    arm: Reversal,
    trials: usize,
    flip: usize,
    critic: Option<Critic>,
    after: &mut dyn FnMut(&Engine, usize),
) -> (EarnedRun, Vec<Moves>, Vec<[i32; 2]>) {
    earned_run_predicted(
        exec,
        Feedback::Answer,
        first_mapping(arm),
        1024,
        trials,
        GATE_BASELINE_Q16,
        Some(flip),
        true,
        critic,
        after,
    )
}

/// One arm of H-19 at 1 024 units (brief 046): the settled engine held to ADR-0077 step by step
/// and its images, the signed image H-18's by its CRC; the calibration before any rewarded run
/// (H-19's stopping rule, step 2) — a frozen block from the zero image, the inhibitory baseline
/// and the signed gate unset, held to ADR-0077's frozen run, and H-18's arm's first block from
/// the signed image with the critic unset, held to H-18's tables; then the arm's 4 608 trials
/// from the signed image with the critic set, the flip between the 1 536th and the 1 537th, the
/// couplings read at the end of the 1 537th; everything dumped and the clauses, the assertion
/// and the readings computed before anything is held; then the assertion, and the pinned
/// tables.
fn critic_arm(arm: Reversal) {
    let k = CRITIC_ARMS
        .iter()
        .position(|&a| a == arm)
        .expect("an arm of H-19");
    let name = format!("critic1024 {arm:?}");
    let (zero, signed) = signed_images(&name);
    let image_crc = pinned_crc(&signed);
    assert_eq!(
        image_crc, PUNISHED_IMAGE_CRC_1024,
        "{name}: H-18's one image"
    );
    assert_eq!(
        crc64(&with_version(&signed, 16)),
        PUNISHED_IMAGE_CRC_FORMAT_16_1024,
        "{name}: every byte but the header's version and seal is the image H-19 read (ADR-0114)"
    );
    {
        let mut frozen = frozen_from(&zero, 1024);
        assert_eq!(
            (frozen.inhibitory_baseline_q16(), frozen.signed_gate()),
            (None, false),
            "{name}: the calibration's image leaves the inhibitory baseline and the signed gate unset"
        );
        let calibration = taught_run(&mut frozen, Arm::Withheld, 1024, BLOCK);
        calibration_holds(&format!("{name} calibration"), &calibration);
    }
    {
        let mut exec = signed_from(&signed, 1024);
        let (run, moves) = punished_run(&mut exec, arm, BLOCK, FLIP, &mut |_, _| {});
        let (blocks, _, trials, read, _) = &run;
        let compositions: Vec<Composition> = trials.chunks(BLOCK).map(composition).collect();
        assert_eq!(
            blocks.as_slice(),
            &PUNISHED_BLOCKS_1024[k][..1],
            "{name}: H-18's first block, the critic unset"
        );
        assert_eq!(
            compositions.as_slice(),
            &PUNISHED_COMPOSITIONS_1024[k][..1],
            "{name}: and its composition"
        );
        assert_eq!(
            earned_blocks(read).as_slice(),
            &PUNISHED_EARNED_1024[k][..1],
            "{name}: and its earned block"
        );
        assert_eq!(
            moves_blocks(read, &moves).as_slice(),
            &PUNISHED_MOVES_1024[k][..1],
            "{name}: and its moves"
        );
        eprintln!(
            "DUMP {name} calibration holds: ADR-0077's settled candidate, H-18's image (crc {image_crc:#018x}) and H-18's first block reproduced"
        );
    }
    let sets = geometry(1024, ROTATION_1024);
    let image_sums = QUIET_1024[SETTLED].1;
    let mut exec = signed_from(&signed, 1024);
    assert_eq!(
        weights_by_polarity(&exec),
        image_sums,
        "{name}: the image's sums"
    );
    assert_eq!(
        pair_couplings(&exec, &sets),
        IMAGE_COUPLINGS_1024,
        "{name}: the same image"
    );
    let image = weights_of(&exec);
    let first = first_mapping(arm);
    let mut at_carry: Option<[[i64; 2]; 2]> = None;
    let (run, moves, expected) = critic_run(
        &mut exec,
        arm,
        CRITIC_TRIALS,
        FLIP,
        Some(CRITIC_AT_START),
        &mut |exec, trial| {
            if trial == FLIP {
                at_carry = Some(pair_couplings(exec, &sets));
            }
        },
    );
    let (blocks, trace, trials, read, volley_ticks) = &run;
    let at_carry = at_carry.expect("the run reached the trial after the flip");
    let earned = earned_blocks(read);
    let compositions: Vec<Composition> = trials.chunks(BLOCK).map(composition).collect();
    let moved = moves_blocks(read, &moves);
    let expected_by_block = expected_blocks(&expected);
    let strong = strong_punishments(read, first);
    assert_eq!(blocks.len(), CRITIC_BLOCKS, "{name}: seventy-two blocks");
    assert_eq!((read.len(), expected.len()), (CRITIC_TRIALS, CRITIC_TRIALS));
    assert_eq!(
        (moved.len(), expected_by_block.len(), strong.len()),
        (CRITIC_BLOCKS, CRITIC_BLOCKS, CRITIC_BLOCKS - FLIP_BLOCK)
    );
    // Everything dumped, and the clauses, the assertion and the readings computed, before
    // anything is held.
    dump_earned(&name, &run, &earned);
    eprintln!("DUMP {name} PIN blocks {blocks:?}");
    eprintln!("DUMP {name} PIN trace {trace:#018x}");
    eprintln!("DUMP {name} PIN compositions {compositions:?}");
    eprintln!("DUMP {name} PIN earned {earned:?}");
    eprintln!("DUMP {name} PIN read {:#018x}", earned_hash(read));
    eprintln!("DUMP {name} PIN census {:?}", census_of(volley_ticks));
    eprintln!("DUMP {name} PIN moves {moved:?}");
    eprintln!("DUMP {name} PIN expected {expected_by_block:?}");
    eprintln!("DUMP {name} PIN strong {strong:?}");
    eprintln!("DUMP {name} PIN carry {at_carry:?}");
    let reach = reach_by_polarity(&exec, &image, 1024, &ALL_PAIRS);
    let correct = [correct_before(blocks), revised_count(blocks)];
    let settle = settle_moves(blocks, first);
    let settled = settles(blocks, first);
    let need_read = need(blocks, &earned);
    let first_rewarded = first_reward(read);
    let first_new_read = first_new(read, first);
    let crossed = crossed_block(&earned, first);
    let below = below_punished(blocks, PUNISHED_BLOCKS_1024[k], first);
    let below_zero_read = below_zero(&expected);
    let within = falls_within(&expected);
    let to_below = presentations_to_below(read, &expected);
    let strong_sum = strong_total(&strong);
    let old_falls_read = old_falls(blocks, &earned, first);
    let fall_slows_read = fall_slows(blocks, &earned, first);
    let wrong_below_read = wrong_below(blocks, first);
    let punished_moves = moves_totals(&moved, 1);
    let rewarded_moves = moves_totals(&moved, 0);
    let new_rise_read = new_rise(blocks, first);
    let once = once_blocks(blocks, &compositions);
    let falls = falls_every_block(image_sums.0, blocks);
    let derivation_read = derivation(read);
    let sums_after = weights_by_polarity(&exec);
    eprintln!(
        "DUMP {name} PIN readings correct {correct:?} settle {settle:?} settled {settled} reach {reach:?} need {need_read:?} first reward {first_rewarded:?} first new {first_new_read:?} crossed {crossed:?} below punished {below:?} (predicted {BELOW_PUNISHED_PREDICTED}) below zero {below_zero_read:?} within {within:?} (predicted {EXPECTATION_FALLS_PREDICTED}) to below {to_below:?} strong total {strong_sum:?} old falls {old_falls_read:?} slows {fall_slows_read:?} wrong below {wrong_below_read:?} punished moves {punished_moves:?} rewarded moves {rewarded_moves:?} new rise {new_rise_read:?} once {once} falls {falls} derivation {derivation_read:?} sums after {sums_after:?} image crc {image_crc:#018x}"
    );
    eprintln!(
        "DUMP {name} couplings course {:?} beside H-18's {:?}",
        couplings_course(blocks),
        couplings_course(PUNISHED_BLOCKS_1024[k])
    );
    eprintln!(
        "DUMP {name} old course {:?} gaps {:?} course {:?} image {image_sums:?} last splits {:?}",
        old_course(blocks, first),
        gaps(blocks, first),
        course(image_sums.0, blocks),
        last_splits(read)
    );
    // The assertion (ADR-0106), after the dump and beside the verdict: H-18's rule.
    assert!(
        punished_held(&reach),
        "{name}: ADR-0106's assertion — no excitatory synapse outside the four stimulus–readout pairs moved: {reach:?}"
    );
    // The pinned tables, and the readings as the constants state.
    pinned(
        &format!("{name} sight"),
        blocks,
        *trace,
        CRITIC_BLOCKS_1024[k],
        CRITIC_TRACES_1024[k],
    );
    assert_eq!(
        compositions.as_slice(),
        CRITIC_COMPOSITIONS_1024[k],
        "{name}: the composition per block"
    );
    assert_eq!(
        earned.as_slice(),
        CRITIC_EARNED_1024[k],
        "{name}: the earned blocks"
    );
    assert_eq!(
        earned_hash(read),
        CRITIC_READ_1024[k],
        "{name}: the readings"
    );
    assert_eq!(
        census_of(volley_ticks),
        CRITIC_CENSUS_1024[k].to_vec(),
        "{name}: the volley's ticks"
    );
    assert_eq!(
        moved.as_slice(),
        CRITIC_MOVES_1024[k],
        "{name}: the moves per block"
    );
    assert_eq!(
        expected_by_block.as_slice(),
        CRITIC_EXPECTED_1024[k],
        "{name}: the expectations per block"
    );
    assert_eq!(
        strong.as_slice(),
        CRITIC_STRONG_1024[k],
        "{name}: the strong punishments per block"
    );
    assert_eq!(at_carry, CRITIC_CARRY_1024[k]);
    assert_eq!(correct, CORRECT_CRITIC_1024[k]);
    assert_eq!(settle, SETTLE_MOVES_1024[k]);
    assert_eq!(settled, SETTLED_1024[k]);
    assert_eq!(reach, REACH_CRITIC_1024[k]);
    assert_eq!(need_read, NEED_CRITIC_1024[k]);
    assert_eq!(first_rewarded, FIRST_REWARD_CRITIC_1024[k]);
    assert_eq!(first_new_read, FIRST_NEW_CRITIC_1024[k]);
    assert_eq!(crossed, CROSSED_CRITIC_1024[k]);
    assert_eq!(below, BELOW_PUNISHED_1024[k]);
    assert_eq!(below_zero_read, BELOW_ZERO_1024[k]);
    assert_eq!(within, FALLS_WITHIN_1024[k]);
    assert_eq!(to_below, TO_BELOW_1024[k]);
    assert_eq!(strong_sum, STRONG_TOTAL_1024[k]);
    assert_eq!(old_falls_read, OLD_FALLS_CRITIC_1024[k]);
    assert_eq!(fall_slows_read, FALL_SLOWS_CRITIC_1024[k]);
    assert_eq!(wrong_below_read, WRONG_BELOW_CRITIC_1024[k]);
    assert_eq!(punished_moves, PUNISHED_MOVES_CRITIC_1024[k]);
    assert_eq!(rewarded_moves, REWARDED_MOVES_CRITIC_1024[k]);
    assert_eq!(new_rise_read, NEW_RISE_CRITIC_1024[k]);
    assert_eq!(once, ONCE_BLOCKS_CRITIC_1024[k]);
    assert_eq!(falls, FALLS_CRITIC_1024[k]);
    assert_eq!(derivation_read, DERIVATION_CRITIC_1024[k]);
    assert_eq!(
        (sums_after, blocks.last().map(|b| (b.7, b.8))),
        (SUMS_AFTER_CRITIC_1024[k], Some(SUMS_AFTER_CRITIC_1024[k])),
        "{name}: the sums after the run are the last block's"
    );
}

/// H-19's arm that starts from the assignment (brief 046): A onto readout 0 and B onto readout
/// 1 for 1 536 trials, then the mirrored mapping for 3 072, the signed gate and the critic set.
#[test]
#[ignore]
fn the_critic_from_the_assignment_at_1024_units_exhaustive() {
    critic_arm(Reversal::AssignmentFirst);
}

/// H-19's arm that starts from the mirrored assignment (brief 046): A onto readout 1 and B onto
/// readout 0 for 1 536 trials, then the assignment for 3 072, the signed gate and the critic
/// set.
#[test]
#[ignore]
fn the_critic_from_the_mirrored_assignment_at_1024_units_exhaustive() {
    critic_arm(Reversal::MirroredFirst);
}

/// The gate's test (ADR-0061's class; brief 046): the arms and the constants as ADR-0106 and
/// ADR-0107 fixed them; the criterion's three clauses at their edges over blocks written by
/// hand, clause 3 at one per cent and one LSB either side, and clause 3 over H-18's pinned
/// tables; the readings' rules over blocks, trials and expectations written by hand; the
/// harness's critic against the task's over the lattice; and a few trials over a flip on the
/// instrument's network at 1 024 units with the inhibitory baseline and the signed gate set,
/// the critic set beside the same trials with it unset — the oracle held at every trial inside
/// `earned_run_predicted` in both, the task's error and expectations held to the harness's
/// critic — where the reward delivered is the error against the expectation, each expectation
/// moves by the error shifted by five, the two runs are one run up to the first trial whose
/// expectation was not zero, and no excitatory synapse outside the pairs the deliveries
/// addressed moves. No whole run, and nothing else added to the gate.
#[test]
fn a_few_trials_under_the_critic_at_1024_units_and_the_rules_of_the_critic() {
    // The arms and the constants.
    assert_eq!(
        CRITIC_ARMS,
        [Reversal::AssignmentFirst, Reversal::MirroredFirst]
    );
    assert_eq!(
        (CRITIC_TRIALS, CRITIC_BLOCKS, FLIP, FLIP_BLOCK),
        (4_608, 72, 1_536, 24)
    );
    assert_eq!(CRITIC_SHIFT, 5, "ADR-0106's shift");
    assert_eq!(
        CRITIC_AT_START,
        Critic {
            expected_q16: [0; 2],
            shift: 5
        },
        "both expectations zero at the start"
    );
    assert_eq!(CRITIC_PREDICTED, None, "ADR-0106 predicts no verdict");
    assert_eq!(
        [BELOW_PUNISHED_PREDICTED, EXPECTATION_FALLS_PREDICTED],
        [true; 2],
        "ADR-0106's two predicted readings"
    );
    assert_eq!((FALLS_WITHIN, STRONG_PUNISHMENT_Q16), (64, -0x8000));
    assert_eq!((SETTLE_BLOCKS, SETTLE_PER_CENT), (4, 100));
    // Every constant of H-19 restated unchanged: ADR-0065's window, trial, seed and gain,
    // ADR-0066's mark and window of the criterion, ADR-0076's stimulus and cancel, ADR-0077's
    // settled candidate, ADR-0080's reward, ADR-0085's two baselines, ADR-0089's flip,
    // ADR-0093's run and arms, ADR-0094's flag and H-18's one image.
    assert_eq!(
        (WINDOW.from, WINDOW.ticks, TRIAL_TICKS, SEED, GAIN_1024),
        (100, 500, 1 << 14, 27, 0x0001_C000)
    );
    assert_eq!((REWARDED_MIN, LAST_BLOCKS, BLOCK), (80, 2, 64));
    assert_eq!(SHAPE_F46, (2, 0x0001_4000));
    assert_eq!(CANCEL_PICKED_1024, Some(CANCEL_AT_THE_EXTREME));
    assert_eq!((SETTLED, BACKGROUNDS[SETTLED]), (0, 0));
    assert_eq!((GATE_BASELINE_Q16, INHIBITORY_BASELINE_Q16), (0, 0x8000));
    assert_eq!(REWARD_Q16, ONE);
    assert_eq!((FLIP, LAST_BEFORE_FLIP), (INHIBITION_TRIALS, 1_535));
    assert_eq!((PUNISHED_TRIALS, PUNISHED_ARMS), (4_608, REVERSAL_ARMS));
    assert_eq!(SIGNED_GATE_BYTE, 25);
    assert_eq!(
        (PUNISHED_IMAGE_CRC_1024, PUNISHED_IMAGE_CRC_FORMAT_16_1024),
        (0xc9e0_2d60_0792_7029, 0x3771_636d_3851_91ac),
        "H-18's image, at format 25 and as read at format 16"
    );
    // The criterion's clauses 1 and 2 at their edges over blocks written by hand, as H-18's.
    let blocks_of = |correct: &[u32]| -> Vec<Block> {
        correct
            .iter()
            .map(|&c| {
                (
                    c,
                    0,
                    [[0; 2]; 2],
                    [0; 2],
                    [0; 2],
                    [0; 2],
                    0,
                    0,
                    0,
                    0,
                    IMAGE_COUPLINGS_1024,
                    (BLOCK as u32).saturating_sub(c),
                )
            })
            .collect()
    };
    let run_of = |before: [u32; 2], after: [u32; 2]| -> Vec<Block> {
        let mut correct = vec![BLOCK as u32; CRITIC_BLOCKS];
        correct[FLIP_BLOCK - 2] = before[0];
        correct[FLIP_BLOCK - 1] = before[1];
        correct[CRITIC_BLOCKS - 2] = after[0];
        correct[CRITIC_BLOCKS - 1] = after[1];
        blocks_of(&correct)
    };
    let edge = run_of([40, 40], [40, 40]);
    assert_eq!((correct_before(&edge), revised_count(&edge)), (80, 80));
    assert_eq!(
        predicted([&edge, &edge]),
        Predicted {
            learned: [true; 2],
            revised: [true; 2],
            settled: [true; 2],
            yes: true
        },
        "80 and 80 in both arms, and no pair moved: yes"
    );
    let short_before = run_of([39, 40], [64, 64]);
    assert_eq!(
        predicted([&edge, &short_before]),
        Predicted {
            learned: [true, false],
            revised: [true; 2],
            settled: [true; 2],
            yes: false
        },
        "79 before the flip in one arm: clause 1 fails there"
    );
    let short_after = run_of([64, 64], [40, 39]);
    assert_eq!(
        predicted([&short_after, &edge]),
        Predicted {
            learned: [true; 2],
            revised: [false, true],
            settled: [true; 2],
            yes: false
        },
        "79 at the end in one arm: clause 2 fails there"
    );
    // Clause 3 at its edges: the four answer pairs, two per mapping, each moved over its span
    // by as much as stays below one per cent of its image coupling, then by one LSB more, up
    // and down, under both first mappings. Only the blocks at a span's two ends are read.
    let settle_run = |first: bool, moves: [[i64; 2]; 2]| -> Vec<Block> {
        let mut blocks = blocks_of(&[BLOCK as u32; CRITIC_BLOCKS]);
        for (m, (end, mapping)) in [(FLIP_BLOCK - 1, first), (CRITIC_BLOCKS - 1, !first)]
            .into_iter()
            .enumerate()
        {
            for s in 0..2usize {
                let answer = answer_of(s as u8, mapping);
                blocks[end].10[s][answer] =
                    IMAGE_COUPLINGS_1024[s][answer].saturating_add(moves[m][s]);
            }
        }
        blocks
    };
    assert_eq!(
        IMAGE_COUPLINGS_1024[0][0]
            .saturating_sub(1)
            .saturating_div(SETTLE_PER_CENT),
        62_495,
        "A→R0's image coupling, 6 249 552: 62 495 is below one per cent of it and 62 496 is not"
    );
    for first in [false, true] {
        let largest = [first, !first].map(|mapping| {
            [0usize, 1].map(|s| {
                IMAGE_COUPLINGS_1024[s][answer_of(s as u8, mapping)]
                    .saturating_sub(1)
                    .saturating_div(SETTLE_PER_CENT)
            })
        });
        let down = largest.map(|m| m.map(|d| d.saturating_neg()));
        assert_eq!(
            settle_moves(&settle_run(first, largest), first),
            Some(largest)
        );
        assert!(
            settles(&settle_run(first, largest), first),
            "{first}: each pair just below one per cent, up"
        );
        assert!(
            settles(&settle_run(first, down), first),
            "{first}: and down"
        );
        assert!(settles(&settle_run(first, [[0; 2]; 2]), first));
        for m in 0..2usize {
            for s in 0..2usize {
                let mut over = largest;
                over[m][s] = over[m][s].saturating_add(1);
                assert!(
                    !settles(&settle_run(first, over), first),
                    "{first} {m} {s}: one LSB past, up"
                );
                let mut under = down;
                under[m][s] = under[m][s].saturating_sub(1);
                assert!(
                    !settles(&settle_run(first, under), first),
                    "{first} {m} {s}: one LSB past, down"
                );
            }
        }
        let mut wrong = settle_run(first, largest);
        for (end, mapping) in [(FLIP_BLOCK - 1, first), (CRITIC_BLOCKS - 1, !first)] {
            for s in 0..2usize {
                let other = answer_of(s as u8, !mapping);
                wrong[end].10[s][other] = wrong[end].10[s][other].saturating_add(1_000_000);
            }
        }
        assert!(
            settles(&wrong, first),
            "{first}: only the answer pairs are read"
        );
        let mut before_span = settle_run(first, largest);
        before_span[FLIP_BLOCK - 1 - SETTLE_BLOCKS - 1].10 = [[0; 2]; 2];
        before_span[CRITIC_BLOCKS - 1 - SETTLE_BLOCKS - 1].10 = [[0; 2]; 2];
        assert!(
            settles(&before_span, first),
            "{first}: nothing before a span's first block is read"
        );
    }
    let over = settle_run(false, [[62_496, 0], [0, 0]]);
    assert_eq!(
        predicted([&over, &settle_run(true, [[0; 2]; 2])]),
        Predicted {
            learned: [true; 2],
            revised: [true; 2],
            settled: [false, true],
            yes: false
        },
        "A→R0 past one per cent in the first arm's first mapping: clause 3 fails there"
    );
    let all = settle_run(false, [[0; 2]; 2]);
    assert_eq!(settle_moves(&all[..CRITIC_BLOCKS - 1], false), None);
    assert!(
        !settles(&all[..CRITIC_BLOCKS - 1], false),
        "a run short of 4 608 does not settle"
    );
    let mut longer = all.clone();
    longer.push(all[0]);
    assert!(!settles(&longer, false), "nor one past it");
    // Clause 3 over H-18's pinned tables: its answer pairs rose over both spans in both arms,
    // by 3.7 to 9.5 per cent of the image's couplings, and it does not settle.
    let h18: Vec<[[i64; 2]; 2]> = (0..2usize)
        .map(|k| {
            let first = first_mapping(PUNISHED_ARMS[k]);
            let moves = settle_moves(PUNISHED_BLOCKS_1024[k], first).expect("seventy-two blocks");
            [first, !first]
                .into_iter()
                .zip(moves)
                .map(|(mapping, pairs)| {
                    [0usize, 1].map(|s| {
                        per_myriad(
                            pairs[s],
                            IMAGE_COUPLINGS_1024[s][answer_of(s as u8, mapping)],
                        )
                    })
                })
                .collect::<Vec<[i64; 2]>>()
                .try_into()
                .expect("two mappings")
        })
        .collect();
    eprintln!("DUMP critic1024 H-18's clause-3 moves, per myriad of the image's: {h18:?}");
    assert_eq!(
        h18, H18_SETTLE_PER_MYRIAD,
        "H-18's moves, as ADR-0106 read them"
    );
    for (k, &arm) in PUNISHED_ARMS.iter().enumerate() {
        assert!(
            !settles(PUNISHED_BLOCKS_1024[k], first_mapping(arm)),
            "{arm:?}: H-18 does not settle"
        );
    }
    assert_eq!(
        predicted([PUNISHED_BLOCKS_1024[0], PUNISHED_BLOCKS_1024[1]]),
        Predicted {
            learned: [true; 2],
            revised: [true; 2],
            settled: [false; 2],
            yes: false
        },
        "H-18's tables read under H-19's rule: learned and revised, and never settled"
    );
    // The readings' rules over blocks, trials and expectations written by hand, the
    // assignment first: A's old answer is readout 0 and its new one readout 1.
    let mut hand = blocks_of(&[BLOCK as u32; CRITIC_BLOCKS]);
    let mut there = hand.clone();
    hand[FLIP_BLOCK - 1].10[0][0] = IMAGE_COUPLINGS_1024[0][0].saturating_add(10);
    there[FLIP_BLOCK - 1].10[0][0] = IMAGE_COUPLINGS_1024[0][0].saturating_add(11);
    hand[FLIP_BLOCK - 1].10[1][1] = IMAGE_COUPLINGS_1024[1][1].saturating_add(11);
    there[FLIP_BLOCK - 1].10[1][1] = IMAGE_COUPLINGS_1024[1][1].saturating_add(11);
    assert_eq!(
        below_punished(&hand, &there, false),
        [true, false],
        "A's pair below H-18's by one; B's level with it, which is not below"
    );
    assert_eq!(
        below_punished(&hand, &there, true),
        [false; 2],
        "the other mapping's pairs are level"
    );
    assert_eq!(
        below_punished(&hand[..FLIP_BLOCK - 1], &there, false),
        [false; 2]
    );
    let mut expected_hand = vec![[ONE, ONE]; CRITIC_TRIALS];
    assert_eq!(below_zero(&expected_hand), [None; 2]);
    assert_eq!(falls_within(&expected_hand), [false; 2]);
    expected_hand[FLIP - 1] = [-1, -1];
    assert_eq!(
        below_zero(&expected_hand),
        [None; 2],
        "below zero before the flip is not read"
    );
    expected_hand[FLIP + FALLS_WITHIN - 1][0] = -1;
    expected_hand[FLIP + FALLS_WITHIN][1] = -1;
    assert_eq!(
        below_zero(&expected_hand),
        [Some(FLIP + FALLS_WITHIN - 1), Some(FLIP + FALLS_WITHIN)]
    );
    assert_eq!(
        falls_within(&expected_hand),
        [true, false],
        "the 1 600th trial is within 64 of the flip and the 1 601st is not"
    );
    expected_hand[FLIP + 3][1] = 0;
    assert_eq!(
        below_zero(&expected_hand)[1],
        Some(FLIP + FALLS_WITHIN),
        "zero is not below zero"
    );
    let trial = |stimulus: u8, selection: Option<u8>, signal: i32| -> EarnedTrial {
        (
            stimulus,
            [0; 2],
            selection,
            false,
            -ONE,
            [[0; 2]; 2],
            0,
            signal,
        )
    };
    let mut read_hand = vec![trial(0, Some(1), ONE); CRITIC_TRIALS];
    for t in read_hand.iter_mut().skip(FLIP).step_by(2) {
        t.0 = 1;
        t.2 = Some(0);
    }
    assert_eq!(
        presentations_to_below(&read_hand, &expected_hand),
        [Some(32), Some(33)],
        "A at the odd trials after the flip, B at the even: 32 of A up to the 1 600th, 33 of B up to the 1 601st"
    );
    read_hand[FLIP - 1] = trial(0, Some(0), -ONE);
    read_hand[FLIP] = trial(0, Some(0), STRONG_PUNISHMENT_Q16);
    read_hand[FLIP + 1] = trial(0, Some(0), STRONG_PUNISHMENT_Q16.saturating_add(1));
    read_hand[FLIP + 2] = trial(1, Some(1), -ONE);
    read_hand[FLIP + 3] = trial(1, Some(0), -ONE);
    read_hand[FLIP + BLOCK] = trial(0, Some(0), i32::MIN);
    read_hand[CRITIC_TRIALS - 1] = trial(1, Some(1), -ONE);
    let strong = strong_punishments(&read_hand, false);
    assert_eq!(strong.len(), CRITIC_BLOCKS - FLIP_BLOCK);
    assert_eq!(
        strong[0],
        [1, 1],
        "the 1 537th's old answer at −0.5 counted, the 1 538th's one LSB above not, B's old answer at −1.0 counted and its new answer not, the 1 536th not read"
    );
    assert_eq!(strong[1], [1, 0]);
    assert_eq!(strong[CRITIC_BLOCKS - FLIP_BLOCK - 1], [0, 1]);
    assert_eq!(strong_total(&strong), [2, 2]);
    assert_eq!(
        strong_punishments(&read_hand, true)[0],
        [0, 1],
        "under the other first mapping the old answers are the other readouts: B's readout 0 at −1.0, the 1 540th"
    );
    assert_eq!(
        strong_punishments(&read_hand[..FLIP], false),
        Vec::<[u32; 2]>::new()
    );
    let mut ramp: Vec<[i32; 2]> = Vec::new();
    for t in 0..(3 * BLOCK) {
        ramp.push([t as i32, (t as i32).saturating_neg()]);
    }
    assert_eq!(
        expected_blocks(&ramp),
        vec![[63, -63], [127, -127], [191, -191]],
        "each block's last trial"
    );
    assert_eq!(
        couplings_course(&hand[..1]),
        vec![[[10_000; 2]; 2]],
        "the image's couplings are ten thousand parts of themselves"
    );
    // ADR-0107's arithmetic of the fading with the carry-over (F-53): the error alone is at or
    // below −1.0 for 22 presentations of each stimulus, as ADR-0106 wrote; the signal a delivery
    // leaves, the carry-over counted, for 42 of each and at or below −0.5 for 133 trials; the
    // full punishment summed about 68 presentations' worth of each stimulus where the error
    // alone is about 54. A signal of −2.0 ends the next trial at −0.820.
    let carried = carried_punishment(400);
    let count = |pick: &dyn Fn(&(i32, i32)) -> bool| carried.iter().filter(|c| pick(c)).count();
    let worth = |of: &dyn Fn(&(i32, i32)) -> i32| {
        carried
            .iter()
            .fold(0i64, |sum, c| {
                sum.saturating_add(i64::from(of(c).clamp(-ONE, 0)))
            })
            .saturating_neg()
            .saturating_div(i64::from(ONE).saturating_mul(2))
    };
    let summary = (
        count(&|c| c.0 <= -ONE),
        count(&|c| c.1 <= -ONE),
        count(&|c| c.1 <= STRONG_PUNISHMENT_Q16),
        worth(&|c| c.0),
        worth(&|c| c.1),
        signal_end(&signal_course(-2 * ONE)),
    );
    eprintln!("DUMP critic1024 the carried punishment {summary:?}");
    assert_eq!(
        summary, CARRIED_PUNISHMENT,
        "(trials the error alone is at or below −1.0, the signal is, the signal at or below −0.5, presentations' worth of each stimulus by the error alone and by the signal, the end of a trial from −2.0)"
    );
    // The harness's critic, `div_euclid` in `i64`, against the task's, a shift saturating in
    // `i32`, over the lattice: one rule, written twice.
    for &expected in I32_LATTICE.iter() {
        for &reward in I32_LATTICE.iter() {
            for shift in [0, 1, 5, 30, 31, 32, u32::MAX] {
                let mut c = Critic {
                    expected_q16: [expected, 0],
                    shift,
                };
                let (error, before, after) = c.predict(0, reward);
                assert_eq!(
                    (error, after),
                    critic_step(expected, reward, shift),
                    "{expected} {reward} {shift}"
                );
                assert_eq!(before, expected);
            }
        }
    }
    // A few trials over a flip on the instrument's network at 1 024 units, the inhibitory
    // baseline and the signed gate set, the assignment first, flipped before the trial of index
    // `GATE_FLIP`: the critic set, and beside it the same network with the critic unset. The
    // oracle is held at every trial inside `earned_run_predicted` in both, and the task's error
    // and expectations to the harness's critic in the first.
    const GATE_FLIP: usize = GATE_TRIALS / 2;
    let p = prior(1024);
    let network = Config {
        inhibitory_baseline_q16: Some(INHIBITORY_BASELINE_Q16),
        signed_gate: true,
        ..config(1024, 2, GATE_BASELINE_Q16)
    };
    let mut critic_exec = at_gain(&p, network.clone(), GAIN_1024);
    let before = weights_of(&critic_exec);
    let (run, _, expected) = critic_run(
        &mut critic_exec,
        Reversal::AssignmentFirst,
        GATE_TRIALS,
        GATE_FLIP,
        Some(CRITIC_AT_START),
        &mut |_, _| {},
    );
    let (blocks, trace, _, read, _) = &run;
    assert!(blocks.is_empty(), "a few trials are no whole block");
    assert_eq!((read.len(), expected.len()), (GATE_TRIALS, GATE_TRIALS));
    let mut plain_exec = at_gain(&p, network, GAIN_1024);
    let (plain_run, _) = punished_run(
        &mut plain_exec,
        Reversal::AssignmentFirst,
        GATE_TRIALS,
        GATE_FLIP,
        &mut |_, _| {},
    );
    let plain = &plain_run.3;
    eprintln!(
        "DUMP critic1024 a few trials trace {trace:#018x} read {read:?} expected {expected:?} plain {plain:?}"
    );
    // By hand: the outcome's reward, ±1.0 by whether the trial was correct under the mapping in
    // force (a tie not); the reward delivered the error against the expectation before; the
    // expectation moved by the error shifted by five, the other stimulus's unmoved.
    let mut held = [0i32; 2];
    let mut first_moved: Option<usize> = None;
    for (t, r) in read.iter().enumerate() {
        let s = usize::from(r.0);
        let in_force = t >= GATE_FLIP;
        assert_eq!(
            r.3,
            r.2 == Some(answer_of(r.0, in_force) as u8),
            "trial {t}: correct under the mapping in force"
        );
        let outcome = if r.3 { ONE } else { -ONE };
        let error = outcome.saturating_sub(held[s]);
        assert_eq!(r.4, error, "trial {t}: the reward delivered is the error");
        if first_moved.is_none() && held[s] != 0 {
            first_moved = Some(t);
        }
        held[s] = held[s].saturating_add(error >> CRITIC_SHIFT);
        assert_eq!(
            expected[t], held,
            "trial {t}: the expectation moved by the error shifted by five"
        );
    }
    let diverged = first_moved.expect("a stimulus presented twice in eight trials");
    assert_eq!(
        read[..diverged],
        plain[..diverged],
        "up to the first trial whose expectation was not zero the two runs are one run"
    );
    let (c, u) = (&read[diverged], &plain[diverged]);
    assert_eq!(
        (c.0, c.1, c.2, c.3),
        (u.0, u.1, u.2, u.3),
        "the trial there is the same trial"
    );
    assert_ne!(
        c.4, u.4,
        "and its reward is not: the critic's error, not the outcome's"
    );
    // No excitatory synapse outside the pairs the deliveries addressed moved: a delivery
    // addresses the selected pair whatever the error, the signal it consolidates under being
    // the error plus what the last delivery left.
    let addressed: Vec<(usize, usize)> = read
        .iter()
        .take(GATE_TRIALS - 1)
        .filter_map(|t| t.2.map(|r| (usize::from(t.0), usize::from(r))))
        .collect();
    let reach = reach_by_polarity(&critic_exec, &before, 1024, &addressed);
    assert_eq!(
        reach.excitatory.1, 0,
        "no excitatory synapse outside the addressed pairs moved: {reach:?}"
    );
    assert!(reach.excitatory.0 > 0, "the addressed pairs moved");
    // Over the pinned tables: the verdict as written, by the rule committed first; the readings
    // as the constants state; and, block by block, both arms' seventy-two blocks consistent with
    // one another, with H-18's trials, with the assertion and with the oracle — each coupling
    // after a block the one before it plus what the oracle consolidated into that pair over the
    // block, the excitatory sum the image's plus the four pairs' moves, what the addressed pairs'
    // synapses moved what the oracle consolidated, and each expectation within the reward.
    let image = QUIET_1024[SETTLED].1;
    let verdict = predicted([CRITIC_BLOCKS_1024[0], CRITIC_BLOCKS_1024[1]]);
    assert_eq!(verdict, CRITIC_1024, "the verdict as written");
    assert_eq!(CRITIC_PREDICTED, None, "and no prediction to hold it to");
    for (k, &arm) in CRITIC_ARMS.iter().enumerate() {
        let blocks = CRITIC_BLOCKS_1024[k];
        let earned = CRITIC_EARNED_1024[k];
        let moved = CRITIC_MOVES_1024[k];
        let first = first_mapping(arm);
        assert_eq!(
            (
                blocks.len(),
                earned.len(),
                moved.len(),
                CRITIC_COMPOSITIONS_1024[k].len(),
                CRITIC_EXPECTED_1024[k].len(),
                CRITIC_STRONG_1024[k].len()
            ),
            (
                CRITIC_BLOCKS,
                CRITIC_BLOCKS,
                CRITIC_BLOCKS,
                CRITIC_BLOCKS,
                CRITIC_BLOCKS,
                CRITIC_BLOCKS - FLIP_BLOCK
            ),
            "{arm:?}: seventy-two blocks of each, forty-eight after the flip"
        );
        assert_ne!(CRITIC_TRACES_1024[k], 0);
        assert_ne!(CRITIC_READ_1024[k], 0);
        assert!(!CRITIC_CENSUS_1024[k].is_empty());
        assert_eq!(
            [correct_before(blocks), revised_count(blocks)],
            CORRECT_CRITIC_1024[k]
        );
        assert_eq!(
            [
                correct_before(blocks) >= REWARDED_MIN,
                revised_count(blocks) >= REWARDED_MIN,
                settles(blocks, first)
            ],
            [verdict.learned[k], verdict.revised[k], verdict.settled[k]]
        );
        assert_eq!(settle_moves(blocks, first), SETTLE_MOVES_1024[k]);
        assert_eq!(settles(blocks, first), SETTLED_1024[k]);
        assert_eq!(
            need(blocks, earned),
            NEED_CRITIC_1024[k],
            "{arm:?}: the need"
        );
        assert_eq!(crossed_block(earned, first), CROSSED_CRITIC_1024[k]);
        assert_eq!(
            below_punished(blocks, PUNISHED_BLOCKS_1024[k], first),
            BELOW_PUNISHED_1024[k]
        );
        assert_eq!(strong_total(CRITIC_STRONG_1024[k]), STRONG_TOTAL_1024[k]);
        assert_eq!(old_falls(blocks, earned, first), OLD_FALLS_CRITIC_1024[k]);
        assert_eq!(fall_slows(blocks, earned, first), FALL_SLOWS_CRITIC_1024[k]);
        assert_eq!(wrong_below(blocks, first), WRONG_BELOW_CRITIC_1024[k]);
        assert_eq!(moves_totals(moved, 1), PUNISHED_MOVES_CRITIC_1024[k]);
        assert_eq!(moves_totals(moved, 0), REWARDED_MOVES_CRITIC_1024[k]);
        assert_eq!(new_rise(blocks, first), NEW_RISE_CRITIC_1024[k]);
        assert_eq!(falls_every_block(image.0, blocks), FALLS_CRITIC_1024[k]);
        assert_eq!(
            once_blocks(blocks, CRITIC_COMPOSITIONS_1024[k]),
            ONCE_BLOCKS_CRITIC_1024[k]
        );
        assert!(
            punished_held(&REACH_CRITIC_1024[k]),
            "{arm:?}: the assertion held"
        );
        let last = blocks.last().expect("a block");
        assert_eq!(SUMS_AFTER_CRITIC_1024[k], (last.7, last.8));
        for (j, e) in CRITIC_EXPECTED_1024[k].iter().enumerate() {
            assert!(
                e.iter().all(|v| v.unsigned_abs() <= ONE.unsigned_abs()),
                "{arm:?} block {j}: each expectation within the reward: {e:?}"
            );
        }
        let mut previous = IMAGE_COUPLINGS_1024;
        for (j, block) in blocks.iter().enumerate() {
            let in_force = first != (j >= FLIP_BLOCK);
            assert_eq!(
                (block.1, block.1),
                (CRITIC_BLOCKS_1024[0][j].1, PUNISHED_BLOCKS_1024[0][j].1),
                "{arm:?} block {j}: the same trials present A in both arms and in H-18's"
            );
            let presented = [block.1, (BLOCK as u32).saturating_sub(block.1)];
            for (s, &n) in presented.iter().enumerate() {
                assert_eq!(
                    earned[j].0[s].iter().sum::<u32>(),
                    n,
                    "{arm:?} block {j}: every presentation of {s} selected or tied"
                );
            }
            assert_eq!(
                block.11,
                earned[j].0[0][2].saturating_add(earned[j].0[1][2]),
                "{arm:?} block {j}: the ties"
            );
            let correct = earned[j].0[0][answer_of(0, in_force)]
                .saturating_add(earned[j].0[1][answer_of(1, in_force)]);
            assert_eq!(
                block.0, correct,
                "{arm:?} block {j}: correct under the mapping in force"
            );
            assert_eq!(
                earned[j].1, correct,
                "{arm:?} block {j}: an error above zero on every correct trial and on no other, the expectation below 1.0"
            );
            let mut rise = 0i64;
            let mut consolidated = 0i64;
            for &(s, r) in &ALL_PAIRS {
                assert_eq!(
                    block.10[s][r],
                    previous[s][r].saturating_add(earned[j].2[s][r]),
                    "{arm:?} block {j}: {s}→{r} moved by what the oracle consolidated"
                );
                rise =
                    rise.saturating_add(block.10[s][r].saturating_sub(IMAGE_COUPLINGS_1024[s][r]));
                consolidated = consolidated.saturating_add(earned[j].2[s][r]);
            }
            assert_eq!(
                block.8,
                image.1.saturating_add(rise),
                "{arm:?} block {j}: the excitatory sum moved by the four pairs' moves and nothing else"
            );
            let moved_sum = moved[j]
                .iter()
                .flat_map(|m| m.1.iter())
                .fold(0i64, |sum, &a| sum.saturating_add(a));
            assert_eq!(
                moved_sum, consolidated,
                "{arm:?} block {j}: what the addressed synapses moved is what the oracle consolidated"
            );
            previous = block.10;
        }
    }
}

/// ADR-0107's arithmetic of the fading with the carry-over (F-53), by `carried_punishment` over
/// 400 trials: the trials whose error alone is at or below −1.0 (44, ADR-0106's 22
/// presentations of each stimulus), whose signal is (84, 42 of each) and whose signal is at or
/// below −0.5; the full punishment summed in presentations of each stimulus by the error alone
/// (53, truncated: ADR-0106's about 54) and by the signal (68); and a signal of −2.0 at the end
/// of a trial, −0.820.
const CARRIED_PUNISHMENT: (usize, usize, usize, i64, i64, i32) = (44, 84, 133, 53, 68, -53_714);

// --------------------- the measurement (brief 046), its tables in inhibition/pins/h19.rs

const CRITIC_TRACES_1024: [u64; 2] = [0x994424537f5461cc, 0x286698c2385a3ee8];
const CRITIC_READ_1024: [u64; 2] = [0x95f37c43af259777, 0xe3ed3b2b426c3c16];
/// Clause 1's and clause 2's counts per arm, `[before the flip, the run's last 128]`, against
/// `REWARDED_MIN`.
const CORRECT_CRITIC_1024: [[u32; 2]; 2] = [[122, 119], [125, 121]];
const SETTLED_1024: [bool; 2] = [false, false];
/// The first trial after the flip that earned a reward, per arm.
const FIRST_REWARD_CRITIC_1024: [Option<usize>; 2] = [Some(1549), Some(1539)];
const CROSSED_CRITIC_1024: [[Option<usize>; 2]; 2] = [[Some(37), Some(41)], [Some(46), Some(39)]];
/// ADR-0106's predicted readings as read, per arm, per stimulus: (1) below H-18's at the
/// flip; (2) the expectation below zero within 64 trials of the flip, with the trial and the
/// presentations it took.
const BELOW_PUNISHED_1024: [[bool; 2]; 2] = [[true, true], [true, true]];
const FALLS_WITHIN_1024: [[bool; 2]; 2] = [[true, true], [true, true]];
const TO_BELOW_1024: [[Option<u32>; 2]; 2] = [[Some(20), Some(24)], [Some(24), Some(23)]];
/// The strong punishments of the old answer after the flip, summed, `[A, B]`, per arm.
const STRONG_TOTAL_1024: [[u32; 2]; 2] = [[253, 324], [277, 278]];
/// ADR-0093's readings (a), (b) and (c), read again under the critic, per arm, per stimulus.
const OLD_FALLS_CRITIC_1024: [[bool; 2]; 2] = [[true, true], [true, true]];
const FALL_SLOWS_CRITIC_1024: [[bool; 2]; 2] = [[true, true], [true, true]];
const WRONG_BELOW_CRITIC_1024: [[bool; 2]; 2] = [[true, true], [true, true]];
/// The new answer's pairs' rise from the flip to the run's end, `[A, B]`, per arm.
const NEW_RISE_CRITIC_1024: [[i64; 2]; 2] = [[1364621, 1088203], [1241644, 1394126]];
/// The blocks, of seventy-two, in which the stimulus fired once, per arm.
const ONCE_BLOCKS_CRITIC_1024: [u32; 2] = [72, 72];
/// Whether the inhibitory sum fell in every block of the run, per arm.
const FALLS_CRITIC_1024: [bool; 2] = [true, true];
/// ADR-0080's derivation as read over each arm's whole run, clause by clause.
const DERIVATION_CRITIC_1024: [[bool; 3]; 2] = [[false, false, false], [false, false, false]];
/// The arena's sums by polarity after each arm's run, `(inhibitory, excitatory)`.
const SUMS_AFTER_CRITIC_1024: [(i64, i64); 2] = [(15797137, 219204113), (16232844, 220081559)];

// ------------------------------------------------- written before the run (ADR-0109)

/// H-20's run (ADR-0109): 7 680 trials in 120 blocks, five of H-16's runs. It does not move
/// after a rewarded run.
const SCHEDULE_TRIALS: usize = 5 * INHIBITION_TRIALS;
/// The blocks of an H-20 run.
const SCHEDULE_BLOCKS: usize = SCHEDULE_TRIALS / BLOCK;
const _: () = assert!(SCHEDULE_TRIALS == 7_680 && SCHEDULE_BLOCKS == 120);

/// Each mapping after the first (ADR-0109): 2 048 trials, thirty-two blocks, where H-19's
/// selection passed 40 of 64 in a block 19 and 23 blocks after its flip.
const LATER_MAPPING_TRIALS: usize = 2_048;
const _: () = assert!(LATER_MAPPING_TRIALS == 32 * BLOCK);

/// The schedule (ADR-0109): the flips before the trials of index 1 536, 3 584 and 5 632, so
/// the mapping flips between the 1 536th trial and the 1 537th, the 3 584th and the 3 585th,
/// and the 5 632nd and the 5 633rd. The first is H-19's `FLIP`. None moves after a rewarded
/// run.
const SCHEDULE_FLIPS: [usize; 3] = [
    FLIP,
    FLIP + LATER_MAPPING_TRIALS,
    FLIP + 2 * LATER_MAPPING_TRIALS,
];
const _: () = assert!(
    SCHEDULE_FLIPS[0] == 1_536
        && SCHEDULE_FLIPS[1] == 3_584
        && SCHEDULE_FLIPS[2] == 5_632
        && SCHEDULE_FLIPS[2] + LATER_MAPPING_TRIALS == SCHEDULE_TRIALS
);

/// The four mappings' trials, `[first, end)` by index: the first 1 536 trials long, each later
/// one 2 048.
const SPANS: [(usize, usize); 4] = [
    (0, SCHEDULE_FLIPS[0]),
    (SCHEDULE_FLIPS[0], SCHEDULE_FLIPS[1]),
    (SCHEDULE_FLIPS[1], SCHEDULE_FLIPS[2]),
    (SCHEDULE_FLIPS[2], SCHEDULE_TRIALS),
];

/// The four mappings' blocks, `[first, end)` by index: 0 to 24, 24 to 56, 56 to 88 and 88 to
/// 120. Every flip falls between two blocks, so every block lies under one mapping.
const MAPPINGS: [(usize, usize); 4] = [
    (SPANS[0].0 / BLOCK, SPANS[0].1 / BLOCK),
    (SPANS[1].0 / BLOCK, SPANS[1].1 / BLOCK),
    (SPANS[2].0 / BLOCK, SPANS[2].1 / BLOCK),
    (SPANS[3].0 / BLOCK, SPANS[3].1 / BLOCK),
];
const _: () = assert!(
    SCHEDULE_FLIPS[0] % BLOCK == 0
        && SCHEDULE_FLIPS[1] % BLOCK == 0
        && SCHEDULE_FLIPS[2] % BLOCK == 0
        && MAPPINGS[0].1 == FLIP_BLOCK
        && MAPPINGS[1].1 == 56
        && MAPPINGS[2].1 == 88
        && MAPPINGS[3].1 == SCHEDULE_BLOCKS
);

/// The blocks H-20 holds to H-19's (ADR-0109): the first 56, every trial before the second
/// flip — the same image, critic and trials, so H-19's arm's bit for bit — and of them the 32
/// from the first flip, from which the strong punishments are read.
const REPLICATED_BLOCKS: usize = MAPPINGS[1].1;
const REPLICATED_AFTER_FLIP: usize = REPLICATED_BLOCKS - FLIP_BLOCK;
const _: () = assert!(
    REPLICATED_BLOCKS == 56 && REPLICATED_AFTER_FLIP == 32 && REPLICATED_BLOCKS <= CRITIC_BLOCKS
);

/// The arms of H-20 (ADR-0109): H-19's two, in their order, each its own weekly test — the
/// assignment first and the mirrored first — from H-19's image, H-18's signed image, with
/// H-19's critic at the start; at each flip `Task::mirrored` negated and nothing else, the
/// critic's expectations carried across it.
const SCHEDULE_ARMS: [Reversal; 2] = CRITIC_ARMS;

/// ADR-0109 writes no prediction for the verdict.
const SCHEDULE_PREDICTED: Option<bool> = None;

/// Clause 2's bound (ADR-0109): every stimulus–readout coupling at or below 1.30 of its image
/// coupling at the end of every block, read in integers as `coupling × 100 ≤ image × 130`.
const BOUND_PER_CENT: i64 = 130;

/// ADR-0109's predicted reading (1), a Hypothesis written before the run and never asserted:
/// after each of the three flips, each stimulus selects its new answer within `NEW_WITHIN`
/// trials of the flip (`new_within`). After H-19's flip each did so within 3 to 68.
const NEW_WITHIN_PREDICTED: bool = true;
/// The trials from a flip the predicted reading (1) reads: 128, trials 1 537 to 1 664 after
/// the first flip.
const NEW_WITHIN: usize = 2 * BLOCK;
const _: () = assert!(NEW_WITHIN == 128);

/// ADR-0109's predicted reading (2), a Hypothesis written before the run and never asserted:
/// each mapping's first `EDGE_BLOCKS` blocks — for the first mapping its first four, for a
/// later one the four after its flip — hold fewer correct trials than its last four
/// (`later_better`).
const LATER_BETTER_PREDICTED: bool = true;
/// The blocks at each end of a mapping the predicted reading (2) reads.
const EDGE_BLOCKS: usize = 4;
const _: () =
    assert!(2 * EDGE_BLOCKS <= FLIP_BLOCK && 2 * EDGE_BLOCKS * BLOCK <= LATER_MAPPING_TRIALS);

// ------------------------------------------------------------ the criterion (ADR-0109)

/// Whether the mapping in force over the block of index `j`, in an arm whose first mapping is
/// `first`, is mirrored: `first` where the schedule has flipped an even number of times by the
/// block's first trial, the other where an odd number (`flipped_at`, the harness's rule).
fn mirrored_at(first: bool, j: usize) -> bool {
    first != flipped_at(&SCHEDULE_FLIPS, j.saturating_mul(BLOCK))
}

/// Clause 1's counts (ADR-0109), per mapping: the correct selections over its last
/// `LAST_BLOCKS` blocks under it — trials 1 409 to 1 536, 3 457 to 3 584, 5 505 to 5 632 and
/// 7 553 to 7 680 — a tie not correct, the task's count; zeros for a run of any other length.
fn mapping_correct(blocks: &[Block]) -> [u32; 4] {
    if blocks.len() != SCHEDULE_BLOCKS {
        return [0; 4];
    }
    MAPPINGS.map(|(_, end)| blocks.get(..end).map_or(0, last_correct))
}

/// Clause 2's rule for one coupling: above 1.30 of its image coupling,
/// `coupling × 100 > image × 130`.
fn over_bound(coupling: i64, image: i64) -> bool {
    coupling.saturating_mul(100) > image.saturating_mul(BOUND_PER_CENT)
}

/// Clause 2's reading (ADR-0109): the first block, by index, at whose end a stimulus–readout
/// coupling stood above 1.30 of its image coupling, with that pair, `(block, stimulus,
/// readout)` — the first in `ALL_PAIRS`'s order where two did at once; none when no coupling
/// did at any block's end.
fn first_over(blocks: &[Block]) -> Option<(usize, usize, usize)> {
    first_over_of(&IMAGE_COUPLINGS_1024, blocks)
}

/// `first_over` against the image couplings given (brief 067), `[stimulus][readout]`.
/// `first_over` calls it with the instrument's image's.
fn first_over_of(image: &[[i64; 2]; 2], blocks: &[Block]) -> Option<(usize, usize, usize)> {
    blocks.iter().enumerate().find_map(|(j, b)| {
        ALL_PAIRS
            .iter()
            .find(|&&(s, r)| over_bound(b.10[s][r], image[s][r]))
            .map(|&(s, r)| (j, s, r))
    })
}

/// H-20's criterion (ADR-0109), clause by clause per arm `[assignment first, mirrored first]`:
/// (1) each of the four mappings learned — `mapping_correct` at least `REWARDED_MIN` — and (2)
/// the couplings bounded — a run of 120 blocks with no coupling past 1.30 of its image's at any
/// block's end. `yes` is all ten. A no names the clause, the mapping and the block: under
/// clause 1 the mappings whose `learned` is false, read over their last two blocks; under
/// clause 2 `over`, the first block past the bound and its pair.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct Scheduled {
    learned: [[bool; 4]; 2],
    bounded: [bool; 2],
    over: [Option<(usize, usize, usize)>; 2],
    yes: bool,
}

fn scheduled(arms: [&[Block]; 2]) -> Scheduled {
    scheduled_of(&IMAGE_COUPLINGS_1024, arms)
}

/// `scheduled` against the image couplings given (brief 067): clause 2 read by `first_over_of`.
/// `scheduled` calls it with the instrument's image's.
fn scheduled_of(image: &[[i64; 2]; 2], arms: [&[Block]; 2]) -> Scheduled {
    let learned = arms.map(|blocks| mapping_correct(blocks).map(|c| c >= REWARDED_MIN));
    let over = arms.map(|blocks| first_over_of(image, blocks));
    let bounded = [0usize, 1].map(|k| arms[k].len() == SCHEDULE_BLOCKS && over[k].is_none());
    Scheduled {
        learned,
        bounded,
        over,
        yes: learned.iter().flatten().chain(&bounded).all(|&c| c),
    }
}

// --------------------------------------------------- the assertion's shape (ADR-0109)

/// An arm's per-block tables, as H-19's arms pin them: the sight's blocks, the compositions,
/// the earned blocks, the moves and each stimulus's expectation from the run's first block,
/// and the strong punishments from the first flip's.
#[derive(Clone, Copy)]
struct Tables<'a> {
    blocks: &'a [Block],
    compositions: &'a [Composition],
    earned: &'a [EarnedBlock],
    moves: &'a [MovesBlock],
    expected: &'a [[i32; 2]],
    strong: &'a [[u32; 2]],
}

/// H-19's arm's pinned tables, by its index in `CRITIC_ARMS`.
fn critic_tables(k: usize) -> Tables<'static> {
    Tables {
        blocks: CRITIC_BLOCKS_1024[k],
        compositions: CRITIC_COMPOSITIONS_1024[k],
        earned: CRITIC_EARNED_1024[k],
        moves: CRITIC_MOVES_1024[k],
        expected: CRITIC_EXPECTED_1024[k],
        strong: CRITIC_STRONG_1024[k],
    }
}

/// The first `rows` rows of `run` are `h19`'s, both holding at least that many.
fn same_rows<T: PartialEq>(run: &[T], h19: &[T], rows: usize) -> bool {
    match (run.get(..rows), h19.get(..rows)) {
        (Some(here), Some(there)) => here == there,
        _ => false,
    }
}

/// ADR-0109's assertion that the first 56 blocks are H-19's arm's bit for bit, table by table
/// in `Tables`'s order: the first `REPLICATED_BLOCKS` rows of every table read from the run's
/// first block, and the first `REPLICATED_AFTER_FLIP` rows of the strong punishments, equal to
/// H-19's. All six true is the assertion; a false one stops the round before any reading is
/// taken, and is a finding. Beside it the arm holds the couplings at the end of the 1 537th
/// trial to H-19's, and the oracle is held to the record at every trial.
fn replication(run: Tables, h19: Tables) -> [bool; 6] {
    [
        same_rows(run.blocks, h19.blocks, REPLICATED_BLOCKS),
        same_rows(run.compositions, h19.compositions, REPLICATED_BLOCKS),
        same_rows(run.earned, h19.earned, REPLICATED_BLOCKS),
        same_rows(run.moves, h19.moves, REPLICATED_BLOCKS),
        same_rows(run.expected, h19.expected, REPLICATED_BLOCKS),
        same_rows(run.strong, h19.strong, REPLICATED_AFTER_FLIP),
    ]
}

// --------------------------------------------------- the readings' shape (ADR-0109)

/// The punishment's course (ADR-0106's reading) under the schedule, per block from the first
/// flip and per stimulus `[A, B]`: the trials that selected the stimulus's old answer — the
/// readout that is not its answer under the mapping in force, which was its answer under the
/// mapping before — and left a signal at or below `STRONG_PUNISHMENT_Q16`. Up to the second
/// flip it is `strong_punishments`; the blocks before the first flip are not read.
fn strong_scheduled(read: &[EarnedTrial], first: bool) -> Vec<[u32; 2]> {
    let mut out = vec![[0u32; 2]; read.len().saturating_sub(FLIP).div_ceil(BLOCK)];
    for (t, trial) in read.iter().enumerate().skip(FLIP) {
        let old = answer_of(trial.0, first == flipped_at(&SCHEDULE_FLIPS, t)) as u8;
        if trial.2 != Some(old) || trial.7 > STRONG_PUNISHMENT_Q16 {
            continue;
        }
        if let Some(block) = t
            .checked_sub(FLIP)
            .and_then(|d| d.checked_div(BLOCK))
            .and_then(|j| out.get_mut(j))
        {
            let into = &mut block[usize::from(trial.0)];
            *into = into.saturating_add(1);
        }
    }
    out
}

/// `strong_scheduled` summed over the blocks of the mapping each flip put in force, per flip
/// and per stimulus; zeros for a mapping the table does not hold whole.
fn strong_by_flip(strong: &[[u32; 2]]) -> [[u32; 2]; 3] {
    [1usize, 2, 3].map(|m| {
        let (from, to) = MAPPINGS[m];
        strong
            .get(from.saturating_sub(FLIP_BLOCK)..to.saturating_sub(FLIP_BLOCK))
            .map_or([0; 2], strong_total)
    })
}

/// Per flip and per stimulus, the first trial from the flip, by index, that selected the
/// stimulus's answer under the mapping the flip put in force; none when none did before the
/// next flip or the run's end. At the first flip it is `first_new` where that came before the
/// second.
fn first_new_scheduled(read: &[EarnedTrial], first: bool) -> [[Option<usize>; 2]; 3] {
    [1usize, 2, 3].map(|m| {
        let (from, to) = SPANS[m];
        let mirrored = mirrored_at(first, MAPPINGS[m].0);
        [0u8, 1].map(|s| {
            let new = answer_of(s, mirrored) as u8;
            read.iter()
                .enumerate()
                .take(to)
                .skip(from)
                .find(|(_, t)| t.0 == s && t.2 == Some(new))
                .map(|(k, _)| k)
        })
    })
}

/// ADR-0109's predicted reading (1) as a rule: per flip and per stimulus, its first new
/// selection before the trial of index `flip + NEW_WITHIN`, among the first 128 trials from
/// the flip.
fn new_within(first_new: [[Option<usize>; 2]; 3]) -> [[bool; 2]; 3] {
    [0usize, 1, 2].map(|f| {
        let by = SCHEDULE_FLIPS[f].saturating_add(NEW_WITHIN);
        first_new[f].map(|t| t.is_some_and(|t| t < by))
    })
}

/// The correct trials of a run of blocks.
fn correct_in(blocks: &[Block]) -> u32 {
    blocks.iter().fold(0u32, |sum, b| sum.saturating_add(b.0))
}

/// Per mapping, the correct trials in its first `EDGE_BLOCKS` blocks and in its last
/// `EDGE_BLOCKS`, `[first, last]`; zeros for a run of any other length.
fn edges(blocks: &[Block]) -> [[u32; 2]; 4] {
    if blocks.len() != SCHEDULE_BLOCKS {
        return [[0; 2]; 4];
    }
    MAPPINGS.map(|(from, to)| {
        [
            blocks
                .get(from..from.saturating_add(EDGE_BLOCKS))
                .map_or(0, correct_in),
            blocks
                .get(to.saturating_sub(EDGE_BLOCKS)..to)
                .map_or(0, correct_in),
        ]
    })
}

/// ADR-0109's predicted reading (2) as a rule: per mapping, fewer correct trials in its first
/// four blocks than in its last four; false for a run of any other length.
fn later_better(blocks: &[Block]) -> [bool; 4] {
    edges(blocks).map(|[early, late]| early < late)
}

/// The speed of each mapping's learning (ADR-0109's reading of each reversal): per mapping, the
/// blocks from its first to the first of its blocks with at least `CROSSING_MARK` correct, that
/// block counted — after H-19's flip, 19 and 23; none when none of its blocks did or the run
/// does not hold it.
fn crossings(blocks: &[Block]) -> [Option<usize>; 4] {
    MAPPINGS.map(|(from, to)| {
        blocks
            .get(from..to)
            .and_then(|mine| mine.iter().position(|b| b.0 >= CROSSING_MARK))
            .map(|j| j.saturating_add(1))
    })
}

/// Per flip and per stimulus, the first block of the mapping the flip put in force, by index,
/// in which the stimulus selected its new answer more often than its old (the earned splits):
/// where its selection crossed; none when no block of the mapping did. At the first flip it is
/// `crossed_block` where that crossed before the second.
fn crossed_scheduled(earned: &[EarnedBlock], first: bool) -> [[Option<usize>; 2]; 3] {
    [1usize, 2, 3].map(|m| {
        let (from, to) = MAPPINGS[m];
        let mirrored = mirrored_at(first, from);
        [0u8, 1].map(|s| {
            let (new, old) = (answer_of(s, mirrored), answer_of(s, !mirrored));
            earned
                .iter()
                .enumerate()
                .take(to)
                .skip(from)
                .find(|(_, b)| b.0[usize::from(s)][new] > b.0[usize::from(s)][old])
                .map(|(j, _)| j)
        })
    })
}

/// Per mapping, its trials' outcomes `[correct, wrong, tied]`: the correct selections, the
/// selections of the other readout, and the ties; zeros for a mapping the run does not hold.
fn tally(blocks: &[Block]) -> [[u32; 3]; 4] {
    MAPPINGS.map(|(from, to)| {
        let Some(mine) = blocks.get(from..to) else {
            return [0; 3];
        };
        let correct = correct_in(mine);
        let ties = mine.iter().fold(0u32, |sum, b| sum.saturating_add(b.11));
        let trials = (mine.len() as u32).saturating_mul(BLOCK as u32);
        [
            correct,
            trials.saturating_sub(correct).saturating_sub(ties),
            ties,
        ]
    })
}

/// H-19's settle measure (ADR-0106's clause 3, a reading here and no clause) over each
/// mapping's last `SETTLE_BLOCKS` blocks, per mapping and per stimulus: the stimulus's answer
/// pair under the mapping, its coupling at the end of the mapping's last block less its
/// coupling `SETTLE_BLOCKS` blocks before; none for a run of any other length. Over the first
/// mapping it is `settle_moves`'s first.
fn settle_scheduled(blocks: &[Block], first: bool) -> Option<[[i64; 2]; 4]> {
    if blocks.len() != SCHEDULE_BLOCKS {
        return None;
    }
    Some(MAPPINGS.map(|(from, to)| {
        let mirrored = mirrored_at(first, from);
        let end = to.saturating_sub(1);
        [0usize, 1].map(|s| {
            let answer = answer_of(s as u8, mirrored);
            let at = |j: usize| blocks.get(j).map_or(0, |b| b.10[s][answer]);
            at(end).saturating_sub(at(end.saturating_sub(SETTLE_BLOCKS)))
        })
    }))
}

/// `settle_scheduled` as fractions of each answer pair's image coupling, in parts per ten
/// thousand, truncated.
fn settle_per_myriad(settle: Option<[[i64; 2]; 4]>, first: bool) -> Option<[[i64; 2]; 4]> {
    settle.map(|moves| {
        let mut out = [[0i64; 2]; 4];
        for (m, (into, pairs)) in out.iter_mut().zip(moves.iter()).enumerate() {
            let mirrored = mirrored_at(first, MAPPINGS[m].0);
            for (s, (fraction, &delta)) in into.iter_mut().zip(pairs.iter()).enumerate() {
                *fraction =
                    per_myriad(delta, IMAGE_COUPLINGS_1024[s][answer_of(s as u8, mirrored)]);
            }
        }
        out
    })
}

/// A coupling's peak: its fraction of the image coupling in parts per ten thousand, its block,
/// its stimulus and its readout.
type Peak = (i64, usize, usize, usize);

/// The highest coupling of each mapping (ADR-0109's reading): per mapping, the highest of the
/// four couplings at any of its blocks' ends as a fraction of its image coupling, in parts per
/// ten thousand, with its block and pair, `(per myriad, block, stimulus, readout)` — the first
/// in block order and then in `ALL_PAIRS`'s where two read the same; none for a mapping of
/// which the run holds no block.
fn highest(blocks: &[Block]) -> [Option<Peak>; 4] {
    highest_of(&IMAGE_COUPLINGS_1024, blocks)
}

/// `highest` against the image couplings given (brief 067), `[stimulus][readout]`. `highest`
/// calls it with the instrument's image's.
fn highest_of(image: &[[i64; 2]; 2], blocks: &[Block]) -> [Option<Peak>; 4] {
    MAPPINGS.map(|(from, to)| {
        let mut best: Option<Peak> = None;
        for (j, b) in blocks.iter().enumerate().take(to).skip(from) {
            for &(s, r) in &ALL_PAIRS {
                let fraction = per_myriad(b.10[s][r], image[s][r]);
                if best.is_none_or(|(high, ..)| fraction > high) {
                    best = Some((fraction, j, s, r));
                }
            }
        }
        best
    })
}

/// The moves after a punishment (`side` 1) or after a reward (`side` 0), summed over each
/// mapping's blocks: how the deliveries of each sign moved the addressed synapses, mapping by
/// mapping.
fn moves_by_mapping(blocks: &[MovesBlock], side: usize) -> [Moves; 4] {
    MAPPINGS.map(|(from, to)| {
        let mut out: Moves = ([0; 3], [0; 2]);
        for block in blocks.iter().take(to).skip(from) {
            add_moves(&mut out, &block[side]);
        }
        out
    })
}

// -------------------------- the run (brief 047), its tables in inhibition/pins/h20.rs

/// An arm's run from the signed engine under a schedule (brief 047): `earned_run_scheduled`
/// under the answer's feedback at the gate's zero with the signed gate set, the arm's first
/// mapping, the flips before the trials of index `flips`, the critic given, and `after` reading
/// the executor at every trial's end — the oracle, fed the reward each trial delivered, held to
/// the record at every trial; the task's error and expectations held to the harness's critic;
/// every trial's contract asserted under the mapping in force at it. Over H-19's one flip it
/// is `critic_run`'s run.
fn schedule_run(
    exec: &mut Engine,
    arm: Reversal,
    trials: usize,
    flips: &[usize],
    critic: Option<Critic>,
    after: &mut dyn FnMut(&Engine, usize),
) -> (EarnedRun, Vec<Moves>, Vec<[i32; 2]>) {
    earned_run_scheduled(
        exec,
        Feedback::Answer,
        first_mapping(arm),
        1024,
        trials,
        GATE_BASELINE_Q16,
        flips,
        true,
        critic,
        after,
    )
}

/// One arm of H-20 at 1 024 units (brief 047): H-19's calibration before any rewarded run
/// (H-20's stopping rule, step 2) — the settled engine held to ADR-0077 step by step and its
/// images, the signed image H-19's by its CRC, a frozen block from the zero image, the
/// inhibitory baseline and the signed gate unset, held to ADR-0077's frozen run, and H-18's
/// arm's first block from the signed image with the critic unset, held to H-18's tables; then
/// the arm's 7 680 trials from the signed image with H-19's critic and the three flips, the
/// couplings read at the end of the first trial under each new mapping; the run's tables
/// dumped; the first 56 blocks held to H-19's arm's, table by table, before any reading is
/// taken; then everything read and dumped, the clauses and the readings computed, before
/// anything else is held; then the assertion, and the pinned tables of the 64 blocks after
/// the second flip.
fn schedule_arm(arm: Reversal) {
    let k = SCHEDULE_ARMS
        .iter()
        .position(|&a| a == arm)
        .expect("an arm of H-20");
    let name = format!("schedule1024 {arm:?}");
    let (zero, signed) = signed_images(&name);
    let image_crc = pinned_crc(&signed);
    assert_eq!(
        image_crc, PUNISHED_IMAGE_CRC_1024,
        "{name}: H-19's image, H-18's"
    );
    assert_eq!(
        crc64(&with_version(&signed, 16)),
        PUNISHED_IMAGE_CRC_FORMAT_16_1024,
        "{name}: every byte but the header's version and seal is the image H-20 read (ADR-0114)"
    );
    {
        let mut frozen = frozen_from(&zero, 1024);
        assert_eq!(
            (frozen.inhibitory_baseline_q16(), frozen.signed_gate()),
            (None, false),
            "{name}: the calibration's image leaves the inhibitory baseline and the signed gate unset"
        );
        let calibration = taught_run(&mut frozen, Arm::Withheld, 1024, BLOCK);
        calibration_holds(&format!("{name} calibration"), &calibration);
    }
    {
        let mut exec = signed_from(&signed, 1024);
        let (run, moves) = punished_run(&mut exec, arm, BLOCK, FLIP, &mut |_, _| {});
        let (blocks, _, trials, read, _) = &run;
        let compositions: Vec<Composition> = trials.chunks(BLOCK).map(composition).collect();
        assert_eq!(
            blocks.as_slice(),
            &PUNISHED_BLOCKS_1024[k][..1],
            "{name}: H-18's first block, the critic unset"
        );
        assert_eq!(
            compositions.as_slice(),
            &PUNISHED_COMPOSITIONS_1024[k][..1],
            "{name}: and its composition"
        );
        assert_eq!(
            earned_blocks(read).as_slice(),
            &PUNISHED_EARNED_1024[k][..1],
            "{name}: and its earned block"
        );
        assert_eq!(
            moves_blocks(read, &moves).as_slice(),
            &PUNISHED_MOVES_1024[k][..1],
            "{name}: and its moves"
        );
        eprintln!(
            "DUMP {name} calibration holds: ADR-0077's settled candidate, H-19's image (crc {image_crc:#018x}) and H-18's first block reproduced"
        );
    }
    let sets = geometry(1024, ROTATION_1024);
    let image_sums = QUIET_1024[SETTLED].1;
    let mut exec = signed_from(&signed, 1024);
    assert_eq!(
        weights_by_polarity(&exec),
        image_sums,
        "{name}: the image's sums"
    );
    assert_eq!(
        pair_couplings(&exec, &sets),
        IMAGE_COUPLINGS_1024,
        "{name}: the same image"
    );
    let image = weights_of(&exec);
    let first = first_mapping(arm);
    let mut at_flips: [Option<[[i64; 2]; 2]>; 3] = [None; 3];
    let (run, moves, expected) = schedule_run(
        &mut exec,
        arm,
        SCHEDULE_TRIALS,
        &SCHEDULE_FLIPS,
        Some(CRITIC_AT_START),
        &mut |exec, trial| {
            if let Some(f) = SCHEDULE_FLIPS.iter().position(|&f| f == trial) {
                at_flips[f] = Some(pair_couplings(exec, &sets));
            }
        },
    );
    let (blocks, trace, trials, read, volley_ticks) = &run;
    let at_flips = at_flips.map(|c| c.expect("the run reached the trial after every flip"));
    let earned = earned_blocks(read);
    let compositions: Vec<Composition> = trials.chunks(BLOCK).map(composition).collect();
    let moved = moves_blocks(read, &moves);
    let expected_by_block = expected_blocks(&expected);
    let strong = strong_scheduled(read, first);
    assert_eq!(blocks.len(), SCHEDULE_BLOCKS, "{name}: 120 blocks");
    assert_eq!(
        (read.len(), expected.len()),
        (SCHEDULE_TRIALS, SCHEDULE_TRIALS)
    );
    assert_eq!(
        (
            compositions.len(),
            earned.len(),
            moved.len(),
            expected_by_block.len(),
            strong.len()
        ),
        (
            SCHEDULE_BLOCKS,
            SCHEDULE_BLOCKS,
            SCHEDULE_BLOCKS,
            SCHEDULE_BLOCKS,
            SCHEDULE_BLOCKS - FLIP_BLOCK
        )
    );
    // The run's tables dumped, the 64 blocks after the second flip as they are pinned, before
    // anything is held or read.
    let after = REPLICATED_BLOCKS;
    eprintln!("DUMP {name} PIN blocks {:?}", &blocks[after..]);
    eprintln!("DUMP {name} PIN trace {trace:#018x}");
    eprintln!("DUMP {name} PIN compositions {:?}", &compositions[after..]);
    eprintln!("DUMP {name} PIN earned {:?}", &earned[after..]);
    eprintln!(
        "DUMP {name} PIN read {:#018x}",
        earned_hash(&read[SCHEDULE_FLIPS[1]..])
    );
    eprintln!("DUMP {name} PIN census {:?}", census_of(volley_ticks));
    eprintln!("DUMP {name} PIN moves {:?}", &moved[after..]);
    eprintln!("DUMP {name} PIN expected {:?}", &expected_by_block[after..]);
    eprintln!(
        "DUMP {name} PIN strong {:?}",
        &strong[REPLICATED_AFTER_FLIP..]
    );
    eprintln!("DUMP {name} PIN at flips {at_flips:?}");
    // The first 56 blocks are H-19's arm's (ADR-0109's assertion): a divergence stops the round
    // here, before any reading is taken, and is a finding.
    let here = Tables {
        blocks,
        compositions: &compositions,
        earned: &earned,
        moves: &moved,
        expected: &expected_by_block,
        strong: &strong,
    };
    let replicated = replication(here, critic_tables(k));
    eprintln!(
        "DUMP {name} replication {replicated:?} at the 1 537th {:?}",
        at_flips[0]
    );
    assert_eq!(
        replicated, [true; 6],
        "{name}: the first 56 blocks are H-19's arm's — its blocks, compositions, earned blocks, moves, expectations and strong punishments"
    );
    assert_eq!(
        at_flips[0], CRITIC_CARRY_1024[k],
        "{name}: and the couplings at the end of the 1 537th trial"
    );
    // Everything read and dumped, and the clauses and the readings computed, before anything
    // else is held.
    dump_earned(&name, &run, &earned);
    let reach = reach_by_polarity(&exec, &image, 1024, &ALL_PAIRS);
    let correct = mapping_correct(blocks);
    let over = first_over(blocks);
    let first_new_read = first_new_scheduled(read, first);
    let within = new_within(first_new_read);
    let edges_read = edges(blocks);
    let later = later_better(blocks);
    let crossings_read = crossings(blocks);
    let crossed = crossed_scheduled(&earned, first);
    let tally_read = tally(blocks);
    let settle = settle_scheduled(blocks, first);
    let highest_read = highest(blocks);
    let strong_sum = strong_by_flip(&strong);
    let punished_moves = moves_by_mapping(&moved, 1);
    let rewarded_moves = moves_by_mapping(&moved, 0);
    let once = once_blocks(blocks, &compositions);
    let falls = falls_every_block(image_sums.0, blocks);
    let sums_after = weights_by_polarity(&exec);
    eprintln!(
        "DUMP {name} PIN readings correct {correct:?} over {over:?} reach {reach:?} first new {first_new_read:?} within {within:?} (predicted {NEW_WITHIN_PREDICTED}) edges {edges_read:?} later better {later:?} (predicted {LATER_BETTER_PREDICTED}) crossings {crossings_read:?} crossed {crossed:?} tally {tally_read:?} settle {settle:?} highest {highest_read:?} strong total {strong_sum:?} punished moves {punished_moves:?} rewarded moves {rewarded_moves:?} once {once} falls {falls} sums after {sums_after:?} image crc {image_crc:#018x}"
    );
    eprintln!(
        "DUMP {name} verdict of this arm: learned {:?} over {over:?} settle per myriad {:?}",
        correct.map(|c| c >= REWARDED_MIN),
        settle_per_myriad(settle, first)
    );
    eprintln!(
        "DUMP {name} couplings course {:?}",
        couplings_course(blocks)
    );
    eprintln!(
        "DUMP {name} expectations {expected_by_block:?} signal {:?}",
        blocks.iter().map(|b| b.9).collect::<Vec<i32>>()
    );
    eprintln!(
        "DUMP {name} inhibitory course {:?} image {image_sums:?} last splits {:?}",
        course(image_sums.0, blocks),
        last_splits(read)
    );
    // The assertion (ADR-0109), after the dump and beside the verdict: H-18's rule.
    assert!(
        punished_held(&reach),
        "{name}: ADR-0109's assertion — no excitatory synapse outside the four stimulus–readout pairs moved: {reach:?}"
    );
    // The pinned tables of the 64 blocks after the second flip, and the readings as the
    // constants state.
    pinned(
        &format!("{name} sight"),
        &blocks[after..],
        *trace,
        SCHEDULE_BLOCKS_1024[k],
        SCHEDULE_TRACES_1024[k],
    );
    assert_eq!(
        &compositions[after..],
        SCHEDULE_COMPOSITIONS_1024[k],
        "{name}: the composition per block"
    );
    assert_eq!(
        &earned[after..],
        SCHEDULE_EARNED_1024[k],
        "{name}: the earned blocks"
    );
    assert_eq!(
        earned_hash(&read[SCHEDULE_FLIPS[1]..]),
        SCHEDULE_READ_1024[k],
        "{name}: the readings from the second flip"
    );
    assert_eq!(
        census_of(volley_ticks),
        SCHEDULE_CENSUS_1024[k].to_vec(),
        "{name}: the volley's ticks"
    );
    assert_eq!(
        &moved[after..],
        SCHEDULE_MOVES_1024[k],
        "{name}: the moves per block"
    );
    assert_eq!(
        &expected_by_block[after..],
        SCHEDULE_EXPECTED_1024[k],
        "{name}: the expectations per block"
    );
    assert_eq!(
        &strong[REPLICATED_AFTER_FLIP..],
        SCHEDULE_STRONG_1024[k],
        "{name}: the strong punishments per block"
    );
    assert_eq!(at_flips, SCHEDULE_AT_FLIPS_1024[k]);
    assert_eq!(correct, CORRECT_SCHEDULE_1024[k]);
    assert_eq!(over, OVER_1024[k]);
    assert_eq!(reach, REACH_SCHEDULE_1024[k]);
    assert_eq!(first_new_read, FIRST_NEW_SCHEDULE_1024[k]);
    assert_eq!(within, NEW_WITHIN_1024[k]);
    assert_eq!(edges_read, EDGES_1024[k]);
    assert_eq!(later, LATER_BETTER_1024[k]);
    assert_eq!(crossings_read, CROSSINGS_1024[k]);
    assert_eq!(crossed, CROSSED_SCHEDULE_1024[k]);
    assert_eq!(tally_read, TALLY_1024[k]);
    assert_eq!(settle, SETTLE_SCHEDULE_1024[k]);
    assert_eq!(highest_read, HIGHEST_1024[k]);
    assert_eq!(strong_sum, STRONG_BY_FLIP_1024[k]);
    assert_eq!(punished_moves, PUNISHED_MOVES_SCHEDULE_1024[k]);
    assert_eq!(rewarded_moves, REWARDED_MOVES_SCHEDULE_1024[k]);
    assert_eq!(once, ONCE_BLOCKS_SCHEDULE_1024[k]);
    assert_eq!(falls, FALLS_SCHEDULE_1024[k]);
    assert_eq!(
        (sums_after, blocks.last().map(|b| (b.7, b.8))),
        (
            SUMS_AFTER_SCHEDULE_1024[k],
            Some(SUMS_AFTER_SCHEDULE_1024[k])
        ),
        "{name}: the sums after the run are the last block's"
    );
}

/// H-20's arm that starts from the assignment (brief 047): A onto readout 0 and B onto readout
/// 1 for 1 536 trials, then the mirrored mapping, the assignment and the mirrored mapping again
/// for 2 048 trials each, the signed gate and the critic set.
#[test]
#[ignore]
fn the_schedule_of_reversals_from_the_assignment_at_1024_units_exhaustive() {
    schedule_arm(Reversal::AssignmentFirst);
}

/// H-20's arm that starts from the mirrored assignment (brief 047): A onto readout 1 and B onto
/// readout 0 for 1 536 trials, then the assignment, the mirrored mapping and the assignment
/// again for 2 048 trials each, the signed gate and the critic set.
#[test]
#[ignore]
fn the_schedule_of_reversals_from_the_mirrored_assignment_at_1024_units_exhaustive() {
    schedule_arm(Reversal::MirroredFirst);
}

/// The gate's test (ADR-0061's class; brief 047): the arms and the constants as ADR-0109 fixed
/// them, H-19's restated; the schedule's rule; the criterion's two clauses at their edges over
/// blocks written by hand — 80 and 79 correct in each mapping's window, a coupling at 1.30 of
/// its image's and one LSB above it — and the verdict naming the clause, the mapping and the
/// block; the replication's rule over a hand-written prefix and over H-19's and H-18's tables;
/// the readings' rules over blocks, trials and tables written by hand; what H-19's pinned
/// tables already decide of H-20; and a few trials over a schedule of three flips on the
/// instrument's network at 1 024 units with the critic set, beside the same trials over the
/// first of those flips alone — the oracle held at every trial inside `earned_run_scheduled`
/// in both — where every trial is judged under the mapping the schedule puts in force and the
/// two runs are one run up to the second flip. No whole run, and nothing else added to the
/// gate.
#[test]
fn a_few_trials_over_a_schedule_at_1024_units_and_the_rules_of_the_schedule() {
    // The arms and the constants.
    assert_eq!(
        SCHEDULE_ARMS,
        [Reversal::AssignmentFirst, Reversal::MirroredFirst]
    );
    assert_eq!(
        (SCHEDULE_TRIALS, SCHEDULE_BLOCKS, LATER_MAPPING_TRIALS),
        (7_680, 120, 2_048)
    );
    assert_eq!(SCHEDULE_FLIPS, [1_536, 3_584, 5_632]);
    assert_eq!(
        SPANS,
        [(0, 1_536), (1_536, 3_584), (3_584, 5_632), (5_632, 7_680)]
    );
    assert_eq!(MAPPINGS, [(0, 24), (24, 56), (56, 88), (88, 120)]);
    assert_eq!((REPLICATED_BLOCKS, REPLICATED_AFTER_FLIP), (56, 32));
    assert_eq!(SCHEDULE_PREDICTED, None, "ADR-0109 predicts no verdict");
    assert_eq!(BOUND_PER_CENT, 130);
    assert_eq!((NEW_WITHIN, EDGE_BLOCKS), (128, 4));
    assert_eq!(
        [NEW_WITHIN_PREDICTED, LATER_BETTER_PREDICTED],
        [true; 2],
        "ADR-0109's two predicted readings"
    );
    // Every constant of H-19 restated unchanged, and with them ADR-0065's window, trial, seed
    // and gain, ADR-0066's mark and window of the criterion, ADR-0076's stimulus and cancel,
    // ADR-0077's settled candidate, ADR-0080's reward and mark of a crossing, ADR-0085's two
    // baselines, ADR-0089's flip, ADR-0093's run and arms, ADR-0094's flag and H-19's image.
    assert_eq!(
        (CRITIC_TRIALS, CRITIC_BLOCKS, FLIP, FLIP_BLOCK),
        (4_608, 72, 1_536, 24)
    );
    assert_eq!(CRITIC_ARMS, PUNISHED_ARMS);
    assert_eq!(CRITIC_SHIFT, 5, "ADR-0106's shift");
    assert_eq!(
        CRITIC_AT_START,
        Critic {
            expected_q16: [0; 2],
            shift: 5
        },
        "both expectations zero at the start"
    );
    assert_eq!(
        (STRONG_PUNISHMENT_Q16, SETTLE_BLOCKS, SETTLE_PER_CENT),
        (-0x8000, 4, 100)
    );
    assert_eq!(
        (WINDOW.from, WINDOW.ticks, TRIAL_TICKS, SEED, GAIN_1024),
        (100, 500, 1 << 14, 27, 0x0001_C000)
    );
    assert_eq!(
        (REWARDED_MIN, LAST_BLOCKS, BLOCK, CROSSING_MARK),
        (80, 2, 64, 40)
    );
    assert_eq!(SHAPE_F46, (2, 0x0001_4000));
    assert_eq!(CANCEL_PICKED_1024, Some(CANCEL_AT_THE_EXTREME));
    assert_eq!((SETTLED, BACKGROUNDS[SETTLED]), (0, 0));
    assert_eq!((GATE_BASELINE_Q16, INHIBITORY_BASELINE_Q16), (0, 0x8000));
    assert_eq!(REWARD_Q16, ONE);
    assert_eq!((PUNISHED_TRIALS, PUNISHED_ARMS), (4_608, REVERSAL_ARMS));
    assert_eq!(SIGNED_GATE_BYTE, 25);
    assert_eq!(
        (PUNISHED_IMAGE_CRC_1024, PUNISHED_IMAGE_CRC_FORMAT_16_1024),
        (0xc9e0_2d60_0792_7029, 0x3771_636d_3851_91ac),
        "H-19's image, H-18's, at format 25 and as H-19 read it at format 16"
    );
    // The schedule's rule: the mapping in force is the other than the first from the 1 537th
    // trial to the 3 584th and from the 5 633rd to the last; under H-19's one flip, from the
    // 1 537th on; under none, never. A block lies under the mapping of its first trial.
    for t in 0..SCHEDULE_TRIALS {
        assert_eq!(
            flipped_at(&SCHEDULE_FLIPS, t),
            (1_536..3_584).contains(&t) || (5_632..7_680).contains(&t),
            "trial {t}"
        );
        assert_eq!(flipped_at(&[FLIP], t), t >= FLIP, "trial {t}: one flip");
        assert!(!flipped_at(&[], t), "trial {t}: none");
    }
    for (m, &(from, to)) in MAPPINGS.iter().enumerate() {
        assert_eq!(
            SPANS[m],
            (from.saturating_mul(BLOCK), to.saturating_mul(BLOCK))
        );
        for j in from..to {
            assert_eq!(
                mirrored_at(false, j),
                m & 1 == 1,
                "block {j}: the assignment first"
            );
            assert_eq!(
                mirrored_at(true, j),
                m & 1 == 0,
                "block {j}: the mirrored first"
            );
        }
    }
    // The criterion's clause 1 at its edges over blocks written by hand: each mapping's last two
    // blocks at 40 and 40, then one of them at 39, in either arm; nothing before a mapping's last
    // two blocks is read, and a run of any other length learns nothing.
    let blocks_of = |correct: &[u32]| -> Vec<Block> {
        correct
            .iter()
            .map(|&c| {
                (
                    c,
                    0,
                    [[0; 2]; 2],
                    [0; 2],
                    [0; 2],
                    [0; 2],
                    0,
                    0,
                    0,
                    0,
                    IMAGE_COUPLINGS_1024,
                    (BLOCK as u32).saturating_sub(c),
                )
            })
            .collect()
    };
    let windows = |counts: [[u32; 2]; 4]| -> Vec<Block> {
        let mut correct = vec![BLOCK as u32; SCHEDULE_BLOCKS];
        for (&(_, end), pair) in MAPPINGS.iter().zip(counts) {
            correct[end.saturating_sub(2)] = pair[0];
            correct[end.saturating_sub(1)] = pair[1];
        }
        blocks_of(&correct)
    };
    let edge = windows([[40, 40]; 4]);
    assert_eq!(mapping_correct(&edge), [80; 4]);
    let all_yes = Scheduled {
        learned: [[true; 4]; 2],
        bounded: [true; 2],
        over: [None; 2],
        yes: true,
    };
    assert_eq!(
        scheduled([&edge, &edge]),
        all_yes,
        "80 in every mapping of both arms, every coupling the image's: yes"
    );
    for m in 0..4usize {
        for late in [false, true] {
            let mut counts = [[40, 40]; 4];
            counts[m][usize::from(late)] = 39;
            let short = windows(counts);
            let mut learned = [true; 4];
            learned[m] = false;
            assert_eq!(mapping_correct(&short)[m], 79);
            assert_eq!(
                scheduled([&short, &edge]),
                Scheduled {
                    learned: [learned, [true; 4]],
                    bounded: [true; 2],
                    over: [None; 2],
                    yes: false
                },
                "79 in mapping {m} of the first arm: clause 1 fails there"
            );
            assert_eq!(
                scheduled([&edge, &short]).learned,
                [[true; 4], learned],
                "and of the second"
            );
        }
        let mut before = edge.clone();
        before[MAPPINGS[m].1.saturating_sub(LAST_BLOCKS + 1)].0 = 0;
        before[MAPPINGS[m].0].0 = 0;
        assert_eq!(
            mapping_correct(&before),
            [80; 4],
            "mapping {m}: nothing before its last two blocks is read"
        );
    }
    assert_eq!(
        mapping_correct(&edge[..SCHEDULE_BLOCKS - 1]),
        [0; 4],
        "a run short of 7 680 learns nothing"
    );
    let mut longer = edge.clone();
    longer.push(edge[0]);
    assert_eq!(mapping_correct(&longer), [0; 4], "nor one past it");
    // Clause 2 at its edges: each pair's coupling at the largest value at or below 1.30 of its
    // image coupling, at the end of the first block, the 56th, the 57th and the last, then one
    // LSB above it; the first block past the bound named, and the first pair in `ALL_PAIRS`'s
    // order at one block; no bound below; a run of any other length not bounded.
    assert_eq!(
        IMAGE_COUPLINGS_1024[0][0]
            .saturating_mul(BOUND_PER_CENT)
            .saturating_div(100),
        8_124_417,
        "A→R0's image coupling, 6 249 552: 8 124 417 is at or below 1.30 of it and 8 124 418 is not"
    );
    for &(s, r) in &ALL_PAIRS {
        let image = IMAGE_COUPLINGS_1024[s][r];
        let at_bound = image.saturating_mul(BOUND_PER_CENT).saturating_div(100);
        assert!(
            !over_bound(at_bound, image) && over_bound(at_bound.saturating_add(1), image),
            "{s}→{r}: {at_bound}"
        );
        for j in [
            0,
            REPLICATED_BLOCKS - 1,
            REPLICATED_BLOCKS,
            SCHEDULE_BLOCKS - 1,
        ] {
            let mut run = edge.clone();
            run[j].10[s][r] = at_bound;
            assert_eq!(first_over(&run), None, "{s}→{r} at block {j}: at 1.30");
            assert_eq!(scheduled([&run, &run]), all_yes);
            run[j].10[s][r] = at_bound.saturating_add(1);
            assert_eq!(
                first_over(&run),
                Some((j, s, r)),
                "{s}→{r} at block {j}: one LSB above"
            );
            assert_eq!(
                scheduled([&edge, &run]),
                Scheduled {
                    learned: [[true; 4]; 2],
                    bounded: [true, false],
                    over: [None, Some((j, s, r))],
                    yes: false
                },
                "{s}→{r} at block {j}: clause 2 fails in the second arm there"
            );
        }
    }
    let mut twice = edge.clone();
    twice[70].10[1][1] = IMAGE_COUPLINGS_1024[1][1].saturating_mul(2);
    twice[90].10[0][0] = IMAGE_COUPLINGS_1024[0][0].saturating_mul(2);
    twice[90].10[1][0] = IMAGE_COUPLINGS_1024[1][0].saturating_mul(2);
    assert_eq!(
        first_over(&twice),
        Some((70, 1, 1)),
        "the first block past it"
    );
    twice[70].10[1][1] = IMAGE_COUPLINGS_1024[1][1];
    assert_eq!(first_over(&twice), Some((90, 0, 0)), "the first pair there");
    let mut low = edge.clone();
    low[100].10 = [[0; 2]; 2];
    assert_eq!(first_over(&low), None, "clause 2 bounds from above only");
    assert_eq!(
        scheduled([&edge[..SCHEDULE_BLOCKS - 1], &edge]),
        Scheduled {
            learned: [[false; 4], [true; 4]],
            bounded: [false, true],
            over: [None; 2],
            yes: false
        },
        "a run short of 7 680 is neither learned nor bounded"
    );
    // The replication's rule. On a hand-written prefix: the same 56 rows hold whatever follows
    // them; a row changed among them breaks the table, and 55 rows are short. Over the pinned
    // tables: H-19's arm against itself holds all six; one row changed at the 56th block — the
    // 32nd from the flip for the strong punishments — breaks that table and only it; a row
    // changed after them breaks nothing; and H-18's arm, the critic unset, is not H-19's.
    let hand = blocks_of(&[BLOCK as u32; SCHEDULE_BLOCKS]);
    let mut tail = hand.clone();
    tail[REPLICATED_BLOCKS].0 = 0;
    tail.truncate(REPLICATED_BLOCKS + 1);
    assert!(same_rows(&tail, &hand, REPLICATED_BLOCKS));
    tail[REPLICATED_BLOCKS - 1].0 = 0;
    assert!(!same_rows(&tail, &hand, REPLICATED_BLOCKS));
    assert!(!same_rows(
        &hand[..REPLICATED_BLOCKS - 1],
        &hand,
        REPLICATED_BLOCKS
    ));
    assert!(!same_rows(
        &hand,
        &hand[..REPLICATED_BLOCKS - 1],
        REPLICATED_BLOCKS
    ));
    for k in 0..2usize {
        let h19 = critic_tables(k);
        assert_eq!(replication(h19, h19), [true; 6], "{k}: H-19's own");
        let mut blocks = h19.blocks.to_vec();
        blocks[REPLICATED_BLOCKS - 1].11 ^= 1;
        assert_eq!(
            replication(
                Tables {
                    blocks: &blocks,
                    ..h19
                },
                h19
            ),
            [false, true, true, true, true, true],
            "{k}: the 56th block's ties"
        );
        let mut later = h19.blocks.to_vec();
        later[REPLICATED_BLOCKS].11 ^= 1;
        assert_eq!(
            replication(
                Tables {
                    blocks: &later,
                    ..h19
                },
                h19
            ),
            [true; 6],
            "{k}: the 57th block is not read"
        );
        let mut expected = h19.expected.to_vec();
        expected[REPLICATED_BLOCKS - 1][1] ^= 1;
        assert_eq!(
            replication(
                Tables {
                    expected: &expected,
                    ..h19
                },
                h19
            ),
            [true, true, true, true, false, true],
            "{k}: an expectation one LSB off"
        );
        let mut strong = h19.strong.to_vec();
        strong[REPLICATED_AFTER_FLIP - 1][0] ^= 1;
        assert_eq!(
            replication(
                Tables {
                    strong: &strong,
                    ..h19
                },
                h19
            ),
            [true, true, true, true, true, false],
            "{k}: the strong punishments of the 56th block"
        );
        strong[REPLICATED_AFTER_FLIP - 1][0] ^= 1;
        strong[REPLICATED_AFTER_FLIP][0] ^= 1;
        assert_eq!(
            replication(
                Tables {
                    strong: &strong,
                    ..h19
                },
                h19
            ),
            [true; 6],
            "{k}: and of the 57th, not read"
        );
        assert_eq!(
            replication(
                Tables {
                    moves: &h19.moves[..REPLICATED_BLOCKS - 1],
                    ..h19
                },
                h19
            ),
            [true, true, true, false, true, true],
            "{k}: 55 blocks of moves are short"
        );
        let h18 = Tables {
            blocks: PUNISHED_BLOCKS_1024[k],
            compositions: PUNISHED_COMPOSITIONS_1024[k],
            earned: PUNISHED_EARNED_1024[k],
            moves: PUNISHED_MOVES_1024[k],
            ..h19
        };
        assert_eq!(
            replication(h18, h19),
            [false, false, false, false, true, true],
            "{k}: H-18's arm, the critic unset, is not H-19's"
        );
    }
    // The readings' rules over trials written by hand, the assignment first: A's answer is
    // readout 0 under the first and third mappings and readout 1 under the second and fourth,
    // B's the other.
    let trial = |stimulus: u8, selection: Option<u8>, signal: i32| -> EarnedTrial {
        (
            stimulus,
            [0; 2],
            selection,
            false,
            -ONE,
            [[0; 2]; 2],
            0,
            signal,
        )
    };
    let mut read_hand = vec![trial(0, None, -ONE); SCHEDULE_TRIALS];
    // The strong punishments: the old answer at −0.5 or below, a tie, one LSB above −0.5, and
    // the answer in force not counted.
    read_hand[FLIP] = trial(0, Some(0), STRONG_PUNISHMENT_Q16);
    read_hand[FLIP + 1] = trial(0, Some(0), STRONG_PUNISHMENT_Q16.saturating_add(1));
    read_hand[SCHEDULE_FLIPS[1] - 1] = trial(1, Some(1), -ONE);
    read_hand[SCHEDULE_FLIPS[1]] = trial(0, Some(0), -ONE);
    read_hand[SCHEDULE_FLIPS[1] + 1] = trial(0, Some(1), -ONE);
    read_hand[SCHEDULE_FLIPS[2]] = trial(1, Some(1), i32::MIN);
    read_hand[SCHEDULE_TRIALS - 1] = trial(1, Some(0), -ONE);
    let strong = strong_scheduled(&read_hand, false);
    assert_eq!(strong.len(), SCHEDULE_BLOCKS - FLIP_BLOCK);
    let counted: Vec<(usize, [u32; 2])> = strong
        .iter()
        .copied()
        .enumerate()
        .filter(|(_, c)| *c != [0; 2])
        .collect();
    assert_eq!(
        counted,
        vec![(0, [1, 0]), (31, [0, 1]), (32, [1, 0]), (64, [0, 1])],
        "the 1 537th's old answer at −0.5; the 3 584th's B onto its old answer; after the second flip A onto readout 1, its old answer, and not onto readout 0; after the third B onto readout 1, and not the last trial's B onto its answer"
    );
    assert_eq!(strong_by_flip(&strong), [[1, 1], [1, 0], [0, 1]]);
    assert_eq!(
        strong_scheduled(&read_hand[..SCHEDULE_FLIPS[1]], false),
        strong_punishments(&read_hand[..SCHEDULE_FLIPS[1]], false),
        "up to the second flip it is H-19's rule"
    );
    assert_eq!(
        strong_scheduled(&read_hand, true)[0],
        [0, 0],
        "under the other first mapping the 1 537th's readout 0 is A's answer"
    );
    // The first new selections: A's new answer 127 trials after the first flip, B's 128 after
    // it; the first new selection before a flip not counted; after the second A's at the flip
    // and B's never, and B's readout 0, its old answer there, not a new one; after the third A's
    // 5 trials in and B's at the last trial.
    let mut news = vec![trial(0, None, 0); SCHEDULE_TRIALS];
    news[FLIP - 1] = trial(0, Some(1), 0);
    news[FLIP + NEW_WITHIN - 1] = trial(0, Some(1), 0);
    news[FLIP + NEW_WITHIN] = trial(1, Some(0), 0);
    news[SCHEDULE_FLIPS[1]] = trial(0, Some(0), 0);
    news[SCHEDULE_FLIPS[1] + 2] = trial(1, Some(0), 0);
    news[SCHEDULE_FLIPS[2] + 5] = trial(0, Some(1), 0);
    news[SCHEDULE_TRIALS - 1] = trial(1, Some(0), 0);
    let first_new_hand = first_new_scheduled(&news, false);
    assert_eq!(
        first_new_hand,
        [
            [Some(FLIP + NEW_WITHIN - 1), Some(FLIP + NEW_WITHIN)],
            [Some(SCHEDULE_FLIPS[1]), None],
            [Some(SCHEDULE_FLIPS[2] + 5), Some(SCHEDULE_TRIALS - 1)],
        ]
    );
    assert_eq!(
        new_within(first_new_hand),
        [[true, false], [true, false], [true, false]],
        "the trial of index 1 663 is within 128 of the first flip and the one of index 1 664 is not"
    );
    assert_eq!(
        first_new_scheduled(&news, false)[0],
        first_new(&news[..SCHEDULE_FLIPS[1]], false),
        "at the first flip it is H-18's rule up to the second"
    );
    // The edges, the crossings, the tally, the settle measure and the highest coupling over
    // blocks written by hand.
    let mut graded = edge.clone();
    for (m, &(from, to)) in MAPPINGS.iter().enumerate() {
        for block in &mut graded[from..to] {
            block.0 = 30;
            block.11 = 2;
        }
        graded[from].0 = 20;
        graded[to.saturating_sub(1)].0 = 20u32.saturating_add(u32::try_from(m).unwrap());
    }
    assert_eq!(
        edges(&graded),
        [[110, 110], [110, 111], [110, 112], [110, 113]]
    );
    assert_eq!(
        later_better(&graded),
        [false, true, true, true],
        "equal is not fewer"
    );
    assert_eq!(later_better(&graded[..SCHEDULE_BLOCKS - 1]), [false; 4]);
    assert_eq!(crossings(&graded), [None; 4]);
    graded[MAPPINGS[1].0 + 18].0 = CROSSING_MARK;
    graded[MAPPINGS[3].0 + 22].0 = CROSSING_MARK - 1;
    graded[MAPPINGS[3].0 + 23].0 = CROSSING_MARK;
    assert_eq!(
        crossings(&graded),
        [None, Some(19), None, Some(24)],
        "40 in a mapping's 19th block: 19 blocks; 39 is not 40"
    );
    assert_eq!(
        crossings(&graded[..MAPPINGS[1].1]),
        [None, Some(19), None, None],
        "a mapping the run does not hold crosses nowhere"
    );
    assert_eq!(
        tally(&graded)[1],
        [951, 1_033, 64],
        "the second mapping: 30 a block, 20 in its first, 21 in its last and 40 in its 19th, two ties a block"
    );
    let mut settling = edge.clone();
    for (m, &(_, to)) in MAPPINGS.iter().enumerate() {
        let mirrored = mirrored_at(false, MAPPINGS[m].0);
        for (s, image) in IMAGE_COUPLINGS_1024.iter().enumerate() {
            let answer = answer_of(s as u8, mirrored);
            settling[to.saturating_sub(1)].10[s][answer] =
                image[answer].saturating_add(i64::try_from(m).unwrap().saturating_add(1));
            settling[to.saturating_sub(1 + SETTLE_BLOCKS)].10[s][answer] =
                image[answer].saturating_sub(10);
            settling[to.saturating_sub(2 + SETTLE_BLOCKS)].10[s][answer] = 0;
        }
    }
    assert_eq!(
        settle_scheduled(&settling, false),
        Some([[11; 2], [12; 2], [13; 2], [14; 2]]),
        "the answer pair's coupling at a mapping's end less four blocks before; nothing before read"
    );
    assert_eq!(
        settle_scheduled(&settling, true),
        Some([[0; 2]; 4]),
        "the other mapping's pairs are the image's"
    );
    assert_eq!(
        settle_scheduled(&settling[..SCHEDULE_BLOCKS - 1], false),
        None
    );
    let mut h19_padded = CRITIC_BLOCKS_1024[0].to_vec();
    h19_padded.resize(SCHEDULE_BLOCKS, edge[0]);
    assert_eq!(
        settle_scheduled(&h19_padded, false).map(|m| [m[0]]),
        SETTLE_MOVES_1024[0].map(|m| [m[0]]),
        "over the first mapping it is H-19's clause 3"
    );
    let mut peaks = edge.clone();
    peaks[3].10[1][0] = IMAGE_COUPLINGS_1024[1][0].saturating_mul(2);
    peaks[30].10[0][1] = IMAGE_COUPLINGS_1024[0][1].saturating_mul(3);
    peaks[31].10[1][1] = IMAGE_COUPLINGS_1024[1][1].saturating_mul(3);
    assert_eq!(
        highest(&peaks),
        [
            Some((20_000, 3, 1, 0)),
            Some((30_000, 30, 0, 1)),
            Some((10_000, MAPPINGS[2].0, 0, 0)),
            Some((10_000, MAPPINGS[3].0, 0, 0)),
        ],
        "the highest, the first where two read the same"
    );
    assert_eq!(highest(&peaks[..MAPPINGS[1].1])[2], None);
    // The crossings per stimulus and the moves per mapping over earned blocks written by hand.
    let empty: EarnedBlock = ([[0; 3]; 2], 0, [[0; 2]; 2], 0, 0);
    let mut earned_hand = vec![empty; SCHEDULE_BLOCKS];
    earned_hand[30].0[0] = [10, 11, 0];
    earned_hand[40].0[1] = [12, 11, 0];
    earned_hand[60].0[0] = [11, 11, 0];
    earned_hand[61].0[0] = [12, 11, 0];
    earned_hand[100].0[1] = [5, 6, 3];
    assert_eq!(
        crossed_scheduled(&earned_hand, false),
        [[Some(30), Some(40)], [Some(61), None], [None, None]],
        "after the first flip A onto readout 1, B onto readout 0; after the second A onto readout 0, level not crossed; after the third B's new answer is readout 0"
    );
    assert_eq!(
        crossed_scheduled(&earned_hand, false)[0],
        crossed_block(&earned_hand[..REPLICATED_BLOCKS], false),
        "at the first flip it is H-18's rule up to the second"
    );
    let moved_hand: Vec<MovesBlock> = (0..SCHEDULE_BLOCKS)
        .map(|j| {
            let one = u32::try_from(j).unwrap();
            [([one, 0, 0], [1, 0]), ([0, one, 0], [0, -1])]
        })
        .collect();
    let rewarded = moves_by_mapping(&moved_hand, 0);
    let punished = moves_by_mapping(&moved_hand, 1);
    assert_eq!(
        rewarded.map(|m| (m.0[0], m.1[0])),
        [(276, 24), (1_264, 32), (2_288, 32), (3_312, 32)]
    );
    assert_eq!(
        punished.map(|m| (m.0[1], m.1[1])),
        [(276, -24), (1_264, -32), (2_288, -32), (3_312, -32)]
    );
    // What H-19's pinned tables already decide of H-20, since its first 56 blocks are H-19's:
    // clause 1 over the first two mappings, clause 2 over the first 56 blocks, the predicted
    // reading (1) at the first flip and (2) over the first two mappings, the first two
    // mappings' speeds, errors and ties, settle measures and highest couplings. The third and
    // the fourth mappings are the run's.
    for k in 0..2usize {
        let first = first_mapping(CRITIC_ARMS[k]);
        let h19 = &CRITIC_BLOCKS_1024[k][..REPLICATED_BLOCKS];
        let mut padded = h19.to_vec();
        padded.resize(SCHEDULE_BLOCKS, edge[0]);
        let decided = (
            [mapping_correct(&padded)[0], mapping_correct(&padded)[1]],
            first_over(h19),
            [edges(&padded)[0], edges(&padded)[1]],
            [crossings(h19)[0], crossings(h19)[1]],
            [tally(h19)[0], tally(h19)[1]],
            settle_scheduled(&padded, first).map(|m| [m[0], m[1]]),
            [highest(h19)[0], highest(h19)[1]],
        );
        eprintln!("DUMP schedule1024 decided by H-19's tables, arm {k}: {decided:?}");
        assert_eq!(decided, H19_DECIDES_1024[k], "arm {k}");
        assert_eq!(
            [mapping_correct(&padded)[0], mapping_correct(&padded)[1]],
            [CORRECT_CRITIC_1024[k][0], last_correct(h19)],
            "arm {k}: clause 1's first count is H-19's"
        );
        let within: Vec<bool> = FIRST_NEW_CRITIC_1024[k]
            .iter()
            .map(|t| t.is_some_and(|t| t < FLIP + NEW_WITHIN))
            .collect();
        assert_eq!(
            within, [true; 2],
            "arm {k}: the first flip's new answers within 128"
        );
        assert_eq!(
            crossed_scheduled(CRITIC_EARNED_1024[k], first)[0],
            CROSSED_CRITIC_1024[k],
            "arm {k}: the first flip's crossings are H-19's"
        );
        assert_eq!(
            strong_by_flip(CRITIC_STRONG_1024[k])[0],
            strong_total(&CRITIC_STRONG_1024[k][..REPLICATED_AFTER_FLIP])
        );
    }
    // A few trials over a schedule on the instrument's network at 1 024 units, the inhibitory
    // baseline, the signed gate and the critic set, the assignment first: flips before the
    // trials of index 2, 4 and 6, and beside it the same network over the flip before the
    // trial of index 2 alone. The oracle is held at every trial inside `earned_run_scheduled`
    // in both, and the task's error and expectations to the harness's critic.
    const GATE_SCHEDULE: [usize; 3] = [2, 4, 6];
    let p = prior(1024);
    let network = Config {
        inhibitory_baseline_q16: Some(INHIBITORY_BASELINE_Q16),
        signed_gate: true,
        ..config(1024, 2, GATE_BASELINE_Q16)
    };
    let mut exec = at_gain(&p, network.clone(), GAIN_1024);
    let before = weights_of(&exec);
    let (run, _, expected) = schedule_run(
        &mut exec,
        Reversal::AssignmentFirst,
        GATE_TRIALS,
        &GATE_SCHEDULE,
        Some(CRITIC_AT_START),
        &mut |_, _| {},
    );
    let (blocks, trace, _, read, _) = &run;
    assert!(blocks.is_empty(), "a few trials are no whole block");
    assert_eq!((read.len(), expected.len()), (GATE_TRIALS, GATE_TRIALS));
    let mut once_exec = at_gain(&p, network, GAIN_1024);
    let (once_run, _, once_expected) = critic_run(
        &mut once_exec,
        Reversal::AssignmentFirst,
        GATE_TRIALS,
        GATE_SCHEDULE[0],
        Some(CRITIC_AT_START),
        &mut |_, _| {},
    );
    let once = &once_run.3;
    eprintln!(
        "DUMP schedule1024 a few trials trace {trace:#018x} read {read:?} expected {expected:?} once {once:?} once expected {once_expected:?}"
    );
    // By hand: the mapping in force the assignment's over the trials of index 0, 1, 4 and 5 and
    // the mirrored one's over 2, 3, 6 and 7; the reward delivered the error against the
    // expectation before; the expectation moved by the error shifted by five, the other
    // stimulus's unmoved and carried across every flip.
    let mut held = [0i32; 2];
    for (t, r) in read.iter().enumerate() {
        let s = usize::from(r.0);
        let in_force = matches!(t, 2 | 3 | 6 | 7);
        assert_eq!(flipped_at(&GATE_SCHEDULE, t), in_force, "trial {t}");
        assert_eq!(
            r.3,
            r.2 == Some(answer_of(r.0, in_force) as u8),
            "trial {t}: correct under the mapping in force"
        );
        let outcome = if r.3 { ONE } else { -ONE };
        let error = outcome.saturating_sub(held[s]);
        assert_eq!(r.4, error, "trial {t}: the reward delivered is the error");
        held[s] = held[s].saturating_add(error >> CRITIC_SHIFT);
        assert_eq!(
            expected[t], held,
            "trial {t}: the expectation moved by the error shifted by five"
        );
    }
    let second = GATE_SCHEDULE[1];
    assert_eq!(
        (&read[..second], &expected[..second]),
        (&once[..second], &once_expected[..second]),
        "up to the second flip the two runs are one run"
    );
    let (c, u) = (&read[second], &once[second]);
    assert_eq!(
        (c.0, c.1, c.2),
        (u.0, u.1, u.2),
        "the trial there is the same trial"
    );
    assert_eq!(
        c.3,
        c.2 == Some(answer_of(c.0, false) as u8),
        "judged under the assignment again"
    );
    assert_eq!(
        u.3,
        u.2 == Some(answer_of(u.0, true) as u8),
        "where the one flip judges it under the mirrored mapping"
    );
    // No excitatory synapse outside the pairs the deliveries addressed moved.
    let addressed: Vec<(usize, usize)> = read
        .iter()
        .take(GATE_TRIALS - 1)
        .filter_map(|t| t.2.map(|r| (usize::from(t.0), usize::from(r))))
        .collect();
    let reach = reach_by_polarity(&exec, &before, 1024, &addressed);
    assert_eq!(
        reach.excitatory.1, 0,
        "no excitatory synapse outside the addressed pairs moved: {reach:?}"
    );
    assert!(reach.excitatory.0 > 0, "the addressed pairs moved");
    // Over the pinned tables: the verdict as written, by the rule committed first; the readings
    // as the constants state; what H-19's tables decided, as the run read it; and, block by
    // block over each arm's 120 blocks — H-19's first 56, to which the run was held, and the 64
    // pinned after them — the tables consistent with one another, with H-19's trials, with the
    // assertion and with the oracle: each coupling after a block the one before plus what the
    // oracle consolidated into that pair over the block, the excitatory sum the image's plus
    // the four pairs' moves, what the addressed synapses moved what the oracle consolidated,
    // and each expectation within the reward.
    let image = QUIET_1024[SETTLED].1;
    let arm_blocks = [0usize, 1].map(|k| {
        whole(
            CRITIC_BLOCKS_1024[k],
            REPLICATED_BLOCKS,
            SCHEDULE_BLOCKS_1024[k],
        )
    });
    let verdict = scheduled([&arm_blocks[0], &arm_blocks[1]]);
    assert_eq!(verdict, SCHEDULE_1024, "the verdict as written");
    assert_eq!(SCHEDULE_PREDICTED, None, "and no prediction to hold it to");
    for (k, &arm) in SCHEDULE_ARMS.iter().enumerate() {
        let first = first_mapping(arm);
        let blocks = &arm_blocks[k];
        let earned = whole(
            CRITIC_EARNED_1024[k],
            REPLICATED_BLOCKS,
            SCHEDULE_EARNED_1024[k],
        );
        let moved = whole(
            CRITIC_MOVES_1024[k],
            REPLICATED_BLOCKS,
            SCHEDULE_MOVES_1024[k],
        );
        let compositions = whole(
            CRITIC_COMPOSITIONS_1024[k],
            REPLICATED_BLOCKS,
            SCHEDULE_COMPOSITIONS_1024[k],
        );
        let expected = whole(
            CRITIC_EXPECTED_1024[k],
            REPLICATED_BLOCKS,
            SCHEDULE_EXPECTED_1024[k],
        );
        let strong = whole(
            CRITIC_STRONG_1024[k],
            REPLICATED_AFTER_FLIP,
            SCHEDULE_STRONG_1024[k],
        );
        let pinned_after = SCHEDULE_BLOCKS - REPLICATED_BLOCKS;
        assert_eq!(
            (
                SCHEDULE_BLOCKS_1024[k].len(),
                SCHEDULE_COMPOSITIONS_1024[k].len(),
                SCHEDULE_EARNED_1024[k].len(),
                SCHEDULE_MOVES_1024[k].len(),
                SCHEDULE_EXPECTED_1024[k].len(),
                SCHEDULE_STRONG_1024[k].len()
            ),
            (
                pinned_after,
                pinned_after,
                pinned_after,
                pinned_after,
                pinned_after,
                pinned_after
            ),
            "{arm:?}: sixty-four blocks of each after the second flip"
        );
        assert_eq!(
            (blocks.len(), strong.len()),
            (SCHEDULE_BLOCKS, SCHEDULE_BLOCKS - FLIP_BLOCK)
        );
        assert_ne!(SCHEDULE_TRACES_1024[k], 0);
        assert_ne!(SCHEDULE_READ_1024[k], 0);
        assert!(!SCHEDULE_CENSUS_1024[k].is_empty());
        assert_eq!(
            SCHEDULE_AT_FLIPS_1024[k][0], CRITIC_CARRY_1024[k],
            "{arm:?}: the couplings at the end of the 1 537th trial are H-19's"
        );
        let correct = mapping_correct(blocks);
        assert_eq!(correct, CORRECT_SCHEDULE_1024[k]);
        assert_eq!(correct.map(|c| c >= REWARDED_MIN), verdict.learned[k]);
        assert_eq!(first_over(blocks), OVER_1024[k]);
        assert_eq!(
            first_over(blocks).is_none(),
            verdict.bounded[k],
            "{arm:?}: 120 blocks, so bounded is no coupling past the bound"
        );
        assert_eq!(new_within(FIRST_NEW_SCHEDULE_1024[k]), NEW_WITHIN_1024[k]);
        assert_eq!(
            FIRST_NEW_SCHEDULE_1024[k][0], FIRST_NEW_CRITIC_1024[k],
            "{arm:?}: the first flip's first new selections are H-19's"
        );
        assert_eq!(edges(blocks), EDGES_1024[k]);
        assert_eq!(later_better(blocks), LATER_BETTER_1024[k]);
        assert_eq!(crossings(blocks), CROSSINGS_1024[k]);
        assert_eq!(crossed_scheduled(&earned, first), CROSSED_SCHEDULE_1024[k]);
        assert_eq!(
            CROSSED_SCHEDULE_1024[k][0], CROSSED_CRITIC_1024[k],
            "{arm:?}: the first flip's crossings are H-19's"
        );
        assert_eq!(tally(blocks), TALLY_1024[k]);
        assert_eq!(settle_scheduled(blocks, first), SETTLE_SCHEDULE_1024[k]);
        assert_eq!(highest(blocks), HIGHEST_1024[k]);
        let decided = (
            [correct[0], correct[1]],
            first_over(&blocks[..REPLICATED_BLOCKS]),
            [EDGES_1024[k][0], EDGES_1024[k][1]],
            [CROSSINGS_1024[k][0], CROSSINGS_1024[k][1]],
            [TALLY_1024[k][0], TALLY_1024[k][1]],
            SETTLE_SCHEDULE_1024[k].map(|m| [m[0], m[1]]),
            [HIGHEST_1024[k][0], HIGHEST_1024[k][1]],
        );
        assert_eq!(
            decided, H19_DECIDES_1024[k],
            "{arm:?}: what H-19's tables decided, the run read"
        );
        assert_eq!(strong_by_flip(&strong), STRONG_BY_FLIP_1024[k]);
        assert_eq!(moves_by_mapping(&moved, 1), PUNISHED_MOVES_SCHEDULE_1024[k]);
        assert_eq!(moves_by_mapping(&moved, 0), REWARDED_MOVES_SCHEDULE_1024[k]);
        assert_eq!(
            once_blocks(blocks, &compositions),
            ONCE_BLOCKS_SCHEDULE_1024[k]
        );
        assert_eq!(falls_every_block(image.0, blocks), FALLS_SCHEDULE_1024[k]);
        assert!(
            punished_held(&REACH_SCHEDULE_1024[k]),
            "{arm:?}: the assertion held"
        );
        let last = blocks.last().expect("a block");
        assert_eq!(SUMS_AFTER_SCHEDULE_1024[k], (last.7, last.8));
        for (j, e) in expected.iter().enumerate() {
            assert!(
                e.iter().all(|v| v.unsigned_abs() <= ONE.unsigned_abs()),
                "{arm:?} block {j}: each expectation within the reward: {e:?}"
            );
        }
        let mut previous = IMAGE_COUPLINGS_1024;
        for (j, block) in blocks.iter().enumerate() {
            let in_force = mirrored_at(first, j);
            assert_eq!(
                block.1, arm_blocks[0][j].1,
                "{arm:?} block {j}: the same trials present A in both arms"
            );
            if let Some(h19) = CRITIC_BLOCKS_1024[0].get(j) {
                assert_eq!(block.1, h19.1, "{arm:?} block {j}: and in H-19's");
            }
            let presented = [block.1, (BLOCK as u32).saturating_sub(block.1)];
            for (s, &n) in presented.iter().enumerate() {
                assert_eq!(
                    earned[j].0[s].iter().sum::<u32>(),
                    n,
                    "{arm:?} block {j}: every presentation of {s} selected or tied"
                );
            }
            assert_eq!(
                block.11,
                earned[j].0[0][2].saturating_add(earned[j].0[1][2]),
                "{arm:?} block {j}: the ties"
            );
            let correct = earned[j].0[0][answer_of(0, in_force)]
                .saturating_add(earned[j].0[1][answer_of(1, in_force)]);
            assert_eq!(
                block.0, correct,
                "{arm:?} block {j}: correct under the mapping in force"
            );
            assert_eq!(
                earned[j].1, correct,
                "{arm:?} block {j}: an error above zero on every correct trial and on no other, the expectation below 1.0"
            );
            let mut rise = 0i64;
            let mut consolidated = 0i64;
            for &(s, r) in &ALL_PAIRS {
                assert_eq!(
                    block.10[s][r],
                    previous[s][r].saturating_add(earned[j].2[s][r]),
                    "{arm:?} block {j}: {s}→{r} moved by what the oracle consolidated"
                );
                rise =
                    rise.saturating_add(block.10[s][r].saturating_sub(IMAGE_COUPLINGS_1024[s][r]));
                consolidated = consolidated.saturating_add(earned[j].2[s][r]);
            }
            assert_eq!(
                block.8,
                image.1.saturating_add(rise),
                "{arm:?} block {j}: the excitatory sum moved by the four pairs' moves and nothing else"
            );
            let moved_sum = moved[j]
                .iter()
                .flat_map(|m| m.1.iter())
                .fold(0i64, |sum, &a| sum.saturating_add(a));
            assert_eq!(
                moved_sum, consolidated,
                "{arm:?} block {j}: what the addressed synapses moved is what the oracle consolidated"
            );
            previous = block.10;
        }
    }
}

/// An arm's whole table of H-20: H-19's first `rows` rows, to which the run was held, and the
/// rows pinned after them.
fn whole<T: Clone>(h19: &[T], rows: usize, after: &[T]) -> Vec<T> {
    h19.iter().take(rows).chain(after).cloned().collect()
}

/// What H-19's pinned tables decide of H-20 before any run, per arm, read by H-20's rules over
/// H-19's first 56 blocks: clause 1's counts over the first two mappings; the first block past
/// 1.30 among the 56 (none); the predicted reading (2)'s edges over the first two mappings; the
/// first two mappings' speeds, `[correct, wrong, tied]` and settle measures; and their highest
/// couplings — H-19's 1.145 and 1.165.
type Decided = (
    [u32; 2],
    Option<(usize, usize, usize)>,
    [[u32; 2]; 2],
    [Option<usize>; 2],
    [[u32; 3]; 2],
    Option<[[i64; 2]; 2]>,
    [Option<Peak>; 2],
);

// --------------------- the measurement (brief 047), its tables in inhibition/pins/h20.rs

const SCHEDULE_TRACES_1024: [u64; 2] = [0xdd2a9318b3c5d288, 0xf4c8a5f8566b124e];
const SCHEDULE_READ_1024: [u64; 2] = [0x78e39782209b718a, 0x5d995a7cb23cf34f];
/// Clause 1's counts per arm and per mapping, against `REWARDED_MIN`, and clause 2's first
/// block past the bound with its pair, per arm.
const CORRECT_SCHEDULE_1024: [[u32; 4]; 2] = [[122, 121, 113, 115], [125, 115, 118, 120]];
const OVER_1024: [Option<(usize, usize, usize)>; 2] = [None, None];
const LATER_BETTER_1024: [[bool; 4]; 2] = [[true, true, true, true], [true, true, true, true]];
/// The blocks, of 120, in which the stimulus fired once, per arm.
const ONCE_BLOCKS_SCHEDULE_1024: [u32; 2] = [120, 120];
/// Whether the inhibitory sum fell in every block of the run, per arm.
const FALLS_SCHEDULE_1024: [bool; 2] = [false, false];
/// The arena's sums by polarity after each arm's run, `(inhibitory, excitatory)`.
const SUMS_AFTER_SCHEDULE_1024: [(i64, i64); 2] = [(11999067, 219302252), (12936700, 220257496)];

// =================================================================================== H-21

// -------------------------------------------- written before the run (ADR-0128, ADR-0129)

/// The target's lead-in (ADR-0128): $2^{20}$ ticks, eight of the settling's windows and as
/// long as a block of trials.
const TARGET_LEAD_IN_TICKS: u64 = 1 << 20;
/// The windows of the target's lead-in, each read on its own.
const TARGET_LEAD_IN_WINDOWS: u64 = TARGET_LEAD_IN_TICKS / WINDOW_TICKS;
/// The trials of one window of `WINDOW_TICKS`, the window ADR-0057's rule counts over.
const WINDOW_TRIALS: usize = (WINDOW_TICKS / TRIAL_TICKS as u64) as usize;
const _: () = assert!(
    TARGET_LEAD_IN_WINDOWS == 8
        && TARGET_LEAD_IN_TICKS == BLOCK as u64 * TRIAL_TICKS as u64
        && WINDOW_TRIALS == 8
        && WINDOW_TRIALS as u64 * TRIAL_TICKS as u64 == WINDOW_TICKS
);

/// The arms of H-21 (ADR-0128): H-20's two, in their order, each its own weekly test, from
/// H-20's image with the target period written, H-20's critic at the start and H-20's flips.
const TARGET_ARMS: [Reversal; 2] = SCHEDULE_ARMS;

/// ADR-0128 writes no prediction for the verdict.
const TARGET_PREDICTED: Option<bool> = None;

/// Clause 1's floor (ADR-0128): the network's inhibitory sum at or above half of the settled
/// image's at every block's end, read in integers as `sum × 100 ≥ image × 50`.
const DRAIN_FLOOR_PER_CENT: i64 = 50;

/// Where the modulator section holds the inhibitory rule's target period (ADR-0053): its
/// bytes `[20..24)`, little-endian.
const TARGET_PERIOD_AT: usize = 20;

/// An inhibitory weight at the rail, one LSB above −1.0: the prior's, from which the rule can
/// only weaken (ADR-0053, ADR-0120).
const RAIL_Q1_15: i16 = -32_767;
const _: () = assert!(RAIL_Q1_15 == i16::MIN + 1 && RAIL_Q1_15 as i32 == -(i16::MAX as i32));

/// The classes a unit is read in (brief 054), in this order: inhibitory, whatever set holds
/// it; an excitatory unit of a stimulus set; an excitatory unit of a readout set; any other
/// unit. At 1 024 units the sets tile every period of twenty, so the last class is the four
/// units past the last whole period.
const CLASSES: usize = 4;

/// The per cents of the units at which the rates' reading reads the ordered counts.
const QUANTILES: [usize; 7] = [0, 10, 25, 50, 75, 90, 100];

/// The trials that end the windows ADR-0057's rule is read over during a run (brief 054): the
/// eight before each flip and the run's last eight.
const WATCHED_ENDS: [usize; 4] = [
    SCHEDULE_FLIPS[0],
    SCHEDULE_FLIPS[1],
    SCHEDULE_FLIPS[2],
    SCHEDULE_TRIALS,
];
const _: () = assert!(
    WATCHED_ENDS[0] >= WINDOW_TRIALS
        && WATCHED_ENDS[1] >= WATCHED_ENDS[0] + WINDOW_TRIALS
        && WATCHED_ENDS[2] >= WATCHED_ENDS[1] + WINDOW_TRIALS
        && WATCHED_ENDS[3] >= WATCHED_ENDS[2] + WINDOW_TRIALS
);

/// The target's rule (ADR-0128), written before it is computed: the settled network's
/// population rate — `spikes` of `units` units over `ticks` ticks, in hertz
/// $10^5 \cdot \text{spikes} / (\text{units} \cdot \text{ticks})$ at the 10 µs tick — and the
/// target period 100 000 ticks over that rate, which is $\text{units} \cdot \text{ticks} /
/// \text{spikes}$: rounded to the nearest tick from the exact quotient, a half up, and clamped
/// to ADR-0053's bounds, `[ISTDP_PERIOD_MIN_TICKS, ISTDP_PERIOD_MAX_TICKS]`; the longest for a
/// network that did not fire.
fn target_period(units: u64, ticks: u64, spikes: u64) -> u32 {
    let exposure = units.saturating_mul(ticks);
    let period = exposure
        .saturating_add(spikes / 2)
        .checked_div(spikes)
        .unwrap_or(u64::MAX);
    period.clamp(
        u64::from(ISTDP_PERIOD_MIN_TICKS),
        u64::from(ISTDP_PERIOD_MAX_TICKS),
    ) as u32
}

// ------------------------------------------------------------ the criterion (ADR-0128)

/// Clause 1's rule for one block: the inhibitory sum below half of the image's,
/// `sum × 100 < image × 50`.
fn drained_below(sum: i64, image: i64) -> bool {
    sum.saturating_mul(100) < image.saturating_mul(DRAIN_FLOOR_PER_CENT)
}

/// Clause 1's reading: the first block, by index, at whose end the inhibitory sum stood below
/// half of the image's; none when no block's did.
fn first_below(image: i64, blocks: &[Block]) -> Option<usize> {
    blocks.iter().position(|b| drained_below(b.7, image))
}

/// The drain's lowest point: the lowest inhibitory sum at a block's end as a fraction of the
/// image's, in parts per ten thousand, truncated, and its block, the first in order where two
/// read the same; none for a run of no block.
fn lowest(image: i64, blocks: &[Block]) -> Option<(i64, usize)> {
    let mut low: Option<(i64, usize)> = None;
    for (j, b) in blocks.iter().enumerate() {
        let fraction = per_myriad(b.7, image);
        if low.is_none_or(|(least, _)| fraction < least) {
            low = Some((fraction, j));
        }
    }
    low
}

/// H-21's criterion (ADR-0128), clause by clause per arm `[assignment first, mirrored first]`:
/// (1) the drain stops — a run of 120 blocks with the inhibitory sum at or above half of the
/// settled image's at every block's end, `below` naming the first block where it was not — and
/// (2) the learning holds, H-20's two clauses as `scheduled` reads them. `yes` is both in both
/// arms.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct Targeted {
    held: [bool; 2],
    below: [Option<usize>; 2],
    learning: Scheduled,
    yes: bool,
}

fn targeted(image: i64, arms: [&[Block]; 2]) -> Targeted {
    let below = arms.map(|blocks| first_below(image, blocks));
    let held = [0usize, 1].map(|k| arms[k].len() == SCHEDULE_BLOCKS && below[k].is_none());
    let learning = scheduled(arms);
    Targeted {
        held,
        below,
        learning,
        yes: held.iter().all(|&h| h) && learning.yes,
    }
}

// ----------------------------------------------------- the readings' shape (brief 054)

/// Each unit's class in `CLASSES`'s order, by its position in the arena, from its flags and
/// the task's sets.
fn classes_of(exec: &Engine, sets: &[Set; 4]) -> Vec<usize> {
    exec.units()
        .iter()
        .enumerate()
        .map(|(position, unit)| {
            assert_eq!(unit.id, position as u64, "a unit's id is its position");
            let id = position as u32;
            if unit.flags & FLAG_INHIBITORY != 0 {
                0
            } else if sets[0].contains(id) || sets[1].contains(id) {
                1
            } else if sets[2].contains(id) || sets[3].contains(id) {
                2
            } else {
                3
            }
        })
        .collect()
}

/// The units of each class.
fn class_sizes(classes: &[usize]) -> [u32; CLASSES] {
    let mut out = [0u32; CLASSES];
    for &c in classes {
        if let Some(n) = out.get_mut(c) {
            *n = n.saturating_add(1);
        }
    }
    out
}

/// The inhibition by class (brief 054): the inhibitory magnitudes summed by the class of the
/// unit they reach, and the inhibitory synapses at the rail.
type ClassInhibition = ([i64; CLASSES], u32);

fn inhibition_by_class(exec: &Engine, classes: &[usize]) -> ClassInhibition {
    let mut out: ClassInhibition = ([0; CLASSES], 0);
    for unit in exec.units() {
        if unit.flags & FLAG_INHIBITORY == 0 {
            continue;
        }
        for s in unit.fan_out(exec.blocks()) {
            if let Some(into) = classes
                .get(s.target as usize)
                .and_then(|&c| out.0.get_mut(c))
            {
                *into = into.saturating_add(i64::from(s.weight_q1_15).saturating_neg());
            }
            out.1 = out
                .1
                .saturating_add(u32::from(s.weight_q1_15 == RAIL_Q1_15));
        }
    }
    out
}

/// Every spike of the train in `[start, end)`, its unit handed to `each`: the train is in tick
/// order, so it is read from its end back to the first spike before `start`. The runs' ticks
/// stay below the stamp's width, so the stamp is the tick.
fn each_spike(train: &[(u32, u32)], start: u32, end: u32, each: &mut dyn FnMut(usize)) {
    for &(tick, unit) in train.iter().rev() {
        if tick < start {
            break;
        }
        if tick < end {
            each(unit as usize);
        }
    }
}

/// ADR-0057's rule over one window's counts at a period (the harness's `spikes_and_at_target`
/// reads it from the train at the engine's period): a unit is at the target when its spikes
/// in a window of `WINDOW_TICKS` are within a factor of two of `WINDOW_TICKS / period`,
/// inclusive both ways; the fraction of the units, Q16.16.
fn at_target(counts: &[u32], period: u32) -> u32 {
    let target = WINDOW_TICKS.checked_div(u64::from(period)).unwrap_or(0) as u32;
    let at = counts
        .iter()
        .filter(|&&count| count.saturating_mul(2) >= target && count <= target.saturating_mul(2))
        .count() as u64;
    // At most the unit count, which is below 2^16: the shift cannot wrap.
    (at << 16).checked_div(counts.len() as u64).unwrap_or(0) as u32
}

/// The settled network's rates before the first trial (ADR-0128's reading), from each unit's
/// spikes over the target's lead-in of `ticks` ticks: the counts at 0, 10, 25, 50, 75, 90 and
/// 100 per cent of the units in order (the unit at `q (n − 1) / 100`, truncated); the units
/// that did not fire; and per class, its units and those at or above the target — whose count
/// is at least `ticks` over the period, `count × period ≥ ticks` — whose inhibition from the
/// rail the rule does not weaken.
type Rates = ([u32; 7], u32, [u32; CLASSES], [u32; CLASSES]);

fn rates(counts: &[u32], classes: &[usize], period: u32, ticks: u64) -> Rates {
    let mut sorted = counts.to_vec();
    sorted.sort_unstable();
    let last = sorted.len().saturating_sub(1);
    let quantiles = QUANTILES.map(|q| {
        sorted
            .get(q.saturating_mul(last) / 100)
            .copied()
            .unwrap_or(0)
    });
    let silent = counts.iter().filter(|&&c| c == 0).count() as u32;
    let mut above = [0u32; CLASSES];
    for (&count, &c) in counts.iter().zip(classes) {
        if u64::from(count).saturating_mul(u64::from(period)) >= ticks {
            if let Some(n) = above.get_mut(c) {
                *n = n.saturating_add(1);
            }
        }
    }
    (quantiles, silent, class_sizes(classes), above)
}

// ---------------------------------------------------------------- the image (brief 054)

/// The modulator section's entry: where its entry sits in the section table, and its
/// section's offset and length.
fn modulator_entry(img: &[u8]) -> (usize, usize, usize) {
    let header = MenteionFileHeader::decode(img[0..64].try_into().unwrap());
    for at in (64..).step_by(64).take(header.section_count as usize) {
        let entry = SectionEntry::decode(img[at..][..64].try_into().unwrap());
        if entry.kind == SECTION_MODULATOR {
            return (at, entry.offset as usize, entry.length as usize);
        }
    }
    panic!("the image holds a modulator section");
}

/// The image with the inhibitory rule's target period written `period` in the modulator
/// section's `[20..24)` and the section re-sealed; every other byte the image's. The image
/// each arm of H-21 decodes is H-20's image so written.
fn targeted_image(image: &[u8], period: u32) -> Vec<u8> {
    let mut img = image.to_vec();
    let (at, offset, length) = modulator_entry(&img);
    img[offset..][TARGET_PERIOD_AT..][..4].copy_from_slice(&period.to_le_bytes());
    let mut entry = SectionEntry::decode(img[at..][..64].try_into().unwrap());
    entry.crc64 = crc64(&img[offset..][..length]);
    img[at..][..64].copy_from_slice(&entry.encode());
    img
}

/// The positions at which two images of one length differ.
fn differing(a: &[u8], b: &[u8]) -> Vec<usize> {
    assert_eq!(a.len(), b.len(), "one image, twice");
    a.iter()
        .zip(b.iter())
        .enumerate()
        .filter(|(_, (x, y))| x != y)
        .map(|(i, _)| i)
        .collect()
}

/// The masked check (ADR-0128's one change): `targeted` differs from `image` only in the
/// modulator section's four bytes of the target period and in the section's entry in the
/// table, which holds its seal; and writing `image`'s own period back into it gives `image`
/// bit for bit.
fn only_the_target(image: &[u8], targeted: &[u8]) -> bool {
    let (at, offset, _) = modulator_entry(image);
    let period = offset.saturating_add(TARGET_PERIOD_AT);
    let entry = at..at.saturating_add(64);
    let mask = period..period.saturating_add(4);
    let own = u32::from_le_bytes(image[mask.clone()].try_into().unwrap());
    image.len() == targeted.len()
        && differing(image, targeted)
            .iter()
            .all(|p| mask.contains(p) || entry.contains(p))
        && targeted_image(targeted, own) == image
}

// ---------------------------------------------------------------- the run (brief 054)

/// The target's lead-in (ADR-0128's rule): the settled image frozen — ADR-0077's zero image,
/// the baseline zero and the inhibitory baseline unset, so nothing consolidates — under
/// ADR-0044's drive for `TARGET_LEAD_IN_TICKS` from the tick it was written at, in windows of
/// `WINDOW_TICKS`, the train asserted to hold each window whole as `settling` asserts it; each
/// window's spikes per unit. Every weight is asserted unmoved after it.
fn target_lead_in(zero: &[u8]) -> Vec<Vec<u32>> {
    target_lead_in_at(zero, 1024)
}

/// `target_lead_in` of a settled image at `size` units (brief 068): the image decoded and the
/// drive laid at that size. `target_lead_in` calls it with 1 024, so its lead-in is the one it
/// was.
fn target_lead_in_at(zero: &[u8], size: u32) -> Vec<Vec<u32>> {
    target_lead_in_under(zero, size, ISTDP_TARGET_PERIOD_TICKS)
}

/// `target_lead_in_at` of a settled image carrying the inhibitory rule's period `period`
/// (ADR-0195): under the read's flag for the inhibitory target the image carries the read's
/// period, where every other settled image carries the default. The frozen copy consolidates
/// nothing, so its spikes do not read the period. `target_lead_in_at` calls it with the default,
/// so its lead-in is the one it was.
fn target_lead_in_under(zero: &[u8], size: u32, period: u32) -> Vec<Vec<u32>> {
    let mut exec = frozen_from(zero, size);
    assert_eq!(
        (
            exec.inhibitory_baseline_q16(),
            exec.istdp_target_period_ticks()
        ),
        (None, period),
        "the settled image: the inhibitory baseline unset, the period it carries"
    );
    let before = weights_of(&exec);
    let drive = drive(size);
    let units = exec.units().len();
    let mut windows = Vec::new();
    for _ in 0..TARGET_LEAD_IN_WINDOWS {
        let from = exec.ticks();
        let held = exec.train().len() as u64;
        let overwritten = exec.train_overwritten();
        lead_in(&mut exec, &drive, 1);
        let to = exec.ticks();
        assert!(
            exec.train_overwritten().wrapping_sub(overwritten) <= held,
            "the train held the window"
        );
        assert!(to <= u64::from(u32::MAX), "the stamp is the tick");
        let mut counts = vec![0u32; units];
        each_spike(exec.train(), from as u32, to as u32, &mut |unit| {
            if let Some(c) = counts.get_mut(unit) {
                *c = c.saturating_add(1);
            }
        });
        windows.push(counts);
    }
    assert_eq!(weights_of(&exec), before, "every weight frozen");
    windows
}

/// Each unit's spikes summed over windows.
fn summed(windows: &[Vec<u32>]) -> Vec<u32> {
    let mut out = vec![0u32; windows.first().map_or(0, Vec::len)];
    for window in windows {
        for (sum, &c) in out.iter_mut().zip(window) {
            *sum = sum.saturating_add(c);
        }
    }
    out
}

/// A table's spikes, all units.
fn spikes_of(counts: &[u32]) -> u64 {
    counts
        .iter()
        .fold(0u64, |sum, &c| sum.saturating_add(u64::from(c)))
}

/// What brief 054 reads of a run beside H-20's tables: the four couplings at the end of the
/// first trial under each new mapping, as H-20 reads them; per block, the spikes by class over
/// the block's trials and the inhibition by class at its end; and the fraction of units at the
/// target by ADR-0057's rule, at the engine's period, over the window of eight trials before
/// each flip and over the run's last.
#[derive(Clone, Debug, PartialEq, Eq)]
struct Watched {
    at_flips: [[[i64; 2]; 2]; 3],
    spikes: Vec<[u64; CLASSES]>,
    inhibition: Vec<ClassInhibition>,
    at_target: [u32; 4],
}

/// An arm's run from the targeted engine (brief 054): H-20's run — `earned_run_observed` under
/// the answer's feedback at the gate's zero with the signed gate set, the arm's first mapping,
/// H-20's flips and critic, the oracle held to the record at every trial — with `after`
/// reading at every trial's end the trial's spikes from the train, whole since the ring holds
/// the most spikes a trial can produce, and the trials asserted to abut; at the end of the
/// first trial under each new mapping the four couplings, as H-20 reads them; and at every
/// block's end the inhibition by class.
fn target_run(
    exec: &mut Engine,
    arm: Reversal,
    sets: &[Set; 4],
    classes: &[usize],
) -> (EarnedRun, Vec<Moves>, Vec<[i32; 2]>, Watched) {
    let period = exec.istdp_target_period_ticks();
    let mut at_flips: [Option<[[i64; 2]; 2]>; 3] = [None; 3];
    let mut spikes: Vec<[u64; CLASSES]> = Vec::new();
    let mut inhibition: Vec<ClassInhibition> = Vec::new();
    let mut fractions: [Option<u32>; 4] = [None; 4];
    let mut block = [0u64; CLASSES];
    let mut window = vec![0u32; classes.len()];
    let mut last_end: Option<u64> = None;
    let (run, moves, expected) = earned_run_observed(
        exec,
        Feedback::Answer,
        first_mapping(arm),
        1024,
        SCHEDULE_TRIALS,
        GATE_BASELINE_Q16,
        &SCHEDULE_FLIPS,
        true,
        Some(CRITIC_AT_START),
        &mut |exec, trial| {
            let end = exec.ticks();
            let start = end
                .checked_sub(u64::from(TRIAL_TICKS))
                .expect("a trial's ticks");
            if let Some(previous) = last_end {
                assert_eq!(start, previous, "trial {trial}: the trials abut");
            }
            last_end = Some(end);
            assert!(end <= u64::from(u32::MAX), "the stamp is the tick");
            let watched = WATCHED_ENDS
                .iter()
                .position(|&e| (e.saturating_sub(WINDOW_TRIALS)..e).contains(&trial));
            each_spike(exec.train(), start as u32, end as u32, &mut |unit| {
                if let Some(n) = classes.get(unit).and_then(|&c| block.get_mut(c)) {
                    *n = n.saturating_add(1);
                }
                if watched.is_some() {
                    if let Some(n) = window.get_mut(unit) {
                        *n = n.saturating_add(1);
                    }
                }
            });
            if let Some(w) = watched {
                if trial.wrapping_add(1) == WATCHED_ENDS[w] {
                    fractions[w] = Some(at_target(&window, period));
                    window.iter_mut().for_each(|n| *n = 0);
                }
            }
            if let Some(f) = SCHEDULE_FLIPS.iter().position(|&f| f == trial) {
                at_flips[f] = Some(pair_couplings(exec, sets));
            }
            if trial.wrapping_add(1) % BLOCK == 0 {
                spikes.push(block);
                block = [0; CLASSES];
                inhibition.push(inhibition_by_class(exec, classes));
            }
        },
    );
    let at_flips = at_flips.map(|c| c.expect("the run reached the trial after every flip"));
    let at_target = fractions.map(|f| f.expect("the run read every window"));
    (
        run,
        moves,
        expected,
        Watched {
            at_flips,
            spikes,
            inhibition,
            at_target,
        },
    )
}

/// H-20's inhibitory course by block for an arm, as its pinned tables hold it: H-19's first 56
/// blocks and the 64 after them, each block's sum as a fraction of the image's in parts per ten
/// thousand. Read beside H-21's.
fn h20_course(k: usize, image: i64) -> Vec<i64> {
    course(
        image,
        &whole(
            CRITIC_BLOCKS_1024[k],
            REPLICATED_BLOCKS,
            SCHEDULE_BLOCKS_1024[k],
        ),
    )
}

/// One arm of H-21 at 1 024 units (brief 054): the calibration before any rewarded run (H-21's
/// stopping rule, step 2) — the settled engine held to ADR-0077 step by step and its images,
/// H-20's image by its CRC, a frozen block from the zero image held to ADR-0077's frozen run —
/// then the target's rule: the lead-in on the frozen image, the target it gives, and the
/// readings of the network it read, dumped and held to their pins before the image is written;
/// then the image each arm decodes, H-20's with the target written, shown to differ from H-20's
/// in the period and the section's seal alone, and decoded; then the arm's 7 680 trials from it
/// with H-20's critic and flips; everything dumped, the clauses and the readings computed before
/// anything is held; then the assertion, and the pinned tables of the whole run.
fn target_arm(arm: Reversal) {
    let k = TARGET_ARMS
        .iter()
        .position(|&a| a == arm)
        .expect("an arm of H-21");
    let name = format!("target1024 {arm:?}");
    let (zero, signed) = signed_images(&name);
    assert_eq!(
        pinned_crc(&signed),
        PUNISHED_IMAGE_CRC_1024,
        "{name}: H-20's image, H-19's and H-18's"
    );
    {
        let mut frozen = frozen_from(&zero, 1024);
        assert_eq!(
            (frozen.inhibitory_baseline_q16(), frozen.signed_gate()),
            (None, false),
            "{name}: the calibration's image leaves the inhibitory baseline and the signed gate unset"
        );
        let calibration = taught_run(&mut frozen, Arm::Withheld, 1024, BLOCK);
        calibration_holds(&format!("{name} calibration"), &calibration);
    }
    eprintln!("DUMP {name} calibration holds: ADR-0077's settled candidate and H-20's image");
    // The target's rule, on the settled image frozen, before the image is written.
    let windows = target_lead_in(&zero);
    let counts = summed(&windows);
    let window_spikes: Vec<u64> = windows.iter().map(|w| spikes_of(w)).collect();
    let period = target_period(1024, TARGET_LEAD_IN_TICKS, spikes_of(&counts));
    let sets = geometry(1024, ROTATION_1024);
    let mut exec = signed_from(&signed, 1024);
    let classes = classes_of(&exec, &sets);
    let settled_rates = rates(&counts, &classes, period, TARGET_LEAD_IN_TICKS);
    let at_start = [ISTDP_TARGET_PERIOD_TICKS, period].map(|p| {
        let mut out = [0u32; TARGET_LEAD_IN_WINDOWS as usize];
        for (into, w) in out.iter_mut().zip(&windows) {
            *into = at_target(w, p);
        }
        out
    });
    let image_sums = QUIET_1024[SETTLED].1;
    let image_inhibition = inhibition_by_class(&exec, &classes);
    eprintln!(
        "DUMP {name} PIN lead-in {window_spikes:?} period {period} alpha {} rates {settled_rates:?} at start {at_start:?} classes {:?} image inhibition {image_inhibition:?}",
        istdp_alpha_q1_15(period),
        class_sizes(&classes)
    );
    assert_eq!(
        window_spikes.as_slice(),
        TARGET_LEAD_IN_1024.as_slice(),
        "{name}: the lead-in's spikes by window"
    );
    assert_eq!(
        period, TARGET_PERIOD_1024,
        "{name}: the target the rule gives"
    );
    assert_eq!(
        settled_rates, TARGET_RATES_1024,
        "{name}: the settled rates"
    );
    assert_eq!(
        at_start, TARGET_AT_START_1024,
        "{name}: the fractions at the target"
    );
    assert_eq!(
        image_inhibition, TARGET_IMAGE_INHIBITION_1024,
        "{name}: the image's inhibition by class"
    );
    assert_eq!(
        image_inhibition.0.iter().sum::<i64>(),
        image_sums.0,
        "{name}: the classes hold the image's inhibition"
    );
    // The image each arm decodes: H-20's, the target written and nothing else.
    let targeted = targeted_image(&signed, period);
    assert!(
        only_the_target(&signed, &targeted),
        "{name}: the image is H-20's in every byte but the target period's and the seal"
    );
    exec = signed_from(&targeted, 1024);
    assert_eq!(
        exec.istdp_target_period_ticks(),
        period,
        "{name}: the image carries the target"
    );
    assert_eq!(
        weights_by_polarity(&exec),
        image_sums,
        "{name}: the image's sums"
    );
    assert_eq!(
        pair_couplings(&exec, &sets),
        IMAGE_COUPLINGS_1024,
        "{name}: the same image"
    );
    eprintln!(
        "DUMP {name} image crc {:#018x}, {} bytes differ from H-20's",
        crc64(&targeted),
        differing(&signed, &targeted).len()
    );
    let image = weights_of(&exec);
    let first = first_mapping(arm);
    let (run, moves, expected, watched) = target_run(&mut exec, arm, &sets, &classes);
    let (blocks, trace, trials, read, volley_ticks) = &run;
    let earned = earned_blocks(read);
    let compositions: Vec<Composition> = trials.chunks(BLOCK).map(composition).collect();
    let moved = moves_blocks(read, &moves);
    let expected_by_block = expected_blocks(&expected);
    let strong = strong_scheduled(read, first);
    assert_eq!(blocks.len(), SCHEDULE_BLOCKS, "{name}: 120 blocks");
    assert_eq!(
        (read.len(), expected.len()),
        (SCHEDULE_TRIALS, SCHEDULE_TRIALS)
    );
    assert_eq!(
        (
            compositions.len(),
            earned.len(),
            moved.len(),
            expected_by_block.len(),
            strong.len(),
            watched.spikes.len(),
            watched.inhibition.len()
        ),
        (
            SCHEDULE_BLOCKS,
            SCHEDULE_BLOCKS,
            SCHEDULE_BLOCKS,
            SCHEDULE_BLOCKS,
            SCHEDULE_BLOCKS - FLIP_BLOCK,
            SCHEDULE_BLOCKS,
            SCHEDULE_BLOCKS
        )
    );
    // The run's tables dumped whole, as they are pinned, before anything is held or read.
    eprintln!("DUMP {name} PIN blocks {blocks:?}");
    eprintln!("DUMP {name} PIN trace {trace:#018x}");
    eprintln!("DUMP {name} PIN compositions {compositions:?}");
    eprintln!("DUMP {name} PIN earned {earned:?}");
    eprintln!("DUMP {name} PIN read {:#018x}", earned_hash(read));
    eprintln!("DUMP {name} PIN census {:?}", census_of(volley_ticks));
    eprintln!("DUMP {name} PIN moves {moved:?}");
    eprintln!("DUMP {name} PIN expected {expected_by_block:?}");
    eprintln!("DUMP {name} PIN strong {strong:?}");
    eprintln!("DUMP {name} PIN at flips {:?}", watched.at_flips);
    eprintln!("DUMP {name} PIN spikes {:?}", watched.spikes);
    eprintln!("DUMP {name} PIN inhibition {:?}", watched.inhibition);
    eprintln!("DUMP {name} PIN at target {:?}", watched.at_target);
    // Everything read and dumped, and the clauses and the readings computed, before anything
    // else is held.
    dump_earned(&name, &run, &earned);
    let reach = reach_by_polarity(&exec, &image, 1024, &ALL_PAIRS);
    let below = first_below(image_sums.0, blocks);
    let low = lowest(image_sums.0, blocks);
    let correct = mapping_correct(blocks);
    let over = first_over(blocks);
    let first_new_read = first_new_scheduled(read, first);
    let crossings_read = crossings(blocks);
    let crossed = crossed_scheduled(&earned, first);
    let tally_read = tally(blocks);
    let settle = settle_scheduled(blocks, first);
    let highest_read = highest(blocks);
    let strong_sum = strong_by_flip(&strong);
    let punished_moves = moves_by_mapping(&moved, 1);
    let rewarded_moves = moves_by_mapping(&moved, 0);
    let once = once_blocks(blocks, &compositions);
    let falls = falls_every_block(image_sums.0, blocks);
    let sums_after = weights_by_polarity(&exec);
    eprintln!(
        "DUMP {name} PIN readings below {below:?} lowest {low:?} correct {correct:?} over {over:?} reach {reach:?} first new {first_new_read:?} crossings {crossings_read:?} crossed {crossed:?} tally {tally_read:?} settle {settle:?} highest {highest_read:?} strong total {strong_sum:?} punished moves {punished_moves:?} rewarded moves {rewarded_moves:?} once {once} falls {falls} sums after {sums_after:?}"
    );
    eprintln!(
        "DUMP {name} verdict of this arm: drain held {} learned {:?} over {over:?} settle per myriad {:?}",
        below.is_none(),
        correct.map(|c| c >= REWARDED_MIN),
        settle_per_myriad(settle, first)
    );
    eprintln!(
        "DUMP {name} inhibitory course {:?} beside H-20's {:?}",
        course(image_sums.0, blocks),
        h20_course(k, image_sums.0)
    );
    eprintln!(
        "DUMP {name} crossings {crossings_read:?} beside H-20's {:?}",
        CROSSINGS_1024[k]
    );
    eprintln!(
        "DUMP {name} couplings course {:?}",
        couplings_course(blocks)
    );
    eprintln!(
        "DUMP {name} expectations {expected_by_block:?} signal {:?}",
        blocks.iter().map(|b| b.9).collect::<Vec<i32>>()
    );
    // The assertion, after the dump and beside the verdict: H-18's rule, as H-20 holds it.
    assert!(
        punished_held(&reach),
        "{name}: no excitatory synapse outside the four stimulus–readout pairs moved: {reach:?}"
    );
    // The pinned tables of the whole run, and the readings as the constants state.
    pinned(
        &format!("{name} sight"),
        blocks,
        *trace,
        TARGET_BLOCKS_1024[k],
        TARGET_TRACES_1024[k],
    );
    assert_eq!(
        compositions.as_slice(),
        TARGET_COMPOSITIONS_1024[k],
        "{name}: the composition per block"
    );
    assert_eq!(
        earned.as_slice(),
        TARGET_EARNED_1024[k],
        "{name}: the earned blocks"
    );
    assert_eq!(
        earned_hash(read),
        TARGET_READ_1024[k],
        "{name}: the readings"
    );
    assert_eq!(
        census_of(volley_ticks),
        TARGET_CENSUS_1024[k].to_vec(),
        "{name}: the volley's ticks"
    );
    assert_eq!(
        moved.as_slice(),
        TARGET_MOVES_1024[k],
        "{name}: the moves per block"
    );
    assert_eq!(
        expected_by_block.as_slice(),
        TARGET_EXPECTED_1024[k],
        "{name}: the expectations per block"
    );
    assert_eq!(
        strong.as_slice(),
        TARGET_STRONG_1024[k],
        "{name}: the strong punishments per block"
    );
    assert_eq!(watched.at_flips, TARGET_AT_FLIPS_1024[k]);
    assert_eq!(
        watched.spikes.as_slice(),
        TARGET_SPIKES_1024[k],
        "{name}: the spikes by class per block"
    );
    assert_eq!(
        watched.inhibition.as_slice(),
        TARGET_INHIBITION_1024[k],
        "{name}: the inhibition by class per block"
    );
    assert_eq!(watched.at_target, TARGET_AT_TARGET_1024[k]);
    assert_eq!(below, BELOW_1024[k]);
    assert_eq!(low, LOWEST_1024[k]);
    assert_eq!(correct, CORRECT_TARGET_1024[k]);
    assert_eq!(over, OVER_TARGET_1024[k]);
    assert_eq!(reach, REACH_TARGET_1024[k]);
    assert_eq!(first_new_read, FIRST_NEW_TARGET_1024[k]);
    assert_eq!(crossings_read, CROSSINGS_TARGET_1024[k]);
    assert_eq!(crossed, CROSSED_TARGET_1024[k]);
    assert_eq!(tally_read, TALLY_TARGET_1024[k]);
    assert_eq!(settle, SETTLE_TARGET_1024[k]);
    assert_eq!(highest_read, HIGHEST_TARGET_1024[k]);
    assert_eq!(strong_sum, STRONG_BY_FLIP_TARGET_1024[k]);
    assert_eq!(punished_moves, PUNISHED_MOVES_TARGET_1024[k]);
    assert_eq!(rewarded_moves, REWARDED_MOVES_TARGET_1024[k]);
    assert_eq!(once, ONCE_BLOCKS_TARGET_1024[k]);
    assert_eq!(falls, FALLS_TARGET_1024[k]);
    assert_eq!(
        (sums_after, blocks.last().map(|b| (b.7, b.8))),
        (SUMS_AFTER_TARGET_1024[k], Some(SUMS_AFTER_TARGET_1024[k])),
        "{name}: the sums after the run are the last block's"
    );
}

/// H-21's arm that starts from the assignment (brief 054): H-20's arm from the assignment
/// with the inhibitory rule's target at the settled network's rate.
#[test]
#[ignore]
fn a_target_the_network_fires_at_from_the_assignment_at_1024_units_exhaustive() {
    target_arm(Reversal::AssignmentFirst);
}

/// H-21's arm that starts from the mirrored assignment (brief 054): H-20's arm from the
/// mirrored assignment with the inhibitory rule's target at the settled network's rate.
#[test]
#[ignore]
fn a_target_the_network_fires_at_from_the_mirrored_assignment_at_1024_units_exhaustive() {
    target_arm(Reversal::MirroredFirst);
}

/// The gate's test (ADR-0061's class; brief 054): the arms and the constants as ADR-0128 fixed
/// them, H-20's restated; the target's rule over a table written by hand — the rounding, the
/// bounds, a network that did not fire, and the default's own rate giving the default; H-21's
/// clause 1 at its edges over blocks written by hand and the verdict naming the clause, the arm
/// and the block; the readings' rules over counts, trains and tables written by hand; the
/// classes and the inhibition by class on the instrument's network, its every inhibitory
/// synapse at the rail; and the image's patch on that network's image, shown to touch the
/// target period's four bytes and the section's seal alone, to be read by the loader, and to
/// be undone by writing the old period back. No run, and nothing else added to the gate.
#[test]
fn the_target_s_rule_the_clauses_of_h_21_and_the_image_s_patch() {
    // The arms and the constants, H-20's restated.
    assert_eq!(TARGET_ARMS, SCHEDULE_ARMS);
    assert_eq!(
        SCHEDULE_ARMS,
        [Reversal::AssignmentFirst, Reversal::MirroredFirst]
    );
    assert_eq!(TARGET_PREDICTED, None, "ADR-0128 predicts no verdict");
    assert_eq!(DRAIN_FLOOR_PER_CENT, 50);
    assert_eq!(
        (
            TARGET_LEAD_IN_TICKS,
            TARGET_LEAD_IN_WINDOWS,
            WINDOW_TICKS,
            WINDOW_TRIALS
        ),
        (1 << 20, 8, 1 << 17, 8)
    );
    assert_eq!(WATCHED_ENDS, [1_536, 3_584, 5_632, 7_680]);
    assert_eq!((TARGET_PERIOD_AT, RAIL_Q1_15, CLASSES), (20, -32_767, 4));
    assert_eq!(QUANTILES, [0, 10, 25, 50, 75, 90, 100]);
    assert_eq!(
        (SCHEDULE_TRIALS, SCHEDULE_BLOCKS, SCHEDULE_FLIPS),
        (7_680, 120, [1_536, 3_584, 5_632])
    );
    assert_eq!(MAPPINGS, [(0, 24), (24, 56), (56, 88), (88, 120)]);
    assert_eq!((BOUND_PER_CENT, REWARDED_MIN, LAST_BLOCKS), (130, 80, 2));
    assert_eq!(
        CRITIC_AT_START,
        Critic {
            expected_q16: [0; 2],
            shift: 5
        }
    );
    assert_eq!((GATE_BASELINE_Q16, INHIBITORY_BASELINE_Q16), (0, 0x8000));
    assert_eq!(
        PUNISHED_IMAGE_CRC_1024, 0xc9e0_2d60_0792_7029,
        "H-20's image, at format 25 (ADR-0202)"
    );
    assert_eq!(
        (
            ISTDP_TARGET_PERIOD_TICKS,
            ISTDP_PERIOD_MIN_TICKS,
            ISTDP_PERIOD_MAX_TICKS
        ),
        (20_000, 100, 1_000_000),
        "ADR-0053's default and bounds"
    );
    // The target's rule over a table written by hand: `(units, ticks, spikes)` and the period.
    let table: [((u64, u64, u64), u32); 16] = [
        // The rounding from the exact quotient: 1 000.5, 1 001.5 and 999.5 go up; 428.57 up,
        // 333.33 down, 375 exact.
        ((1, 2_001, 2), 1_001),
        ((1, 2_003, 2), 1_002),
        ((1, 1_999, 2), 1_000),
        ((3, 1_000, 7), 429),
        ((1, 1_000, 3), 333),
        ((3, 1_000, 8), 375),
        // The bounds: 99 is clamped up to 100, 1 000 001 down to 1 000 000; at the bounds, as is.
        ((1, 99, 1), 100),
        ((1, 100, 1), 100),
        ((1, 1_000_000, 1), 1_000_000),
        ((1, 1_000_001, 1), 1_000_000),
        // A network that did not fire: the longest period.
        ((1_024, 1 << 20, 0), 1_000_000),
        // At 1 024 units over the lead-in: the default's 5 Hz, 53 687 spikes, gives the default
        // period; ADR-0117's 1.68 Hz, 18 039 spikes, gives 59 523; 18 000 gives 59 652.
        ((1_024, 1 << 20, 53_687), 20_000),
        ((1_024, 1 << 20, 18_039), 59_523),
        ((1_024, 1 << 20, 18_000), 59_652),
        // One spike more or fewer moves the period by about three ticks there.
        ((1_024, 1 << 20, 18_001), 59_649),
        ((1_024, 1 << 20, 17_999), 59_656),
    ];
    for ((units, ticks, spikes), period) in table {
        assert_eq!(
            target_period(units, ticks, spikes),
            period,
            "{units} units, {ticks} ticks, {spikes} spikes"
        );
    }
    // The depression the rule's period gives, beside the default's: 22 against 67.
    assert_eq!(
        (
            istdp_alpha_q1_15(59_652),
            istdp_alpha_q1_15(ISTDP_TARGET_PERIOD_TICKS)
        ),
        (22, 67)
    );
    // Clause 1 at its edges over blocks written by hand, the image's sum 165 876 268 (even) and
    // 3 (odd): half of it holds and one LSB below does not, at the first block, the 56th and the
    // last; the first block below named; a run of any other length does not hold.
    let image = QUIET_1024[SETTLED].1.0;
    assert_eq!(image, 165_876_268, "the settled image's inhibitory sum");
    let half = image / 2;
    assert!(!drained_below(half, image) && drained_below(half.saturating_sub(1), image));
    assert!(
        !drained_below(2, 3) && drained_below(1, 3),
        "half of an odd sum"
    );
    assert!(!drained_below(image, image) && !drained_below(image.saturating_mul(2), image));
    let blocks_at = |sum: i64| -> Vec<Block> {
        vec![
            (
                BLOCK as u32,
                0,
                [[0; 2]; 2],
                [0; 2],
                [0; 2],
                [0; 2],
                0,
                sum,
                0,
                0,
                IMAGE_COUPLINGS_1024,
                0,
            );
            SCHEDULE_BLOCKS
        ]
    };
    let full = blocks_at(image);
    let learning_yes = Scheduled {
        learned: [[true; 4]; 2],
        bounded: [true; 2],
        over: [None; 2],
        yes: true,
    };
    assert_eq!(scheduled([&full, &full]), learning_yes);
    assert_eq!(
        targeted(image, [&full, &full]),
        Targeted {
            held: [true; 2],
            below: [None; 2],
            learning: learning_yes,
            yes: true
        },
        "every block at the image's sum, every mapping learned: yes"
    );
    assert_eq!(lowest(image, &full), Some((10_000, 0)));
    for j in [0, REPLICATED_BLOCKS - 1, SCHEDULE_BLOCKS - 1] {
        let mut run = full.clone();
        run[j].7 = half;
        assert_eq!(first_below(image, &run), None, "block {j} at half");
        assert!(targeted(image, [&run, &run]).yes);
        assert_eq!(lowest(image, &run), Some((5_000, j)));
        run[j].7 = half.saturating_sub(1);
        assert_eq!(first_below(image, &run), Some(j), "block {j} one LSB below");
        assert_eq!(
            targeted(image, [&full, &run]),
            Targeted {
                held: [true, false],
                below: [None, Some(j)],
                learning: learning_yes,
                yes: false
            },
            "block {j}: clause 1 fails in the second arm there"
        );
        assert_eq!(
            targeted(image, [&run, &full]).held,
            [false, true],
            "and in the first"
        );
    }
    let mut twice = full.clone();
    twice[40].7 = 0;
    twice[90].7 = 0;
    assert_eq!(
        first_below(image, &twice),
        Some(40),
        "the first block below"
    );
    assert_eq!(lowest(image, &twice), Some((0, 40)), "the first lowest");
    assert_eq!(
        targeted(image, [&full[..SCHEDULE_BLOCKS - 1], &full]),
        Targeted {
            held: [false, true],
            below: [None; 2],
            learning: Scheduled {
                learned: [[false; 4], [true; 4]],
                bounded: [false, true],
                over: [None; 2],
                yes: false
            },
            yes: false
        },
        "a run short of 7 680 holds no clause"
    );
    let mut unlearned = full.clone();
    unlearned[MAPPINGS[2].1.saturating_sub(1)].0 = 0;
    unlearned[MAPPINGS[2].1.saturating_sub(2)].0 = 0;
    let verdict = targeted(image, [&full, &unlearned]);
    assert_eq!(
        (verdict.held, verdict.learning.learned[1], verdict.yes),
        ([true; 2], [true, true, false, true], false),
        "the drain held and the third mapping unlearned in the second arm: clause 2 fails"
    );
    assert_eq!(lowest(image, &[]), None);
    // ADR-0057's rule over counts written by hand: at the rule's period of about 59 652 ticks
    // the target is two spikes a window and the band 1 to 4; at the default's, six and 3 to 12.
    let counts = [0u32, 1, 2, 3, 4, 5, 6, 12, 13];
    assert_eq!(WINDOW_TICKS / 59_652, 2);
    assert_eq!(at_target(&counts, 59_652), (4 << 16) / 9, "1, 2, 3 and 4");
    assert_eq!(
        at_target(&counts, ISTDP_TARGET_PERIOD_TICKS),
        (5 << 16) / 9,
        "3, 4, 5, 6 and 12"
    );
    assert_eq!(at_target(&[], 59_652), 0);
    // The rates over counts written by hand, eleven units of four classes over 2^20 ticks at a
    // period of 2^16, so that sixteen spikes is the target.
    let counts = [0u32, 16, 15, 17, 3, 40, 16, 0, 9, 30, 15];
    let classes = [0usize, 0, 1, 1, 2, 2, 2, 2, 3, 3, 3];
    assert_eq!(
        rates(&counts, &classes, 1 << 16, 1 << 20),
        ([0, 0, 3, 15, 16, 30, 40], 2, [2, 2, 4, 3], [1, 1, 2, 1])
    );
    // A trial's spikes from a train written by hand: those in [100, 200) and no other, the
    // train read from its end back.
    let train = [
        (90u32, 0u32),
        (99, 1),
        (100, 2),
        (150, 3),
        (150, 2),
        (199, 1),
        (200, 0),
    ];
    let mut seen = Vec::new();
    each_spike(&train, 100, 200, &mut |u| seen.push(u));
    assert_eq!(seen, [1, 2, 3, 2]);
    let mut none = Vec::new();
    each_spike(&train, 300, 400, &mut |u| none.push(u));
    assert!(none.is_empty());
    assert_eq!(summed(&[vec![1, 2], vec![3, 0]]), [4, 2]);
    assert_eq!(spikes_of(&[4, 2]), 6);
    // The classes and the inhibition by class on the instrument's network at 1 024 units: 204
    // inhibitory units, 102 of the stimulus sets, 714 of the readout sets and the four past the
    // last period; every inhibitory synapse at the rail, the prior's sum held by the classes.
    let p = prior(1024);
    let exec = at_gain(&p, config(1024, 2, 0), GAIN_1024);
    let sets = geometry(1024, ROTATION_1024);
    let classes = classes_of(&exec, &sets);
    assert_eq!(class_sizes(&classes), [204, 102, 714, 4]);
    let inhibition = inhibition_by_class(&exec, &classes);
    assert_eq!(inhibition.0.iter().sum::<i64>(), PRIOR_SUMS_1024.0);
    assert_eq!(
        i64::from(inhibition.1).saturating_mul(i64::from(i16::MAX)),
        PRIOR_SUMS_1024.0,
        "every inhibitory synapse of the prior at the rail"
    );
    // The image's patch on the network's image: the period written touches its four bytes and
    // the section's entry alone; the loader reads it; the old period written back undoes it;
    // a byte moved elsewhere fails the check; and a period outside the bounds is refused by
    // the loader, so the bytes are the ones it reads.
    let img = Image::encode(&exec).expect("quiescent");
    let patched = targeted_image(&img, 59_652);
    let moved = differing(&img, &patched);
    let (at, offset, _) = modulator_entry(&img);
    let period_bytes = offset.saturating_add(20)..offset.saturating_add(24);
    let entry_bytes = at..at.saturating_add(64);
    assert!(
        !moved.is_empty()
            && moved.len() <= 12
            && moved
                .iter()
                .all(|p| period_bytes.contains(p) || entry_bytes.contains(p)),
        "the period's bytes and the entry's seal: {moved:?}"
    );
    assert!(only_the_target(&img, &patched));
    assert!(
        only_the_target(&img, &img),
        "nothing written, nothing moved"
    );
    assert_eq!(targeted_image(&patched, ISTDP_TARGET_PERIOD_TICKS), img);
    let decoded = Image::decode::<2048>(&patched, config(1024, 2, 0)).expect("a well-formed image");
    assert_eq!(decoded.istdp_target_period_ticks(), 59_652);
    assert_eq!(weights_of(&decoded), weights_of(&exec));
    let mut elsewhere = patched.clone();
    elsewhere[offset.saturating_add(16)] ^= 1;
    assert!(!only_the_target(&img, &elsewhere), "the baseline's byte");
    for period in [ISTDP_PERIOD_MIN_TICKS - 1, ISTDP_PERIOD_MAX_TICKS + 1] {
        assert!(
            matches!(
                Image::decode::<2048>(&targeted_image(&img, period), config(1024, 2, 0)),
                Err(ImageError::Config(ConfigError::IstdpPeriodOutOfRange))
            ),
            "{period}: refused by the loader"
        );
    }
    // Over the lead-in's pins: the rule gives the pinned target from the pinned spikes, 18 449
    // at 1 024 units over 2^20 ticks; its depression is 23; the rates' classes are the
    // classes, and every unit is counted; the image's inhibition by class sums to the settled
    // image's, and fewer of its synapses sit at the rail than the prior's 6 528 (F-59).
    let spikes: u64 = TARGET_LEAD_IN_1024.iter().sum();
    assert_eq!(spikes, 18_449);
    assert_eq!(
        target_period(1024, TARGET_LEAD_IN_TICKS, spikes),
        TARGET_PERIOD_1024
    );
    assert_eq!(
        (TARGET_PERIOD_1024, istdp_alpha_q1_15(TARGET_PERIOD_1024)),
        (58_201, 23)
    );
    assert_eq!(TARGET_RATES_1024.2, [204, 102, 714, 4]);
    assert_eq!(TARGET_RATES_1024.2.iter().sum::<u32>(), 1024);
    assert_eq!(
        TARGET_IMAGE_INHIBITION_1024.0.iter().sum::<i64>(),
        QUIET_1024[SETTLED].1.0
    );
    assert!(TARGET_IMAGE_INHIBITION_1024.1 < inhibition.1);
    // Over the arms' pinned tables: the verdict as written, by the rule committed first; the
    // readings as the constants state; and, block by block over each arm's 120 blocks, the tables
    // consistent with one another, with the assertion, with the oracle and with the train's
    // reading — each block's inhibition by class summing to its inhibitory sum, the stimulus
    // class's spikes the stimulus sets' own spikes the harness counts, each coupling the one
    // before plus what the oracle consolidated, the excitatory sum the image's plus the four
    // pairs' moves, and each expectation within the reward.
    let image = QUIET_1024[SETTLED].1;
    let h20 = whole(
        CRITIC_BLOCKS_1024[0],
        REPLICATED_BLOCKS,
        SCHEDULE_BLOCKS_1024[0],
    );
    let verdict = targeted(image.0, [TARGET_BLOCKS_1024[0], TARGET_BLOCKS_1024[1]]);
    assert_eq!(verdict, TARGET_1024, "the verdict as written");
    assert_eq!(TARGET_PREDICTED, None, "and no prediction to hold it to");
    for (k, &arm) in TARGET_ARMS.iter().enumerate() {
        let first = first_mapping(arm);
        let blocks = TARGET_BLOCKS_1024[k];
        let earned = TARGET_EARNED_1024[k];
        let moved = TARGET_MOVES_1024[k];
        let compositions = TARGET_COMPOSITIONS_1024[k];
        let expected = TARGET_EXPECTED_1024[k];
        let strong = TARGET_STRONG_1024[k];
        let spikes = TARGET_SPIKES_1024[k];
        let inhibition = TARGET_INHIBITION_1024[k];
        assert_eq!(
            [
                blocks.len(),
                compositions.len(),
                earned.len(),
                moved.len(),
                expected.len(),
                spikes.len(),
                inhibition.len()
            ],
            [SCHEDULE_BLOCKS; 7],
            "{arm:?}: 120 blocks of each"
        );
        assert_eq!(strong.len(), SCHEDULE_BLOCKS - FLIP_BLOCK);
        assert_ne!(TARGET_TRACES_1024[k], 0);
        assert_ne!(TARGET_READ_1024[k], 0);
        assert!(!TARGET_CENSUS_1024[k].is_empty());
        let below = first_below(image.0, blocks);
        assert_eq!(below, BELOW_1024[k]);
        assert_eq!(below.is_none(), verdict.held[k]);
        assert_eq!(lowest(image.0, blocks), LOWEST_1024[k]);
        let correct = mapping_correct(blocks);
        assert_eq!(correct, CORRECT_TARGET_1024[k]);
        assert_eq!(
            correct.map(|c| c >= REWARDED_MIN),
            verdict.learning.learned[k]
        );
        assert_eq!(first_over(blocks), OVER_TARGET_1024[k]);
        assert_eq!(first_over(blocks).is_none(), verdict.learning.bounded[k]);
        assert_eq!(crossings(blocks), CROSSINGS_TARGET_1024[k]);
        assert_eq!(crossed_scheduled(earned, first), CROSSED_TARGET_1024[k]);
        assert_eq!(tally(blocks), TALLY_TARGET_1024[k]);
        assert_eq!(settle_scheduled(blocks, first), SETTLE_TARGET_1024[k]);
        assert_eq!(highest(blocks), HIGHEST_TARGET_1024[k]);
        assert_eq!(strong_by_flip(strong), STRONG_BY_FLIP_TARGET_1024[k]);
        assert_eq!(moves_by_mapping(moved, 1), PUNISHED_MOVES_TARGET_1024[k]);
        assert_eq!(moves_by_mapping(moved, 0), REWARDED_MOVES_TARGET_1024[k]);
        assert_eq!(
            once_blocks(blocks, compositions),
            ONCE_BLOCKS_TARGET_1024[k]
        );
        assert_eq!(falls_every_block(image.0, blocks), FALLS_TARGET_1024[k]);
        assert!(
            punished_held(&REACH_TARGET_1024[k]),
            "{arm:?}: the assertion held"
        );
        let last = blocks.last().expect("a block");
        assert_eq!(SUMS_AFTER_TARGET_1024[k], (last.7, last.8));
        for (j, e) in expected.iter().enumerate() {
            assert!(
                e.iter().all(|v| v.unsigned_abs() <= ONE.unsigned_abs()),
                "{arm:?} block {j}: each expectation within the reward: {e:?}"
            );
        }
        let mut previous = IMAGE_COUPLINGS_1024;
        for (j, block) in blocks.iter().enumerate() {
            let in_force = mirrored_at(first, j);
            assert_eq!(
                inhibition[j].0.iter().sum::<i64>(),
                block.7,
                "{arm:?} block {j}: the classes hold the inhibitory sum"
            );
            assert_eq!(
                spikes[j][1],
                block.4[0].saturating_add(block.4[1]),
                "{arm:?} block {j}: the stimulus class's spikes are the stimulus sets' own"
            );
            assert_eq!(
                block.1, TARGET_BLOCKS_1024[0][j].1,
                "{arm:?} block {j}: the same trials present A in both arms"
            );
            assert_eq!(block.1, h20[j].1, "{arm:?} block {j}: and in H-20's");
            let presented = [block.1, (BLOCK as u32).saturating_sub(block.1)];
            for (s, &n) in presented.iter().enumerate() {
                assert_eq!(
                    earned[j].0[s].iter().sum::<u32>(),
                    n,
                    "{arm:?} block {j}: every presentation of {s} selected or tied"
                );
            }
            assert_eq!(
                block.11,
                earned[j].0[0][2].saturating_add(earned[j].0[1][2]),
                "{arm:?} block {j}: the ties"
            );
            let correct = earned[j].0[0][answer_of(0, in_force)]
                .saturating_add(earned[j].0[1][answer_of(1, in_force)]);
            assert_eq!(
                block.0, correct,
                "{arm:?} block {j}: correct under the mapping in force"
            );
            let mut rise = 0i64;
            let mut consolidated = 0i64;
            for &(s, r) in &ALL_PAIRS {
                assert_eq!(
                    block.10[s][r],
                    previous[s][r].saturating_add(earned[j].2[s][r]),
                    "{arm:?} block {j}: {s}→{r} moved by what the oracle consolidated"
                );
                rise =
                    rise.saturating_add(block.10[s][r].saturating_sub(IMAGE_COUPLINGS_1024[s][r]));
                consolidated = consolidated.saturating_add(earned[j].2[s][r]);
            }
            assert_eq!(
                block.8,
                image.1.saturating_add(rise),
                "{arm:?} block {j}: the excitatory sum moved by the four pairs' moves and nothing else"
            );
            let moved_sum = moved[j]
                .iter()
                .flat_map(|m| m.1.iter())
                .fold(0i64, |sum, &a| sum.saturating_add(a));
            assert_eq!(
                moved_sum, consolidated,
                "{arm:?} block {j}: what the addressed synapses moved is what the oracle consolidated"
            );
            previous = block.10;
        }
    }
}

// --------------------- the measurement (brief 054), its tables in inhibition/pins/h21.rs

/// The target's lead-in at 1 024 units, pinned from its first run before any rewarded run: the
/// spikes of each of its eight windows, 18 449 in all, 1.718 Hz a unit.
const TARGET_LEAD_IN_1024: [u64; 8] = [2367, 2310, 2349, 2261, 2274, 2312, 2338, 2238];
/// The target the rule gives from them, pinned before any rewarded run: 58 201 ticks, where the
/// depression per spike is 23, against the default's 20 000 and 67.
const TARGET_PERIOD_1024: u32 = 58201;
/// The settled image's inhibition by class and its synapses at the rail: 45 of 6 528 (F-59).
const TARGET_IMAGE_INHIBITION_1024: ClassInhibition = ([23484143, 17014646, 124682554, 694925], 45);

const TARGET_TRACES_1024: [u64; 2] = [0xde1db3a9d0229c28, 0x8e3df2a2880105e4];
const TARGET_READ_1024: [u64; 2] = [0x6a55577b78aa3ee3, 0xc993ae1f857b651b];
const BELOW_1024: [Option<usize>; 2] = [None, None];
const LOWEST_1024: [Option<(i64, usize)>; 2] = [Some((8478, 119)), Some((8477, 119))];
const CORRECT_TARGET_1024: [[u32; 4]; 2] = [[121, 119, 115, 119], [124, 113, 115, 119]];
const OVER_TARGET_1024: [Option<(usize, usize, usize)>; 2] = [None, None];
const ONCE_BLOCKS_TARGET_1024: [u32; 2] = [120, 120];
const FALLS_TARGET_1024: [bool; 2] = [false, false];
const SUMS_AFTER_TARGET_1024: [(i64, i64); 2] = [(140646239, 219907303), (140624296, 220366324)];

// =================================================================================== H-22

// -------------------------------------------- written before the run (ADR-0130, ADR-0132)

/// The arms of H-22 (ADR-0130): H-21's two, in their order, each its own weekly test, from
/// H-21's image with the engine's critic written, the task carrying no critic of its own, and
/// H-20's flips.
const VALUED_ARMS: [Reversal; 2] = TARGET_ARMS;

/// ADR-0130 writes no prediction for the verdict.
const VALUED_PREDICTED: Option<bool> = None;

/// The engine's critic (ADR-0132), placed by the arithmetic written before the first rewarded
/// run: a step of $2^{-9}$ and a scale of $2^{-2}$. Their sum, eleven, is the least at which
/// one stimulus volley of `VOLLEY_UNITS` spikes moves the value of the same volley by at most
/// the task critic's thirty-second of the error — 51/2 048, about a fortieth; the scale puts a
/// weight's rail at an eighth of the reward a spike and the volley's share of the reward at a
/// sixth of it; the shift leaves a positive error below 512, 0.8 per cent of the reward, moving
/// nothing. It does not move after a rewarded run.
const VALUED_CRITIC: ValueCritic = ValueCritic { shift: 9, scale: 2 };

/// The stimulus's volley at 1 024 units: each of its set's 51 units once a trial (ADR-0076).
const VOLLEY_UNITS: u32 = 51;

/// The task critic's step, H-21's: a thirty-second of the error (ADR-0106).
const TASK_STEP_SHIFT: u32 = 5;
const _: () = assert!(TASK_STEP_SHIFT == CRITIC_SHIFT);

// The arithmetic's two inequalities: the volley times 32 fits the step and the scale's
// 2^11 and not 2^10.
const _: () = assert!(
    (VOLLEY_UNITS as u64) << TASK_STEP_SHIFT <= 1 << (VALUED_CRITIC.shift + VALUED_CRITIC.scale)
        && (VOLLEY_UNITS as u64) << TASK_STEP_SHIFT
            > 1 << (VALUED_CRITIC.shift + VALUED_CRITIC.scale - 1)
);

/// Clause 3's bound (ADR-0130): the mean error over the correct trials of a mapping's last 128
/// at most half the reward's magnitude, read in integers as `errors × 2 ≤ reward × correct`,
/// with at least one correct trial.
const PREDICTS_DIVISOR: i64 = 2;

/// Where the modulator section holds the critic (ADR-0131): its flag, its shift and its scale
/// at `[48]`, `[49]` and `[50]`.
const CRITIC_AT: usize = 48;

/// The groups the value weights are read in (brief 055), in this order: inhibitory, whatever
/// set holds it; an excitatory unit of stimulus A's set; of stimulus B's; of readout 0's; of
/// readout 1's; any other unit.
const GROUPS: usize = 6;

// ------------------------------------------------------------ the criterion (ADR-0130)

/// Clause 3's reading over a span of trials: the errors the correct trials delivered — the
/// reward the task records being the error the modulator received — summed, and their count.
fn correct_errors(read: &[EarnedTrial]) -> (i64, u32) {
    read.iter()
        .filter(|t| t.3)
        .fold((0i64, 0u32), |(sum, n), t| {
            (sum.saturating_add(i64::from(t.4)), n.saturating_add(1))
        })
}

/// Clause 3's counts per mapping: over its last `LAST_BLOCKS` blocks' trials, 1 409 to 1 536,
/// 3 457 to 3 584, 5 505 to 5 632 and 7 553 to 7 680; zeros for a run of any other length.
fn mapping_errors(read: &[EarnedTrial]) -> [(i64, u32); 4] {
    if read.len() != SCHEDULE_TRIALS {
        return [(0, 0); 4];
    }
    SPANS.map(|(_, end)| {
        correct_errors(
            read.get(end.saturating_sub(LAST_BLOCKS.saturating_mul(BLOCK))..end)
                .unwrap_or(&[]),
        )
    })
}

/// Clause 3's rule (ADR-0130): at least one correct trial, and their mean error at most half the
/// reward's magnitude, `errors × 2 ≤ reward × correct`.
fn predicts(errors: i64, correct: u32) -> bool {
    correct > 0
        && errors.saturating_mul(PREDICTS_DIVISOR)
            <= i64::from(REWARD_Q16).saturating_mul(i64::from(correct))
}

/// H-22's criterion (ADR-0130), clause by clause per arm `[assignment first, mirrored first]`:
/// (1) each mapping learned and (2) the couplings bounded, H-20's two as `scheduled` reads them,
/// and (3) the critic predicts, per mapping, `predicts` over its last 128 trials. `yes` is all
/// in both arms; a no names the clause, the arm and the mapping.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct Valued {
    learning: Scheduled,
    predicted: [[bool; 4]; 2],
    yes: bool,
}

fn valued(arms: [&[Block]; 2], errors: [[(i64, u32); 4]; 2]) -> Valued {
    let learning = scheduled(arms);
    let predicted = errors.map(|mapping| mapping.map(|(sum, n)| predicts(sum, n)));
    Valued {
        learning,
        predicted,
        yes: learning.yes && predicted.iter().flatten().all(|&p| p),
    }
}

// ----------------------------------------------------- the readings' shape (brief 055)

/// Each unit's group in `GROUPS`'s order, by its position in the arena.
fn groups_of(exec: &Engine, sets: &[Set; 4]) -> Vec<usize> {
    exec.units()
        .iter()
        .enumerate()
        .map(|(position, unit)| {
            assert_eq!(unit.id, position as u64, "a unit's id is its position");
            let id = position as u32;
            if unit.flags & FLAG_INHIBITORY != 0 {
                0
            } else {
                sets.iter()
                    .position(|set| set.contains(id))
                    .map_or(5, |s| s.saturating_add(1))
            }
        })
        .collect()
}

/// The units of each group.
fn group_sizes(groups: &[usize]) -> [u32; GROUPS] {
    let mut out = [0u32; GROUPS];
    for &g in groups {
        if let Some(n) = out.get_mut(g) {
            *n = n.saturating_add(1);
        }
    }
    out
}

/// The value weights by group (brief 055): each group's weights summed, and the lowest and the
/// highest weight of any unit.
type Weights = ([i64; GROUPS], i16, i16);

fn weights_by_group(exec: &Engine, groups: &[usize]) -> Weights {
    let mut out: Weights = ([0; GROUPS], 0, 0);
    for (unit, &g) in exec.units().iter().zip(groups) {
        if let Some(sum) = out.0.get_mut(g) {
            *sum = sum.saturating_add(i64::from(unit.value_weight));
        }
        out.1 = out.1.min(unit.value_weight);
        out.2 = out.2.max(unit.value_weight);
    }
    out
}

/// The engine's value by block (brief 055), per stimulus: its trials, their values summed, its
/// correct trials, and their errors summed.
type ValueBlock = [[i64; 4]; 2];

fn value_blocks(read: &[EarnedTrial], values: &[i32]) -> Vec<ValueBlock> {
    assert_eq!(read.len(), values.len(), "a value a trial");
    read.chunks(BLOCK)
        .zip(values.chunks(BLOCK))
        .map(|(trials, values)| {
            let mut out: ValueBlock = [[0; 4]; 2];
            for (t, &v) in trials.iter().zip(values) {
                let s = &mut out[usize::from(t.0)];
                s[0] = s[0].saturating_add(1);
                s[1] = s[1].saturating_add(i64::from(v));
                if t.3 {
                    s[2] = s[2].saturating_add(1);
                    s[3] = s[3].saturating_add(i64::from(t.4));
                }
            }
            out
        })
        .collect()
}

/// The FNV-1a of every trial's value.
fn values_hash(values: &[i32]) -> u64 {
    fnv1a_64(values)
}

/// A block's mean value per stimulus, truncated toward zero; zero for a stimulus the block did
/// not present.
fn mean_values(block: &ValueBlock) -> [i64; 2] {
    block.map(|s| s[1].checked_div(s[0]).unwrap_or(0))
}

// ---------------------------------------------------------------- the image (brief 055)

/// The image with the modulator section's `[48..51)` written `bytes` and the section re-sealed;
/// every other byte the image's.
fn with_critic_bytes(image: &[u8], bytes: [u8; 3]) -> Vec<u8> {
    let mut img = image.to_vec();
    let (at, offset, length) = modulator_entry(&img);
    img[offset..][CRITIC_AT..][..3].copy_from_slice(&bytes);
    let mut entry = SectionEntry::decode(img[at..][..64].try_into().unwrap());
    entry.crc64 = crc64(&img[offset..][..length]);
    img[at..][..64].copy_from_slice(&entry.encode());
    img
}

/// The image with the engine's critic written: its flag set and its constants. The image each
/// arm of H-22 decodes is H-21's image so written.
fn valued_image(image: &[u8], critic: ValueCritic) -> Vec<u8> {
    with_critic_bytes(image, [1, critic.shift, critic.scale])
}

/// The masked check (ADR-0132's one change): `valued` differs from `image` only in the
/// modulator section's three bytes of the critic and in the section's entry in the table, which
/// holds its seal; and writing zeros back gives `image` bit for bit.
fn only_the_critic(image: &[u8], valued: &[u8]) -> bool {
    let (at, offset, _) = modulator_entry(image);
    let critic = offset.saturating_add(CRITIC_AT);
    let entry = at..at.saturating_add(64);
    let mask = critic..critic.saturating_add(3);
    image.len() == valued.len()
        && image[mask.clone()] == [0; 3]
        && differing(image, valued)
            .iter()
            .all(|p| mask.contains(p) || entry.contains(p))
        && with_critic_bytes(valued, [0; 3]) == image
}

// ---------------------------------------------------------------- the run (brief 055)

/// H-21's first block from H-21's image with the engine's critic unset (H-22's calibration,
/// ADR-0130's stopping rule step 2): H-21's run for one block — the task's critic, the arm's
/// first mapping — held to H-21's pinned first block table by table.
fn h21_first_block(targeted: &[u8], arm: Reversal, k: usize, name: &str) {
    let mut exec = signed_from(targeted, 1024);
    assert_eq!(
        (exec.critic(), exec.istdp_target_period_ticks()),
        (None, TARGET_PERIOD_1024),
        "{name}: H-21's image carries the target and no critic"
    );
    let (run, moves, expected) = earned_run_observed(
        &mut exec,
        Feedback::Answer,
        first_mapping(arm),
        1024,
        BLOCK,
        GATE_BASELINE_Q16,
        &SCHEDULE_FLIPS,
        true,
        Some(CRITIC_AT_START),
        &mut |_, _| {},
    );
    let (blocks, _, trials, read, _) = &run;
    let compositions: Vec<Composition> = trials.chunks(BLOCK).map(composition).collect();
    eprintln!(
        "DUMP {name} H-21's first block {:?} earned {:?} expected {:?}",
        blocks,
        earned_blocks(read),
        expected_blocks(&expected)
    );
    assert_eq!(blocks.as_slice(), &TARGET_BLOCKS_1024[k][..1], "{name}");
    assert_eq!(
        compositions.as_slice(),
        &TARGET_COMPOSITIONS_1024[k][..1],
        "{name}"
    );
    assert_eq!(
        earned_blocks(read).as_slice(),
        &TARGET_EARNED_1024[k][..1],
        "{name}"
    );
    assert_eq!(
        moves_blocks(read, &moves).as_slice(),
        &TARGET_MOVES_1024[k][..1],
        "{name}"
    );
    assert_eq!(
        expected_blocks(&expected).as_slice(),
        &TARGET_EXPECTED_1024[k][..1],
        "{name}"
    );
}

/// What brief 055 reads of a run beside H-21's tables: the four couplings at the end of the
/// first trial under each new mapping, as H-20 reads them, and the value weights by group at
/// every block's end.
#[derive(Clone, Debug, PartialEq, Eq)]
struct ValuedWatch {
    at_flips: [[[i64; 2]; 2]; 3],
    weights: Vec<Weights>,
}

/// An arm's run from the valued engine (brief 055): H-21's run — `earned_run_valued` under the
/// answer's feedback at the gate's zero with the signed gate set, the arm's first mapping and
/// H-20's flips — with the task carrying no critic, the engine's critic held to the harness's at
/// every trial; at the end of the first trial under each new mapping the four couplings, and at
/// every block's end the weights by group.
fn valued_run(
    exec: &mut Engine,
    arm: Reversal,
    sets: &[Set; 4],
    groups: &[usize],
) -> (EarnedRun, Vec<Moves>, Vec<i32>, ValuedWatch) {
    let mut at_flips: [Option<[[i64; 2]; 2]>; 3] = [None; 3];
    let mut weights: Vec<Weights> = Vec::new();
    let (run, moves, expected, values) = earned_run_valued(
        exec,
        Feedback::Answer,
        first_mapping(arm),
        1024,
        SCHEDULE_TRIALS,
        GATE_BASELINE_Q16,
        &SCHEDULE_FLIPS,
        true,
        None,
        &mut |exec, trial| {
            if let Some(f) = SCHEDULE_FLIPS.iter().position(|&f| f == trial) {
                at_flips[f] = Some(pair_couplings(exec, sets));
            }
            if trial.wrapping_add(1) % BLOCK == 0 {
                weights.push(weights_by_group(exec, groups));
            }
        },
    );
    assert!(expected.is_empty(), "the task carries no critic");
    let at_flips = at_flips.map(|c| c.expect("the run reached the trial after every flip"));
    (run, moves, values, ValuedWatch { at_flips, weights })
}

/// One arm of H-22 at 1 024 units (brief 055): the calibration before any rewarded run (H-22's
/// stopping rule, step 2) — the settled engine held to ADR-0077 step by step and its images,
/// H-20's image by its CRC, a frozen block from the zero image held to ADR-0077's frozen run,
/// H-21's image by its CRC and its first block reproduced with the engine's critic unset — then
/// the image the arm decodes, H-21's with the critic written, shown to differ from H-21's in the
/// critic's three bytes and the section's seal alone, and decoded; then the arm's 7 680 trials
/// from it with no task critic and H-20's flips; everything dumped, the clauses and the readings
/// computed before anything is held; then the assertion, and the pinned tables of the whole run.
fn valued_arm(arm: Reversal) {
    let k = VALUED_ARMS
        .iter()
        .position(|&a| a == arm)
        .expect("an arm of H-22");
    let name = format!("valued1024 {arm:?}");
    let (zero, signed) = signed_images(&name);
    assert_eq!(
        pinned_crc(&signed),
        PUNISHED_IMAGE_CRC_1024,
        "{name}: H-20's image, H-19's and H-18's"
    );
    {
        let mut frozen = frozen_from(&zero, 1024);
        assert_eq!(
            (frozen.inhibitory_baseline_q16(), frozen.signed_gate()),
            (None, false),
            "{name}: the calibration's image leaves the inhibitory baseline and the signed gate unset"
        );
        let calibration = taught_run(&mut frozen, Arm::Withheld, 1024, BLOCK);
        calibration_holds(&format!("{name} calibration"), &calibration);
    }
    let targeted = targeted_image(&signed, TARGET_PERIOD_1024);
    assert!(
        only_the_target(&signed, &targeted),
        "{name}: H-21's image is H-20's in every byte but the target period's and the seal"
    );
    assert_eq!(
        pinned_crc(&targeted),
        TARGET_IMAGE_CRC_1024,
        "{name}: H-21's image"
    );
    assert_eq!(
        crc64(&with_version(&targeted, 18)),
        TARGET_IMAGE_CRC_FORMAT_18_1024,
        "{name}: every byte but the header's version and seal is the image H-21 read (ADR-0095)"
    );
    h21_first_block(&targeted, arm, k, &name);
    eprintln!(
        "DUMP {name} calibration holds: ADR-0077's settled candidate, H-20's image, H-21's image and its first block"
    );
    // The image the arm decodes: H-21's, the critic written and nothing else.
    let image_bytes = valued_image(&targeted, VALUED_CRITIC);
    assert!(
        only_the_critic(&targeted, &image_bytes),
        "{name}: the image is H-21's in every byte but the critic's and the seal"
    );
    let sets = geometry(1024, ROTATION_1024);
    let mut exec = signed_from(&image_bytes, 1024);
    assert_eq!(
        (exec.critic(), exec.istdp_target_period_ticks()),
        (Some(VALUED_CRITIC), TARGET_PERIOD_1024),
        "{name}: the image carries the critic and the target"
    );
    assert!(
        exec.units().iter().all(|u| u.value_weight == 0) && exec.features().iter().all(|&c| c == 0),
        "{name}: every weight and every count zero"
    );
    let image_sums = QUIET_1024[SETTLED].1;
    assert_eq!(
        weights_by_polarity(&exec),
        image_sums,
        "{name}: the image's sums"
    );
    assert_eq!(
        pair_couplings(&exec, &sets),
        IMAGE_COUPLINGS_1024,
        "{name}: the same image"
    );
    let groups = groups_of(&exec, &sets);
    eprintln!(
        "DUMP {name} image crc {:#018x}, {} bytes differ from H-21's, groups {:?}",
        crc64(&image_bytes),
        differing(&targeted, &image_bytes).len(),
        group_sizes(&groups)
    );
    let image = weights_of(&exec);
    let first = first_mapping(arm);
    let (run, moves, values, watched) = valued_run(&mut exec, arm, &sets, &groups);
    let (blocks, trace, trials, read, volley_ticks) = &run;
    let earned = earned_blocks(read);
    let compositions: Vec<Composition> = trials.chunks(BLOCK).map(composition).collect();
    let moved = moves_blocks(read, &moves);
    let strong = strong_scheduled(read, first);
    let valued_by_block = value_blocks(read, &values);
    assert_eq!(blocks.len(), SCHEDULE_BLOCKS, "{name}: 120 blocks");
    assert_eq!(
        (read.len(), values.len()),
        (SCHEDULE_TRIALS, SCHEDULE_TRIALS)
    );
    assert_eq!(
        (
            compositions.len(),
            earned.len(),
            moved.len(),
            valued_by_block.len(),
            strong.len(),
            watched.weights.len()
        ),
        (
            SCHEDULE_BLOCKS,
            SCHEDULE_BLOCKS,
            SCHEDULE_BLOCKS,
            SCHEDULE_BLOCKS,
            SCHEDULE_BLOCKS - FLIP_BLOCK,
            SCHEDULE_BLOCKS
        )
    );
    // The run's tables dumped whole, as they are pinned, before anything is held or read.
    eprintln!("DUMP {name} PIN blocks {blocks:?}");
    eprintln!("DUMP {name} PIN trace {trace:#018x}");
    eprintln!("DUMP {name} PIN compositions {compositions:?}");
    eprintln!("DUMP {name} PIN earned {earned:?}");
    eprintln!("DUMP {name} PIN read {:#018x}", earned_hash(read));
    eprintln!("DUMP {name} PIN census {:?}", census_of(volley_ticks));
    eprintln!("DUMP {name} PIN moves {moved:?}");
    eprintln!("DUMP {name} PIN strong {strong:?}");
    eprintln!("DUMP {name} PIN at flips {:?}", watched.at_flips);
    eprintln!("DUMP {name} PIN values {valued_by_block:?}");
    eprintln!("DUMP {name} PIN value hash {:#018x}", values_hash(&values));
    eprintln!("DUMP {name} PIN weights {:?}", watched.weights);
    // Everything read and dumped, and the clauses and the readings computed, before anything
    // else is held.
    dump_earned(&name, &run, &earned);
    let reach = reach_by_polarity(&exec, &image, 1024, &ALL_PAIRS);
    let correct = mapping_correct(blocks);
    let over = first_over(blocks);
    let errors = mapping_errors(read);
    let first_new_read = first_new_scheduled(read, first);
    let crossings_read = crossings(blocks);
    let crossed = crossed_scheduled(&earned, first);
    let tally_read = tally(blocks);
    let settle = settle_scheduled(blocks, first);
    let highest_read = highest(blocks);
    let strong_sum = strong_by_flip(&strong);
    let punished_moves = moves_by_mapping(&moved, 1);
    let rewarded_moves = moves_by_mapping(&moved, 0);
    let once = once_blocks(blocks, &compositions);
    let falls = falls_every_block(image_sums.0, blocks);
    let sums_after = weights_by_polarity(&exec);
    eprintln!(
        "DUMP {name} PIN readings correct {correct:?} over {over:?} errors {errors:?} reach {reach:?} first new {first_new_read:?} crossings {crossings_read:?} crossed {crossed:?} tally {tally_read:?} settle {settle:?} highest {highest_read:?} strong total {strong_sum:?} punished moves {punished_moves:?} rewarded moves {rewarded_moves:?} once {once} falls {falls} sums after {sums_after:?}"
    );
    eprintln!(
        "DUMP {name} verdict of this arm: learned {:?} over {over:?} predicts {:?} mean errors {:?} settle per myriad {:?}",
        correct.map(|c| c >= REWARDED_MIN),
        errors.map(|(sum, n)| predicts(sum, n)),
        errors.map(|(sum, n)| sum.checked_div(i64::from(n))),
        settle_per_myriad(settle, first)
    );
    eprintln!(
        "DUMP {name} value beside H-21's expectation by block {:?}",
        valued_by_block
            .iter()
            .zip(TARGET_EXPECTED_1024[k])
            .map(|(v, e)| (mean_values(v), *e))
            .collect::<Vec<_>>()
    );
    eprintln!(
        "DUMP {name} inhibitory course {:?} beside H-21's {:?}",
        course(image_sums.0, blocks),
        course(image_sums.0, TARGET_BLOCKS_1024[k])
    );
    eprintln!(
        "DUMP {name} crossings {crossings_read:?} beside H-21's {:?} and H-20's {:?}",
        CROSSINGS_TARGET_1024[k], CROSSINGS_1024[k]
    );
    eprintln!(
        "DUMP {name} couplings course {:?}",
        couplings_course(blocks)
    );
    eprintln!(
        "DUMP {name} signal {:?}",
        blocks.iter().map(|b| b.9).collect::<Vec<i32>>()
    );
    // The assertion, after the dump and beside the verdict: H-18's rule, as H-20 and H-21 hold
    // it.
    assert!(
        punished_held(&reach),
        "{name}: no excitatory synapse outside the four stimulus–readout pairs moved: {reach:?}"
    );
    // The pinned tables of the whole run, and the readings as the constants state.
    pinned(
        &format!("{name} sight"),
        blocks,
        *trace,
        VALUED_BLOCKS_1024[k],
        VALUED_TRACES_1024[k],
    );
    assert_eq!(
        compositions.as_slice(),
        VALUED_COMPOSITIONS_1024[k],
        "{name}: the composition per block"
    );
    assert_eq!(
        earned.as_slice(),
        VALUED_EARNED_1024[k],
        "{name}: the earned blocks"
    );
    assert_eq!(
        earned_hash(read),
        VALUED_READ_1024[k],
        "{name}: the readings"
    );
    assert_eq!(
        census_of(volley_ticks),
        VALUED_CENSUS_1024[k].to_vec(),
        "{name}: the volley's ticks"
    );
    assert_eq!(
        moved.as_slice(),
        VALUED_MOVES_1024[k],
        "{name}: the moves per block"
    );
    assert_eq!(
        strong.as_slice(),
        VALUED_STRONG_1024[k],
        "{name}: the strong punishments per block"
    );
    assert_eq!(watched.at_flips, VALUED_AT_FLIPS_1024[k]);
    assert_eq!(
        valued_by_block.as_slice(),
        VALUED_VALUES_1024[k],
        "{name}: the engine's value per block"
    );
    assert_eq!(
        values_hash(&values),
        VALUED_VALUE_HASH_1024[k],
        "{name}: every trial's value"
    );
    assert_eq!(
        watched.weights.as_slice(),
        VALUED_WEIGHTS_1024[k],
        "{name}: the weights by group per block"
    );
    assert_eq!(correct, CORRECT_VALUED_1024[k]);
    assert_eq!(over, OVER_VALUED_1024[k]);
    assert_eq!(errors, ERRORS_VALUED_1024[k]);
    assert_eq!(reach, REACH_VALUED_1024[k]);
    assert_eq!(first_new_read, FIRST_NEW_VALUED_1024[k]);
    assert_eq!(crossings_read, CROSSINGS_VALUED_1024[k]);
    assert_eq!(crossed, CROSSED_VALUED_1024[k]);
    assert_eq!(tally_read, TALLY_VALUED_1024[k]);
    assert_eq!(settle, SETTLE_VALUED_1024[k]);
    assert_eq!(highest_read, HIGHEST_VALUED_1024[k]);
    assert_eq!(strong_sum, STRONG_BY_FLIP_VALUED_1024[k]);
    assert_eq!(punished_moves, PUNISHED_MOVES_VALUED_1024[k]);
    assert_eq!(rewarded_moves, REWARDED_MOVES_VALUED_1024[k]);
    assert_eq!(once, ONCE_BLOCKS_VALUED_1024[k]);
    assert_eq!(falls, FALLS_VALUED_1024[k]);
    assert_eq!(
        (sums_after, blocks.last().map(|b| (b.7, b.8))),
        (SUMS_AFTER_VALUED_1024[k], Some(SUMS_AFTER_VALUED_1024[k])),
        "{name}: the sums after the run are the last block's"
    );
}

/// H-22's arm that starts from the assignment (brief 055): H-21's arm from the assignment with
/// the task's critic replaced by the engine's own.
#[test]
#[ignore]
fn a_critic_of_the_engines_own_from_the_assignment_at_1024_units_exhaustive() {
    valued_arm(Reversal::AssignmentFirst);
}

/// H-22's arm that starts from the mirrored assignment (brief 055): H-21's arm from the mirrored
/// assignment with the task's critic replaced by the engine's own.
#[test]
#[ignore]
fn a_critic_of_the_engines_own_from_the_mirrored_assignment_at_1024_units_exhaustive() {
    valued_arm(Reversal::MirroredFirst);
}

/// The gate's test (ADR-0061's class; brief 055): the arms and the constants as ADR-0130 and
/// ADR-0132 fixed them, H-21's restated; ADR-0132's arithmetic over numbers written by hand —
/// the volley's step beside the task critic's, the rail, the step's floor and the background's
/// noise; the harness's second writing of the critic's rule over a table written by hand and
/// held to the engine's rule over seeded draws; H-22's clause 3 at its edges and the verdict
/// naming the clause, the arm and the mapping; the readings' rules over tables written by hand
/// and the groups on the instrument's network; and the image's patch on that network's image,
/// shown to touch the critic's three bytes and the section's seal alone, to be read by the
/// loader, and to be undone by writing zeros back; and, over the arms' pinned tables, the verdict
/// as written and every reading, block by block. No run, and nothing else added to the gate.
#[test]
fn the_critic_s_arithmetic_the_clauses_of_h_22_and_the_image_s_patch() {
    // The arms and the constants, H-21's restated.
    assert_eq!(VALUED_ARMS, TARGET_ARMS);
    assert_eq!(
        VALUED_ARMS,
        [Reversal::AssignmentFirst, Reversal::MirroredFirst]
    );
    assert_eq!(VALUED_PREDICTED, None, "ADR-0130 predicts no verdict");
    assert_eq!(VALUED_CRITIC, ValueCritic { shift: 9, scale: 2 });
    assert!(VALUED_CRITIC.is_valid());
    assert_eq!(
        (VOLLEY_UNITS, TASK_STEP_SHIFT, PREDICTS_DIVISOR),
        (51, 5, 2)
    );
    assert_eq!((CRITIC_AT, GROUPS, REWARD_Q16), (48, 6, ONE));
    assert_eq!(TARGET_PERIOD_1024, 58_201);
    assert_eq!(
        TARGET_IMAGE_CRC_1024, 0xd34f_afe0_6993_8d2e,
        "H-21's image, at format 25 (ADR-0202)"
    );
    assert_eq!(
        (SCHEDULE_TRIALS, SCHEDULE_FLIPS, MAPPINGS),
        (
            7_680,
            [1_536, 3_584, 5_632],
            [(0, 24), (24, 56), (56, 88), (88, 120)]
        )
    );
    assert_eq!(
        SPANS,
        [(0, 1_536), (1_536, 3_584), (3_584, 5_632), (5_632, 7_680)]
    );
    assert_eq!((BOUND_PER_CENT, REWARDED_MIN, LAST_BLOCKS), (130, 80, 2));
    // ADR-0132's arithmetic. The stimulus set at 1 024 units is the volley's 51 units.
    let sets = geometry(1024, ROTATION_1024);
    assert_eq!(
        (sets[0].len(), sets[1].len()),
        (u64::from(VOLLEY_UNITS), u64::from(VOLLEY_UNITS))
    );
    // One volley under the error of a whole reward against a value of zero: each unit's weight
    // up by 65 536 / 512 = 128, and the same volley's value then 51 × 128 / 4 = 1 632, which is
    // 51 / 2 048 of the reward, beside the task critic's 2 048, a thirty-second of it.
    let volley = [1u32; VOLLEY_UNITS as usize];
    let (value, error, moved) =
        value_step(&[0; VOLLEY_UNITS as usize], &volley, VALUED_CRITIC, ONE);
    assert_eq!((value, error), (0, ONE));
    assert!(moved.iter().all(|&w| w == 128));
    let after = VALUED_CRITIC.value_q16(moved.iter().copied().zip(volley));
    assert_eq!(after, 1_632);
    assert_eq!(i64::from(after), i64::from(ONE).saturating_mul(51) / 2_048);
    assert_eq!(ONE >> TASK_STEP_SHIFT, 2_048, "the task critic's step");
    assert!(after <= ONE >> TASK_STEP_SHIFT);
    // At the sum of ten, the volley would move it by 3 264, past the task critic's.
    let ten = ValueCritic { shift: 8, scale: 2 };
    let (_, _, moved) = value_step(&[0; VOLLEY_UNITS as usize], &volley, ten, ONE);
    assert_eq!(ten.value_q16(moved.iter().copied().zip(volley)), 3_264);
    // The rail: a weight of i16::MAX predicts 8 191 a spike, an eighth of the reward; the volley
    // predicts the whole reward at 5 141 a unit, 0.157 of the rail, and not at 5 140.
    assert_eq!(VALUED_CRITIC.value_q16([(i16::MAX, 1)]), 8_191);
    let at = |w: i16| VALUED_CRITIC.value_q16(core::iter::repeat_n((w, 1), 51));
    assert_eq!((at(5_140), at(5_141)), (65_535, 65_547));
    // The step's floor: an error below 512 moves no weight up, and any error below zero moves
    // each unit that fired one LSB down at least; the 351 spikes of a trial at H-21's rates then
    // lower the value by 351 / 4, floored, 88 of the 65 536, 0.13 per cent.
    assert_eq!(VALUED_CRITIC.step(0, 511, 1), 0);
    assert_eq!(VALUED_CRITIC.step(0, 512, 1), 1);
    assert_eq!(VALUED_CRITIC.step(0, -1, 1), -1);
    let spikes = [1u32; 351];
    let (_, _, floored) = value_step(&[0; 351], &spikes, VALUED_CRITIC, -1);
    assert_eq!(
        VALUED_CRITIC.value_q16(floored.iter().copied().zip(spikes)),
        -88
    );
    // The background's noise: 300 spikes a trial over units at one weight w carry 75 w, and one
    // spike more or less moves it by w / 4. With the background carrying the whole reward the
    // weight is 874 and a Poisson count of 300 ± 17 moves the value by about 3 700, 5.8 per
    // cent of the reward.
    let background = |w: i16, n: usize| VALUED_CRITIC.value_q16(core::iter::repeat_n((w, 1), n));
    assert_eq!(background(874, 300), 65_550);
    assert_eq!(
        background(874, 317).saturating_sub(background(874, 300)),
        3_714
    );
    // The harness's second writing of the rule over a table written by hand: weights 100, −40,
    // 7 and 0 and counts 2, 2, 0 and 1 are a value of (200 − 80) / 4 = 30; the reward 1.0 less
    // it is 65 506; each weight moves by 65 506 × its count over 512, floored: 255, 255, 0, 127.
    let (value, error, moved) = value_step(&[100, -40, 7, 0], &[2, 2, 0, 1], VALUED_CRITIC, ONE);
    assert_eq!((value, error), (30, 65_506));
    assert_eq!(moved, [355, 215, 7, 127]);
    let (value, error, moved) = value_step(&[-3], &[1], VALUED_CRITIC, -ONE);
    assert_eq!(
        (value, error),
        (-1, -65_535),
        "minus three quarters, floored"
    );
    assert_eq!(moved, [-3 - 128]);
    assert_eq!(
        value_step(&[i16::MAX], &[u32::MAX], VALUED_CRITIC, i32::MIN),
        (i32::MAX, i32::MIN, vec![i16::MIN]),
        "the value and the error at the width, the weight at its rail"
    );
    assert_eq!(value_step(&[], &[], VALUED_CRITIC, ONE), (0, ONE, vec![]));
    // The two writings over seeded draws, the engine's rule and the harness's.
    let mut rng = Lcg::new(0x55);
    for draw in 0..2_000 {
        let critic = ValueCritic {
            shift: rng.below(31) as u8,
            scale: rng.below(15) as u8,
        };
        let n = rng.below(40) as usize;
        let weights: Vec<i16> = (0..n).map(|_| rng.next_i16()).collect();
        let counts: Vec<u32> = (0..n).map(|_| rng.below(5)).collect();
        let reward = rng.i32_edge_biased();
        let (value, error, moved) = value_step(&weights, &counts, critic, reward);
        let engine_value = critic.value_q16(weights.iter().copied().zip(counts.iter().copied()));
        assert_eq!(value, engine_value, "draw {draw}");
        assert_eq!(
            error,
            ValueCritic::error_q16(reward, engine_value),
            "draw {draw}"
        );
        let engine_moved: Vec<i16> = weights
            .iter()
            .zip(&counts)
            .map(|(&w, &c)| critic.step(w, error, c))
            .collect();
        assert_eq!(moved, engine_moved, "draw {draw}");
    }
    // Clause 3 at its edges: half the reward a correct trial holds and one LSB more does not; a
    // mean below zero holds; no correct trial does not.
    let half = i64::from(ONE / 2);
    for n in [1u32, 2, 64, 128] {
        let edge = half.saturating_mul(i64::from(n));
        assert!(predicts(edge, n), "{n} at half");
        assert!(!predicts(edge.saturating_add(1), n), "{n} one LSB over");
        assert!(predicts(edge.saturating_neg(), n));
    }
    assert!(
        !predicts(0, 0) && !predicts(-1, 0),
        "no correct trial predicts nothing"
    );
    // Over trials written by hand: a run of 7 680 whose correct trials each delivered an error;
    // the last 128 of each mapping read, the incorrect and the earlier ones not, the third
    // mapping's last trial incorrect.
    let trial = |correct: bool, error: i32| -> EarnedTrial {
        (0, [0; 2], None, correct, error, [[0; 2]; 2], 0, 0)
    };
    let mut read: Vec<EarnedTrial> = vec![trial(true, ONE); SCHEDULE_TRIALS];
    for (m, &(_, end)) in SPANS.iter().enumerate() {
        for (j, t) in read[end.saturating_sub(128)..end].iter_mut().enumerate() {
            *t = trial(
                j % 4 != 0,
                (m as i32).saturating_add(1).saturating_mul(1_000),
            );
        }
        read[end.saturating_sub(129)] = trial(true, i32::MAX);
    }
    read[SPANS[2].1 - 1] = trial(false, i32::MIN);
    let errors = mapping_errors(&read);
    assert_eq!(
        errors,
        [(96_000, 96), (192_000, 96), (285_000, 95), (384_000, 96)]
    );
    assert_eq!(mapping_errors(&read[1..]), [(0, 0); 4], "another length");
    assert_eq!(correct_errors(&[]), (0, 0));
    // The verdict: every clause over blocks written by hand, each mapping learned and bounded,
    // and clause 3 failing in one mapping of one arm, named.
    let full = vec![
        (
            BLOCK as u32,
            0,
            [[0; 2]; 2],
            [0; 2],
            [0; 2],
            [0; 2],
            0,
            0,
            0,
            0,
            IMAGE_COUPLINGS_1024,
            0,
        );
        SCHEDULE_BLOCKS
    ];
    let learning_yes = Scheduled {
        learned: [[true; 4]; 2],
        bounded: [true; 2],
        over: [None; 2],
        yes: true,
    };
    let held = [(half.saturating_mul(128), 128); 4];
    assert_eq!(
        valued([&full, &full], [held, held]),
        Valued {
            learning: learning_yes,
            predicted: [[true; 4]; 2],
            yes: true
        }
    );
    let mut failing = held;
    failing[2] = (half.saturating_mul(128).saturating_add(1), 128);
    assert_eq!(
        valued([&full, &full], [held, failing]),
        Valued {
            learning: learning_yes,
            predicted: [[true; 4], [true, true, false, true]],
            yes: false
        },
        "clause 3 fails in the second arm's third mapping"
    );
    let mut unlearned = full.clone();
    unlearned[MAPPINGS[1].1 - 1].0 = 0;
    unlearned[MAPPINGS[1].1 - 2].0 = 0;
    let verdict = valued([&unlearned, &full], [held, held]);
    assert_eq!(
        (verdict.learning.learned[0], verdict.predicted, verdict.yes),
        ([true, false, true, true], [[true; 4]; 2], false),
        "clause 1 fails in the first arm's second mapping, clause 3 holds"
    );
    // The readings' rules over tables written by hand.
    let block_read = [
        (0u8, true, 100, 10),
        (0, false, 300, -20),
        (1, true, -50, 40),
        (1, true, 70, 60),
    ];
    let read: Vec<EarnedTrial> = block_read
        .iter()
        .map(|&(s, c, _, e)| (s, [0; 2], None, c, e, [[0; 2]; 2], 0, 0))
        .collect();
    let values: Vec<i32> = block_read.iter().map(|t| t.2).collect();
    let by_block = value_blocks(&read, &values);
    assert_eq!(by_block, [[[2, 400, 1, 10], [2, 20, 2, 100]]]);
    assert_eq!(mean_values(&by_block[0]), [200, 10]);
    assert_eq!(
        mean_values(&[[0; 4]; 2]),
        [0, 0],
        "a stimulus not presented"
    );
    assert_eq!(values_hash(&values), fnv1a_64(&[100, 300, -50, 70]));
    // The groups and the weights by group on the instrument's network at 1 024 units: 204
    // inhibitory units, 51 of each stimulus set, 357 of each readout set and the four past the
    // last period; every weight zero; a weight written by hand read in its group and at the
    // extremes.
    let p = prior(1024);
    let mut exec = at_gain(&p, config(1024, 2, 0), GAIN_1024);
    let groups = groups_of(&exec, &sets);
    assert_eq!(group_sizes(&groups), [204, 51, 51, 357, 357, 4]);
    assert_eq!(weights_by_group(&exec, &groups), ([0; GROUPS], 0, 0));
    let a = sets[0].units().next().expect("a unit of A");
    let r1 = sets[3].units().next().expect("a unit of readout 1");
    exec.units_mut()[a as usize].value_weight = -7;
    exec.units_mut()[r1 as usize].value_weight = 300;
    assert_eq!(
        weights_by_group(&exec, &groups),
        ([0, -7, 0, 0, 300, 0], -7, 300)
    );
    exec.units_mut()[a as usize].value_weight = 0;
    exec.units_mut()[r1 as usize].value_weight = 0;
    // The image's patch on the network's image: the critic written touches its three bytes and
    // the entry's seal alone; the loader reads it; zeros written back undo it; a byte moved
    // elsewhere fails the check; constants the rule does not resolve are refused by the loader,
    // so the bytes are the ones it reads.
    let img = Image::encode(&exec).expect("quiescent");
    let patched = valued_image(&img, VALUED_CRITIC);
    let moved = differing(&img, &patched);
    let (at, offset, _) = modulator_entry(&img);
    let critic_bytes = offset.saturating_add(48)..offset.saturating_add(51);
    let entry_bytes = at..at.saturating_add(64);
    assert!(
        !moved.is_empty()
            && moved.len() <= 11
            && moved
                .iter()
                .all(|p| critic_bytes.contains(p) || entry_bytes.contains(p)),
        "the critic's bytes and the entry's seal: {moved:?}"
    );
    assert!(only_the_critic(&img, &patched));
    assert!(
        only_the_critic(&img, &img),
        "nothing written, nothing moved"
    );
    assert!(
        !only_the_critic(&patched, &patched),
        "an image that carries a critic already"
    );
    assert_eq!(with_critic_bytes(&patched, [0; 3]), img);
    let decoded = Image::decode::<2048>(&patched, config(1024, 2, 0)).expect("a well-formed image");
    assert_eq!(decoded.critic(), Some(VALUED_CRITIC));
    assert_eq!(weights_of(&decoded), weights_of(&exec));
    let mut elsewhere = patched.clone();
    elsewhere[offset.saturating_add(16)] ^= 1;
    assert!(!only_the_critic(&img, &elsewhere), "the baseline's byte");
    for bad in [
        ValueCritic {
            shift: 31,
            scale: 2,
        },
        ValueCritic {
            shift: 9,
            scale: 15,
        },
    ] {
        assert!(
            matches!(
                Image::decode::<2048>(&valued_image(&img, bad), config(1024, 2, 0)),
                Err(ImageError::Config(ConfigError::CriticOutOfRange))
            ),
            "{bad:?}: refused by the loader"
        );
    }
    // Over the arms' pinned tables: the verdict as written, by the rule committed first; the
    // readings as the constants state; and, block by block over each arm's 120 blocks, the tables
    // consistent with one another, with the assertion and with the oracle — the value's trials
    // the block's presentations, its correct trials the block's, the errors of each mapping's last
    // two blocks the clause's, each coupling the one before plus what the oracle consolidated, the
    // excitatory sum the image's plus the four pairs' moves.
    let image_sums = QUIET_1024[SETTLED].1;
    let verdict = valued(
        [VALUED_BLOCKS_1024[0], VALUED_BLOCKS_1024[1]],
        ERRORS_VALUED_1024,
    );
    assert_eq!(verdict, VALUED_1024, "the verdict as written");
    assert_eq!(VALUED_PREDICTED, None, "and no prediction to hold it to");
    for (k, &arm) in VALUED_ARMS.iter().enumerate() {
        let first = first_mapping(arm);
        let blocks = VALUED_BLOCKS_1024[k];
        let earned = VALUED_EARNED_1024[k];
        let moved = VALUED_MOVES_1024[k];
        let compositions = VALUED_COMPOSITIONS_1024[k];
        let values = VALUED_VALUES_1024[k];
        let weights = VALUED_WEIGHTS_1024[k];
        let strong = VALUED_STRONG_1024[k];
        assert_eq!(
            [
                blocks.len(),
                compositions.len(),
                earned.len(),
                moved.len(),
                values.len(),
                weights.len()
            ],
            [SCHEDULE_BLOCKS; 6],
            "{arm:?}: 120 blocks of each"
        );
        assert_eq!(strong.len(), SCHEDULE_BLOCKS - FLIP_BLOCK);
        assert_ne!(VALUED_TRACES_1024[k], 0);
        assert_ne!(VALUED_READ_1024[k], 0);
        assert_ne!(VALUED_VALUE_HASH_1024[k], 0);
        assert!(!VALUED_CENSUS_1024[k].is_empty());
        let correct = mapping_correct(blocks);
        assert_eq!(correct, CORRECT_VALUED_1024[k]);
        assert_eq!(
            correct.map(|c| c >= REWARDED_MIN),
            verdict.learning.learned[k]
        );
        assert_eq!(first_over(blocks), OVER_VALUED_1024[k]);
        assert_eq!(first_over(blocks).is_none(), verdict.learning.bounded[k]);
        assert_eq!(
            ERRORS_VALUED_1024[k].map(|(sum, n)| predicts(sum, n)),
            verdict.predicted[k]
        );
        assert_eq!(crossings(blocks), CROSSINGS_VALUED_1024[k]);
        assert_eq!(crossed_scheduled(earned, first), CROSSED_VALUED_1024[k]);
        assert_eq!(tally(blocks), TALLY_VALUED_1024[k]);
        assert_eq!(settle_scheduled(blocks, first), SETTLE_VALUED_1024[k]);
        assert_eq!(highest(blocks), HIGHEST_VALUED_1024[k]);
        assert_eq!(strong_by_flip(strong), STRONG_BY_FLIP_VALUED_1024[k]);
        assert_eq!(moves_by_mapping(moved, 1), PUNISHED_MOVES_VALUED_1024[k]);
        assert_eq!(moves_by_mapping(moved, 0), REWARDED_MOVES_VALUED_1024[k]);
        assert_eq!(
            once_blocks(blocks, compositions),
            ONCE_BLOCKS_VALUED_1024[k]
        );
        assert_eq!(
            falls_every_block(image_sums.0, blocks),
            FALLS_VALUED_1024[k]
        );
        assert!(
            punished_held(&REACH_VALUED_1024[k]),
            "{arm:?}: the assertion held"
        );
        let last = blocks.last().expect("a block");
        assert_eq!(SUMS_AFTER_VALUED_1024[k], (last.7, last.8));
        // Each mapping's last two blocks hold clause 3's correct trials and their errors.
        for (m, &(_, end)) in MAPPINGS.iter().enumerate() {
            let (sum, n) = values[end.saturating_sub(LAST_BLOCKS)..end].iter().fold(
                (0i64, 0i64),
                |(sum, n), v| {
                    (
                        sum.saturating_add(v[0][3]).saturating_add(v[1][3]),
                        n.saturating_add(v[0][2]).saturating_add(v[1][2]),
                    )
                },
            );
            assert_eq!(
                (sum, n),
                (
                    ERRORS_VALUED_1024[k][m].0,
                    i64::from(ERRORS_VALUED_1024[k][m].1)
                ),
                "{arm:?} mapping {m}: clause 3's trials are the value table's"
            );
        }
        let mut previous = IMAGE_COUPLINGS_1024;
        for (j, block) in blocks.iter().enumerate() {
            let in_force = mirrored_at(first, j);
            assert_eq!(
                block.1, VALUED_BLOCKS_1024[0][j].1,
                "{arm:?} block {j}: the same trials present A in both arms"
            );
            assert_eq!(
                block.1, TARGET_BLOCKS_1024[k][j].1,
                "{arm:?} block {j}: and in H-21's"
            );
            let presented = [block.1, (BLOCK as u32).saturating_sub(block.1)];
            for (s, &n) in presented.iter().enumerate() {
                assert_eq!(
                    earned[j].0[s].iter().sum::<u32>(),
                    n,
                    "{arm:?} block {j}: every presentation of {s} selected or tied"
                );
                assert_eq!(
                    values[j][s][0],
                    i64::from(n),
                    "{arm:?} block {j}: a value for every presentation of {s}"
                );
                assert_eq!(
                    values[j][s][2],
                    i64::from(earned[j].0[s][answer_of(s as u8, in_force)]),
                    "{arm:?} block {j}: the value's correct trials of {s} the block's"
                );
            }
            let correct = earned[j].0[0][answer_of(0, in_force)]
                .saturating_add(earned[j].0[1][answer_of(1, in_force)]);
            assert_eq!(
                block.0, correct,
                "{arm:?} block {j}: correct under the mapping in force"
            );
            let mut rise = 0i64;
            let mut consolidated = 0i64;
            for &(s, r) in &ALL_PAIRS {
                assert_eq!(
                    block.10[s][r],
                    previous[s][r].saturating_add(earned[j].2[s][r]),
                    "{arm:?} block {j}: {s}→{r} moved by what the oracle consolidated"
                );
                rise =
                    rise.saturating_add(block.10[s][r].saturating_sub(IMAGE_COUPLINGS_1024[s][r]));
                consolidated = consolidated.saturating_add(earned[j].2[s][r]);
            }
            assert_eq!(
                block.8,
                image_sums.1.saturating_add(rise),
                "{arm:?} block {j}: the excitatory sum moved by the four pairs' moves and nothing else"
            );
            let moved_sum = moved[j]
                .iter()
                .flat_map(|m| m.1.iter())
                .fold(0i64, |sum, &a| sum.saturating_add(a));
            assert_eq!(
                moved_sum, consolidated,
                "{arm:?} block {j}: what the addressed synapses moved is what the oracle consolidated"
            );
            assert!(
                weights[j].1 <= weights[j].2,
                "{arm:?} block {j}: the lowest weight at most the highest"
            );
            previous = block.10;
        }
    }
}

// --------------------- the measurement (brief 055), its tables in inhibition/pins/h22.rs

/// H-21's image by its CRC-64: H-20's with the target period written (ADR-0129), at format 25
/// (it was `0xafe7eff2d59da51f` at 18, the CRC H-21 read, `0xeefb68fd147b41c5` at 19, the CRC
/// H-22 read, `0xbb7452f9fec5e146` at 20, the CRC H-23 to H-29 read, `0xfa68d5f63f23059c` at
/// 21, `0x394d5ce67d0828f2` at 22, `0x7851dbe9bceecc28` at 23 and `0x925328efa87569f4` at 24;
/// ADR-0134, ADR-0155, ADR-0180, ADR-0189, ADR-0194 and ADR-0202 re-pinned it with the format as
/// ADR-0095 re-pinned H-17's).
/// ADR-0221 moved the format to 26 for the magic alone, and the pin holds the image at 25 since
/// (`pinned_crc`, ADR-0222).
const TARGET_IMAGE_CRC_1024: u64 = 0xd34fafe069938d2e;
/// The same image with its header's version written back to 18 and the header resealed: the
/// CRC-64 H-21 read (ADR-0129), so that every byte of the image but the version and the seal is
/// the image H-21 ran from (ADR-0134, as ADR-0095).
const TARGET_IMAGE_CRC_FORMAT_18_1024: u64 = 0xafe7eff2d59da51f;

const VALUED_TRACES_1024: [u64; 2] = [0x681281d3285393a0, 0xdbe1ca126a63d46a];
const VALUED_READ_1024: [u64; 2] = [0xdd005dc6e0a17e45, 0x23d08a00546bcf92];
const VALUED_VALUE_HASH_1024: [u64; 2] = [0xb0940e292146584a, 0xeb35dbb21cb55aef];
const CORRECT_VALUED_1024: [[u32; 4]; 2] = [[121, 96, 120, 100], [125, 89, 121, 113]];
const OVER_VALUED_1024: [Option<(usize, usize, usize)>; 2] = [None, None];
const ONCE_BLOCKS_VALUED_1024: [u32; 2] = [120, 120];
const FALLS_VALUED_1024: [bool; 2] = [false, false];
const SUMS_AFTER_VALUED_1024: [(i64, i64); 2] = [(140866105, 219227626), (140276945, 219802246)];

// =================================================================================== H-23

// -------------------------------------------- written before the run (ADR-0133, ADR-0135)

/// The arms of H-23 (ADR-0133): H-22's two, in their order, each its own weekly test, from
/// H-22's image with the critic's window written by its rule, the task carrying no critic of
/// its own, and H-20's flips.
const WINDOWED_ARMS: [Reversal; 2] = VALUED_ARMS;

/// ADR-0133's prediction, written first: clause 3 holds, in both arms. A reading beside the
/// verdict and never asserted; the verdict is read by the clauses whatever it says.
const REVERSALS_PREDICTED: bool = true;

/// The critic's window as its rule reads it from H-21's image (ADR-0133, ADR-0135): the
/// shortest delay of any synapse the image carries, `shortest_delay` over the arena the loader
/// fills, 100 ticks, the reference prior's local band's floor. Within it after a reward the
/// presented stimulus's volley has fired, some twelve ticks on, and no response to it can have
/// come back through a synapse. It does not move after a rewarded run.
const WINDOW_TICKS_1024: u16 = 100;

/// Clause 3's bound (ADR-0133): each of the three reversals passes `CROSSING_MARK` of 64 within
/// 23 blocks of its flip, the crossing block counted — the slowest reversal H-20 and H-21 read
/// with the task's critic, H-21's first from the mirrored assignment.
const REVERSAL_BLOCKS_MAX: usize = 23;

/// Clause 4's bound (ADR-0133, F-61's form): over a mapping's last 128 trials, a stimulus's mean
/// value within a quarter of the reward of $(2p - 1)$ of it, $p$ its accuracy over its trials
/// there, read in integers as `|V − (2c − n) r| × 4 ≤ r n` over its $n$ trials, $c$ of them
/// correct, their values summing to $V$, with at least one trial.
const HOLDS_DIVISOR: i64 = 4;

/// Where the modulator section holds the critic's window (ADR-0134): `[52..54)`.
const WINDOW_AT: usize = 52;

/// The settled network's spikes a unit a tick at H-21's target (ADR-0129): the period of
/// 58 201 ticks is 100 000 over its rate in hertz, so a unit fires once a period.
const TARGET_TICKS_PER_SPIKE: u64 = TARGET_PERIOD_1024 as u64;

// ADR-0132's arithmetic restated for the window's features (ADR-0135). The volley's 51 spikes,
// each once in the window, move the value of the same volley by 51/2 048 of the error, as in
// H-22: the sum of the shift and the scale is kept, so the two inequalities stand.
const _: () = assert!(
    (VOLLEY_UNITS as u64) << TASK_STEP_SHIFT <= 1 << (VALUED_CRITIC.shift + VALUED_CRITIC.scale)
);
// The background the window admits: 1 024 units over 100 ticks at a spike every 58 201 ticks a
// unit, 102 400 / 58 201, one and three quarters — under the 51 of the volley by a factor of 29,
// where H-22's features held some 300 background spikes beside the volley's 51.
const _: () = assert!(
    1024 * WINDOW_TICKS_1024 as u64 / TARGET_TICKS_PER_SPIKE == 1
        && 1024 * WINDOW_TICKS_1024 as u64 * 4 / TARGET_TICKS_PER_SPIKE == 7
);

// ------------------------------------------------------------ the criterion (ADR-0133)

/// Clause 3's rule (ADR-0133), per arm: each of the three reversals — the second, third and
/// fourth mappings — crossed `CROSSING_MARK` within `REVERSAL_BLOCKS_MAX` blocks of its flip,
/// the crossing block counted (`crossings`); a reversal that never crossed does not hold.
fn reversals_within(crossed: [Option<usize>; 4]) -> [bool; 3] {
    [1usize, 2, 3].map(|m| crossed[m].is_some_and(|n| n <= REVERSAL_BLOCKS_MAX))
}

/// A stimulus's trials over a span: their count, the correct ones, and the engine's values at
/// their rewards summed.
type StimulusValue = (u32, u32, i64);

/// Clause 4's counts per mapping and stimulus `[A, B]`, over each mapping's last `LAST_BLOCKS`
/// blocks' trials — 1 409 to 1 536, 3 457 to 3 584, 5 505 to 5 632 and 7 553 to 7 680; zeros
/// for a run of any other length, or without a value a trial.
fn stimulus_values(read: &[EarnedTrial], values: &[i32]) -> [[StimulusValue; 2]; 4] {
    if read.len() != SCHEDULE_TRIALS || values.len() != SCHEDULE_TRIALS {
        return [[(0, 0, 0); 2]; 4];
    }
    SPANS.map(|(_, end)| {
        let from = end.saturating_sub(LAST_BLOCKS.saturating_mul(BLOCK));
        let mut out = [(0u32, 0u32, 0i64); 2];
        for (t, &v) in read[from..end].iter().zip(&values[from..end]) {
            if let Some(s) = out.get_mut(usize::from(t.0)) {
                s.0 = s.0.saturating_add(1);
                s.1 = s.1.saturating_add(u32::from(t.3));
                s.2 = s.2.saturating_add(i64::from(v));
            }
        }
        out
    })
}

/// Clause 4's rule (ADR-0133, F-61's form): at least one trial, and the values' sum within a
/// quarter of the reward a trial of $(2c - n) r$, `|V − (2c − n) r| × 4 ≤ r n`.
fn holds_expected((n, c, v): StimulusValue) -> bool {
    let r = i64::from(REWARD_Q16);
    let expected = i64::from(c)
        .saturating_mul(2)
        .saturating_sub(i64::from(n))
        .saturating_mul(r);
    n > 0
        && v.saturating_sub(expected)
            .saturating_abs()
            .saturating_mul(HOLDS_DIVISOR)
            <= r.saturating_mul(i64::from(n))
}

/// H-23's criterion (ADR-0133), clause by clause per arm `[assignment first, mirrored first]`:
/// (1) each mapping learned and (2) the couplings bounded, H-20's two as `scheduled` reads them;
/// (3) each reversal within 23 blocks, `reversals_within` of `crossings`; and (4) each stimulus's
/// mean value within a quarter of the reward of $2p - 1$, per mapping, `holds_expected`. `yes` is
/// all in both arms; a no names the clause, the arm, the mapping and the stimulus.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct Windowed {
    learning: Scheduled,
    revised: [[bool; 3]; 2],
    held: [[[bool; 2]; 4]; 2],
    yes: bool,
}

fn windowed(arms: [&[Block]; 2], values: [[[StimulusValue; 2]; 4]; 2]) -> Windowed {
    let learning = scheduled(arms);
    let revised = arms.map(|blocks| reversals_within(crossings(blocks)));
    let held = values.map(|mapping| mapping.map(|stimuli| stimuli.map(holds_expected)));
    Windowed {
        learning,
        revised,
        held,
        yes: learning.yes
            && revised.iter().flatten().all(|&r| r)
            && held.iter().flatten().flatten().all(|&h| h),
    }
}

// ----------------------------------------------------- the readings' shape (brief 056)

/// The spikes the window admitted by block, per presented stimulus `[A, B]` and group in
/// `GROUPS`'s order: at every trial's reward, the train's spikes fewer ticks than the window
/// after it opened, summed over the block's trials of that stimulus.
type Admitted = [[u32; GROUPS]; 2];

fn admitted_blocks(read: &[EarnedTrial], admitted: &[[u32; GROUPS]]) -> Vec<Admitted> {
    assert_eq!(read.len(), admitted.len(), "an admission a trial");
    read.chunks(BLOCK)
        .zip(admitted.chunks(BLOCK))
        .map(|(trials, admitted)| {
            let mut out: Admitted = [[0; GROUPS]; 2];
            for (t, a) in trials.iter().zip(admitted) {
                if let Some(row) = out.get_mut(usize::from(t.0)) {
                    for (sum, &n) in row.iter_mut().zip(a) {
                        *sum = sum.saturating_add(n);
                    }
                }
            }
            out
        })
        .collect()
}

/// The value's trough after each flip (ADR-0132's reading), per flip and stimulus: the lowest
/// of a block's per-stimulus means over the blocks of the mapping the flip put in force; zeros
/// for a mapping the table does not hold whole.
fn troughs(means: &[[i64; 2]]) -> [[i64; 2]; 3] {
    [1usize, 2, 3].map(|m| {
        let (from, to) = MAPPINGS[m];
        means.get(from..to).map_or([0; 2], |mine| {
            [0usize, 1].map(|s| mine.iter().map(|b| b[s]).min().unwrap_or(0))
        })
    })
}

/// The engine's mean value per block and stimulus, `mean_values` of each block.
fn value_means(values: &[ValueBlock]) -> Vec<[i64; 2]> {
    values.iter().map(mean_values).collect()
}

/// The task critic's expectation per block's end and stimulus, H-21's reading, widened.
fn expected_means(expected: &[[i32; 2]]) -> Vec<[i64; 2]> {
    expected.iter().map(|e| e.map(i64::from)).collect()
}

// ---------------------------------------------------------------- the image (brief 056)

/// The image with the modulator section's `[52..54)` written `window` and the section re-sealed;
/// every other byte the image's.
fn with_window_bytes(image: &[u8], window: u16) -> Vec<u8> {
    let mut img = image.to_vec();
    let (at, offset, length) = modulator_entry(&img);
    img[offset..][WINDOW_AT..][..2].copy_from_slice(&window.to_le_bytes());
    let mut entry = SectionEntry::decode(img[at..][..64].try_into().unwrap());
    entry.crc64 = crc64(&img[offset..][..length]);
    img[at..][..64].copy_from_slice(&entry.encode());
    img
}

/// The masked check (ADR-0135's one change): `windowed` differs from `image` only in the
/// modulator section's two bytes of the window and in the section's entry in the table, which
/// holds its seal; and writing zeros back gives `image` bit for bit.
fn only_the_window(image: &[u8], windowed: &[u8]) -> bool {
    let (at, offset, _) = modulator_entry(image);
    let window = offset.saturating_add(WINDOW_AT);
    let entry = at..at.saturating_add(64);
    let mask = window..window.saturating_add(2);
    image.len() == windowed.len()
        && image[mask.clone()] == [0; 2]
        && differing(image, windowed)
            .iter()
            .all(|p| mask.contains(p) || entry.contains(p))
        && with_window_bytes(windowed, 0) == image
}

// ---------------------------------------------------------------- the run (brief 056)

/// H-22's first block from H-22's image with the window unset (H-23's calibration, ADR-0133's
/// stopping rule step 2): H-22's run for one block — the engine's critic, no task critic, the
/// arm's first mapping — held to H-22's pinned first block table by table.
fn h22_first_block(valued: &[u8], arm: Reversal, k: usize, name: &str) {
    let mut exec = signed_from(valued, 1024);
    assert_eq!(
        (
            exec.critic(),
            exec.critic_window_ticks(),
            exec.istdp_target_period_ticks()
        ),
        (Some(VALUED_CRITIC), 0, TARGET_PERIOD_1024),
        "{name}: H-22's image carries the critic and the target, and no window"
    );
    let sets = geometry(1024, ROTATION_1024);
    let groups = groups_of(&exec, &sets);
    let mut weights: Vec<Weights> = Vec::new();
    let (run, moves, expected, values) = earned_run_valued(
        &mut exec,
        Feedback::Answer,
        first_mapping(arm),
        1024,
        BLOCK,
        GATE_BASELINE_Q16,
        &SCHEDULE_FLIPS,
        true,
        None,
        &mut |exec, trial| {
            if trial.wrapping_add(1) % BLOCK == 0 {
                weights.push(weights_by_group(exec, &groups));
            }
        },
    );
    assert!(expected.is_empty(), "{name}: the task carries no critic");
    let (blocks, _, trials, read, _) = &run;
    let compositions: Vec<Composition> = trials.chunks(BLOCK).map(composition).collect();
    let by_block = value_blocks(read, &values);
    eprintln!(
        "DUMP {name} H-22's first block {:?} earned {:?} values {:?} weights {:?}",
        blocks,
        earned_blocks(read),
        by_block,
        weights
    );
    assert_eq!(blocks.as_slice(), &VALUED_BLOCKS_1024[k][..1], "{name}");
    assert_eq!(
        compositions.as_slice(),
        &VALUED_COMPOSITIONS_1024[k][..1],
        "{name}"
    );
    assert_eq!(
        earned_blocks(read).as_slice(),
        &VALUED_EARNED_1024[k][..1],
        "{name}"
    );
    assert_eq!(
        moves_blocks(read, &moves).as_slice(),
        &VALUED_MOVES_1024[k][..1],
        "{name}"
    );
    assert_eq!(by_block.as_slice(), &VALUED_VALUES_1024[k][..1], "{name}");
    assert_eq!(weights.as_slice(), &VALUED_WEIGHTS_1024[k][..1], "{name}");
}

/// What brief 056 reads of a run beside H-22's tables: the four couplings at the end of the
/// first trial under each new mapping, the value weights by group at every block's end, and at
/// every trial's reward the spikes the window admitted by group.
#[derive(Clone, Debug, PartialEq, Eq)]
struct WindowedWatch {
    at_flips: [[[i64; 2]; 2]; 3],
    weights: Vec<Weights>,
    admitted: Vec<[u32; GROUPS]>,
}

/// An arm's run from the windowed engine (brief 056): H-22's run — `earned_run_valued` under the
/// answer's feedback at the gate's zero with the signed gate set, the arm's first mapping and
/// H-20's flips, the task carrying no critic — with the engine's window set, the engine's value,
/// error, weights and opening held to the harness's at every trial; at the end of the first trial
/// under each new mapping the four couplings, at every block's end the weights by group, and at
/// every trial's reward the train's spikes by group within `window` ticks after the opening the
/// reward closed — the engine's start at the first, each reward's tick after it.
fn windowed_run(
    exec: &mut Engine,
    arm: Reversal,
    sets: &[Set; 4],
    groups: &[usize],
    window: u16,
) -> (EarnedRun, Vec<Moves>, Vec<i32>, WindowedWatch) {
    let mut at_flips: [Option<[[i64; 2]; 2]>; 3] = [None; 3];
    let mut weights: Vec<Weights> = Vec::new();
    let mut admitted: Vec<[u32; GROUPS]> = Vec::with_capacity(SCHEDULE_TRIALS);
    let mut opened = exec.ticks();
    let (run, moves, expected, values) = earned_run_valued(
        exec,
        Feedback::Answer,
        first_mapping(arm),
        1024,
        SCHEDULE_TRIALS,
        GATE_BASELINE_Q16,
        &SCHEDULE_FLIPS,
        true,
        None,
        &mut |exec, trial| {
            let mut in_window = [0u32; GROUPS];
            for &(tick, unit) in exec.train() {
                let since = u64::from(tick).checked_sub(opened);
                if since.is_some_and(|d| d < u64::from(window)) {
                    if let Some(n) = groups
                        .get(unit as usize)
                        .and_then(|&g| in_window.get_mut(g))
                    {
                        *n = n.saturating_add(1);
                    }
                }
            }
            admitted.push(in_window);
            opened = exec.ticks();
            if let Some(f) = SCHEDULE_FLIPS.iter().position(|&f| f == trial) {
                at_flips[f] = Some(pair_couplings(exec, sets));
            }
            if trial.wrapping_add(1) % BLOCK == 0 {
                weights.push(weights_by_group(exec, groups));
            }
        },
    );
    assert!(expected.is_empty(), "the task carries no critic");
    let at_flips = at_flips.map(|c| c.expect("the run reached the trial after every flip"));
    (
        run,
        moves,
        values,
        WindowedWatch {
            at_flips,
            weights,
            admitted,
        },
    )
}

/// One arm of H-23 at 1 024 units (brief 056): the calibration before any rewarded run (H-23's
/// stopping rule, step 2) — the settled engine held to ADR-0077 step by step and its images,
/// H-20's image by its CRC, a frozen block from the zero image held to ADR-0077's frozen run,
/// H-21's image by its CRC at format 20 and at 18, H-22's image by its CRC at 20 and at 19 and
/// its first block reproduced with the window unset — then the window's length read by its rule
/// from H-22's image and held to the length committed first, the image the arm decodes, H-22's
/// with the window written, shown to differ from H-22's in the window's two bytes and the
/// section's seal alone, and decoded; then the arm's 7 680 trials from it with no task critic
/// and H-20's flips; everything dumped, the clauses and the readings computed before anything is
/// held; then the assertion, and the pinned tables of the whole run.
fn windowed_arm(arm: Reversal) {
    let k = WINDOWED_ARMS
        .iter()
        .position(|&a| a == arm)
        .expect("an arm of H-23");
    let name = format!("windowed1024 {arm:?}");
    let (zero, signed) = signed_images(&name);
    assert_eq!(
        pinned_crc(&signed),
        PUNISHED_IMAGE_CRC_1024,
        "{name}: H-20's image, H-19's and H-18's"
    );
    {
        let mut frozen = frozen_from(&zero, 1024);
        assert_eq!(
            (frozen.inhibitory_baseline_q16(), frozen.signed_gate()),
            (None, false),
            "{name}: the calibration's image leaves the inhibitory baseline and the signed gate unset"
        );
        let calibration = taught_run(&mut frozen, Arm::Withheld, 1024, BLOCK);
        calibration_holds(&format!("{name} calibration"), &calibration);
    }
    let targeted = targeted_image(&signed, TARGET_PERIOD_1024);
    assert!(
        only_the_target(&signed, &targeted),
        "{name}: H-21's image is H-20's in every byte but the target period's and the seal"
    );
    assert_eq!(
        (pinned_crc(&targeted), crc64(&with_version(&targeted, 18))),
        (TARGET_IMAGE_CRC_1024, TARGET_IMAGE_CRC_FORMAT_18_1024),
        "{name}: H-21's image, and as H-21 read it"
    );
    let valued = valued_image(&targeted, VALUED_CRITIC);
    assert!(
        only_the_critic(&targeted, &valued),
        "{name}: H-22's image is H-21's in every byte but the critic's and the seal"
    );
    assert_eq!(
        (pinned_crc(&valued), crc64(&with_version(&valued, 19))),
        (VALUED_IMAGE_CRC_1024, VALUED_IMAGE_CRC_FORMAT_19_1024),
        "{name}: H-22's image, and as H-22 read it"
    );
    h22_first_block(&valued, arm, k, &name);
    eprintln!(
        "DUMP {name} calibration holds: ADR-0077's settled candidate, H-20's, H-21's and H-22's images and H-22's first block"
    );
    // The window's length by its rule, over the arena the loader fills from H-22's image.
    let window =
        shortest_delay(signed_from(&valued, 1024).blocks()).expect("the image carries a synapse");
    eprintln!("DUMP {name} the window's rule reads {window} ticks");
    assert_eq!(
        window, WINDOW_TICKS_1024,
        "{name}: the length committed before the run"
    );
    // The image the arm decodes: H-22's, the window written and nothing else.
    let image_bytes = with_window_bytes(&valued, window);
    assert!(
        only_the_window(&valued, &image_bytes),
        "{name}: the image is H-22's in every byte but the window's and the seal"
    );
    assert_eq!(
        pinned_crc(&image_bytes),
        WINDOWED_IMAGE_CRC_1024,
        "{name}: the image each arm decodes"
    );
    let sets = geometry(1024, ROTATION_1024);
    let mut exec = signed_from(&image_bytes, 1024);
    assert_eq!(
        (
            exec.critic(),
            exec.critic_window_ticks(),
            exec.istdp_target_period_ticks(),
            exec.window_opened()
        ),
        (
            Some(VALUED_CRITIC),
            WINDOW_TICKS_1024,
            TARGET_PERIOD_1024,
            exec.ticks()
        ),
        "{name}: the image carries the critic, its window and the target, the window open at the load"
    );
    assert!(
        exec.units().iter().all(|u| u.value_weight == 0) && exec.features().iter().all(|&c| c == 0),
        "{name}: every weight and every count zero"
    );
    let image_sums = QUIET_1024[SETTLED].1;
    assert_eq!(
        weights_by_polarity(&exec),
        image_sums,
        "{name}: the image's sums"
    );
    assert_eq!(
        pair_couplings(&exec, &sets),
        IMAGE_COUPLINGS_1024,
        "{name}: the same image"
    );
    let groups = groups_of(&exec, &sets);
    eprintln!(
        "DUMP {name} image crc {:#018x}, {} bytes differ from H-22's, groups {:?}",
        crc64(&image_bytes),
        differing(&valued, &image_bytes).len(),
        group_sizes(&groups)
    );
    let image = weights_of(&exec);
    let first = first_mapping(arm);
    let (run, moves, values, watched) = windowed_run(&mut exec, arm, &sets, &groups, window);
    let (blocks, trace, trials, read, volley_ticks) = &run;
    let earned = earned_blocks(read);
    let compositions: Vec<Composition> = trials.chunks(BLOCK).map(composition).collect();
    let moved = moves_blocks(read, &moves);
    let strong = strong_scheduled(read, first);
    let valued_by_block = value_blocks(read, &values);
    let admitted = admitted_blocks(read, &watched.admitted);
    assert_eq!(blocks.len(), SCHEDULE_BLOCKS, "{name}: 120 blocks");
    assert_eq!(
        (read.len(), values.len(), watched.admitted.len()),
        (SCHEDULE_TRIALS, SCHEDULE_TRIALS, SCHEDULE_TRIALS)
    );
    assert_eq!(
        (
            compositions.len(),
            earned.len(),
            moved.len(),
            valued_by_block.len(),
            strong.len(),
            watched.weights.len(),
            admitted.len()
        ),
        (
            SCHEDULE_BLOCKS,
            SCHEDULE_BLOCKS,
            SCHEDULE_BLOCKS,
            SCHEDULE_BLOCKS,
            SCHEDULE_BLOCKS - FLIP_BLOCK,
            SCHEDULE_BLOCKS,
            SCHEDULE_BLOCKS
        )
    );
    // The run's tables dumped whole, as they are pinned, before anything is held or read.
    eprintln!("DUMP {name} PIN blocks {blocks:?}");
    eprintln!("DUMP {name} PIN trace {trace:#018x}");
    eprintln!("DUMP {name} PIN compositions {compositions:?}");
    eprintln!("DUMP {name} PIN earned {earned:?}");
    eprintln!("DUMP {name} PIN read {:#018x}", earned_hash(read));
    eprintln!("DUMP {name} PIN census {:?}", census_of(volley_ticks));
    eprintln!("DUMP {name} PIN moves {moved:?}");
    eprintln!("DUMP {name} PIN strong {strong:?}");
    eprintln!("DUMP {name} PIN at flips {:?}", watched.at_flips);
    eprintln!("DUMP {name} PIN values {valued_by_block:?}");
    eprintln!("DUMP {name} PIN value hash {:#018x}", values_hash(&values));
    eprintln!("DUMP {name} PIN weights {:?}", watched.weights);
    eprintln!("DUMP {name} PIN admitted {admitted:?}");
    // Everything read and dumped, and the clauses and the readings computed, before anything
    // else is held.
    dump_earned(&name, &run, &earned);
    let reach = reach_by_polarity(&exec, &image, 1024, &ALL_PAIRS);
    let correct = mapping_correct(blocks);
    let over = first_over(blocks);
    let stimulus_read = stimulus_values(read, &values);
    let first_new_read = first_new_scheduled(read, first);
    let crossings_read = crossings(blocks);
    let crossed = crossed_scheduled(&earned, first);
    let tally_read = tally(blocks);
    let settle = settle_scheduled(blocks, first);
    let highest_read = highest(blocks);
    let strong_sum = strong_by_flip(&strong);
    let punished_moves = moves_by_mapping(&moved, 1);
    let rewarded_moves = moves_by_mapping(&moved, 0);
    let once = once_blocks(blocks, &compositions);
    let falls = falls_every_block(image_sums.0, blocks);
    let sums_after = weights_by_polarity(&exec);
    let troughs_read = troughs(&value_means(&valued_by_block));
    eprintln!(
        "DUMP {name} PIN readings correct {correct:?} over {over:?} stimulus values {stimulus_read:?} reach {reach:?} first new {first_new_read:?} crossings {crossings_read:?} crossed {crossed:?} tally {tally_read:?} settle {settle:?} highest {highest_read:?} strong total {strong_sum:?} punished moves {punished_moves:?} rewarded moves {rewarded_moves:?} once {once} falls {falls} sums after {sums_after:?} troughs {troughs_read:?}"
    );
    eprintln!(
        "DUMP {name} verdict of this arm: learned {:?} over {over:?} revised {:?} held {:?} settle per myriad {:?}",
        correct.map(|c| c >= REWARDED_MIN),
        reversals_within(crossings_read),
        stimulus_read.map(|m| m.map(holds_expected)),
        settle_per_myriad(settle, first)
    );
    eprintln!(
        "DUMP {name} the prediction, clause 3 holds: {REVERSALS_PREDICTED}; read {:?}",
        reversals_within(crossings_read)
    );
    eprintln!(
        "DUMP {name} value by block beside H-22's and H-21's expectation {:?}",
        value_means(&valued_by_block)
            .iter()
            .zip(value_means(VALUED_VALUES_1024[k]))
            .zip(TARGET_EXPECTED_1024[k])
            .map(|((w, v), e)| (*w, v, *e))
            .collect::<Vec<_>>()
    );
    eprintln!(
        "DUMP {name} troughs {troughs_read:?} beside H-22's {:?} and H-21's {:?}",
        troughs(&value_means(VALUED_VALUES_1024[k])),
        troughs(&expected_means(TARGET_EXPECTED_1024[k]))
    );
    eprintln!(
        "DUMP {name} strong by flip {strong_sum:?} beside H-22's {:?} and H-21's {:?}",
        STRONG_BY_FLIP_VALUED_1024[k], STRONG_BY_FLIP_TARGET_1024[k]
    );
    eprintln!(
        "DUMP {name} inhibitory course {:?} beside H-22's {:?}",
        course(image_sums.0, blocks),
        course(image_sums.0, VALUED_BLOCKS_1024[k])
    );
    eprintln!(
        "DUMP {name} crossings {crossings_read:?} beside H-22's {:?}, H-21's {:?} and H-20's {:?}",
        CROSSINGS_VALUED_1024[k], CROSSINGS_TARGET_1024[k], CROSSINGS_1024[k]
    );
    eprintln!(
        "DUMP {name} couplings course {:?}",
        couplings_course(blocks)
    );
    eprintln!(
        "DUMP {name} signal {:?}",
        blocks.iter().map(|b| b.9).collect::<Vec<i32>>()
    );
    // The assertion, after the dump and beside the verdict: H-18's rule, as H-20 to H-22 hold it.
    assert!(
        punished_held(&reach),
        "{name}: no excitatory synapse outside the four stimulus–readout pairs moved: {reach:?}"
    );
    // The pinned tables of the whole run, and the readings as the constants state.
    pinned(
        &format!("{name} sight"),
        blocks,
        *trace,
        WINDOWED_BLOCKS_1024[k],
        WINDOWED_TRACES_1024[k],
    );
    assert_eq!(
        compositions.as_slice(),
        WINDOWED_COMPOSITIONS_1024[k],
        "{name}: the composition per block"
    );
    assert_eq!(
        earned.as_slice(),
        WINDOWED_EARNED_1024[k],
        "{name}: the earned blocks"
    );
    assert_eq!(
        earned_hash(read),
        WINDOWED_READ_1024[k],
        "{name}: the readings"
    );
    assert_eq!(
        census_of(volley_ticks),
        WINDOWED_CENSUS_1024[k].to_vec(),
        "{name}: the volley's ticks"
    );
    assert_eq!(
        moved.as_slice(),
        WINDOWED_MOVES_1024[k],
        "{name}: the moves per block"
    );
    assert_eq!(
        strong.as_slice(),
        WINDOWED_STRONG_1024[k],
        "{name}: the strong punishments per block"
    );
    assert_eq!(watched.at_flips, WINDOWED_AT_FLIPS_1024[k]);
    assert_eq!(
        valued_by_block.as_slice(),
        WINDOWED_VALUES_1024[k],
        "{name}: the engine's value per block"
    );
    assert_eq!(
        values_hash(&values),
        WINDOWED_VALUE_HASH_1024[k],
        "{name}: every trial's value"
    );
    assert_eq!(
        watched.weights.as_slice(),
        WINDOWED_WEIGHTS_1024[k],
        "{name}: the weights by group per block"
    );
    assert_eq!(
        admitted.as_slice(),
        WINDOWED_ADMITTED_1024[k],
        "{name}: the spikes the window admitted per block"
    );
    assert_eq!(correct, CORRECT_WINDOWED_1024[k]);
    assert_eq!(over, OVER_WINDOWED_1024[k]);
    assert_eq!(stimulus_read, STIMULUS_VALUES_WINDOWED_1024[k]);
    assert_eq!(reach, REACH_WINDOWED_1024[k]);
    assert_eq!(first_new_read, FIRST_NEW_WINDOWED_1024[k]);
    assert_eq!(crossings_read, CROSSINGS_WINDOWED_1024[k]);
    assert_eq!(crossed, CROSSED_WINDOWED_1024[k]);
    assert_eq!(tally_read, TALLY_WINDOWED_1024[k]);
    assert_eq!(settle, SETTLE_WINDOWED_1024[k]);
    assert_eq!(highest_read, HIGHEST_WINDOWED_1024[k]);
    assert_eq!(strong_sum, STRONG_BY_FLIP_WINDOWED_1024[k]);
    assert_eq!(punished_moves, PUNISHED_MOVES_WINDOWED_1024[k]);
    assert_eq!(rewarded_moves, REWARDED_MOVES_WINDOWED_1024[k]);
    assert_eq!(once, ONCE_BLOCKS_WINDOWED_1024[k]);
    assert_eq!(falls, FALLS_WINDOWED_1024[k]);
    assert_eq!(troughs_read, TROUGHS_WINDOWED_1024[k]);
    assert_eq!(
        (sums_after, blocks.last().map(|b| (b.7, b.8))),
        (
            SUMS_AFTER_WINDOWED_1024[k],
            Some(SUMS_AFTER_WINDOWED_1024[k])
        ),
        "{name}: the sums after the run are the last block's"
    );
}

/// H-23's arm that starts from the assignment (brief 056): H-22's arm from the assignment with
/// the engine's critic counting only within its window.
#[test]
#[ignore]
fn a_critic_with_a_window_from_the_assignment_at_1024_units_exhaustive() {
    windowed_arm(Reversal::AssignmentFirst);
}

/// H-23's arm that starts from the mirrored assignment (brief 056): H-22's arm from the mirrored
/// assignment with the engine's critic counting only within its window.
#[test]
#[ignore]
fn a_critic_with_a_window_from_the_mirrored_assignment_at_1024_units_exhaustive() {
    windowed_arm(Reversal::MirroredFirst);
}

/// The gate's test (ADR-0061's class; brief 056): the arms and the constants as ADR-0133 and
/// ADR-0135 fixed them, H-22's restated; the window's rule over images written by hand and over
/// the instrument's network, whose delays the settled image carries; ADR-0135's arithmetic over
/// numbers written by hand — the volley's step, the background the window admits, the step's
/// floor and dead band; H-23's clauses 3 and 4 at their edges and the verdict naming the clause,
/// the arm, the mapping and the stimulus; the readings' rules over tables written by hand; and
/// the image's patch on the instrument's network's image, shown to touch the window's two bytes
/// and the section's seal alone, to be read by the loader and refused at another length, and to
/// be undone by writing zeros back; and, over the arms' pinned tables, the verdict as written and
/// every reading, block by block. No run, and nothing else added to the gate.
#[test]
fn the_window_s_rule_its_arithmetic_the_clauses_of_h_23_and_the_image_s_patch() {
    // The arms and the constants, H-22's restated.
    assert_eq!(WINDOWED_ARMS, VALUED_ARMS);
    assert_eq!(
        WINDOWED_ARMS,
        [Reversal::AssignmentFirst, Reversal::MirroredFirst]
    );
    assert_eq!(
        (REVERSALS_PREDICTED, VALUED_PREDICTED),
        (true, None),
        "ADR-0133 predicts clause 3 holds, and ADR-0130 no verdict of H-22"
    );
    assert_eq!(VALUED_CRITIC, ValueCritic { shift: 9, scale: 2 });
    assert_eq!(
        (
            WINDOW_TICKS_1024,
            REVERSAL_BLOCKS_MAX,
            HOLDS_DIVISOR,
            WINDOW_AT
        ),
        (100, 23, 4, 52)
    );
    assert_eq!((VOLLEY_UNITS, TASK_STEP_SHIFT, REWARD_Q16), (51, 5, ONE));
    assert_eq!(
        (TARGET_PERIOD_1024, TARGET_TICKS_PER_SPIKE),
        (58_201, 58_201)
    );
    assert_eq!(
        (
            VALUED_IMAGE_CRC_1024,
            VALUED_IMAGE_CRC_FORMAT_19_1024,
            WINDOWED_IMAGE_CRC_1024
        ),
        (
            0x82d3_5098_0232_c4e2,
            0xbf67_9785_7fda_0809,
            0x387f_1060_a1f1_d99b
        ),
        "H-22's image at format 25 and as H-22 read it at 19, and the image each arm decodes"
    );
    // Clause 3's bound is the slowest reversal H-20 and H-21 read with the task's critic, both
    // arms: 23 blocks, H-21's first from the mirrored assignment.
    let slowest = CROSSINGS_1024
        .iter()
        .chain(&CROSSINGS_TARGET_1024)
        .flat_map(|arm| arm[1..].iter().map(|c| c.expect("every reversal crossed")))
        .max();
    assert_eq!(slowest, Some(REVERSAL_BLOCKS_MAX));
    assert_eq!(CROSSINGS_TARGET_1024[1][1], Some(REVERSAL_BLOCKS_MAX));
    // The window's rule over networks written by hand: the least delay of any synapse, whichever
    // block holds it; an empty slot's delay no synapse's.
    {
        let mut exec = Executor::<8>::new(Config {
            units: 3,
            blocks: 3,
            ..Config::default()
        })
        .unwrap();
        assert_eq!(shortest_delay(exec.blocks()), None, "no synapse");
        let blocks = exec.blocks_mut();
        assert!(blocks[0].set_synapse(0, 1, 100, 300, false));
        assert!(blocks[2].set_synapse(3, 2, 100, 101, false));
        blocks[1].delays_ticks[2] = 5;
        assert_eq!(shortest_delay(exec.blocks()), Some(101));
        assert!(exec.blocks_mut()[1].set_synapse(1, 0, 100, 100, true));
        assert_eq!(shortest_delay(exec.blocks()), Some(100));
    }
    // Over the instrument's network at 1 024 units, whose delays every image of it carries: no
    // rule moves a delay, so H-21's image reads what the network was synthesised with — the local
    // band's floor, 100 ticks, every delay in the local band, 100 to 300, or the far one, from
    // 1 400.
    let p = prior(1024);
    let exec = at_gain(&p, config(1024, 2, 0), GAIN_1024);
    assert_eq!(shortest_delay(exec.blocks()), Some(WINDOW_TICKS_1024));
    let delays: Vec<u16> = exec
        .blocks()
        .iter()
        .flat_map(|b| {
            (0..4)
                .filter(|&s| b.target(s).is_some())
                .map(|s| b.delays_ticks[s])
        })
        .collect();
    assert!(
        delays
            .iter()
            .all(|&d| (100..=300).contains(&d) || d >= 1_400)
    );
    let at_floor = delays.iter().filter(|&&d| d == WINDOW_TICKS_1024).count();
    assert!(at_floor > 0, "a synapse at the floor");
    eprintln!(
        "DUMP the instrument's network: {} synapses, {at_floor} at the window's length",
        delays.len()
    );
    // ADR-0135's arithmetic. One volley under the error of a whole reward against a value of
    // zero moves its own value by 51 / 2 048 of the reward, as in H-22, 1 632 of 65 536.
    let volley = [1u32; VOLLEY_UNITS as usize];
    let (_, _, moved) = value_step(&[0; VOLLEY_UNITS as usize], &volley, VALUED_CRITIC, ONE);
    assert_eq!(
        VALUED_CRITIC.value_q16(moved.iter().copied().zip(volley)),
        1_632
    );
    assert_eq!(
        ONE >> TASK_STEP_SHIFT,
        2_048,
        "the task critic's step, above the volley's"
    );
    // The window admits the volley and about two background spikes: 1 024 units over 100 ticks
    // at a spike every 58 201 ticks a unit, 1.76. With them the same step moves its own trial's
    // value by 53 / 2 048, where H-22's 351 spikes moved it by 431 / 2 048 (ADR-0132).
    assert_eq!(
        (1_024u64 * u64::from(WINDOW_TICKS_1024) * 100) / TARGET_TICKS_PER_SPIKE,
        175,
        "1.75 spikes, in hundredths, floored"
    );
    let window_spikes = [1u32; 53];
    let (_, _, moved) = value_step(&[0; 53], &window_spikes, VALUED_CRITIC, ONE);
    assert_eq!(
        VALUED_CRITIC.value_q16(moved.iter().copied().zip(window_spikes)),
        1_696
    );
    // The floor: a negative error moves each unit that fired one LSB down, 53 of them lowering
    // the value by 53 / 4, floored to 14 of the 65 536 a trial, against H-22's 88; a positive
    // error below 512 moves nothing, 0.78 per cent of the reward, as in H-22.
    let (_, _, floored) = value_step(&[0; 53], &window_spikes, VALUED_CRITIC, -1);
    assert_eq!(
        VALUED_CRITIC.value_q16(floored.iter().copied().zip(window_spikes)),
        -14
    );
    assert_eq!(
        (VALUED_CRITIC.step(0, 511, 1), VALUED_CRITIC.step(0, 512, 1)),
        (0, 1)
    );
    // The rail: the volley carries the whole reward at 5 141 a unit, 0.157 of the rail, as in
    // H-22, so the rule still resolves the value the clauses read.
    let at = |w: i16| VALUED_CRITIC.value_q16(core::iter::repeat_n((w, 1), 51));
    assert_eq!((at(5_140), at(5_141)), (65_535, 65_547));
    // Clause 3 at its edges: 23 blocks hold, 24 and none do not, each reversal on its own; the
    // first mapping's crossing is not read.
    assert_eq!(
        reversals_within([None, Some(23), Some(1), Some(REVERSAL_BLOCKS_MAX)]),
        [true; 3]
    );
    assert_eq!(
        reversals_within([Some(1), Some(24), None, Some(23)]),
        [false, false, true]
    );
    assert_eq!(
        reversals_within(CROSSINGS_VALUED_1024[0]),
        [false, true, false],
        "H-22 from the assignment: 30, 15 and 27"
    );
    assert_eq!(
        reversals_within(CROSSINGS_VALUED_1024[1]),
        [false, true, true],
        "H-22 from the mirrored assignment: 30, 10 and 22"
    );
    assert_eq!(reversals_within(CROSSINGS_TARGET_1024[0]), [true; 3]);
    assert_eq!(reversals_within(CROSSINGS_TARGET_1024[1]), [true; 3]);
    // Clause 4 at its edges: 64 trials, 48 correct, 2p − 1 a half; the values' sum 32 rewards,
    // within a quarter of the reward a trial, 16 rewards, either side; one LSB past on either
    // side does not hold; no trial does not.
    let r = i64::from(ONE);
    let expected = r.saturating_mul(32);
    let quarter = r.saturating_mul(16);
    for v in [
        expected,
        expected.saturating_add(quarter),
        expected.saturating_sub(quarter),
    ] {
        assert!(holds_expected((64, 48, v)), "{v}");
    }
    assert!(!holds_expected((
        64,
        48,
        expected.saturating_add(quarter).saturating_add(1)
    )));
    assert!(!holds_expected((
        64,
        48,
        expected.saturating_sub(quarter).saturating_sub(1)
    )));
    assert!(!holds_expected((0, 0, 0)), "no trial holds nothing");
    assert!(
        holds_expected((64, 16, r.saturating_mul(-32))),
        "2p − 1 below zero"
    );
    assert!(
        holds_expected((1, 0, -r)) && holds_expected((1, 1, r)),
        "one trial each way"
    );
    assert!(!holds_expected((1, 1, r.saturating_mul(3) / 4 - 1)));
    // Over trials written by hand: a run of 7 680 whose trials alternate stimuli; the last 128 of
    // each mapping read, the earlier ones not; values a quarter under and over what the clause
    // takes.
    let trial =
        |s: u8, correct: bool| -> EarnedTrial { (s, [0; 2], None, correct, 0, [[0; 2]; 2], 0, 0) };
    let mut read: Vec<EarnedTrial> = (0..SCHEDULE_TRIALS)
        .map(|t| trial((t % 2) as u8, true))
        .collect();
    let mut values: Vec<i32> = vec![i32::MAX; SCHEDULE_TRIALS];
    for &(_, end) in &SPANS {
        for t in end.saturating_sub(128)..end {
            read[t] = trial((t % 2) as u8, t % 4 < 2);
            values[t] = if t % 2 == 0 { 0 } else { ONE / 2 };
        }
    }
    let by_mapping = stimulus_values(&read, &values);
    assert_eq!(
        by_mapping,
        [[(64, 32, 0), (64, 32, 32 * r)]; 4],
        "each stimulus half right in the last 128, A valued 0 and B a half"
    );
    assert_eq!(
        by_mapping.map(|m| m.map(holds_expected)),
        [[true, false]; 4],
        "A at 2p − 1, B half a reward over"
    );
    assert_eq!(
        stimulus_values(&read[1..], &values[1..]),
        [[(0, 0, 0); 2]; 4]
    );
    assert_eq!(
        stimulus_values(&read, &values[1..]),
        [[(0, 0, 0); 2]; 4],
        "a value a trial"
    );
    // The verdict: every clause over tables written by hand, and each clause failing on its own,
    // named.
    let full = vec![
        (
            BLOCK as u32,
            0,
            [[0; 2]; 2],
            [0; 2],
            [0; 2],
            [0; 2],
            0,
            0,
            0,
            0,
            IMAGE_COUPLINGS_1024,
            0,
        );
        SCHEDULE_BLOCKS
    ];
    let learning_yes = Scheduled {
        learned: [[true; 4]; 2],
        bounded: [true; 2],
        over: [None; 2],
        yes: true,
    };
    let held = [[(64, 64, r.saturating_mul(64)); 2]; 4];
    assert_eq!(
        windowed([&full, &full], [held, held]),
        Windowed {
            learning: learning_yes,
            revised: [[true; 3]; 2],
            held: [[[true; 2]; 4]; 2],
            yes: true
        }
    );
    let mut slow = full.clone();
    for b in &mut slow[MAPPINGS[2].0..MAPPINGS[2].0 + REVERSAL_BLOCKS_MAX] {
        b.0 = CROSSING_MARK - 1;
    }
    assert_eq!(crossings(&slow)[2], Some(REVERSAL_BLOCKS_MAX + 1));
    let verdict = windowed([&full, &slow], [held, held]);
    assert_eq!(
        (verdict.learning, verdict.revised, verdict.yes),
        (learning_yes, [[true; 3], [true, false, true]], false),
        "clause 3 fails in the second arm's second reversal"
    );
    let mut unheld = held;
    unheld[3][1] = (64, 64, r.saturating_mul(48).saturating_sub(1));
    let verdict = windowed([&full, &full], [unheld, held]);
    assert_eq!(
        (verdict.held[0][3], verdict.held[1], verdict.yes),
        ([true, false], [[true; 2]; 4], false),
        "clause 4 fails for B in the first arm's fourth mapping"
    );
    let mut unlearned = full.clone();
    unlearned[MAPPINGS[1].1 - 1].0 = 0;
    unlearned[MAPPINGS[1].1 - 2].0 = 0;
    let verdict = windowed([&unlearned, &full], [held, held]);
    assert_eq!(
        (verdict.learning.learned[0], verdict.revised, verdict.yes),
        ([true, false, true, true], [[true; 3]; 2], false),
        "clause 1 fails in the first arm's second mapping, clause 3 holds"
    );
    // The readings' rules over tables written by hand.
    let read: Vec<EarnedTrial> = [0u8, 1, 0, 1].iter().map(|&s| trial(s, true)).collect();
    let per_trial = [
        [1, 51, 0, 0, 0, 1],
        [0, 0, 51, 0, 0, 0],
        [2, 50, 0, 1, 0, 0],
        [0, 1, 51, 0, 2, 0],
    ];
    assert_eq!(
        admitted_blocks(&read, &per_trial),
        [[[3, 101, 0, 1, 0, 1], [0, 1, 102, 0, 2, 0]]]
    );
    let mut means = vec![[0i64; 2]; SCHEDULE_BLOCKS];
    means[30] = [-5, 7];
    means[40] = [3, -9];
    means[60] = [-1, -1];
    means[100] = [2, 4];
    assert_eq!(troughs(&means), [[-5, -9], [-1, -1], [0, 0]]);
    assert_eq!(troughs(&means[..100]), [[-5, -9], [-1, -1], [0; 2]]);
    assert_eq!(
        value_means(&[[[2, 400, 1, 10], [2, 20, 2, 100]]]),
        [[200, 10]]
    );
    assert_eq!(
        expected_means(&[[-3, i32::MAX]]),
        [[-3, i64::from(i32::MAX)]]
    );
    // H-22's troughs and H-21's by the same rule: the depth ADR-0132 read after the first and
    // third flips, deeper than the task critic's.
    for k in 0..2 {
        let valued = troughs(&value_means(VALUED_VALUES_1024[k]));
        let target = troughs(&expected_means(TARGET_EXPECTED_1024[k]));
        eprintln!("DUMP troughs H-22 {valued:?} H-21 {target:?}");
        for f in [0usize, 2] {
            assert!(
                valued[f].iter().min() < target[f].iter().min(),
                "arm {k} flip {f}: H-22's value fell below H-21's expectation"
            );
        }
    }
    // The image's patch on the instrument's network's image, with the critic written as H-22's
    // is: the window written touches its two bytes and the entry's seal alone; the loader reads
    // it; zeros written back undo it; a byte moved elsewhere fails the check; a length the rule
    // does not give is refused by the loader.
    let img = valued_image(&Image::encode(&exec).expect("quiescent"), VALUED_CRITIC);
    let patched = with_window_bytes(&img, WINDOW_TICKS_1024);
    let moved = differing(&img, &patched);
    let (at, offset, _) = modulator_entry(&img);
    let window_bytes = offset.saturating_add(WINDOW_AT)..offset.saturating_add(WINDOW_AT + 2);
    let entry_bytes = at..at.saturating_add(64);
    assert!(
        !moved.is_empty()
            && moved.len() <= 10
            && moved
                .iter()
                .all(|p| window_bytes.contains(p) || entry_bytes.contains(p)),
        "the window's bytes and the entry's seal: {moved:?}"
    );
    assert!(only_the_window(&img, &patched));
    assert!(
        only_the_window(&img, &img),
        "nothing written, nothing moved"
    );
    assert!(
        !only_the_window(&patched, &patched),
        "an image that carries a window already"
    );
    assert_eq!(with_window_bytes(&patched, 0), img);
    let decoded = Image::decode::<2048>(&patched, config(1024, 2, 0)).expect("a well-formed image");
    assert_eq!(
        (
            decoded.critic(),
            decoded.critic_window_ticks(),
            decoded.window_opened()
        ),
        (Some(VALUED_CRITIC), WINDOW_TICKS_1024, decoded.ticks())
    );
    assert_eq!(weights_of(&decoded), weights_of(&exec));
    let mut elsewhere = patched.clone();
    elsewhere[offset.saturating_add(16)] ^= 1;
    assert!(!only_the_window(&img, &elsewhere), "the baseline's byte");
    for bad in [99u16, 101, 300] {
        assert!(
            matches!(
                Image::decode::<2048>(&with_window_bytes(&img, bad), config(1024, 2, 0)),
                Err(ImageError::WindowNotShortestDelay {
                    window,
                    shortest: Some(100)
                }) if window == bad
            ),
            "{bad}: refused by the loader"
        );
    }
    assert!(
        matches!(
            Image::decode::<2048>(
                &with_window_bytes(&Image::encode(&exec).expect("quiescent"), WINDOW_TICKS_1024),
                config(1024, 2, 0)
            ),
            Err(ImageError::Config(ConfigError::WindowWithoutCritic))
        ),
        "no window without the critic"
    );
    // Over the arms' pinned tables: the verdict as written, by the rule committed first; the
    // readings as the constants state; and, block by block over each arm's 120 blocks, the tables
    // consistent with one another, with the assertion and with the oracle — the value's trials the
    // block's presentations, its correct trials the block's, clause 4's counts each mapping's last
    // two blocks', the window's spikes of the presented stimulus at most its units, each coupling
    // the one before plus what the oracle consolidated, the excitatory sum the image's plus the
    // four pairs' moves.
    let image_sums = QUIET_1024[SETTLED].1;
    let verdict = windowed(
        [WINDOWED_BLOCKS_1024[0], WINDOWED_BLOCKS_1024[1]],
        STIMULUS_VALUES_WINDOWED_1024,
    );
    assert_eq!(verdict, WINDOWED_1024, "the verdict as written");
    for (k, &arm) in WINDOWED_ARMS.iter().enumerate() {
        let first = first_mapping(arm);
        let blocks = WINDOWED_BLOCKS_1024[k];
        let earned = WINDOWED_EARNED_1024[k];
        let moved = WINDOWED_MOVES_1024[k];
        let compositions = WINDOWED_COMPOSITIONS_1024[k];
        let values = WINDOWED_VALUES_1024[k];
        let weights = WINDOWED_WEIGHTS_1024[k];
        let admitted = WINDOWED_ADMITTED_1024[k];
        let strong = WINDOWED_STRONG_1024[k];
        assert_eq!(
            [
                blocks.len(),
                compositions.len(),
                earned.len(),
                moved.len(),
                values.len(),
                weights.len(),
                admitted.len()
            ],
            [SCHEDULE_BLOCKS; 7],
            "{arm:?}: 120 blocks of each"
        );
        assert_eq!(strong.len(), SCHEDULE_BLOCKS - FLIP_BLOCK);
        assert_ne!(WINDOWED_TRACES_1024[k], 0);
        assert_ne!(WINDOWED_READ_1024[k], 0);
        assert_ne!(WINDOWED_VALUE_HASH_1024[k], 0);
        assert!(!WINDOWED_CENSUS_1024[k].is_empty());
        let correct = mapping_correct(blocks);
        assert_eq!(correct, CORRECT_WINDOWED_1024[k]);
        assert_eq!(
            correct.map(|c| c >= REWARDED_MIN),
            verdict.learning.learned[k]
        );
        assert_eq!(first_over(blocks), OVER_WINDOWED_1024[k]);
        assert_eq!(first_over(blocks).is_none(), verdict.learning.bounded[k]);
        assert_eq!(crossings(blocks), CROSSINGS_WINDOWED_1024[k]);
        assert_eq!(
            reversals_within(CROSSINGS_WINDOWED_1024[k]),
            verdict.revised[k]
        );
        assert_eq!(
            STIMULUS_VALUES_WINDOWED_1024[k].map(|m| m.map(holds_expected)),
            verdict.held[k]
        );
        assert_eq!(crossed_scheduled(earned, first), CROSSED_WINDOWED_1024[k]);
        assert_eq!(tally(blocks), TALLY_WINDOWED_1024[k]);
        assert_eq!(settle_scheduled(blocks, first), SETTLE_WINDOWED_1024[k]);
        assert_eq!(highest(blocks), HIGHEST_WINDOWED_1024[k]);
        assert_eq!(strong_by_flip(strong), STRONG_BY_FLIP_WINDOWED_1024[k]);
        assert_eq!(moves_by_mapping(moved, 1), PUNISHED_MOVES_WINDOWED_1024[k]);
        assert_eq!(moves_by_mapping(moved, 0), REWARDED_MOVES_WINDOWED_1024[k]);
        assert_eq!(
            once_blocks(blocks, compositions),
            ONCE_BLOCKS_WINDOWED_1024[k]
        );
        assert_eq!(
            falls_every_block(image_sums.0, blocks),
            FALLS_WINDOWED_1024[k]
        );
        assert_eq!(troughs(&value_means(values)), TROUGHS_WINDOWED_1024[k]);
        assert!(
            punished_held(&REACH_WINDOWED_1024[k]),
            "{arm:?}: the assertion held"
        );
        let last = blocks.last().expect("a block");
        assert_eq!(SUMS_AFTER_WINDOWED_1024[k], (last.7, last.8));
        // Each mapping's last two blocks hold clause 4's trials, correct trials and values.
        for (m, &(_, end)) in MAPPINGS.iter().enumerate() {
            for s in 0..2 {
                let (n, c, v) = values[end.saturating_sub(LAST_BLOCKS)..end].iter().fold(
                    (0i64, 0i64, 0i64),
                    |(n, c, v), b| {
                        (
                            n.saturating_add(b[s][0]),
                            c.saturating_add(b[s][2]),
                            v.saturating_add(b[s][1]),
                        )
                    },
                );
                let (tn, tc, tv) = STIMULUS_VALUES_WINDOWED_1024[k][m][s];
                assert_eq!(
                    (n, c, v),
                    (i64::from(tn), i64::from(tc), tv),
                    "{arm:?} mapping {m} stimulus {s}: clause 4's trials are the value table's"
                );
            }
        }
        let mut previous = IMAGE_COUPLINGS_1024;
        for (j, block) in blocks.iter().enumerate() {
            let in_force = mirrored_at(first, j);
            assert_eq!(
                block.1, VALUED_BLOCKS_1024[k][j].1,
                "{arm:?} block {j}: the same trials present A as in H-22"
            );
            let presented = [block.1, (BLOCK as u32).saturating_sub(block.1)];
            for (s, &n) in presented.iter().enumerate() {
                assert_eq!(
                    earned[j].0[s].iter().sum::<u32>(),
                    n,
                    "{arm:?} block {j}: every presentation of {s} selected or tied"
                );
                assert_eq!(
                    values[j][s][0],
                    i64::from(n),
                    "{arm:?} block {j}: a value for every presentation of {s}"
                );
                assert_eq!(
                    values[j][s][2],
                    i64::from(earned[j].0[s][answer_of(s as u8, in_force)]),
                    "{arm:?} block {j}: the value's correct trials of {s} the block's"
                );
                // The window admits the presented stimulus's units at most once a presentation
                // each, its volley, and the other stimulus's and the readouts' only as background.
                assert!(
                    admitted[j][s][s.saturating_add(1)] <= n.saturating_mul(VOLLEY_UNITS),
                    "{arm:?} block {j}: at most the volley of {s}"
                );
            }
            let correct = earned[j].0[0][answer_of(0, in_force)]
                .saturating_add(earned[j].0[1][answer_of(1, in_force)]);
            assert_eq!(
                block.0, correct,
                "{arm:?} block {j}: correct under the mapping in force"
            );
            let mut rise = 0i64;
            let mut consolidated = 0i64;
            for &(s, r) in &ALL_PAIRS {
                assert_eq!(
                    block.10[s][r],
                    previous[s][r].saturating_add(earned[j].2[s][r]),
                    "{arm:?} block {j}: {s}→{r} moved by what the oracle consolidated"
                );
                rise =
                    rise.saturating_add(block.10[s][r].saturating_sub(IMAGE_COUPLINGS_1024[s][r]));
                consolidated = consolidated.saturating_add(earned[j].2[s][r]);
            }
            assert_eq!(
                block.8,
                image_sums.1.saturating_add(rise),
                "{arm:?} block {j}: the excitatory sum moved by the four pairs' moves and nothing else"
            );
            let moved_sum = moved[j]
                .iter()
                .flat_map(|m| m.1.iter())
                .fold(0i64, |sum, &a| sum.saturating_add(a));
            assert_eq!(
                moved_sum, consolidated,
                "{arm:?} block {j}: what the addressed synapses moved is what the oracle consolidated"
            );
            assert!(
                weights[j].1 <= weights[j].2,
                "{arm:?} block {j}: the lowest weight at most the highest"
            );
            previous = block.10;
        }
    }
}

// --------------------- the measurement (brief 056), its tables in inhibition/pins/h23.rs

/// H-22's image by its CRC-64: H-21's with the critic written (ADR-0132), at format 25 (it was
/// `0xeae8ad819564a88a` at 20, the CRC H-23 to H-29 read, `0xabf42a8e54824c50` at 21,
/// `0x68d1a39e16a9613e` at 22, `0x29cd2491d74f85e4` at 23 and `0xc3cfd797c3d42038` at 24;
/// ADR-0155, ADR-0180, ADR-0189, ADR-0194 and ADR-0202 re-pinned it with the format as ADR-0095
/// re-pinned H-17's).
/// ADR-0221 moved the format to 26 for the magic alone, and the pin holds the image at 25 since
/// (`pinned_crc`, ADR-0222).
const VALUED_IMAGE_CRC_1024: u64 = 0x82d350980232c4e2;
/// The same image with its header's version written back to 19 and the header resealed: the
/// CRC-64 H-22 read (ADR-0132), so that every byte of the image but the version and the seal is
/// the image H-22 ran from (ADR-0134, as ADR-0095).
const VALUED_IMAGE_CRC_FORMAT_19_1024: u64 = 0xbf6797857fda0809;
/// The image each arm of H-23 decodes: H-22's with the window written at the length its rule
/// reads, 100 ticks, committed before any rewarded run. At format 25: ADR-0155 moved the format
/// from 20, ADR-0180 from 21, where it was `0x11586a76f7415129`, ADR-0189 from 22, where it was
/// `0xd27de366b56a7c47`, ADR-0194 from 23, where it was `0x93616469748c989d`, and ADR-0202 from
/// 24, where it was `0x7963976f60173d41`, and each re-pinned it as ADR-0095 re-pinned H-17's.
/// ADR-0221 moved the format to 26 for the magic alone, and the pin holds the image at 25 since
/// (`pinned_crc`, ADR-0222).
const WINDOWED_IMAGE_CRC_1024: u64 = 0x387f1060a1f1d99b;
/// The same image with its header's version written back to 20 and the header resealed: the
/// CRC-64 every arm from H-23's to H-29's read (ADR-0135 to ADR-0153), so that every byte of the
/// image but the version and the seal is the image they ran from (ADR-0155, as ADR-0095).
const WINDOWED_IMAGE_CRC_FORMAT_20_1024: u64 = 0x5044ed7936a7b5f3;

const WINDOWED_TRACES_1024: [u64; 2] = [0x8ef90c39dced6622, 0x43d6734476f03fe6];
const WINDOWED_READ_1024: [u64; 2] = [0x3c319186a48e56ed, 0x06ce93c8a99e5f8d];
const WINDOWED_VALUE_HASH_1024: [u64; 2] = [0x763d3a5224fbeaa1, 0xe459949f5cfa3607];
const CORRECT_WINDOWED_1024: [[u32; 4]; 2] = [[120, 121, 120, 115], [124, 116, 116, 123]];
const OVER_WINDOWED_1024: [Option<(usize, usize, usize)>; 2] = [None, None];
const ONCE_BLOCKS_WINDOWED_1024: [u32; 2] = [120, 120];
const FALLS_WINDOWED_1024: [bool; 2] = [false, false];
const SUMS_AFTER_WINDOWED_1024: [(i64, i64); 2] = [(140834024, 219914965), (140660269, 220532908)];

// -------------------------------------------- written before the run (ADR-0136, ADR-0137)

/// The arms of H-24 (ADR-0136): H-23's two, in their order, each its own weekly test, from
/// H-23's image, the task carrying no critic of its own, H-20's flips, and the reward delivered
/// to every synapse.
const UNADDRESSED_ARMS: [Reversal; 2] = WINDOWED_ARMS;

/// The one change from H-23 (ADR-0136): the task's delivery, every unit a source and a target
/// at every trial's end, `Executor::address_all`.
const UNADDRESSED_DELIVERY: Delivery = Delivery::Global;

/// ADR-0136 made no prediction for the verdict: the literature's account predicts yes, and
/// ADR-0066's global reading was a no under a configuration that no longer exists.
const UNADDRESSED_PREDICTED: Option<bool> = None;

/// Clause 3's band (ADR-0136): at every block's end the excitatory sum outside the four
/// stimulus–readout couplings within 0.75 and 1.25 of the image's, both bounds held, read in
/// integers as `3 × image ≤ 4 × outside ≤ 5 × image`. It does not move after a rewarded run.
const BAND_QUARTERS: (i64, i64) = (3, 5);
const BAND_DIVISOR: i64 = 4;
const _: () = assert!(BAND_QUARTERS.0 < BAND_DIVISOR && BAND_DIVISOR < BAND_QUARTERS.1);

/// The rows the network's readings are read in (brief 057): the excitatory classes of
/// `CLASSES` a synapse's source can be in — a stimulus unit, a readout unit, any other — class
/// `c` at row `c − 1`; the columns are the target's class in `CLASSES`'s order.
const SOURCES: usize = CLASSES - 1;
const _: () = assert!(SOURCES == 3);

// ------------------------------------------------------------ the criterion (ADR-0136)

/// The excitatory sum outside the four stimulus–readout couplings at a block's end: the
/// arena's excitatory sum less the four couplings, each the weights from an excitatory unit of
/// a stimulus set onto a unit of a readout set, of either polarity.
fn outside_of(block: &Block) -> i64 {
    block
        .10
        .iter()
        .flatten()
        .fold(block.8, |sum, &c| sum.saturating_sub(c))
}

/// The image's outside sum: the settled image's excitatory sum, which H-20's to H-23's images
/// carry, less its four couplings.
fn image_outside() -> i64 {
    IMAGE_COUPLINGS_1024
        .iter()
        .flatten()
        .fold(QUIET_1024[SETTLED].1.1, |sum, &c| sum.saturating_sub(c))
}

/// Clause 3's rule at one block's end (ADR-0136): `outside` within 0.75 and 1.25 of `image`,
/// both bounds held, an image above zero.
fn within_band(outside: i64, image: i64) -> bool {
    let scaled = outside.saturating_mul(BAND_DIVISOR);
    image > 0
        && scaled >= image.saturating_mul(BAND_QUARTERS.0)
        && scaled <= image.saturating_mul(BAND_QUARTERS.1)
}

/// Clause 3's reading over an arm's blocks: the first block, by index, whose end left the band,
/// with its outside sum; none when every block's end lies within it.
fn left_band(image: i64, blocks: &[Block]) -> Option<(usize, i64)> {
    blocks
        .iter()
        .map(outside_of)
        .enumerate()
        .find(|&(_, outside)| !within_band(outside, image))
}

/// H-24's criterion (ADR-0136), clause by clause per arm `[assignment first, mirrored first]`:
/// (1) each mapping learned and (2) the couplings bounded, H-20's two as `scheduled` reads
/// them; (3) the network held — a run of 120 blocks every one of whose ends lies within the
/// band. `yes` is all in both arms; a no names the clause and the arm, under clause 3 the first
/// block that left the band with its sum.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct Unaddressed {
    learning: Scheduled,
    left: [Option<(usize, i64)>; 2],
    held: [bool; 2],
    yes: bool,
}

fn unaddressed(image: i64, arms: [&[Block]; 2]) -> Unaddressed {
    let learning = scheduled(arms);
    let left = arms.map(|blocks| left_band(image, blocks));
    let held = [0usize, 1].map(|k| arms[k].len() == SCHEDULE_BLOCKS && left[k].is_none());
    Unaddressed {
        learning,
        left,
        held,
        yes: learning.yes && held.iter().all(|&h| h),
    }
}

// ----------------------------------------------------- the readings' shape (brief 057)

/// Where a synapse of an excitatory unit lies (brief 057): in a stimulus–readout pair
/// `(stimulus, readout)` — its source a unit of the stimulus set, its target a unit of the
/// readout set, of either polarity, the synapses the four couplings sum — or, outside the
/// pairs, in the cell of its source's row in `SOURCES` and its target's class in `CLASSES`.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum Place {
    Pair(usize, usize),
    Outside(usize, usize),
}

/// The place of the synapse from `source`, an excitatory unit, onto `target`.
fn place_of(sets: &[Set; 4], classes: &[usize], source: u32, target: u32) -> Place {
    let stimulus = [0usize, 1].into_iter().find(|&s| sets[s].contains(source));
    let readout = [0usize, 1]
        .into_iter()
        .find(|&r| readout_set(sets, r).contains(target));
    match (stimulus, readout) {
        (Some(s), Some(r)) => Place::Pair(s, r),
        _ => Place::Outside(
            classes
                .get(source as usize)
                .map_or(0, |c| c.saturating_sub(1)),
            classes.get(target as usize).copied().unwrap_or(0),
        ),
    }
}

/// One cell of the network outside the couplings at a block's end (brief 057): its excitatory
/// weights summed; its synapses whose weight differs from the image's; the largest move from
/// the image's weight by magnitude, with its sign, the first in the arena's walk at a tie; and
/// its synapses at zero and at `i16::MAX`, the two rails of an excitatory weight.
type Cell = (i64, u32, i32, u32, u32);

/// The cells by source row and target class.
type Cells = [[Cell; CLASSES]; SOURCES];

/// The network outside the four couplings on `exec`, cell by cell, against `image`, the weights
/// by block and slot as `weights_of` holds them. Every excitatory unit's occupied slots are
/// walked once, through its chain.
fn cells_of(exec: &Engine, image: &[Vec<i16>], sets: &[Set; 4], classes: &[usize]) -> Cells {
    let mut out: Cells = [[(0, 0, 0, 0, 0); CLASSES]; SOURCES];
    for unit in exec.units() {
        if unit.flags & FLAG_INHIBITORY != 0 {
            continue;
        }
        for s in unit.fan_out(exec.blocks()) {
            let Place::Outside(row, column) = place_of(sets, classes, unit.id as u32, s.target)
            else {
                continue;
            };
            let Some(cell) = out.get_mut(row).and_then(|r| r.get_mut(column)) else {
                continue;
            };
            let was = image
                .get(s.block_idx as usize)
                .and_then(|b| b.get(usize::from(s.slot)))
                .copied()
                .expect("the image holds the synapse");
            let delta = i32::from(s.weight_q1_15).saturating_sub(i32::from(was));
            cell.0 = cell.0.saturating_add(i64::from(s.weight_q1_15));
            cell.1 = cell.1.saturating_add(u32::from(delta != 0));
            if delta.unsigned_abs() > cell.2.unsigned_abs() {
                cell.2 = delta;
            }
            cell.3 = cell.3.saturating_add(u32::from(s.weight_q1_15 == 0));
            cell.4 = cell.4.saturating_add(u32::from(s.weight_q1_15 == i16::MAX));
        }
    }
    out
}

/// The synapses of each cell, which no rule changes: a cell's moved synapses are read as a
/// fraction of these.
fn cell_sizes(exec: &Engine, sets: &[Set; 4], classes: &[usize]) -> [[u32; CLASSES]; SOURCES] {
    let mut out = [[0u32; CLASSES]; SOURCES];
    for unit in exec.units() {
        if unit.flags & FLAG_INHIBITORY != 0 {
            continue;
        }
        for s in unit.fan_out(exec.blocks()) {
            if let Place::Outside(row, column) = place_of(sets, classes, unit.id as u32, s.target) {
                if let Some(n) = out.get_mut(row).and_then(|r| r.get_mut(column)) {
                    *n = n.saturating_add(1);
                }
            }
        }
    }
    out
}

/// The cells' sums, the outside sum over the arena.
fn cells_sum(cells: &Cells) -> i64 {
    cells
        .iter()
        .flatten()
        .fold(0i64, |sum, c| sum.saturating_add(c.0))
}

/// Where the consolidation went (brief 057), by the network's oracle over a trial or a block:
/// the weight raised and the weight lowered, each summed with its sign, `[raised, lowered]`,
/// in the answer's pairs — each stimulus onto its answer under the mapping in force at the
/// trial the consolidation fell in — in the other two pairs, and outside the pairs.
type Went = [[i64; 2]; 3];

/// A `Went` plus another, amount by amount.
fn add_went(into: &mut Went, went: &Went) {
    for (a, b) in into.iter_mut().flatten().zip(went.iter().flatten()) {
        *a = a.saturating_add(*b);
    }
}

// ------------------------------------------------------------- the oracle (brief 057)

/// An occupied slot of an excitatory unit's block as the network's oracle replays it: the
/// slot, its target, its trace and its weight's magnitude, and where it lies.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct Wired {
    slot: usize,
    target: u32,
    trace: i16,
    magnitude: i32,
    place: Place,
}

/// A block of an excitatory unit's chain as the network's oracle replays it: its index in the
/// arena, its presynaptic stamp and its occupied slots, in slot order.
#[derive(Clone, Debug, PartialEq, Eq)]
struct Wiring {
    block: usize,
    stamp: u32,
    slots: Vec<Wired>,
}

/// A block of the arena as the oracle starts from it: its stamp, and each occupied slot's
/// target, trace and weight as the record holds them, the weight read as a magnitude of an
/// excitatory block, never below zero.
fn wiring_of(block: &SynapseBlock, index: usize, place: &dyn Fn(u32) -> Place) -> Wiring {
    Wiring {
        block: index,
        stamp: block.last_spike_tick,
        slots: (0..SYNAPSES_PER_BLOCK)
            .filter_map(|slot| {
                block.target(slot).map(|target| Wired {
                    slot,
                    target,
                    trace: block.eligibility_q1_15[slot],
                    magnitude: i32::from(block.weights_q1_15[slot]).max(0),
                    place: place(target),
                })
            })
            .collect(),
    }
}

/// One presynaptic spike at `t` through an excitatory block, as the oracle replays it — the
/// harness's second writing of `step_stdp_all` and `consolidate_signed` (`consolidate` with the
/// signed gate unset): every slot's trace decayed by the ticks since the block's stamp, when
/// there are any; the pair rule against the target's last spike in `last` — the potentiation
/// when the target fired after the stamp and not after `t`, the depression at the magnitude
/// when it fired before `t`, neither without a spike on record; the consolidation under the
/// slot's modulation, `modulation` of the slot; then the stamp. `moved` is handed each slot and
/// what its magnitude moved.
fn replay_block(
    wiring: &mut Wiring,
    t: u32,
    last: &[u32],
    signed: bool,
    modulation: &dyn Fn(&Wired) -> i32,
    moved: &mut dyn FnMut(&Wired, i32),
) {
    let elapsed = t.wrapping_sub(wiring.stamp);
    let factor =
        (elapsed != 0).then(|| i64::from(stp_decay_factor_q16(elapsed, ELIGIBILITY_TAU_SHIFT)));
    for syn in wiring.slots.iter_mut() {
        if let Some(f) = factor {
            syn.trace = decayed(syn.trace, f);
        }
        let post = last
            .get(syn.target as usize)
            .copied()
            .unwrap_or(NO_SPIKE_ON_RECORD);
        if post != NO_SPIKE_ON_RECORD {
            let since_post = t.wrapping_sub(post) as i32;
            if wiring.stamp != NO_SPIKE_ON_RECORD {
                let post_after_prev = post.wrapping_sub(wiring.stamp) as i32;
                if post_after_prev > 0 && since_post >= 0 {
                    syn.trace = syn
                        .trace
                        .saturating_add(pair_window(STDP_A_PLUS_Q1_15, post_after_prev as u32));
                }
            }
            if since_post > 0 {
                syn.trace = syn.trace.saturating_sub(depression_at(
                    pair_window(STDP_A_MINUS_Q1_15, since_post as u32),
                    syn.magnitude,
                ));
            }
        }
        let m = modulation(syn);
        let (trace, magnitude, amount) = if signed {
            consolidated_signed(syn.trace, syn.magnitude, m)
        } else {
            consolidated(syn.trace, syn.magnitude, m)
        };
        syn.trace = trace;
        syn.magnitude = magnitude;
        moved(syn, amount);
    }
    wiring.stamp = t;
}

/// The network's oracle (brief 057, ADR-0137): every excitatory synapse of the arena — the
/// stimulus–readout pairs the composer replays among them — replayed from the train by
/// `replay_block`, a synapse taking the baseline plus the signal where the executor's addressed
/// set holds its source and its target and the baseline alone elsewhere, as the delivery wrote
/// the set at the last trial's end, and held to the record's traces, weights and stamps at every
/// trial. Under the global delivery every synapse takes the signal; under the addressed one only
/// the pair the last trial addressed does.
struct Network {
    /// Each unit's chain in the arena's order, as the oracle replays it; empty for an
    /// inhibitory unit, whose blocks the inhibitory rule moves.
    chains: Vec<Vec<Wiring>>,
    /// Each unit's last somatic spike: the record's at the start, the train's since.
    last: Vec<u32>,
    /// The addressed set the next trial's spikes are consolidated under, as the executor holds
    /// it: at the start every unit a source and a target, the state a new executor starts in.
    sources: Vec<bool>,
    targets: Vec<bool>,
    /// The first tick the next reading replays, and the signal at the next trial's first tick.
    cursor: u32,
    signal: i32,
    baseline: i32,
    signed: bool,
    /// Whether no trial has been read: only the first reading holds spikes before its trial,
    /// the lead-in's, under the signal at rest.
    first: bool,
}

impl Network {
    fn new(exec: &Engine, sets: &[Set; 4], classes: &[usize]) -> Self {
        Self::placed(exec, &|source, target| {
            place_of(sets, classes, source, target)
        })
    }

    /// `new` with each synapse's place by the caller's rule (brief 062), handed the synapse's
    /// source, an excitatory unit, and its target: a task of three readouts names its six
    /// pairs. `new` calls it with the two-readout rule, `place_of`.
    fn placed(exec: &Engine, place: &dyn Fn(u32, u32) -> Place) -> Self {
        let blocks = exec.blocks();
        let units = exec.units();
        let chains = units
            .iter()
            .map(|unit| {
                if unit.flags & FLAG_INHIBITORY != 0 {
                    return Vec::new();
                }
                let source = unit.id as u32;
                unit.chain(blocks)
                    .map(|idx| {
                        let block = blocks.get(idx as usize).expect("a block of the arena");
                        wiring_of(block, idx as usize, &|target| place(source, target))
                    })
                    .collect()
            })
            .collect();
        let n = units.len() as u32;
        Self {
            chains,
            last: units.iter().map(|u| u.last_soma_spike_tick).collect(),
            sources: (0..n).map(|u| exec.is_source(u)).collect(),
            targets: (0..n).map(|u| exec.is_target(u)).collect(),
            cursor: exec.ticks() as u32,
            signal: exec.modulator().dopamine_rpe,
            baseline: exec.modulation_baseline_q16(),
            signed: exec.signed_gate(),
            first: true,
        }
    }

    /// The excitatory synapses replayed.
    fn synapses(&self) -> usize {
        self.chains
            .iter()
            .flatten()
            .map(|w| w.slots.len())
            .fold(0usize, usize::saturating_add)
    }

    /// One trial's reading at its end, after its reward: the train's spikes since the last
    /// reading replayed tick by tick — every spiking unit's last spike written first, as the
    /// executor's integration precedes its fan-out, then each spiking excitatory unit's blocks
    /// — under the signal's course from the one the last reward left, at rest before the first
    /// trial's start; then the record held to the oracle, and the addressed set and the signal
    /// read for the next trial. `answers` names each stimulus's answer under the mapping in
    /// force. Returns where the trial's consolidation went.
    fn replay(&mut self, exec: &mut Engine, trial: usize, answers: [usize; 2]) -> Went {
        self.replay_each(exec, trial, answers, &mut |_, _| {})
    }

    /// `replay` with every consolidation handed to `each` as it is replayed (brief 062): the
    /// slot, which names its place, and what its weight moved by. `replay` calls it with a
    /// reader that reads nothing.
    fn replay_each(
        &mut self,
        exec: &mut Engine,
        trial: usize,
        answers: [usize; 2],
        each: &mut dyn FnMut(&Wired, i32),
    ) -> Went {
        let end = exec.ticks();
        assert!(end <= u64::from(u32::MAX), "the stamp is the tick");
        let end = end as u32;
        let start = end.checked_sub(TRIAL_TICKS).expect("a trial's ticks");
        let course = signal_course(self.signal);
        let at_rest = self.first && self.signal == 0;
        let cursor = self.cursor;
        let overwritten = exec.train_overwritten();
        let train = exec.train();
        assert!(
            overwritten == 0 || train.first().is_some_and(|&(t, _)| t <= cursor),
            "trial {trial}: the train held every spike since the last reading"
        );
        let from = train.partition_point(|&(t, _)| t < cursor);
        let to = train.partition_point(|&(t, _)| t < end);
        let mut went: Went = [[0; 2]; 3];
        let (baseline, signed) = (self.baseline, self.signed);
        for tick in train[from..to].chunk_by(|a, b| a.0 == b.0) {
            let Some(&(t, _)) = tick.first() else {
                continue;
            };
            for &(_, unit) in tick {
                if let Some(l) = self.last.get_mut(unit as usize) {
                    *l = t;
                }
            }
            let signal = match course.get(t.wrapping_sub(start) as usize) {
                Some(&s) => s,
                None => {
                    assert!(
                        t < start && at_rest,
                        "trial {trial}: a spike before its trial is the lead-in's, at rest"
                    );
                    0
                }
            };
            for &(_, unit) in tick {
                let from_source = self.sources.get(unit as usize).copied().unwrap_or(false);
                let targets = &self.targets;
                let Some(chain) = self.chains.get_mut(unit as usize) else {
                    panic!("trial {trial}: a spiking unit outside the arena");
                };
                for wiring in chain.iter_mut() {
                    replay_block(
                        wiring,
                        t,
                        &self.last,
                        signed,
                        &|syn| {
                            if from_source
                                && targets.get(syn.target as usize).copied().unwrap_or(false)
                            {
                                baseline.saturating_add(signal)
                            } else {
                                baseline
                            }
                        },
                        &mut |syn, amount| {
                            let row = match syn.place {
                                Place::Pair(s, r) => usize::from(answers[s] != r),
                                Place::Outside(..) => 2,
                            };
                            let side = usize::from(amount < 0);
                            went[row][side] = went[row][side].saturating_add(i64::from(amount));
                            each(syn, amount);
                        },
                    );
                }
            }
        }
        self.first = false;
        self.cursor = end;
        let blocks = exec.blocks();
        for wiring in self.chains.iter().flatten() {
            let block = blocks.get(wiring.block).expect("a block of the arena");
            assert_eq!(
                block.last_spike_tick, wiring.stamp,
                "trial {trial}: block {}'s stamp is the oracle's",
                wiring.block
            );
            for syn in &wiring.slots {
                assert_eq!(
                    (
                        block.eligibility_q1_15[syn.slot],
                        i32::from(block.weights_q1_15[syn.slot])
                    ),
                    (syn.trace, syn.magnitude),
                    "trial {trial}: block {} slot {}: the record's trace and weight are the oracle's",
                    wiring.block,
                    syn.slot
                );
            }
        }
        let n = self.last.len() as u32;
        self.sources = (0..n).map(|u| exec.is_source(u)).collect();
        self.targets = (0..n).map(|u| exec.is_target(u)).collect();
        self.signal = exec.modulator().dopamine_rpe;
        went
    }
}

// ---------------------------------------------------------------- the run (brief 057)

/// What brief 057 reads of a run beside H-23's tables: the four couplings at the end of the
/// first trial under each new mapping the run reaches; at every block's end the value weights by
/// group, the network's cells against the image, where the consolidation went over the block and
/// the block's spikes by class; and at every trial's reward the spikes the window admitted by
/// group. Brief 058 adds, at every trial's end, the addressed sources the delivery wrote by
/// group: the presented stimulus's set under the addressed delivery, every unit under the global
/// one, and under the drawn one the units the window counted.
#[derive(Clone, Debug, PartialEq, Eq)]
struct Watch {
    at_flips: [Option<[[i64; 2]; 2]>; 3],
    weights: Vec<Weights>,
    admitted: Vec<[u32; GROUPS]>,
    spikes: Vec<[u64; CLASSES]>,
    cells: Vec<Cells>,
    went: Vec<Went>,
    sourced: Vec<[u32; GROUPS]>,
}

/// An arm's run from H-23's image under `delivery` for `trials` trials (brief 057): H-23's run
/// — `earned_run_delivered` under the answer's feedback at the gate's zero with the signed gate
/// set, the arm's first mapping and H-20's flips, the task carrying no critic, the engine's
/// value, error, weights and window held to the harness's at every trial — with the network's
/// oracle replayed and held at every trial; the spikes the window admitted read at every
/// trial's reward as H-23's run reads them, and the trial's spikes by class from the train,
/// whole since the ring holds the most spikes a trial can produce. `image` is the weights the
/// cells are read against. It is `shadowed_run` with no shadow, which it calls so.
#[allow(clippy::too_many_arguments)]
fn delivered_run(
    exec: &mut Engine,
    arm: Reversal,
    sets: &[Set; 4],
    groups: &[usize],
    classes: &[usize],
    image: &[Vec<i16>],
    delivery: Delivery,
    trials: usize,
) -> (EarnedRun, Vec<Moves>, Vec<i32>, Watch) {
    let (run, moves, values, watched, beside) = shadowed_run(
        exec, arm, sets, groups, classes, image, delivery, trials, false,
    );
    assert!(beside.is_none(), "no shadow, no reading beside the run");
    (run, moves, values, watched)
}

/// What brief 059 reads beside a run under the drawn delivery (ADR-0141): the harness's
/// shadows' tables (`Shadowed`), and each trial's spikes of the two readout sets over the whole
/// trial, `[readout 0, readout 1]`, from the train as the task's readout counts them.
#[derive(Clone, Debug, PartialEq, Eq)]
struct Beside {
    shadowed: Shadowed,
    heard: Vec<[u32; 2]>,
}

/// A run with what brief 059 reads beside it: `delivered_run`'s four values and the reading,
/// none without the shadows.
type BesideRun = (EarnedRun, Vec<Moves>, Vec<i32>, Watch, Option<Beside>);

/// `delivered_run` with the shadows beside the composer or without them (brief 059):
/// `earned_run_shadowed` in `earned_run_delivered`'s place, and each trial's spikes of the two
/// readout sets over the whole trial read from the train. The shadows read the run and are
/// never written back, and nothing the run does reads them, so the run with them is the run
/// without; without them the fifth value is none and this is `delivered_run`, which calls it
/// so. It is `held_run` with no hold, which it calls so.
#[allow(clippy::too_many_arguments)]
fn shadowed_run(
    exec: &mut Engine,
    arm: Reversal,
    sets: &[Set; 4],
    groups: &[usize],
    classes: &[usize],
    image: &[Vec<i16>],
    delivery: Delivery,
    trials: usize,
    shadowed: bool,
) -> BesideRun {
    assert!(
        delivery != Delivery::Released,
        "the released delivery is `held_run`'s"
    );
    let (run, along) = held_run(
        exec, arm, sets, groups, classes, image, delivery, trials, shadowed, None,
    );
    assert!(
        along.held.held.iter().all(|&messages| messages == 0),
        "no hold, no message of one"
    );
    run
}

/// What brief 060 reads beside a run (ADR-0145): the harness's reading (`HeldRead`) — the run's own
/// consolidation by stimulus, readout and direction, the eligibility at each reward from the
/// sources drawn there, and the hold's messages — and each trial's spikes of the two readout
/// sets within the span and over the whole trial, `[readout 0, readout 1]`, from the train as
/// the task's readout counts them.
#[derive(Clone, Debug, PartialEq, Eq)]
struct Along {
    held: HeldRead,
    spanned: Vec<[u32; 2]>,
    heard: Vec<[u32; 2]>,
}

/// `shadowed_run` under a hold or none, and under the released delivery beside the three (brief
/// 060): `earned_run_held` in `earned_run_shadowed`'s place, and each trial's spikes of the two
/// readout sets within the span read from the train beside those over the whole trial. The
/// readings read the train and write nothing, so a run with no hold under one of the three
/// deliveries before the released one is `shadowed_run`'s, which calls it so. It is `fed_run`
/// under the answer's feedback, which it calls so.
#[allow(clippy::too_many_arguments)]
fn held_run(
    exec: &mut Engine,
    arm: Reversal,
    sets: &[Set; 4],
    groups: &[usize],
    classes: &[usize],
    image: &[Vec<i16>],
    delivery: Delivery,
    trials: usize,
    shadowed: bool,
    hold: Option<Hold>,
) -> (BesideRun, Along) {
    fed_run(
        exec,
        arm,
        sets,
        groups,
        classes,
        image,
        delivery,
        trials,
        shadowed,
        hold,
        Feedback::Answer,
    )
}

/// `held_run` under a feedback (brief 061, ADR-0148): the task's feedback is `feedback`, and
/// nothing else of the run is touched. Under `Feedback::Answer` it is `held_run`, which calls it
/// so; under `Feedback::SevenInEight` the harness holds every trial's reward to its own coin
/// (`misleads`), and the network's oracle, which reads the signal each reward left and the
/// answers under the mapping in force, replays as it does under the answer's feedback.
#[allow(clippy::too_many_arguments)]
fn fed_run(
    exec: &mut Engine,
    arm: Reversal,
    sets: &[Set; 4],
    groups: &[usize],
    classes: &[usize],
    image: &[Vec<i16>],
    delivery: Delivery,
    trials: usize,
    shadowed: bool,
    hold: Option<Hold>,
    feedback: Feedback,
) -> (BesideRun, Along) {
    fed_run_on(
        &DERIVED_1024,
        exec,
        arm,
        sets,
        groups,
        classes,
        image,
        delivery,
        trials,
        shadowed,
        hold,
        feedback,
    )
}

/// `fed_run` on the network `derived` describes (ADR-0165, brief 067): `earned_run_held_on` in
/// `earned_run_held`'s place, with `sets` the four sets laid from the network's rotation.
/// `fed_run` calls it with `DERIVED_1024`, so its run is the run it was.
#[allow(clippy::too_many_arguments)]
fn fed_run_on(
    derived: &Derived,
    exec: &mut Engine,
    arm: Reversal,
    sets: &[Set; 4],
    groups: &[usize],
    classes: &[usize],
    image: &[Vec<i16>],
    delivery: Delivery,
    trials: usize,
    shadowed: bool,
    hold: Option<Hold>,
    feedback: Feedback,
) -> (BesideRun, Along) {
    fed_run_at(
        1024,
        derived,
        exec,
        arm,
        sets,
        groups,
        classes,
        image,
        delivery,
        trials,
        shadowed,
        hold,
        feedback,
        &mut |_, _| {},
    )
}

/// `fed_run_on` at `units` (ADR-0168, brief 068): the sets held to the geometry at that size and
/// the run at that size; and `extra` called at every trial's end, after the run's own readings,
/// with the engine and the trial — a reading of the caller's, which reads the engine and writes
/// nothing to it. `fed_run_on` calls it with 1 024 and a reading of nothing, so its run is the run
/// it was.
#[allow(clippy::too_many_arguments)]
fn fed_run_at(
    units: u32,
    derived: &Derived,
    exec: &mut Engine,
    arm: Reversal,
    sets: &[Set; 4],
    groups: &[usize],
    classes: &[usize],
    image: &[Vec<i16>],
    delivery: Delivery,
    trials: usize,
    shadowed: bool,
    hold: Option<Hold>,
    feedback: Feedback,
    extra: &mut dyn FnMut(&mut Engine, usize),
) -> (BesideRun, Along) {
    assert_eq!(
        *sets,
        geometry(units, derived.rotation),
        "the sets are the network's"
    );
    let readouts = Readout::new([sets[2], sets[3]]);
    let mut heard: Vec<[u32; 2]> = Vec::with_capacity(trials);
    let mut spanned: Vec<[u32; 2]> = Vec::with_capacity(trials);
    let first = first_mapping(arm);
    let window = exec.critic_window_ticks();
    let mut network = Network::new(exec, sets, classes);
    let mut at_flips: [Option<[[i64; 2]; 2]>; 3] = [None; 3];
    let mut weights: Vec<Weights> = Vec::new();
    let mut admitted: Vec<[u32; GROUPS]> = Vec::with_capacity(trials);
    let mut spikes: Vec<[u64; CLASSES]> = Vec::new();
    let mut cells: Vec<Cells> = Vec::new();
    let mut went: Vec<Went> = Vec::new();
    let mut sourced: Vec<[u32; GROUPS]> = Vec::with_capacity(trials);
    let mut spikes_block = [0u64; CLASSES];
    let mut went_block: Went = [[0; 2]; 3];
    let mut opened = exec.ticks();
    let (run, moves, expected, values, shadows, held) = earned_run_held_on(
        derived,
        exec,
        feedback,
        first,
        units,
        trials,
        GATE_BASELINE_Q16,
        &SCHEDULE_FLIPS,
        true,
        None,
        delivery,
        shadowed,
        hold,
        &mut |exec, trial| {
            // The spikes the window admitted, as H-23's run reads them.
            let mut in_window = [0u32; GROUPS];
            for &(tick, unit) in exec.train() {
                let since = u64::from(tick).checked_sub(opened);
                if since.is_some_and(|d| d < u64::from(window)) {
                    if let Some(n) = groups
                        .get(unit as usize)
                        .and_then(|&g| in_window.get_mut(g))
                    {
                        *n = n.saturating_add(1);
                    }
                }
            }
            admitted.push(in_window);
            opened = exec.ticks();
            // The addressed sources the delivery wrote at this trial's end, by group.
            let mut sources = [0u32; GROUPS];
            for (unit, &g) in groups.iter().enumerate() {
                if exec.is_source(unit as u32) {
                    if let Some(n) = sources.get_mut(g) {
                        *n = n.saturating_add(1);
                    }
                }
            }
            sourced.push(sources);
            // The network's oracle, the answers under the mapping in force at this trial.
            let in_force = first != flipped_at(&SCHEDULE_FLIPS, trial);
            let answers = [answer_of(0, in_force), answer_of(1, in_force)];
            add_went(&mut went_block, &network.replay(exec, trial, answers));
            // The trial's spikes by class.
            let end = exec.ticks();
            let start = end
                .checked_sub(u64::from(TRIAL_TICKS))
                .expect("a trial's ticks");
            each_spike(exec.train(), start as u32, end as u32, &mut |unit| {
                if let Some(n) = classes.get(unit).and_then(|&c| spikes_block.get_mut(c)) {
                    *n = n.saturating_add(1);
                }
            });
            // The trial's spikes of each readout set over the whole trial (brief 059), and
            // within the span (brief 060).
            heard.push(readouts.count_window(exec.train(), start as u32, TRIAL_TICKS));
            spanned.push(readouts.count_window(
                exec.train(),
                (start as u32).wrapping_add(HOLD_SPAN.from),
                HOLD_SPAN.ticks,
            ));
            if let Some(f) = SCHEDULE_FLIPS.iter().position(|&f| f == trial) {
                at_flips[f] = Some(pair_couplings(exec, sets));
            }
            if trial.wrapping_add(1) % BLOCK == 0 {
                weights.push(weights_by_group(exec, groups));
                cells.push(cells_of(exec, image, sets, classes));
                went.push(went_block);
                went_block = [[0; 2]; 3];
                spikes.push(spikes_block);
                spikes_block = [0; CLASSES];
            }
            extra(exec, trial);
        },
    );
    assert!(expected.is_empty(), "the task carries no critic");
    assert_eq!(
        (heard.len(), spanned.len()),
        (trials, trials),
        "a count over the trial and one within the span a trial"
    );
    (
        (
            run,
            moves,
            values,
            Watch {
                at_flips,
                weights,
                admitted,
                spikes,
                cells,
                went,
                sourced,
            },
            shadows.map(|shadowed| Beside {
                shadowed,
                heard: heard.clone(),
            }),
        ),
        Along {
            held,
            spanned,
            heard,
        },
    )
}

/// H-23's first block from H-23's image under the addressed delivery (H-24's calibration,
/// ADR-0136's stopping rule step 2): H-23's run for one block — the engine's critic with its
/// window, no task critic, the arm's first mapping, `Delivery::Addressed` — held to H-23's
/// pinned first block table by table, with the network's oracle replayed beside it and held to
/// the record at every trial, where it reads nothing moved outside the pairs and the pairs moved
/// by what the composer consolidated.
fn h23_first_block(windowed: &[u8], arm: Reversal, k: usize, name: &str) {
    let mut exec = signed_from(windowed, 1024);
    assert_eq!(
        (
            exec.critic(),
            exec.critic_window_ticks(),
            exec.istdp_target_period_ticks()
        ),
        (Some(VALUED_CRITIC), WINDOW_TICKS_1024, TARGET_PERIOD_1024),
        "{name}: H-23's image carries the critic, its window and the target"
    );
    let sets = geometry(1024, ROTATION_1024);
    let groups = groups_of(&exec, &sets);
    let classes = classes_of(&exec, &sets);
    let image = weights_of(&exec);
    let (run, moves, values, watched) = delivered_run(
        &mut exec,
        arm,
        &sets,
        &groups,
        &classes,
        &image,
        Delivery::Addressed,
        BLOCK,
    );
    let (blocks, _, trials, read, _) = &run;
    let compositions: Vec<Composition> = trials.chunks(BLOCK).map(composition).collect();
    let earned = earned_blocks(read);
    let by_block = value_blocks(read, &values);
    let admitted = admitted_blocks(read, &watched.admitted);
    eprintln!(
        "DUMP {name} H-23's first block {:?} earned {:?} values {:?} weights {:?} admitted {:?} went {:?} cells {:?}",
        blocks, earned, by_block, watched.weights, admitted, watched.went, watched.cells
    );
    assert_eq!(blocks.as_slice(), &WINDOWED_BLOCKS_1024[k][..1], "{name}");
    assert_eq!(
        compositions.as_slice(),
        &WINDOWED_COMPOSITIONS_1024[k][..1],
        "{name}"
    );
    assert_eq!(earned.as_slice(), &WINDOWED_EARNED_1024[k][..1], "{name}");
    assert_eq!(
        moves_blocks(read, &moves).as_slice(),
        &WINDOWED_MOVES_1024[k][..1],
        "{name}"
    );
    assert_eq!(by_block.as_slice(), &WINDOWED_VALUES_1024[k][..1], "{name}");
    assert_eq!(
        watched.weights.as_slice(),
        &WINDOWED_WEIGHTS_1024[k][..1],
        "{name}"
    );
    assert_eq!(
        admitted.as_slice(),
        &WINDOWED_ADMITTED_1024[k][..1],
        "{name}"
    );
    // The network's oracle under the addressed delivery: nothing outside the pairs moved, and
    // the pairs by what the composer consolidated into them.
    let consolidated = earned[0]
        .2
        .iter()
        .flatten()
        .fold(0i64, |sum, &c| sum.saturating_add(c));
    let went = watched.went[0];
    assert_eq!(
        (
            went[2],
            went[0]
                .iter()
                .chain(&went[1])
                .fold(0i64, |sum, &a| sum.saturating_add(a))
        ),
        ([0, 0], consolidated),
        "{name}: the network's oracle reads H-23's addressed consolidation"
    );
    assert_eq!(
        cells_sum(&watched.cells[0]),
        image_outside(),
        "{name}: the network outside the pairs unmoved"
    );
}

/// One arm of H-24 at 1 024 units (brief 057): the calibration before any rewarded run (H-24's
/// stopping rule, step 2) — the settled engine held to ADR-0077 step by step and its images,
/// H-20's image by its CRC, a frozen block from the zero image held to ADR-0077's frozen run,
/// H-21's, H-22's and H-23's images by their CRCs, and H-23's first block from H-23's image
/// under the addressed delivery reproduced table by table — then the arm's 7 680 trials from
/// H-23's image under the global delivery with no task critic and H-20's flips, the network's
/// oracle held at every trial; everything dumped, the clauses and the readings computed before
/// anything is held; then the pinned tables of the whole run.
fn unaddressed_arm(arm: Reversal) {
    let k = UNADDRESSED_ARMS
        .iter()
        .position(|&a| a == arm)
        .expect("an arm of H-24");
    let name = format!("unaddressed1024 {arm:?}");
    let (zero, signed) = signed_images(&name);
    assert_eq!(
        pinned_crc(&signed),
        PUNISHED_IMAGE_CRC_1024,
        "{name}: H-20's image, H-19's and H-18's"
    );
    {
        let mut frozen = frozen_from(&zero, 1024);
        assert_eq!(
            (frozen.inhibitory_baseline_q16(), frozen.signed_gate()),
            (None, false),
            "{name}: the calibration's image leaves the inhibitory baseline and the signed gate unset"
        );
        let calibration = taught_run(&mut frozen, Arm::Withheld, 1024, BLOCK);
        calibration_holds(&format!("{name} calibration"), &calibration);
    }
    let targeted = targeted_image(&signed, TARGET_PERIOD_1024);
    assert!(
        only_the_target(&signed, &targeted),
        "{name}: H-21's image is H-20's in every byte but the target period's and the seal"
    );
    assert_eq!(
        (pinned_crc(&targeted), crc64(&with_version(&targeted, 18))),
        (TARGET_IMAGE_CRC_1024, TARGET_IMAGE_CRC_FORMAT_18_1024),
        "{name}: H-21's image, and as H-21 read it"
    );
    let valued = valued_image(&targeted, VALUED_CRITIC);
    assert!(
        only_the_critic(&targeted, &valued),
        "{name}: H-22's image is H-21's in every byte but the critic's and the seal"
    );
    assert_eq!(
        (pinned_crc(&valued), crc64(&with_version(&valued, 19))),
        (VALUED_IMAGE_CRC_1024, VALUED_IMAGE_CRC_FORMAT_19_1024),
        "{name}: H-22's image, and as H-22 read it"
    );
    let windowed = with_window_bytes(&valued, WINDOW_TICKS_1024);
    assert!(
        only_the_window(&valued, &windowed),
        "{name}: H-23's image is H-22's in every byte but the window's and the seal"
    );
    assert_eq!(
        pinned_crc(&windowed),
        WINDOWED_IMAGE_CRC_1024,
        "{name}: H-23's image, the image this arm decodes"
    );
    h23_first_block(&windowed, arm, k, &name);
    eprintln!(
        "DUMP {name} calibration holds: ADR-0077's settled candidate, H-20's to H-23's images and H-23's first block under the addressed delivery"
    );
    let sets = geometry(1024, ROTATION_1024);
    let mut exec = signed_from(&windowed, 1024);
    assert_eq!(
        (
            exec.critic(),
            exec.critic_window_ticks(),
            exec.istdp_target_period_ticks(),
            exec.window_opened()
        ),
        (
            Some(VALUED_CRITIC),
            WINDOW_TICKS_1024,
            TARGET_PERIOD_1024,
            exec.ticks()
        ),
        "{name}: H-23's configuration, the window open at the load"
    );
    assert!(
        exec.units().iter().all(|u| u.value_weight == 0) && exec.features().iter().all(|&c| c == 0),
        "{name}: every weight and every count zero"
    );
    let image_sums = QUIET_1024[SETTLED].1;
    assert_eq!(
        weights_by_polarity(&exec),
        image_sums,
        "{name}: the image's sums"
    );
    assert_eq!(
        pair_couplings(&exec, &sets),
        IMAGE_COUPLINGS_1024,
        "{name}: the same image"
    );
    let groups = groups_of(&exec, &sets);
    let classes = classes_of(&exec, &sets);
    let image = weights_of(&exec);
    let image_cells = cells_of(&exec, &image, &sets, &classes);
    let sizes = cell_sizes(&exec, &sets, &classes);
    let outside = image_outside();
    eprintln!(
        "DUMP {name} PIN image cells {image_cells:?} sizes {sizes:?} outside {outside} classes {:?}",
        class_sizes(&classes)
    );
    assert_eq!(
        cells_sum(&image_cells),
        outside,
        "{name}: the cells sum to the image's outside sum"
    );
    let first = first_mapping(arm);
    let (run, moves, values, watched) = delivered_run(
        &mut exec,
        arm,
        &sets,
        &groups,
        &classes,
        &image,
        UNADDRESSED_DELIVERY,
        SCHEDULE_TRIALS,
    );
    let (blocks, trace, trials, read, volley_ticks) = &run;
    let earned = earned_blocks(read);
    let compositions: Vec<Composition> = trials.chunks(BLOCK).map(composition).collect();
    let moved = moves_blocks(read, &moves);
    let strong = strong_scheduled(read, first);
    let valued_by_block = value_blocks(read, &values);
    let admitted = admitted_blocks(read, &watched.admitted);
    let at_flips = watched
        .at_flips
        .map(|c| c.expect("the run reached the trial after every flip"));
    assert_eq!(blocks.len(), SCHEDULE_BLOCKS, "{name}: 120 blocks");
    assert_eq!(
        (read.len(), values.len(), watched.admitted.len()),
        (SCHEDULE_TRIALS, SCHEDULE_TRIALS, SCHEDULE_TRIALS)
    );
    assert_eq!(
        [
            compositions.len(),
            earned.len(),
            moved.len(),
            valued_by_block.len(),
            watched.weights.len(),
            admitted.len(),
            watched.spikes.len(),
            watched.cells.len(),
            watched.went.len()
        ],
        [SCHEDULE_BLOCKS; 9]
    );
    assert_eq!(strong.len(), SCHEDULE_BLOCKS - FLIP_BLOCK);
    // The run's tables dumped whole, as they are pinned, before anything is held or read.
    eprintln!("DUMP {name} PIN blocks {blocks:?}");
    eprintln!("DUMP {name} PIN trace {trace:#018x}");
    eprintln!("DUMP {name} PIN compositions {compositions:?}");
    eprintln!("DUMP {name} PIN earned {earned:?}");
    eprintln!("DUMP {name} PIN read {:#018x}", earned_hash(read));
    eprintln!("DUMP {name} PIN census {:?}", census_of(volley_ticks));
    eprintln!("DUMP {name} PIN moves {moved:?}");
    eprintln!("DUMP {name} PIN strong {strong:?}");
    eprintln!("DUMP {name} PIN at flips {at_flips:?}");
    eprintln!("DUMP {name} PIN values {valued_by_block:?}");
    eprintln!("DUMP {name} PIN value hash {:#018x}", values_hash(&values));
    eprintln!("DUMP {name} PIN weights {:?}", watched.weights);
    eprintln!("DUMP {name} PIN admitted {admitted:?}");
    eprintln!("DUMP {name} PIN spikes {:?}", watched.spikes);
    eprintln!("DUMP {name} PIN cells {:?}", watched.cells);
    eprintln!("DUMP {name} PIN went {:?}", watched.went);
    // Everything read and dumped, and the clauses and the readings computed, before anything
    // else is held.
    dump_earned(&name, &run, &earned);
    let reach = reach_by_polarity(&exec, &image, 1024, &ALL_PAIRS);
    let correct = mapping_correct(blocks);
    let over = first_over(blocks);
    let left = left_band(outside, blocks);
    let stimulus_read = stimulus_values(read, &values);
    let first_new_read = first_new_scheduled(read, first);
    let crossings_read = crossings(blocks);
    let crossed = crossed_scheduled(&earned, first);
    let tally_read = tally(blocks);
    let settle = settle_scheduled(blocks, first);
    let highest_read = highest(blocks);
    let strong_sum = strong_by_flip(&strong);
    let punished_moves = moves_by_mapping(&moved, 1);
    let rewarded_moves = moves_by_mapping(&moved, 0);
    let once = once_blocks(blocks, &compositions);
    let falls = falls_every_block(image_sums.0, blocks);
    let sums_after = weights_by_polarity(&exec);
    let troughs_read = troughs(&value_means(&valued_by_block));
    eprintln!(
        "DUMP {name} PIN readings correct {correct:?} over {over:?} left {left:?} stimulus values {stimulus_read:?} reach {reach:?} first new {first_new_read:?} crossings {crossings_read:?} crossed {crossed:?} tally {tally_read:?} settle {settle:?} highest {highest_read:?} strong total {strong_sum:?} punished moves {punished_moves:?} rewarded moves {rewarded_moves:?} once {once} falls {falls} sums after {sums_after:?} troughs {troughs_read:?}"
    );
    eprintln!(
        "DUMP {name} verdict of this arm: learned {:?} over {over:?} held {} left {left:?}; readings: revised within 23 {:?} value within a quarter of 2p − 1 {:?}; the prediction {UNADDRESSED_PREDICTED:?}",
        correct.map(|c| c >= REWARDED_MIN),
        left.is_none(),
        reversals_within(crossings_read),
        stimulus_read.map(|m| m.map(holds_expected))
    );
    eprintln!(
        "DUMP {name} outside course, per myriad of the image's {:?}",
        blocks
            .iter()
            .map(|b| per_myriad(outside_of(b), outside))
            .collect::<Vec<i64>>()
    );
    eprintln!(
        "DUMP {name} couplings course {:?} beside H-23's {:?}",
        couplings_course(blocks),
        couplings_course(WINDOWED_BLOCKS_1024[k])
    );
    eprintln!(
        "DUMP {name} crossings {crossings_read:?} beside H-23's {:?}, H-22's {:?} and H-21's {:?}",
        CROSSINGS_WINDOWED_1024[k], CROSSINGS_VALUED_1024[k], CROSSINGS_TARGET_1024[k]
    );
    eprintln!(
        "DUMP {name} value by block beside H-23's {:?}",
        value_means(&valued_by_block)
            .iter()
            .zip(value_means(WINDOWED_VALUES_1024[k]))
            .map(|(u, w)| (*u, w))
            .collect::<Vec<_>>()
    );
    eprintln!(
        "DUMP {name} troughs {troughs_read:?} beside H-23's {:?}",
        TROUGHS_WINDOWED_1024[k]
    );
    eprintln!(
        "DUMP {name} strong by flip {strong_sum:?} beside H-23's {:?}",
        STRONG_BY_FLIP_WINDOWED_1024[k]
    );
    eprintln!(
        "DUMP {name} inhibitory course {:?} beside H-23's {:?}",
        course(image_sums.0, blocks),
        course(image_sums.0, WINDOWED_BLOCKS_1024[k])
    );
    eprintln!(
        "DUMP {name} signal {:?}",
        blocks.iter().map(|b| b.9).collect::<Vec<i32>>()
    );
    // The pinned tables of the whole run, and the readings as the constants state.
    pinned(
        &format!("{name} sight"),
        blocks,
        *trace,
        UNADDRESSED_BLOCKS_1024[k],
        UNADDRESSED_TRACES_1024[k],
    );
    assert_eq!(
        compositions.as_slice(),
        UNADDRESSED_COMPOSITIONS_1024[k],
        "{name}: the composition per block"
    );
    assert_eq!(
        earned.as_slice(),
        UNADDRESSED_EARNED_1024[k],
        "{name}: the earned blocks"
    );
    assert_eq!(
        earned_hash(read),
        UNADDRESSED_READ_1024[k],
        "{name}: the readings"
    );
    assert_eq!(
        census_of(volley_ticks),
        UNADDRESSED_CENSUS_1024[k].to_vec(),
        "{name}: the volley's ticks"
    );
    assert_eq!(
        moved.as_slice(),
        UNADDRESSED_MOVES_1024[k],
        "{name}: the moves per block"
    );
    assert_eq!(
        strong.as_slice(),
        UNADDRESSED_STRONG_1024[k],
        "{name}: the strong punishments per block"
    );
    assert_eq!(at_flips, UNADDRESSED_AT_FLIPS_1024[k]);
    assert_eq!(
        valued_by_block.as_slice(),
        UNADDRESSED_VALUES_1024[k],
        "{name}: the engine's value per block"
    );
    assert_eq!(
        values_hash(&values),
        UNADDRESSED_VALUE_HASH_1024[k],
        "{name}: every trial's value"
    );
    assert_eq!(
        watched.weights.as_slice(),
        UNADDRESSED_WEIGHTS_1024[k],
        "{name}: the weights by group per block"
    );
    assert_eq!(
        admitted.as_slice(),
        UNADDRESSED_ADMITTED_1024[k],
        "{name}: the spikes the window admitted per block"
    );
    assert_eq!(
        watched.spikes.as_slice(),
        UNADDRESSED_SPIKES_1024[k],
        "{name}: the spikes by class per block"
    );
    assert_eq!(
        watched.cells.as_slice(),
        UNADDRESSED_CELLS_1024[k],
        "{name}: the network's cells per block"
    );
    assert_eq!(
        watched.went.as_slice(),
        UNADDRESSED_WENT_1024[k],
        "{name}: where the consolidation went per block"
    );
    assert_eq!((image_cells, sizes), (IMAGE_CELLS_1024, CELL_SIZES_1024));
    assert_eq!(correct, CORRECT_UNADDRESSED_1024[k]);
    assert_eq!(over, OVER_UNADDRESSED_1024[k]);
    assert_eq!(left, LEFT_UNADDRESSED_1024[k]);
    assert_eq!(stimulus_read, STIMULUS_VALUES_UNADDRESSED_1024[k]);
    assert_eq!(reach, REACH_UNADDRESSED_1024[k]);
    assert_eq!(first_new_read, FIRST_NEW_UNADDRESSED_1024[k]);
    assert_eq!(crossings_read, CROSSINGS_UNADDRESSED_1024[k]);
    assert_eq!(crossed, CROSSED_UNADDRESSED_1024[k]);
    assert_eq!(tally_read, TALLY_UNADDRESSED_1024[k]);
    assert_eq!(settle, SETTLE_UNADDRESSED_1024[k]);
    assert_eq!(highest_read, HIGHEST_UNADDRESSED_1024[k]);
    assert_eq!(strong_sum, STRONG_BY_FLIP_UNADDRESSED_1024[k]);
    assert_eq!(punished_moves, PUNISHED_MOVES_UNADDRESSED_1024[k]);
    assert_eq!(rewarded_moves, REWARDED_MOVES_UNADDRESSED_1024[k]);
    assert_eq!(once, ONCE_BLOCKS_UNADDRESSED_1024[k]);
    assert_eq!(falls, FALLS_UNADDRESSED_1024[k]);
    assert_eq!(troughs_read, TROUGHS_UNADDRESSED_1024[k]);
    assert_eq!(
        (sums_after, blocks.last().map(|b| (b.7, b.8))),
        (
            SUMS_AFTER_UNADDRESSED_1024[k],
            Some(SUMS_AFTER_UNADDRESSED_1024[k])
        ),
        "{name}: the sums after the run are the last block's"
    );
}

/// H-24's arm that starts from the assignment (brief 057): H-23's arm from the assignment with
/// the reward delivered to every synapse.
#[test]
#[ignore]
fn the_reward_unaddressed_from_the_assignment_at_1024_units_exhaustive() {
    unaddressed_arm(Reversal::AssignmentFirst);
}

/// H-24's arm that starts from the mirrored assignment (brief 057): H-23's arm from the
/// mirrored assignment with the reward delivered to every synapse.
#[test]
#[ignore]
fn the_reward_unaddressed_from_the_mirrored_assignment_at_1024_units_exhaustive() {
    unaddressed_arm(Reversal::MirroredFirst);
}

/// The gate's test (ADR-0061's class; brief 057): the arms and the constants as ADR-0136 and
/// ADR-0137 fixed them; clause 3 at its edges and the verdict naming the clause and the arm
/// over tables written by hand; the network's places and cells over the instrument's network;
/// eight trials on the instrument's network under each delivery, its image flagged as the
/// arms' are and no critic, both oracles held to the record at every trial, the network outside
/// the pairs still under the addressed delivery and moved under the global one; the oracle's
/// replay of a block against the engine's own rule, `step_stdp_all` and `consolidate_signed`,
/// over blocks written by hand; the readings' rules over tables written by hand; and, over the
/// arms' pinned tables, the verdict as written and every reading, block by block. Nothing else
/// added to the gate.
#[test]
fn the_clauses_of_h_24_the_network_s_oracle_and_the_readings_rules() {
    // The arms and the constants.
    assert_eq!(UNADDRESSED_ARMS, WINDOWED_ARMS);
    assert_eq!(
        UNADDRESSED_ARMS,
        [Reversal::AssignmentFirst, Reversal::MirroredFirst]
    );
    assert_eq!(UNADDRESSED_DELIVERY, Delivery::Global);
    assert_eq!(
        UNADDRESSED_PREDICTED, None,
        "ADR-0136 makes no prediction for the verdict"
    );
    assert_eq!((BAND_QUARTERS, BAND_DIVISOR, SOURCES), ((3, 5), 4, 3));
    assert_eq!(
        (REWARDED_MIN, BOUND_PER_CENT, SCHEDULE_BLOCKS),
        (80, 130, 120),
        "clauses 1 and 2 are H-20's"
    );
    assert_eq!(
        WINDOWED_IMAGE_CRC_1024, 0x387f_1060_a1f1_d99b,
        "H-23's image, the one each arm decodes"
    );
    // The image's outside sum: the settled image's excitatory sum less its four couplings.
    let outside = image_outside();
    let couplings = IMAGE_COUPLINGS_1024
        .iter()
        .flatten()
        .fold(0i64, |sum, &c| sum.saturating_add(c));
    assert_eq!(
        outside.saturating_add(couplings),
        QUIET_1024[SETTLED].1.1,
        "the outside sum and the couplings make the excitatory sum"
    );
    assert!(outside > 0 && couplings > 0);
    eprintln!("DUMP the image's outside sum {outside}, its couplings {couplings}");
    // Clause 3 at its edges: 0.75 and 1.25 of the image hold, one LSB beyond either does not; an
    // image that is not a multiple of four rounds the band inward; no image holds nothing.
    assert!(within_band(3_000, 4_000) && within_band(5_000, 4_000));
    assert!(!within_band(2_999, 4_000) && !within_band(5_001, 4_000));
    assert!(within_band(3_001, 4_001) && !within_band(3_000, 4_001));
    assert!(within_band(5_001, 4_001) && !within_band(5_002, 4_001));
    assert!(!within_band(0, 0) && !within_band(1, 0) && !within_band(-3, -4));
    // Over blocks written by hand: the outside sum is the excitatory sum less the couplings.
    let block = |excitatory: i64, couplings: [[i64; 2]; 2]| -> Block {
        (
            BLOCK as u32,
            0,
            [[0; 2]; 2],
            [0; 2],
            [0; 2],
            [0; 2],
            0,
            0,
            excitatory,
            0,
            couplings,
            0,
        )
    };
    assert_eq!(outside_of(&block(1_000, [[10, 20], [30, 40]])), 900);
    let image_excitatory = QUIET_1024[SETTLED].1.1;
    let full = vec![block(image_excitatory, IMAGE_COUPLINGS_1024); SCHEDULE_BLOCKS];
    assert_eq!(left_band(outside, &full), None);
    // The lowest and the highest sums the band holds, three quarters and five quarters of the
    // image's outside sum, rounded inward.
    let low = outside
        .saturating_mul(3)
        .saturating_add(3)
        .checked_div(4)
        .expect("four");
    let high = outside.saturating_mul(5).checked_div(4).expect("four");
    assert!(within_band(low, outside) && !within_band(low.saturating_sub(1), outside));
    assert!(within_band(high, outside) && !within_band(high.saturating_add(1), outside));
    let with_outside = |sum: i64| block(sum.saturating_add(couplings), IMAGE_COUPLINGS_1024);
    let mut edge = full.clone();
    edge[0] = with_outside(low);
    edge[SCHEDULE_BLOCKS - 1] = with_outside(high);
    assert_eq!(left_band(outside, &edge), None, "the band's two ends hold");
    let mut drained = full.clone();
    drained[70] = with_outside(low.saturating_sub(1));
    drained[90] = with_outside(high.saturating_add(1));
    assert_eq!(
        left_band(outside, &drained),
        Some((70, low.saturating_sub(1))),
        "the first block that left the band, with its sum"
    );
    // The verdict: every clause over tables written by hand, and each failing on its own, named.
    let learning_yes = Scheduled {
        learned: [[true; 4]; 2],
        bounded: [true; 2],
        over: [None; 2],
        yes: true,
    };
    assert_eq!(
        unaddressed(outside, [&full, &full]),
        Unaddressed {
            learning: learning_yes,
            left: [None; 2],
            held: [true; 2],
            yes: true
        }
    );
    let verdict = unaddressed(outside, [&full, &drained]);
    assert_eq!(
        (verdict.learning, verdict.left, verdict.held, verdict.yes),
        (
            learning_yes,
            [None, Some((70, low.saturating_sub(1)))],
            [true, false],
            false
        ),
        "clause 3 fails in the second arm at block 70"
    );
    let verdict = unaddressed(outside, [&full, &full[1..]]);
    assert_eq!(
        (verdict.left, verdict.held, verdict.yes),
        ([None; 2], [true, false], false),
        "a run that is not whole holds no clause"
    );
    let mut unlearned = full.clone();
    unlearned[MAPPINGS[2].1 - 1].0 = 0;
    unlearned[MAPPINGS[2].1 - 2].0 = 0;
    let verdict = unaddressed(outside, [&unlearned, &full]);
    assert_eq!(
        (verdict.learning.learned[0], verdict.held, verdict.yes),
        ([true, true, false, true], [true; 2], false),
        "clause 1 fails in the first arm's third mapping, clause 3 holds"
    );
    let mut over = full.clone();
    over[40].10[1][0] = IMAGE_COUPLINGS_1024[1][0]
        .saturating_mul(131)
        .checked_div(100)
        .expect("a hundred");
    over[40].8 = over[40]
        .8
        .saturating_add(over[40].10[1][0].saturating_sub(IMAGE_COUPLINGS_1024[1][0]));
    let verdict = unaddressed(outside, [&full, &over]);
    assert_eq!(
        (verdict.learning.over, verdict.held, verdict.yes),
        ([None, Some((40, 1, 0))], [true; 2], false),
        "clause 2 fails in the second arm at block 40, B→R0, the outside sum unmoved"
    );
    // The network's places over the instrument's network at 1 024 units, whose wiring every
    // image of it carries: the pairs are the synapses the composer replays, and every other
    // excitatory synapse falls in a cell of its source's row and its target's class.
    let sets = geometry(1024, ROTATION_1024);
    let p = prior(1024);
    let mut exec = at_gain(&p, config(1024, 2, 0), GAIN_1024);
    let classes = classes_of(&exec, &sets);
    let mut pairs = [[0u32; 2]; 2];
    let mut excitatory = 0u32;
    for unit in exec.units() {
        if unit.flags & FLAG_INHIBITORY != 0 {
            continue;
        }
        for s in unit.fan_out(exec.blocks()) {
            excitatory = excitatory.saturating_add(1);
            match place_of(&sets, &classes, unit.id as u32, s.target) {
                Place::Pair(st, r) => pairs[st][r] = pairs[st][r].saturating_add(1),
                Place::Outside(row, column) => {
                    assert!(row < SOURCES && column < CLASSES);
                    assert_eq!(classes[unit.id as usize], row.saturating_add(1));
                }
            }
        }
    }
    assert_eq!(
        pairs, SYNAPSES_1024,
        "the pairs are the composer's synapses"
    );
    let network = Network::new(&exec, &sets, &classes);
    assert_eq!(
        network.synapses(),
        excitatory as usize,
        "the network's oracle replays every excitatory synapse"
    );
    assert!(
        network.sources.iter().chain(&network.targets).all(|&a| a),
        "a new executor starts with every unit a source and a target"
    );
    let sizes = cell_sizes(&exec, &sets, &classes);
    let in_cells = sizes
        .iter()
        .flatten()
        .fold(0u32, |sum, &n| sum.saturating_add(n));
    let in_pairs = SYNAPSES_1024
        .iter()
        .flatten()
        .fold(0u32, |sum, &n| sum.saturating_add(n));
    assert_eq!(in_cells.saturating_add(in_pairs), excitatory);
    assert_eq!(
        sizes[0][2], 0,
        "a stimulus unit's synapse onto an excitatory readout unit is a pair's"
    );
    eprintln!("DUMP the instrument's network: {excitatory} excitatory synapses, cells {sizes:?}");
    // The cells over the instrument's network against its own weights: nothing moved; then three
    // weights written by hand, one to each rail and one down by a thousand, each in its cell.
    let image = weights_of(&exec);
    let before = cells_of(&exec, &image, &sets, &classes);
    for (row, cells) in before.iter().enumerate() {
        for (column, cell) in cells.iter().enumerate() {
            assert_eq!(
                (cell.1, cell.2, cell.3, cell.4),
                (0, 0, 0, 0),
                "{row} {column}"
            );
        }
    }
    let (_, excitatory_sum) = weights_by_polarity(&exec);
    let four = harness::couplings(&exec, &sets)
        .iter()
        .fold(0i64, |sum, &c| sum.saturating_add(c));
    assert_eq!(cells_sum(&before), excitatory_sum.saturating_sub(four));
    let mut outside_slots: Vec<(usize, usize, (usize, usize), i16)> = Vec::new();
    for unit in exec.units() {
        if unit.flags & FLAG_INHIBITORY != 0 || outside_slots.len() >= 3 {
            continue;
        }
        for s in unit.fan_out(exec.blocks()) {
            if let Place::Outside(row, column) = place_of(&sets, &classes, unit.id as u32, s.target)
            {
                if outside_slots.len() < 3 && outside_slots.iter().all(|o| o.2 != (row, column)) {
                    outside_slots.push((
                        s.block_idx as usize,
                        usize::from(s.slot),
                        (row, column),
                        s.weight_q1_15,
                    ));
                }
            }
        }
    }
    assert_eq!(outside_slots.len(), 3, "three synapses in three cells");
    let written = [0i16, i16::MAX, 0];
    for (k, &(b, slot, _, w)) in outside_slots.iter().enumerate() {
        exec.blocks_mut()[b].weights_q1_15[slot] = if k == 2 {
            w.saturating_sub(1_000)
        } else {
            written[k]
        };
    }
    let after = cells_of(&exec, &image, &sets, &classes);
    for (k, &(_, _, (row, column), w)) in outside_slots.iter().enumerate() {
        let now = if k == 2 {
            w.saturating_sub(1_000)
        } else {
            written[k]
        };
        let cell = after[row][column];
        let was = before[row][column];
        assert_eq!(
            (cell.0, cell.1, cell.2, cell.3, cell.4),
            (
                was.0
                    .saturating_add(i64::from(now))
                    .saturating_sub(i64::from(w)),
                1,
                i32::from(now).saturating_sub(i32::from(w)),
                u32::from(now == 0),
                u32::from(now == i16::MAX)
            ),
            "cell {row} {column}"
        );
    }
    // A few trials on the instrument's network under each delivery, its image carrying the
    // inhibitory baseline and the signed gate as the arms' images do, with no critic: both
    // oracles held to the record at every trial inside the run, the lead-in's spikes among the
    // global delivery's; under the addressed delivery no excitatory synapse outside the pairs
    // moves, under the global one the network outside them does.
    let fresh = at_gain(&p, config(1024, 2, 0), GAIN_1024);
    let flagged = signed_image(&inhibited_image(&Image::encode(&fresh).expect("quiescent")));
    for (delivery, outside_moved) in [(Delivery::Addressed, false), (Delivery::Global, true)] {
        let mut run_exec = signed_from(&flagged, 1024);
        let image = weights_of(&run_exec);
        let groups = groups_of(&run_exec, &sets);
        let (run, moves, values, watched) = delivered_run(
            &mut run_exec,
            Reversal::AssignmentFirst,
            &sets,
            &groups,
            &classes,
            &image,
            delivery,
            GATE_TRIALS,
        );
        let reach = reach_by_polarity(&run_exec, &image, 1024, &ALL_PAIRS);
        eprintln!(
            "DUMP {delivery:?}: {GATE_TRIALS} trials {:?} moves {moves:?} reach {reach:?}",
            run.3
        );
        assert_eq!(
            (
                run.3.len(),
                moves.len(),
                values.len(),
                watched.admitted.len()
            ),
            (GATE_TRIALS, GATE_TRIALS, 0, GATE_TRIALS),
            "{delivery:?}: a reading a trial, no value without a critic"
        );
        assert!(
            run.3.iter().any(|t| t.4 != 0),
            "{delivery:?}: a trial was rewarded or punished"
        );
        assert_eq!(
            reach.excitatory.1 > 0,
            outside_moved,
            "{delivery:?}: the network outside the pairs"
        );
    }
    // The oracle's replay of a block against the engine's own rule: a block written by hand —
    // four slots, their traces of both signs, a weight at each rail — through presynaptic spikes
    // whose targets fired before, after and at the spike or never, under modulations above and
    // below zero and at zero, with the signed gate set and unset; the oracle's traces, weights
    // and stamp the engine's after every spike, and what it moved the weights' difference.
    let targets = [5u32, 6, 7, 8];
    let mut engine_block = SynapseBlock::new();
    for (slot, &target) in targets.iter().enumerate() {
        assert!(engine_block.set_synapse(slot, target, 6_000, 100, false));
    }
    engine_block.weights_q1_15 = [9_000, 0, i16::MAX, 12_000];
    engine_block.eligibility_q1_15 = [1_200, -800, 3_000, 0];
    engine_block.last_spike_tick = 10_000;
    let mut wiring = wiring_of(&engine_block, 3, &|target| {
        Place::Outside(0, target as usize)
    });
    assert_eq!(wiring.slots.len(), 4);
    let mut last = vec![NO_SPIKE_ON_RECORD; 9];
    let cases: [(u32, [u32; 4], [i32; 4], bool); 6] = [
        (
            10_500,
            [10_200, 10_600, 0, 10_500],
            [ONE, ONE, ONE, ONE],
            true,
        ),
        (
            11_000,
            [10_700, 10_900, 10_950, 0],
            [-ONE / 2, -ONE, 0, ONE / 3],
            true,
        ),
        (11_000, [10_990, 11_000, 0, 10_999], [ONE / 4; 4], true),
        (20_000, [15_000, 19_000, 19_999, 12_000], [-ONE; 4], true),
        (
            20_400,
            [20_100, 20_300, 20_399, 0],
            [ONE / 2, -ONE / 2, ONE, 0],
            false,
        ),
        (
            90_000,
            [89_000, 0, 89_999, 60_000],
            [ONE, ONE, -ONE, -ONE],
            true,
        ),
    ];
    for (c, &(t, posts, modulations, signed)) in cases.iter().enumerate() {
        for (slot, &target) in targets.iter().enumerate() {
            if posts[slot] != NO_SPIKE_ON_RECORD {
                last[target as usize] = posts[slot];
            }
        }
        let posts_now = targets.map(|target| last[target as usize]);
        let weights_before = engine_block.weights_q1_15;
        engine_block.step_stdp_all(t, posts_now, Polarity::Excitatory, 0);
        for (slot, &m) in modulations.iter().enumerate() {
            // Unset, a modulation below zero is the engine's `modulation`, clamped at zero.
            let m = if signed { m } else { m.max(0) };
            engine_block.consolidate_signed(slot, m, Polarity::Excitatory);
        }
        let mut moved = [0i32; 4];
        replay_block(
            &mut wiring,
            t,
            &last,
            signed,
            &|syn| {
                let m = modulations[syn.slot];
                if signed { m } else { m.max(0) }
            },
            &mut |syn, amount| moved[syn.slot] = amount,
        );
        assert_eq!(
            wiring.stamp, engine_block.last_spike_tick,
            "case {c}: the stamp"
        );
        for syn in &wiring.slots {
            assert_eq!(
                (syn.trace, syn.magnitude),
                (
                    engine_block.eligibility_q1_15[syn.slot],
                    i32::from(engine_block.weights_q1_15[syn.slot])
                ),
                "case {c} slot {}: the oracle's trace and weight are the engine's",
                syn.slot
            );
            assert_eq!(
                moved[syn.slot],
                i32::from(engine_block.weights_q1_15[syn.slot])
                    .saturating_sub(i32::from(weights_before[syn.slot])),
                "case {c} slot {}: what it moved",
                syn.slot
            );
        }
        eprintln!(
            "DUMP case {c}: traces {:?} weights {:?} moved {moved:?}",
            engine_block.eligibility_q1_15, engine_block.weights_q1_15
        );
    }
    // The readings' rules over values written by hand.
    let mut went: Went = [[1, -2], [0, 0], [5, -7]];
    add_went(&mut went, &[[2, -1], [3, 0], [0, -1]]);
    assert_eq!(went, [[3, -3], [3, 0], [5, -8]]);
    let mut cells: Cells = [[(0, 0, 0, 0, 0); CLASSES]; SOURCES];
    cells[0][1].0 = 7;
    cells[2][3].0 = -2;
    assert_eq!(cells_sum(&cells), 5);
    // Over the arms' pinned tables: the verdict as written, by the rule committed first; the
    // readings as the constants state; and, block by block over each arm's 120 blocks, the tables
    // consistent with one another and with both oracles — the same trials presenting A as in
    // H-23, the value's trials the block's presentations, clause 4's counts each mapping's last two
    // blocks', each coupling the one before plus what the composer consolidated, the pairs' moves
    // by the network's oracle what the composer consolidated, the outside's moves the cells' sum
    // moved, the cells' sum the outside sum, and the stimulus class's spikes the stimulus sets'.
    let verdict = unaddressed(
        outside,
        [UNADDRESSED_BLOCKS_1024[0], UNADDRESSED_BLOCKS_1024[1]],
    );
    assert_eq!(verdict, UNADDRESSED_1024, "the verdict as written");
    assert_eq!(
        cells_sum(&IMAGE_CELLS_1024),
        outside,
        "the image's cells sum to its outside sum"
    );
    assert!(
        IMAGE_CELLS_1024
            .iter()
            .flatten()
            .all(|c| (c.1, c.2, c.3, c.4) == (0, 0, 0, 0)),
        "the image against itself: nothing moved, nothing at a rail"
    );
    assert_eq!(CELL_SIZES_1024, sizes, "the cells' sizes the network's");
    for (k, &arm) in UNADDRESSED_ARMS.iter().enumerate() {
        let first = first_mapping(arm);
        let blocks = UNADDRESSED_BLOCKS_1024[k];
        let earned = UNADDRESSED_EARNED_1024[k];
        let moved = UNADDRESSED_MOVES_1024[k];
        let compositions = UNADDRESSED_COMPOSITIONS_1024[k];
        let values = UNADDRESSED_VALUES_1024[k];
        let weights = UNADDRESSED_WEIGHTS_1024[k];
        let admitted = UNADDRESSED_ADMITTED_1024[k];
        let spikes = UNADDRESSED_SPIKES_1024[k];
        let cells = UNADDRESSED_CELLS_1024[k];
        let went = UNADDRESSED_WENT_1024[k];
        let strong = UNADDRESSED_STRONG_1024[k];
        assert_eq!(
            [
                blocks.len(),
                compositions.len(),
                earned.len(),
                moved.len(),
                values.len(),
                weights.len(),
                admitted.len(),
                spikes.len(),
                cells.len(),
                went.len()
            ],
            [SCHEDULE_BLOCKS; 10],
            "{arm:?}: 120 blocks of each"
        );
        assert_eq!(strong.len(), SCHEDULE_BLOCKS - FLIP_BLOCK);
        assert_ne!(UNADDRESSED_TRACES_1024[k], 0);
        assert_ne!(UNADDRESSED_READ_1024[k], 0);
        assert_ne!(UNADDRESSED_VALUE_HASH_1024[k], 0);
        assert!(!UNADDRESSED_CENSUS_1024[k].is_empty());
        let correct = mapping_correct(blocks);
        assert_eq!(correct, CORRECT_UNADDRESSED_1024[k]);
        assert_eq!(
            correct.map(|c| c >= REWARDED_MIN),
            verdict.learning.learned[k]
        );
        assert_eq!(first_over(blocks), OVER_UNADDRESSED_1024[k]);
        assert_eq!(first_over(blocks).is_none(), verdict.learning.bounded[k]);
        assert_eq!(left_band(outside, blocks), LEFT_UNADDRESSED_1024[k]);
        assert_eq!(
            LEFT_UNADDRESSED_1024[k].is_none(),
            verdict.held[k],
            "{arm:?}: clause 3 as the band reads it"
        );
        assert_eq!(crossings(blocks), CROSSINGS_UNADDRESSED_1024[k]);
        assert_eq!(
            crossed_scheduled(earned, first),
            CROSSED_UNADDRESSED_1024[k]
        );
        assert_eq!(tally(blocks), TALLY_UNADDRESSED_1024[k]);
        assert_eq!(settle_scheduled(blocks, first), SETTLE_UNADDRESSED_1024[k]);
        assert_eq!(highest(blocks), HIGHEST_UNADDRESSED_1024[k]);
        assert_eq!(strong_by_flip(strong), STRONG_BY_FLIP_UNADDRESSED_1024[k]);
        assert_eq!(
            moves_by_mapping(moved, 1),
            PUNISHED_MOVES_UNADDRESSED_1024[k]
        );
        assert_eq!(
            moves_by_mapping(moved, 0),
            REWARDED_MOVES_UNADDRESSED_1024[k]
        );
        assert_eq!(
            once_blocks(blocks, compositions),
            ONCE_BLOCKS_UNADDRESSED_1024[k]
        );
        assert_eq!(
            falls_every_block(QUIET_1024[SETTLED].1.0, blocks),
            FALLS_UNADDRESSED_1024[k]
        );
        assert_eq!(troughs(&value_means(values)), TROUGHS_UNADDRESSED_1024[k]);
        let last = blocks.last().expect("a block");
        assert_eq!(SUMS_AFTER_UNADDRESSED_1024[k], (last.7, last.8));
        // The reach at the run's end: every pair's synapse moved, and outside the pairs as many as
        // the last block's cells count moved.
        let reach = REACH_UNADDRESSED_1024[k];
        let outside_moved = cells[SCHEDULE_BLOCKS - 1]
            .iter()
            .flatten()
            .fold(0u64, |sum, c| sum.saturating_add(u64::from(c.1)));
        assert_eq!(
            reach.excitatory,
            (u64::from(in_pairs), outside_moved),
            "{arm:?}: the reach is the cells'"
        );
        // Each mapping's last two blocks hold clause 4's trials, correct trials and values, read
        // here as H-23's reading.
        for (m, &(_, end)) in MAPPINGS.iter().enumerate() {
            for s in 0..2 {
                let (n, c, v) = values[end.saturating_sub(LAST_BLOCKS)..end].iter().fold(
                    (0i64, 0i64, 0i64),
                    |(n, c, v), b| {
                        (
                            n.saturating_add(b[s][0]),
                            c.saturating_add(b[s][2]),
                            v.saturating_add(b[s][1]),
                        )
                    },
                );
                let (tn, tc, tv) = STIMULUS_VALUES_UNADDRESSED_1024[k][m][s];
                assert_eq!(
                    (n, c, v),
                    (i64::from(tn), i64::from(tc), tv),
                    "{arm:?} mapping {m} stimulus {s}: the value table's"
                );
            }
        }
        let mut previous = IMAGE_COUPLINGS_1024;
        let mut previous_outside = outside;
        for (j, block) in blocks.iter().enumerate() {
            let in_force = mirrored_at(first, j);
            assert_eq!(
                block.1, WINDOWED_BLOCKS_1024[k][j].1,
                "{arm:?} block {j}: the same trials present A as in H-23"
            );
            let presented = [block.1, (BLOCK as u32).saturating_sub(block.1)];
            for (s, &n) in presented.iter().enumerate() {
                assert_eq!(
                    earned[j].0[s].iter().sum::<u32>(),
                    n,
                    "{arm:?} block {j}: every presentation of {s} selected or tied"
                );
                assert_eq!(
                    values[j][s][0],
                    i64::from(n),
                    "{arm:?} block {j}: a value for every presentation of {s}"
                );
                assert_eq!(
                    values[j][s][2],
                    i64::from(earned[j].0[s][answer_of(s as u8, in_force)]),
                    "{arm:?} block {j}: the value's correct trials of {s} the block's"
                );
                assert!(
                    admitted[j][s][s.saturating_add(1)] <= n.saturating_mul(VOLLEY_UNITS),
                    "{arm:?} block {j}: at most the volley of {s}"
                );
            }
            let correct = earned[j].0[0][answer_of(0, in_force)]
                .saturating_add(earned[j].0[1][answer_of(1, in_force)]);
            assert_eq!(
                block.0, correct,
                "{arm:?} block {j}: correct under the mapping in force"
            );
            let mut consolidated = 0i64;
            for &(s, r) in &ALL_PAIRS {
                assert_eq!(
                    block.10[s][r],
                    previous[s][r].saturating_add(earned[j].2[s][r]),
                    "{arm:?} block {j}: {s}→{r} moved by what the composer consolidated"
                );
                consolidated = consolidated.saturating_add(earned[j].2[s][r]);
            }
            let net = |row: &[i64; 2]| row[0].saturating_add(row[1]);
            assert_eq!(
                net(&went[j][0]).saturating_add(net(&went[j][1])),
                consolidated,
                "{arm:?} block {j}: the network's oracle moved the pairs as the composer did"
            );
            assert!(
                went[j].iter().all(|row| row[0] >= 0 && row[1] <= 0),
                "{arm:?} block {j}: raised and lowered each with its sign"
            );
            let now = cells_sum(&cells[j]);
            assert_eq!(
                now,
                outside_of(block),
                "{arm:?} block {j}: the cells sum to the outside sum"
            );
            assert_eq!(
                now.saturating_sub(previous_outside),
                net(&went[j][2]),
                "{arm:?} block {j}: the outside moved by what the network's oracle consolidated there"
            );
            for (row, cells_row) in cells[j].iter().enumerate() {
                for (column, cell) in cells_row.iter().enumerate() {
                    let size = CELL_SIZES_1024[row][column];
                    assert!(
                        cell.1 <= size && cell.3 <= size && cell.4 <= size,
                        "{arm:?} block {j} cell {row} {column}: counts within the cell's synapses"
                    );
                }
            }
            assert_eq!(
                spikes[j][1],
                block.4[0].saturating_add(block.4[1]),
                "{arm:?} block {j}: the stimulus class's spikes are the stimulus sets'"
            );
            assert!(
                weights[j].1 <= weights[j].2,
                "{arm:?} block {j}: the lowest weight at most the highest"
            );
            previous = block.10;
            previous_outside = now;
        }
    }
}

// --------------------- the measurement (brief 057), its tables in inhibition/pins/h24.rs

const UNADDRESSED_TRACES_1024: [u64; 2] = [0x56c51bc47386d3a4, 0xaa1db7bc2f35b6a2];
const UNADDRESSED_READ_1024: [u64; 2] = [0x4f6498e2a0948953, 0x0be05d25b4194d89];
const UNADDRESSED_VALUE_HASH_1024: [u64; 2] = [0x0ee5a1c6deebb1ce, 0x7010ccb90c22e0b9];
const CORRECT_UNADDRESSED_1024: [[u32; 4]; 2] = [[79, 78, 64, 87], [89, 67, 64, 83]];
const OVER_UNADDRESSED_1024: [Option<(usize, usize, usize)>; 2] = [None, None];
const LEFT_UNADDRESSED_1024: [Option<(usize, i64)>; 2] = [None, None];
const ONCE_BLOCKS_UNADDRESSED_1024: [u32; 2] = [120, 120];
const FALLS_UNADDRESSED_1024: [bool; 2] = [false, false];

// =================================================================================== H-25

// -------------------------------------------- written before the run (ADR-0138, ADR-0140)

/// The arms of H-25 (ADR-0138): H-23's two, in their order, each its own weekly test, from
/// H-23's image, the task carrying no critic of its own, and H-20's flips.
const DRAWN_ARMS: [Reversal; 2] = UNADDRESSED_ARMS;

/// The one change from H-23 (ADR-0138, ADR-0139): the task's delivery, the address's sources
/// drawn by the executor from its critic's window counts at every trial's end, its targets the
/// selected readout's units as under the addressed delivery (`Executor::address_drawn`).
const DRAWN_DELIVERY: Delivery = Delivery::Drawn;

/// ADR-0138's prediction, written first: yes — the drawn sources are the presented stimulus's
/// set but for about 1.6 background units a trial, so the reward reaches what the host's address
/// reached, and a little more. A reading beside the verdict and never asserted; the verdict is
/// read by the clauses whatever it says.
const DRAWN_PREDICTED: bool = true;

// ------------------------------------------------------------ the criterion (ADR-0138)

/// H-25's criterion (ADR-0138), clause by clause per arm `[assignment first, mirrored first]`:
/// (1) each mapping learned and (2) the couplings bounded, H-20's two as `scheduled` reads them;
/// (3) each reversal within 23 blocks of its flip, H-23's `reversals_within` of `crossings`; and
/// (4) the network held, H-24's band at every block's end of a run of 120 blocks, `left_band`.
/// `yes` is all in both arms; a no names the clause and the arm — under clause 1 the mapping,
/// under clause 2 the block and the pair, under clause 3 the reversal, under clause 4 the first
/// block that left the band with its sum.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct Drawn {
    learning: Scheduled,
    revised: [[bool; 3]; 2],
    left: [Option<(usize, i64)>; 2],
    held: [bool; 2],
    yes: bool,
}

fn drawn(image: i64, arms: [&[Block]; 2]) -> Drawn {
    drawn_of(&IMAGE_COUPLINGS_1024, image, arms)
}

/// `drawn` against the image couplings given (brief 067): clauses 1 and 2 by `scheduled_of`, and
/// `image` the outside sum of the same image. `drawn` calls it with the instrument's image's.
fn drawn_of(couplings: &[[i64; 2]; 2], image: i64, arms: [&[Block]; 2]) -> Drawn {
    let learning = scheduled_of(couplings, arms);
    let revised = arms.map(|blocks| reversals_within(crossings(blocks)));
    let left = arms.map(|blocks| left_band(image, blocks));
    let held = [0usize, 1].map(|k| arms[k].len() == SCHEDULE_BLOCKS && left[k].is_none());
    Drawn {
        learning,
        revised,
        left,
        held,
        yes: learning.yes && revised.iter().flatten().all(|&r| r) && held.iter().all(|&h| h),
    }
}

// ----------------------------------------------------- the readings' shape (brief 058)

/// The addressed sources by block (brief 058), per presented stimulus `[A, B]` and group in
/// `GROUPS`'s order: at every trial's end, the units the delivery wrote as the address's
/// sources, summed over the block's trials of that stimulus — `admitted_blocks`'s sum over the
/// sources instead of the spikes. The host's sources are the presented stimulus's set, in the
/// stimulus's own group: `[s][s + 1]` of them drawn, and every other group's the window's
/// background.
type Sourced = Admitted;

/// The drawn sources per block beside the host's (brief 058), per stimulus `[A, B]`: the
/// presented stimulus's units drawn, the presented stimulus's units left out — its set's size
/// times its presentations less those drawn — and the units of every other group drawn,
/// summed. `sizes` is the units of each group.
fn beside_host(block: &Block, sourced: &Sourced, sizes: &[u32; GROUPS]) -> [[u32; 3]; 2] {
    let presented = [block.1, (BLOCK as u32).saturating_sub(block.1)];
    [0usize, 1].map(|s| {
        let own = s.saturating_add(1);
        let drawn_in = sourced[s][own];
        let host = sizes[own].saturating_mul(presented[s]);
        let others = sourced[s]
            .iter()
            .enumerate()
            .filter(|&(g, _)| g != own)
            .fold(0u32, |sum, (_, &n)| sum.saturating_add(n));
        [drawn_in, host.saturating_sub(drawn_in), others]
    })
}

/// Every trial's sources by group, hashed: `fnv1a_64` over the counts as `i32` words.
fn sources_hash(sourced: &[[u32; GROUPS]]) -> u64 {
    let words: Vec<i32> = sourced
        .iter()
        .flatten()
        .map(|&n| i32::try_from(n).unwrap_or(i32::MAX))
        .collect();
    fnv1a_64(&words)
}

// ---------------------------------------------------------------- the run (brief 058)

/// One arm of H-25 at 1 024 units (brief 058): the calibration before any rewarded run (H-25's
/// stopping rule, step 2) — the settled engine held to ADR-0077 step by step and its images,
/// H-20's image by its CRC, a frozen block from the zero image held to ADR-0077's frozen run,
/// H-21's, H-22's and H-23's images by their CRCs, and H-23's first block from H-23's image under
/// the host's address reproduced table by table — then the arm's 7 680 trials from H-23's image
/// under the drawn delivery with no task critic and H-20's flips, the drawn sources held to the
/// critic's oracle's counts and both oracles held to the record at every trial; everything
/// dumped, the clauses and the readings computed before anything is held; then the pinned tables
/// of the whole run.
fn drawn_arm(arm: Reversal) {
    let k = DRAWN_ARMS
        .iter()
        .position(|&a| a == arm)
        .expect("an arm of H-25");
    let name = format!("drawn1024 {arm:?}");
    let (zero, signed) = signed_images(&name);
    assert_eq!(
        pinned_crc(&signed),
        PUNISHED_IMAGE_CRC_1024,
        "{name}: H-20's image, H-19's and H-18's"
    );
    {
        let mut frozen = frozen_from(&zero, 1024);
        assert_eq!(
            (frozen.inhibitory_baseline_q16(), frozen.signed_gate()),
            (None, false),
            "{name}: the calibration's image leaves the inhibitory baseline and the signed gate unset"
        );
        let calibration = taught_run(&mut frozen, Arm::Withheld, 1024, BLOCK);
        calibration_holds(&format!("{name} calibration"), &calibration);
    }
    let targeted = targeted_image(&signed, TARGET_PERIOD_1024);
    assert!(
        only_the_target(&signed, &targeted),
        "{name}: H-21's image is H-20's in every byte but the target period's and the seal"
    );
    assert_eq!(
        (pinned_crc(&targeted), crc64(&with_version(&targeted, 18))),
        (TARGET_IMAGE_CRC_1024, TARGET_IMAGE_CRC_FORMAT_18_1024),
        "{name}: H-21's image, and as H-21 read it"
    );
    let valued = valued_image(&targeted, VALUED_CRITIC);
    assert!(
        only_the_critic(&targeted, &valued),
        "{name}: H-22's image is H-21's in every byte but the critic's and the seal"
    );
    assert_eq!(
        (pinned_crc(&valued), crc64(&with_version(&valued, 19))),
        (VALUED_IMAGE_CRC_1024, VALUED_IMAGE_CRC_FORMAT_19_1024),
        "{name}: H-22's image, and as H-22 read it"
    );
    let windowed = with_window_bytes(&valued, WINDOW_TICKS_1024);
    assert!(
        only_the_window(&valued, &windowed),
        "{name}: H-23's image is H-22's in every byte but the window's and the seal"
    );
    assert_eq!(
        pinned_crc(&windowed),
        WINDOWED_IMAGE_CRC_1024,
        "{name}: H-23's image, the image this arm decodes"
    );
    h23_first_block(&windowed, arm, k, &name);
    eprintln!(
        "DUMP {name} calibration holds: ADR-0077's settled candidate, H-20's to H-23's images and H-23's first block under the host's address"
    );
    let sets = geometry(1024, ROTATION_1024);
    let mut exec = signed_from(&windowed, 1024);
    assert_eq!(
        (
            exec.critic(),
            exec.critic_window_ticks(),
            exec.istdp_target_period_ticks(),
            exec.window_opened(),
            exec.draws()
        ),
        (
            Some(VALUED_CRITIC),
            WINDOW_TICKS_1024,
            TARGET_PERIOD_1024,
            exec.ticks(),
            Ok(())
        ),
        "{name}: H-23's configuration, the window open at the load, and the engine draws"
    );
    assert!(
        exec.units().iter().all(|u| u.value_weight == 0) && exec.features().iter().all(|&c| c == 0),
        "{name}: every weight and every count zero"
    );
    let image_sums = QUIET_1024[SETTLED].1;
    assert_eq!(
        weights_by_polarity(&exec),
        image_sums,
        "{name}: the image's sums"
    );
    assert_eq!(
        pair_couplings(&exec, &sets),
        IMAGE_COUPLINGS_1024,
        "{name}: the same image"
    );
    let groups = groups_of(&exec, &sets);
    let sizes = group_sizes(&groups);
    let classes = classes_of(&exec, &sets);
    let image = weights_of(&exec);
    let image_cells = cells_of(&exec, &image, &sets, &classes);
    let outside = image_outside();
    assert_eq!(
        (image_cells, cell_sizes(&exec, &sets, &classes)),
        (IMAGE_CELLS_1024, CELL_SIZES_1024),
        "{name}: H-24's image cells"
    );
    assert_eq!(
        cells_sum(&image_cells),
        outside,
        "{name}: the cells sum to the image's outside sum"
    );
    let first = first_mapping(arm);
    // The shadows beside the composer (brief 059, ADR-0141): they read the run and are never
    // written back, so the run is H-25's, and every table below is held as it was.
    let (run, moves, values, watched, beside) = shadowed_run(
        &mut exec,
        arm,
        &sets,
        &groups,
        &classes,
        &image,
        DRAWN_DELIVERY,
        SCHEDULE_TRIALS,
        true,
    );
    let beside = beside.expect("the shadows' reading beside the run");
    let (blocks, trace, trials, read, volley_ticks) = &run;
    let earned = earned_blocks(read);
    let compositions: Vec<Composition> = trials.chunks(BLOCK).map(composition).collect();
    let moved = moves_blocks(read, &moves);
    let strong = strong_scheduled(read, first);
    let valued_by_block = value_blocks(read, &values);
    let admitted = admitted_blocks(read, &watched.admitted);
    let sourced: Vec<Sourced> = admitted_blocks(read, &watched.sourced);
    let at_flips = watched
        .at_flips
        .map(|c| c.expect("the run reached the trial after every flip"));
    assert_eq!(blocks.len(), SCHEDULE_BLOCKS, "{name}: 120 blocks");
    assert_eq!(
        (
            read.len(),
            values.len(),
            watched.admitted.len(),
            watched.sourced.len()
        ),
        (
            SCHEDULE_TRIALS,
            SCHEDULE_TRIALS,
            SCHEDULE_TRIALS,
            SCHEDULE_TRIALS
        )
    );
    assert_eq!(
        [
            compositions.len(),
            earned.len(),
            moved.len(),
            valued_by_block.len(),
            watched.weights.len(),
            admitted.len(),
            watched.spikes.len(),
            watched.cells.len(),
            watched.went.len(),
            sourced.len()
        ],
        [SCHEDULE_BLOCKS; 10]
    );
    assert_eq!(strong.len(), SCHEDULE_BLOCKS - FLIP_BLOCK);
    // The run's tables dumped whole, as they are pinned, before anything is held or read.
    eprintln!("DUMP {name} PIN blocks {blocks:?}");
    eprintln!("DUMP {name} PIN trace {trace:#018x}");
    eprintln!("DUMP {name} PIN compositions {compositions:?}");
    eprintln!("DUMP {name} PIN earned {earned:?}");
    eprintln!("DUMP {name} PIN read {:#018x}", earned_hash(read));
    eprintln!("DUMP {name} PIN census {:?}", census_of(volley_ticks));
    eprintln!("DUMP {name} PIN moves {moved:?}");
    eprintln!("DUMP {name} PIN strong {strong:?}");
    eprintln!("DUMP {name} PIN at flips {at_flips:?}");
    eprintln!("DUMP {name} PIN values {valued_by_block:?}");
    eprintln!("DUMP {name} PIN value hash {:#018x}", values_hash(&values));
    eprintln!("DUMP {name} PIN weights {:?}", watched.weights);
    eprintln!("DUMP {name} PIN admitted {admitted:?}");
    eprintln!("DUMP {name} PIN spikes {:?}", watched.spikes);
    eprintln!("DUMP {name} PIN cells {:?}", watched.cells);
    eprintln!("DUMP {name} PIN went {:?}", watched.went);
    eprintln!("DUMP {name} PIN sourced {sourced:?}");
    eprintln!(
        "DUMP {name} PIN sources hash {:#018x}",
        sources_hash(&watched.sourced)
    );
    // Everything read and dumped, and the clauses and the readings computed, before anything
    // else is held.
    dump_earned(&name, &run, &earned);
    let reach = reach_by_polarity(&exec, &image, 1024, &ALL_PAIRS);
    let correct = mapping_correct(blocks);
    let over = first_over(blocks);
    let crossings_read = crossings(blocks);
    let revised = reversals_within(crossings_read);
    let left = left_band(outside, blocks);
    let stimulus_read = stimulus_values(read, &values);
    let first_new_read = first_new_scheduled(read, first);
    let crossed = crossed_scheduled(&earned, first);
    let tally_read = tally(blocks);
    let settle = settle_scheduled(blocks, first);
    let highest_read = highest(blocks);
    let strong_sum = strong_by_flip(&strong);
    let punished_moves = moves_by_mapping(&moved, 1);
    let rewarded_moves = moves_by_mapping(&moved, 0);
    let once = once_blocks(blocks, &compositions);
    let falls = falls_every_block(image_sums.0, blocks);
    let sums_after = weights_by_polarity(&exec);
    let troughs_read = troughs(&value_means(&valued_by_block));
    let host: Vec<[[u32; 3]; 2]> = blocks
        .iter()
        .zip(&sourced)
        .map(|(b, s)| beside_host(b, s, &sizes))
        .collect();
    eprintln!(
        "DUMP {name} PIN readings correct {correct:?} over {over:?} crossings {crossings_read:?} revised {revised:?} left {left:?} stimulus values {stimulus_read:?} reach {reach:?} first new {first_new_read:?} crossed {crossed:?} tally {tally_read:?} settle {settle:?} highest {highest_read:?} strong total {strong_sum:?} punished moves {punished_moves:?} rewarded moves {rewarded_moves:?} once {once} falls {falls} sums after {sums_after:?} troughs {troughs_read:?}"
    );
    eprintln!(
        "DUMP {name} verdict of this arm: learned {:?} over {over:?} revised {revised:?} held {} left {left:?}; readings: value within a quarter of 2p − 1 {:?}; the prediction, yes: {DRAWN_PREDICTED}",
        correct.map(|c| c >= REWARDED_MIN),
        left.is_none(),
        stimulus_read.map(|m| m.map(holds_expected))
    );
    eprintln!(
        "DUMP {name} the drawn sources beside the host's per block, [A, B] of [drawn, left out, others]: {host:?}; group sizes {sizes:?}"
    );
    eprintln!(
        "DUMP {name} outside course, per myriad of the image's {:?}",
        blocks
            .iter()
            .map(|b| per_myriad(outside_of(b), outside))
            .collect::<Vec<i64>>()
    );
    eprintln!(
        "DUMP {name} couplings course {:?} beside H-23's {:?}",
        couplings_course(blocks),
        couplings_course(WINDOWED_BLOCKS_1024[k])
    );
    eprintln!(
        "DUMP {name} crossings {crossings_read:?} beside H-23's {:?} and H-24's {:?}",
        CROSSINGS_WINDOWED_1024[k], CROSSINGS_UNADDRESSED_1024[k]
    );
    eprintln!(
        "DUMP {name} value by block beside H-23's {:?}",
        value_means(&valued_by_block)
            .iter()
            .zip(value_means(WINDOWED_VALUES_1024[k]))
            .map(|(u, w)| (*u, w))
            .collect::<Vec<_>>()
    );
    eprintln!(
        "DUMP {name} troughs {troughs_read:?} beside H-23's {:?}",
        TROUGHS_WINDOWED_1024[k]
    );
    eprintln!(
        "DUMP {name} strong by flip {strong_sum:?} beside H-23's {:?}",
        STRONG_BY_FLIP_WINDOWED_1024[k]
    );
    eprintln!(
        "DUMP {name} inhibitory course {:?} beside H-23's {:?}",
        course(image_sums.0, blocks),
        course(image_sums.0, WINDOWED_BLOCKS_1024[k])
    );
    eprintln!(
        "DUMP {name} signal {:?}",
        blocks.iter().map(|b| b.9).collect::<Vec<i32>>()
    );
    // The pinned tables of the whole run, and the readings as the constants state.
    pinned(
        &format!("{name} sight"),
        blocks,
        *trace,
        DRAWN_BLOCKS_1024[k],
        DRAWN_TRACES_1024[k],
    );
    assert_eq!(
        compositions.as_slice(),
        DRAWN_COMPOSITIONS_1024[k],
        "{name}: the composition per block"
    );
    assert_eq!(
        earned.as_slice(),
        DRAWN_EARNED_1024[k],
        "{name}: the earned blocks"
    );
    assert_eq!(
        earned_hash(read),
        DRAWN_READ_1024[k],
        "{name}: the readings"
    );
    assert_eq!(
        census_of(volley_ticks),
        DRAWN_CENSUS_1024[k].to_vec(),
        "{name}: the volley's ticks"
    );
    assert_eq!(
        moved.as_slice(),
        DRAWN_MOVES_1024[k],
        "{name}: the moves per block"
    );
    assert_eq!(
        strong.as_slice(),
        DRAWN_STRONG_1024[k],
        "{name}: the strong punishments per block"
    );
    assert_eq!(at_flips, DRAWN_AT_FLIPS_1024[k]);
    assert_eq!(
        valued_by_block.as_slice(),
        DRAWN_VALUES_1024[k],
        "{name}: the engine's value per block"
    );
    assert_eq!(
        values_hash(&values),
        DRAWN_VALUE_HASH_1024[k],
        "{name}: every trial's value"
    );
    assert_eq!(
        watched.weights.as_slice(),
        DRAWN_WEIGHTS_1024[k],
        "{name}: the weights by group per block"
    );
    assert_eq!(
        admitted.as_slice(),
        DRAWN_ADMITTED_1024[k],
        "{name}: the spikes the window admitted per block"
    );
    assert_eq!(
        watched.spikes.as_slice(),
        DRAWN_SPIKES_1024[k],
        "{name}: the spikes by class per block"
    );
    assert_eq!(
        watched.cells.as_slice(),
        DRAWN_CELLS_1024[k],
        "{name}: the network's cells per block"
    );
    assert_eq!(
        watched.went.as_slice(),
        DRAWN_WENT_1024[k],
        "{name}: where the consolidation went per block"
    );
    assert_eq!(
        sourced.as_slice(),
        DRAWN_SOURCED_1024[k],
        "{name}: the drawn sources per block"
    );
    assert_eq!(
        sources_hash(&watched.sourced),
        DRAWN_SOURCES_HASH_1024[k],
        "{name}: every trial's drawn sources"
    );
    assert_eq!(correct, CORRECT_DRAWN_1024[k]);
    assert_eq!(over, OVER_DRAWN_1024[k]);
    assert_eq!(crossings_read, CROSSINGS_DRAWN_1024[k]);
    assert_eq!(left, LEFT_DRAWN_1024[k]);
    assert_eq!(stimulus_read, STIMULUS_VALUES_DRAWN_1024[k]);
    assert_eq!(reach, REACH_DRAWN_1024[k]);
    assert_eq!(first_new_read, FIRST_NEW_DRAWN_1024[k]);
    assert_eq!(crossed, CROSSED_DRAWN_1024[k]);
    assert_eq!(tally_read, TALLY_DRAWN_1024[k]);
    assert_eq!(settle, SETTLE_DRAWN_1024[k]);
    assert_eq!(highest_read, HIGHEST_DRAWN_1024[k]);
    assert_eq!(strong_sum, STRONG_BY_FLIP_DRAWN_1024[k]);
    assert_eq!(punished_moves, PUNISHED_MOVES_DRAWN_1024[k]);
    assert_eq!(rewarded_moves, REWARDED_MOVES_DRAWN_1024[k]);
    assert_eq!(once, ONCE_BLOCKS_DRAWN_1024[k]);
    assert_eq!(falls, FALLS_DRAWN_1024[k]);
    assert_eq!(troughs_read, TROUGHS_DRAWN_1024[k]);
    assert_eq!(
        (sums_after, blocks.last().map(|b| (b.7, b.8))),
        (SUMS_AFTER_DRAWN_1024[k], Some(SUMS_AFTER_DRAWN_1024[k])),
        "{name}: the sums after the run are the last block's"
    );
    // H-26 (brief 059): the run is H-25's, table by table and reading by reading; only now is
    // the shadow beside it read.
    eprintln!("DUMP {name} H-25's arm reproduced bit for bit with the shadows beside it");
    released_reading(&name, k, arm, blocks, read, &watched.went, &beside);
}

/// H-25's arm that starts from the assignment (brief 058): H-23's arm from the assignment with
/// the address's sources drawn by the engine. Since brief 059 the shadows of H-26 ride beside
/// it, read after H-25's own tables are held.
#[test]
#[ignore]
fn the_address_drawn_from_the_assignment_at_1024_units_exhaustive() {
    drawn_arm(Reversal::AssignmentFirst);
}

/// H-25's arm that starts from the mirrored assignment (brief 058): H-23's arm from the mirrored
/// assignment with the address's sources drawn by the engine. Since brief 059 the shadows of
/// H-26 ride beside it, read after H-25's own tables are held.
#[test]
#[ignore]
fn the_address_drawn_from_the_mirrored_assignment_at_1024_units_exhaustive() {
    drawn_arm(Reversal::MirroredFirst);
}

/// The gate's test (ADR-0061's class; brief 058): the arms and the constants as ADR-0138 and
/// ADR-0140 fixed them; H-25's four clauses at their edges and the verdict naming the clause and
/// the arm over tables written by hand; the readings' rules over tables written by hand; and
/// eight trials on the instrument's network under the drawn delivery, its image flagged as the
/// arms' images are and carrying the critic with its window, the drawn sources held at every
/// trial to the units the critic's oracle counted, both oracles held to the record, and every
/// trial's sources read against the spikes the window admitted. Nothing else added to the gate.
#[test]
fn the_clauses_of_h_25_the_drawn_sources_and_the_readings_rules() {
    // The arms and the constants.
    assert_eq!(DRAWN_ARMS, UNADDRESSED_ARMS);
    assert_eq!(
        DRAWN_ARMS,
        [Reversal::AssignmentFirst, Reversal::MirroredFirst]
    );
    assert_eq!(DRAWN_DELIVERY, Delivery::Drawn);
    const _: () = assert!(DRAWN_PREDICTED, "ADR-0138 predicts yes");
    assert_eq!(
        (
            REWARDED_MIN,
            BOUND_PER_CENT,
            REVERSAL_BLOCKS_MAX,
            CROSSING_MARK,
            SCHEDULE_BLOCKS
        ),
        (80, 130, 23, 40, 120),
        "clauses 1 to 3 are H-23's"
    );
    assert_eq!(
        (BAND_QUARTERS, BAND_DIVISOR),
        ((3, 5), 4),
        "clause 4 is H-24's clause 3"
    );
    assert_eq!(
        (WINDOWED_IMAGE_CRC_1024, WINDOW_TICKS_1024),
        (0x387f_1060_a1f1_d99b, 100),
        "H-23's image, the one each arm decodes, and its window"
    );
    let outside = image_outside();
    // The verdict: every clause over tables written by hand, and each failing on its own, named.
    let block = |correct: u32, excitatory: i64, couplings: [[i64; 2]; 2]| -> Block {
        (
            correct,
            0,
            [[0; 2]; 2],
            [0; 2],
            [0; 2],
            [0; 2],
            0,
            0,
            excitatory,
            0,
            couplings,
            0,
        )
    };
    let couplings = IMAGE_COUPLINGS_1024
        .iter()
        .flatten()
        .fold(0i64, |sum, &c| sum.saturating_add(c));
    let full =
        vec![block(BLOCK as u32, QUIET_1024[SETTLED].1.1, IMAGE_COUPLINGS_1024); SCHEDULE_BLOCKS];
    let learning_yes = Scheduled {
        learned: [[true; 4]; 2],
        bounded: [true; 2],
        over: [None; 2],
        yes: true,
    };
    assert_eq!(
        drawn(outside, [&full, &full]),
        Drawn {
            learning: learning_yes,
            revised: [[true; 3]; 2],
            left: [None; 2],
            held: [true; 2],
            yes: true
        }
    );
    // Clause 3 at its edge: a mapping whose first `below` blocks are one short of the mark.
    let slow = |mapping: usize, below: usize| -> Vec<Block> {
        let mut blocks = full.clone();
        let from = MAPPINGS[mapping].0;
        for b in blocks.iter_mut().skip(from).take(below) {
            b.0 = CROSSING_MARK.saturating_sub(1);
        }
        blocks
    };
    let at_edge = slow(2, REVERSAL_BLOCKS_MAX.saturating_sub(1));
    assert_eq!(crossings(&at_edge)[2], Some(REVERSAL_BLOCKS_MAX));
    assert!(
        drawn(outside, [&full, &at_edge]).yes,
        "the second reversal passes the mark in its 23rd block: it holds"
    );
    let past = slow(2, REVERSAL_BLOCKS_MAX);
    assert_eq!(
        crossings(&past)[2],
        Some(REVERSAL_BLOCKS_MAX.saturating_add(1))
    );
    let verdict = drawn(outside, [&full, &past]);
    assert_eq!(
        (verdict.learning, verdict.revised, verdict.held, verdict.yes),
        (
            learning_yes,
            [[true; 3], [true, false, true]],
            [true; 2],
            false
        ),
        "clause 3 fails in the second arm's second reversal alone, in its 24th block"
    );
    let first_late = slow(0, 20);
    assert_eq!(crossings(&first_late)[0], Some(21));
    assert!(
        drawn(outside, [&first_late, &full]).yes,
        "the first mapping is no reversal: clause 3 reads nothing of it"
    );
    let mut unlearned = full.clone();
    unlearned[MAPPINGS[2].1 - 1].0 = 0;
    unlearned[MAPPINGS[2].1 - 2].0 = 0;
    let verdict = drawn(outside, [&unlearned, &full]);
    assert_eq!(
        (
            verdict.learning.learned[0],
            verdict.revised,
            verdict.held,
            verdict.yes
        ),
        ([true, true, false, true], [[true; 3]; 2], [true; 2], false),
        "clause 1 fails in the first arm's third mapping alone"
    );
    let mut over = full.clone();
    over[40].10[1][0] = IMAGE_COUPLINGS_1024[1][0]
        .saturating_mul(131)
        .checked_div(100)
        .expect("a hundred");
    over[40].8 = over[40]
        .8
        .saturating_add(over[40].10[1][0].saturating_sub(IMAGE_COUPLINGS_1024[1][0]));
    let verdict = drawn(outside, [&full, &over]);
    assert_eq!(
        (
            verdict.learning.over,
            verdict.revised,
            verdict.held,
            verdict.yes
        ),
        ([None, Some((40, 1, 0))], [[true; 3]; 2], [true; 2], false),
        "clause 2 fails in the second arm at block 40, B→R0, alone"
    );
    let low = outside
        .saturating_mul(3)
        .saturating_add(3)
        .checked_div(4)
        .expect("four");
    let high = outside.saturating_mul(5).checked_div(4).expect("four");
    let with_outside = |sum: i64| {
        block(
            BLOCK as u32,
            sum.saturating_add(couplings),
            IMAGE_COUPLINGS_1024,
        )
    };
    let mut edge = full.clone();
    edge[0] = with_outside(low);
    edge[SCHEDULE_BLOCKS - 1] = with_outside(high);
    assert!(
        drawn(outside, [&edge, &edge]).yes,
        "the band's two ends hold"
    );
    let mut drained = full.clone();
    drained[70] = with_outside(high.saturating_add(1));
    let verdict = drawn(outside, [&drained, &full]);
    assert_eq!(
        (
            verdict.learning,
            verdict.revised,
            verdict.left,
            verdict.held,
            verdict.yes
        ),
        (
            learning_yes,
            [[true; 3]; 2],
            [Some((70, high.saturating_add(1))), None],
            [false, true],
            false
        ),
        "clause 4 fails in the first arm at block 70 alone, with its sum"
    );
    let verdict = drawn(outside, [&full, &full[1..]]);
    assert_eq!(
        (verdict.held, verdict.yes),
        ([true, false], false),
        "a run that is not whole holds no clause"
    );
    // The readings' rules over values written by hand: the drawn sources beside the host's, and
    // every trial's sources hashed.
    let mut sizes = [0u32; GROUPS];
    sizes[1] = 51;
    sizes[2] = 51;
    let mut hand = block(0, 0, [[0; 2]; 2]);
    hand.1 = 30;
    let sourced: Sourced = [[1, 1_500, 3, 0, 2, 5], [0, 2, 1_700, 1, 0, 4]];
    assert_eq!(
        beside_host(&hand, &sourced, &sizes),
        [[1_500, 30, 11], [1_700, 34, 7]],
        "A presented 30 times and B 34: drawn, left out, others"
    );
    let every: Sourced = [[0, 1_530, 0, 0, 0, 0], [0, 0, 1_734, 0, 0, 0]];
    assert_eq!(
        beside_host(&hand, &every, &sizes),
        [[1_530, 0, 0], [1_734, 0, 0]],
        "the host's address: every unit of the presented set and nothing else"
    );
    let trials = [[1u32, 51, 0, 0, 2, 0], [0, 0, 50, 1, 0, 0]];
    let mut moved = trials;
    moved[1][3] = 2;
    assert_eq!(sources_hash(&trials), sources_hash(&trials));
    assert_ne!(sources_hash(&trials), sources_hash(&moved));
    assert_ne!(sources_hash(&trials), sources_hash(&trials[..1]));
    // Eight trials on the instrument's network under the drawn delivery, its image carrying the
    // inhibitory baseline and the signed gate as the arms' images do, and the critic with its
    // window as H-23's does, the window's length read by its rule: the drawn sources held at every
    // trial to the units the critic's oracle counted, the targets to the selected readout, both
    // oracles held to the record; and every trial's sources by group within the spikes the window
    // admitted, a group drawn from exactly when the window admitted a spike of it.
    let sets = geometry(1024, ROTATION_1024);
    let p = prior(1024);
    let fresh = at_gain(&p, config(1024, 2, 0), GAIN_1024);
    let flagged = signed_image(&inhibited_image(&Image::encode(&fresh).expect("quiescent")));
    let window = shortest_delay(signed_from(&flagged, 1024).blocks()).expect("a synapse");
    assert_eq!(
        window, WINDOW_TICKS_1024,
        "the instrument's network carries the reference prior's delays"
    );
    let bytes = with_window_bytes(&valued_image(&flagged, VALUED_CRITIC), window);
    let mut exec = signed_from(&bytes, 1024);
    assert_eq!(
        (exec.critic(), exec.critic_window_ticks(), exec.draws()),
        (Some(VALUED_CRITIC), window, Ok(()))
    );
    let image = weights_of(&exec);
    let groups = groups_of(&exec, &sets);
    let classes = classes_of(&exec, &sets);
    let (run, moves, values, watched) = delivered_run(
        &mut exec,
        Reversal::AssignmentFirst,
        &sets,
        &groups,
        &classes,
        &image,
        Delivery::Drawn,
        GATE_TRIALS,
    );
    let reach = reach_by_polarity(&exec, &image, 1024, &ALL_PAIRS);
    eprintln!(
        "DUMP drawn: {GATE_TRIALS} trials {:?} moves {moves:?} reach {reach:?} sources {:?} admitted {:?}",
        run.3, watched.sourced, watched.admitted
    );
    assert_eq!(
        (
            run.3.len(),
            moves.len(),
            values.len(),
            watched.admitted.len(),
            watched.sourced.len()
        ),
        (
            GATE_TRIALS,
            GATE_TRIALS,
            GATE_TRIALS,
            GATE_TRIALS,
            GATE_TRIALS
        ),
        "a reading, a value and a drawing a trial"
    );
    assert!(
        run.3.iter().any(|t| t.4 != 0),
        "a trial was rewarded or punished"
    );
    for (t, (sources, admitted)) in watched.sourced.iter().zip(&watched.admitted).enumerate() {
        for (g, (&drawn_units, &spikes)) in sources.iter().zip(admitted).enumerate() {
            assert!(
                drawn_units <= spikes && (drawn_units == 0) == (spikes == 0),
                "trial {t} group {g}: {drawn_units} units drawn of {spikes} spikes admitted"
            );
        }
    }
    // Over the arms' pinned tables: the verdict as written, by the rule committed first; the
    // readings as the constants state; and, block by block over each arm's 120 blocks, the tables
    // consistent with one another and with both oracles — the same trials presenting A as in
    // H-23, the value's trials the block's presentations, each coupling the one before plus what
    // the composer consolidated, the pairs' moves by the network's oracle what the composer
    // consolidated, the outside's moves the cells' sum moved, the cells' sum the outside sum, and
    // the drawn sources within the spikes the window admitted, a group drawn from exactly when the
    // window admitted a spike of it, the presented stimulus's drawn units at most its set's.
    let verdict = drawn(outside, [DRAWN_BLOCKS_1024[0], DRAWN_BLOCKS_1024[1]]);
    assert_eq!(verdict, DRAWN_1024, "the verdict as written");
    let sizes = group_sizes(&groups);
    for (k, &arm) in DRAWN_ARMS.iter().enumerate() {
        let first = first_mapping(arm);
        let blocks = DRAWN_BLOCKS_1024[k];
        let earned = DRAWN_EARNED_1024[k];
        let moved = DRAWN_MOVES_1024[k];
        let compositions = DRAWN_COMPOSITIONS_1024[k];
        let values = DRAWN_VALUES_1024[k];
        let weights = DRAWN_WEIGHTS_1024[k];
        let admitted = DRAWN_ADMITTED_1024[k];
        let spikes = DRAWN_SPIKES_1024[k];
        let cells = DRAWN_CELLS_1024[k];
        let went = DRAWN_WENT_1024[k];
        let sourced = DRAWN_SOURCED_1024[k];
        let strong = DRAWN_STRONG_1024[k];
        assert_eq!(
            [
                blocks.len(),
                compositions.len(),
                earned.len(),
                moved.len(),
                values.len(),
                weights.len(),
                admitted.len(),
                spikes.len(),
                cells.len(),
                went.len(),
                sourced.len()
            ],
            [SCHEDULE_BLOCKS; 11],
            "{arm:?}: 120 blocks of each"
        );
        assert_eq!(strong.len(), SCHEDULE_BLOCKS - FLIP_BLOCK);
        assert_ne!(DRAWN_TRACES_1024[k], 0);
        assert_ne!(DRAWN_READ_1024[k], 0);
        assert_ne!(DRAWN_VALUE_HASH_1024[k], 0);
        assert_ne!(DRAWN_SOURCES_HASH_1024[k], 0);
        assert!(!DRAWN_CENSUS_1024[k].is_empty());
        let correct = mapping_correct(blocks);
        assert_eq!(correct, CORRECT_DRAWN_1024[k]);
        assert_eq!(
            correct.map(|c| c >= REWARDED_MIN),
            verdict.learning.learned[k]
        );
        assert_eq!(first_over(blocks), OVER_DRAWN_1024[k]);
        assert_eq!(first_over(blocks).is_none(), verdict.learning.bounded[k]);
        assert_eq!(crossings(blocks), CROSSINGS_DRAWN_1024[k]);
        assert_eq!(
            reversals_within(CROSSINGS_DRAWN_1024[k]),
            verdict.revised[k],
            "{arm:?}: clause 3 as the crossings read it"
        );
        assert_eq!(left_band(outside, blocks), LEFT_DRAWN_1024[k]);
        assert_eq!(
            LEFT_DRAWN_1024[k].is_none(),
            verdict.held[k],
            "{arm:?}: clause 4 as the band reads it"
        );
        assert_eq!(crossed_scheduled(earned, first), CROSSED_DRAWN_1024[k]);
        assert_eq!(tally(blocks), TALLY_DRAWN_1024[k]);
        assert_eq!(settle_scheduled(blocks, first), SETTLE_DRAWN_1024[k]);
        assert_eq!(highest(blocks), HIGHEST_DRAWN_1024[k]);
        assert_eq!(strong_by_flip(strong), STRONG_BY_FLIP_DRAWN_1024[k]);
        assert_eq!(moves_by_mapping(moved, 1), PUNISHED_MOVES_DRAWN_1024[k]);
        assert_eq!(moves_by_mapping(moved, 0), REWARDED_MOVES_DRAWN_1024[k]);
        assert_eq!(once_blocks(blocks, compositions), ONCE_BLOCKS_DRAWN_1024[k]);
        assert_eq!(
            falls_every_block(QUIET_1024[SETTLED].1.0, blocks),
            FALLS_DRAWN_1024[k]
        );
        assert_eq!(troughs(&value_means(values)), TROUGHS_DRAWN_1024[k]);
        let last = blocks.last().expect("a block");
        assert_eq!(SUMS_AFTER_DRAWN_1024[k], (last.7, last.8));
        // The reach at the run's end: the pairs' synapses that moved, and outside the pairs as
        // many as the last block's cells count moved.
        let reach = REACH_DRAWN_1024[k];
        let outside_moved = cells[SCHEDULE_BLOCKS - 1]
            .iter()
            .flatten()
            .fold(0u64, |sum, c| sum.saturating_add(u64::from(c.1)));
        assert_eq!(
            reach.excitatory.1, outside_moved,
            "{arm:?}: the reach outside the pairs is the cells'"
        );
        // Each mapping's last two blocks hold the value's trials, correct trials and values.
        for (m, &(_, end)) in MAPPINGS.iter().enumerate() {
            for s in 0..2 {
                let (n, c, v) = values[end.saturating_sub(LAST_BLOCKS)..end].iter().fold(
                    (0i64, 0i64, 0i64),
                    |(n, c, v), b| {
                        (
                            n.saturating_add(b[s][0]),
                            c.saturating_add(b[s][2]),
                            v.saturating_add(b[s][1]),
                        )
                    },
                );
                let (tn, tc, tv) = STIMULUS_VALUES_DRAWN_1024[k][m][s];
                assert_eq!(
                    (n, c, v),
                    (i64::from(tn), i64::from(tc), tv),
                    "{arm:?} mapping {m} stimulus {s}: the value table's"
                );
            }
        }
        let mut previous = IMAGE_COUPLINGS_1024;
        let mut previous_outside = outside;
        for (j, block) in blocks.iter().enumerate() {
            let in_force = mirrored_at(first, j);
            assert_eq!(
                block.1, WINDOWED_BLOCKS_1024[k][j].1,
                "{arm:?} block {j}: the same trials present A as in H-23"
            );
            let presented = [block.1, (BLOCK as u32).saturating_sub(block.1)];
            for (s, &n) in presented.iter().enumerate() {
                let own = s.saturating_add(1);
                assert_eq!(
                    earned[j].0[s].iter().sum::<u32>(),
                    n,
                    "{arm:?} block {j}: every presentation of {s} selected or tied"
                );
                assert_eq!(
                    values[j][s][0],
                    i64::from(n),
                    "{arm:?} block {j}: a value for every presentation of {s}"
                );
                assert_eq!(
                    values[j][s][2],
                    i64::from(earned[j].0[s][answer_of(s as u8, in_force)]),
                    "{arm:?} block {j}: the value's correct trials of {s} the block's"
                );
                for (g, (&units, &fired)) in sourced[j][s].iter().zip(&admitted[j][s]).enumerate() {
                    assert!(
                        units <= fired && (units == 0) == (fired == 0),
                        "{arm:?} block {j} stimulus {s} group {g}: {units} drawn of {fired} admitted"
                    );
                }
                assert!(
                    sourced[j][s][own] <= sizes[own].saturating_mul(n),
                    "{arm:?} block {j}: at most the set of {s} a presentation"
                );
            }
            let correct = earned[j].0[0][answer_of(0, in_force)]
                .saturating_add(earned[j].0[1][answer_of(1, in_force)]);
            assert_eq!(
                block.0, correct,
                "{arm:?} block {j}: correct under the mapping in force"
            );
            let mut consolidated = 0i64;
            for &(s, r) in &ALL_PAIRS {
                assert_eq!(
                    block.10[s][r],
                    previous[s][r].saturating_add(earned[j].2[s][r]),
                    "{arm:?} block {j}: {s}→{r} moved by what the composer consolidated"
                );
                consolidated = consolidated.saturating_add(earned[j].2[s][r]);
            }
            let net = |row: &[i64; 2]| row[0].saturating_add(row[1]);
            assert_eq!(
                net(&went[j][0]).saturating_add(net(&went[j][1])),
                consolidated,
                "{arm:?} block {j}: the network's oracle moved the pairs as the composer did"
            );
            assert!(
                went[j].iter().all(|row| row[0] >= 0 && row[1] <= 0),
                "{arm:?} block {j}: raised and lowered each with its sign"
            );
            let now = cells_sum(&cells[j]);
            assert_eq!(
                now,
                outside_of(block),
                "{arm:?} block {j}: the cells sum to the outside sum"
            );
            assert_eq!(
                now.saturating_sub(previous_outside),
                net(&went[j][2]),
                "{arm:?} block {j}: the outside moved by what the network's oracle consolidated there"
            );
            for (row, cells_row) in cells[j].iter().enumerate() {
                for (column, cell) in cells_row.iter().enumerate() {
                    let size = CELL_SIZES_1024[row][column];
                    assert!(
                        cell.1 <= size && cell.3 <= size && cell.4 <= size,
                        "{arm:?} block {j} cell {row} {column}: counts within the cell's synapses"
                    );
                }
            }
            assert_eq!(
                spikes[j][1],
                block.4[0].saturating_add(block.4[1]),
                "{arm:?} block {j}: the stimulus class's spikes are the stimulus sets'"
            );
            assert!(
                weights[j].1 <= weights[j].2,
                "{arm:?} block {j}: the lowest weight at most the highest"
            );
            previous = block.10;
            previous_outside = now;
        }
    }
}

// --------------------- the measurement (brief 058), its tables in inhibition/pins/h25.rs

const DRAWN_TRACES_1024: [u64; 2] = [0x113d0b33181135e2, 0xee98a94a4ba25846];
const DRAWN_READ_1024: [u64; 2] = [0x606fddf2c6648248, 0xda51758177c02783];
const DRAWN_VALUE_HASH_1024: [u64; 2] = [0x4c87997e17939b2d, 0xcdb1e67e960ddd86];
const DRAWN_SOURCES_HASH_1024: [u64; 2] = [0x39f157c1260bb9c5, 0x5285cd4173ec5f47];
const CORRECT_DRAWN_1024: [[u32; 4]; 2] = [[122, 124, 119, 116], [124, 118, 123, 117]];
const OVER_DRAWN_1024: [Option<(usize, usize, usize)>; 2] = [None, None];
const LEFT_DRAWN_1024: [Option<(usize, i64)>; 2] = [None, None];
const ONCE_BLOCKS_DRAWN_1024: [u32; 2] = [120, 120];
const FALLS_DRAWN_1024: [bool; 2] = [false, false];
const SUMS_AFTER_DRAWN_1024: [(i64, i64); 2] = [(140653317, 219748610), (140974490, 220582185)];

// =================================================================================== H-26

// -------------------------------------------- written before the run (ADR-0141, ADR-0142)

/// The arms of H-26 (ADR-0141): H-25's two, in their order, each H-25's own weekly test with the
/// shadows beside its composer — H-25's run reproduced bit for bit and held to H-25's tables
/// before anything of the shadow is read.
const RELEASED_ARMS: [Reversal; 2] = DRAWN_ARMS;

/// ADR-0141's prediction, written first: no — without a competition the readout that lost
/// carries much of the eligibility, H-24 read the other pairs moving as much as the answer's,
/// and the geometry makes the two readouts' couplings equal. A reading beside the verdict and
/// never asserted; the verdict is read by the rule whatever it says.
const RELEASED_PREDICTED: bool = false;

/// H-26's rule (ADR-0141): the cost at most half the signal, read in integers as
/// `COST_TIMES × cost ≤ signal`. It does not move after the run.
const COST_TIMES: i64 = 2;

// ------------------------------------------------------------ the criterion (ADR-0141)

/// The shadow's consolidation folded by the address in force and the mapping in force (brief
/// 059), `[side][pairs][raised, lowered]`:
/// - the side: `[0]` the pairs of the readout the last trial selected, the targets the run's
///   address wrote; `[1]` the pairs of the readout it did not select, which only the release
///   reaches — both readouts' after a tie, and before the first trial;
/// - the pairs: `[0]` each stimulus onto its answer under the mapping in force at the trial
///   the consolidation fell in, `[1]` each stimulus onto the other readout, as `Went` reads
///   them;
/// - the weight raised and the weight lowered, each summed with its sign.
type Shade = [[[i64; 2]; 2]; 2];

/// The side of the address in force a readout's pairs lie on: 0 where the last trial selected
/// the readout, 1 where it did not — both readouts after a tie and before the first trial.
fn side_of(selected: Option<u8>, readout: usize) -> usize {
    usize::from(selected.map(usize::from) != Some(readout))
}

/// One trial's consolidation folded into a `Shade`: `shifted` by stimulus, readout and
/// direction, `selected` the selection the address in force was written under — the trial
/// before's — and `mirrored` the mapping in force at the trial the consolidation fell in.
fn shade_of(shifted: &Shifted, selected: Option<u8>, mirrored: bool) -> Shade {
    let mut out: Shade = [[[0; 2]; 2]; 2];
    for &(s, r) in &ALL_PAIRS {
        let pairs = usize::from(answer_of(s as u8, mirrored) != r);
        let into = &mut out[side_of(selected, r)][pairs];
        for (sum, &amount) in into.iter_mut().zip(&shifted[s][r]) {
            *sum = sum.saturating_add(amount);
        }
    }
    out
}

/// A `Shade` plus another, amount by amount.
fn add_shade(into: &mut Shade, shade: &Shade) {
    for (a, b) in into
        .iter_mut()
        .flatten()
        .flatten()
        .zip(shade.iter().flatten().flatten())
    {
        *a = a.saturating_add(*b);
    }
}

/// The net of a `[raised, lowered]`.
fn net_of(sides: &[i64; 2]) -> i64 {
    sides[0].saturating_add(sides[1])
}

/// The cost of a shade (ADR-0141): its consolidation on the pairs of the readout not selected,
/// signed against the answer — the other pairs' net, where a rise is cost, less the answer
/// pairs' net, where a fall is. The selected side is the run's own address and enters nothing.
fn cost_of(shade: &Shade) -> i64 {
    net_of(&shade[1][1]).saturating_sub(net_of(&shade[1][0]))
}

/// The learning signal of a `Went` (ADR-0141): the answer pairs' net consolidation less the
/// other pairs', as H-24's and H-25's readings of where the consolidation went define them.
fn signal_of(went: &Went) -> i64 {
    net_of(&went[0]).saturating_sub(net_of(&went[1]))
}

/// The kind of the trial an address was written at: 0 a correct selection, 1 a wrong one, 2 a
/// tie — and no trial at all, before the first, where nothing was selected.
fn kind_of(before: Option<&EarnedTrial>) -> usize {
    match before {
        Some(t) if t.2.is_some() => usize::from(!t.3),
        _ => 2,
    }
}

/// One block of a shadow (brief 059): its shade summed over the block's trials, and the block's
/// cost by the kind of the trial each address was written at, `[after a correct selection,
/// after a wrong one, after a tie]`, which sum to the shade's cost.
type Costed = (Shade, [i64; 3]);

/// A shadow's blocks from what each trial consolidated, `BLOCK` trials each: every trial's
/// `Shifted` folded under the selection of the trial before it — none before the first — and
/// the mapping in force at the trial itself, in an arm whose first mapping is `first`; the
/// trial's cost entered under the kind of the trial before it.
fn costed_blocks(read: &[EarnedTrial], shifted: &[Shifted], first: bool) -> Vec<Costed> {
    assert_eq!(read.len(), shifted.len(), "a reading of the shadow a trial");
    shifted
        .chunks(BLOCK)
        .enumerate()
        .map(|(j, trials)| {
            let mut block: Costed = ([[[0; 2]; 2]; 2], [0; 3]);
            for (i, moved) in trials.iter().enumerate() {
                let t = j.saturating_mul(BLOCK).saturating_add(i);
                let before = t.checked_sub(1).and_then(|p| read.get(p));
                let mirrored = first != flipped_at(&SCHEDULE_FLIPS, t);
                let shade = shade_of(moved, before.and_then(|b| b.2), mirrored);
                add_shade(&mut block.0, &shade);
                let kind = &mut block.1[kind_of(before)];
                *kind = kind.saturating_add(cost_of(&shade));
            }
            block
        })
        .collect()
}

/// A table of 120 blocks summed over each mapping's blocks; none for a run of any other length.
fn by_mapping(per_block: &[i64]) -> Option<[i64; 4]> {
    (per_block.len() == SCHEDULE_BLOCKS).then(|| {
        MAPPINGS.map(|(from, to)| {
            per_block.get(from..to).map_or(0, |mine| {
                mine.iter().fold(0i64, |sum, &c| sum.saturating_add(c))
            })
        })
    })
}

/// H-26's rule for one mapping (ADR-0141): the cost at most half the signal.
fn affordable(cost: i64, signal: i64) -> bool {
    cost.saturating_mul(COST_TIMES) <= signal
}

/// H-26's criterion (ADR-0141), per arm `[assignment first, mirrored first]` and mapping: the
/// cost — the released shadow's consolidation on the pairs of the readout not selected, signed
/// against the answer, summed over the mapping's blocks — the signal — the run's answer pairs'
/// net consolidation less its other pairs', by the network's oracle, summed over the mapping's
/// blocks — and whether the cost is at most half the signal, in a run of 120 blocks of each; a
/// run of any other length holds nothing and reads zeros. `yes` is every mapping of both arms;
/// a no names the mappings whose `held` is false.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct Released {
    cost: [[i64; 4]; 2],
    signal: [[i64; 4]; 2],
    held: [[bool; 4]; 2],
    yes: bool,
}

fn released(arms: [(&[Costed], &[Went]); 2]) -> Released {
    let costs = arms
        .map(|(costed, _)| by_mapping(&costed.iter().map(|c| cost_of(&c.0)).collect::<Vec<i64>>()));
    let signals =
        arms.map(|(_, went)| by_mapping(&went.iter().map(signal_of).collect::<Vec<i64>>()));
    let held = [0usize, 1].map(|k| match (costs[k], signals[k]) {
        (Some(cost), Some(signal)) => [0usize, 1, 2, 3].map(|m| affordable(cost[m], signal[m])),
        _ => [false; 4],
    });
    Released {
        cost: costs.map(|c| c.unwrap_or([0; 4])),
        signal: signals.map(|s| s.unwrap_or([0; 4])),
        held,
        yes: held.iter().flatten().all(|&h| h),
    }
}

// ----------------------------------------------------- the readings' shape (brief 059)

/// The readouts' spikes over a block (brief 059), `[in the readout window, over the whole
/// trial][the selected readout's, the other's, both readouts' at a tie]`: each trial's two
/// counts summed on the side its own selection put them, a tie's two counts together.
type Heard = [[u64; 3]; 2];

fn heard_blocks(read: &[EarnedTrial], over_trial: &[[u32; 2]]) -> Vec<Heard> {
    assert_eq!(
        read.len(),
        over_trial.len(),
        "a count over the trial a trial"
    );
    read.chunks(BLOCK)
        .zip(over_trial.chunks(BLOCK))
        .map(|(trials, whole)| {
            let mut out: Heard = [[0; 3]; 2];
            for (t, over) in trials.iter().zip(whole) {
                for (row, counts) in out.iter_mut().zip([&t.1, over]) {
                    match t.2 {
                        Some(r) => {
                            let r = usize::from(r);
                            row[0] = row[0].saturating_add(u64::from(counts[r]));
                            row[1] = row[1].saturating_add(u64::from(counts[r ^ 1]));
                        }
                        None => {
                            row[2] = row[2]
                                .saturating_add(u64::from(counts[0]))
                                .saturating_add(u64::from(counts[1]));
                        }
                    }
                }
            }
            out
        })
        .collect()
}

/// The eligibility at a block's rewards (brief 059), from the sources drawn at each trial's
/// end: `[onto the selected readout, onto the other, onto both at a tie][above zero, below
/// zero]`, each trial's by its own selection — the address written there, under which the next
/// trial's spikes are consolidated.
type Eligible = [[i64; 2]; 3];

fn eligible_blocks(read: &[EarnedTrial], eligible: &[[[i64; 2]; 2]]) -> Vec<Eligible> {
    assert_eq!(read.len(), eligible.len(), "an eligibility a trial");
    read.chunks(BLOCK)
        .zip(eligible.chunks(BLOCK))
        .map(|(trials, traces)| {
            let mut out: Eligible = [[0; 2]; 3];
            for (t, onto) in trials.iter().zip(traces) {
                for (readout, sides) in onto.iter().enumerate() {
                    let row = match t.2 {
                        Some(r) => usize::from(usize::from(r) != readout),
                        None => 2,
                    };
                    for (sum, &trace) in out[row].iter_mut().zip(sides) {
                        *sum = sum.saturating_add(trace);
                    }
                }
            }
            out
        })
        .collect()
}

/// The bins the count margins are read in: 0, a tie; 1; 2; 3 to 4; 5 to 8; 9 or more.
const MARGIN_BINS: usize = 6;

fn margin_bin(margin: u32) -> usize {
    match margin {
        0 => 0,
        1 => 1,
        2 => 2,
        3..=4 => 3,
        5..=8 => 4,
        _ => 5,
    }
}

/// The count margins of a block (brief 059): its trials by the margin the gating decided by —
/// the larger count in the readout window less the smaller — in `MARGIN_BINS`'s bins, and the
/// margins summed.
type Margins = ([u32; MARGIN_BINS], u64);

fn margins_blocks(read: &[EarnedTrial]) -> Vec<Margins> {
    read.chunks(BLOCK)
        .map(|trials| {
            let mut out: Margins = ([0; MARGIN_BINS], 0);
            for t in trials {
                let margin = t.1[0].abs_diff(t.1[1]);
                let bin = &mut out.0[margin_bin(margin)];
                *bin = bin.saturating_add(1);
                out.1 = out.1.saturating_add(u64::from(margin));
            }
            out
        })
        .collect()
}

/// A shadow's couplings at every block's end (brief 059): `image`, the couplings it started
/// from, plus what it consolidated into each pair up to there, `[stimulus][readout]`.
fn shadow_couplings(image: [[i64; 2]; 2], shifted: &[Shifted]) -> Vec<[[i64; 2]; 2]> {
    let mut now = image;
    shifted
        .chunks(BLOCK)
        .map(|trials| {
            for moved in trials {
                for &(s, r) in &ALL_PAIRS {
                    now[s][r] = now[s][r].saturating_add(net_of(&moved[s][r]));
                }
            }
            now
        })
        .collect()
}

/// The cost and the signal of each mapping, the reversal's blocks apart from the learned ones
/// (ADR-0141's reading): `[up to the crossing, past it]` of `(cost, signal)` — the mapping's
/// blocks up to and including the first with at least `CROSSING_MARK` correct, as `crossings`
/// counts them, and the blocks after it. A mapping that never crossed is all the first; for the
/// first mapping the blocks up to the crossing are those it took from the image.
fn apart(costs: &[i64], signals: &[i64], crossed: [Option<usize>; 4]) -> [[(i64, i64); 2]; 4] {
    let sum = |table: &[i64], from: usize, to: usize| {
        table.get(from..to).map_or(0, |mine| {
            mine.iter().fold(0i64, |sum, &c| sum.saturating_add(c))
        })
    };
    let mut out = [[(0, 0); 2]; 4];
    for (m, &(from, to)) in MAPPINGS.iter().enumerate() {
        let at = crossed[m].map_or(to, |blocks| from.saturating_add(blocks).min(to));
        out[m] = [
            (sum(costs, from, at), sum(signals, from, at)),
            (sum(costs, at, to), sum(signals, at, to)),
        ];
    }
    out
}

/// A table's rows summed over each mapping's blocks by `add`, from `zero`; `zero` for a mapping
/// the table does not hold.
fn over_mappings<R, T: Copy>(table: &[R], zero: T, add: &dyn Fn(&mut T, &R)) -> [T; 4] {
    MAPPINGS.map(|(from, to)| {
        let mut sum = zero;
        for row in table.get(from..to).unwrap_or(&[]) {
            add(&mut sum, row);
        }
        sum
    })
}

/// Every trial's reading beside the run, hashed: `fnv1a_64` over each trial's released
/// consolidation, its eligibility from the drawn sources and its readouts' spikes over the
/// trial, each number as its `i32` words.
fn beside_hash(beside: &Beside) -> u64 {
    let mut words: Vec<i32> = Vec::new();
    let mut wide = |x: i64| {
        words.push(x as i32);
        words.push((x >> 32) as i32);
    };
    let Shadowed {
        released, eligible, ..
    } = &beside.shadowed;
    for ((moved, traces), counts) in released.iter().zip(eligible).zip(&beside.heard) {
        for &amount in moved.iter().flatten().flatten() {
            wide(amount);
        }
        for &trace in traces.iter().flatten() {
            wide(trace);
        }
        for &count in counts {
            wide(i64::from(count));
        }
    }
    fnv1a_64(&words)
}

// ---------------------------------------------------------------- the run (brief 059)

/// H-26's reading of one arm (brief 059), called by H-25's arm after every one of H-25's tables
/// is held, so that nothing of the shadow is read on a run that is not H-25's bit for bit:
/// - the run's own consolidation by the shadow's fold, held to the network's oracle block by
///   block — nothing on the pairs of the readout not selected, and the selected side the
///   oracle's answer pairs and other pairs, direction by direction;
/// - the released shadow's blocks, the readouts' spikes, the eligibility at the rewards, the
///   count margins and the shadow's couplings, dumped whole as they are pinned;
/// - this arm's part of the verdict by the rule committed first, and the readings by mapping;
/// - then the pinned tables.
fn released_reading(
    name: &str,
    k: usize,
    arm: Reversal,
    blocks: &[Block],
    read: &[EarnedTrial],
    went: &[Went],
    beside: &Beside,
) {
    let first = first_mapping(arm);
    let Shadowed {
        run,
        released: shadow,
        eligible,
        couplings,
    } = &beside.shadowed;
    assert_eq!(
        (
            run.len(),
            shadow.len(),
            eligible.len(),
            beside.heard.len(),
            went.len()
        ),
        (
            SCHEDULE_TRIALS,
            SCHEDULE_TRIALS,
            SCHEDULE_TRIALS,
            SCHEDULE_TRIALS,
            SCHEDULE_BLOCKS
        ),
        "{name}: a reading beside every trial"
    );
    let own = costed_blocks(read, run, first);
    for (j, (mine, oracle)) in own.iter().zip(went).enumerate() {
        assert_eq!(
            (mine.0[1], mine.1),
            ([[0; 2]; 2], [0; 3]),
            "{name} block {j}: the run consolidated nothing onto the readout not selected"
        );
        assert_eq!(
            mine.0[0],
            [oracle[0], oracle[1]],
            "{name} block {j}: the composer's fold is the network's oracle's"
        );
    }
    let costed = costed_blocks(read, shadow, first);
    let heard = heard_blocks(read, &beside.heard);
    let traces = eligible_blocks(read, eligible);
    let margins = margins_blocks(read);
    let course = shadow_couplings(IMAGE_COUPLINGS_1024, shadow);
    let hash = beside_hash(beside);
    assert_eq!(
        [
            costed.len(),
            heard.len(),
            traces.len(),
            margins.len(),
            course.len()
        ],
        [SCHEDULE_BLOCKS; 5],
        "{name}: 120 blocks of each"
    );
    assert_eq!(
        course.last(),
        Some(couplings),
        "{name}: the shadow's tables sum to the shadow's own weights"
    );
    // The tables dumped whole, as they are pinned, before anything of them is held or read.
    eprintln!("DUMP {name} PIN h26-costed {costed:?}");
    eprintln!("DUMP {name} PIN h26-heard {heard:?}");
    eprintln!("DUMP {name} PIN h26-eligible {traces:?}");
    eprintln!("DUMP {name} PIN h26-margins {margins:?}");
    eprintln!("DUMP {name} PIN h26-couplings {course:?}");
    eprintln!("DUMP {name} PIN h26-hash {hash:#018x}");
    // This arm's part of the verdict, by the rule committed first, and the readings.
    let costs: Vec<i64> = costed.iter().map(|c| cost_of(&c.0)).collect();
    let signals: Vec<i64> = went.iter().map(signal_of).collect();
    let cost = by_mapping(&costs).expect("a run of 120 blocks");
    let signal = by_mapping(&signals).expect("a run of 120 blocks");
    let held = [0usize, 1, 2, 3].map(|m| affordable(cost[m], signal[m]));
    let kinds = over_mappings(&costed, [0i64; 3], &|sum: &mut [i64; 3], row: &Costed| {
        for (a, b) in sum.iter_mut().zip(&row.1) {
            *a = a.saturating_add(*b);
        }
    });
    let split = apart(&costs, &signals, crossings(blocks));
    eprintln!("DUMP {name} PIN h26-cost {cost:?}");
    eprintln!("DUMP {name} PIN h26-signal {signal:?}");
    eprintln!("DUMP {name} PIN h26-kinds {kinds:?}");
    eprintln!("DUMP {name} PIN h26-apart {split:?}");
    eprintln!(
        "DUMP {name} H-26, this arm: cost {cost:?} signal {signal:?} cost at most half the signal {held:?}; the prediction, yes: {RELEASED_PREDICTED}"
    );
    eprintln!(
        "DUMP {name} H-26 cost per block {costs:?} signal per block {signals:?} crossings {:?}",
        crossings(blocks)
    );
    eprintln!(
        "DUMP {name} H-26 shade by mapping, [selected, not selected][answer's pairs, other pairs][raised, lowered]: {:?}; the run's own selected side {:?}",
        over_mappings(
            &costed,
            [[[0i64; 2]; 2]; 2],
            &|sum: &mut Shade, row: &Costed| add_shade(sum, &row.0)
        ),
        over_mappings(
            &own,
            [[[0i64; 2]; 2]; 2],
            &|sum: &mut Shade, row: &Costed| add_shade(sum, &row.0)
        )
        .map(|shade| shade[0])
    );
    eprintln!(
        "DUMP {name} H-26 readouts' spikes by mapping, [window, trial][selected, other, at ties]: {:?}",
        over_mappings(&heard, [[0u64; 3]; 2], &|sum: &mut Heard, row: &Heard| {
            for (a, b) in sum.iter_mut().flatten().zip(row.iter().flatten()) {
                *a = a.saturating_add(*b);
            }
        })
    );
    eprintln!(
        "DUMP {name} H-26 eligibility at the rewards by mapping, [selected, other, at ties][above zero, below zero]: {:?}",
        over_mappings(
            &traces,
            [[0i64; 2]; 3],
            &|sum: &mut Eligible, row: &Eligible| {
                for (a, b) in sum.iter_mut().flatten().zip(row.iter().flatten()) {
                    *a = a.saturating_add(*b);
                }
            }
        )
    );
    eprintln!(
        "DUMP {name} H-26 margins by mapping, trials at 0, 1, 2, 3–4, 5–8, 9+ and the margins summed: {:?}; trials by outcome {:?}",
        over_mappings(
            &margins,
            ([0u32; MARGIN_BINS], 0u64),
            &|sum: &mut Margins, row: &Margins| {
                for (a, b) in sum.0.iter_mut().zip(&row.0) {
                    *a = a.saturating_add(*b);
                }
                sum.1 = sum.1.saturating_add(row.1);
            }
        ),
        tally(blocks)
    );
    eprintln!(
        "DUMP {name} H-26 the shadow's couplings at each mapping's end, per myriad of the image's {:?} beside the run's {:?}; its highest {:?}",
        MAPPINGS.map(|(_, to)| {
            course
                .get(to.saturating_sub(1))
                .map(|c| ALL_PAIRS.map(|(s, r)| per_myriad(c[s][r], IMAGE_COUPLINGS_1024[s][r])))
        }),
        MAPPINGS.map(|(_, to)| {
            blocks
                .get(to.saturating_sub(1))
                .map(|b| ALL_PAIRS.map(|(s, r)| per_myriad(b.10[s][r], IMAGE_COUPLINGS_1024[s][r])))
        }),
        course
            .iter()
            .enumerate()
            .flat_map(|(j, c)| ALL_PAIRS.map(|(s, r)| (
                per_myriad(c[s][r], IMAGE_COUPLINGS_1024[s][r]),
                j,
                s,
                r
            )))
            .max()
    );
    // The pinned tables of the shadow's reading, and the readings as the constants state.
    assert_eq!(
        costed.as_slice(),
        RELEASED_COSTED_1024[k],
        "{name}: the released shadow per block"
    );
    assert_eq!(
        heard.as_slice(),
        RELEASED_HEARD_1024[k],
        "{name}: the readouts' spikes per block"
    );
    assert_eq!(
        traces.as_slice(),
        RELEASED_ELIGIBLE_1024[k],
        "{name}: the eligibility at the rewards per block"
    );
    assert_eq!(
        margins.as_slice(),
        RELEASED_MARGINS_1024[k],
        "{name}: the count margins per block"
    );
    assert_eq!(
        course.as_slice(),
        RELEASED_COUPLINGS_1024[k],
        "{name}: the shadow's couplings per block"
    );
    assert_eq!(
        hash, RELEASED_HASH_1024[k],
        "{name}: every trial's reading beside the run"
    );
    assert_eq!(cost, COST_RELEASED_1024[k]);
    assert_eq!(signal, SIGNAL_RELEASED_1024[k]);
    assert_eq!(kinds, KINDS_RELEASED_1024[k]);
    assert_eq!(split, APART_RELEASED_1024[k]);
}

/// The gate's test (ADR-0061's class; brief 059): the arms, the prediction and the rule's
/// constant as ADR-0141 fixed them, and the signal as H-25's pinned tables already hold it;
/// H-26's rule at its edges and the verdict naming the mapping and the arm over tables written
/// by hand; the shadow's folds and the readings' rules over values written by hand; the shadow's
/// rule against the composer's on a run written by hand, spike by spike; and eight trials on the
/// instrument's network under the drawn delivery with the shadows beside the composer — the one
/// under the drawn address held to the composer at every trial, the same eight trials without
/// the shadows the same run, and the released one read against the run's own; then, over the
/// arms' pinned tables, the verdict as written and the tables held to one another and to H-25's
/// block by block. Nothing else added to the gate.
#[test]
fn the_rule_of_h_26_the_shadow_s_rule_and_the_readings_rules() {
    // The arms, the prediction and the rule's constant.
    assert_eq!(RELEASED_ARMS, DRAWN_ARMS);
    assert_eq!(
        RELEASED_ARMS,
        [Reversal::AssignmentFirst, Reversal::MirroredFirst]
    );
    const _: () = assert!(!RELEASED_PREDICTED, "ADR-0141 predicts no");
    const _: () = assert!(COST_TIMES == 2, "at most half the signal");
    // The signal is the run's, and H-25's pinned tables hold it already: the answer pairs' net
    // less the other pairs' per mapping, ADR-0140's table of where the consolidation went.
    for (k, &arm) in RELEASED_ARMS.iter().enumerate() {
        let signals: Vec<i64> = DRAWN_WENT_1024[k].iter().map(signal_of).collect();
        assert_eq!(
            by_mapping(&signals),
            Some(SIGNAL_RELEASED_1024[k]),
            "{arm:?}: the signal per mapping, from H-25's table"
        );
    }
    assert_eq!(
        SIGNAL_RELEASED_1024,
        [
            [
                1_963_991 + 714_225,
                2_442_666 + 2_582_144,
                2_500_849 + 2_666_083,
                3_040_807 + 2_465_583
            ],
            [
                2_272_937 + 465_352,
                2_516_134 + 2_461_151,
                2_490_753 + 2_320_682,
                2_707_446 + 2_427_736
            ]
        ],
        "ADR-0140's nets, the answer's less the other pairs'"
    );
    // H-26's rule at its edges, over tables written by hand: a run whose every mapping holds its
    // cost and its signal in its first and its last block.
    let costed_of = |cost: i64| -> Costed {
        (
            [[[0; 2]; 2], [[0; 2], [cost.max(0), cost.min(0)]]],
            [cost, 0, 0],
        )
    };
    let went_of = |signal: i64| -> Went { [[signal.max(0), signal.min(0)], [0; 2], [0; 2]] };
    let tables = |costs: [i64; 4], signals: [i64; 4]| -> (Vec<Costed>, Vec<Went>) {
        let mut costed = vec![costed_of(0); SCHEDULE_BLOCKS];
        let mut went = vec![went_of(0); SCHEDULE_BLOCKS];
        for (m, &(from, to)) in MAPPINGS.iter().enumerate() {
            // One LSB in the mapping's first block and the rest in its last, so that a sum
            // that left either block out, or took a neighbour's, reads another number.
            let last = to.saturating_sub(1);
            costed[from] = costed_of(1);
            costed[last] = costed_of(costs[m].saturating_sub(1));
            went[from] = went_of(1);
            went[last] = went_of(signals[m].saturating_sub(1));
        }
        (costed, went)
    };
    let verdict_of = |a: &(Vec<Costed>, Vec<Went>), b: &(Vec<Costed>, Vec<Went>)| {
        released([(&a.0, &a.1), (&b.0, &b.1)])
    };
    let at_half = tables([50, 60, 70, 80], [100, 120, 140, 160]);
    assert_eq!(
        verdict_of(&at_half, &at_half),
        Released {
            cost: [[50, 60, 70, 80]; 2],
            signal: [[100, 120, 140, 160]; 2],
            held: [[true; 4]; 2],
            yes: true
        },
        "a cost of exactly half the signal holds, in every mapping of both arms"
    );
    let past = tables([50, 60, 71, 80], [100, 120, 140, 160]);
    assert_eq!(
        verdict_of(&at_half, &past),
        Released {
            cost: [[50, 60, 70, 80], [50, 60, 71, 80]],
            signal: [[100, 120, 140, 160]; 2],
            held: [[true; 4], [true, true, false, true]],
            yes: false
        },
        "one LSB past half fails, in the second arm's third mapping alone"
    );
    let first_fails = tables([51, 60, 70, 80], [100, 120, 140, 160]);
    assert_eq!(
        verdict_of(&first_fails, &at_half).held,
        [[false, true, true, true], [true; 4]],
        "and in the first arm's first mapping alone"
    );
    assert!(
        affordable(3, 7) && !affordable(4, 7),
        "an odd signal: twice the cost at most the signal"
    );
    assert!(
        affordable(-1, 0) && affordable(0, 0) && !affordable(1, 0),
        "no signal affords no cost"
    );
    assert!(
        affordable(-5, 1) && affordable(-2, -4) && !affordable(-1, -4),
        "a cost below zero is a release that helps; below a signal below zero it is still read by the rule"
    );
    assert!(
        affordable(i64::MAX, i64::MAX) && !affordable(i64::MAX, i64::MAX - 1),
        "the product saturates and does not wrap"
    );
    let short = (at_half.0[1..].to_vec(), at_half.1.clone());
    assert_eq!(
        verdict_of(&at_half, &short),
        Released {
            cost: [[50, 60, 70, 80], [0; 4]],
            signal: [[100, 120, 140, 160]; 2],
            held: [[true; 4], [false; 4]],
            yes: false
        },
        "a shadow that is not whole holds nothing"
    );
    let unread = (at_half.0.clone(), at_half.1[..SCHEDULE_BLOCKS - 1].to_vec());
    assert_eq!(
        verdict_of(&unread, &at_half).held,
        [[false; 4], [true; 4]],
        "nor does a run that is not whole"
    );
    assert_eq!(by_mapping(&[1; SCHEDULE_BLOCKS]), Some([24, 32, 32, 32]));
    assert_eq!(by_mapping(&[1; SCHEDULE_BLOCKS - 1]), None);
    // The folds over values written by hand. A trial's consolidation, every amount another
    // number: `[stimulus][readout][raised, lowered]`.
    let moved: Shifted = [[[1, -2], [4, -8]], [[16, -32], [64, -128]]];
    assert_eq!(
        [
            side_of(Some(0), 0),
            side_of(Some(0), 1),
            side_of(Some(1), 0),
            side_of(Some(1), 1),
            side_of(None, 0),
            side_of(None, 1)
        ],
        [0, 1, 1, 0, 1, 1],
        "the selected readout's pairs on the run's side, the other's on the release's, both at a tie"
    );
    // Readout 1 selected under the assignment: A's answer, readout 0, was not selected, B's was.
    assert_eq!(
        shade_of(&moved, Some(1), false),
        [[[64, -128], [4, -8]], [[1, -2], [16, -32]]],
        "selected: B onto its answer and A onto the other; not selected: A onto its answer and B onto the other"
    );
    assert_eq!(
        cost_of(&shade_of(&moved, Some(1), false)),
        (16 - 32) - (1 - 2),
        "B's rise onto the other readout and A's fall from its answer are cost; the selected side enters nothing"
    );
    // The same under the mirrored mapping: the pairs change places, the sides do not.
    assert_eq!(
        shade_of(&moved, Some(1), true),
        [[[4, -8], [64, -128]], [[16, -32], [1, -2]]]
    );
    assert_eq!(
        cost_of(&shade_of(&moved, Some(1), true)),
        (1 - 2) - (16 - 32)
    );
    assert_eq!(
        shade_of(&moved, Some(0), false),
        [[[1, -2], [16, -32]], [[64, -128], [4, -8]]]
    );
    // At a tie the run addressed nothing, and the release reaches both readouts.
    assert_eq!(
        shade_of(&moved, None, false),
        [[[0; 2]; 2], [[1 + 64, -2 - 128], [4 + 16, -8 - 32]]]
    );
    assert_eq!(
        cost_of(&shade_of(&moved, None, false)),
        (4 + 16 - 8 - 32) - (1 + 64 - 2 - 128)
    );
    // The four signs of the cost, one amount each: a rise onto the other readout and a fall from
    // the answer are cost; a rise onto the answer and a fall from the other readout are not.
    let one = |pairs: usize, amount: i64| -> Shade {
        let mut shade: Shade = [[[7, -7]; 2], [[0; 2]; 2]];
        shade[1][pairs][usize::from(amount < 0)] = amount;
        shade
    };
    assert_eq!(
        [
            cost_of(&one(1, 9)),
            cost_of(&one(0, -9)),
            cost_of(&one(0, 9)),
            cost_of(&one(1, -9))
        ],
        [9, 9, -9, -9]
    );
    assert_eq!(signal_of(&[[10, -3], [5, -6], [1_000, -2_000]]), 7 + 1);
    let mut both = shade_of(&moved, Some(1), false);
    add_shade(&mut both, &shade_of(&moved, Some(0), false));
    assert_eq!(both, [[[65, -130], [20, -40]], [[65, -130], [20, -40]]]);
    // The blocks' fold: a trial's consolidation under the selection of the trial before it and
    // the mapping in force at the trial itself, entered in the trial's own block under the kind
    // of the trial before.
    let trial = |selection: Option<u8>, correct: bool, counts: [u32; 2]| -> EarnedTrial {
        (0, counts, selection, correct, 0, [[0; 2]; 2], 0, 0)
    };
    assert_eq!(
        [
            kind_of(Some(&trial(Some(0), true, [0; 2]))),
            kind_of(Some(&trial(Some(1), false, [0; 2]))),
            kind_of(Some(&trial(None, false, [0; 2]))),
            kind_of(None)
        ],
        [0, 1, 2, 2]
    );
    let trials = FLIP + BLOCK;
    let mut read = vec![trial(Some(0), true, [0; 2]); trials];
    let mut shifted: Vec<Shifted> = vec![[[[0; 2]; 2]; 2]; trials];
    // Trial 0: nothing was selected before it, so everything is on the release's side.
    shifted[0] = moved;
    // Trial 64, the second block's first: its address is trial 63's, a wrong selection of 1.
    read[BLOCK - 1] = trial(Some(1), false, [0; 2]);
    shifted[BLOCK] = moved;
    // Trial 65: its address is trial 64's, a tie.
    read[BLOCK] = trial(None, false, [0; 2]);
    shifted[BLOCK + 1] = moved;
    // The last trial before the flip and the first after it, each after a correct selection of
    // 0: the same consolidation folded under the mapping in force at each.
    shifted[FLIP - 1] = moved;
    shifted[FLIP] = moved;
    let folded = costed_blocks(&read, &shifted, false);
    assert_eq!(folded.len(), FLIP_BLOCK + 1);
    assert_eq!(
        folded[0],
        (
            shade_of(&moved, None, false),
            [0, 0, cost_of(&shade_of(&moved, None, false))]
        ),
        "before the first trial nothing was selected: a tie's kind"
    );
    let after_wrong = shade_of(&moved, Some(1), false);
    let after_tie = shade_of(&moved, None, false);
    let mut second = after_wrong;
    add_shade(&mut second, &after_tie);
    assert_eq!(
        folded[1],
        (second, [0, cost_of(&after_wrong), cost_of(&after_tie)]),
        "the second block: one trial after a wrong selection and one after a tie"
    );
    assert_eq!(
        (folded[FLIP_BLOCK - 1], folded[FLIP_BLOCK]),
        (
            (
                shade_of(&moved, Some(0), false),
                [cost_of(&shade_of(&moved, Some(0), false)), 0, 0]
            ),
            (
                shade_of(&moved, Some(0), true),
                [cost_of(&shade_of(&moved, Some(0), true)), 0, 0]
            )
        ),
        "the first trial after the flip is folded under the new mapping, its address the old one's last"
    );
    assert_ne!(
        costed_blocks(&read, &shifted, true)[0],
        folded[0],
        "the arm's first mapping decides which pairs are the answer's"
    );
    for block in &folded {
        assert_eq!(
            block.1.iter().sum::<i64>(),
            cost_of(&block.0),
            "the kinds sum to the block's cost"
        );
    }
    // The readouts' spikes, the eligibility and the margins, over trials written by hand.
    let mut heard_read = vec![trial(Some(0), true, [9, 4]); BLOCK];
    heard_read[1] = trial(Some(1), true, [2, 7]);
    heard_read[2] = trial(None, false, [5, 5]);
    let mut over_trial = vec![[20u32, 10]; BLOCK];
    over_trial[1] = [6, 30];
    over_trial[2] = [11, 12];
    // The trials that select readout 0 with the counts written first: all but those two.
    const ZEROS: u64 = (BLOCK - 2) as u64;
    assert_eq!(
        heard_blocks(&heard_read, &over_trial),
        vec![[
            [9 * ZEROS + 7, 4 * ZEROS + 2, 10],
            [20 * ZEROS + 30, 10 * ZEROS + 6, 23]
        ]],
        "each trial's counts on the side its own selection put them, a tie's together"
    );
    let mut traces = vec![[[100i64, -10], [30, -3]]; BLOCK];
    traces[1] = [[1, -2], [4, -8]];
    traces[2] = [[16, -32], [64, -128]];
    const ZEROS_I: i64 = ZEROS as i64;
    assert_eq!(
        eligible_blocks(&heard_read, &traces),
        vec![[
            [100 * ZEROS_I + 4, -10 * ZEROS_I - 8],
            [30 * ZEROS_I + 1, -3 * ZEROS_I - 2],
            [16 + 64, -32 - 128]
        ]],
        "the eligibility onto the readout each trial selected, onto the other, and at a tie onto both"
    );
    assert_eq!(
        [0u32, 1, 2, 3, 4, 5, 8, 9, u32::MAX].map(margin_bin),
        [0, 1, 2, 3, 3, 4, 4, 5, 5],
        "the bins' edges"
    );
    let mut margin_read = vec![trial(Some(0), true, [9, 4]); BLOCK];
    margin_read[0] = trial(None, false, [5, 5]);
    margin_read[1] = trial(Some(1), true, [2, 3]);
    margin_read[2] = trial(Some(1), true, [0, 2]);
    margin_read[3] = trial(Some(0), true, [7, 3]);
    margin_read[4] = trial(Some(0), true, [20, 3]);
    const FIVES: u32 = (BLOCK - 5) as u32;
    assert_eq!(
        margins_blocks(&margin_read),
        vec![([1, 1, 1, 1, FIVES, 1], (5 * FIVES + 1 + 2 + 4 + 17) as u64)],
        "a trial a bin, by the larger count less the smaller"
    );
    // The shadow's couplings: an image's plus what each block's trials consolidated.
    let mut by_trial: Vec<Shifted> = vec![[[[0; 2]; 2]; 2]; 2 * BLOCK];
    by_trial[3] = moved;
    by_trial[BLOCK + 1] = moved;
    by_trial[2 * BLOCK - 1] = moved;
    let image = [[1_000, 2_000], [3_000, 4_000]];
    assert_eq!(
        shadow_couplings(image, &by_trial),
        vec![
            [[1_000 - 1, 2_000 - 4], [3_000 - 16, 4_000 - 64]],
            [[1_000 - 3, 2_000 - 12], [3_000 - 48, 4_000 - 192]]
        ]
    );
    // The cost and the signal apart: a mapping's blocks up to its crossing, that block counted,
    // and the blocks after it; a mapping that never crossed is all the first.
    let costs: Vec<i64> = (0..SCHEDULE_BLOCKS as i64).collect();
    let signals: Vec<i64> = (1_000..1_000 + SCHEDULE_BLOCKS as i64).collect();
    let range = |from: i64, to: i64| -> (i64, i64) {
        (
            (from..to).sum::<i64>(),
            signals[from as usize..to as usize].iter().sum::<i64>(),
        )
    };
    assert_eq!(
        apart(&costs, &signals, [Some(6), Some(32), None, Some(1)]),
        [
            [range(0, 6), range(6, 24)],
            [range(24, 56), range(56, 56)],
            [range(56, 88), range(88, 88)],
            [range(88, 89), range(89, 120)]
        ]
    );
    assert_eq!(
        over_mappings(&costs, 0i64, &|sum: &mut i64, row: &i64| *sum =
            sum.saturating_add(*row)),
        [
            range(0, 24).0,
            range(24, 56).0,
            range(56, 88).0,
            range(88, 120).0
        ]
    );
    // The shadow's rule against the composer's on a run written by hand. Four units: 0, a source
    // the executor drew, and 1, one it did not, both of stimulus A's; 2, a unit of readout 0, and
    // 3, a unit of readout 1; a synapse from each source onto each, at the depression's reference
    // magnitude, never yet spiked through.
    let reference = 1i32 << DEPRESSION_REFERENCE_SHIFT;
    let wire = |source: u32, target: u32, readout: usize| Replayed {
        block_idx: 0,
        slot: 0,
        source,
        target,
        stimulus: 0,
        readout,
        delay: 100,
        magnitude: reference,
        stamp: NO_SPIKE_ON_RECORD,
        trace: 0,
    };
    let wired = vec![wire(0, 2, 0), wire(0, 3, 1), wire(1, 2, 0), wire(1, 3, 1)];
    let no_volleys = vec![Vec::new(); 4];
    // The first trial, from tick 1 000, nothing rewarded or drawn yet: each source fires, and
    // then each readout unit, ten and twenty ticks after the drawn source.
    const FIRST_START: u32 = 1_000;
    const SECOND_START: u32 = FIRST_START + TRIAL_TICKS;
    let first_spikes = vec![vec![FIRST_START], vec![1_005], vec![1_010], vec![1_020]];
    let at_rest = signal_course(0);
    let none_drawn = [false; 4];
    let first_reading = Replay {
        spikes: &first_spikes,
        volleys: &no_volleys,
        cursor: 0,
        start: FIRST_START,
        course: Some(&at_rest),
        addressed: None,
        drawn: Some(&none_drawn),
        released: false,
        baseline: 0,
        signed: true,
        global: false,
        at_rest: true,
    };
    let mut composer = wired.clone();
    let mut shadow = wired.clone();
    let quiet = advance(&mut composer, &first_reading);
    assert_eq!(
        quiet,
        advance(
            &mut shadow,
            &Replay {
                released: true,
                ..first_reading
            }
        ),
        "nothing drawn, nothing released"
    );
    assert_eq!(
        (quiet.1, quiet.2),
        ([[0; 2]; 2], [[[0; 2]; 2]; 2]),
        "a first spike pairs with nothing and consolidates nothing"
    );
    assert!(
        composer == shadow
            && composer
                .iter()
                .all(|s| s.trace == 0 && s.magnitude == reference)
            && [composer[0].stamp, composer[2].stamp] == [1_000, 1_005],
        "the stamps and nothing else"
    );
    // The second trial, under the signal a reward of 1.0 left and the address of the first:
    // readout 0 selected, source 0 drawn. Readout 1's unit fires one tick in, then source 0 at
    // the third tick and source 1 at the fourth.
    let second_spikes = vec![
        vec![FIRST_START, SECOND_START + 3],
        vec![1_005, SECOND_START + 4],
        vec![1_010],
        vec![1_020, SECOND_START + 1],
    ];
    let rewarded = signal_course(REWARD_Q16);
    let punished = signal_course(REWARD_Q16.saturating_neg());
    let drawn = [true, false, false, false];
    let reading =
        |course: &[i32], selected: Option<usize>, released: bool| -> (Advanced, Vec<Replayed>) {
            let mut synapses = composer.clone();
            let advanced = advance(
                &mut synapses,
                &Replay {
                    spikes: &second_spikes,
                    volleys: &no_volleys,
                    cursor: SECOND_START,
                    start: SECOND_START,
                    course: Some(course),
                    addressed: selected.map(|r| (0, r)),
                    drawn: Some(&drawn),
                    released,
                    baseline: 0,
                    signed: true,
                    global: false,
                    at_rest: false,
                },
            );
            (advanced, synapses)
        };
    // The traces the pair rule leaves at the drawn source's spike, by the rule's two terms: onto
    // readout 0's unit, which fired ten ticks after the source's last spike and not since, the
    // potentiation of ten ticks less the depression of the 16 377 since; onto readout 1's unit,
    // which fired two ticks before this spike, the potentiation of its 16 385 ticks after the
    // source's last less the depression of two.
    const SINCE: u32 = SECOND_START + 3 - 1_010;
    const AFTER: u32 = SECOND_START + 1 - FIRST_START;
    const _: () = assert!(SINCE == 16_377 && AFTER == 16_385);
    let onto_0 = pair_window(STDP_A_PLUS_Q1_15, 10).saturating_sub(depression_at(
        pair_window(STDP_A_MINUS_Q1_15, SINCE),
        reference,
    ));
    let onto_1 = pair_window(STDP_A_PLUS_Q1_15, AFTER)
        .saturating_sub(depression_at(pair_window(STDP_A_MINUS_Q1_15, 2), reference));
    assert!(
        onto_0 > 0 && onto_1 < 0,
        "one trace above zero and one below: {onto_0} and {onto_1}"
    );
    // Rewarded, readout 0 selected. The composer consolidates the drawn source's synapse onto
    // readout 0 and nothing else; the shadow under the drawn address is the composer; the
    // released shadow consolidates the same and, beside it, the drawn source's synapse onto
    // readout 1, the readout not selected — a trace below zero under a signal above it, so the
    // weight falls. The source not drawn consolidates under neither.
    let (run, run_synapses) = reading(&rewarded, Some(0), false);
    let (again, again_synapses) = reading(&rewarded, Some(0), false);
    let (free, free_synapses) = reading(&rewarded, Some(0), true);
    assert!(
        run == again && run_synapses == again_synapses,
        "the shadow under the drawn address is the composer's rule, number by number"
    );
    let taken_0 = consolidated_signed(onto_0, reference, rewarded[3]);
    let taken_1 = consolidated_signed(onto_1, reference, rewarded[3]);
    assert!(
        taken_0.2 > 0 && taken_1.2 < 0,
        "the rewarded consolidation raises one weight and lowers the other: {} and {}",
        taken_0.2,
        taken_1.2
    );
    assert_eq!(
        run.2,
        [[[i64::from(taken_0.2), 0], [0, 0]], [[0; 2]; 2]],
        "the run's address: the drawn source onto the selected readout"
    );
    assert_eq!(
        free.2,
        [
            [[i64::from(taken_0.2), 0], [0, i64::from(taken_1.2)]],
            [[0; 2]; 2]
        ],
        "the released targets: the same, and the drawn source onto the readout not selected"
    );
    assert_eq!(
        [
            (run_synapses[0].trace, run_synapses[0].magnitude),
            (run_synapses[1].trace, run_synapses[1].magnitude),
            (free_synapses[0].trace, free_synapses[0].magnitude),
            (free_synapses[1].trace, free_synapses[1].magnitude)
        ],
        [
            (taken_0.0, taken_0.1),
            (onto_1, reference),
            (taken_0.0, taken_0.1),
            (taken_1.0, taken_1.1)
        ],
        "each consolidation takes from its own trace into its own weight"
    );
    assert!(
        run_synapses[2..] == free_synapses[2..]
            && free_synapses[2..]
                .iter()
                .all(|s| s.magnitude == reference && s.trace != 0),
        "the source not drawn pairs and consolidates under neither address"
    );
    assert!(
        run_synapses
            .iter()
            .zip(&free_synapses)
            .all(|(a, b)| a.stamp == b.stamp),
        "the release moves no stamp"
    );
    // The cost of that trial by the rule: under the assignment readout 0 is A's answer, so the
    // fall onto readout 1 is a fall from the other readout and a cost below zero; under the
    // mirrored mapping readout 1 is A's answer and the same fall is cost.
    assert_eq!(
        [
            cost_of(&shade_of(&free.2, Some(0), false)),
            cost_of(&shade_of(&free.2, Some(0), true)),
            cost_of(&shade_of(&run.2, Some(0), false)),
            cost_of(&shade_of(&run.2, Some(0), true))
        ],
        [
            i64::from(taken_1.2),
            i64::from(taken_1.2).saturating_neg(),
            0,
            0
        ],
        "the run's own address costs nothing by the rule"
    );
    // Punished, readout 0 selected: the signed gate moves each weight against its trace, so the
    // released shadow raises the weight onto the readout not selected.
    let (run, _) = reading(&punished, Some(0), false);
    let (free, _) = reading(&punished, Some(0), true);
    let struck_0 = consolidated_signed(onto_0, reference, punished[3]);
    let struck_1 = consolidated_signed(onto_1, reference, punished[3]);
    assert!(struck_0.2 < 0 && struck_1.2 > 0);
    assert_eq!(
        (run.2, free.2),
        (
            [[[0, i64::from(struck_0.2)], [0, 0]], [[0; 2]; 2]],
            [
                [[0, i64::from(struck_0.2)], [i64::from(struck_1.2), 0]],
                [[0; 2]; 2]
            ]
        ),
        "a punishment under the signed gate, with and without the release"
    );
    // A tie: the run's address has no target and consolidates nothing; the released one reaches
    // both readouts from the drawn source.
    let (run, run_synapses) = reading(&punished, None, false);
    let (free, _) = reading(&punished, None, true);
    assert!(
        run.2 == [[[0; 2]; 2]; 2] && run_synapses.iter().all(|s| s.magnitude == reference),
        "a tie addresses nothing"
    );
    assert_eq!(
        free.2,
        [
            [[0, i64::from(struck_0.2)], [i64::from(struck_1.2), 0]],
            [[0; 2]; 2]
        ],
        "a tie, released: the drawn source onto both readouts"
    );
    assert_eq!(
        shade_of(&free.2, None, false)[0],
        [[0; 2]; 2],
        "and all of it on the release's side"
    );
    // Eight trials on the instrument's network under the drawn delivery, its image flagged and
    // carrying the critic with its window as the arms' images do, with the shadows beside the
    // composer and again without them.
    let sets = geometry(1024, ROTATION_1024);
    let p = prior(1024);
    let fresh = at_gain(&p, config(1024, 2, 0), GAIN_1024);
    let flagged = signed_image(&inhibited_image(&Image::encode(&fresh).expect("quiescent")));
    let window = shortest_delay(signed_from(&flagged, 1024).blocks()).expect("a synapse");
    let bytes = with_window_bytes(&valued_image(&flagged, VALUED_CRITIC), window);
    let run_of = |shadowed: bool| {
        let mut exec = signed_from(&bytes, 1024);
        let image = weights_of(&exec);
        let couplings = pair_couplings(&exec, &sets);
        let groups = groups_of(&exec, &sets);
        let classes = classes_of(&exec, &sets);
        let out = shadowed_run(
            &mut exec,
            Reversal::AssignmentFirst,
            &sets,
            &groups,
            &classes,
            &image,
            Delivery::Drawn,
            GATE_TRIALS,
            shadowed,
        );
        (
            out,
            couplings,
            pair_couplings(&exec, &sets),
            weights_of(&exec),
        )
    };
    let ((run, moves, values, watched, beside), couplings, couplings_after, after) = run_of(true);
    let ((bare_run, bare_moves, bare_values, bare_watched, bare_beside), _, _, bare_after) =
        run_of(false);
    assert!(bare_beside.is_none(), "no shadow, nothing beside");
    assert!(
        run == bare_run
            && moves == bare_moves
            && values == bare_values
            && watched == bare_watched
            && after == bare_after,
        "the shadows read the run and never write: the run with them is the run without"
    );
    let beside = beside.expect("the shadows' reading");
    let read = &run.3;
    eprintln!(
        "DUMP shadowed: {GATE_TRIALS} trials {read:?} run {:?} released {:?} eligible {:?} heard {:?}",
        beside.shadowed.run, beside.shadowed.released, beside.shadowed.eligible, beside.heard
    );
    assert_eq!(
        (
            beside.shadowed.run.len(),
            beside.shadowed.released.len(),
            beside.shadowed.eligible.len(),
            beside.heard.len()
        ),
        (GATE_TRIALS, GATE_TRIALS, GATE_TRIALS, GATE_TRIALS),
        "a reading beside every trial"
    );
    // The run's own consolidation is the composer's, and by the fold lies on the selected side
    // alone; a trial whose address drew no unit of a stimulus set — and the first, which has no
    // address — consolidates nothing, under the run's address or the released one.
    let none_drawn = |t: usize| watched.sourced[t][1] == 0 && watched.sourced[t][2] == 0;
    let mut diverged = false;
    for (t, (own, free)) in beside
        .shadowed
        .run
        .iter()
        .zip(&beside.shadowed.released)
        .enumerate()
    {
        let selected = t.checked_sub(1).and_then(|p| read[p].2);
        let (mine, theirs) = (
            shade_of(own, selected, false),
            shade_of(free, selected, false),
        );
        for &(s, r) in &ALL_PAIRS {
            assert_eq!(
                net_of(&own[s][r]),
                read[t].5[s][r],
                "trial {t}: the run's two sides sum to what the composer consolidated"
            );
        }
        assert_eq!(
            mine[1], [[0; 2]; 2],
            "trial {t}: the run consolidated nothing onto the readout not selected"
        );
        if t.checked_sub(1).is_none_or(none_drawn) {
            assert_eq!(
                (*own, *free),
                ([[[0; 2]; 2]; 2], [[[0; 2]; 2]; 2]),
                "trial {t}: no stimulus unit drawn, nothing consolidated"
            );
        }
        if none_drawn(t) {
            assert_eq!(
                beside.shadowed.eligible[t], [[0; 2]; 2],
                "trial {t}: no stimulus unit drawn, no eligibility from the drawn sources"
            );
        }
        // Until the release has consolidated something of its own the shadow's weights and
        // traces are the run's, so its selected side is the run's, the trial it first does so
        // included: a synapse lies on one side.
        if !diverged {
            assert_eq!(
                theirs[0], mine[0],
                "trial {t}: the release's selected side is the run's until the release diverges"
            );
        }
        diverged |= theirs[1] != [[0; 2]; 2];
        assert!(
            beside.heard[t][0] >= read[t].1[0] && beside.heard[t][1] >= read[t].1[1],
            "trial {t}: the readout window lies within the trial"
        );
    }
    assert!(
        diverged,
        "the release consolidated something onto a readout not selected in these trials"
    );
    assert!(
        beside.shadowed.eligible.iter().any(|e| *e != [[0; 2]; 2]),
        "a drawing's sources carry eligibility"
    );
    assert_eq!(
        shadow_couplings(couplings, &beside.shadowed.released),
        vec![beside.shadowed.couplings],
        "the released shadow's table sums to its own weights"
    );
    assert_eq!(
        shadow_couplings(couplings, &beside.shadowed.run),
        vec![couplings_after],
        "and the run's to the record's"
    );
    let mut other = beside.clone();
    other.heard[GATE_TRIALS - 1][1] = other.heard[GATE_TRIALS - 1][1].wrapping_add(1);
    assert_ne!(beside_hash(&beside), beside_hash(&other));
    other = beside.clone();
    other.shadowed.eligible[GATE_TRIALS - 1][0][1] =
        other.shadowed.eligible[GATE_TRIALS - 1][0][1].wrapping_sub(1);
    assert_ne!(beside_hash(&beside), beside_hash(&other));
    other = beside.clone();
    other.shadowed.released[0][1][1][0] = other.shadowed.released[0][1][1][0].wrapping_add(1);
    assert_ne!(beside_hash(&beside), beside_hash(&other));
    // Over the arms' pinned tables: the verdict as written, by the rule committed first; the
    // readings as the constants state; and, block by block over each arm's 120 blocks, H-26's
    // tables consistent with one another and with H-25's — the kinds summing to the block's
    // cost, the shadow's couplings moved by what its shade holds, the readouts' spikes in the
    // window the block's, the margins' ties the block's and their sum the selected readout's
    // count less the other's, and nothing read at a tie in a block that had none.
    let verdict = released([
        (RELEASED_COSTED_1024[0], DRAWN_WENT_1024[0]),
        (RELEASED_COSTED_1024[1], DRAWN_WENT_1024[1]),
    ]);
    assert_eq!(verdict, RELEASED_1024, "the verdict as written");
    assert_eq!(
        (verdict.cost, verdict.signal),
        (COST_RELEASED_1024, SIGNAL_RELEASED_1024)
    );
    for (k, &arm) in RELEASED_ARMS.iter().enumerate() {
        let blocks = DRAWN_BLOCKS_1024[k];
        let went = DRAWN_WENT_1024[k];
        let costed = RELEASED_COSTED_1024[k];
        let heard = RELEASED_HEARD_1024[k];
        let traces = RELEASED_ELIGIBLE_1024[k];
        let margins = RELEASED_MARGINS_1024[k];
        let course = RELEASED_COUPLINGS_1024[k];
        assert_eq!(
            [
                costed.len(),
                heard.len(),
                traces.len(),
                margins.len(),
                course.len()
            ],
            [SCHEDULE_BLOCKS; 5],
            "{arm:?}: 120 blocks of each"
        );
        assert_ne!(RELEASED_HASH_1024[k], 0);
        let costs: Vec<i64> = costed.iter().map(|c| cost_of(&c.0)).collect();
        let signals: Vec<i64> = went.iter().map(signal_of).collect();
        assert_eq!(
            over_mappings(costed, [0i64; 3], &|sum: &mut [i64; 3], row: &Costed| {
                for (a, b) in sum.iter_mut().zip(&row.1) {
                    *a = a.saturating_add(*b);
                }
            }),
            KINDS_RELEASED_1024[k],
            "{arm:?}: the cost by kind per mapping"
        );
        assert_eq!(
            apart(&costs, &signals, CROSSINGS_DRAWN_1024[k]),
            APART_RELEASED_1024[k],
            "{arm:?}: the cost and the signal apart"
        );
        for (m, parts) in APART_RELEASED_1024[k].iter().enumerate() {
            assert_eq!(
                (
                    parts[0].0.saturating_add(parts[1].0),
                    parts[0].1.saturating_add(parts[1].1)
                ),
                (COST_RELEASED_1024[k][m], SIGNAL_RELEASED_1024[k][m]),
                "{arm:?} mapping {m}: the two parts are the mapping"
            );
            assert_eq!(
                KINDS_RELEASED_1024[k][m].iter().sum::<i64>(),
                COST_RELEASED_1024[k][m],
                "{arm:?} mapping {m}: the kinds are the mapping's cost"
            );
        }
        let mut previous = IMAGE_COUPLINGS_1024;
        for (j, block) in blocks.iter().enumerate() {
            let (shade, kinds) = &costed[j];
            assert_eq!(
                kinds.iter().sum::<i64>(),
                costs[j],
                "{arm:?} block {j}: the kinds sum to the block's cost"
            );
            assert!(
                shade.iter().flatten().all(|p| p[0] >= 0 && p[1] <= 0)
                    && traces[j].iter().all(|row| row[0] >= 0 && row[1] <= 0),
                "{arm:?} block {j}: raised and lowered, above and below, each with its sign"
            );
            let moved = shade
                .iter()
                .flatten()
                .flatten()
                .fold(0i64, |sum, &a| sum.saturating_add(a));
            let total = |c: &[[i64; 2]; 2]| {
                c.iter()
                    .flatten()
                    .fold(0i64, |sum, &a| sum.saturating_add(a))
            };
            assert_eq!(
                total(&course[j]).saturating_sub(total(&previous)),
                moved,
                "{arm:?} block {j}: the shadow's couplings moved by what its shade holds"
            );
            let in_window = heard[j][0]
                .iter()
                .fold(0u64, |sum, &n| sum.saturating_add(n));
            let counted = block
                .2
                .iter()
                .flatten()
                .fold(0u64, |sum, &n| sum.saturating_add(n));
            assert_eq!(
                in_window, counted,
                "{arm:?} block {j}: the readouts' spikes in the window are the block's"
            );
            assert!(
                heard[j][1]
                    .iter()
                    .zip(&heard[j][0])
                    .all(|(trial, window)| trial >= window),
                "{arm:?} block {j}: the window lies within the trial"
            );
            assert_eq!(
                (
                    margins[j].0[0],
                    margins[j].0.iter().sum::<u32>(),
                    margins[j].1
                ),
                (
                    block.11,
                    BLOCK as u32,
                    heard[j][0][0].saturating_sub(heard[j][0][1])
                ),
                "{arm:?} block {j}: the ties, a bin a trial, and the margins the selected readout's count less the other's"
            );
            if block.11 == 0 {
                assert_eq!(
                    (heard[j][0][2], heard[j][1][2], traces[j][2]),
                    (0, 0, [0; 2]),
                    "{arm:?} block {j}: no tie, nothing read at one"
                );
            }
            previous = course[j];
        }
    }
}

// --------------------- the measurement (brief 059), its tables in inhibition/pins/h26.rs

const RELEASED_HASH_1024: [u64; 2] = [0x9466ed8c8e715027, 0xe34424a493330239];

// =================================================================================== H-27

// -------------------------------------------- written before the run (ADR-0143, ADR-0145)

/// The arms of brief 060 (ADR-0143, ADR-0145), in the order they are pinned, each its own
/// weekly test: H-27's two — the released delivery with the hold, from the assignment and from
/// the mirrored assignment — and the control's two, the released delivery alone. Each is H-25's
/// arm of the same first mapping with the delivery changed and, in H-27's, the hold set: H-23's
/// image, H-20's flips, the engine's critic with its window, the task carrying no critic.
const GATED_ARMS: [(Reversal, bool); 4] = [
    (Reversal::AssignmentFirst, true),
    (Reversal::MirroredFirst, true),
    (Reversal::AssignmentFirst, false),
    (Reversal::MirroredFirst, false),
];

/// The delivery of all four (ADR-0143, ADR-0144): the address's sources drawn by the engine as
/// under H-25, its targets every unit, at a tie as at any trial.
const GATED_DELIVERY: Delivery = Delivery::Released;

/// ADR-0143 writes no prediction for H-27's verdict: the account predicts yes, and the pair
/// rule's last spike and the response already made in the window pull the other way.
const GATED_PREDICTED: Option<bool> = None;

/// ADR-0143's prediction for the control, written first: no, on clause 1 or 3 — ADR-0142's
/// first-order reading leaves the release alone about half the signal, and a reversal has 32
/// blocks. A reading beside the verdict and never asserted.
const ALONE_PREDICTED: bool = false;

/// The hold's last tick (ADR-0143): tick $2^{12}$ of the trial, two time constants of the pair
/// rule after the trial's first tick. A message is due before a tick below it, so the last
/// lands on it at the latest.
const HOLD_UNTIL: u32 = 1 << (STDP_TAU_SHIFT + 1);

/// The tick the readout window closes at, from the trial's first: the first the hold is due at.
const HOLD_CLOSE: u32 = WINDOW.from + WINDOW.ticks;

const _: () = assert!(HOLD_CLOSE == 600 && HOLD_UNTIL == 4096 && HOLD_UNTIL < TRIAL_TICKS);

/// The span (ADR-0143): the trial's ticks from the readout window's close through tick
/// $2^{12}$, both ends counted — the tick the selection is made before, which no message of the
/// hold can reach, and the last tick one can land on. The frozen check and the readings count
/// the readouts' spikes over it.
const HOLD_SPAN: Window = Window {
    from: HOLD_CLOSE,
    ticks: HOLD_UNTIL - HOLD_CLOSE + 1,
};

const _: () = assert!(HOLD_SPAN.ticks == 3497);

/// One message of the hold: the most negative efficacy one message carries, −2.0, the cancel's
/// (ADR-0076), −3.5 after the gain of 1.75, so that the hold is counted in messages.
const HOLD_MESSAGE_Q16: i32 = CANCEL_MESSAGE_Q16;

/// The cadences the hold is derived over: the powers of two from every tick to $2^{12}$ ticks,
/// a mask on the ticks since the close as the engine's own cadences are masks on the tick
/// (ADR-0035). The longest is longer than the span: one delivery, at the close.
const HOLD_SHIFT_MAX: u32 = 12;

/// The hold's messages a time, derived by `least_hold` and not chosen: one at every tick keeps
/// the oracle's every unit silent, and none does not.
const HOLD_MESSAGES: u32 = 1;

/// The hold's cadence, derived by `least_hold` and not chosen: the longest of the lattice at
/// which one message a time keeps the oracle's every unit silent through the span of each of
/// the frozen block's sixty-four trials. At twice it a unit fires in the seventh trial.
const HOLD_EVERY: u32 = 512;

/// The hold (ADR-0143, ADR-0145): one message at the bound into every unit of the channel the
/// gate holds, before the tick the readout window closes at and before every 512th tick after
/// it below tick $2^{12}$ — seven times a trial, landing on ticks 601, 1 113, 1 625, 2 137,
/// 2 649, 3 161 and 3 673. Committed before the frozen check; it does not move after it.
const HOLD: Hold = hold_of(HOLD_MESSAGES, HOLD_EVERY);

/// The frozen check's rule (ADR-0143): over a frozen block, the spikes of the readout not
/// selected within the span at most a tenth of the selected readout's in the same span, read
/// in integers as `HOLD_CHECK_TIMES × other ≤ selected`.
const HOLD_CHECK_TIMES: u64 = 10;

// ------------------------------------------------------ the hold's oracle (ADR-0145)

/// The tick ADR-0077's settled image was written at: its lead-in's windows and the quiet run
/// after them. Every image an arm decodes carries it, and the drive is a function of the tick.
const SETTLED_TICK: u64 =
    (BACKGROUND_LEAD_IN_1024[SETTLED].len() as u64 * WINDOW_TICKS) + QUIET_1024[SETTLED].0;

const _: () = assert!(SETTLED_TICK == 12_585_412);

/// The first tick of the trial of index `trial` in a run from the settled image: the image's
/// tick, the instrument's lead-in of one readout window, and the trials before it.
fn trial_start(trial: usize) -> u64 {
    SETTLED_TICK
        .saturating_add(u64::from(LEAD_IN))
        .saturating_add((trial as u64).saturating_mul(u64::from(TRIAL_TICKS)))
}

/// The trial ticks on which a message of the drive lands on each unit, in a trial whose first
/// tick is `start`, over the ticks `from..=to`, ascending: the drive's messages due at the
/// clock's tick `start + k` are injected before trial tick `k`, reach the units
/// `Drive::unit_at` names and land on tick `k + 1` (ADR-0023), a unit named twice landing
/// twice.
fn drive_landings(units: u32, start: u64, from: u32, to: u32) -> Vec<Vec<u32>> {
    let drive = drive(units);
    let mut out = vec![Vec::new(); units as usize];
    for tick in from..=to {
        let Some(k) = tick.checked_sub(1) else {
            continue;
        };
        let at = start.saturating_add(u64::from(k));
        if !drive.is_due(at) {
            continue;
        }
        for index in 0..drive.messages {
            if let Some(list) = out.get_mut(drive.unit_at(at, index) as usize) {
                list.push(tick);
            }
        }
    }
    out
}

/// The hold's oracle (ADR-0145): `menteion-core`'s `integrate` stepped alone on one unit at the
/// base threshold, from `standing` basal and somatic potentials as the tick after the readout
/// window's close finds them, through tick `HOLD_UNTIL`. On each tick the unit takes, in one
/// batch scaled by `gain` as the executor scales a turn's sum (`scaled_q16`, `batch_q16`): the
/// drive's messages that land on it, `landings` the trial ticks they land on, ascending; and
/// `hold`'s messages when the hold was due before the tick before, so that they land on this
/// one. Returns the first tick the unit fires on; none when it is silent through the span.
/// It models no synapse, and no unit inside its refractory window at the close, whose inputs
/// the membrane rule drops: the frozen check reads the network for both.
fn held_alone(
    standing: (i32, i32),
    hold: Option<Hold>,
    landings: &[u32],
    gain: u32,
) -> Option<u32> {
    let mut unit = DendriticSuperNeuron::new(0);
    unit.v_thresh = THRESHOLD_BASE;
    unit.v_basal = standing.0;
    unit.v_soma = standing.1;
    let drive = drive(1024);
    // The landings up to the tick before the first, which the standing potentials hold.
    let mut taken = landings.partition_point(|&at| at <= HOLD_CLOSE);
    for tick in HOLD_CLOSE.saturating_add(1)..=HOLD_UNTIL {
        let through = landings.partition_point(|&at| at <= tick);
        let messages = through.saturating_sub(taken) as u32;
        taken = through;
        let mut sum = batch_q16(messages, drive.efficacy_q16);
        if let Some(h) = hold {
            if h.is_due(HOLD_CLOSE, tick.saturating_sub(1)) {
                sum = sum.saturating_add(batch_q16(h.messages, h.efficacy_q16));
            }
        }
        if unit.integrate(scaled_q16(sum, gain), 0, tick) {
            return Some(tick);
        }
    }
    None
}

/// The first unit of the readouts the oracle reads firing under `hold` over the trials
/// `trials` of a run from the settled image, as `(trial, unit, tick)`: every unit of readout 0
/// then of readout 1, each from `EXTREME_STANDING` — the most standing potential a unit carries
/// without firing (ADR-0076) — under the drive as it lands on that unit in that trial. None
/// when `hold` keeps every one of them silent through the span of every trial.
fn first_fired(hold: Option<Hold>, trials: core::ops::Range<usize>) -> Option<(usize, u32, u32)> {
    let sets = geometry(1024, ROTATION_1024);
    for trial in trials {
        let landings = drive_landings(
            1024,
            trial_start(trial),
            HOLD_CLOSE.saturating_add(1),
            HOLD_UNTIL,
        );
        for unit in sets[2].units().chain(sets[3].units()) {
            let on_unit = landings.get(unit as usize).map_or(&[][..], Vec::as_slice);
            if let Some(tick) = held_alone(EXTREME_STANDING, hold, on_unit, GAIN_1024) {
                return Some((trial, unit, tick));
            }
        }
    }
    None
}

/// The hold of `messages` messages at the bound on the cadence `every`, to the span's end.
const fn hold_of(messages: u32, every: u32) -> Hold {
    Hold {
        until: HOLD_UNTIL,
        every,
        messages,
        efficacy_q16: HOLD_MESSAGE_Q16,
    }
}

/// The least hold over `trials` (ADR-0143, ADR-0145), by the oracle: the least messages a
/// time, at the bound, with which the densest cadence — every tick — keeps every unit silent
/// through every span; then, at that count, the longest cadence of `HOLD_SHIFT_MAX`'s lattice
/// that still does, the fewest ticks. None when no count up to `LEAST_SCAN` silences at every
/// tick. The cadences nest — a cadence's ticks are among those of every shorter one — and the
/// membrane's rule is monotone in its input while the unit does not fire, so a cadence that
/// silences is silenced by every shorter one.
fn least_hold(trials: core::ops::Range<usize>) -> Option<Hold> {
    let messages =
        (1..=LEAST_SCAN).find(|&m| first_fired(Some(hold_of(m, 1)), trials.clone()).is_none())?;
    (0..=HOLD_SHIFT_MAX)
        .rev()
        .map(|shift| hold_of(messages, 1u32 << shift))
        .find(|&hold| first_fired(Some(hold), trials.clone()).is_none())
}

// ------------------------------------------------------------ the criterion (ADR-0143)

/// Brief 060's two verdicts (ADR-0143), each H-25's four clauses as `drawn` reads them over two
/// arms `[assignment first, mirrored first]`: H-27's, over the arms with the hold, and the
/// control's, over the arms with the release alone.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct Gated {
    held: Drawn,
    alone: Drawn,
}

fn gated(image: i64, arms: [&[Block]; 4]) -> Gated {
    Gated {
        held: drawn(image, [arms[0], arms[1]]),
        alone: drawn(image, [arms[2], arms[3]]),
    }
}

/// The step of H-27's stopping rule a verdict reaches (ADR-0143): 3 at a yes; 4 at a no on
/// clause 4, the network not held in an arm, whatever else failed; otherwise 5, a no on clause
/// 1, 2 or 3.
fn step_of(verdict: &Drawn) -> u8 {
    match (verdict.yes, verdict.held) {
        (true, _) => 3,
        (false, [true, true]) => 5,
        (false, _) => 4,
    }
}

// ----------------------------------------------------- the readings' shape (brief 060)

/// One trial's spikes of the two readout sets by where they fell (brief 060), `[in the readout
/// window, within the span, over the whole trial][readout 0, readout 1]`.
type Fired = [[u32; 2]; 3];

/// The readouts' spikes over a block (brief 060), `[in the readout window, within the span,
/// over the whole trial][the selected readout's, the other's, both readouts' at a tie]`: each
/// trial's counts summed on the side its own selection put them, a tie's two counts together —
/// `Heard` with the span between its two rows.
type Quieted = [[u64; 3]; 3];

fn quieted_blocks(selections: &[Option<u8>], fired: &[Fired]) -> Vec<Quieted> {
    assert_eq!(selections.len(), fired.len(), "a count a trial");
    selections
        .chunks(BLOCK)
        .zip(fired.chunks(BLOCK))
        .map(|(selected, trials)| {
            let mut out: Quieted = [[0; 3]; 3];
            for (selection, counts) in selected.iter().zip(trials) {
                for (row, pair) in out.iter_mut().zip(counts) {
                    match selection {
                        Some(r) => {
                            let r = usize::from(*r);
                            row[0] = row[0].saturating_add(u64::from(pair[r]));
                            row[1] = row[1].saturating_add(u64::from(pair[r ^ 1]));
                        }
                        None => {
                            row[2] = row[2]
                                .saturating_add(u64::from(pair[0]))
                                .saturating_add(u64::from(pair[1]));
                        }
                    }
                }
            }
            out
        })
        .collect()
}

/// A `Quieted` plus another, count by count.
fn add_quieted(into: &mut Quieted, quieted: &Quieted) {
    for (a, b) in into.iter_mut().flatten().zip(quieted.iter().flatten()) {
        *a = a.saturating_add(*b);
    }
}

/// The frozen check's rule over a block (ADR-0143): the readout not selected fired, within the
/// span, at most a tenth of what the selected readout fired there.
fn hold_checked(quieted: &Quieted) -> bool {
    quieted[1][1].saturating_mul(HOLD_CHECK_TIMES) <= quieted[1][0]
}

/// The side of the address in force the run's own consolidation fell on, per mapping (brief
/// 060): the selected side's signal — its answer pairs' net less its other pairs' — and the
/// cost on the side not selected, `cost_of`; the first less the second is the run's whole
/// signal, `signal_of` of the network's oracle's `Went`.
fn selected_signal(shade: &Shade) -> i64 {
    net_of(&shade[0][0]).saturating_sub(net_of(&shade[0][1]))
}

/// What an arm of brief 060 pins beside its tables: H-25's readings by their rules, and brief
/// 060's per mapping — the cost on the side not selected, the selected side's signal, the
/// run's whole signal by the network's oracle, the cost by the kind of the trial the address
/// was written at, and the hold's messages.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct GatedRead {
    correct: [u32; 4],
    over: Option<(usize, usize, usize)>,
    crossings: [Option<usize>; 4],
    left: Option<(usize, i64)>,
    stimulus_values: [[StimulusValue; 2]; 4],
    reach: Reach,
    first_new: [[Option<usize>; 2]; 3],
    crossed: [[Option<usize>; 2]; 3],
    tally: [[u32; 3]; 4],
    settle: Option<[[i64; 2]; 4]>,
    highest: [Option<Peak>; 4],
    strong: [[u32; 2]; 3],
    punished: [Moves; 4],
    rewarded: [Moves; 4],
    once: u32,
    falls: bool,
    troughs: [[i64; 2]; 3],
    sums_after: (i64, i64),
    cost: [i64; 4],
    selected: [i64; 4],
    signal: [i64; 4],
    kinds: [[i64; 3]; 4],
    held: [u64; 4],
}

/// Every trial's reading beside the run, hashed (brief 060): `fnv1a_64` over each trial's
/// consolidation by stimulus, readout and direction, its eligibility from the drawn sources,
/// its readouts' spikes within the span and over the trial, and the hold's messages, each
/// number as its `i32` words.
fn along_hash(along: &Along) -> u64 {
    let mut words: Vec<i32> = Vec::new();
    let mut wide = |x: i64| {
        words.push(x as i32);
        words.push((x >> 32) as i32);
    };
    for (t, moved) in along.held.shifted.iter().enumerate() {
        for &amount in moved.iter().flatten().flatten() {
            wide(amount);
        }
        for &trace in along.held.eligible.get(t).into_iter().flatten().flatten() {
            wide(trace);
        }
        for &count in along
            .spanned
            .get(t)
            .into_iter()
            .chain(along.heard.get(t))
            .flatten()
        {
            wide(i64::from(count));
        }
        wide(i64::from(along.held.held.get(t).copied().unwrap_or(0)));
    }
    fnv1a_64(&words)
}

// ----------------------------------------------------- the calibration (brief 060)

/// One trial's reading of a frozen block: the selection and where the readouts' spikes fell.
type FrozenTrial = (Option<u8>, Fired);

/// A frozen block's reading (brief 060): the sight's block and its accuracy sequence's hash,
/// the readouts' spikes by where they fell, the hold's messages, and every trial's reading by
/// one hash.
type FrozenHeld = (Block, u64, Quieted, u64, u64);

/// Every trial's reading of a frozen block, hashed.
fn frozen_hash(read: &[FrozenTrial]) -> u64 {
    let words: Vec<i32> = read
        .iter()
        .flat_map(|(selection, fired)| {
            core::iter::once(i32::from(selection.map_or(3, |r| r))).chain(
                fired
                    .iter()
                    .flatten()
                    .map(|&n| i32::try_from(n).unwrap_or(i32::MAX)),
            )
        })
        .collect();
    fnv1a_64(&words)
}

/// A frozen block from the zero image under `hold` or none (ADR-0143's calibration): ADR-0077's
/// frozen run — the settled network with the baseline at zero, the reward withheld, ADR-0076's
/// stimulus, sixty-four trials — with the task carrying the hold, the readouts' spikes read
/// from the train within the span and over the trial at every trial's end, the hold's messages
/// held to its times, and no weight of either polarity moved. With no hold the block and its
/// sequence are ADR-0077's, which the caller holds.
fn frozen_held(zero: &[u8], hold: Option<Hold>) -> (FrozenHeld, Vec<FrozenTrial>) {
    let mut exec = frozen_from(zero, 1024);
    assert_eq!(exec.ticks(), SETTLED_TICK, "the image's tick, the oracle's");
    let sums = weights_by_polarity(&exec);
    let sets = geometry(1024, ROTATION_1024);
    let readouts = Readout::new([sets[2], sets[3]]);
    let picked = CANCEL_PICKED_1024.expect("ADR-0076 picked a cancel");
    let task = Task {
        hold,
        ..task(
            SHAPE_F46,
            Some(cancel_of(picked)),
            1024,
            Feedback::Withheld,
            false,
            Delivery::Addressed,
        )
    };
    let mut read: Vec<FrozenTrial> = Vec::with_capacity(BLOCK);
    let mut messages = 0u64;
    let (blocks, trace) = run_on(
        &mut exec,
        task,
        1024,
        BLOCK,
        &mut |exec, trial, start, outcome| {
            assert_eq!(
                u64::from(start),
                trial_start(trial),
                "trial {trial}: the first tick the oracle read the drive at"
            );
            let due = match (hold, outcome.selection) {
                (Some(h), Some(r)) => u64::from(hold_times(&h, HOLD_CLOSE))
                    .saturating_mul(u64::from(h.messages))
                    .saturating_mul(readout_set(&sets, usize::from(r ^ 1)).len()),
                _ => 0,
            };
            assert_eq!(
                u64::from(outcome.held),
                due,
                "trial {trial}: the hold's messages"
            );
            messages = messages.saturating_add(due);
            let within = readouts.count_window(
                exec.train(),
                start.wrapping_add(HOLD_SPAN.from),
                HOLD_SPAN.ticks,
            );
            let over = readouts.count_window(exec.train(), start, TRIAL_TICKS);
            read.push((outcome.selection, [outcome.counts, within, over]));
        },
    );
    let [block] = blocks.as_slice() else {
        panic!("a block of sixty-four trials");
    };
    assert_eq!(
        (block.7, block.8),
        sums,
        "no weight moves at a modulation of zero"
    );
    let selections: Vec<Option<u8>> = read.iter().map(|t| t.0).collect();
    let fired: Vec<Fired> = read.iter().map(|t| t.1).collect();
    let [quieted] = quieted_blocks(&selections, &fired)[..] else {
        panic!("one block of readings");
    };
    ((*block, trace, quieted, messages, frozen_hash(&read)), read)
}

/// The hold's calibration (H-27's stopping rule, step 2; brief 060), before any rewarded run:
/// the hold held to the rule that derived it over the whole frozen block; the frozen block
/// with no hold, ADR-0077's bit for bit; then the same block with the hold, read by the frozen
/// check's rule. Everything is dumped before the rule is asserted, so that a schedule that
/// fails still shows its reading: the round stops there, as a finding.
fn hold_calibration(name: &str, zero: &[u8]) {
    let least = least_hold(0..BLOCK);
    eprintln!("DUMP {name} the least hold by the oracle over the frozen block: {least:?}");
    assert_eq!(
        least,
        Some(HOLD),
        "{name}: the hold is the least the oracle derives"
    );
    let (bare, bare_read) = frozen_held(zero, None);
    let (held, held_read) = frozen_held(zero, Some(HOLD));
    eprintln!("DUMP {name} PIN frozen-bare {:?}", (bare.2, bare.4));
    eprintln!("DUMP {name} PIN frozen-held {held:?}");
    eprintln!("DUMP {name} frozen block with no hold {bare:?} trials {bare_read:?}");
    eprintln!("DUMP {name} frozen block with the hold, trials {held_read:?}");
    eprintln!(
        "DUMP {name} the frozen check: within the span the readout not selected fired {} and the selected {} with the hold, {} and {} without it; at most a tenth: {}",
        held.2[1][1],
        held.2[1][0],
        bare.2[1][1],
        bare.2[1][0],
        hold_checked(&held.2)
    );
    assert_eq!(
        (bare.0, bare.1, bare.3),
        (BACKGROUND_1024[SETTLED].0, BACKGROUND_1024[SETTLED].1, 0),
        "{name}: with no hold the frozen block is ADR-0077's"
    );
    assert!(
        hold_checked(&held.2),
        "{name}: the schedule fails its frozen check, and the round stops here as a finding"
    );
    assert_eq!(
        Some((bare.2, bare.4)),
        BARE_FROZEN_1024,
        "{name}: the frozen block's spans with no hold"
    );
    assert_eq!(
        Some(held),
        HELD_FROZEN_1024,
        "{name}: the frozen block with the hold"
    );
}

/// H-25's first block from H-23's image under the drawn delivery (H-27's stopping rule, step
/// 2): H-25's run for one block held to H-25's pinned first block table by table, with the
/// network's oracle replayed beside it and held to the record at every trial.
fn drawn_first_block(windowed: &[u8], arm: Reversal, name: &str) {
    let k = DRAWN_ARMS
        .iter()
        .position(|&a| a == arm)
        .expect("an arm of H-25");
    let mut exec = signed_from(windowed, 1024);
    let sets = geometry(1024, ROTATION_1024);
    let groups = groups_of(&exec, &sets);
    let classes = classes_of(&exec, &sets);
    let image = weights_of(&exec);
    let (run, moves, values, watched) = delivered_run(
        &mut exec,
        arm,
        &sets,
        &groups,
        &classes,
        &image,
        Delivery::Drawn,
        BLOCK,
    );
    let (blocks, _, trials, read, _) = &run;
    let compositions: Vec<Composition> = trials.chunks(BLOCK).map(composition).collect();
    let earned = earned_blocks(read);
    let by_block = value_blocks(read, &values);
    let admitted = admitted_blocks(read, &watched.admitted);
    let sourced: Vec<Sourced> = admitted_blocks(read, &watched.sourced);
    eprintln!(
        "DUMP {name} H-25's first block {blocks:?} earned {earned:?} values {by_block:?} sourced {sourced:?} went {:?}",
        watched.went
    );
    assert_eq!(blocks.as_slice(), &DRAWN_BLOCKS_1024[k][..1], "{name}");
    assert_eq!(
        compositions.as_slice(),
        &DRAWN_COMPOSITIONS_1024[k][..1],
        "{name}"
    );
    assert_eq!(earned.as_slice(), &DRAWN_EARNED_1024[k][..1], "{name}");
    assert_eq!(
        moves_blocks(read, &moves).as_slice(),
        &DRAWN_MOVES_1024[k][..1],
        "{name}"
    );
    assert_eq!(by_block.as_slice(), &DRAWN_VALUES_1024[k][..1], "{name}");
    assert_eq!(
        watched.weights.as_slice(),
        &DRAWN_WEIGHTS_1024[k][..1],
        "{name}"
    );
    assert_eq!(admitted.as_slice(), &DRAWN_ADMITTED_1024[k][..1], "{name}");
    assert_eq!(
        watched.spikes.as_slice(),
        &DRAWN_SPIKES_1024[k][..1],
        "{name}"
    );
    assert_eq!(
        watched.cells.as_slice(),
        &DRAWN_CELLS_1024[k][..1],
        "{name}"
    );
    assert_eq!(watched.went.as_slice(), &DRAWN_WENT_1024[k][..1], "{name}");
    assert_eq!(sourced.as_slice(), &DRAWN_SOURCED_1024[k][..1], "{name}");
}

// ---------------------------------------------------------------- the run (brief 060)

/// One arm of brief 060 at 1 024 units: the calibration before any rewarded run (H-27's
/// stopping rule, step 2) — the settled engine held to ADR-0077 step by step and its images,
/// H-20's to H-23's images by their CRCs, a frozen block from the zero image held to ADR-0077's
/// frozen run, H-25's first block from H-23's image under the drawn delivery reproduced table
/// by table, and, in an arm with the hold, the hold's own calibration and its frozen check —
/// then the arm's 7 680 trials from H-23's image under the released delivery, with the hold or
/// without it, the drawn sources held to the critic's oracle's counts, every unit a target,
/// the hold's messages held to its times, and both oracles held to the record at every trial;
/// everything dumped, the clauses and the readings computed before anything is held; then the
/// pinned tables of the whole run.
fn gated_arm(arm: Reversal, hold: bool) {
    let k = GATED_ARMS
        .iter()
        .position(|&a| a == (arm, hold))
        .expect("an arm of brief 060");
    let name = format!("gated1024 {arm:?} {}", if hold { "held" } else { "alone" });
    let (zero, signed) = signed_images(&name);
    assert_eq!(
        pinned_crc(&signed),
        PUNISHED_IMAGE_CRC_1024,
        "{name}: H-20's image, H-19's and H-18's"
    );
    {
        let mut frozen = frozen_from(&zero, 1024);
        assert_eq!(
            (frozen.inhibitory_baseline_q16(), frozen.signed_gate()),
            (None, false),
            "{name}: the calibration's image leaves the inhibitory baseline and the signed gate unset"
        );
        let calibration = taught_run(&mut frozen, Arm::Withheld, 1024, BLOCK);
        calibration_holds(&format!("{name} calibration"), &calibration);
    }
    let targeted = targeted_image(&signed, TARGET_PERIOD_1024);
    assert!(
        only_the_target(&signed, &targeted),
        "{name}: H-21's image is H-20's in every byte but the target period's and the seal"
    );
    assert_eq!(
        pinned_crc(&targeted),
        TARGET_IMAGE_CRC_1024,
        "{name}: H-21's image"
    );
    let valued = valued_image(&targeted, VALUED_CRITIC);
    assert!(
        only_the_critic(&targeted, &valued),
        "{name}: H-22's image is H-21's in every byte but the critic's and the seal"
    );
    assert_eq!(
        pinned_crc(&valued),
        VALUED_IMAGE_CRC_1024,
        "{name}: H-22's image"
    );
    let windowed = with_window_bytes(&valued, WINDOW_TICKS_1024);
    assert!(
        only_the_window(&valued, &windowed),
        "{name}: H-23's image is H-22's in every byte but the window's and the seal"
    );
    assert_eq!(
        pinned_crc(&windowed),
        WINDOWED_IMAGE_CRC_1024,
        "{name}: H-23's image, the image this arm decodes"
    );
    drawn_first_block(&windowed, arm, &name);
    if hold {
        hold_calibration(&name, &zero);
    }
    eprintln!(
        "DUMP {name} calibration holds: ADR-0077's settled candidate, H-20's to H-23's images, H-25's first block under the drawn address{}",
        if hold {
            ", and the hold's frozen check"
        } else {
            ""
        }
    );
    let sets = geometry(1024, ROTATION_1024);
    let mut exec = signed_from(&windowed, 1024);
    assert_eq!(
        (
            exec.critic(),
            exec.critic_window_ticks(),
            exec.istdp_target_period_ticks(),
            exec.window_opened(),
            exec.draws(),
            exec.ticks()
        ),
        (
            Some(VALUED_CRITIC),
            WINDOW_TICKS_1024,
            TARGET_PERIOD_1024,
            exec.ticks(),
            Ok(()),
            SETTLED_TICK
        ),
        "{name}: H-23's configuration, the window open at the load, and the engine draws"
    );
    assert!(
        exec.units().iter().all(|u| u.value_weight == 0) && exec.features().iter().all(|&c| c == 0),
        "{name}: every weight and every count zero"
    );
    let image_sums = QUIET_1024[SETTLED].1;
    assert_eq!(
        weights_by_polarity(&exec),
        image_sums,
        "{name}: the image's sums"
    );
    assert_eq!(
        pair_couplings(&exec, &sets),
        IMAGE_COUPLINGS_1024,
        "{name}: the same image"
    );
    let groups = groups_of(&exec, &sets);
    let sizes = group_sizes(&groups);
    let classes = classes_of(&exec, &sets);
    let image = weights_of(&exec);
    let image_cells = cells_of(&exec, &image, &sets, &classes);
    let outside = image_outside();
    assert_eq!(
        (image_cells, cell_sizes(&exec, &sets, &classes)),
        (IMAGE_CELLS_1024, CELL_SIZES_1024),
        "{name}: H-24's image cells"
    );
    let first = first_mapping(arm);
    let ((run, moves, values, watched, beside), along) = held_run(
        &mut exec,
        arm,
        &sets,
        &groups,
        &classes,
        &image,
        GATED_DELIVERY,
        SCHEDULE_TRIALS,
        false,
        hold.then_some(HOLD),
    );
    assert!(beside.is_none(), "{name}: no shadow beside the run");
    let (blocks, trace, trials, read, volley_ticks) = &run;
    let earned = earned_blocks(read);
    let compositions: Vec<Composition> = trials.chunks(BLOCK).map(composition).collect();
    let moved = moves_blocks(read, &moves);
    let strong = strong_scheduled(read, first);
    let valued_by_block = value_blocks(read, &values);
    let admitted = admitted_blocks(read, &watched.admitted);
    let sourced: Vec<Sourced> = admitted_blocks(read, &watched.sourced);
    let at_flips = watched
        .at_flips
        .map(|c| c.expect("the run reached the trial after every flip"));
    assert_eq!(blocks.len(), SCHEDULE_BLOCKS, "{name}: 120 blocks");
    assert_eq!(
        [
            read.len(),
            values.len(),
            watched.admitted.len(),
            watched.sourced.len(),
            along.held.shifted.len(),
            along.held.eligible.len(),
            along.held.held.len(),
            along.spanned.len(),
            along.heard.len()
        ],
        [SCHEDULE_TRIALS; 9],
        "{name}: a reading a trial"
    );
    // Brief 060's tables: the run's own consolidation folded by the address in force, the
    // readouts' spikes by where they fell, the eligibility at the rewards, the count margins
    // and the hold's messages, per block.
    let costed = costed_blocks(read, &along.held.shifted, first);
    let selections: Vec<Option<u8>> = read.iter().map(|t| t.2).collect();
    let fired: Vec<Fired> = read
        .iter()
        .zip(along.spanned.iter().zip(&along.heard))
        .map(|(t, (within, over))| [t.1, *within, *over])
        .collect();
    let quieted = quieted_blocks(&selections, &fired);
    let traces = eligible_blocks(read, &along.held.eligible);
    let margins = margins_blocks(read);
    let messages: Vec<u64> = along
        .held
        .held
        .chunks(BLOCK)
        .map(|block| {
            block
                .iter()
                .fold(0u64, |sum, &n| sum.saturating_add(u64::from(n)))
        })
        .collect();
    let hash = along_hash(&along);
    assert_eq!(
        [
            compositions.len(),
            earned.len(),
            moved.len(),
            valued_by_block.len(),
            watched.weights.len(),
            admitted.len(),
            watched.spikes.len(),
            watched.cells.len(),
            watched.went.len(),
            sourced.len(),
            costed.len(),
            quieted.len(),
            traces.len(),
            margins.len(),
            messages.len()
        ],
        [SCHEDULE_BLOCKS; 15]
    );
    assert_eq!(strong.len(), SCHEDULE_BLOCKS - FLIP_BLOCK);
    // The run's tables dumped whole, as they are pinned, before anything is held or read.
    eprintln!("DUMP {name} PIN blocks {blocks:?}");
    eprintln!("DUMP {name} PIN trace {trace:#018x}");
    eprintln!("DUMP {name} PIN compositions {compositions:?}");
    eprintln!("DUMP {name} PIN earned {earned:?}");
    eprintln!("DUMP {name} PIN read {:#018x}", earned_hash(read));
    eprintln!("DUMP {name} PIN census {:?}", census_of(volley_ticks));
    eprintln!("DUMP {name} PIN moves {moved:?}");
    eprintln!("DUMP {name} PIN strong {strong:?}");
    eprintln!("DUMP {name} PIN at flips {at_flips:?}");
    eprintln!("DUMP {name} PIN values {valued_by_block:?}");
    eprintln!("DUMP {name} PIN value hash {:#018x}", values_hash(&values));
    eprintln!("DUMP {name} PIN weights {:?}", watched.weights);
    eprintln!("DUMP {name} PIN admitted {admitted:?}");
    eprintln!("DUMP {name} PIN spikes {:?}", watched.spikes);
    eprintln!("DUMP {name} PIN cells {:?}", watched.cells);
    eprintln!("DUMP {name} PIN went {:?}", watched.went);
    eprintln!("DUMP {name} PIN sourced {sourced:?}");
    eprintln!(
        "DUMP {name} PIN sources hash {:#018x}",
        sources_hash(&watched.sourced)
    );
    eprintln!("DUMP {name} PIN costed {costed:?}");
    eprintln!("DUMP {name} PIN quieted {quieted:?}");
    eprintln!("DUMP {name} PIN eligible {traces:?}");
    eprintln!("DUMP {name} PIN margins {margins:?}");
    eprintln!("DUMP {name} PIN messages {messages:?}");
    eprintln!("DUMP {name} PIN along hash {hash:#018x}");
    // Everything read and dumped, and the clauses and the readings computed, before anything
    // else is held.
    dump_earned(&name, &run, &earned);
    let costs: Vec<i64> = costed.iter().map(|c| cost_of(&c.0)).collect();
    let selected_side: Vec<i64> = costed.iter().map(|c| selected_signal(&c.0)).collect();
    let signals: Vec<i64> = watched.went.iter().map(signal_of).collect();
    let stimulus_read = stimulus_values(read, &values);
    let crossings_read = crossings(blocks);
    let read_of_arm = GatedRead {
        correct: mapping_correct(blocks),
        over: first_over(blocks),
        crossings: crossings_read,
        left: left_band(outside, blocks),
        stimulus_values: stimulus_read,
        reach: reach_by_polarity(&exec, &image, 1024, &ALL_PAIRS),
        first_new: first_new_scheduled(read, first),
        crossed: crossed_scheduled(&earned, first),
        tally: tally(blocks),
        settle: settle_scheduled(blocks, first),
        highest: highest(blocks),
        strong: strong_by_flip(&strong),
        punished: moves_by_mapping(&moved, 1),
        rewarded: moves_by_mapping(&moved, 0),
        once: once_blocks(blocks, &compositions),
        falls: falls_every_block(image_sums.0, blocks),
        troughs: troughs(&value_means(&valued_by_block)),
        sums_after: weights_by_polarity(&exec),
        cost: by_mapping(&costs).expect("a run of 120 blocks"),
        selected: by_mapping(&selected_side).expect("a run of 120 blocks"),
        signal: by_mapping(&signals).expect("a run of 120 blocks"),
        kinds: over_mappings(&costed, [0i64; 3], &|sum: &mut [i64; 3], row: &Costed| {
            for (a, b) in sum.iter_mut().zip(&row.1) {
                *a = a.saturating_add(*b);
            }
        }),
        held: over_mappings(&messages, 0u64, &|sum: &mut u64, row: &u64| {
            *sum = sum.saturating_add(*row);
        }),
    };
    eprintln!("DUMP {name} PIN readings {read_of_arm:?}");
    let revised = reversals_within(crossings_read);
    eprintln!(
        "DUMP {name} verdict of this arm: learned {:?} over {:?} revised {revised:?} held {} left {:?}; readings: value within a quarter of 2p − 1 {:?}; the prediction for H-27 {GATED_PREDICTED:?} and for the control {ALONE_PREDICTED}",
        read_of_arm.correct.map(|c| c >= REWARDED_MIN),
        read_of_arm.over,
        read_of_arm.left.is_none(),
        read_of_arm.left,
        stimulus_read.map(|m| m.map(holds_expected))
    );
    let host: Vec<[[u32; 3]; 2]> = blocks
        .iter()
        .zip(&sourced)
        .map(|(b, s)| beside_host(b, s, &sizes))
        .collect();
    eprintln!(
        "DUMP {name} the drawn sources beside the host's per block, [A, B] of [drawn, left out, others]: {host:?}; group sizes {sizes:?}"
    );
    eprintln!(
        "DUMP {name} outside course, per myriad of the image's {:?}",
        blocks
            .iter()
            .map(|b| per_myriad(outside_of(b), outside))
            .collect::<Vec<i64>>()
    );
    let h25 = DRAWN_ARMS
        .iter()
        .position(|&a| a == arm)
        .expect("an arm of H-25");
    eprintln!(
        "DUMP {name} couplings course {:?} beside H-25's {:?}",
        couplings_course(blocks),
        couplings_course(DRAWN_BLOCKS_1024[h25])
    );
    eprintln!(
        "DUMP {name} crossings {crossings_read:?} beside H-25's {:?}",
        CROSSINGS_DRAWN_1024[h25]
    );
    eprintln!(
        "DUMP {name} value by block beside H-25's {:?}",
        value_means(&valued_by_block)
            .iter()
            .zip(value_means(DRAWN_VALUES_1024[h25]))
            .map(|(u, w)| (*u, w))
            .collect::<Vec<_>>()
    );
    eprintln!(
        "DUMP {name} inhibitory course {:?} beside H-25's {:?}",
        course(image_sums.0, blocks),
        course(image_sums.0, DRAWN_BLOCKS_1024[h25])
    );
    eprintln!(
        "DUMP {name} cost per block {costs:?} selected side's signal per block {selected_side:?} whole signal per block {signals:?}"
    );
    eprintln!(
        "DUMP {name} shade by mapping, [selected, not selected][answer's pairs, other pairs][raised, lowered]: {:?}",
        over_mappings(
            &costed,
            [[[0i64; 2]; 2]; 2],
            &|sum: &mut Shade, row: &Costed| add_shade(sum, &row.0)
        )
    );
    eprintln!(
        "DUMP {name} readouts' spikes by mapping, [window, span, trial][selected, other, at ties]: {:?} beside H-25's [window, trial] {:?}",
        over_mappings(
            &quieted,
            [[0u64; 3]; 3],
            &|sum: &mut Quieted, row: &Quieted| { add_quieted(sum, row) }
        ),
        over_mappings(
            RELEASED_HEARD_1024[h25],
            [[0u64; 3]; 2],
            &|sum: &mut Heard, row: &Heard| {
                for (a, b) in sum.iter_mut().flatten().zip(row.iter().flatten()) {
                    *a = a.saturating_add(*b);
                }
            }
        )
    );
    let eligible_sum = |sum: &mut Eligible, row: &Eligible| {
        for (a, b) in sum.iter_mut().flatten().zip(row.iter().flatten()) {
            *a = a.saturating_add(*b);
        }
    };
    eprintln!(
        "DUMP {name} eligibility at the rewards by mapping, [selected, other, at ties][above zero, below zero]: {:?} beside H-25's {:?}",
        over_mappings(&traces, [[0i64; 2]; 3], &eligible_sum),
        over_mappings(RELEASED_ELIGIBLE_1024[h25], [[0i64; 2]; 3], &eligible_sum)
    );
    eprintln!(
        "DUMP {name} spikes by class by mapping {:?} beside H-25's {:?}",
        over_mappings(
            &watched.spikes,
            [0u64; CLASSES],
            &|sum: &mut [u64; CLASSES], row: &[u64; CLASSES]| {
                for (a, b) in sum.iter_mut().zip(row) {
                    *a = a.saturating_add(*b);
                }
            }
        ),
        over_mappings(
            DRAWN_SPIKES_1024[h25],
            [0u64; CLASSES],
            &|sum: &mut [u64; CLASSES], row: &[u64; CLASSES]| {
                for (a, b) in sum.iter_mut().zip(row) {
                    *a = a.saturating_add(*b);
                }
            }
        )
    );
    eprintln!(
        "DUMP {name} signal {:?}",
        blocks.iter().map(|b| b.9).collect::<Vec<i32>>()
    );
    // The composer's fold is the network's oracle's, block by block: both sides of the address
    // in force together are what the oracle read in the answer's pairs and in the other pairs,
    // direction by direction.
    for (j, (mine, oracle)) in costed.iter().zip(&watched.went).enumerate() {
        let both = [0usize, 1].map(|pairs| {
            [0usize, 1].map(|d| mine.0[0][pairs][d].saturating_add(mine.0[1][pairs][d]))
        });
        assert_eq!(
            both,
            [oracle[0], oracle[1]],
            "{name} block {j}: the composer's fold is the network's oracle's"
        );
    }
    // The pinned tables of the whole run, and the readings as the constants state.
    pinned(
        &format!("{name} sight"),
        blocks,
        *trace,
        GATED_BLOCKS_1024[k],
        GATED_TRACES_1024[k],
    );
    assert_eq!(
        compositions.as_slice(),
        GATED_COMPOSITIONS_1024[k],
        "{name}: the composition per block"
    );
    assert_eq!(
        earned.as_slice(),
        GATED_EARNED_1024[k],
        "{name}: the earned blocks"
    );
    assert_eq!(
        earned_hash(read),
        GATED_READ_1024[k],
        "{name}: the readings"
    );
    assert_eq!(
        census_of(volley_ticks),
        GATED_CENSUS_1024[k].to_vec(),
        "{name}: the volley's ticks"
    );
    assert_eq!(
        moved.as_slice(),
        GATED_MOVES_1024[k],
        "{name}: the moves per block"
    );
    assert_eq!(
        strong.as_slice(),
        GATED_STRONG_1024[k],
        "{name}: the strong punishments per block"
    );
    assert_eq!(Some(at_flips), GATED_AT_FLIPS_1024[k]);
    assert_eq!(
        valued_by_block.as_slice(),
        GATED_VALUES_1024[k],
        "{name}: the engine's value per block"
    );
    assert_eq!(
        values_hash(&values),
        GATED_VALUE_HASH_1024[k],
        "{name}: every trial's value"
    );
    assert_eq!(
        watched.weights.as_slice(),
        GATED_WEIGHTS_1024[k],
        "{name}: the weights by group per block"
    );
    assert_eq!(
        admitted.as_slice(),
        GATED_ADMITTED_1024[k],
        "{name}: the spikes the window admitted per block"
    );
    assert_eq!(
        watched.spikes.as_slice(),
        GATED_SPIKES_1024[k],
        "{name}: the spikes by class per block"
    );
    assert_eq!(
        watched.cells.as_slice(),
        GATED_CELLS_1024[k],
        "{name}: the network's cells per block"
    );
    assert_eq!(
        watched.went.as_slice(),
        GATED_WENT_1024[k],
        "{name}: where the consolidation went per block"
    );
    assert_eq!(
        sourced.as_slice(),
        GATED_SOURCED_1024[k],
        "{name}: the drawn sources per block"
    );
    assert_eq!(
        sources_hash(&watched.sourced),
        GATED_SOURCES_HASH_1024[k],
        "{name}: every trial's drawn sources"
    );
    assert_eq!(
        costed.as_slice(),
        GATED_COSTED_1024[k],
        "{name}: the consolidation by the address in force per block"
    );
    assert_eq!(
        quieted.as_slice(),
        GATED_QUIETED_1024[k],
        "{name}: the readouts' spikes by where they fell per block"
    );
    assert_eq!(
        traces.as_slice(),
        GATED_ELIGIBLE_1024[k],
        "{name}: the eligibility at the rewards per block"
    );
    assert_eq!(
        margins.as_slice(),
        GATED_MARGINS_1024[k],
        "{name}: the count margins per block"
    );
    assert_eq!(
        messages.as_slice(),
        GATED_MESSAGES_1024[k],
        "{name}: the hold's messages per block"
    );
    assert_eq!(
        hash, GATED_ALONG_HASH_1024[k],
        "{name}: every trial's reading beside the run"
    );
    assert_eq!(
        Some(read_of_arm),
        GATED_READINGS_1024[k],
        "{name}: the readings"
    );
    assert_eq!(
        blocks.last().map(|b| (b.7, b.8)),
        Some(read_of_arm.sums_after),
        "{name}: the sums after the run are the last block's"
    );
}

