/// The gate's test (ADR-0061's class; brief 067): the seeds and the constants as ADR-0165 and
/// ADR-0167 fixed them; every rule of a derivation at its edges over tables written by hand; the
/// rules over the tables the tree pins for the instrument's prior, each returning the constant the
/// tree holds, where that needs no run; H-33's clauses and its stopping rule's steps over tables
/// written by hand; the readings' rules over tables written by hand; and, over the two networks'
/// pinned tables, each rule returning what the derivation pinned, each arm's readings by their
/// rules, and the verdict and its step as written. It runs no rule on a network of another seed.
/// Nothing else added to the gate.
#[test]
fn the_rules_of_a_derivation_the_clauses_of_h_33_and_the_readings_rules() {
    // The seeds and the constants.
    assert_eq!(SEEDS, [23, 24]);
    assert_eq!(PRIOR_SEED, 22);
    assert_eq!(prior(1024), prior_seeded(1024, PRIOR_SEED));
    for seed in SEEDS {
        let p = prior_seeded(1024, seed);
        assert_eq!(
            Prior {
                seed: PRIOR_SEED,
                ..p
            },
            prior(1024),
            "seed {seed}: the seed is the one change"
        );
    }
    assert_eq!(
        SEEDED_ARMS,
        [Reversal::AssignmentFirst, Reversal::MirroredFirst]
    );
    const _: () = assert!(SEEDED_PREDICTED.is_none(), "ADR-0165 predicts no verdict");
    assert_eq!(
        (ROTATIONS, GAINS, LEAD_IN_EXTENDED, LEAST_SCAN, SEEN_MIN),
        (20, [0x0001_C000, 0x0002_0000], 160, 32, 56),
        "the ranges the rules scan"
    );
    assert_eq!(
        (
            REWARDED_MIN,
            BOUND_PER_CENT,
            REVERSAL_BLOCKS_MAX,
            CROSSING_MARK,
            SCHEDULE_BLOCKS,
            BAND_QUARTERS,
            BAND_DIVISOR
        ),
        (80, 130, 23, 40, 120, (3, 5), 4),
        "clauses 1 to 4 are H-25's"
    );
    // The rotation's rule at its edges.
    let balanced_from = |first: u32| {
        move |rotation: u32| -> [i64; 4] {
            if rotation >= first {
                [100, 110, 105, 100]
            } else {
                [100, 111, 0, 100]
            }
        }
    };
    assert_eq!(
        first_balanced(&balanced_from(0)),
        (Some(0), vec![[100, 110, 105, 100]])
    );
    let (rotation, scanned) = first_balanced(&balanced_from(2));
    assert_eq!((rotation, scanned.len()), (Some(2), 3));
    assert_eq!(first_balanced(&balanced_from(19)).0, Some(19));
    let (rotation, scanned) = first_balanced(&balanced_from(20));
    assert_eq!(
        (rotation, scanned.len()),
        (None, 20),
        "no rotation of the period: the rule returns nothing"
    );
    // The gain's rule at its edges.
    let sight = |seen: u32| -> (Block, u64) {
        let mut block = CALIBRATION_1024[0].0;
        block.6 = seen;
        (block, 0)
    };
    assert_eq!(first_calibrated(&[sight(SEEN_MIN)]), Some(GAINS[0]));
    assert_eq!(first_calibrated(&[sight(SEEN_MIN - 1)]), None);
    assert_eq!(
        first_calibrated(&[sight(SEEN_MIN - 1), sight(SEEN_MIN)]),
        Some(GAINS[1])
    );
    assert_eq!(
        first_calibrated(&[sight(0), sight(0)]),
        None,
        "neither candidate: the rule returns nothing"
    );
    assert_eq!(first_calibrated(&[]), None);
    // The cancel's rule at its edges.
    assert_eq!(
        cancel_candidates(CANCEL_TICKS, GAIN_1024),
        (
            [Some(CANCEL_ONCE_AT_REST), Some(CANCEL_AT_THE_EXTREME)],
            Some(CANCELS)
        ),
        "over ADR-0076's span at 1.75 the candidates are ADR-0076's"
    );
    assert_eq!(
        cancel_candidates(0, GAIN_1024),
        ([None, None], None),
        "a span of no tick cancels nothing: no candidate"
    );
    let after = |spikes: u64| -> (Block, u64, Composition) {
        (
            CALIBRATION_1024[0].0,
            0,
            (
                [[0; 2]; 2],
                [[[0; 4]; 2]; 2],
                [[0, 0], [0, 0], [0, spikes]],
                0,
                0,
            ),
        )
    };
    let (passing, loud) = (after(0), after(327));
    assert_eq!(
        first_firing_once(51, &[3, 6, 12], &[true; 3], &[passing; 3]),
        Some(3)
    );
    assert_eq!(
        first_firing_once(51, &[3, 6, 12], &[false, true, true], &[passing; 3]),
        Some(6),
        "a failed probe is skipped"
    );
    assert_eq!(
        first_firing_once(51, &[3, 6, 12], &[true; 3], &[loud, loud, passing]),
        Some(12)
    );
    assert_eq!(
        first_firing_once(51, &[3, 6, 12], &[true; 3], &[loud; 3]),
        None,
        "no candidate fires once: the rule returns nothing"
    );
    assert_eq!(
        first_firing_once(51, &[3, 6, 12], &[true], &[loud]),
        None,
        "of the candidates run, none"
    );
    // The frozen block's measures at their edges, and a network at rest falls quiet at once.
    let mut block = BACKGROUND_1024[SETTLED].0;
    let composed = BACKGROUND_1024[SETTLED].2;
    block.6 = SEEN_MIN;
    assert_eq!(frozen_measures(51, &block, &composed), [true, true]);
    block.6 = SEEN_MIN - 1;
    assert_eq!(frozen_measures(51, &block, &composed), [true, false]);
    assert_eq!(
        frozen_measures(51, &block, &loud.2),
        [false, false],
        "the stimulus fires again after the opening"
    );
    let p = prior(1024);
    let mut fresh = at_gain(&p, config(1024, 1, 0), GAIN_1024);
    assert_eq!(quiet_within(&mut fresh), Some(0));
    // The critic's arithmetic at its edges.
    assert_eq!(critic_for(51), Some(VALUED_CRITIC), "ADR-0132's own");
    assert_eq!(
        (critic_for(50), critic_for(33), critic_for(64)),
        (
            Some(VALUED_CRITIC),
            Some(VALUED_CRITIC),
            Some(VALUED_CRITIC)
        ),
        "33 to 64 units: the sum is eleven"
    );
    assert_eq!(
        critic_for(32),
        Some(ValueCritic { shift: 8, scale: 2 }),
        "32 units fit a sum of ten"
    );
    assert_eq!(
        critic_for(4),
        Some(ValueCritic { shift: 5, scale: 2 }),
        "four units fit a sum of seven"
    );
    assert_eq!(
        (critic_for(65), critic_for(0)),
        (Some(ValueCritic { shift: 9, scale: 3 }), None),
        "ADR-0168: past 64 units the shift is held and the scale takes the rest; and no volley, whose sum is below the scale"
    );
    // Clause 0 at its edges.
    assert!(RULES_1024.hold());
    assert!(!Rules::default().hold());
    for unset in [
        Rules {
            rotation: None,
            ..RULES_1024
        },
        Rules {
            gain: None,
            ..RULES_1024
        },
        Rules {
            settled: None,
            ..RULES_1024
        },
        Rules {
            span: None,
            ..RULES_1024
        },
        Rules {
            least: [Some(3), None],
            ..RULES_1024
        },
        Rules {
            cancel: None,
            ..RULES_1024
        },
        Rules {
            frozen: None,
            ..RULES_1024
        },
        Rules {
            frozen: Some([true, false]),
            ..RULES_1024
        },
        Rules {
            frozen: Some([false, true]),
            ..RULES_1024
        },
        Rules {
            period: None,
            ..RULES_1024
        },
        Rules {
            window: None,
            ..RULES_1024
        },
        Rules {
            critic: None,
            ..RULES_1024
        },
    ] {
        assert!(!unset.hold(), "{unset:?}");
    }
    // The rules over the tables the tree pins for the instrument's prior: each returns the
    // constant the tree holds.
    let sets = geometry(1024, ROTATION_1024);
    let (rotation, scanned) = first_balanced(&|r| couplings(&fresh, &geometry(1024, r)));
    assert_eq!(
        (rotation, scanned.len()),
        (RULES_1024.rotation, 1),
        "the rotation"
    );
    assert_eq!(
        first_calibrated(&CALIBRATION_1024),
        RULES_1024.gain,
        "the gain"
    );
    assert_eq!(
        settled_within(
            PRIOR_SUMS_1024.1,
            &lead_in_sums(BACKGROUND_LEAD_IN_1024[SETTLED])
        ),
        RULES_1024.settled,
        "the settled network"
    );
    assert_eq!(
        Some(span_of(&VOLLEY_TICKS_1024)),
        RULES_1024.span,
        "the span"
    );
    assert_eq!(
        first_firing_once(sets[0].len(), &CANCELS, &[true; 3], &CANCELLED_1024),
        RULES_1024.cancel,
        "the cancel"
    );
    assert_eq!(
        Some(frozen_measures(
            sets[0].len(),
            &BACKGROUND_1024[SETTLED].0,
            &BACKGROUND_1024[SETTLED].2
        )),
        RULES_1024.frozen,
        "the frozen block's two measures"
    );
    assert_eq!(
        Some(target_period(
            1024,
            TARGET_LEAD_IN_TICKS,
            TARGET_LEAD_IN_1024.iter().sum()
        )),
        RULES_1024.period,
        "the target period"
    );
    assert_eq!(
        shortest_delay(fresh.blocks()),
        RULES_1024.window,
        "the critic's window"
    );
    assert_eq!(
        u32::try_from(sets[0].len()).ok().and_then(critic_for),
        RULES_1024.critic,
        "the critic"
    );
    assert_eq!(
        outside_image(&IMAGE_COUPLINGS_1024, QUIET_1024[SETTLED].1.1),
        image_outside(),
        "the outside sum of the instrument's image"
    );
    assert_eq!(
        DERIVED_1024,
        Derived {
            rotation: 0,
            cancel: Cancel {
                offset: 201,
                ticks: 9,
                messages: 6,
                efficacy_q16: CANCEL_MESSAGE_Q16
            },
            synapses: SYNAPSES_1024
        }
    );
    // H-33's verdict and its stopping rule's steps over tables written by hand, against an image
    // written by hand.
    let image: [[i64; 2]; 2] = [[1_000, 2_000], [3_000, 4_000]];
    let outside = 90_000i64;
    let block = |correct: u32, outside: i64, couplings: [[i64; 2]; 2]| -> Block {
        let excitatory = couplings
            .iter()
            .flatten()
            .fold(outside, |sum, &c| sum.saturating_add(c));
        (
            correct,
            0,
            [[0; 2]; 2],
            [0; 2],
            [0; 2],
            [0; 2],
            0,
            0,
            excitatory,
            0,
            couplings,
            0,
        )
    };
    assert_eq!(outside_image(&image, 100_000), outside);
    let full = vec![block(BLOCK as u32, outside, image); SCHEDULE_BLOCKS];
    let yes = seeded(&RULES_1024, Some((&image, outside, [&full, &full])));
    assert!(yes.derived && yes.yes && yes.arms.is_some_and(|verdict| verdict.yes));
    assert_eq!(seeded_step(&[yes, yes]), 3, "yes on both networks");
    let underived = seeded(
        &Rules {
            settled: None,
            ..RULES_1024
        },
        Some((&image, outside, [&full, &full])),
    );
    assert_eq!(
        underived,
        Seeded {
            derived: false,
            arms: None,
            yes: false
        },
        "a rule that returned nothing: clause 0 fails and no arm is read"
    );
    assert_eq!(seeded_step(&[yes, underived]), 4);
    assert_eq!(seeded_step(&[underived, yes]), 4, "on either network");
    assert!(
        !seeded(&RULES_1024, None).yes,
        "a network whose arms did not run is no yes"
    );
    let mut drained = full.clone();
    drained[70] = block(BLOCK as u32, outside.saturating_mul(5) / 4 + 1, image);
    let left = seeded(&RULES_1024, Some((&image, outside, [&drained, &full])));
    assert_eq!(
        left.arms.map(|verdict| (verdict.left, verdict.held)),
        Some(([Some((70, 112_501)), None], [false, true])),
        "clause 4 fails in the first arm at block 70, with its sum"
    );
    assert_eq!(seeded_step(&[yes, left]), 5);
    let mut unlearned = full.clone();
    unlearned[MAPPINGS[2].1 - 1].0 = 0;
    unlearned[MAPPINGS[2].1 - 2].0 = 0;
    let not_learned = seeded(&RULES_1024, Some((&image, outside, [&full, &unlearned])));
    assert_eq!(
        not_learned.arms.map(|verdict| verdict.learning.learned[1]),
        Some([true, true, false, true]),
        "clause 1 fails in the second arm's third mapping"
    );
    assert_eq!(seeded_step(&[not_learned, yes]), 6);
    let mut over = full.clone();
    over[40] = block(BLOCK as u32, outside, [[1_000, 2_000], [3_901, 4_000]]);
    let unbounded = seeded(&RULES_1024, Some((&image, outside, [&over, &full])));
    assert_eq!(
        unbounded.arms.map(|verdict| verdict.learning.over),
        Some([Some((40, 1, 0)), None]),
        "clause 2 fails at block 40, B→R0, one past 1.30 of this image's 3 000"
    );
    let mut at_bound = full.clone();
    at_bound[40] = block(BLOCK as u32, outside, [[1_000, 2_000], [3_900, 4_000]]);
    assert!(seeded(&RULES_1024, Some((&image, outside, [&at_bound, &full]))).yes);
    assert_eq!(seeded_step(&[unbounded, yes]), 6);
    assert_eq!(
        seeded_step(&[left, not_learned]),
        5,
        "clause 4 comes before clauses 1 and 2"
    );
    let mut slow = full.clone();
    for b in slow
        .iter_mut()
        .skip(MAPPINGS[1].0)
        .take(REVERSAL_BLOCKS_MAX)
    {
        b.0 = CROSSING_MARK - 1;
    }
    let late = seeded(&RULES_1024, Some((&image, outside, [&full, &slow])));
    assert_eq!(
        late.arms
            .map(|verdict| (verdict.learning.yes, verdict.revised, verdict.held)),
        Some((true, [[true; 3], [false, true, true]], [true; 2])),
        "clause 3 alone fails: the first reversal passes the mark in its 24th block"
    );
    assert_eq!(seeded_step(&[late, yes]), 7);
    assert_eq!(seeded_step(&[late, not_learned]), 6);
    // The readings' rules over tables written by hand.
    assert_eq!(
        frozen_selections(&[
            (0, [3, 1]),
            (0, [1, 3]),
            (0, [2, 2]),
            (1, [0, 1]),
            (1, [0, 2]),
            (0, [5, 0])
        ]),
        [[2, 1, 1], [0, 2, 0]]
    );
    assert_eq!(
        frozen_selections(&BACKGROUND_COUNTED_1024[SETTLED]),
        [[14, 15, 5], [12, 15, 3]],
        "ADR-0077's frozen block, as H-16 read its lean"
    );
    assert_eq!(
        couplings_course_of(&image, &[block(0, 0, [[1_100, 2_000], [1_500, 4_400]])]),
        vec![[[11_000, 10_000], [5_000, 11_000]]]
    );
    assert_eq!(
        couplings_course_of(&IMAGE_COUPLINGS_1024, DRAWN_BLOCKS_1024[0]),
        couplings_course(DRAWN_BLOCKS_1024[0]),
        "against the instrument's image it is `couplings_course`"
    );
    let hand: Composition = ([[0; 2]; 2], [[[0; 4]; 2]; 2], [[0; 2]; 3], 0, 7);
    let mut other = hand;
    other.4 = 8;
    assert_eq!(
        compositions_hash(&[hand, other]),
        compositions_hash(&[hand, other])
    );
    assert_ne!(
        compositions_hash(&[hand, other]),
        compositions_hash(&[other, hand])
    );
    assert_ne!(compositions_hash(&[hand]), compositions_hash(&[hand, hand]));
    // Over the two networks' pinned tables: each rule, over the table its derivation pinned,
    // returns what the derivation pinned; clause 0 holds; each arm's 120 blocks give its readings
    // by the rules; and the verdict and the step are as written, by the rules committed first.
    let mut verdicts = Vec::new();
    for (n, seed) in SEEDS.iter().enumerate() {
        let rules = RULES_SEEDED[n].expect("a derivation pinned");
        assert!(rules.hold(), "seed {seed}: clause 0");
        let scanned = SCANNED_SEEDED[n];
        assert_eq!(
            (
                first_balanced(&|r| scanned.get(r as usize).copied().unwrap_or([0; 4])).0,
                scanned.len()
            ),
            (rules.rotation, rules.rotation.map_or(0, |r| r as usize + 1)),
            "seed {seed}: the rotation, the last scanned"
        );
        let len = geometry(1024, rules.rotation.expect("a rotation"))[0].len();
        assert_eq!(first_calibrated(CALIBRATIONS_SEEDED[n]), rules.gain);
        assert_eq!(
            settled_within(PRIOR_SUMS_SEEDED[n].1, &lead_in_sums(LEAD_IN_SEEDED[n])),
            rules.settled,
            "seed {seed}: the settled window"
        );
        assert_eq!(Some(LEAD_IN_SEEDED[n].len()), rules.settled);
        assert_eq!(Some(span_of(CENSUS_SEEDED[n])), rules.span);
        let (least, candidates) =
            cancel_candidates(rules.span.expect("a span"), rules.gain.expect("a gain"));
        assert_eq!(least, rules.least, "seed {seed}: the least counts");
        let probed: Vec<bool> = PROBES_SEEDED[n].iter().map(|p| p.len() == 1).collect();
        assert_eq!(
            first_firing_once(
                len,
                &candidates.expect("three candidates"),
                &probed,
                CANCELLED_SEEDED[n]
            ),
            rules.cancel,
            "seed {seed}: the cancel"
        );
        let (frozen, _, composed) = FROZEN_SEEDED[n].expect("a frozen block");
        assert_eq!(Some(frozen_measures(len, &frozen, &composed)), rules.frozen);
        assert_eq!(
            Some(target_period(
                1024,
                TARGET_LEAD_IN_TICKS,
                TARGET_LEAD_IN_SEEDED[n].iter().sum()
            )),
            rules.period,
            "seed {seed}: the target period"
        );
        assert_eq!(u32::try_from(len).ok().and_then(critic_for), rules.critic);
        assert_eq!(
            frozen_selections(FROZEN_COUNTED_SEEDED[n])
                .iter()
                .flatten()
                .sum::<u32>(),
            BLOCK as u32,
            "seed {seed}: a selection or a tie a trial"
        );
        let couplings = COUPLINGS_SEEDED[n].expect("the image's couplings");
        let sums = QUIET_SEEDED[n].expect("the quiet run").1;
        let outside = outside_image(&couplings, sums.1);
        for k in 0..SEEDED_ARMS.len() {
            let blocks = SEEDED_BLOCKS[n][k];
            let readings = SEEDED_READINGS[n][k].expect("an arm's readings");
            assert_eq!(
                [
                    blocks.len(),
                    SEEDED_EARNED[n][k].len(),
                    SEEDED_VALUES[n][k].len(),
                    SEEDED_SOURCED[n][k].len()
                ],
                [SCHEDULE_BLOCKS; 4],
                "seed {seed} arm {k}: 120 blocks of each"
            );
            assert!(
                [
                    SEEDED_TRACES[n][k],
                    SEEDED_COMPOSED[n][k],
                    SEEDED_READ[n][k],
                    SEEDED_VALUE_HASH[n][k],
                    SEEDED_SOURCES_HASH[n][k]
                ]
                .iter()
                .all(|&hash| hash != 0),
                "seed {seed} arm {k}: every run's number pinned"
            );
            assert_eq!(
                (
                    readings.correct,
                    readings.over,
                    readings.crossings,
                    readings.left,
                    readings.highest,
                    readings.tally
                ),
                (
                    mapping_correct(blocks),
                    first_over_of(&couplings, blocks),
                    crossings(blocks),
                    left_band(outside, blocks),
                    highest_of(&couplings, blocks),
                    tally(blocks)
                ),
                "seed {seed} arm {k}: the readings by the rules"
            );
            assert_eq!(
                readings.troughs,
                troughs(&value_means(SEEDED_VALUES[n][k])),
                "seed {seed} arm {k}: the troughs"
            );
            assert_eq!(
                (readings.falls, Some(readings.sums_after)),
                (
                    falls_every_block(sums.0, blocks),
                    blocks.last().map(|b| (b.7, b.8))
                ),
                "seed {seed} arm {k}: the sums"
            );
            for (j, (block, earned)) in blocks.iter().zip(SEEDED_EARNED[n][k]).enumerate() {
                let presented = [block.1, (BLOCK as u32).saturating_sub(block.1)];
                for (s, &trials) in presented.iter().enumerate() {
                    assert_eq!(
                        earned.0[s].iter().sum::<u32>(),
                        trials,
                        "seed {seed} arm {k} block {j}: a selection or a tie a presentation"
                    );
                    assert_eq!(
                        SEEDED_VALUES[n][k][j][s][0],
                        i64::from(trials),
                        "seed {seed} arm {k} block {j}: a value a presentation"
                    );
                }
            }
        }
        let verdict = seeded(
            &rules,
            Some((
                &couplings,
                outside,
                [SEEDED_BLOCKS[n][0], SEEDED_BLOCKS[n][1]],
            )),
        );
        assert_eq!(
            verdict, SEEDED_1024[n],
            "seed {seed}: the verdict as written"
        );
        verdicts.push(verdict);
    }
    assert_eq!(
        seeded_step(&[verdicts[0], verdicts[1]]),
        SEEDED_STEP_1024,
        "the step as written"
    );
}

// --------------------- the measurement (brief 067), its tables in inhibition/pins/h33.rs

/// The prior's sums by polarity, per network.
const PRIOR_SUMS_SEEDED: [(i64, i64); 2] = [(213902976, 236101425), (213902976, 235672060)];
/// The synapses from each stimulus set onto each readout set, per network.
const SYNAPSES_SEEDED: [[[u32; 2]; 2]; 2] = [[[824, 767], [791, 799]], [[794, 782], [771, 809]]];
/// The probe of each cancel candidate tried, per network.
const PROBES_SEEDED: [&[&[u32]]; 2] = [&[&[5], &[5]], &[&[5], &[5]]];

/// The step of ADR-0165's stopping rule the verdict reaches (`seeded_step`): 3, yes on both
/// networks. The learning configuration is the rules', not one network's.
const SEEDED_STEP_1024: u8 = 3;

// =================================================================================== H-34

// -------------------------------------------- written before the run (ADR-0168, ADR-0169)

/// The size of H-34's networks (ADR-0168): 2 048 units, twice the size every learning result of
/// H-25's configuration was read at, and the largest at which an arm of H-20's whole schedule
/// fits one test of a weekly shard.
const TWICE_SIZE: u32 = 2048;

/// The networks of H-34 (ADR-0168): ADR-0044's generator at `TWICE_SIZE` units from seeds 22 and 23,
/// every other parameter the instrument's prior's (`prior_seeded`). They are the first two of the
/// three seeds read at 1 024 units; at another size each is another network. Neither was looked
/// at before it was taken, none replaces one that reads badly, and no third and no other size is
/// run. The drive's rule and seed and the task's seed are H-25's.
const TWICE_SEEDS: [u64; 2] = [22, 23];
const _: () =
    assert!(TWICE_SIZE == 2 * 1024 && TWICE_SEEDS[0] == PRIOR_SEED && TWICE_SEEDS[1] == SEEDS[0]);

/// The arms of H-34 on each network (ADR-0168): H-25's two, in their order, each its own weekly
/// test, under H-25's delivery, schedule and task.
const TWICE_ARMS: [Reversal; 2] = DRAWN_ARMS;
const _: () = assert!(matches!(
    (TWICE_ARMS, SEEDED_ARMS),
    (
        [Reversal::AssignmentFirst, Reversal::MirroredFirst],
        [Reversal::AssignmentFirst, Reversal::MirroredFirst]
    )
));

/// ADR-0168 writes no prediction for the verdict, and brief 068 adds none.
const TWICE_PREDICTED: Option<bool> = None;

/// The tokens one wheel slot of the harness's engine holds, `Engine`'s parameter (ADR-0013): not
/// a capacity of `config`, and not the units.
const WHEEL_SLOT: usize = 2048;

// ----------------------------------------------------- the readings' shape (brief 068)

/// One trial's reading of the critic's step (ADR-0168's reading, brief 068): the value of the
/// window's counts under the weights before the trial's reward, which is the value the engine
/// read at it; the value of the same counts under the weights after it; the units the window
/// counted; the spikes it counted; and the spikes the trial's ticks put in the train.
type Stepped = (i32, i32, u32, u32, u64);

/// The critic's reading over an arm (ADR-0168): what a presentation moves the value by, and the
/// units the critic counts a trial.
/// - `moved`: per mapping, over its whole span of trials, the value's moves by its own
///   presentation — the value of a trial's counts after its reward less the value before —
///   summed in magnitude, and the errors summed in magnitude. Their quotient is the step a
///   presentation takes of its error, which the rule sets at the volley's units over
///   $2^{\text{shift} + \text{scale}}$.
/// - `counted`: per mapping, its trials, the units the window counted summed over them, and the
///   spikes it counted.
/// - `against`: the trials whose value moved against its error's sign.
/// - `most`: the most spikes one trial's ticks put in the train, beside the train's capacity.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct CriticRead {
    moved: [(i64, i64); 4],
    counted: [(u64, u64, u64); 4],
    against: u32,
    most: u64,
}

/// `CriticRead` of a run's trials and the error each trial's reward delivered; zeros for a run of
/// any other length than the schedule's.
fn critic_read(stepped: &[Stepped], errors: &[i32]) -> CriticRead {
    let mut out = CriticRead {
        moved: [(0, 0); 4],
        counted: [(0, 0, 0); 4],
        against: 0,
        most: 0,
    };
    if stepped.len() != SCHEDULE_TRIALS || errors.len() != SCHEDULE_TRIALS {
        return out;
    }
    for (m, &(from, to)) in SPANS.iter().enumerate() {
        let trials = stepped.iter().zip(errors).take(to).skip(from);
        for (&(before, after, units, spikes, in_trial), &error) in trials {
            let moved = i64::from(after).saturating_sub(i64::from(before));
            let error = i64::from(error);
            out.moved[m].0 = out.moved[m].0.saturating_add(moved.saturating_abs());
            out.moved[m].1 = out.moved[m].1.saturating_add(error.saturating_abs());
            out.counted[m].0 = out.counted[m].0.saturating_add(1);
            out.counted[m].1 = out.counted[m].1.saturating_add(u64::from(units));
            out.counted[m].2 = out.counted[m].2.saturating_add(u64::from(spikes));
            if moved != 0 && (moved < 0) != (error < 0) {
                out.against = out.against.saturating_add(1);
            }
            out.most = out.most.max(in_trial);
        }
    }
    out
}

/// `n` over `d` in hundredths, truncated; zero over nothing.
fn per_hundred(n: u64, d: u64) -> u64 {
    n.saturating_mul(100).checked_div(d).unwrap_or(0)
}

/// The step the critic's rule sets for a volley of `len` units, each counted once, in parts per
/// ten thousand of the error: `len` over $2^{\text{shift} + \text{scale}}$.
fn rule_step_per_myriad(len: u64, critic: ValueCritic) -> i64 {
    let sum = u32::from(critic.shift).saturating_add(u32::from(critic.scale));
    let whole = 1u64.checked_shl(sum).unwrap_or(u64::MAX);
    len.saturating_mul(10_000).checked_div(whole).unwrap_or(0) as i64
}

/// The margins of a frozen block (ADR-0168's reading), by stimulus `[A, B]`: the difference of
/// the two readouts' counts summed in magnitude over the stimulus's trials, and the two counts
/// summed. A selection is the difference's sign, so the first over the second is how far from a
/// tie the selections stand.
fn frozen_margins(counted: &[Counted]) -> [[u64; 2]; 2] {
    let mut out = [[0u64; 2]; 2];
    for &(stimulus, [r0, r1]) in counted {
        if let Some(by) = out.get_mut(usize::from(stimulus)) {
            by[0] = by[0].saturating_add(u64::from(r0.abs_diff(r1)));
            by[1] = by[1].saturating_add(u64::from(r0).saturating_add(u64::from(r1)));
        }
    }
    out
}

// ---------------------------------------------------------------- the run (brief 068)

/// H-34's network of index `n` in `TWICE_SEEDS`, at `TWICE_SIZE` units, with the tables pinned from
/// the one run of its derivation and of each of its arms.
fn twice_site(n: usize) -> Site {
    let seed = TWICE_SEEDS[n];
    Site {
        units: TWICE_SIZE,
        seed,
        name: format!("twice{seed}"),
        derivation: DerivationPins {
            rules: RULES_TWICE[n],
            scanned: SCANNED_TWICE[n],
            prior_sums: PRIOR_SUMS_TWICE[n],
            calibrations: CALIBRATIONS_TWICE[n],
            census: CENSUS_TWICE[n],
            synapses: SYNAPSES_TWICE[n],
            probes: PROBES_TWICE[n],
            cancelled: CANCELLED_TWICE[n],
            lead_in: LEAD_IN_TWICE[n],
            quiet: QUIET_TWICE[n],
            frozen: FROZEN_TWICE[n],
            counted: FROZEN_COUNTED_TWICE[n],
            frozen_census: FROZEN_CENSUS_TWICE[n],
            target_lead_in: TARGET_LEAD_IN_TWICE[n],
            crcs: CRCS_TWICE[n],
            couplings: COUPLINGS_TWICE[n],
        },
        arms: [0usize, 1].map(|k| ArmPins {
            blocks: TWICE_BLOCKS[n][k],
            trace: TWICE_TRACES[n][k],
            composed: TWICE_COMPOSED[n][k],
            earned: TWICE_EARNED[n][k],
            read: TWICE_READ[n][k],
            values: TWICE_VALUES[n][k],
            value_hash: TWICE_VALUE_HASH[n][k],
            sourced: TWICE_SOURCED[n][k],
            sources_hash: TWICE_SOURCES_HASH[n][k],
            readings: TWICE_READINGS[n][k],
            critic: TWICE_CRITIC[n][k],
            whole: None,
        }),
    }
}

