/// The gate's test (ADR-0061's class; brief 072): H-38's steps, target, bound and settling; the
/// rate's rule as an oracle at its edges and against the record's own; the gain's mean's
/// criterion and the settled network's rule under the rate's rule at their edges, and what they
/// read of the lead-ins the tree pins; clause 0, H-38's verdict and its stopping rule's steps
/// over tables written by hand; the four predicted readings' rules at their edges; the lead-in's
/// reading, the steepness, the controller's watch beside an arm, the gain by block and the arm's
/// reading over tables written by hand; the gain held's lead-in by the rate's reading, which the
/// scan's stand beside; and, over H-38's pinned tables, each step's lead-in and what its
/// derivation returned by their rules, the verdict and its step as written, the four predicted
/// readings as read, and each arm's gain by block against its reading (`rate_tables`). It runs
/// no lead-in. Nothing else added to the gate.
#[test]
fn the_settled_network_s_rule_under_the_rate_s_rule_clause_0_of_h_38_and_the_predicted_readings_rules()
 {
    // The steps, the target, the bound, the network and the settling.
    assert_eq!(RATE_STEPS, [0x2000, 0x1000, 0x0800, 0x0400, 0x0200, 0x0100]);
    assert!(
        RATE_STEPS.windows(2).all(|pair| pair[0] > pair[1]),
        "the largest step first, so the first that holds is the largest"
    );
    assert_eq!(
        (
            RATE_TARGET_PERIOD,
            RATE_TARGET_COUNT,
            RATE_BOUND,
            MEAN_WINDOWS
        ),
        (58_201, 2_306, 320, 16)
    );
    assert_eq!((SCAN_UNITS, PRIOR_SEED, RATE_SIXTEENTH), (1024, 22, 1));
    assert_eq!(
        (RULED_PREDICTED, RATE_READINGS_PREDICTED),
        (true, [true; 4])
    );
    for step in RATE_STEPS {
        assert_eq!(
            under_rate(step),
            Settling {
                step,
                gains: false,
                bound: 320,
                target: 58_201,
                mean: true,
                read: 0,
                inhibitory: false,
                probe: false
            }
        );
    }
    // The count the engine makes of the period at 1 024 units is the count the rules read by.
    let engine = Executor::<8>::new(Config {
        units: SCAN_UNITS as usize,
        control_step_q0_16: RATE_STEPS[1],
        rate_target_period_ticks: RATE_TARGET_PERIOD,
        ..Config::default()
    })
    .expect("a configuration the engine takes");
    assert_eq!(engine.rate_target_per_window(), Some(RATE_TARGET_COUNT));
    assert_eq!(
        (saturation_count(SCAN_UNITS), WINDOW_SHIFT, BLOCK_WINDOWS),
        (32_768, 17, 8)
    );
    // The rate's rule as an oracle, at its edges, each number written by hand.
    let gain = GAIN_1024;
    let target = RATE_TARGET_COUNT;
    for step in RATE_STEPS {
        assert_eq!(
            rate_regulated(gain, 2_306, target, step),
            gain,
            "at its target, still"
        );
    }
    assert_eq!(
        rate_regulated(gain, 0, target, 0x2000),
        0x0001_F800,
        "no spike: the gain rises by the step, 1.75 to 1.96875"
    );
    assert_eq!(
        rate_regulated(gain, 4_612, target, 0x2000),
        0x0001_8800,
        "twice the target: it falls by the step, to 1.53125"
    );
    assert_eq!(
        rate_regulated(gain, 32_768, target, 0x2000),
        0x0001_8800,
        "the error is clamped at one: the saturation rule's count moves it as twice does"
    );
    assert_eq!(
        rate_regulated(gain, 1_153, target, 0x1000),
        0x0001_CE00,
        "half the target at a sixteenth: a thirty-second up"
    );
    assert_eq!(
        rate_regulated(gain, 3_459, target, 0x1000),
        0x0001_B200,
        "half again as many at a sixteenth: a thirty-second down"
    );
    // The gain held's first window, 2 446 spikes, 6.07 per cent above the target: at an eighth
    // the gain falls by 0.76 per cent, at one in 256 by 0.024.
    assert_eq!(BACKGROUND_LEAD_IN_1024[SETTLED][0].0, 2_446);
    assert_eq!(rate_regulated(gain, 2_446, target, 0x2000), 113_818);
    assert_eq!(rate_regulated(gain, 2_446, target, 0x0100), 114_660);
    assert_eq!(
        rate_regulated(GAIN_MAX_Q16, 0, target, CONTROL_STEP_MAX_Q0_16),
        GAIN_MAX_Q16
    );
    assert_eq!(
        rate_regulated(GAIN_MIN_Q16, 32_768, target, CONTROL_STEP_MAX_Q0_16),
        GAIN_MIN_Q16
    );
    for spikes in [0, 1_000, 2_306, 9_000, 40_000] {
        assert_eq!(
            rate_regulated(gain, spikes, target, 0),
            gain,
            "no step, no move"
        );
        assert_eq!(
            rate_regulated(gain, spikes, 0, 0x2000),
            gain,
            "no target, no move"
        );
    }
    // And against the record's own rule, fed the same windows bin by bin: the oracle is the
    // rule `menteion-homeostasis` holds, whatever the gain, the step and the count.
    let mut walk = 0x9E37_79B9u32;
    let mut next = || {
        walk = walk.wrapping_mul(1_664_525).wrapping_add(1_013_904_223);
        walk >> 8
    };
    for round in 0..400u32 {
        let step = RATE_STEPS[(round % 6) as usize];
        let mut pool = HomeostaticDrivePool {
            control_step_q0_16: step,
            synaptic_gain_q16: GAIN_MIN_Q16.saturating_add(next() % 0x0003_C000),
            ..HomeostaticDrivePool::new()
        };
        let before = pool.synaptic_gain_q16;
        let mut spikes = 0u64;
        for _ in 0..31 {
            let bin = next() % 160;
            pool.count_activity(bin);
            assert!(pool.close_bin().is_some());
            spikes = spikes.saturating_add(u64::from(bin));
        }
        let over = match round % 3 {
            0 => target,
            1 => u32::try_from(spikes).unwrap_or(u32::MAX).max(1),
            _ => (next() % 5_000).saturating_add(1),
        };
        assert_eq!(
            pool.regulate_rate(over),
            Some(rate_regulated(before, spikes, over, step)),
            "round {round}: {spikes} spikes over {over} at {step:#06x} from {before}"
        );
    }
    // The gain's mean's criterion at its edges. Both blocks of sixteen are whole windows of the
    // lead-in, so no window below the thirty-second holds it.
    let g = i64::from(GAIN_1024);
    let flat = vec![g; 48];
    assert!((0..32).all(|window| !mean_settled_in(&flat, window)));
    assert!(mean_settled_in(&flat, 32) && mean_settled_in(&flat, 48));
    assert!(!mean_settled_in(&flat, 49), "past the series");
    assert_eq!(mean_settled_within(&flat), Some(32));
    assert_eq!(mean_settled_within(&flat[..31]), None);
    assert_eq!(mean_settled_within(&[]), None);
    // A gain that alternates about its mean, a step up and a step down, is settled in its mean
    // where ADR-0055's criterion over each window's gain is not: ADR-0177's finding.
    let swing: Vec<i64> = (0..48i64)
        .map(|k| g.saturating_add((k & 1).saturating_mul(0x4000)))
        .collect();
    assert_eq!(mean_settled_within(&swing), Some(32));
    assert_eq!(settled_within(g, &swing), None);
    // Exactly 0.75 per cent off in the mean is not within; one part inside is. Sixteen gains of
    // 40 000 sum to 640 000, of which 0.75 per cent is 4 800.
    let mut off = vec![40_000i64; 32];
    off[16] = 44_800;
    assert!(!mean_settled_in(&off, 32), "exactly 0.75 per cent above");
    off[16] = 44_799;
    assert!(mean_settled_in(&off, 32));
    off[16] = 35_200;
    assert!(!mean_settled_in(&off, 32), "exactly 0.75 per cent below");
    off[16] = 35_201;
    assert!(mean_settled_in(&off, 32));
    // The reference is the sixteen before: a rise in them is read against their own sum.
    let mut risen = vec![40_000i64; 32];
    risen[0] = 44_836;
    assert!(
        mean_settled_in(&risen, 32),
        "4 836 below a reference of 644 836, whose 0.75 per cent is 4 836.27"
    );
    risen[0] = 44_837;
    assert!(
        !mean_settled_in(&risen, 32),
        "4 837 is past 0.75 per cent of 644 837"
    );
    // A gain that rises by a hundredth a window through its twentieth window and is still from
    // the twenty-first: its mean is settled at the forty-eighth, where the sixteen before hold
    // four windows of the rise, ten hundredths short of the sixteen after in all.
    let drifting: Vec<i64> = (0..64i64)
        .map(|k| g.saturating_add(k.min(20).saturating_mul(g / 100)))
        .collect();
    assert_eq!(mean_settled_within(&drifting), Some(48));
    // The settled network's rule under the rate's rule: both criteria at one window.
    let sums = vec![10_000i64; 64];
    assert_eq!(settled_in_mean(10_000, &sums, &flat), Some(32));
    assert_eq!(settled_in_mean(10_000, &sums, &swing), Some(32));
    assert_eq!(settled_in_mean(10_000, &sums, &drifting), Some(48));
    assert_eq!(
        settled_in_mean(10_000, &sums[..31], &flat),
        None,
        "the shorter series bounds the rule"
    );
    assert_eq!(settled_in_mean(10_000, &sums, &flat[..31]), None);
    // The sums settling later than the gain's mean: the rule waits for the sums.
    let mut late = vec![9_000i64; 64];
    for sum in late.iter_mut().take(30) {
        *sum = 10_000;
    }
    assert_eq!(settled_within(10_000, &late), Some(16));
    assert_eq!(
        settled_in_mean(10_000, &late, &flat),
        Some(47),
        "the sums hold to the thirtieth window and again from the forty-seventh"
    );
    // The settlings' rule over a table.
    let window = |spikes: u64, gain: u32, estimate: u32| -> LeadInWindow {
        (spikes, [3, 4], 500, 10_000, 0, gain, estimate)
    };
    let swinging: Vec<LeadInWindow> = (0..48u32)
        .map(|k| {
            window(
                2_306,
                GAIN_1024.saturating_add((k & 1).saturating_mul(0x4000)),
                0,
            )
        })
        .collect();
    assert_eq!(
        (
            under_rate(RATE_STEPS[0]).settled(10_000, GAIN_1024, &swinging),
            under_step(RATE_STEPS[1]).settled(10_000, GAIN_1024, &swinging),
            GAIN_HELD.settled(10_000, GAIN_1024, &swinging)
        ),
        (Some(32), None, Some(16)),
        "the mean reads a swing as settled, each window's gain does not, and the sums alone do not read it"
    );
    assert_eq!(
        under_rate(RATE_STEPS[0]).settled(10_000, GAIN_1024, &swinging[..31]),
        None
    );
    // What the two criteria read of the lead-ins the tree pins, beside the rule each was run
    // under: the gain held's, ADR-0077's at an eighth and H-37's five.
    let held_table = BACKGROUND_LEAD_IN_1024[SETTLED];
    let beside: Vec<Option<usize>> = [held_table, BACKGROUND_LEAD_IN_1024[1]]
        .into_iter()
        .chain(SCAN_LEAD_IN)
        .map(|table| {
            settled_in_mean(
                PRIOR_SUMS_1024.1,
                &lead_in_sums(table),
                &lead_in_gains(table),
            )
        })
        .collect();
    eprintln!(
        "DUMP beside PIN the settled network's rule under the rate's rule over the pinned lead-ins [held, eighth, H-37's five] {beside:?}"
    );
    assert_eq!(
        beside, RATE_BESIDE_SETTLED,
        "the pinned lead-ins by the mean's rule"
    );
    // Clause 0, H-38's verdict and its stopping rule's steps, over tables written by hand
    // against an image written by hand.
    let image: [[i64; 2]; 2] = [[1_000, 2_000], [3_000, 4_000]];
    let outside = 90_000i64;
    let block = |correct: u32| -> Block {
        let excitatory = image
            .iter()
            .flatten()
            .fold(outside, |sum, &c| sum.saturating_add(c));
        (
            correct,
            0,
            [[0; 2]; 2],
            [0; 2],
            [0; 2],
            [0; 2],
            0,
            0,
            excitatory,
            0,
            image,
            0,
        )
    };
    let full = vec![block(BLOCK as u32); SCHEDULE_BLOCKS];
    let mut unlearned = full.clone();
    for at in [
        MAPPINGS[2].1.saturating_sub(1),
        MAPPINGS[2].1.saturating_sub(2),
    ] {
        unlearned[at].0 = 0;
    }
    let unsettled = Rules {
        settled: None,
        ..RULES_1024
    };
    let blind = Rules {
        frozen: Some([true, false]),
        ..RULES_1024
    };
    let short = Rules {
        frozen: Some([false, true]),
        ..RULES_1024
    };
    let arms = Some((&image, outside, [full.as_slice(), full.as_slice()]));
    let yes = ruled(&[RULES_1024; 6], arms);
    assert_eq!(
        (yes.held, yes.taken, yes.yes, ruled_step(&yes)),
        ([true; 6], Some(0), true, 3)
    );
    assert_eq!(yes.yes, RULED_PREDICTED, "the prediction is a yes");
    let none = ruled(&[unsettled, blind, short, unsettled, blind, short], arms);
    assert_eq!(
        (
            none.held,
            none.taken,
            none.arms,
            none.yes,
            ruled_step(&none)
        ),
        ([false; 6], None, None, false, 5),
        "no step holds: no arm is read"
    );
    let second = ruled(
        &[unsettled, RULES_1024, blind, RULES_1024, short, RULES_1024],
        arms,
    );
    assert_eq!(
        (second.held, second.taken, second.yes),
        ([false, true, false, true, false, true], Some(1), true),
        "the step taken is the largest that holds, the first in the scan's order"
    );
    let last = ruled(
        &[
            unsettled, unsettled, unsettled, unsettled, unsettled, RULES_1024,
        ],
        arms,
    );
    assert_eq!((last.taken, ruled_step(&last)), (Some(5), 3));
    let not_learned = ruled(
        &[RULES_1024; 6],
        Some((&image, outside, [full.as_slice(), unlearned.as_slice()])),
    );
    assert_eq!(
        not_learned.arms.map(|verdict| verdict.learning.learned[1]),
        Some([true, true, false, true]),
        "clause 1 fails in the second arm's third mapping"
    );
    assert_eq!(
        (not_learned.taken, not_learned.yes, ruled_step(&not_learned)),
        (Some(0), false, 4),
        "a step holds and the learning does not"
    );
    let unread = ruled(&[RULES_1024; 6], None);
    assert_eq!(
        (unread.taken, unread.arms, unread.yes, ruled_step(&unread)),
        (Some(0), None, false, 4),
        "a step taken whose arms did not run is no yes"
    );
    // The four predicted readings' rules at their edges.
    for (gain, within) in [
        (108_953, false),
        (108_954, true),
        (GAIN_1024, true),
        (120_422, true),
        (120_423, false),
        (GAIN_MIN_Q16, false),
        (GAIN_MAX_Q16, false),
    ] {
        assert_eq!(gain_within(gain), within, "a gain of {gain}");
    }
    assert!(gains_within(&[108_954, GAIN_1024, 120_422]));
    assert!(!gains_within(&[GAIN_1024, 120_423, GAIN_1024]));
    assert!(!gains_within(&[]), "an arm with no window read nothing");
    assert!(mean_below(&[GAIN_1024 - 1, GAIN_1024], GAIN_1024));
    assert!(
        !mean_below(&[GAIN_1024 - 1, GAIN_1024 + 1], GAIN_1024),
        "a mean at the carried gain is not below it"
    );
    assert!(!mean_below(&[GAIN_1024 + 1], GAIN_1024) && !mean_below(&[], GAIN_1024));
    let quiet = [window(2_000, gain, 0), window(32_767, gain, 0)];
    let loud = [window(2_000, gain, 0), window(32_768, gain, 0)];
    let mut held = [false; 6];
    held[RATE_SIXTEENTH] = true;
    let low = [GAIN_1024 - 5, GAIN_1024 - 7];
    let high = [GAIN_1024 + 5, GAIN_1024 - 7, 120_423];
    assert_eq!(
        rate_predicted(
            &held,
            1024,
            &[&quiet, &quiet],
            Some([(&low, GAIN_1024), (&low, GAIN_1024)])
        ),
        [Some(true); 4]
    );
    assert_eq!(
        rate_predicted(
            &[true, false, true, true, true, true],
            1024,
            &[&quiet, &loud],
            None
        ),
        [Some(false), Some(false), None, None],
        "a sixteenth alone is the first reading; one window at the saturation rule's count misses the second; no arm, no third or fourth"
    );
    assert_eq!(
        rate_predicted(
            &held,
            1024,
            &[&quiet, &[]],
            Some([(&low, GAIN_1024), (&high, GAIN_1024)])
        ),
        [Some(true), Some(false), Some(false), Some(false)],
        "a lead-in with no window read nothing; one arm outside the band and not below misses for both"
    );
    assert_eq!(
        rate_predicted(
            &held,
            1024,
            &[],
            Some([(&low, GAIN_1024 - 7), (&low, GAIN_1024)])
        ),
        [Some(true), Some(true), Some(true), Some(false)],
        "each arm's mean against the gain its own image carried"
    );
    // The lead-in's reading at its edges, over a table written by hand under a step of an
    // eighth: the first two windows by the rule, above and below the target, the third at the
    // saturation rule's count, the fourth's gain not the rule's.
    let after_one = rate_regulated(gain, 2_446, target, 0x2000);
    let after_two = rate_regulated(after_one, 2_000, target, 0x2000);
    let after_three = rate_regulated(after_two, 32_768, target, 0x2000);
    let hand = [
        (2_446, [3, 4], 900, 9_000, 0, after_one, 0x4000),
        (2_000, [30, 40], 800, 8_000, 0, after_two, 0),
        (32_768, [300, 400], 700, 7_000, 0, after_three, 0x0001_0000),
        (
            2_306,
            [200, 100],
            500,
            6_000,
            0,
            after_three.saturating_add(1),
            0x8000,
        ),
    ];
    let read = rate_read(1024, 0x2000, target, (1_000, 10_000), gain, &hand);
    assert_eq!(
        read,
        RateRead {
            windows: 4,
            settled: [None; 3],
            band: Some((after_three, after_two)),
            late: None,
            counts: Some((2_000, 32_768)),
            sixteen: None,
            above: 2,
            saturated: 1,
            unruled: 1,
            last: (2_306, 300, after_three.saturating_add(1), 0x8000),
            sums: [5_000, 6_000],
            steepness: read.steepness,
        }
    );
    assert!(after_one < gain && after_two > after_one && after_three < after_two);
    let empty = rate_read(1024, 0x2000, target, (1_000, 10_000), gain, &[]);
    assert_eq!(
        (
            empty.windows,
            empty.band,
            empty.counts,
            empty.steepness,
            empty.last
        ),
        (0, None, None, None, (0, 0, gain, 0))
    );
    // The steepness: a table whose spikes are in proportion to the gain they ran under has a
    // steepness of one, in hundredths; in proportion to its square about two near the mean; a
    // gain that never moved, none.
    let proportional: Vec<LeadInWindow> = [100_000u32, 110_000, 120_000, 130_000, 100_000]
        .windows(2)
        .map(|pair| window(u64::from(pair[0]) / 50, pair[1], 0))
        .collect();
    assert_eq!(steepness(100_000, &proportional), Some(100));
    assert_eq!(
        steepness(
            GAIN_1024,
            &[window(9, GAIN_1024, 0), window(11, GAIN_1024, 0)]
        ),
        None,
        "no gain moved: no slope"
    );
    assert_eq!(steepness(GAIN_1024, &[]), None);
    let steep: Vec<LeadInWindow> = [100_000u32, 101_000, 102_000, 103_000, 100_000]
        .windows(2)
        .map(|pair| {
            window(
                u64::from(pair[0])
                    .saturating_mul(14)
                    .saturating_sub(1_218_000),
                pair[1],
                0,
            )
        })
        .collect();
    assert_eq!(
        steepness(100_000, &steep),
        Some(700),
        "fourteen times the gain less a constant: seven per cent of rate a per cent of gain at these means"
    );
    // The controller's watch beside an arm: the windows that ended inside the run, each with
    // the gain at the first trial's end at or after its own. The load is 1 000 ticks into the
    // window of index 3; trials of 16 384 ticks.
    let first = 3u64;
    let load = first.saturating_mul(WINDOW_TICKS).saturating_add(1_000);
    let ends: Vec<u64> = (1..=17u64)
        .map(|t| load.saturating_add(t.saturating_mul(u64::from(TRIAL_TICKS))))
        .collect();
    let trial_gains: Vec<u32> = (0..17u32).map(|t| 100u32.saturating_add(t)).collect();
    assert_eq!(
        windows_of(first, &[7, 8, 9], &ends, &trial_gains),
        vec![(7, 107), (8, 115)],
        "the window open at the load ends in the eighth trial, the next in the sixteenth, and the third is open at the run's end"
    );
    assert_eq!(
        windows_of(first, &[7, 8, 9], &ends[..7], &trial_gains[..7]),
        vec![]
    );
    assert_eq!(windows_of(first, &[], &ends, &trial_gains), vec![]);
    // A trial that ends exactly at a window's end holds that window's regulation.
    let aligned: Vec<u64> = (1..=8u64)
        .map(|t| {
            first
                .saturating_mul(WINDOW_TICKS)
                .saturating_add(t.saturating_mul(u64::from(TRIAL_TICKS)))
        })
        .collect();
    assert_eq!(
        windows_of(first, &[5, 6], &aligned, &trial_gains[..8]),
        vec![(5, 107)]
    );
    // The gain by block, eight windows to a block, and the arm's reading.
    let course: Vec<(u64, u32)> = (0..20u32)
        .map(|w| {
            (
                2_000u64.saturating_add(u64::from(w)),
                114_000u32.saturating_add(w.saturating_mul(10)),
            )
        })
        .collect();
    assert_eq!(
        gain_blocks(&course),
        vec![
            (114_000, 114_070, 114_070, 16_028),
            (114_080, 114_150, 114_150, 16_092)
        ],
        "twenty windows are two blocks and four left out"
    );
    assert_eq!(gain_blocks(&course[..7]), vec![]);
    assert_eq!(window_gains(&course[..3]), [114_000, 114_010, 114_020]);
    // An arm's reading over a course the rule made: from 1.75 under a sixteenth, the count a
    // hundredth above its target in every window, so the gain falls a little in each.
    let mut ruled_course: Vec<(u64, u32)> = Vec::new();
    let mut at = GAIN_1024;
    for _ in 0..(SCHEDULE_BLOCKS.saturating_mul(BLOCK_WINDOWS)) {
        at = rate_regulated(at, 2_329, target, 0x1000);
        ruled_course.push((2_329, at));
    }
    let by_rule = gain_read(&ruled_course, GAIN_1024, 0x1000, Some(target));
    assert_eq!(
        (by_rule.windows, by_rule.unruled, by_rule.above),
        (960, 0, 960)
    );
    assert_eq!(by_rule.target, Some(960 * 2_306));
    assert_eq!(by_rule.counts, Some((2_329, 2_329, 960 * 2_329)));
    assert_eq!(
        by_rule.band,
        ruled_course
            .last()
            .map(|&(_, low)| (low, ruled_course[0].1)),
        "a gain that only falls: its first is its highest and its last its lowest"
    );
    assert!(
        by_rule
            .outside
            .is_some_and(|(window, gain)| !gain_within(gain)
                && ruled_course
                    .get(window.saturating_sub(2))
                    .is_some_and(|&(_, before)| gain_within(before))),
        "the first window outside the band, the one before it inside"
    );
    assert!(
        by_rule.mean.0 < by_rule.mean.1,
        "the mean below the gain carried"
    );
    assert_eq!(
        by_rule
            .reversals
            .map(|r| r.map(|(at, low, high)| at > high && high > low)),
        [Some(true); 3],
        "through each reversal the gain at the flip, then the lowest and the highest of its twenty-three blocks"
    );
    // The same course read under another step is not the rule's; with the gain held, a course of
    // one gain is the rule's and one that moves is not.
    assert!(gain_read(&ruled_course, GAIN_1024, 0x2000, Some(target)).unruled > 0);
    let held_course = vec![(2_300u64, GAIN_1024); 16];
    let by_hold = gain_read(&held_course, GAIN_1024, 0, None);
    assert_eq!(
        (
            by_hold.unruled,
            by_hold.band,
            by_hold.outside,
            by_hold.target,
            by_hold.above,
            by_hold.reversals
        ),
        (0, Some((GAIN_1024, GAIN_1024)), None, None, 0, [None; 3])
    );
    let sixteen_gains = u64::from(GAIN_1024).saturating_mul(16);
    assert_eq!(by_hold.mean, (sixteen_gains, sixteen_gains));
    assert_eq!(
        gain_read(&ruled_course[..16], GAIN_1024, 0, None).unruled,
        16,
        "with no target a gain that moves is no rule's"
    );
    assert_ne!(by_hold.hash, by_rule.hash);
    let no_windows = gain_read(&[], GAIN_1024, 0x1000, Some(target));
    assert_eq!(
        (
            no_windows.windows,
            no_windows.band,
            no_windows.counts,
            no_windows.mean
        ),
        (0, None, None, (0, 0))
    );
    // The gain held's lead-in by the rate's reading, which the scan's stand beside: read under
    // no step, so every window's gain is the rule's, and against H-38's target.
    let held_read = rate_read(1024, 0, target, PRIOR_SUMS_1024, GAIN_1024, held_table);
    eprintln!("DUMP beside PIN held rate read {held_read:?}");
    assert_eq!(
        held_read, HELD_RATE_READ,
        "the gain held's lead-in, as read"
    );
    assert_eq!(
        (held_read.unruled, held_read.saturated, held_read.steepness),
        (0, 0, None)
    );
    // An arm's pinned reading gives predicted readings 3 and 4 as the rules over its gains do:
    // outside the band and below, within it and not below, within it and below, and no window.
    let within_below = vec![(2_300u64, GAIN_1024 - 100); 16];
    for (course, loaded, expected) in [
        (ruled_course.as_slice(), GAIN_1024, (false, true)),
        (held_course.as_slice(), GAIN_1024, (true, false)),
        (within_below.as_slice(), GAIN_1024, (true, true)),
        (&[][..], GAIN_1024, (false, false)),
    ] {
        let gains = window_gains(course);
        assert_eq!((gains_within(&gains), mean_below(&gains, loaded)), expected);
        assert_eq!(
            gain_readings(&gain_read(course, loaded, 0, None)),
            expected,
            "the pinned reading gives the two readings as the gains do"
        );
    }
    // Over H-38's pinned tables, by the rules above.
    rate_tables();
}

// ------------------------------------- the gate's checks over the pinned tables (ADR-0181)

/// Predicted readings 3 and 4 of an arm from its pinned reading: every gain within the band is
/// no first window outside it, and the mean below the image's is the gains' sum below as many
/// times the image's; an arm with no window holds neither.
fn gain_readings(read: &GainRead) -> (bool, bool) {
    (
        read.windows > 0 && read.outside.is_none(),
        read.windows > 0 && read.mean.0 < read.mean.1,
    )
}

/// The gate's checks over H-38's pinned tables (ADR-0181), by the rules committed before any of
/// them was run. Each step's lead-in is the first window the settled network's rule under the
/// rate's rule gives, or the bound; what its derivation returned of that rule is the rule's
/// over the table; its reading is `rate_read`'s, with every window's gain the rate's rule's;
/// its first window is the gain held's with the gain moved at its end by the rule; the frozen
/// block's two measures, where it was reached, are the rule's over the block; a rule that
/// returned nothing left nothing after it; and no window passed the train. Then the verdict by
/// `ruled` over the six pinned rules and, where the taken step's arms are pinned, their blocks
/// against the image that step's derivation wrote; the stopping rule's step; and the four
/// predicted readings — the first two by `rate_predicted` over the pinned rules and lead-ins,
/// the last two from each arm's pinned reading of its gain — each as written. Where arms are
/// pinned, each arm's gain by block is held to its reading: 120 blocks, the band the blocks'
/// lowest and highest, the count the blocks' summed, and the mean against the gain the taken
/// step's image carries.
fn rate_tables() {
    let held_table = BACKGROUND_LEAD_IN_1024[SETTLED];
    let capacity = config(SCAN_UNITS, 2, BASELINE_Q16).train_capacity as u64;
    let len = geometry(SCAN_UNITS, ROTATION_1024)[0].len();
    let mut rules = [Rules::default(); 6];
    for (k, &step) in RATE_STEPS.iter().enumerate() {
        let name = RATE_NAMES[k];
        let pins = rate_pins(k);
        let pinned = pins.rules.expect("the step's derivation is pinned");
        let table = pins.lead_in;
        assert_eq!(
            (pinned.rotation, pinned.gain),
            (RULES_1024.rotation, RULES_1024.gain),
            "{name}: the rules before the settled network are seed 22's"
        );
        let settled = under_rate(step).settled(PRIOR_SUMS_1024.1, GAIN_1024, table);
        assert_eq!(
            table.len() as u64,
            settled.map_or(RATE_BOUND, |w| w as u64),
            "{name}: the lead-in is the first settled window, or the bound"
        );
        assert_eq!(
            pinned.settled,
            settled.filter(|_| pins.quiet.is_some()),
            "{name}: the settled network's rule, over a network that fell quiet"
        );
        let read = rate_read(
            SCAN_UNITS,
            step,
            RATE_TARGET_COUNT,
            PRIOR_SUMS_1024,
            GAIN_1024,
            table,
        );
        assert_eq!(Some(read), pins.read, "{name}: the lead-in's reading");
        assert_eq!(
            (read.settled[2], read.unruled),
            (settled, 0),
            "{name}: the rule's window, and every window's gain the rate's rule's"
        );
        assert!(
            read.counts
                .is_some_and(|(_, greatest)| greatest <= capacity),
            "{name}: the train held every window read from it"
        );
        let first = table.first().expect("a window of the lead-in");
        assert_eq!(
            (
                first.0, first.1, first.2, first.3, first.4, first.6, first.5
            ),
            (
                held_table[0].0,
                held_table[0].1,
                held_table[0].2,
                held_table[0].3,
                held_table[0].4,
                held_table[0].6,
                rate_regulated(GAIN_1024, held_table[0].0, RATE_TARGET_COUNT, step)
            ),
            "{name}: the first window is the gain held's, the gain moved at its end by the rule"
        );
        assert_eq!(
            pinned.frozen,
            pins.frozen
                .map(|(block, _, composed)| frozen_measures(len, &block, &composed)),
            "{name}: the frozen block's two measures by their rule"
        );
        assert_eq!(
            (
                pins.quiet.is_some(),
                pins.carried.is_some(),
                pins.frozen.is_some(),
                pins.after_frozen.is_some(),
                pins.crcs.is_some(),
                pins.couplings.is_some()
            ),
            (
                pinned.settled.is_some(),
                pinned.settled.is_some(),
                pinned.frozen.is_some(),
                pinned.frozen.is_some(),
                pinned.critic.is_some(),
                pinned.critic.is_some()
            ),
            "{name}: a rule that returned nothing left no table after it"
        );
        rules[k] = pinned;
        eprintln!(
            "DUMP rate {name} step {step:#06x}: clause 0 {}; rules {pinned:?}; read {read:?}; by rate {:?}",
            pinned.hold(),
            estimate_by_rate(SCAN_UNITS, &[table])
        );
    }
    let lead_ins: Vec<&[LeadInWindow]> = RATE_LEAD_IN.to_vec();
    let taken = ruled(&rules, None).taken;
    assert_eq!(taken, ruled_taken(), "the step the arms run under");
    // The arms, where a step is taken and its arms are pinned, against the image that step's
    // derivation wrote.
    let image = taken.and_then(|k| {
        let pins = rate_pins(k);
        pins.couplings.zip(pins.quiet).zip(pins.carried)
    });
    let pinned_arms = RULED_BLOCKS.iter().all(|blocks| !blocks.is_empty());
    let arms = image
        .as_ref()
        .filter(|_| pinned_arms)
        .map(|((couplings, (_, sums)), _)| {
            (couplings, outside_image(couplings, sums.1), RULED_BLOCKS)
        });
    let verdict = ruled(&rules, arms);
    let mut readings = rate_predicted(&verdict.held, SCAN_UNITS, &lead_ins, None);
    if let [Some(first), Some(second)] = RULED_GAIN {
        let (a, b) = (gain_readings(&first), gain_readings(&second));
        readings[2] = Some(a.0 && b.0);
        readings[3] = Some(a.1 && b.1);
    }
    eprintln!(
        "DUMP rate PIN verdict {verdict:?} step {} predicted readings {readings:?}",
        ruled_step(&verdict)
    );
    assert_eq!(Some(verdict), RULED_1024, "H-38's verdict as written");
    assert_eq!(
        Some(ruled_step(&verdict)),
        RULED_STEP_1024,
        "the step of the stopping rule reached"
    );
    assert_eq!(
        Some(readings),
        RATE_READINGS_READ_1024,
        "ADR-0178's four predicted readings, as read"
    );
    assert_eq!(
        (verdict.yes, readings),
        (RULED_PREDICTED, RATE_READINGS_PREDICTED.map(Some)),
        "the prediction held, and each of the four predicted readings"
    );
    // Each pinned arm's gain by block against its reading.
    for (k, read) in RULED_GAIN.iter().enumerate() {
        let Some(read) = read else {
            assert!(
                RULED_GAIN_BLOCKS[k].is_empty() && RULED_BLOCKS[k].is_empty(),
                "an arm with no reading is not pinned"
            );
            continue;
        };
        let blocks = RULED_GAIN_BLOCKS[k];
        let carried = image.map(|(_, (gain, _))| gain);
        assert_eq!(
            (
                blocks.len(),
                RULED_BLOCKS[k].len(),
                read.windows,
                read.unruled
            ),
            (
                SCHEDULE_BLOCKS,
                SCHEDULE_BLOCKS,
                SCHEDULE_BLOCKS.saturating_mul(BLOCK_WINDOWS),
                0
            ),
            "arm {k}: 120 blocks of eight windows, every window's gain the rule's"
        );
        assert_eq!(
            read.band,
            blocks
                .iter()
                .map(|b| b.0)
                .min()
                .zip(blocks.iter().map(|b| b.1).max()),
            "arm {k}: the band is the blocks' lowest and highest"
        );
        assert_eq!(
            read.counts.map(|(_, _, summed)| summed),
            Some(blocks.iter().fold(0u64, |sum, b| sum.saturating_add(b.3))),
            "arm {k}: the count is the blocks' summed"
        );
        assert_eq!(
            Some(read.mean.1),
            carried.map(|gain| (read.windows as u64).saturating_mul(u64::from(gain))),
            "arm {k}: the mean is read against the gain the taken step's image carries"
        );
        assert_eq!(
            read.target,
            Some((read.windows as u64).saturating_mul(u64::from(RATE_TARGET_COUNT))),
            "arm {k}: the engine carried H-38's target"
        );
        assert_eq!(
            read.outside.is_none(),
            blocks.iter().all(|b| gain_within(b.0) && gain_within(b.1)),
            "arm {k}: no window outside the band is every block's lowest and highest within it"
        );
    }
}

// ---------- as read from the one run (ADR-0181), its tables in inhibition/pins/h38.rs

/// The step of ADR-0178's stopping rule the verdict reaches: 3, yes.
const RULED_STEP_1024: Option<u8> = Some(3);
/// ADR-0178's four predicted readings, as read; the third and the fourth none where no arm ran.
/// Each held: a sixteenth holds; no window of the six lead-ins at the saturation rule's count;
/// the gain within five per cent of 1.75 after every window of both arms; and each arm's mean
/// gain below the gain its image carries.
const RATE_READINGS_READ_1024: Option<[Option<bool>; 4]> = Some([Some(true); 4]);

// ----- the tables the gate reads beside (ADR-0181), its tables in inhibition/pins/h38.rs

// ---------- pinned from the one run (brief 072), its tables in inhibition/pins/h38.rs

const RULED_TRACES: [u64; 2] = [0xe246d68ece96a384, 0x26c25aa5790bb426];
const RULED_COMPOSED: [u64; 2] = [0x67a5780df57dd459, 0xed2d9387c48f36cb];
const RULED_READ: [u64; 2] = [0x6ff467d48c14c964, 0xc6bc50e44f3c83f9];
const RULED_VALUE_HASH: [u64; 2] = [0xd878853310d8eb29, 0x99d77f59ae22b334];
const RULED_SOURCES_HASH: [u64; 2] = [0xfc4c21e7ba4f32d6, 0xb7397575c2c7dbe0];

// =================================================================================== H-39

// --------------------------------------------- written before the run (ADR-0182, ADR-0183)

/// The networks of H-39 (ADR-0182), in their order: ADR-0044's generator at 1 024 units from
/// seed 22, the instrument's prior, and from H-33's seeds 23 and 24. No other network and no
/// other size is run.
const SIXTEENTH_SEEDS: [u64; 3] = [PRIOR_SEED, SEEDS[0], SEEDS[1]];

/// The step of H-39 (ADR-0182), Q0.16, on every network: a sixteenth, the second of H-38's scan.
const SIXTEENTH_STEP: u16 = RATE_STEPS[RATE_SIXTEENTH];
const _: () = assert!(SIXTEENTH_STEP == 0x1000);

/// Each network's target (ADR-0182): the period its own derivation returns with the gain held,
/// the settled network's rate by ADR-0128's rule — H-25's 58 201 ticks on seed 22, and the 59 510
/// and 59 179 H-33's derivations returned on seeds 23 and 24 (`RULES_SEEDED`). None is carried
/// from another network.
const SIXTEENTH_TARGETS: [u32; 3] = [TARGET_PERIOD_1024, 59_510, 59_179];

/// Those periods as a window's counts at 1 024 units (ADR-0180's rule): 134 217 728 over each,
/// to nearest — 2 306.107, 2 255.381 and 2 268.033 spikes.
const SIXTEENTH_COUNTS: [u32; 3] = [RATE_TARGET_COUNT, 2_255, 2_268];
const _: () = assert!(
    SIXTEENTH_TARGETS[0] == RATE_TARGET_PERIOD
        && (134_217_728 + 59_510 / 2) / 59_510 == SIXTEENTH_COUNTS[1] as u64
        && (134_217_728 + 59_179 / 2) / 59_179 == SIXTEENTH_COUNTS[2] as u64
);

/// The names H-39's dumps carry, per network: a derivation's `rate {name}` and an arm's
/// `ruled {name}`. Seed 22's is the name of H-38's step of a sixteenth, whose derivation brief 072
/// pinned and whose own test runs it.
const SIXTEENTH_NAMES: [&str; 3] = ["sixteenth", "sixteenth23", "sixteenth24"];

/// H-39's settling on a network whose target is `target` ticks (ADR-0182): H-38's at a
/// sixteenth with the network's own target — the controller on at a sixteenth and the rate's
/// rule on from the lead-in's first window, the settled network's rule over the excitatory sums
/// and the gain's mean, within `RATE_BOUND` windows. On seed 22 it is `under_rate`'s.
const fn at_a_sixteenth(target: u32) -> Settling {
    Settling {
        step: SIXTEENTH_STEP,
        gains: false,
        bound: RATE_BOUND,
        target,
        mean: true,
        read: 0,
        inhibitory: false,
        probe: false,
    }
}

/// The arms of H-39 (ADR-0182): H-25's two on each network, in their order, each its own weekly
/// test.
const SIXTEENTH_ARMS: [Reversal; 2] = DRAWN_ARMS;

/// ADR-0182's prediction for H-39, written before any run: yes.
const SIXTEENTH_PREDICTED: bool = true;

/// ADR-0182's four predicted readings, in its order, each predicted to hold: the step holds on
/// seeds 23 and 24; through each of the six arms the gain after every window within five per
/// cent of 1.75 (`gain_within`); in each arm fewer than `OPPOSITE_BELOW` pairs of consecutive
/// windows on opposite sides of the target; in each arm the inhibitory sum ending lower, as a
/// fraction of its image's, than in the same network's arm with the gain held. A miss is
/// recorded as one.
const SIXTEENTH_READINGS_PREDICTED: [bool; 4] = [true; 4];

/// Predicted reading 3's mark (ADR-0182): fewer than 600 of the 959 pairs an arm's 960 windows
/// make, where an eighth's arms read 750 and 758 (`RULED_OPPOSITE`).
const OPPOSITE_BELOW: u32 = 600;

// ---------------------------------------------------------------- the rules (ADR-0183)

/// The pairs of consecutive windows on opposite sides of the target (ADR-0181's reading of an
/// eighth's arms, ADR-0182's predicted reading 3): of each window after the first, whether one of
/// it and the window before it holds more spikes than `target` and the other does not. A window
/// at the target is not above it.
fn opposite_pairs(windows: &[(u64, u32)], target: u32) -> u32 {
    let above = |window: &(u64, u32)| window.0 > u64::from(target);
    windows
        .windows(2)
        .filter(|pair| above(&pair[0]) != above(&pair[1]))
        .count() as u32
}

/// An arm's inhibitory sum at its end beside its image's, `(the last block's, the image's)`; none
/// for an arm of no block.
fn inhibitory_end(image: i64, blocks: &[Block]) -> Option<(i64, i64)> {
    blocks.last().map(|block| (block.7, image))
}

/// Predicted reading 4's rule (ADR-0182): an arm's inhibitory sum ends lower, as a fraction of its
/// image's, than another arm's — `ended.0 / ended.1 < held.0 / held.1`, by the two products in
/// wider integers and strictly; not where either image's sum is not above zero.
fn ends_lower(ended: (i64, i64), held: (i64, i64)) -> bool {
    ended.1 > 0
        && held.1 > 0
        && i128::from(ended.0).saturating_mul(i128::from(held.1))
            < i128::from(held.0).saturating_mul(i128::from(ended.1))
}

/// What predicted readings 2 to 4 read of one arm under the rule (ADR-0183): whether the gain
/// after every window was within the band; the pairs of consecutive windows on opposite sides of
/// the target; the inhibitory sum at the arm's end beside its image's; and the same at the end of
/// the same network's arm with the gain held.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct SixteenthArm {
    within: bool,
    opposite: u32,
    ended: (i64, i64),
    held: (i64, i64),
}

/// ADR-0182's four predicted readings as rules, in its order: the step holds on seeds 23 and 24,
/// clause 0 of the second and the third network; and over the arms given, every arm's gain
/// within the band, every arm's opposite pairs below `OPPOSITE_BELOW`, and every arm's
/// inhibitory sum ending lower than its network's arm's with the gain held (`ends_lower`). The
/// last three are read over the arms that ran and are none where none did.
fn sixteenth_predicted(held: &[bool; 3], arms: &[SixteenthArm]) -> [Option<bool>; 4] {
    let over = |rule: fn(&SixteenthArm) -> bool| (!arms.is_empty()).then(|| arms.iter().all(rule));
    [
        Some(held[1] && held[2]),
        over(|arm| arm.within),
        over(|arm| arm.opposite < OPPOSITE_BELOW),
        over(|arm| ends_lower(arm.ended, arm.held)),
    ]
}

// ------------------------------------------------------------ the criterion (ADR-0182)

/// H-39's verdict (ADR-0182): per network, in `SIXTEENTH_SEEDS`'s order, clause 0 — every rule
/// of the derivation under the rate's rule at a sixteenth gave a value and the frozen block
/// passed both measures — and, where it holds and the arms ran, clauses 1 to 4, H-25's four by
/// H-25's rules against the image that network's derivation wrote: `seeded`, H-33's verdict on a
/// network, which is those. `yes` when all five hold in both arms on all three networks; a no
/// names the network, and in it the clause and the arm.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct Sixteenth {
    networks: [Seeded; 3],
    yes: bool,
}

fn sixteenth(rules: &[Rules; 3], arms: [Option<SeededArms<'_>>; 3]) -> Sixteenth {
    let networks = [0usize, 1, 2].map(|n| seeded(&rules[n], arms[n]));
    Sixteenth {
        networks,
        yes: networks.iter().all(|network| network.yes),
    }
}

/// The step of ADR-0182's stopping rule a verdict reaches: 3, yes; 4, a no on clause 0 on a
/// network; otherwise 5, a no on seed 22; otherwise 6, a no on seed 23 or seed 24 alone.
fn sixteenth_step(verdict: &Sixteenth) -> u8 {
    if verdict.yes {
        3
    } else if verdict.networks.iter().any(|network| !network.derived) {
        4
    } else if !verdict.networks[0].yes {
        5
    } else {
        6
    }
}

// ------------------------------------------------------------------ the run (brief 073)

/// What a derivation on a network makes before its settled network, and its cancel, beside that
/// network's derivation with the gain held (ADR-0183): neither reads the step or the target, so
/// each is the gain held's. The names of what differs, none where all agree — the rotation and
/// the gain as their rules returned them, the couplings at each rotation scanned, the prior's
/// sums, the calibration's blocks, the volley's census and the synapses; and, where the
/// derivation reached its cancel, the cancel's rules — the span, the two least counts and the
/// pick — the candidates' frozen blocks and their probes.
fn settling_apart(pins: &DerivationPins, d: &Derivation) -> Vec<&'static str> {
    let held = pins.rules.unwrap_or_default();
    let mut apart = Vec::new();
    for (what, same) in [
        ("rotation", d.rules.rotation == held.rotation),
        ("gain", d.rules.gain == held.gain),
        ("scanned", d.scanned.as_slice() == pins.scanned),
        ("prior sums", d.prior_sums == pins.prior_sums),
        (
            "calibrations",
            d.calibrations.as_slice() == pins.calibrations,
        ),
        ("census", d.census.as_slice() == pins.census),
        ("synapses", d.synapses == pins.synapses),
    ] {
        if !same {
            apart.push(what);
        }
    }
    if d.rules.span.is_some() {
        for (what, same) in [
            (
                "cancel's rules",
                (d.rules.span, d.rules.least, d.rules.cancel)
                    == (held.span, held.least, held.cancel),
            ),
            ("cancelled", d.cancelled.as_slice() == pins.cancelled),
            (
                "probes",
                d.probes
                    .iter()
                    .map(Vec::as_slice)
                    .eq(pins.probes.iter().copied()),
            ),
        ] {
            if !same {
                apart.push(what);
            }
        }
    }
    apart
}

/// Whether a lead-in's first window under the rate's rule is the gain held's first window in
/// everything but the gain its regulation left — the rule moves nothing before a window's end —
/// and that gain is the rate's rule's from `gain`, the window's spikes, the target's count and
/// the step.
fn first_ruled(
    held: &LeadInWindow,
    first: &LeadInWindow,
    gain: u32,
    count: u32,
    step: u16,
) -> bool {
    (first.0, first.1, first.2, first.3, first.4, first.6)
        == (held.0, held.1, held.2, held.3, held.4, held.6)
        && first.5 == rate_regulated(gain, first.0, count, step)
}

/// The tables H-39's derivation on network `n` is held to: on seed 22 H-38's step of a
/// sixteenth's, which brief 072 pinned; on seeds 23 and 24 their own, pinned from their one run.
fn sixteenth_pins(n: usize) -> RatePins {
    let Some(m) = n.checked_sub(1) else {
        return rate_pins(RATE_SIXTEENTH);
    };
    RatePins {
        rules: SEEDED_RATE_RULES[m],
        lead_in: SEEDED_RATE_LEAD_IN[m],
        quiet: SEEDED_RATE_QUIET[m],
        carried: SEEDED_RATE_CARRIED[m],
        frozen: SEEDED_RATE_FROZEN[m],
        counted: SEEDED_RATE_COUNTED[m],
        frozen_census: SEEDED_RATE_FROZEN_CENSUS[m],
        after_frozen: SEEDED_RATE_AFTER_FROZEN[m],
        target_lead_in: SEEDED_RATE_TARGET_LEAD_IN[m],
        crcs: SEEDED_RATE_CRCS[m],
        couplings: SEEDED_RATE_COUPLINGS[m],
        read: SEEDED_RATE_READ[m],
    }
}

/// H-39's derivation on network `n` of `SIXTEENTH_SEEDS` past the first, run and dumped whole
/// before anything of it is held: `derive_under` on the network's prior at a sixteenth under its
/// own target (`at_a_sixteenth`), as `rate_derivation` runs H-38's on seed 22, and the lead-in's
/// reading against the network's count from the gain the gain's rule returned. A rule that
/// returns nothing stops the derivation there, which is a reading of clause 0 and is not
/// repaired.
fn sixteenth_derivation(n: usize, name: &str) -> (Derivation, RateRead) {
    let m = n.checked_sub(1).expect("seed 23 or seed 24");
    let d = derive_under(
        SCAN_UNITS,
        SIXTEENTH_SEEDS[n],
        &at_a_sixteenth(SIXTEENTH_TARGETS[n]),
        name,
    );
    dump_derivation(name, &d);
    eprintln!("DUMP {name} PIN carried {:?}", d.carried);
    eprintln!("DUMP {name} PIN after frozen {:?}", d.after_frozen);
    let read = rate_read(
        SCAN_UNITS,
        SIXTEENTH_STEP,
        SIXTEENTH_COUNTS[n],
        d.prior_sums,
        d.rules.gain.unwrap_or(GAIN_1024),
        &d.lead_in,
    );
    eprintln!("DUMP {name} PIN read {read:?}");
    eprintln!(
        "DUMP {name} the estimate by the rate of its window {:?}",
        estimate_by_rate(SCAN_UNITS, &[&d.lead_in])
    );
    eprintln!(
        "DUMP {name} step {SIXTEENTH_STEP:#06x}, target {} ticks, {} spikes a window: clause 0 {}; no window at the saturation rule's count {:?}; the greatest window {:?} spikes of the {} the train holds; beside the gain held on this network {:?}, and seed 22 at a sixteenth {:?}",
        SIXTEENTH_TARGETS[n],
        SIXTEENTH_COUNTS[n],
        d.rules.hold(),
        rate_predicted(&[false; 6], SCAN_UNITS, &[&d.lead_in], None)[1],
        read.counts.map(|(_, greatest)| greatest),
        config(SCAN_UNITS, 2, BASELINE_Q16).train_capacity,
        SEEDED_HELD_RATE_READ[m],
        RATE_READ[RATE_SIXTEENTH]
    );
    (d, read)
}

/// H-39's derivation on seed 23 or seed 24 held (ADR-0183), after it is dumped, as
/// `rate_derivation_held` holds H-38's on seed 22, with the network's derivation with the gain
/// held, H-33's (`seeded_site`), where that holds seed 22's constants:
/// - what the derivation makes before the settled network, and its cancel where it was reached,
///   are the gain held's (`settling_apart`);
/// - the lead-in's first window is the gain held's in everything but the gain its regulation
///   left, and that gain is the rate's rule's from the gain's rule's gain (`first_ruled`);
/// - every window's gain is the rate's rule's from the gain before it, the window's spikes, the
///   network's count and the step;
/// - no window of the lead-in holds more spikes than the train's capacity, which
///   `lead_in_window` asserts window by window, and no worker's report carries an entry dropped
///   (`undropped`);
/// - the tables pinned from the derivation's one run (`rate_pins_held`).
fn sixteenth_derivation_held(n: usize, name: &str, d: &Derivation, read: &RateRead) {
    let m = n.checked_sub(1).expect("seed 23 or seed 24");
    let held = seeded_site(m).derivation;
    assert_eq!(
        settling_apart(&held, d),
        Vec::<&str>::new(),
        "{name}: what the derivation makes before the settled network, and its cancel, are the gain held's"
    );
    let gain = held
        .rules
        .and_then(|rules| rules.gain)
        .expect("the gain held's gain");
    let first = d.lead_in.first().expect("a window of the lead-in");
    let held_first = held
        .lead_in
        .first()
        .expect("a window of the gain held's lead-in");
    assert!(
        first_ruled(held_first, first, gain, SIXTEENTH_COUNTS[n], SIXTEENTH_STEP),
        "{name}: the first window is the gain held's, the gain moved at its end by the rule"
    );
    assert_eq!(
        read.unruled, 0,
        "{name}: every window's gain is the rate's rule's"
    );
    let capacity = config(SCAN_UNITS, 2, BASELINE_Q16).train_capacity as u64;
    assert!(
        read.counts
            .is_some_and(|(_, greatest)| greatest <= capacity),
        "{name}: the train held every window read from it"
    );
    rate_pins_held(name, &sixteenth_pins(n), d, read);
}

/// H-39's derivation on network `n` past the first (brief 073), a test of its own:
/// `sixteenth_derivation`, then `sixteenth_derivation_held`.
fn sixteenth_derived(n: usize) {
    let name = format!("rate {}", SIXTEENTH_NAMES[n]);
    let (d, read) = sixteenth_derivation(n, &name);
    sixteenth_derivation_held(n, &name, &d, &read);
}

/// H-39's network of index `n` in `SIXTEENTH_SEEDS` for its arms, at a sixteenth, with the
/// tables its arms' one run pinned.
fn sixteenth_site(n: usize) -> RuledSite {
    RuledSite {
        step: RATE_SIXTEENTH,
        network: n,
        name: format!("ruled {}", SIXTEENTH_NAMES[n]),
        arms: [0usize, 1].map(|k| ArmPins {
            blocks: SIXTEENTH_BLOCKS[n][k],
            trace: SIXTEENTH_TRACES[n][k],
            composed: SIXTEENTH_COMPOSED[n][k],
            earned: SIXTEENTH_EARNED[n][k],
            read: SIXTEENTH_READ[n][k],
            values: SIXTEENTH_VALUES[n][k],
            value_hash: SIXTEENTH_VALUE_HASH[n][k],
            sourced: SIXTEENTH_SOURCED[n][k],
            sources_hash: SIXTEENTH_SOURCES_HASH[n][k],
            readings: SIXTEENTH_READINGS[n][k],
            critic: SIXTEENTH_CRITIC[n][k],
            whole: SIXTEENTH_WHOLE[n][k],
        }),
        gains: [0usize, 1].map(|k| GainPins {
            blocks: SIXTEENTH_GAIN_BLOCKS[n][k],
            read: SIXTEENTH_GAIN[n][k],
            opposite: SIXTEENTH_OPPOSITE[n][k],
        }),
        read: false,
        inhibitory: false,
        probe: false,
    }
}

/// One arm of H-39 (ADR-0182, brief 073): H-25's arm on network `n` from the image its derivation
/// under the rate's rule at a sixteenth wrote, the step and the network's target carried through
/// every trial — `arm_on` on its `RuledSite`, under the true reward. Its calibration is the
/// network's derivation run again and held as its own test holds it; on a network whose clause 0
/// does not hold there is no arm.
fn sixteenth_arm(n: usize, arm: Reversal) {
    arm_on(Ground::Ruled(&sixteenth_site(n)), None, arm);
}

/// The inhibitory sum at the end of arm `k` of network `n` with the gain held, beside its image's:
/// H-25's on seed 22 and H-33's on seeds 23 and 24, as the tree pins them.
fn held_end(n: usize, k: usize) -> Option<(i64, i64)> {
    match n.checked_sub(1) {
        None => inhibitory_end(QUIET_1024[SETTLED].1.0, DRAWN_BLOCKS_1024[k]),
        Some(m) => inhibitory_end(QUIET_SEEDED[m]?.1.0, SEEDED_BLOCKS[m][k]),
    }
}

/// What predicted readings 2 to 4 read of arm `k` of network `n` from its pinned tables (ADR-0183):
/// its gain within the band by its pinned reading (`gain_readings`), its opposite pairs as
/// pinned, and its inhibitory sum's end against the image its network's derivation wrote beside
/// the network's arm's with the gain held. None before its one run.
fn sixteenth_arm_read(n: usize, k: usize) -> Option<SixteenthArm> {
    let read = SIXTEENTH_GAIN[n][k]?;
    let (_, sums) = sixteenth_pins(n).quiet?;
    Some(SixteenthArm {
        within: gain_readings(&read).0,
        opposite: SIXTEENTH_OPPOSITE[n][k]?,
        ended: inhibitory_end(sums.0, SIXTEENTH_BLOCKS[n][k])?,
        held: held_end(n, k)?,
    })
}

