/// A derivation with the gain held given back from its pinned tables (ADR-0183), so that the gate
/// tries a derivation's checks before any run: what each rule returned and every table it was
/// read from; the images, which the pins hold by their CRCs, are not.
fn pinned_derivation(pins: &DerivationPins) -> Derivation {
    Derivation {
        rules: pins.rules.unwrap_or_default(),
        scanned: pins.scanned.to_vec(),
        prior_sums: pins.prior_sums,
        calibrations: pins.calibrations.to_vec(),
        census: pins.census.to_vec(),
        synapses: pins.synapses,
        probes: pins.probes.iter().map(|probe| probe.to_vec()).collect(),
        cancelled: pins.cancelled.to_vec(),
        lead_in: pins.lead_in.to_vec(),
        quiet: pins.quiet,
        frozen: pins.frozen,
        counted: pins.counted.to_vec(),
        frozen_census: pins.frozen_census.to_vec(),
        target_lead_in: pins.target_lead_in.to_vec(),
        crcs_read: pins.crcs,
        couplings: pins.couplings,
        ..Derivation::default()
    }
}

/// The gate's test (ADR-0061's class; brief 073): H-39's networks, targets, counts, step,
/// settling, arms and prediction; the opposite pairs' rule and the inhibitory sum's at their
/// edges; H-39's verdict and its stopping rule's steps over tables written by hand; the four
/// predicted readings' rules at their edges; the checks a derivation on seed 23 or seed 24 is
/// held by, tried before any such run over the tables the tree pins — what a derivation makes
/// before its settled network and its cancel against each network's derivation with the gain
/// held, and a first window under the rule against seed 22's at a sixteenth and at an eighth;
/// the tables read before the run — each network's gain held's lead-in by the rate's reading,
/// the inhibitory sum's end in each arm with the gain held, and H-38's arms' opposite pairs and
/// inhibitory ends; and, over H-39's pinned tables, each network's derivation by its rules, each
/// arm's gain by block against its reading, and the verdict, its step and the four predicted
/// readings as written (`sixteenth_tables`). It runs no lead-in. Nothing else added to the gate.
#[test]
fn the_networks_of_h_39_its_clauses_and_its_predicted_readings_rules() {
    // The networks, the targets, the counts, the step, the settling, the arms and the
    // prediction.
    assert_eq!(SIXTEENTH_SEEDS, [22, 23, 24]);
    assert_eq!(SIXTEENTH_TARGETS, [58_201, 59_510, 59_179]);
    assert_eq!(
        SIXTEENTH_TARGETS.map(Some),
        [
            Some(TARGET_PERIOD_1024),
            RULES_SEEDED[0].and_then(|rules| rules.period),
            RULES_SEEDED[1].and_then(|rules| rules.period)
        ],
        "each network's target is the period its own derivation returns with the gain held"
    );
    assert_eq!(SIXTEENTH_COUNTS, [2_306, 2_255, 2_268]);
    for (n, &period) in SIXTEENTH_TARGETS.iter().enumerate() {
        let engine = Executor::<8>::new(Config {
            units: SCAN_UNITS as usize,
            control_step_q0_16: SIXTEENTH_STEP,
            rate_target_period_ticks: period,
            ..Config::default()
        })
        .expect("a configuration the engine takes");
        assert_eq!(
            engine.rate_target_per_window(),
            Some(SIXTEENTH_COUNTS[n]),
            "network {n}: the count the engine makes of its target is the count the rules read by"
        );
    }
    assert_eq!(
        (
            SIXTEENTH_STEP,
            RATE_STEPS[RATE_SIXTEENTH],
            RATE_BOUND,
            SCAN_UNITS
        ),
        (0x1000, 0x1000, 320, 1024)
    );
    assert_eq!(
        at_a_sixteenth(RATE_TARGET_PERIOD),
        under_rate(SIXTEENTH_STEP),
        "on seed 22 H-39's settling is H-38's at a sixteenth"
    );
    for &period in &SIXTEENTH_TARGETS {
        assert_eq!(
            at_a_sixteenth(period),
            Settling {
                step: 0x1000,
                gains: false,
                bound: 320,
                target: period,
                mean: true,
                read: 0,
                inhibitory: false,
                probe: false
            }
        );
    }
    assert_eq!(SIXTEENTH_NAMES[0], RATE_NAMES[RATE_SIXTEENTH]);
    assert_eq!(
        SIXTEENTH_ARMS,
        [Reversal::AssignmentFirst, Reversal::MirroredFirst]
    );
    assert_eq!(
        (
            SIXTEENTH_PREDICTED,
            SIXTEENTH_READINGS_PREDICTED,
            OPPOSITE_BELOW
        ),
        (true, [true; 4], 600)
    );
    assert_eq!(
        (
            REWARDED_MIN,
            BOUND_PER_CENT,
            REVERSAL_BLOCKS_MAX,
            CROSSING_MARK,
            SCHEDULE_BLOCKS,
            BAND_QUARTERS,
            BAND_DIVISOR
        ),
        (80, 130, 23, 40, 120, (3, 5), 4),
        "clauses 1 to 4 are H-25's"
    );
    // The opposite pairs' rule at its edges: a window at the target is not above it.
    let win = |spikes: u64| (spikes, GAIN_1024);
    assert_eq!(opposite_pairs(&[], 2_306), 0);
    assert_eq!(opposite_pairs(&[win(9_999)], 2_306), 0);
    assert_eq!(opposite_pairs(&[win(2_306), win(2_307)], 2_306), 1);
    assert_eq!(
        opposite_pairs(&[win(2_306), win(2_306), win(0)], 2_306),
        0,
        "a window at the target stands with those below it"
    );
    assert_eq!(
        opposite_pairs(&[win(2_307), win(2_306), win(2_307)], 2_306),
        2
    );
    let alternating: Vec<(u64, u32)> = (0..960u64)
        .map(|w| win(if w & 1 == 0 { 2_400 } else { 2_200 }))
        .collect();
    assert_eq!(
        opposite_pairs(&alternating, 2_306),
        959,
        "960 windows that alternate: every pair"
    );
    assert_eq!(opposite_pairs(&alternating, 2_400), 0);
    let mut once = vec![win(2_200); 960];
    once[480] = win(2_400);
    assert_eq!(opposite_pairs(&once, 2_306), 2);
    // The inhibitory sum's rule at its edges.
    assert!(ends_lower((782, 1_000), (848, 1_000)));
    assert!(
        !ends_lower((848, 1_000), (848, 1_000)),
        "at the same fraction it is not lower"
    );
    assert!(!ends_lower((1, 2), (2, 4)), "one fraction written two ways");
    assert!(!ends_lower((849, 1_000), (848, 1_000)));
    assert!(ends_lower((1_999_999, 4_000_000), (1, 2)));
    assert!(
        !ends_lower((1, 0), (2, 3)) && !ends_lower((1, 2), (2, 0)),
        "against an image of no sum it reads nothing"
    );
    assert!(
        ends_lower((i64::MAX.saturating_sub(1), i64::MAX), (i64::MAX, i64::MAX)),
        "the products in wider integers"
    );
    // Clause 0, H-39's verdict and its stopping rule's steps, over tables written by hand
    // against an image written by hand.
    let image: [[i64; 2]; 2] = [[1_000, 2_000], [3_000, 4_000]];
    let outside = 90_000i64;
    let block = |correct: u32, inhibitory: i64| -> Block {
        let excitatory = image
            .iter()
            .flatten()
            .fold(outside, |sum, &c| sum.saturating_add(c));
        (
            correct,
            0,
            [[0; 2]; 2],
            [0; 2],
            [0; 2],
            [0; 2],
            0,
            inhibitory,
            excitatory,
            0,
            image,
            0,
        )
    };
    assert_eq!(inhibitory_end(5_000, &[]), None);
    assert_eq!(
        inhibitory_end(5_000, &[block(64, 4_000), block(64, 3_900)]),
        Some((3_900, 5_000)),
        "the last block's sum"
    );
    let full = vec![block(BLOCK as u32, 0); SCHEDULE_BLOCKS];
    let mut unlearned = full.clone();
    for at in [
        MAPPINGS[2].1.saturating_sub(1),
        MAPPINGS[2].1.saturating_sub(2),
    ] {
        unlearned[at].0 = 0;
    }
    let unsettled = Rules {
        settled: None,
        ..RULES_1024
    };
    let blind = Rules {
        frozen: Some([true, false]),
        ..RULES_1024
    };
    let arms = Some((&image, outside, [full.as_slice(), full.as_slice()]));
    let unlearned_arms = Some((&image, outside, [full.as_slice(), unlearned.as_slice()]));
    let yes = sixteenth(&[RULES_1024; 3], [arms; 3]);
    assert_eq!((yes.yes, sixteenth_step(&yes)), (true, 3));
    assert_eq!(yes.yes, SIXTEENTH_PREDICTED, "the prediction is a yes");
    let underived = sixteenth(&[RULES_1024, RULES_1024, unsettled], [arms; 3]);
    assert_eq!(
        (
            underived
                .networks
                .map(|network| (network.derived, network.arms.is_some())),
            underived.yes,
            sixteenth_step(&underived)
        ),
        ([(true, true), (true, true), (false, false)], false, 4),
        "a no on clause 0 on seed 24: its arms are not read"
    );
    assert_eq!(
        sixteenth_step(&sixteenth(&[blind, RULES_1024, RULES_1024], [arms; 3])),
        4,
        "a frozen block that fails a measure on seed 22"
    );
    assert_eq!(
        sixteenth_step(&sixteenth(
            &[RULES_1024, RULES_1024, unsettled],
            [unlearned_arms, arms, arms]
        )),
        4,
        "clause 0 is read first"
    );
    let on_22 = sixteenth(&[RULES_1024; 3], [unlearned_arms, arms, arms]);
    assert_eq!(
        (
            on_22.networks[0]
                .arms
                .map(|verdict| verdict.learning.learned[1]),
            on_22.networks[0].yes,
            on_22.yes,
            sixteenth_step(&on_22)
        ),
        (Some([true, true, false, true]), false, false, 5),
        "clause 1 fails in seed 22's second arm's third mapping"
    );
    assert_eq!(
        sixteenth_step(&sixteenth(
            &[RULES_1024; 3],
            [unlearned_arms, unlearned_arms, arms]
        )),
        5,
        "a no on seed 22 is read before one on seed 23"
    );
    for (given, expected) in [
        ([arms, unlearned_arms, arms], [true, false, true]),
        ([arms, arms, unlearned_arms], [true, true, false]),
    ] {
        let verdict = sixteenth(&[RULES_1024; 3], given);
        assert_eq!(
            (
                verdict.networks.map(|network| network.yes),
                sixteenth_step(&verdict)
            ),
            (expected, 6),
            "a no on seed 23 or seed 24 alone"
        );
    }
    let unread = sixteenth(&[RULES_1024; 3], [arms, arms, None]);
    assert_eq!(
        (
            unread.networks[2].derived,
            unread.networks[2].arms,
            unread.yes,
            sixteenth_step(&unread)
        ),
        (true, None, false, 6),
        "a network whose arms did not run is no yes"
    );
    // The four predicted readings' rules at their edges.
    let arm = |within: bool, opposite: u32, ended: i64| SixteenthArm {
        within,
        opposite,
        ended: (ended, 1_000),
        held: (848, 1_000),
    };
    let good = arm(true, 599, 847);
    assert_eq!(sixteenth_predicted(&[true; 3], &[good; 6]), [Some(true); 4]);
    assert_eq!(
        sixteenth_predicted(&[true, true, false], &[]),
        [Some(false), None, None, None],
        "seed 24's step does not hold; no arm, no second to fourth"
    );
    assert_eq!(
        sixteenth_predicted(&[false, true, true], &[good]),
        [Some(true); 4],
        "the first reading is of seeds 23 and 24 alone"
    );
    for (odd, expected) in [
        (
            arm(false, 599, 847),
            [Some(true), Some(false), Some(true), Some(true)],
        ),
        (
            arm(true, 600, 847),
            [Some(true), Some(true), Some(false), Some(true)],
        ),
        (
            arm(true, 599, 848),
            [Some(true), Some(true), Some(true), Some(false)],
        ),
    ] {
        let mut six = vec![good; 5];
        six.push(odd);
        assert_eq!(
            sixteenth_predicted(&[true; 3], &six),
            expected,
            "one arm of six misses: {odd:?}"
        );
    }
    // The checks a derivation on seed 23 or seed 24 is held by, tried over the tables the tree
    // pins before any such run. Each network's derivation with the gain held, given back from its
    // pins, is its own in everything before its settled network and in its cancel; a table
    // changed is named; a derivation that stopped before its cancel is not held to one; another
    // network's is not this one's.
    for (m, seed) in SEEDS.iter().enumerate() {
        let pins = seeded_site(m).derivation;
        assert_eq!(
            settling_apart(&pins, &pinned_derivation(&pins)),
            Vec::<&str>::new(),
            "seed {seed}: the gain held's against its own pins"
        );
        let mut moved = pinned_derivation(&pins);
        if let Some(first) = moved.census.first_mut() {
            first.1 = first.1.saturating_add(1);
        }
        moved.probes.pop();
        assert_eq!(settling_apart(&pins, &moved), vec!["census", "probes"]);
        moved.rules.span = None;
        assert_eq!(
            settling_apart(&pins, &moved),
            vec!["census"],
            "a derivation that stopped before its cancel"
        );
        let other = pinned_derivation(&seeded_site(m ^ 1).derivation);
        assert!(
            settling_apart(&pins, &other).contains(&"prior sums"),
            "seed {seed}: another network's is not this one's"
        );
    }
    // A first window under the rule: seed 22's at a sixteenth and at an eighth against the gain
    // held's, by the rule a derivation on seed 23 or seed 24 is held by; and each of those
    // networks' gain held's first window against itself, under no step and under the gain moved
    // at its end by the rule.
    let held_first = &BACKGROUND_LEAD_IN_1024[SETTLED][0];
    let sixteenth_first = &RATE_LEAD_IN[RATE_SIXTEENTH][0];
    assert!(first_ruled(
        held_first,
        sixteenth_first,
        GAIN_1024,
        RATE_TARGET_COUNT,
        SIXTEENTH_STEP
    ));
    assert!(first_ruled(
        held_first,
        &RATE_LEAD_IN[0][0],
        GAIN_1024,
        RATE_TARGET_COUNT,
        RATE_STEPS[0]
    ));
    assert!(
        !first_ruled(
            held_first,
            &RATE_LEAD_IN[0][0],
            GAIN_1024,
            RATE_TARGET_COUNT,
            SIXTEENTH_STEP
        ),
        "an eighth's first window is not a sixteenth's"
    );
    assert!(
        !first_ruled(
            held_first,
            sixteenth_first,
            GAIN_1024,
            SIXTEENTH_COUNTS[1],
            SIXTEENTH_STEP
        ),
        "nor read against another network's count"
    );
    for (m, seed) in SEEDS.iter().enumerate() {
        let first = LEAD_IN_SEEDED[m][0];
        let count = SIXTEENTH_COUNTS[m.saturating_add(1)];
        assert!(first_ruled(&first, &first, GAIN_1024, count, 0));
        let mut moved = first;
        moved.5 = rate_regulated(GAIN_1024, first.0, count, SIXTEENTH_STEP);
        assert_ne!(moved.5, first.5, "seed {seed}: the rule moves the gain");
        assert!(first_ruled(
            &first,
            &moved,
            GAIN_1024,
            count,
            SIXTEENTH_STEP
        ));
        moved.2 = moved.2.saturating_add(1);
        assert!(
            !first_ruled(&first, &moved, GAIN_1024, count, SIXTEENTH_STEP),
            "a window whose sums moved"
        );
    }
    // The tables read before the run, functions of tables the tree pins: each of seeds 23's and
    // 24's gain held's lead-ins by the rate's reading against its own count, under no step; the
    // inhibitory sum at the end of each arm with the gain held beside its image's, per network;
    // and H-38's arms' opposite pairs, as ADR-0181 read them, and their inhibitory ends.
    let held_reads = [0usize, 1].map(|m| {
        rate_read(
            SCAN_UNITS,
            0,
            SIXTEENTH_COUNTS[m.saturating_add(1)],
            PRIOR_SUMS_SEEDED[m],
            GAIN_1024,
            LEAD_IN_SEEDED[m],
        )
    });
    let held_ends = [0usize, 1, 2].map(|n| [0usize, 1].map(|k| held_end(n, k)));
    let ruled_ends = [0usize, 1]
        .map(|k| inhibitory_end(RATE_QUIET[0].map_or(0, |(_, sums)| sums.0), RULED_BLOCKS[k]));
    eprintln!("DUMP beside PIN seeded held rate read {held_reads:?}");
    eprintln!("DUMP beside PIN held ends {held_ends:?}");
    eprintln!("DUMP beside PIN ruled ends {ruled_ends:?}");
    assert_eq!(
        held_reads, SEEDED_HELD_RATE_READ,
        "the gain held's lead-ins on seeds 23 and 24, as read"
    );
    assert!(
        held_reads
            .iter()
            .all(|read| (read.unruled, read.saturated, read.steepness) == (0, 0, None)),
        "under no step every window's gain is the rule's and the gain never moved"
    );
    assert_eq!(
        held_ends,
        HELD_ENDS.map(|network| network.map(Some)),
        "the inhibitory sum's end in each arm with the gain held"
    );
    assert_eq!(ruled_ends, RULED_ENDS.map(Some));
    for k in 0..2usize {
        assert!(
            ends_lower(RULED_ENDS[k], HELD_ENDS[0][k]),
            "arm {k}: under an eighth the sum ended lower than with the gain held, as ADR-0181 read it"
        );
    }
    assert_eq!(RULED_OPPOSITE, [Some(750), Some(758)]);
    assert!(
        RULED_OPPOSITE
            .iter()
            .all(|pairs| pairs.is_some_and(|pairs| pairs >= OPPOSITE_BELOW)),
        "an eighth's arms would miss predicted reading 3"
    );
    // Over H-39's pinned tables, by the rules above.
    sixteenth_tables();
}

/// An image a derivation under the rate's rule wrote, as the gate reads an arm against it: its
/// four couplings, its sums by polarity and the gain it carries.
type RuledImage = ([[i64; 2]; 2], (i64, i64), u32);

/// The gate's checks over H-39's pinned tables (ADR-0183), by the rules committed before any of
/// them was run, each where it is pinned. On each network whose derivation is pinned: the rules
/// before the settled network are the gain held's; the lead-in is the first settled window under
/// H-39's settling, or the bound, and what the derivation returned of that rule is the rule's
/// over the table; its reading is `rate_read`'s against the network's count, with every window's
/// gain the rate's rule's; its first window is the gain held's with the gain moved at its end by
/// the rule; the frozen block's two measures, where it was reached, are the rule's over the
/// block; a rule that returned nothing left nothing after it; and no window passed the train.
/// Each pinned arm's gain by block against its reading, as `rate_tables` holds H-38's: 120 blocks,
/// the band the blocks' lowest and highest, the count the blocks' summed, the mean against the
/// gain its network's image carries, the target the network's, and its opposite pairs pinned
/// with it. Then, where every derivation is pinned and every arm of each network whose clause 0
/// holds, the verdict by `sixteenth`, its step and the four predicted readings by
/// `sixteenth_predicted`, each as written; before that, none is.
fn sixteenth_tables() {
    let capacity = config(SCAN_UNITS, 2, BASELINE_Q16).train_capacity as u64;
    let mut rules: [Option<Rules>; 3] = [None; 3];
    let mut images: [Option<RuledImage>; 3] = [None; 3];
    for n in 0..3usize {
        let name = SIXTEENTH_NAMES[n];
        let pins = sixteenth_pins(n);
        let Some(pinned) = pins.rules else {
            assert!(
                pins.lead_in.is_empty()
                    && pins.read.is_none()
                    && SIXTEENTH_BLOCKS[n].iter().all(|blocks| blocks.is_empty()),
                "{name}: a network whose derivation is not pinned has no table and no arm"
            );
            continue;
        };
        let (held_rules, held_first, priors) = match n.checked_sub(1) {
            None => (
                RULES_1024,
                BACKGROUND_LEAD_IN_1024[SETTLED][0],
                PRIOR_SUMS_1024,
            ),
            Some(m) => (
                RULES_SEEDED[m].expect("H-33's derivation"),
                LEAD_IN_SEEDED[m][0],
                PRIOR_SUMS_SEEDED[m],
            ),
        };
        assert_eq!(
            (pinned.rotation, pinned.gain),
            (held_rules.rotation, held_rules.gain),
            "{name}: the rules before the settled network are the gain held's"
        );
        let gain = held_rules.gain.expect("the gain's rule's gain");
        let table = pins.lead_in;
        let settled = at_a_sixteenth(SIXTEENTH_TARGETS[n]).settled(priors.1, gain, table);
        assert_eq!(
            table.len() as u64,
            settled.map_or(RATE_BOUND, |w| w as u64),
            "{name}: the lead-in is the first settled window, or the bound"
        );
        assert_eq!(
            pinned.settled,
            settled.filter(|_| pins.quiet.is_some()),
            "{name}: the settled network's rule, over a network that fell quiet"
        );
        let read = rate_read(
            SCAN_UNITS,
            SIXTEENTH_STEP,
            SIXTEENTH_COUNTS[n],
            priors,
            gain,
            table,
        );
        assert_eq!(Some(read), pins.read, "{name}: the lead-in's reading");
        assert_eq!(
            (read.settled[2], read.unruled),
            (settled, 0),
            "{name}: the rule's window, and every window's gain the rate's rule's"
        );
        assert!(
            read.counts
                .is_some_and(|(_, greatest)| greatest <= capacity),
            "{name}: the train held every window read from it"
        );
        assert!(
            table.first().is_some_and(|first| first_ruled(
                &held_first,
                first,
                gain,
                SIXTEENTH_COUNTS[n],
                SIXTEENTH_STEP
            )),
            "{name}: the first window is the gain held's, the gain moved at its end by the rule"
        );
        let len = geometry(SCAN_UNITS, pinned.rotation.unwrap_or(0))[0].len();
        assert_eq!(
            pinned.frozen,
            pins.frozen
                .map(|(block, _, composed)| frozen_measures(len, &block, &composed)),
            "{name}: the frozen block's two measures by their rule"
        );
        assert_eq!(
            (
                pins.quiet.is_some(),
                pins.carried.is_some(),
                pins.frozen.is_some(),
                pins.after_frozen.is_some(),
                pins.crcs.is_some(),
                pins.couplings.is_some()
            ),
            (
                pinned.settled.is_some(),
                pinned.settled.is_some(),
                pinned.frozen.is_some(),
                pinned.frozen.is_some(),
                pinned.critic.is_some(),
                pinned.critic.is_some()
            ),
            "{name}: a rule that returned nothing left no table after it"
        );
        rules[n] = Some(pinned);
        images[n] = pins
            .couplings
            .zip(pins.quiet)
            .zip(pins.carried)
            .map(|((couplings, (_, sums)), (gain, _))| (couplings, sums, gain));
        eprintln!(
            "DUMP sixteenth {name} target {} ticks, {} spikes a window: clause 0 {}; rules {pinned:?}; read {read:?}",
            SIXTEENTH_TARGETS[n],
            SIXTEENTH_COUNTS[n],
            pinned.hold()
        );
    }
    // Each pinned arm, against the image its network's derivation wrote.
    let mut arm_reads: Vec<SixteenthArm> = Vec::new();
    let mut arms_pinned = [false; 3];
    for n in 0..3usize {
        for k in 0..2usize {
            let name = format!("{} {:?}", SIXTEENTH_NAMES[n], SIXTEENTH_ARMS[k]);
            let blocks = SIXTEENTH_GAIN_BLOCKS[n][k];
            let Some(read) = SIXTEENTH_GAIN[n][k] else {
                assert!(
                    blocks.is_empty()
                        && SIXTEENTH_BLOCKS[n][k].is_empty()
                        && SIXTEENTH_OPPOSITE[n][k].is_none(),
                    "{name}: an arm with no reading is not pinned"
                );
                continue;
            };
            let carried = images[n]
                .map(|(_, _, gain)| gain)
                .expect("an arm of a network whose derivation wrote an image");
            assert_eq!(
                (
                    blocks.len(),
                    SIXTEENTH_BLOCKS[n][k].len(),
                    read.windows,
                    read.unruled
                ),
                (
                    SCHEDULE_BLOCKS,
                    SCHEDULE_BLOCKS,
                    SCHEDULE_BLOCKS.saturating_mul(BLOCK_WINDOWS),
                    0
                ),
                "{name}: 120 blocks of eight windows, every window's gain the rule's"
            );
            assert_eq!(
                read.band,
                blocks
                    .iter()
                    .map(|b| b.0)
                    .min()
                    .zip(blocks.iter().map(|b| b.1).max()),
                "{name}: the band is the blocks' lowest and highest"
            );
            assert_eq!(
                read.counts.map(|(_, _, summed)| summed),
                Some(blocks.iter().fold(0u64, |sum, b| sum.saturating_add(b.3))),
                "{name}: the count is the blocks' summed"
            );
            assert_eq!(
                read.mean.1,
                (read.windows as u64).saturating_mul(u64::from(carried)),
                "{name}: the mean is read against the gain its network's image carries"
            );
            assert_eq!(
                read.target,
                Some((read.windows as u64).saturating_mul(u64::from(SIXTEENTH_COUNTS[n]))),
                "{name}: the engine carried the network's target"
            );
            assert_eq!(
                read.outside.is_none(),
                blocks.iter().all(|b| gain_within(b.0) && gain_within(b.1)),
                "{name}: no window outside the band is every block's lowest and highest within it"
            );
            let opposite =
                SIXTEENTH_OPPOSITE[n][k].expect("an arm's opposite pairs, pinned with it");
            assert!(
                opposite < SCHEDULE_BLOCKS.saturating_mul(BLOCK_WINDOWS) as u32,
                "{name}: of 959 pairs"
            );
            arm_reads.push(sixteenth_arm_read(n, k).expect("a pinned arm's reading"));
        }
        arms_pinned[n] = SIXTEENTH_GAIN[n].iter().all(Option::is_some);
    }
    let complete =
        (0..3usize).all(|n| rules[n].is_some_and(|rules| !rules.hold() || arms_pinned[n]));
    let verdict = complete.then(|| {
        let arms = [0usize, 1, 2].map(|n| {
            images[n]
                .as_ref()
                .filter(|_| arms_pinned[n])
                .map(|(couplings, sums, _)| {
                    (
                        couplings,
                        outside_image(couplings, sums.1),
                        SIXTEENTH_BLOCKS[n],
                    )
                })
        });
        sixteenth(&rules.map(Option::unwrap_or_default), arms)
    });
    let readings = verdict.map(|verdict| {
        sixteenth_predicted(&verdict.networks.map(|network| network.derived), &arm_reads)
    });
    eprintln!(
        "DUMP sixteenth PIN verdict {verdict:?} step {:?} predicted readings {readings:?}; the arms' readings {arm_reads:?}",
        verdict.map(|verdict| sixteenth_step(&verdict))
    );
    assert_eq!(verdict, SIXTEENTH_1024, "H-39's verdict as written");
    assert_eq!(
        verdict.map(|verdict| sixteenth_step(&verdict)),
        SIXTEENTH_STEP_1024,
        "the step of the stopping rule reached"
    );
    assert_eq!(
        readings, SIXTEENTH_READINGS_READ_1024,
        "ADR-0182's four predicted readings, as read"
    );
}

// ---------- as read from the one run (ADR-0183), its tables in inhibition/pins/h39.rs

/// The step of ADR-0182's stopping rule the verdict reaches: 3, yes.
const SIXTEENTH_STEP_1024: Option<u8> = Some(3);

// ----- the tables the gate reads beside (ADR-0183), its tables in inhibition/pins/h39.rs

/// The inhibitory sum at the end of each of H-38's arms under an eighth beside its image's, as the
/// tree pins them.
const RULED_ENDS: [(i64, i64); 2] = [(127319721, 162864171), (127452842, 162864171)];

/// H-38's arms' pairs of consecutive windows on opposite sides of the target, of 959, as ADR-0181
/// read them from the arms' dumps: pinned by brief 073 and held by every weekly run of those
/// arms.
const RULED_OPPOSITE: [Option<u32>; 2] = [Some(750), Some(758)];

// ---------- pinned from the one run (brief 073), its tables in inhibition/pins/h39.rs

const SEEDED_RATE_CARRIED: [Option<(u32, u32)>; 2] = [Some((114427, 8678)), Some((114573, 0))];
const SEEDED_RATE_AFTER_FROZEN: [Option<(u32, u32)>; 2] = [Some((113141, 0)), Some((112860, 0))];

// --------------------------------------------- written before the run (ADR-0188, ADR-0190)

/// The networks of H-40 (ADR-0188), in their order: H-39's, ADR-0044's generator at 1 024 units
/// from seeds 22, 23 and 24. No other network and no other size is run.
const READ_SEEDS: [u64; 3] = SIXTEENTH_SEEDS;

/// The step of H-40 (ADR-0188), Q0.16, on every network: a sixteenth, H-39's.
const READ_STEP: u16 = SIXTEENTH_STEP;
const _: () = assert!(READ_STEP == 0x1000);

/// The read's span (ADR-0188): 128 windows of the gain held from the lead-in's first, the counts
/// of the last sixteen, windows 113 to 128, summed; `Config::rate_read_windows` (ADR-0189).
const READ_SPAN: u8 = 128;

/// The windows of the read summed: sixteen, ADR-0055's.
const READ_LAST: usize = SETTLED_WINDOWS;
const _: () = assert!(READ_LAST == 16 && READ_SPAN as usize > 2 * READ_LAST);

/// The lead-in's bound (ADR-0188): 320 windows from its first, the read's 128 among them, H-39's.
const READ_BOUND: u64 = RATE_BOUND;
const _: () = assert!(READ_BOUND == 320);

/// The names H-40's dumps carry, per network: a derivation's `rate {name}` and an arm's
/// `ruled {name}`.
const READ_NAMES: [&str; 3] = ["read22", "read23", "read24"];

/// H-40's settling (ADR-0188, ADR-0190): the controller on at a sixteenth, no target set and the
/// read set at 128 windows from the lead-in's first; after the read, H-39's settled network's
/// rule over the excitatory sums and the gain's mean, read over the windows the rule moved the
/// gain in, within `READ_BOUND` windows in all; and a network settled only where the read made a
/// target the rule accepts.
const UNDER_THE_READ: Settling = Settling {
    step: READ_STEP,
    gains: false,
    bound: READ_BOUND,
    target: 0,
    mean: true,
    read: READ_SPAN,
    inhibitory: false,
    probe: false,
};

/// The arms of H-40 (ADR-0188): H-25's two on each network, in their order, each its own weekly
/// test.
const READ_ARMS: [Reversal; 2] = DRAWN_ARMS;

/// ADR-0188's prediction for H-40, written before any run: yes.
const READ_PREDICTED: bool = true;

/// ADR-0188's three predicted readings, in its order, each predicted to hold: each network's read
/// target within five per cent of its derived one, seed 22's below it; in each of the six arms the
/// mean count a window within one per cent of its read target; through each of the six arms the
/// gain after every window within five per cent of 1.75 (`gain_within`). A miss is recorded as
/// one.
const READ_READINGS_PREDICTED: [bool; 3] = [true; 3];

/// Predicted reading 1's band (ADR-0188): a read target within five per cent of the derived one
/// when twenty times their distance is at most the derived one, both ends counted. The target is
/// read as a window's count, the engine's and the derivation's (`SIXTEENTH_COUNTS`), so "below"
/// is a count below: a rate below.
const READ_TARGET_DIVISOR: u64 = 20;

/// Predicted reading 2's band (ADR-0188): an arm's windows' count within one per cent of as many
/// times its read target when a hundred times their distance is at most it, both ends counted.
const READ_COUNT_DIVISOR: u64 = 100;

// ---------------------------------------------------------------- the rules (ADR-0190)

/// What a read of the target left after a lead-in (ADR-0190): the engine's read — under way,
/// refused, or none where it ended in a target — the period and the count the engine then held.
type ReadMade = (Option<TargetRead>, u32, Option<u32>);

/// ADR-0188's read in wider integers, written from its text and not from the engine's code: of
/// the counts of a read's last sixteen windows, the mean to nearest; the period, the units times
/// the window's ticks over it, to nearest; the window's count of that period, to nearest; each a
/// half going up, by doubling. None where the mean is no spike, the period no tick or past the
/// width, or the count no spike or past what a window's bins count.
fn read_target_by_hand(units: u32, sixteen: &[u64]) -> Option<(u32, u32)> {
    if sixteen.len() != READ_LAST {
        return None;
    }
    let sum = sixteen
        .iter()
        .fold(0i128, |sum, &c| sum.saturating_add(i128::from(c)));
    let mean = sum.saturating_mul(2).saturating_add(16).div_euclid(32);
    let ticks = i128::from(units).saturating_mul(i128::from(WINDOW_TICKS));
    if mean == 0 {
        return None;
    }
    let period = ticks
        .saturating_mul(2)
        .saturating_add(mean)
        .div_euclid(mean.saturating_mul(2));
    if period == 0 || period > i128::from(u32::MAX) {
        return None;
    }
    let count = ticks
        .saturating_mul(2)
        .saturating_add(period)
        .div_euclid(period.saturating_mul(2));
    if count == 0 || count > 536_870_880 {
        return None;
    }
    Some((period as u32, count as u32))
}

/// What a lead-in under the read reads of it (ADR-0190), each an integer rule over its table;
/// windows counted from one.
/// - `sixteen`: the spikes of the read's last sixteen windows, 113 to 128; none short of the read.
/// - `target`: the period and the count `read_target_by_hand` makes of them.
/// - `held`: the windows of the read whose gain is not `gain`, the gain before its first.
/// - `after`: `rate_read` over the windows after the read, against the read's count at the step,
///   from the sums and the gain the read's last window left; none without a target.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct ReadRead {
    sixteen: Option<[u64; READ_LAST]>,
    target: Option<(u32, u32)>,
    held: u32,
    after: Option<RateRead>,
}

fn read_read(units: u32, step: u16, gain: u32, table: &[LeadInWindow]) -> ReadRead {
    let span = usize::from(READ_SPAN);
    let read = table.get(..span).unwrap_or(table);
    let sixteen: Option<[u64; READ_LAST]> = table
        .get(span.saturating_sub(READ_LAST)..span)
        .and_then(|windows| {
            windows
                .iter()
                .map(|w| w.0)
                .collect::<Vec<u64>>()
                .try_into()
                .ok()
        });
    let target = sixteen.and_then(|counts| read_target_by_hand(units, &counts));
    let after = target
        .zip(table.get(span.saturating_sub(1)))
        .and_then(|((_, count), last)| {
            table
                .get(span..)
                .map(|rest| rate_read(units, step, count, (last.2, last.3), last.5, rest))
        });
    ReadRead {
        sixteen,
        target,
        held: read.iter().filter(|w| w.5 != gain).count() as u32,
        after,
    }
}

/// Predicted reading 1's rule (ADR-0188): a read count within `READ_TARGET_DIVISOR`'s five per cent
/// of the derived count.
fn read_target_within(read: u32, derived: u32) -> bool {
    u64::from(read.abs_diff(derived)).saturating_mul(READ_TARGET_DIVISOR) <= u64::from(derived)
}

/// Predicted reading 2's rule (ADR-0188): an arm's windows' spikes summed within one per cent of
/// as many times its target.
fn count_within(summed: u64, target: u64) -> bool {
    summed.abs_diff(target).saturating_mul(READ_COUNT_DIVISOR) <= target
}

/// What predicted readings 2 and 3 read of one arm under the read (ADR-0190): its windows'
/// spikes summed and as many times its read target, from its gain's reading, and whether the gain
/// after every window was within the band.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct ReadArm {
    summed: u64,
    target: u64,
    within: bool,
}

/// `ReadArm` of an arm's gain reading; none where the engine carried no target.
fn read_arm_of(read: &GainRead) -> Option<ReadArm> {
    Some(ReadArm {
        summed: read.counts?.2,
        target: read.target?,
        within: gain_readings(read).0,
    })
}

/// ADR-0188's three predicted readings as rules, in its order: every network's read count within
/// five per cent of its derived count and seed 22's below it, none where any network's read is
/// not pinned; and, over the arms given, every arm's count within one per cent of its target and
/// every arm's gain within the band, none where no arm ran. A network whose read made no target
/// does not hold the first.
fn read_predicted(counts: [Option<Option<u32>>; 3], arms: &[ReadArm]) -> [Option<bool>; 3] {
    let first = counts.iter().all(Option::is_some).then(|| {
        (0..3usize).all(|n| {
            counts[n]
                .flatten()
                .is_some_and(|c| read_target_within(c, SIXTEENTH_COUNTS[n]))
        }) && counts[0].flatten().is_some_and(|c| c < SIXTEENTH_COUNTS[0])
    });
    let over = |rule: fn(&ReadArm) -> bool| (!arms.is_empty()).then(|| arms.iter().all(rule));
    [
        first,
        over(|arm| count_within(arm.summed, arm.target)),
        over(|arm| arm.within),
    ]
}

// ------------------------------------------------------------ the criterion (ADR-0188)

/// H-40's verdict (ADR-0188) is H-39's form (`Sixteenth`, `sixteenth`): per network, clause 0 —
/// the read made a target the rule accepts, the lead-in settled after it in its sums and its
/// gain's mean, every later rule gave a value and the frozen block passed both measures, which
/// `Rules::hold` reads with the read folded into `settled` (`derive_under`) — and, where it holds
/// and the arms ran, H-25's four against the image that network's derivation wrote. `yes` when
/// all five hold in both arms on all three networks.
fn read_verdict(rules: &[Rules; 3], arms: [Option<SeededArms<'_>>; 3]) -> Sixteenth {
    sixteenth(rules, arms)
}

/// The step of ADR-0188's stopping rule a verdict reaches: 3, yes; 4, a no on clause 0 on a
/// network; otherwise 5.
fn read_stop(verdict: &Sixteenth) -> u8 {
    if verdict.yes {
        3
    } else if verdict.networks.iter().any(|network| !network.derived) {
        4
    } else {
        5
    }
}

// ------------------------------------------------------------------ the run (brief 074)

/// The lead-in of network `n`'s derivation with the gain held, as the tree pins it: ADR-0077's on
/// seed 22, H-33's on seeds 23 and 24. Under the read the gain is held as it is there, so the
/// read's windows are these, window for window, as far as they ran.
fn gain_held_lead_in(n: usize) -> &'static [LeadInWindow] {
    match n.checked_sub(1) {
        None => BACKGROUND_LEAD_IN_1024[SETTLED],
        Some(m) => LEAD_IN_SEEDED[m],
    }
}

/// The tables H-40's derivation on network `n` is held to, pinned from its one run, as a step of
/// H-38's scan holds them (`RatePins`), the reading the rate's over the windows after the read.
fn read_rate_pins(n: usize) -> RatePins {
    RatePins {
        rules: READ_RULES[n],
        lead_in: READ_LEAD_IN[n],
        quiet: READ_QUIET[n],
        carried: READ_CARRIED[n],
        frozen: READ_FROZEN[n],
        counted: READ_COUNTED[n],
        frozen_census: READ_FROZEN_CENSUS[n],
        after_frozen: READ_AFTER_FROZEN[n],
        target_lead_in: READ_TARGET_LEAD_IN[n],
        crcs: READ_CRCS[n],
        couplings: READ_COUPLINGS[n],
        read: READ_READ[n].and_then(|read| read.after),
    }
}

/// H-40's derivation on network `n`, run and dumped whole before anything of it is held:
/// `derive_under` on the network's prior under the read (`UNDER_THE_READ`), and the lead-in's
/// reading of the read and of the rule after it. A rule that returns nothing, or a read that
/// makes no target, stops the derivation there, which is a reading of clause 0 and is not
/// repaired.
fn read_derivation(n: usize, name: &str) -> (Derivation, ReadRead) {
    let d = derive_under(SCAN_UNITS, READ_SEEDS[n], &UNDER_THE_READ, name);
    dump_derivation(name, &d);
    eprintln!("DUMP {name} PIN carried {:?}", d.carried);
    eprintln!("DUMP {name} PIN after frozen {:?}", d.after_frozen);
    let read = read_read(
        SCAN_UNITS,
        READ_STEP,
        d.rules.gain.unwrap_or(GAIN_1024),
        &d.lead_in,
    );
    eprintln!("DUMP {name} PIN read {read:?}");
    let beside = sixteenth_pins(n).rules.unwrap_or_default();
    eprintln!(
        "DUMP {name} the read's sixteen windows {:?}, summed {:?}; its target {:?} beside the derived {} ticks, {} spikes a window; within five per cent {:?}; the lead-in of {} windows settled at {:?} beside H-39's at a sixteenth {:?} and the gain held's {}; the inhibitory target period {:?} beside H-39's {:?}; clause 0 {}",
        read.sixteen,
        read.sixteen
            .map(|w| w.iter().fold(0u64, |s, &c| s.saturating_add(c))),
        read.target,
        SIXTEENTH_TARGETS[n],
        SIXTEENTH_COUNTS[n],
        read.target
            .map(|(_, count)| read_target_within(count, SIXTEENTH_COUNTS[n])),
        d.lead_in.len(),
        d.rules.settled,
        beside.settled,
        gain_held_lead_in(n).len(),
        d.rules.period,
        beside.period,
        d.rules.hold()
    );
    eprintln!(
        "DUMP {name} the estimate by the rate of its window after the read {:?}",
        estimate_by_rate(
            SCAN_UNITS,
            &[d.lead_in.get(usize::from(READ_SPAN)..).unwrap_or(&[])]
        )
    );
    (d, read)
}

/// H-40's derivation on network `n` held (ADR-0190), after it is dumped, by its rules wherever no
/// table of its own is pinned:
/// - what it makes before the settled network, and its cancel where it was reached, are the
///   network's derivation's with the gain held (`before_the_settling_held` and `cancel_held` on
///   seed 22, `settling_apart` against H-33's on seeds 23 and 24);
/// - the read's windows are the gain held's lead-in, window for window, as far as that ran, and
///   no window of the read moved the gain;
/// - what the engine made of the read is `read_target_by_hand`'s of its sixteen windows: the
///   period and the count, the read ended; or, where the hand rule refuses, the read refused;
/// - every window after the read is the rate's rule's against that count, and no window passed
///   the train;
/// - where its one run is pinned, every table of it (`read_pins_held`).
fn read_derivation_held(n: usize, name: &str, d: &Derivation, read: &ReadRead) {
    match n.checked_sub(1) {
        None => {
            before_the_settling_held(name, d);
            if d.rules.span.is_some() {
                cancel_held(name, d);
            }
        }
        Some(m) => assert_eq!(
            settling_apart(&seeded_site(m).derivation, d),
            Vec::<&str>::new(),
            "{name}: what the derivation makes before the settled network, and its cancel, are the gain held's"
        ),
    }
    let held = gain_held_lead_in(n);
    assert!(held.len() <= usize::from(READ_SPAN));
    assert_eq!(
        d.lead_in.get(..held.len()),
        Some(held),
        "{name}: the read's windows are the gain held's lead-in, window for window"
    );
    assert_eq!(read.held, 0, "{name}: no window of the read moved the gain");
    let made = match read.target {
        Some((period, count)) => (None, period, Some(count)),
        None => (Some(TargetRead::Refused), 0, None),
    };
    assert_eq!(
        d.read,
        Some(made),
        "{name}: what the engine made of the read is the hand rule's of its sixteen windows"
    );
    if let Some(after) = read.after {
        assert_eq!(
            after.unruled, 0,
            "{name}: every window after the read is the rate's rule's"
        );
        let capacity = config(SCAN_UNITS, 2, BASELINE_Q16).train_capacity as u64;
        assert!(
            after
                .counts
                .is_none_or(|(_, greatest)| greatest <= capacity),
            "{name}: the train held every window read from it"
        );
    }
    if READ_RULES[n].is_some() {
        read_pins_held(name, n, d, read);
    } else {
        assert!(
            READ_LEAD_IN[n].is_empty() && READ_READ[n].is_none() && READ_MADE[n].is_none(),
            "{name}: a derivation pinned whole or not at all"
        );
        eprintln!(
            "DUMP {name} not pinned: the derivation's one run (ADR-0190), its tables written from this log"
        );
    }
}

/// H-40's derivation on network `n` held to the tables pinned from its one run: H-38's
/// (`rate_pins_held`'s) but the images at the format that round read, 23, through each image
/// with its header's version written back to it since ADR-0194 (`READ_TARGET_FORMAT`), and the
/// read's reading and what the engine made of it.
fn read_pins_held(name: &str, n: usize, d: &Derivation, read: &ReadRead) {
    let pins = read_rate_pins(n);
    assert_eq!(Some(d.rules), pins.rules, "{name}: what each rule returned");
    assert_eq!(d.lead_in.as_slice(), pins.lead_in, "{name}: the lead-in");
    assert_eq!(d.quiet, pins.quiet, "{name}: the quiet run");
    assert_eq!(d.carried, pins.carried, "{name}: what the image carries");
    assert_eq!(d.frozen, pins.frozen, "{name}: the frozen block");
    assert_eq!(
        d.counted.as_slice(),
        pins.counted,
        "{name}: the frozen block's counts"
    );
    assert_eq!(
        d.frozen_census.as_slice(),
        pins.frozen_census,
        "{name}: the frozen block's census"
    );
    assert_eq!(
        d.after_frozen, pins.after_frozen,
        "{name}: the gain and the estimate after the frozen block"
    );
    assert_eq!(
        d.target_lead_in.as_slice(),
        pins.target_lead_in,
        "{name}: the target's lead-in"
    );
    assert_eq!(
        d.crcs_read_target, pins.crcs,
        "{name}: the images, each with its header's version written back to the format H-40 read"
    );
    assert_eq!(d.couplings, pins.couplings, "{name}: the image's couplings");
    assert_eq!(Some(*read), READ_READ[n], "{name}: the read's reading");
    assert_eq!(
        d.read, READ_MADE[n],
        "{name}: what the engine made of the read"
    );
}

/// H-40's derivation on network `n` (brief 074), a test of its own: `read_derivation`, then
/// `read_derivation_held`.
fn read_derived(n: usize) {
    let name = format!("rate {}", READ_NAMES[n]);
    let (d, read) = read_derivation(n, &name);
    read_derivation_held(n, &name, &d, &read);
}

/// H-40's network of index `n` for its arms, at a sixteenth under its read target, with the tables
/// its arms' one run pinned.
fn read_site(n: usize) -> RuledSite {
    RuledSite {
        step: RATE_SIXTEENTH,
        network: n,
        name: format!("ruled {}", READ_NAMES[n]),
        arms: [0usize, 1].map(|k| ArmPins {
            blocks: READ_ARM_BLOCKS[n][k],
            trace: READ_ARM_TRACES[n][k],
            composed: READ_ARM_COMPOSED[n][k],
            earned: READ_ARM_EARNED[n][k],
            read: READ_ARM_READ[n][k],
            values: READ_ARM_VALUES[n][k],
            value_hash: READ_ARM_VALUE_HASH[n][k],
            sourced: READ_ARM_SOURCED[n][k],
            sources_hash: READ_ARM_SOURCES_HASH[n][k],
            readings: READ_ARM_READINGS[n][k],
            critic: READ_ARM_CRITIC[n][k],
            whole: READ_ARM_WHOLE[n][k],
        }),
        gains: [0usize, 1].map(|k| GainPins {
            blocks: READ_ARM_GAIN_BLOCKS[n][k],
            read: READ_ARM_GAIN[n][k],
            opposite: READ_ARM_OPPOSITE[n][k],
        }),
        read: true,
        inhibitory: false,
        probe: false,
    }
}

/// An H-40 network as its arms' tables are read against it: the settled sums and the image's
/// couplings its derivation pinned, and, as the arms its own are read beside, that network's two
/// under H-39, each network beside its own arms under H-39 as ADR-0188's readings ask. A network
/// whose derivation is not pinned has no stand, and no arm runs on it.
fn read_stand(site: &RuledSite) -> Stand {
    let pins = read_rate_pins(site.network);
    let (_, sums) = pins
        .quiet
        .expect("the settled image's sums: an arm runs from a pinned derivation");
    let couplings = pins
        .couplings
        .expect("the image's couplings: an arm runs from a pinned derivation");
    let rotation = pins
        .rules
        .and_then(|rules| rules.rotation)
        .expect("the rotation: an arm runs from a pinned derivation");
    let beside = sixteenth_site(site.network);
    let own = [0usize, 1].map(|k| {
        let arm = &beside.arms[k];
        let read = arm.readings.expect("H-39's arm's readings");
        Own {
            blocks: arm.blocks,
            values: arm.values,
            crossings: read.crossings,
            troughs: read.troughs,
            signal: arm.whole.map(|whole| whole.read.signal),
            strong: arm.whole.map(|whole| whole.read.strong),
            whole: arm.whole,
        }
    });
    Stand {
        len: geometry(SCAN_UNITS, rotation)[0].len(),
        sums,
        couplings,
        own,
        apart: [beside.arms[0].blocks, beside.arms[1].blocks],
    }
}

/// An H-40 network's calibration and what a rewarded run takes from it: its derivation under
/// the read, dumped and held as its own test holds it, to the tables its one run pinned; on a
/// network whose clause 0 does not hold, no arm.
fn read_made(n: usize, name: &str) -> Made {
    let (mut d, read) = read_derivation(n, name);
    read_derivation_held(n, name, &d, &read);
    assert!(
        READ_RULES[n].is_some(),
        "{name}: an arm runs from its network's pinned derivation"
    );
    assert!(
        d.rules.hold(),
        "{name}: clause 0 holds on this network, or it has no arm"
    );
    eprintln!("DUMP {name} calibration holds: the derivation under the read is the one pinned");
    d.made
        .take()
        .expect("a derivation whose rules hold makes a configuration")
}

/// One arm of H-40 (ADR-0188, brief 074): H-25's arm on network `n` from the image its derivation
/// under the read wrote, the step and the read target carried through every trial — `arm_on` on
/// its `RuledSite`, under the true reward. Its calibration is the network's derivation run again
/// and held as its own test holds it.
fn read_arm(n: usize, arm: Reversal) {
    arm_on(Ground::Ruled(&read_site(n)), None, arm);
}

