// ------------------------------------------- the two services, alternated (brief 084)

/// What one run of brief 084's alternation leaves, to be held to its round's run under the
/// other service (ADR-0224): the hash of every unit's 64 bytes and every block's at its end, the
/// mailbox head read as holding mail or not; the messages delivered, and those its drive sent;
/// the spikes; the turns served and the steps caught up.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct Ran {
    arena: u64,
    delivered: u64,
    sent: u64,
    spikes: u64,
    turns: u64,
    caught_up: u64,
}

/// FNV-1a over every unit's 64 bytes and every block's, as `encode` writes them, atomics as
/// plain values. The mailbox head is a node index from a worker's pool, whose order the two
/// workers' frees in one phase set (ADR-0099's scheduler bytes): it is hashed as whether the
/// mailbox holds a message (exploration 008).
fn arena_hash(exec: &Engine) -> u64 {
    let mut hash: u64 = 0xcbf2_9ce4_8422_2325;
    let units = exec.units().iter().map(|u| {
        let mut bytes = u.encode();
        bytes[8..16].copy_from_slice(&u64::from(!u.mailbox_is_empty()).to_le_bytes());
        bytes
    });
    let blocks = exec.blocks().iter().map(|b| b.encode());
    for record in units.chain(blocks) {
        for byte in record {
            hash ^= u64::from(byte);
            hash = hash.wrapping_mul(0x0000_0100_0000_01b3);
        }
    }
    hash
}

/// The engine's `Ran` at its end, the drive having sent `sent`. The arena is read first, which
/// brings every asleep unit up to date, so that its steps are counted.
fn ran(exec: &mut Engine, sent: u64) -> Ran {
    let arena = arena_hash(exec);
    Ran {
        arena,
        delivered: exec.delivered(),
        sent,
        spikes: (exec.train().len() as u64).saturating_add(exec.train_overwritten()),
        turns: exec.turns(),
        caught_up: exec.caught_up(),
    }
}

/// Exploration 008's workload, exploration 006's: H-45's control on seed 22 from the assignment,
/// `untold_arm(0, Reversal::AssignmentFirst, 0)`, over its derivation and the first 16 of its
/// 120 blocks. The derivation is held whole, as `probe_made` holds it, and the blocks are the
/// first 16 of H-42's arm's, with no move. Returns its `Ran` and its milliseconds.
fn alternated_control(service: &str) -> (Ran, u128) {
    const BLOCKS: usize = 16;
    let clock = std::time::Instant::now();
    let (n, arm, delay) = (0usize, Reversal::AssignmentFirst, 0u8);
    let k = UNTOLD_ARMS
        .iter()
        .position(|&a| a == arm)
        .expect("an arm of H-25's two");
    let name = format!(
        "{} delay {delay} {arm:?} over {BLOCKS} blocks {service}",
        UNTOLD_NAMES[n]
    );
    let mut end = None;
    let (_, run) = untold_run_over(
        n,
        arm,
        delay,
        false,
        &name,
        BLOCKS.saturating_mul(BLOCK),
        &mut |exec| end = Some(ran(exec, 0)),
    );
    let millis = clock.elapsed().as_millis();
    eprintln!("DUMP {name} PIN blocks {:?}", run.blocks);
    assert_eq!(
        Some(run.blocks.as_slice()),
        PROBE_ARM_BLOCKS[n][k].get(..BLOCKS),
        "{name}: the blocks run are the first of H-42's arm's"
    );
    assert_eq!(run.moved, None, "{name}: no move");
    (end.expect("the run's end"), millis)
}

/// The ticks of a sparse run: under per-tick service about 1.5 µs a tick at 1 024 units, by
/// ADR-0101's timed run of the same drive in the cost table, so that each run lasts more than a
/// minute.
const SPARSE_TICKS: u64 = 1 << 27;

/// The reference network at 1 024 units, ADR-0097's, under its drive 256 times sparser, run (c):
/// one message every 32nd tick, for `SPARSE_TICKS`. Returns its `Ran` and its milliseconds, the
/// network built before the clock starts.
fn alternated_sparse() -> (Ran, u128) {
    let units = 1024;
    let mut exec = at_gain(&prior(units), config(units, 2, 0), GAIN_1024);
    let drive = Drive {
        every: 32,
        messages: 1,
        ..drive(units)
    };
    let inject = exec.injector();
    let mut sent = 0u64;
    let clock = std::time::Instant::now();
    for _ in 0..SPARSE_TICKS {
        let messages = drive.step(&inject, exec.ticks()).expect("the drive runs");
        sent = sent.saturating_add(u64::from(messages));
        exec.tick();
    }
    let millis = clock.elapsed().as_millis();
    (ran(&mut exec, sent), millis)
}

/// `run` with every engine the harness's `served` passes on this thread served per tick, the
/// tests' reference (ADR-0224): one run of the alternation.
fn served_per_tick<R>(run: impl FnOnce() -> R) -> R {
    let was = PER_TICK.replace(true);
    let result = run();
    PER_TICK.set(was);
    result
}

/// One round's two runs of `workload`, served per tick (`served_per_tick`) and on arrival, in the
/// order `per_tick_first` gives, each printed as a `TIME` line and a `RAN` line; the run on
/// arrival held to the run per tick: the same arena, messages and spikes, and its turns and
/// steps together the per-tick run's turns.
fn alternated(
    round: u32,
    what: &str,
    per_tick_first: bool,
    workload: impl Fn(&str) -> (Ran, u128),
) {
    let per_tick = || served_per_tick(|| workload("per tick"));
    let arrival = || workload("on arrival");
    let (per_tick, arrival) = if per_tick_first {
        let p = per_tick();
        (p, arrival())
    } else {
        let a = arrival();
        (per_tick(), a)
    };
    for (service, (r, millis)) in [("per tick", per_tick), ("on arrival", arrival)] {
        eprintln!("TIME round {round} {what} {service} {millis}");
        eprintln!("RAN round {round} {what} {service} {r:?}");
    }
    let (p, a) = (per_tick.0, arrival.0);
    assert_eq!(
        p.caught_up, 0,
        "round {round}, {what}: per tick catches nothing up"
    );
    assert!(a.turns < p.turns, "round {round}, {what}: units slept");
    assert_eq!(
        (a.arena, a.delivered, a.sent, a.spikes),
        (p.arena, p.delivered, p.sent, p.spikes),
        "round {round}, {what}: the arena, the messages and the spikes"
    );
    assert_eq!(
        a.turns.saturating_add(a.caught_up),
        p.turns,
        "round {round}, {what}: the turns of per-tick service, served or caught up"
    );
}

/// Brief 084's alternation (ADR-0224, ADR-0225), by a dispatch at `scope=arms` on AArch64: in
/// one process, three rounds of exploration 008's 16-block workload and of the reference network
/// at 1 024 units under ADR-0097's sparse drive, each under both services, per tick first in the
/// first and third rounds and second in the second. Each run builds its own executors and
/// network. Not a whole-domain test, and not an exploration's.
#[test]
#[ignore]
fn on_arrival_and_per_tick_service_alternate_on_one_runner_timed() {
    for round in 1..=3u32 {
        let per_tick_first = round != 2;
        alternated(round, "16 blocks", per_tick_first, alternated_control);
        alternated(round, "sparse", per_tick_first, |_| alternated_sparse());
    }
    eprintln!("DUMP the two services alternated: every run held");
}

/// The gate's test (ADR-0061's class; brief 082): H-45's networks, delays, arms, constants,
/// prediction and predicted readings; clause 1's, clause 2's and clause 3's rules, the mapping of
/// a trial, the readings' rules and the verdict's steps at their edges over tables written by
/// hand; and, over H-45's pinned tables, the verdict, its step and the three readings as written
/// (`untold_tables`). It runs no trial. Nothing else added to the gate.
#[test]
fn the_delay_read_of_h_45_its_clauses_and_its_predicted_readings_rules() {
    assert_eq!(UNTOLD_SEEDS, [22, 23, 24]);
    assert_eq!(
        (KEPT_ADDRESSES, UNTOLD_AGES, UNTOLD_DELAYS),
        (2, 3, [1, 2]),
        "ADR-0216's"
    );
    assert_eq!(
        UNTOLD_ARMS,
        [Reversal::AssignmentFirst, Reversal::MirroredFirst]
    );
    assert_eq!(
        (DELAY_WINDOW, DELAY_RUN, DELAY_LEAD_SHIFT),
        (64, 64, 5),
        "ADR-0216's window, run and lead, a thirty-second"
    );
    assert_eq!(
        (UNTOLD_PREDICTED, UNTOLD_READINGS_PREDICTED),
        (true, [true; 3]),
        "ADR-0216 predicts yes, and each of its three readings"
    );
    assert_eq!(
        (
            LAST_MAPPING_FROM,
            FIRST_MAPPING_TO,
            EARLY_ARMS,
            TOLD_QUARTERS
        ),
        (5_632, 1_536, 8, (5, 4))
    );
    // Clause 1 at its edges.
    let at = |trial: usize, age: u8| Some((trial, age, [0u64; UNTOLD_AGES]));
    assert!(moved_right(at(5_631, 1), 1));
    assert!(moved_right(at(0, 2), 2));
    assert!(!moved_right(at(5_632, 1), 1), "the last mapping begun");
    assert!(!moved_right(at(100, 2), 1), "a wrong age");
    assert!(!moved_right(at(100, 0), 1), "age zero");
    assert!(!moved_right(None, 1), "no move");
    // The mapping of a trial.
    assert_eq!(
        [0, 1_535, 1_536, 3_583, 3_584, 5_631, 5_632, 7_679, 7_680].map(mapping_of),
        [
            Some(0),
            Some(0),
            Some(1),
            Some(1),
            Some(2),
            Some(2),
            Some(3),
            Some(3),
            None
        ]
    );
    // Clause 2 over the hand table: every block at 64 correct, the image's couplings and sums.
    let image = [[10_000i64, 10_000], [10_000, 10_000]];
    let excitatory = 140_000i64;
    let outside = outside_image(&image, excitatory);
    let blocks: Vec<Block> = (0..SCHEDULE_BLOCKS)
        .map(|_| kept_hand_block(64, image, excitatory))
        .collect();
    assert_eq!(
        after_clauses(&image, outside, &blocks, at(100, 1)),
        [true; 4]
    );
    assert_eq!(
        after_clauses(&image, outside, &blocks, at(5_631, 1)),
        [true; 4]
    );
    assert_eq!(
        after_clauses(&image, outside, &blocks, at(5_632, 1)),
        [false; 4],
        "a move in the last mapping"
    );
    assert_eq!(after_clauses(&image, outside, &blocks, None), [false; 4]);
    assert_eq!(
        after_clauses(&image, outside, &blocks[..119], at(100, 1)),
        [false; 4],
        "a run short of 120 blocks"
    );
    // A mapping before the move's unlearned, and after it.
    let mut unlearned = blocks.clone();
    for block in unlearned.iter_mut().take(MAPPINGS[1].1).skip(MAPPINGS[1].0) {
        block.0 = 20;
    }
    assert_eq!(
        after_clauses(&image, outside, &unlearned, at(100, 1)),
        [false, true, false, true],
        "the second mapping, after the move, unlearned and its reversal never crossed"
    );
    assert_eq!(
        after_clauses(&image, outside, &unlearned, at(1_536, 1)),
        [true; 4],
        "the move in the second mapping: neither counted"
    );
    // A coupling past 1.30 and the band left, before the next mapping's first block and in it.
    let mut over = blocks.clone();
    over[MAPPINGS[1].0.saturating_sub(1)].10[0][1] = 13_001;
    assert_eq!(after_clauses(&image, outside, &over, at(100, 1)), [true; 4]);
    over[MAPPINGS[1].0].10[0][1] = 13_001;
    assert_eq!(
        after_clauses(&image, outside, &over, at(100, 1)),
        [true, false, true, true]
    );
    let mut left = blocks.clone();
    left[MAPPINGS[2].0.saturating_sub(1)].8 = excitatory.saturating_sub(25_001);
    assert_eq!(
        after_clauses(&image, outside, &left, at(2_000, 1)),
        [true; 4],
        "left in the move's mapping"
    );
    assert_eq!(
        after_clauses(&image, outside, &left, at(100, 1)),
        [true, true, true, false]
    );
    // A reversal slow in the last mapping: the 24th block, then the 23rd.
    let mut slow = blocks.clone();
    for block in slow.iter_mut().skip(MAPPINGS[3].0).take(23) {
        block.0 = 39;
    }
    assert_eq!(
        after_clauses(&image, outside, &slow, at(4_000, 2)),
        [true, true, false, true]
    );
    slow[MAPPINGS[3].0.saturating_add(22)].0 = 40;
    assert_eq!(
        after_clauses(&image, outside, &slow, at(4_000, 2)),
        [true; 4]
    );
    // Clause 3.
    assert!(control_held(&UntoldControl {
        moved: None,
        h42: true
    }));
    assert!(!control_held(&UntoldControl {
        moved: at(7_000, 1),
        h42: true
    }));
    assert!(!control_held(&UntoldControl {
        moved: None,
        h42: false
    }));
    // The readings' rules at their edges.
    let arm = |trial: Option<usize>, whole: [bool; 4], reversals: u32| UntoldArm {
        moved: trial.map(|t| (t, 1, [0u64; UNTOLD_AGES])),
        whole,
        reversals,
    };
    assert!(moved_early(&arm(Some(1_535), [true; 4], 40)));
    assert!(!moved_early(&arm(Some(1_536), [true; 4], 40)));
    assert!(!moved_early(&arm(None, [true; 4], 40)));
    assert!(within_told(50, 40) && !within_told(51, 40));
    assert!(within_told(0, 0) && !within_told(1, 0));
    let early = Some(arm(Some(300), [true; 4], 40));
    let mut arms = [[[early; 2]; 2]; 3];
    let told = [[[40u32; 2]; 2]; 3];
    assert_eq!(untold_predicted(arms, told), [Some(true); 3]);
    // Eight early, four late with nothing else held: reading 1 at its edge.
    for network in arms.iter_mut().skip(1) {
        network[1] = [Some(arm(Some(1_536), [false; 4], 96)); 2];
    }
    assert_eq!(
        untold_predicted(arms, told),
        [Some(true); 3],
        "eight of twelve"
    );
    arms[0][1][0] = Some(arm(None, [false; 4], 96));
    assert_eq!(
        untold_predicted(arms, told),
        [Some(false), Some(true), Some(true)],
        "seven of twelve"
    );
    let mut whole = [[[early; 2]; 2]; 3];
    whole[2][0][1] = Some(arm(Some(300), [true, true, false, true], 40));
    assert_eq!(untold_predicted(whole, told)[1], Some(false));
    let mut slower = [[[early; 2]; 2]; 3];
    slower[1][1][1] = Some(arm(Some(300), [true; 4], 51));
    assert_eq!(untold_predicted(slower, told)[2], Some(false));
    slower[1][1][1] = Some(arm(Some(300), [true; 4], 50));
    assert_eq!(untold_predicted(slower, told)[2], Some(true), "at 1.25");
    let none = [[[Some(arm(None, [false; 4], 96)); 2]; 2]; 3];
    assert_eq!(
        untold_predicted(none, told),
        [Some(false), Some(true), Some(true)],
        "over no arm moved early, readings 2 and 3 vacuous"
    );
    let mut short = [[[early; 2]; 2]; 3];
    short[2][1][1] = None;
    assert_eq!(untold_predicted(short, told), [None; 3]);
    // The verdict and the stopping rule's steps.
    let (moved, after, controls) = (
        [[[true; 2]; 2]; 3],
        [[[[true; 4]; 2]; 2]; 3],
        [[true; 2]; 3],
    );
    let all = untold_verdict(moved, after, controls);
    assert!(all.yes);
    assert_eq!(untold_stop(&all), 3);
    let mut one = moved;
    one[1][0][1] = false;
    assert_eq!(untold_stop(&untold_verdict(one, after, controls)), 4);
    let mut three = controls;
    three[2][0] = false;
    let no_three = untold_verdict(moved, after, three);
    assert_eq!((no_three.yes, untold_stop(&no_three)), (false, 5));
    assert_eq!(
        untold_stop(&untold_verdict(one, after, three)),
        4,
        "clause 1 first"
    );
    let mut two = after;
    two[0][1][0][3] = false;
    let no_two = untold_verdict(moved, two, controls);
    assert_eq!((no_two.yes, untold_stop(&no_two)), (false, 6));
    untold_tables();
}

/// The gate's checks over H-45's pinned tables (ADR-0218), by the rules committed before any of
/// them was run, each where it is pinned. An arm's blocks, trace, hash, table, move and rewards
/// lost are pinned together, its table of 120 blocks whose rewards are its trials less its delay
/// and its rewards lost. Then, where every arm and control is pinned, the verdict by the three
/// clauses against the image each network's derivation wrote, its step and the three readings,
/// each as written; before that, none is.
fn untold_tables() {
    let mut moved = [[[false; 2]; 2]; 3];
    let mut after = [[[[false; 4]; 2]; 2]; 3];
    let mut controls = [[false; 2]; 3];
    let mut arms: [[[Option<UntoldArm>; 2]; 2]; 3] = [[[None; 2]; 2]; 3];
    let mut told = [[[0u32; 2]; 2]; 3];
    let mut complete = true;
    for n in 0..3usize {
        let pins = probe_rate_pins(n);
        let couplings = pins.couplings.expect("H-42's derivation, pinned");
        let (_, sums) = pins.quiet.expect("H-42's settled image's sums, pinned");
        let outside = outside_image(&couplings, sums.1);
        for k in 0..2usize {
            match UNTOLD_CONTROLS[n][k] {
                Some(control) => controls[n][k] = control_held(&control),
                None => complete = false,
            }
            for (d, &delay) in UNTOLD_DELAYS.iter().enumerate() {
                let name = format!("{} delay {delay} {:?}", UNTOLD_NAMES[n], UNTOLD_ARMS[k]);
                told[n][d][k] = reversals_summed(crossings(KEPT_ARM_BLOCKS[n][d][k]));
                let (blocks, trace, hash, table, move_pin, lost) = untold_pins(n, d, k);
                if blocks.is_empty() {
                    assert!(
                        trace == 0
                            && hash == 0
                            && table.is_empty()
                            && move_pin.is_none()
                            && lost == 0,
                        "{name}: an arm pinned whole or not at all"
                    );
                    complete = false;
                    continue;
                }
                assert_eq!(
                    (blocks.len(), table.len()),
                    (SCHEDULE_BLOCKS, SCHEDULE_BLOCKS),
                    "{name}: 120 blocks"
                );
                assert!(trace != 0 && hash != 0, "{name}: a sequence and its values");
                assert_eq!(
                    table
                        .iter()
                        .fold(0usize, |sum, b| sum.saturating_add(b.1 as usize)),
                    SCHEDULE_TRIALS
                        .saturating_sub(usize::from(delay))
                        .saturating_sub(lost as usize),
                    "{name}: a reward at every trial's end but the first `delay` and those lost"
                );
                moved[n][d][k] = moved_right(move_pin, delay);
                after[n][d][k] = after_clauses(&couplings, outside, blocks, move_pin);
                arms[n][d][k] = Some(UntoldArm {
                    moved: move_pin,
                    whole: kept_clauses(&couplings, outside, blocks),
                    reversals: reversals_summed(crossings(blocks)),
                });
            }
        }
    }
    let verdict = complete.then(|| untold_verdict(moved, after, controls));
    let readings = verdict.map(|_| untold_predicted(arms, told));
    eprintln!(
        "DUMP untold PIN verdict {verdict:?} step {:?} predicted readings {readings:?}; the arms' readings {arms:?}; the told arms' reversals {told:?}",
        verdict.map(|verdict| untold_stop(&verdict))
    );
    assert_eq!(verdict, UNTOLD_1024, "H-45's verdict as written");
    assert_eq!(
        verdict.map(|verdict| untold_stop(&verdict)),
        UNTOLD_STOP_1024,
        "the step of the stopping rule reached"
    );
    assert_eq!(
        readings, UNTOLD_READINGS_READ_1024,
        "ADR-0216's three predicted readings, as read"
    );
}

// ---------- as read from the one run (ADR-0218), its tables in inhibition/pins/h45.rs

/// The step of ADR-0216's stopping rule the verdict reaches: 3, yes.
const UNTOLD_STOP_1024: Option<u8> = Some(3);
/// ADR-0216's three predicted readings, as read: all three held. Nine arms of twelve moved inside
/// the first mapping; each held H-25's four clauses over the whole arm, and its reversals within
/// 1.25 of its told arm's.
const UNTOLD_READINGS_READ_1024: Option<[Option<bool>; 3]> = Some([Some(true); 3]);

const UNTOLD_ARM_LOST: [[[u32; 2]; 2]; 3] = [[[1, 1], [2, 2]], [[1, 1], [2, 2]], [[1, 1], [2, 2]]];

// =================================================================================== H-46

// ------------------------------------------- written before the run (ADR-0226, ADR-0229)

/// The networks of H-46 (ADR-0226): H-42's, ADR-0044's generator at 1 024 units from seeds 22, 23
/// and 24, each from the image an engine born under `Config::reads_its_targets()` settles. No
/// other network is run.
const ZERO_SEEDS: [u64; 3] = PROBE_SEEDS;

/// The arms of H-46 (ADR-0226): H-25's two on H-20's schedule, under the answer.
const ZERO_ARMS: [Reversal; 2] = PROBE_ARMS;

/// The schedules of a long run (ADR-0226), back to back, each from the image the one before
/// left; and a job's, the eighth image carried from the first half's job to the second's.
const ZERO_SCHEDULES: usize = 16;
const ZERO_HALF: usize = 8;

/// The depression's exponent of H-46's arms (ADR-0226): a quarter. Its controls are at one.
const ZERO_EXPONENT: DepressionExponent = DepressionExponent::Quarter;

/// ADR-0226's prediction for H-46, written before any run: yes.
const ZERO_PREDICTED: bool = true;

/// ADR-0226's four predicted readings, in its order, each predicted to hold. A miss is recorded
/// as one and decides nothing.
const ZERO_READINGS_PREDICTED: [bool; 4] = [true; 4];

/// The schedules predicted readings 1 and 4 read: 9 to 16, here by index.
const ZERO_LATE: core::ops::Range<usize> = 8..16;

/// Predicted reading 1's bound (ADR-0226): an arm's reversals over schedules 9 to 16 at most 1.25
/// times its control's, read in integers as `arm × 4 ≤ control × 5`.
const ZERO_SPEED_QUARTERS: (u32, u32) = (5, 4);

/// Predicted reading 2's bound (ADR-0226): each coupling at most 1.25 of H-42's image's.
const ZERO_HIGHEST_QUARTERS: (i64, i64) = (5, 4);

/// Predicted reading 3's bound (ADR-0226): a schedule that starts with half or more of its
/// couplings' synapses in the bottom eighth of the width sums its reversals at 16 blocks or
/// fewer. The bottom eighth is the first two sixteenths of `ZeroRow::bins`.
const ZERO_SPLIT_REVERSALS: u32 = 16;
const ZERO_BOTTOM_EIGHTH: usize = 2;

/// Predicted reading 4's band (ADR-0226): the inhibitory sum within 0.45 and 0.65 of H-42's
/// image's, in hundredths.
const ZERO_INHIBITORY_HUNDREDTHS: (i64, i64) = (45, 65);

const _: () = assert!(ZERO_HALF * 2 == ZERO_SCHEDULES && ZERO_LATE.end == ZERO_SCHEDULES);

/// A form of a long run (ADR-0226): `ZERO_CONTROL`, the default with both rules unset; or
/// `ZERO_ARM`, the zero sum carried and the exponent at a quarter. Each indexes `ZERO_NAMES` and
/// the second index of the pinned tables.
const ZERO_CONTROL: usize = 0;
const ZERO_ARM: usize = 1;

/// The names H-46's dumps carry, per network and form.
const ZERO_NAMES: [[&str; 2]; 3] = [
    ["default22", "zero22"],
    ["default23", "zero23"],
    ["default24", "zero24"],
];

// ---------------------------------------------------------------- the rules (ADR-0229)

/// A coupling's synapses by sixteenths of the width: `[A→R0, A→R1, B→R0, B→R1]`.
type Bins = [[u32; 16]; 4];

/// One schedule of a long run as its tables pin it (ADR-0229): its trial sequence's hash, its
/// values' hash and the CRC-64 of the image it wrote; H-25's four clauses (`kept_clauses`), every
/// coupling against H-42's image on its network; each mapping's last 128 correct and its crossing
/// (`crossings`); each coupling's highest and lowest over the blocks' ends, and the inhibitory
/// sum's, lowest then highest; each coupling's most synapses at the rail at a block's end; and
/// the image it wrote by sixteenths of the width.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct ZeroRow {
    trace: u64,
    values: u64,
    image: u64,
    clauses: [bool; 4],
    correct: [u32; 4],
    crossed: [Option<usize>; 4],
    highest: [[i64; 2]; 2],
    lowest: [[i64; 2]; 2],
    inhibitory: (i64, i64),
    rail: [u32; 4],
    bins: Bins,
}

/// Clause 1's four on one arm (ADR-0226): each of H-25's four in every one of the sixteen
/// schedules; all false for a run of any other length.
fn zero_clauses(rows: &[ZeroRow]) -> [bool; 4] {
    core::array::from_fn(|c| rows.len() == ZERO_SCHEDULES && rows.iter().all(|r| r.clauses[c]))
}

/// Clause 2 on one control (ADR-0226): some coupling past 1.30 of H-42's image's at a block's end
/// of one of the sixteen schedules, which is H-25's second clause false there.
fn zero_passed(rows: &[ZeroRow]) -> bool {
    rows.len() == ZERO_SCHEDULES && rows.iter().any(|r| !r.clauses[1])
}

/// H-46's verdict (ADR-0226): clause 1's four per network and arm, `[network][arm]` in
/// `ZERO_ARMS`' order; clause 2 per network and arm. `yes` when both hold in all twelve runs.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct ZeroVerdict {
    arms: [[[bool; 4]; 2]; 3],
    controls: [[bool; 2]; 3],
    yes: bool,
}

fn zero_verdict(arms: [[[bool; 4]; 2]; 3], controls: [[bool; 2]; 3]) -> ZeroVerdict {
    ZeroVerdict {
        arms,
        controls,
        yes: arms.iter().flatten().flatten().all(|&c| c) && controls.iter().flatten().all(|&c| c),
    }
}

/// The step of ADR-0226's stopping rule a verdict reaches, the first that applies: 3, yes; 4, a
/// no on clause 1 by a coupling; 5, by learning, a mapping or a reversal; 6, by the excitatory sum
/// outside the couplings; otherwise 7, a no on clause 2.
fn zero_stop(verdict: &ZeroVerdict) -> u8 {
    if verdict.yes {
        return 3;
    }
    let any = |clause: usize| verdict.arms.iter().flatten().any(|c| !c[clause]);
    if any(1) {
        return 4;
    }
    if any(0) || any(2) {
        return 5;
    }
    if any(3) {
        return 6;
    }
    7
}

/// The reversals of schedules 9 to 16, summed (`reversals_summed`).
fn zero_late_reversals(rows: &[ZeroRow]) -> u32 {
    rows.get(ZERO_LATE)
        .unwrap_or(&[])
        .iter()
        .fold(0u32, |sum, r| {
            sum.saturating_add(reversals_summed(r.crossed))
        })
}

/// Predicted reading 1's rule on one arm beside its control.
fn zero_speed_held(arm: u32, control: u32) -> bool {
    arm.saturating_mul(ZERO_SPEED_QUARTERS.1) <= control.saturating_mul(ZERO_SPEED_QUARTERS.0)
}

/// Predicted reading 2's rule on one arm: every coupling's highest, over all its schedules, at
/// most 1.25 of the image's.
fn zero_highest_held(rows: &[ZeroRow], image: &[[i64; 2]; 2]) -> bool {
    rows.iter().all(|r| {
        ALL_PAIRS.iter().all(|&(s, x)| {
            r.highest[s][x].saturating_mul(ZERO_HIGHEST_QUARTERS.1)
                <= image[s][x].saturating_mul(ZERO_HIGHEST_QUARTERS.0)
        })
    })
}

/// Whether half or more of an image's couplings' synapses stand in the bottom eighth of the width.
fn zero_split(bins: &Bins) -> bool {
    let total = bins
        .iter()
        .flatten()
        .fold(0u32, |n, &c| n.saturating_add(c));
    let bottom = bins.iter().fold(0u32, |n, coupling| {
        coupling
            .iter()
            .take(ZERO_BOTTOM_EIGHTH)
            .fold(n, |n, &c| n.saturating_add(c))
    });
    total > 0 && bottom.saturating_mul(2) >= total
}

/// Predicted reading 3's rule on one run, from `start`, the image its first schedule starts from:
/// none where no schedule starts split, which does not read it; otherwise whether every one that
/// does sums its reversals at `ZERO_SPLIT_REVERSALS` blocks or fewer.
fn zero_split_held(rows: &[ZeroRow], start: &Bins) -> Option<bool> {
    let mut read = None;
    let mut image = start;
    for row in rows {
        if zero_split(image) {
            let within = reversals_summed(row.crossed) <= ZERO_SPLIT_REVERSALS;
            read = Some(read.unwrap_or(true) && within);
        }
        image = &row.bins;
    }
    read
}

/// Predicted reading 4's rule on one arm: the inhibitory sum within its band of `image` at every
/// block's end of schedules 9 to 16.
fn zero_inhibitory_held(rows: &[ZeroRow], image: i64) -> bool {
    let (low, high) = ZERO_INHIBITORY_HUNDREDTHS;
    rows.get(ZERO_LATE).unwrap_or(&[]).iter().all(|r| {
        r.inhibitory.0.saturating_mul(100) >= image.saturating_mul(low)
            && r.inhibitory.1.saturating_mul(100) <= image.saturating_mul(high)
    })
}

/// What H-46's tables read, each `[network][form][arm]` or per network: every run's rows, each
/// network's image's couplings, its inhibitory sum and its image by sixteenths.
struct ZeroTables<'a> {
    rows: [[[&'a [ZeroRow]; 2]; 2]; 3],
    couplings: [[[i64; 2]; 2]; 3],
    inhibitory: [i64; 3],
    bins: [Bins; 3],
}

/// ADR-0226's four predicted readings as rules (ADR-0229), in its order. Reading 3 reads every
/// arm and control, and is none where no run has a schedule that starts split.
fn zero_predicted(tables: &ZeroTables) -> [Option<bool>; 4] {
    let (mut speed, mut highest, mut inhibitory) = (true, true, true);
    let mut split: Option<bool> = None;
    for n in 0..3usize {
        for k in 0..2usize {
            let arm = tables.rows[n][ZERO_ARM][k];
            let control = tables.rows[n][ZERO_CONTROL][k];
            speed &= zero_speed_held(zero_late_reversals(arm), zero_late_reversals(control));
            highest &= zero_highest_held(arm, &tables.couplings[n]);
            inhibitory &= zero_inhibitory_held(arm, tables.inhibitory[n]);
            for rows in [arm, control] {
                if let Some(held) = zero_split_held(rows, &tables.bins[n]) {
                    split = Some(split.unwrap_or(true) && held);
                }
            }
        }
    }
    [Some(speed), Some(highest), split, Some(inhibitory)]
}

// ------------------------------------------------------------------ the run (brief 085)

/// The engine a schedule of H-46 decodes; nothing of its form is in the image. The control's is
/// `kept_from`'s, H-43's twin on time, H-42's arm bit for bit under the default. The arm's is the
/// running configuration (ADR-0232) at the control's sizing, of which a decode keeps the exponent
/// alone. Its kept addresses are unset, so the task draws the address and gives a plain reward,
/// which at age zero is the arm's first form, a kept address and a reward of age zero, bit for bit.
fn zero_from(image: &[u8], units: u32, form: usize) -> Engine {
    let sized = config(units, 2, 0);
    let (under, exponent) = match form {
        ZERO_ARM => (
            Config {
                workers: sized.workers,
                nodes_per_worker: sized.nodes_per_worker,
                injector_capacity: sized.injector_capacity,
                train_capacity: sized.train_capacity,
                ..Config::runs_a_settled_image()
            },
            ZERO_EXPONENT,
        ),
        _ => (
            Config {
                kept_addresses: KEPT_ADDRESSES,
                ..sized
            },
            DepressionExponent::One,
        ),
    };
    let exec = served(Image::decode::<2048>(image, under).expect("a well-formed record"));
    assert!(
        exec.signed_gate() && exec.inhibitory_baseline_q16() == Some(INHIBITORY_BASELINE_Q16),
        "the image carries the signed gate and the inhibitory baseline"
    );
    assert_eq!(exec.depression_exponent(), exponent, "the form's exponent");
    exec
}

/// Each stimulus set's excitatory units and its held value, its couplings to the two readout sets
/// summed in H-42's image, and the readout units onto which they are held (ADR-0226): set on
/// every schedule's engine of an arm, since no image holds them.
struct ZeroGroups {
    sources: [Vec<u32>; 2],
    values: [i64; 2],
    targets: Vec<u32>,
}

/// The groups on network `made`: each value read from H-42's image through `coupling_sum`, as a
/// host reads it (ADR-0232), and held to the couplings its derivation pinned.
fn zero_groups(made: &Made, name: &str) -> ZeroGroups {
    let units = SCAN_UNITS;
    let sets = geometry(units, made.derived.rotation);
    let exec = zero_from(&made.windowed, units, ZERO_CONTROL);
    let sources = [0usize, 1].map(|s| {
        exec.units()
            .iter()
            .filter(|u| u.flags & FLAG_INHIBITORY == 0 && sets[s].contains(u.id as u32))
            .map(|u| u.id as u32)
            .collect::<Vec<u32>>()
    });
    let targets: Vec<u32> = (0..units)
        .filter(|&id| sets[2].contains(id) || sets[3].contains(id))
        .collect();
    let values = [0usize, 1].map(|s| {
        exec.coupling_sum(&sources[s], &targets)
            .expect("excitatory units once each, and every unit in the arena")
    });
    eprintln!(
        "DUMP {name} the groups: {:?} excitatory units, their values {values:?}, {} readout units",
        sources.each_ref().map(|s| s.len()),
        targets.len()
    );
    assert_eq!(
        values,
        made.couplings.map(|c| c[0].saturating_add(c[1])),
        "{name}: each group's value, its couplings in H-42's image"
    );
    undropped(exec, name);
    ZeroGroups {
        sources,
        values,
        targets,
    }
}

/// The four couplings on `exec` by sixteenths of the width, and each one's synapses at the rail.
fn zero_bands(exec: &Engine, sets: &[Set; 4]) -> (Bins, [u32; 4]) {
    let mut bins: Bins = [[0; 16]; 4];
    let mut rail = [0u32; 4];
    for unit in exec.units() {
        if unit.flags & FLAG_INHIBITORY != 0 {
            continue;
        }
        let id = unit.id as u32;
        let Some(from) = [0usize, 1].into_iter().find(|&s| sets[s].contains(id)) else {
            continue;
        };
        for s in unit.fan_out(exec.blocks()) {
            let Some(into) = [0usize, 1]
                .into_iter()
                .find(|&r| sets[r.saturating_add(2)].contains(s.target))
            else {
                continue;
            };
            let pair = from.saturating_mul(2).saturating_add(into);
            let band = usize::try_from(s.weight_q1_15.max(0) >> 11).unwrap_or(0);
            bins[pair][band] = bins[pair][band].saturating_add(1);
            rail[pair] = rail[pair].saturating_add(u32::from(s.weight_q1_15 == i16::MAX));
        }
    }
    (bins, rail)
}

/// One schedule's run: its blocks, trace, values, and each coupling's most synapses at the rail at
/// a block's end.
struct ZeroRun {
    blocks: Vec<Block>,
    trace: u64,
    values: Vec<i32>,
    rail: [u32; 4],
}

/// One schedule of a long run from `image`, `trials` trials and `flips` (ADR-0229): the engine of
/// the form (`zero_from`), under an arm the groups set, every fraction at a half, at H-42's
/// values; H-25's arm under the answer, the drawn delivery, the engine's critic and its window,
/// and every reward at age zero. The engine is returned as the schedule left it.
fn zero_schedule(
    made: &Made,
    image: &[u8],
    arm: Reversal,
    form: usize,
    groups: &ZeroGroups,
    trials: usize,
    flips: &[usize],
) -> (Engine, ZeroRun) {
    let units = SCAN_UNITS;
    let sets = geometry(units, made.derived.rotation);
    let mut exec = zero_from(image, units, form);
    if form == ZERO_ARM {
        let held = [
            (groups.sources[0].as_slice(), groups.values[0]),
            (groups.sources[1].as_slice(), groups.values[1]),
        ];
        assert!(
            exec.set_zero_sum(&held, &groups.targets),
            "every source excitatory and in the arena, once, and every target in the arena"
        );
    }
    let task = task_over(
        sets,
        SHAPE_F46,
        Some(made.derived.cancel),
        units,
        Feedback::Answer,
        first_mapping(arm),
        DRAWN_DELIVERY,
    );
    let mut values: Vec<i32> = Vec::with_capacity(trials);
    let mut rail = [0u32; 4];
    let (blocks, trace) = run_on_scheduled_over(
        sets,
        &mut exec,
        task,
        units,
        trials,
        flips,
        &mut |exec, trial, _, outcome| {
            if let Some(value) = outcome.value_q16 {
                values.push(value);
            }
            if trial.wrapping_add(1) % BLOCK == 0 {
                let (_, now) = zero_bands(exec, &sets);
                rail = core::array::from_fn(|p| rail[p].max(now[p]));
            }
        },
    );
    let run = ZeroRun {
        blocks,
        trace,
        values,
        rail,
    };
    (exec, run)
}

/// A schedule's row (`ZeroRow`), from its run and the image `exec`, run quiet, wrote.
fn zero_row(made: &Made, exec: &Engine, run: &ZeroRun, image: &[u8]) -> ZeroRow {
    let sets = geometry(SCAN_UNITS, made.derived.rotation);
    let outside = outside_image(&made.couplings, made.sums.1);
    let blocks = &run.blocks;
    let over = |pick: fn(i64, i64) -> i64, start: i64| {
        let mut out = [[start; 2]; 2];
        for b in blocks {
            for &(s, r) in &ALL_PAIRS {
                out[s][r] = pick(out[s][r], b.10[s][r]);
            }
        }
        out
    };
    let inhibitory = blocks.iter().fold((i64::MAX, i64::MIN), |(low, high), b| {
        (low.min(b.7), high.max(b.7))
    });
    ZeroRow {
        trace: run.trace,
        values: values_hash(&run.values),
        image: crc64(image),
        clauses: kept_clauses(&made.couplings, outside, blocks),
        correct: mapping_correct(blocks),
        crossed: crossings(blocks),
        highest: over(i64::max, i64::MIN),
        lowest: over(i64::min, i64::MAX),
        inhibitory,
        rail: run.rail,
        bins: zero_bands(exec, &sets).0,
    }
}

/// `bytes` in lowercase hexadecimal, two digits a byte, as a job's log carries an image.
fn zero_hex(bytes: &[u8]) -> String {
    use std::fmt::Write as _;
    let mut out = String::with_capacity(bytes.len().saturating_mul(2));
    for b in bytes {
        let _ = write!(out, "{b:02x}");
    }
    out
}

/// The eighth image a first half wrote, in `tests/h46/` from the commit that adds it (ADR-0226).
fn zero_image_path(n: usize, form: usize, k: usize) -> String {
    format!(
        "{}/tests/h46/{}-{:?}-image-8.image",
        env!("CARGO_MANIFEST_DIR"),
        ZERO_NAMES[n][form],
        ZERO_ARMS[k]
    )
}

/// The calibration's check of H-46's stopping rule, step 2 (ADR-0226): a control's first schedule
/// is H-42's arm on its network, bit for bit, its blocks, its trace and every reward's value. It
/// fails the job, and the round stops as a finding.
fn zero_first_is_h42(name: &str, n: usize, k: usize, run: &ZeroRun) {
    pinned(
        name,
        &run.blocks,
        run.trace,
        PROBE_ARM_BLOCKS[n][k],
        PROBE_ARM_TRACES[n][k],
    );
    assert_eq!(
        values_hash(&run.values),
        PROBE_ARM_VALUE_HASH[n][k],
        "{name}: every reward's value is H-42's"
    );
    eprintln!("DUMP {name} is H-42's arm on its network, bit for bit");
}

/// A half of a long run of H-46 on network `n` (ADR-0226, ADR-0229): half 0, schedules 1 to 8 from
/// H-42's image, the derivation run again and held to H-42's pinned tables (`probe_made`); half 1,
/// schedules 9 to 16 from the eighth image half 0 wrote, held to its CRC-64. Every schedule's row
/// and blocks are dumped, then held where they are pinned, and each schedule's image decoded for
/// the next; a first half prints its last image whole, for the second.
fn zero_half(n: usize, arm: Reversal, form: usize, half: usize) {
    let k = ZERO_ARMS
        .iter()
        .position(|&a| a == arm)
        .expect("an arm of H-25's two");
    let name = format!("{} {arm:?}", ZERO_NAMES[n][form]);
    let made = probe_made(n, &name);
    let groups = zero_groups(&made, &name);
    let sets = geometry(SCAN_UNITS, made.derived.rotation);
    let start = ZERO_HALF.saturating_mul(half);
    let mut image = if half == 0 {
        let exec = zero_from(&made.windowed, SCAN_UNITS, ZERO_CONTROL);
        let bins = zero_bands(&exec, &sets).0;
        eprintln!(
            "DUMP {name} PIN image bins {bins:?}; its inhibitory sum {:?}; its couplings {:?}",
            made.sums.0, made.couplings
        );
        undropped(exec, &name);
        made.windowed.clone()
    } else {
        let path = zero_image_path(n, form, k);
        let image = std::fs::read(&path).unwrap_or_else(|e| panic!("{name}: {path}: {e}"));
        assert_eq!(
            Some(crc64(&image)),
            ZERO_IMAGES_CRC[n][form][k],
            "{name}: the carried image is the one its first half printed"
        );
        image
    };
    for s in start..start.saturating_add(ZERO_HALF) {
        let at = format!("{name} schedule {}", s.saturating_add(1));
        let (mut exec, run) = zero_schedule(
            &made,
            &image,
            arm,
            form,
            &groups,
            SCHEDULE_TRIALS,
            &SCHEDULE_FLIPS,
        );
        let quiet_ticks = quiet(&mut exec);
        let written = Image::encode(&exec).expect("quiescent");
        let row = zero_row(&made, &exec, &run, &written);
        eprintln!("DUMP {at} PIN row {row:?}");
        eprintln!(
            "DUMP {at} quiet in {quiet_ticks} ticks; blocks {:?}",
            run.blocks
        );
        if form == ZERO_CONTROL && s == 0 {
            zero_first_is_h42(&at, n, k, &run);
        }
        if let Some(pin) = ZERO_ROWS[n][form][k].get(s) {
            assert_eq!(row, *pin, "{at}: its pinned row");
        }
        undropped(exec, &at);
        image = written;
    }
    if half == 0 {
        eprintln!(
            "DUMP {name} image 8 CRC-64 {:#018x}, {} bytes, hex {}",
            crc64(&image),
            image.len(),
            zero_hex(&image)
        );
    }
}

/// The short form of an arm of H-46 (ADR-0226): its first schedule, on the weekly job, held to the
/// row its long run pinned.
fn zero_short(n: usize, arm: Reversal) {
    let k = ZERO_ARMS
        .iter()
        .position(|&a| a == arm)
        .expect("an arm of H-25's two");
    let name = format!("{} {arm:?} short", ZERO_NAMES[n][ZERO_ARM]);
    let made = probe_made(n, &name);
    let groups = zero_groups(&made, &name);
    let (mut exec, run) = zero_schedule(
        &made,
        &made.windowed,
        arm,
        ZERO_ARM,
        &groups,
        SCHEDULE_TRIALS,
        &SCHEDULE_FLIPS,
    );
    quiet(&mut exec);
    let written = Image::encode(&exec).expect("quiescent");
    let row = zero_row(&made, &exec, &run, &written);
    eprintln!("DUMP {name} PIN row {row:?}");
    match ZERO_ROWS[n][ZERO_ARM][k].first() {
        Some(pin) => assert_eq!(row, *pin, "{name}: its long run's first schedule"),
        None => {
            eprintln!("DUMP {name} not pinned: its long run's tables are written from the logs")
        }
    }
    undropped(exec, &name);
}

/// The trial of H-46's harness (ADR-0229), run by a dispatch before the protocol's commit: on seed
/// 22 from the assignment, two blocks' schedules, the second from the image the first wrote. The
/// control's first is H-42's arm as far as it runs. It reads a row, the groups' sums at their
/// values within a thousandth, and an image through its hexadecimal form. Nothing is pinned.
#[test]
#[ignore]
fn the_harness_of_h_46_over_two_short_schedules_paused() {
    let arm = Reversal::AssignmentFirst;
    let trials = 2usize.saturating_mul(BLOCK);
    let name = "zero trial";
    let made = probe_made(0, name);
    let groups = zero_groups(&made, name);
    for form in [ZERO_CONTROL, ZERO_ARM] {
        let mut image = made.windowed.clone();
        for s in 0..2usize {
            let at = format!("{name} form {form} schedule {s}");
            let (mut exec, run) = zero_schedule(&made, &image, arm, form, &groups, trials, &[]);
            assert_eq!(
                (exec.zero_sum_groups(), exec.depression_exponent()),
                match form {
                    ZERO_ARM => (2, ZERO_EXPONENT),
                    _ => (0, DepressionExponent::One),
                },
                "{at}: the form's rules"
            );
            if form == ZERO_CONTROL && s == 0 {
                assert_eq!(
                    Some(run.blocks.as_slice()),
                    PROBE_ARM_BLOCKS[0][0].get(..run.blocks.len()),
                    "{at}: H-42's arm as far as it runs"
                );
            }
            if form == ZERO_ARM {
                for b in &run.blocks {
                    for (group, value) in groups.values.iter().enumerate() {
                        let sum = b.10[group][0].saturating_add(b.10[group][1]);
                        assert!(
                            sum.saturating_sub(*value)
                                .saturating_abs()
                                .saturating_mul(1_000)
                                <= *value,
                            "{at}: group {group} at {sum}, its value {value}"
                        );
                    }
                }
            }
            quiet(&mut exec);
            let written = Image::encode(&exec).expect("quiescent");
            let row = zero_row(&made, &exec, &run, &written);
            eprintln!("DUMP {at} PIN row {row:?}");
            eprintln!(
                "DUMP {at} image {} bytes, hex head {}",
                written.len(),
                &zero_hex(&written)[..64]
            );
            undropped(exec, &at);
            image = written;
        }
    }
}

